/* =========================================================
   ADMIN LIVE QUEUE
========================================================= */

.admin-queue-page {
  min-height: 100vh;
  background: var(--background);
}

.admin-queue-container {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  margin: 0 auto;

  padding: 30px 0 65px;
}

.admin-queue-top {
  display: flex;

  align-items: flex-end;
  justify-content: space-between;

  gap: 25px;

  margin-bottom: 22px;
}

.admin-queue-top h1 {
  margin: 8px 0 7px;

  color: var(--text-main);

  font-family: var(--font-heading);

  font-size: 32px;
  line-height: 1.05;

  letter-spacing: -0.045em;
}

.admin-queue-top p {
  margin: 0;

  color: var(--text-muted);

  font-size: 12px;
  line-height: 1.6;
}

.queue-date-card {
  min-width: 180px;

  padding: 10px 12px;

  display: flex;
  align-items: center;
  gap: 8px;

  border: 1px solid var(--border);
  border-radius: 12px;

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.queue-date-card svg {
  color: var(--primary);
}

.queue-date-card span,
.queue-date-card strong {
  display: block;
}

.queue-date-card span {
  color: var(--text-faint);

  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.queue-date-card strong {
  margin-top: 2px;

  color: var(--text-strong);

  font-size: 9px;
}


/* TOOLBAR */

.queue-toolbar {
  margin-bottom: 13px;

  display: flex;
  align-items: center;

  justify-content: space-between;

  gap: 12px;
}

.queue-search {
  width: 290px;

  min-height: 43px;

  padding: 0 11px;

  display: flex;
  align-items: center;

  gap: 7px;

  border: 1px solid var(--border);
  border-radius: 11px;

  background: var(--surface);
}

.queue-search svg {
  flex: 0 0 auto;

  color: var(--text-faint);
}

.queue-search input {
  min-width: 0;
  flex: 1;

  border: 0;
  outline: 0;

  color: var(--text-strong);
  background: transparent;

  font-size: 9px;
  font-weight: 600;
}

.queue-filters {
  display: flex;

  flex-wrap: wrap;

  gap: 6px;
}

.queue-filters button {
  min-height: 35px;

  padding: 0 9px;

  border: 1px solid var(--border);
  border-radius: 9px;

  color: var(--text-muted);
  background: var(--surface);

  font-size: 8px;
  font-weight: 800;
}

.queue-filters button:hover {
  color: var(--text-strong);
  background: var(--surface-hover);
}

.queue-filters button.active {
  color: var(--text-on-primary);
  border-color: var(--primary);
  background: var(--primary);
}


/* LAYOUT */

.queue-layout {
  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    350px;

  gap: 14px;

  align-items: start;
}

.queue-list-card,
.queue-detail-card {
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.queue-list-card {
  overflow: hidden;
}

.queue-list-heading {
  min-height: 67px;

  padding: 0 18px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  border-bottom: 1px solid var(--border);
}

.queue-list-heading span {
  color: var(--text-faint);

  font-size: 7px;
  font-weight: 800;

  letter-spacing: 0.11em;
}

.queue-list-heading h2 {
  margin: 4px 0 0;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 15px;
}

.queue-live-dot {
  display: flex;
  align-items: center;
  gap: 5px;

  color: var(--success);

  font-size: 8px;
  font-weight: 800;
}

.queue-live-dot span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: var(--success);
}


/* QUEUE ROW */

.queue-row {
  width: 100%;

  min-height: 76px;

  padding: 10px 15px;

  display: grid;

  grid-template-columns:
    55px
    minmax(0, 1fr)
    125px
    100px
    15px;

  align-items: center;

  gap: 10px;

  border-bottom: 1px solid var(--border);

  color: var(--text-body);

  background: transparent;

  text-align: left;
}

.queue-row:last-child {
  border-bottom: 0;
}

.queue-row:hover {
  background: var(--surface-hover);
}

.queue-row.selected {
  background: var(--primary-soft);

  box-shadow:
    inset 3px 0 0 var(--primary);
}

.queue-token {
  color: var(--primary);

  font-family: var(--font-heading);

  font-size: 10px;
  font-weight: 800;
}

.queue-farmer {
  min-width: 0;
}

.queue-farmer strong,
.queue-farmer span {
  display: block;

  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;
}

.queue-farmer strong {
  color: var(--text-strong);

  font-size: 10px;
  font-weight: 800;
}

.queue-farmer span {
  margin-top: 3px;

  color: var(--text-muted);

  font-size: 8px;
}

