  bottom: 18px;

  color: #327dac;

  background: rgba(255, 255, 255, 0.34);
}


/* =========================================================
   FOOTER
========================================================= */

.landing-footer {
  color: rgba(255, 255, 255, 0.82);

  background: #19394b;
}

.landing-footer-main {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);

  gap: 30px;

  padding: 70px 7vw;
}

.landing-footer-logo {
  display: inline-flex;

  text-decoration: none;
}

.landing-footer-brand p {
  max-width: 320px;

  margin: 20px 0 0;

  color: rgba(255, 255, 255, 0.67);

  font-size: 13px;
  line-height: 1.7;
}

.landing-footer-column {
  display: flex;
  flex-direction: column;
  gap: 13px;
}

.landing-footer-column strong {
  margin-bottom: 6px;

  color: #f4cd69;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.landing-footer-column a {
  color: rgba(255, 255, 255, 0.70);

  font-size: 12px;
  font-weight: 600;

  text-decoration: none;
}

.landing-footer-column a:hover {
  color: #ffffff;
}

.landing-footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  padding: 20px 7vw;

  border-top: 1px solid rgba(255, 255, 255, 0.09);

  color: rgba(255, 255, 255, 0.52);

  font-size: 10px;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1100px) {

  .landing-nav {
    gap: 20px;
  }

  .landing-hero {
    grid-template-columns: 1fr;

    padding-top: 70px;
  }

  .landing-hero-content {
    max-width: 800px;
  }

  .landing-hero-visual {
    min-height: 500px;
  }

  .landing-purpose-grid {
    grid-template-columns: 1fr;
  }

  .purpose-card {
    min-height: 250px;
  }

  .landing-process-track {
    flex-wrap: wrap;
    gap: 16px;
  }

  .landing-process-step {
    flex: 1 1 calc(33.333% - 16px);
  }

  .landing-process-connector {
    display: none;
  }

  .landing-feature-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .landing-final-cta-decoration {
    opacity: 0.45;
    right: -90px;
  }

}


@media (max-width: 800px) {

  .landing-header {
    min-height: 72px;
    padding: 11px 20px;
  }

  .landing-nav,
  .landing-header-actions {
    display: none;
  }

  .landing-mobile-menu-button {
    display: inline-flex;
  }

  .landing-mobile-menu {
    position: fixed;
    z-index: 49;

    top: 72px;
    left: 0;
    right: 0;

    display: flex;
    flex-direction: column;
    gap: 5px;

    padding: 15px 20px 20px;

    border-bottom: 1px solid #dce6eb;

    background: #ffffff;

    box-shadow:
      0 18px 30px rgba(29, 60, 76, 0.10);
  }

  .landing-mobile-menu a {
    padding: 13px 10px;

    color: #31566c;

    font-size: 13px;
    font-weight: 800;

    text-decoration: none;
  }

  .landing-mobile-menu a:last-child {
    margin-top: 4px;

    border-radius: 10px;

    color: #ffffff;
    background: #166534;
    text-align: center;
  }

  .landing-hero {
    min-height: auto;

    padding: 55px 20px 65px;
  }

  .landing-hero h1 {
    font-size: 52px;
  }

  .landing-hero-description {
    font-size: 16px;
  }

  .landing-hero-visual {
    min-height: 450px;
  }

  .landing-farm-illustration {
    height: 390px;
  }

  .landing-orbit {
    display: none;
  }

  .landing-purpose-section,
  .landing-process-section,
  .landing-portals-section,
  .landing-features-section {
    padding: 80px 20px;
  }

  .landing-portal-grid {
    grid-template-columns: 1fr;
  }

  .landing-feature-grid {
    grid-template-columns: 1fr;
  }

  .landing-process-step {
    flex: 1 1 100%;
  }

  .landing-purpose-final-section {
    padding: 50px 20px 80px;
  }

  .landing-purpose-final-card {
    align-items: flex-start;
    flex-direction: column;

    padding: 30px;
  }

  .landing-final-cta {
    min-height: auto;

    padding: 70px 20px;
  }

  .landing-final-cta-decoration {
    display: none;
  }

  .landing-footer-main {
    grid-template-columns: 1fr 1fr;

    gap: 40px;

    padding: 55px 20px;
  }

  .landing-footer-brand {
    grid-column: 1 / -1;
  }

  .landing-footer-bottom {
    flex-direction: column;
    align-items: flex-start;

    padding: 18px 20px;
  }

}


@media (max-width: 520px) {

  .landing-hero h1 {
    font-size: 43px;
  }

  .landing-hero-badge {
    font-size: 9px;
  }

  .landing-hero-points {
    flex-direction: column;
    gap: 10px;
  }

  .landing-hero-actions {
    flex-direction: column;
  }

  .landing-primary-button,
  .landing-secondary-button {
    width: 100%;
  }

  .landing-hero-visual {
    min-height: 380px;
  }

  .landing-farm-illustration {
    width: 100%;
    height: 330px;

    border-radius: 25px;
  }

  .landing-floating-card {
    min-width: 145px;
    padding: 9px;
  }

  .landing-floating-card span {
    font-size: 7px;
  }

  .landing-floating-card strong {
    font-size: 11px;
  }

  .card-token {
    left: 10px;
    top: 43px;
  }

  .card-weighing {
    right: 10px;
    bottom: 76px;
  }

  .card-payment {
    left: 18px;
    bottom: 15px;
  }

  .landing-farm-tile {
    width: 115px;
    height: 115px;
  }

  .landing-farm-tile svg {
    width: 50px;
    height: 50px;
  }

  .landing-portal-card {
    min-height: 520px;

    padding: 25px;
  }

  .portal-card-content h3 {
    font-size: 29px;
  }

  .portal-card-content p {
    font-size: 14px;
  }

  .landing-purpose-final-card h2 {
    font-size: 31px;
  }

  .landing-final-cta h2 {
    font-size: 39px;
  }

  .landing-footer-main {
    grid-template-columns: 1fr;
  }

  .landing-footer-brand {
    grid-column: auto;
  }

}
/* =========================================================
   FARMER HOME - LIVE DASHBOARD
========================================================= */

.farmer-home-page {
  min-height: 100vh;
  background:
    linear-gradient(
      180deg,
      #f7fbf8 0%,
      #ffffff 100%
    );
  color: #1d3b4d;
}

.farmer-home-container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 42px 28px 80px;
}


/* =========================================================
   WELCOME
========================================================= */

.farmer-welcome {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  margin-bottom: 32px;
}

.farmer-welcome .page-eyebrow {
  display: inline-block;
  margin-bottom: 8px;
}

.farmer-welcome h1 {
  margin: 0;
  color: #193b50;
  font-family: var(--font-heading);
  font-size: clamp(34px, 4vw, 52px);
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.farmer-welcome > div:first-child p {
  max-width: 650px;
  margin: 12px 0 0;
  color: #728693;
  font-size: 16px;
  line-height: 1.65;
}

.farmer-profile {
  display: flex;
  align-items: center;
  gap: 12px;
}

.farmer-avatar {
  width: 50px;
  height: 50px;
  flex: 0 0 50px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 16px;

  color: #ffffff;
  background:
    linear-gradient(
      135deg,
      #166534,
      #2d9a62
    );

  font-size: 15px;
  font-weight: 900;
}

.farmer-profile > div:nth-child(2) {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.farmer-profile strong {
  color: #29485b;
  font-size: 13px;
}

.farmer-profile span {
  color: #8495a0;
  font-size: 10px;
}

.farmer-refresh-button {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-left: 6px;

  border: 1px solid #dbe6eb;
  border-radius: 11px;

  color: #527183;
  background: #ffffff;

  cursor: pointer;
}

.farmer-refresh-button:hover {
  color: #166534;
  border-color: #bad9c5;
  background: #f3faf5;
}

.farmer-refresh-button:disabled {
  opacity: 0.6;
  cursor: default;
}


/* =========================================================
   EMPTY / ERROR
========================================================= */

.empty-state-card {
  padding: 55px 35px;

  text-align: center;

  border: 1px solid #dde8ec;
  border-radius: 25px;

  background: #ffffff;

  box-shadow:
    0 16px 45px rgba(31, 62, 76, 0.06);
}

.empty-state-icon {
  width: 65px;
  height: 65px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin: 0 auto 20px;

  border-radius: 18px;

  color: #166534;
  background: #eaf7ee;
}

.empty-state-card .page-eyebrow {
  display: block;
  margin-bottom: 10px;
}

.empty-state-card h1 {
  margin: 0;

  color: #24445a;

  font-family: var(--font-heading);
  font-size: 30px;
}

.empty-state-card p {
  max-width: 560px;
  margin: 13px auto 25px;

  color: #728692;

  font-size: 14px;
  line-height: 1.7;
}

.loading-spin {
  animation:
    farmer-spin 1s linear infinite;
}

@keyframes farmer-spin {
  to {
    transform: rotate(360deg);
  }
}


/* =========================================================
   CURRENT BOOKING
========================================================= */

.next-booking-card {
  padding: 32px;

  border-radius: 26px;

  background:
    linear-gradient(
      135deg,
      #ffffff 0%,
      #f5fbf7 100%
    );

  border: 1px solid #dce9df;

  box-shadow:
    0 20px 55px rgba(30, 74, 51, 0.08);
}

.booking-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.card-eyebrow {
  display: block;

  color: #718a96;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.booking-token-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 9px;
}

.home-token {
  color: #1e5d43;

  font-family: var(--font-heading);
  font-size: 34px;
  font-weight: 900;
  letter-spacing: -0.02em;
}

.booking-confirmed-icon {
  width: 52px;
  height: 52px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 16px;

  color: #166534;
  background: #e3f4e8;
}


/* =========================================================
   STATUS MESSAGE
========================================================= */

.booking-status-message {
  display: flex;
  align-items: center;
  gap: 13px;

  margin-top: 26px;
  padding: 15px 16px;

  border-radius: 15px;

  background: #eef8f1;
}

.status-message-icon {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  color: #166534;
  background: #d9efdf;
}

.booking-status-message > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.booking-status-message strong {
  color: #255c43;
  font-size: 12px;
}

.booking-status-message span {
  color: #6d837c;
  font-size: 11px;
  line-height: 1.5;
}


/* =========================================================
   DETAILS
========================================================= */

.booking-main-details {
  display: grid;
  grid-template-columns: repeat(2, 1fr);

  gap: 16px;

  margin-top: 22px;
}

.home-detail {
  display: flex;
  align-items: flex-start;
  gap: 13px;

  padding: 18px;

  border: 1px solid #e0e9ed;
  border-radius: 16px;

  background: #ffffff;
}

.home-detail-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  color: #277caf;
  background: #ffedd5;
}

.home-detail > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.home-detail span {
  color: #7c909b;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.home-detail strong {
  color: #28485b;
  font-size: 14px;
}

.home-detail small {
  color: #718590;
  font-size: 10px;
  line-height: 1.5;
}

.booking-action-row {
  display: flex;
  align-items: center;
  gap: 12px;

  margin-top: 24px;
}

.home-primary-action,
.home-secondary-action {
  min-height: 48px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  padding: 0 18px;

  border-radius: 11px;

  font-size: 11px;
  font-weight: 900;

  text-decoration: none;
}

.home-primary-action {
  color: #ffffff;
  background: #166534;
}

.home-primary-action:hover {
  background: #197342;
}

.home-secondary-action {
  color: #315b70;
  border: 1px solid #d9e4ea;
  background: #ffffff;
}

.home-secondary-action:hover {
  color: #f97316;
  border-color: #b9d1dd;
}


/* =========================================================
   QUICK ACTION CARDS
========================================================= */

.farmer-home-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);

  gap: 18px;

  margin-top: 22px;
}

.home-feature-card {
  min-height: 205px;

  display: flex;
  flex-direction: column;

  padding: 24px;

  border-radius: 21px;

  text-decoration: none;

  border: 1px solid transparent;

  transition:
    transform 160ms ease,
    box-shadow 160ms ease;
}

.home-feature-card:hover {
  transform: translateY(-4px);

  box-shadow:
    0 17px 42px rgba(31, 61, 75, 0.09);
}

.booking-feature {
  border-color: #d7ebdc;
  background: #eff9f1;
}

.status-feature {
  border-color: #d9e9f1;
  background: #eff7fb;
}

.help-feature {
  border-color: #f1e2c5;
  background: #fff9ed;
}

.feature-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.feature-icon {
  width: 46px;
  height: 46px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 13px;
}

.booking-feature .feature-icon {
  color: #166534;
  background: #dcefe1;
}

.status-feature .feature-icon {
  color: #277caf;
  background: #dceef7;
}

.help-feature .feature-icon {
  color: #ca8b24;
  background: #f9eac5;
}

.home-feature-card h2 {
  margin: 25px 0 9px;

  color: #28475a;

  font-family: var(--font-heading);
  font-size: 20px;
}

.home-feature-card p {
  margin: 0;

  color: #748792;

  font-size: 11px;
  line-height: 1.7;
}


/* =========================================================
   PROCUREMENT JOURNEY
========================================================= */

.farmer-progress-card {
  margin-top: 24px;
  padding: 29px;

  border: 1px solid #fed7aa;
  border-radius: 22px;

  background: #ffffff;

  box-shadow:
    0 12px 35px rgba(31, 61, 75, 0.05);
}

.farmer-progress-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 20px;
}

.farmer-progress-heading h2 {
  margin: 6px 0 0;

  color: #26465a;

  font-family: var(--font-heading);
  font-size: 23px;
}

.farmer-current-stage {
  padding: 8px 11px;

  border-radius: 999px;

  color: #166534;
  background: #e9f6ed;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.06em;
}

.farmer-progress-track {
  display: flex;
  align-items: flex-start;

  margin-top: 30px;
}

.farmer-progress-stage {
  width: 105px;

  display: flex;
  flex-direction: column;
  align-items: center;

  text-align: center;

  color: #9aa9b1;
}

.farmer-progress-stage.active {
  color: #2f5d72;
}

.farmer-progress-stage.complete {
  color: #166534;
}

.farmer-progress-icon {
  width: 45px;
  height: 45px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  border: 2px solid #dfe7eb;

  background: #ffffff;
}

.farmer-progress-stage.active
.farmer-progress-icon {
  border-color: #94c8a4;
  background: #edf8ef;
  color: #166534;
}

.farmer-progress-stage.complete
.farmer-progress-icon {
  border-color: #166534;
  background: #166534;
  color: #ffffff;
}

.farmer-progress-stage span {
  margin-top: 9px;

  font-size: 10px;
  font-weight: 800;
}

.farmer-progress-line {
  flex: 1;

  height: 2px;

  margin-top: 22px;

  background: #e4eaed;
}

.farmer-progress-line.active {
  background: #77b88a;
}


/* =========================================================
   NOTIFICATIONS
========================================================= */

.home-sms-card {
  display: flex;
  align-items: flex-start;
  gap: 15px;

  margin-top: 22px;
  padding: 22px;

  border: 1px solid #dbe8ef;
  border-radius: 19px;

  background:
    linear-gradient(
      135deg,
      #f4f9fc,
      #eef7fb
    );
}

.home-sms-icon {
  width: 45px;
  height: 45px;
  flex: 0 0 45px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 13px;

  color: #277caf;
  background: #dceef7;
}

.home-sms-card > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.home-sms-card span {
  color: #277caf;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.home-sms-card h3 {
  margin: 1px 0 0;

  color: #2b4b5f;

  font-family: var(--font-heading);
  font-size: 17px;
}

.home-sms-card p {
  margin: 0;

  color: #718793;

  font-size: 11px;
  line-height: 1.6;
}


/* =========================================================
   BOOKING HISTORY
========================================================= */

.home-history-section {
  margin-top: 25px;
}

.home-history-list {
  display: flex;
  flex-direction: column;

  margin-top: 10px;

  border: 1px solid #dce6eb;
  border-radius: 17px;

  overflow: hidden;

  background: #ffffff;
}

.home-history-item {
  display: grid;
  grid-template-columns: 1fr auto 20px;
  align-items: center;
  gap: 18px;

  padding: 15px 18px;

  color: inherit;
  text-decoration: none;

  border-bottom: 1px solid #edf1f3;
}

.home-history-item:last-child {
  border-bottom: 0;
}

.home-history-item:hover {
  background: #f8fbfc;
}

.home-history-item > div:first-child {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.home-history-item > div:first-child strong {
  color: #28485b;
  font-size: 12px;
}

.home-history-item > div:first-child span {
  color: #81929c;
  font-size: 10px;
}

.home-history-item > div:nth-child(2) {
  display: flex;
  align-items: center;
  gap: 13px;
}

.home-history-item > div:nth-child(2) > span {
  color: #708591;
  font-size: 10px;
}

.home-history-item > svg {
  color: #91a1aa;
}


/* =========================================================
   SUPPORT ROW
========================================================= */

.home-support-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  margin-top: 25px;

  color: #8a9aa4;

  font-size: 10px;
}

.home-support-row a {
  display: inline-flex;
  align-items: center;
  gap: 5px;

  color: #35708e;

  font-size: 10px;
  font-weight: 800;

  text-decoration: none;
}

.home-support-row a:hover {
  color: #f97316;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 900px) {

  .farmer-welcome {
    align-items: flex-start;
    flex-direction: column;
  }

  .booking-main-details {
    grid-template-columns: 1fr;
  }

  .farmer-home-grid {
    grid-template-columns: 1fr;
  }

  .farmer-progress-track {
    overflow-x: auto;
    padding-bottom: 8px;
  }

}


@media (max-width: 600px) {

  .farmer-home-container {
    padding: 25px 16px 55px;
  }

  .farmer-welcome h1 {
    font-size: 37px;
  }

  .farmer-profile {
    width: 100%;
  }

  .next-booking-card {
    padding: 22px;
  }

  .booking-card-top {
    gap: 12px;
  }

  .home-token {
    font-size: 28px;
  }

  .booking-action-row {
    flex-direction: column;
    align-items: stretch;
  }

  .home-primary-action,
