  width: 100%;

  min-height: 55px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 12px;

  padding: 9px 13px;

  border: 1px solid #d6e2e8;

  border-radius: 12px;

  color: #718794;

  background: #f9fbfc;

  cursor: pointer;

  text-align: left;

  transition:
