  background: #197342;
}

.help-contact-right {
  display: flex;

  flex-direction: column;

  gap: 12px;
}

.help-contact-use-card {
  padding: 22px;

  border: 1px solid #fed7aa;

  border-radius: 18px;

  background: #ffffff;
}

.help-contact-use-icon {
  width: 40px;
  height: 40px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  color: #c6871c;

  background: #fff0ca;
}

.help-contact-use-card > div:nth-child(2) {
  display: flex;

  flex-direction: column;

  gap: 4px;

  margin-top: 11px;
}

.help-contact-use-card > div:nth-child(2) span {
  color: #8b9aa2;

  font-size: 7px;
  font-weight: 900;

  letter-spacing: .1em;
}

.help-contact-use-card h3 {
  margin: 0;

  color: #315064;

  font-family: var(--font-heading);

  font-size: 18px;
}

.help-contact-reasons {
  display: grid;

  grid-template-columns:
    repeat(2, 1fr);

  gap: 9px;

  margin-top: 17px;
}

.help-contact-reasons > div {
  display: flex;

  align-items: flex-start;

  gap: 6px;

  padding: 8px;

  border-radius: 8px;

  background: #f7fafb;
}

.help-contact-reasons svg {
  flex: 0 0 auto;

  color: #166534;
}

.help-contact-reasons span {
  color: #728792;

  font-size: 7px;

  line-height: 1.5;
}

.help-emergency-note {
  display: flex;

  align-items: flex-start;

  gap: 8px;

  padding: 12px;

  border: 1px solid #e3e9ed;

  border-radius: 11px;

  color: #778b95;

  background: #f7f9fa;
}

.help-emergency-note svg {
  flex: 0 0 auto;

  color: #166534;
}

.help-emergency-note p {
  margin: 0;

  font-size: 7px;

  line-height: 1.6;
}


/* =========================================================
   LANGUAGE
========================================================= */

.help-language-section {
  display: flex;

  align-items: center;

  gap: 15px;

  margin-top: 45px;

  padding: 20px 22px;

  border: 1px solid #fed7aa;

  border-radius: 18px;

  background: #ffffff;
}

.help-language-icon {
  width: 45px;
  height: 45px;

  flex: 0 0 45px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  color: #288e91;

  background: #e3f4f3;
}

.help-language-copy {
  min-width: 0;

  flex: 1;
}

.help-language-copy .page-eyebrow {
  display: inline-block;

  margin-bottom: 4px;
}

.help-language-copy h2 {
  margin: 0 0 5px;

  color: #315164;

  font-family: var(--font-heading);

  font-size: 20px;
}

.help-language-copy p {
  margin: 0;

  color: #81929b;

  font-size: 8px;

  line-height: 1.55;
}

.help-language-list {
  display: flex;

  gap: 7px;
}

.help-language-option {
  min-width: 77px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  padding: 9px;

  border: 1px solid #dbe5e9;

  border-radius: 10px;

  color: #738892;

  background: #f9fbfc;
}

.help-language-option.active {
  border-color: #9fc9aa;

  color: #166534;

  background: #edf8f0;
}

.help-language-option strong {
  font-size: 10px;
}

.help-language-option span {
  margin-top: 2px;

  font-size: 6px;
}


/* =========================================================
   FINAL CTA
========================================================= */

.help-final-card {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 25px;

  margin-top: 25px;

  padding: 25px;

  border-radius: 20px;

  color: #ffffff;

  background:
    linear-gradient(
      135deg,
      #1e6243,
      #297952
    );

  box-shadow:
    0 17px 40px
    rgba(
      27,
      92,
      62,
      .15
    );
}

.help-final-card .page-eyebrow {
  display: inline-block;

  color: rgba(
    255,
    255,
    255,
    .67
  );
}

.help-final-card h2 {
  margin: 7px 0 6px;

  color: #ffffff;

  font-family: var(--font-heading);

  font-size: 25px;
}

.help-final-card p {
  max-width: 650px;

  margin: 0;

  color: rgba(
    255,
    255,
    255,
    .75
  );

  font-size: 9px;

  line-height: 1.6;
}

.help-final-actions {
  display: flex;

  align-items: center;

  gap: 8px;

  flex-wrap: wrap;

  justify-content: flex-end;
}

.help-final-card .help-primary-action {
  color: #1e6243;

  background: #ffffff;

  box-shadow: none;
}

.help-final-card .help-primary-action:hover {
  background: #eef8f1;
}

.help-final-card .help-secondary-action {
  color: #ffffff;

  border-color:
    rgba(
      255,
      255,
      255,
      .28
    );

  background:
    rgba(
      255,
      255,
      255,
      .08
    );
}


/* =========================================================
   FOOTER
========================================================= */

.help-page-footer {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 20px;

  padding:
    22px
    7vw;

  border-top: 1px solid #e4eaed;

  color: #81929a;

  background: #ffffff;

  font-size: 8px;
}

.help-page-footer > div {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.help-page-footer strong {
  color: #31566b;

  font-family: var(--font-heading);

  font-size: 12px;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1050px) {

  .help-hero {
    grid-template-columns: 1fr;
  }

  .help-hero-card {
    max-width: none;
  }

  .help-topic-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .help-checklist-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .help-connectivity-section {
    grid-template-columns: 1fr;
  }

  .help-sms-section {
    grid-template-columns: 1fr;
  }

  .help-phone-mockup {
    margin: 0;
  }

  .help-faq-layout {
    grid-template-columns: 1fr;
  }

  .help-faq-side {
    display: grid;

    grid-template-columns:
      repeat(2, 1fr);
  }

}


@media (max-width: 800px) {

  .help-guides-grid {
    grid-template-columns: 1fr;
  }

  .help-contact-grid {
    grid-template-columns: 1fr;
  }

  .help-language-section {
    align-items: flex-start;

    flex-wrap: wrap;
  }

  .help-language-copy {
    flex-basis: calc(
      100% - 60px
    );
  }

  .help-language-list {
    width: 100%;
  }

  .help-language-option {
    flex: 1;
  }

  .help-final-card {
    align-items: flex-start;

    flex-direction: column;
  }

  .help-final-actions {
    justify-content: flex-start;
  }

}


@media (max-width: 600px) {

  .help-container {
    padding:
      25px
      16px
      60px;
  }

  .help-hero-copy h1 {
    font-size: 44px;
  }

  .help-hero-copy > p {
    font-size: 13px;
  }

  .help-topic-grid {
    grid-template-columns: 1fr;
  }

  .help-checklist-grid {
    grid-template-columns: 1fr;
  }

  .help-connectivity-points {
    grid-template-columns: 1fr;
  }

  .help-faq-side {
    grid-template-columns: 1fr;
  }

  .help-contact-reasons {
    grid-template-columns: 1fr;
  }

  .help-sms-section {
    padding: 22px;
  }

  .help-final-actions {
    width: 100%;
    flex-direction: column;
    align-items: stretch;
  }

  .help-final-actions a {
    width: 100%;
  }

  .help-page-footer {
    align-items: flex-start;

    flex-direction: column;

    padding:
      20px
      16px;
  }

}
/* =========================================================
   ADMIN LOGIN PAGE
========================================================= */

.admin-login-page {
  min-height: 100vh;

  color: #18394d;

  background:
    radial-gradient(
      circle at 0% 0%,
      rgba(39, 126, 174, 0.08),
      transparent 25%
    ),
    radial-gradient(
      circle at 98% 12%,
      rgba(199, 137, 30, 0.09),
      transparent 24%
    ),
    linear-gradient(
      180deg,
      #fbfcfa 0%,
      #f4f8fa 55%,
      #ffffff 100%
    );
}

.admin-login-header {
  min-height: 76px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding:
    0
    max(24px, 6vw);

  border-bottom: 1px solid #e1e8eb;

  background:
    rgba(
      255,
      255,
      255,
      0.92
    );

  backdrop-filter: blur(12px);
}

.admin-login-brand {
  display: flex;
  align-items: center;

  gap: 10px;

  color: inherit;

  text-decoration: none;
}

.admin-brand-mark {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  color: #ffffff;

  background:
    linear-gradient(
      145deg,
      #276f9b,
      #3591bc
    );

  font-size: 12px;
  font-weight: 950;

  box-shadow:
    0 7px 18px
    rgba(
      39,
      111,
      155,
      0.16
    );
}

.admin-login-brand > div:last-child {
  display: flex;
  flex-direction: column;

  gap: 2px;
}

.admin-login-brand strong {
  color: #294a5d;

  font-family: var(--font-heading);

  font-size: 17px;

  line-height: 1;
}

.admin-login-brand span {
  color: #80939e;

  font-size: 8px;

  font-weight: 800;

  letter-spacing: .04em;
}

.admin-login-back {
  display: inline-flex;
  align-items: center;

  gap: 6px;

  color: #587180;

  font-size: 10px;
  font-weight: 900;

  text-decoration: none;
}

.admin-login-back:hover {
  color: #c2410c;
}


/* =========================================================
   MAIN CONTAINER
========================================================= */

.admin-login-container {
  width: 100%;
  max-width: 1240px;

  margin: 0 auto;

  padding:
    50px
    28px
    70px;
}

.admin-login-layout {
  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    430px;

  gap: 65px;

  align-items: center;
}


/* =========================================================
   INTRO
========================================================= */

.admin-login-intro {
  max-width: 690px;
}

.admin-login-eyebrow-row {
  display: flex;

  align-items: center;

  gap: 9px;

  flex-wrap: wrap;
}

.admin-secure-pill {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  padding:
    5px
    9px;

  border: 1px solid #d4e4ec;

  border-radius: 999px;

  color: #287aa4;

  background: #edf6fa;

  font-size: 8px;

  font-weight: 900;

  letter-spacing: .07em;
}

.admin-secure-pill > span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #2f8cb5;

  box-shadow:
    0 0 0 4px
    rgba(
      47,
      140,
      181,
      .08
    );
}

.admin-login-intro h1 {
  margin:
    13px
    0
    15px;

  color: #18394d;

  font-family: var(--font-heading);

  font-size: clamp(
    46px,
    5vw,
    68px
  );

  line-height: .97;

  letter-spacing: -.045em;
}

.admin-login-intro h1 span {
  display: block;

  color: #c2410c;
}

.admin-login-intro > p {
  max-width: 660px;

  margin: 0;

  color: #718792;

  font-size: 15px;

  line-height: 1.75;
}


/* =========================================================
   FEATURE GRID
========================================================= */

.admin-login-feature-grid {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 10px;

  margin-top: 28px;
}

.admin-login-feature {
  display: flex;

  align-items: flex-start;

  gap: 10px;

  padding: 14px;

  border: 1px solid #fed7aa;

  border-radius: 14px;

  background: rgba(
    255,
    255,
    255,
    .84
  );

  transition:
    transform .16s ease,
    border-color .16s ease,
    box-shadow .16s ease;
}

.admin-login-feature:hover {
  transform: translateY(-2px);

  border-color: #bfd4df;

  box-shadow:
    0 11px 25px
    rgba(
      30,
      63,
      77,
      .06
    );
}

.admin-login-feature-icon {
  width: 40px;
  height: 40px;

  flex: 0 0 40px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  color: #c2410c;

  background: #ffedd5;
}

.admin-login-feature:nth-child(2)
.admin-login-feature-icon {
  color: #166534;
  background: #e5f4e9;
}

.admin-login-feature:nth-child(3)
.admin-login-feature-icon {
  color: #c4871c;
  background: #fff0cc;
}

.admin-login-feature:nth-child(4)
.admin-login-feature-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-login-feature > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 4px;
}

.admin-login-feature strong {
  color: #315165;

  font-size: 10px;
}

.admin-login-feature span {
  color: #7c909a;

  font-size: 8px;

  line-height: 1.55;
}


/* =========================================================
   WORKFLOW
========================================================= */

.admin-login-workflow {
  margin-top: 25px;

  padding:
    16px
    17px;

  border: 1px solid #fed7aa;

  border-radius: 16px;

  background:
    linear-gradient(
      135deg,
      #f7fafb,
      #ffffff
    );
}

.admin-login-workflow-heading {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-login-workflow-heading span {
  color: #8b9aa1;

  font-size: 7px;

  font-weight: 900;

  letter-spacing: .12em;
}

.admin-login-workflow-heading strong {
  color: #315165;

  font-size: 11px;
}

.admin-workflow-steps {
  display: flex;

  align-items: center;

  margin-top: 14px;
}

.admin-workflow-step {
  display: flex;

  flex-direction: column;

  align-items: center;

  gap: 5px;

  min-width: 50px;
}

.admin-workflow-step span {
  width: 29px;
  height: 29px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  color: #c2410c;

  background: #ffedd5;

  font-size: 7px;

  font-weight: 900;
}

.admin-workflow-step strong {
  color: #647d8a;

  font-size: 7px;

  font-weight: 900;
}

.admin-workflow-line {
  flex: 1;

  height: 1px;

  margin:
    0
    5px;

  background: #d6e2e7;
}


/* =========================================================
   LOGIN CARD
========================================================= */

.admin-login-card {
  padding: 29px;

  border: 1px solid #d9e5e9;

  border-radius: 24px;

  background:
    rgba(
      255,
      255,
      255,
      .97
    );

  box-shadow:
    0 24px 60px
    rgba(
      31,
      63,
      77,
      .11
    );
}

.admin-login-card-heading {
  display: flex;

  align-items: flex-start;

  gap: 12px;

  padding-bottom: 20px;

  border-bottom: 1px solid #e9eef1;
}

.admin-login-lock {
  width: 48px;
  height: 48px;

  flex: 0 0 48px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 14px;

  color: #c2410c;

  background: #ffedd5;
}

.admin-login-card-heading > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 4px;
}

.admin-login-card-heading .page-eyebrow {
  display: inline-block;
}

.admin-login-card-heading h2 {
  margin: 0;

  color: #2b4a5e;

  font-family: var(--font-heading);

  font-size: 24px;

  line-height: 1.1;
}

.admin-login-card-heading p {
  margin: 2px 0 0;

  color: #81929c;

  font-size: 9px;

  line-height: 1.5;
}


/* =========================================================
   FIELDS
========================================================= */

.admin-login-card form {
  margin-top: 22px;
}

.admin-login-field {
  margin-bottom: 17px;
}

.admin-login-field label {
  display: block;

  margin-bottom: 8px;

  color: #365366;

  font-size: 9px;

  font-weight: 900;
}

.admin-login-input {
  height: 51px;

  display: flex;
  align-items: center;

  gap: 9px;

  padding:
    0
    13px;

  border: 1px solid #d6e2e7;

  border-radius: 11px;

  color: #78909b;

  background: #f9fbfc;

  transition:
    border-color .15s ease,
    background .15s ease,
    box-shadow .15s ease;
}

.admin-login-input:focus-within {
  border-color: #c2410c;

  background: #ffffff;

  box-shadow:
    0 0 0 4px
    rgba(
      39,
      124,
      172,
      .08
    );
}

.admin-login-input > svg {
  flex: 0 0 auto;
}

.admin-login-input input {
  min-width: 0;

  width: 100%;
  height: 100%;

  padding: 0;

  border: 0;
  outline: 0;

  color: #29485b;

  background: transparent;

  font-size: 11px;
  font-weight: 700;
}

.admin-login-input input::placeholder {
  color: #b0bdc4;
}

.admin-show-password {
  flex: 0 0 auto;

  padding: 5px 2px;

  border: 0;

  color: #4c7489;

  background: transparent;

  cursor: pointer;

  font-size: 8px;

  font-weight: 900;
}

.admin-show-password:hover {
  color: #c2410c;
}

.admin-login-field small {
  display: block;

  margin-top: 6px;

  color: #8b9aa2;

  font-size: 7px;

  line-height: 1.5;
}


/* =========================================================
   ERROR
========================================================= */

.admin-login-error {
  display: flex;

  align-items: flex-start;

  gap: 8px;

  margin:
    2px
    0
    14px;

  padding:
    11px
    12px;

  border: 1px solid #efd1cc;

  border-radius: 10px;

  color: #b05247;

  background: #fff4f1;

  font-size: 8px;

  line-height: 1.5;
}

.admin-login-error svg {
  flex: 0 0 auto;
}


/* =========================================================
   REMEMBER
========================================================= */

.admin-remember-row {
  display: flex;

  align-items: center;

  gap: 7px;

  margin:
    2px
    0
    15px;

  color: #71858f;

  font-size: 8px;

  cursor: pointer;
}

.admin-remember-row input {
  width: 14px;
  height: 14px;

  accent-color: #c2410c;

  cursor: pointer;
}


/* =========================================================
   SUBMIT
========================================================= */

.admin-login-submit {
  width: 100%;

  min-height: 51px;

  display: flex;
  align-items: center;
  justify-content: center;

  gap: 8px;

  border: 0;

  border-radius: 11px;

  color: #ffffff;

  background:
    linear-gradient(
      135deg,
      #276f9b,
      #2f91bb
    );

  box-shadow:
    0 10px 22px
    rgba(
      39,
      111,
      155,
      .17
    );

  cursor: pointer;

  font-size: 10px;

  font-weight: 900;

  transition:
    transform .15s ease,
    box-shadow .15s ease;
}

.admin-login-submit:hover:not(:disabled) {
  transform: translateY(-1px);

  box-shadow:
    0 14px 28px
    rgba(
      39,
      111,
      155,
      .22
    );
}

.admin-login-submit:disabled {
  opacity: .7;

  cursor: not-allowed;
}

.admin-login-spinner {
  width: 16px;
  height: 16px;

  border: 2px solid
    rgba(
      255,
      255,
      255,
      .4
    );

  border-top-color: #ffffff;

  border-radius: 50%;

  animation:
    adminLoginSpin .75s linear infinite;
}

@keyframes adminLoginSpin {

  to {
    transform: rotate(360deg);
  }

}


/* =========================================================
   DEMO ACCESS
========================================================= */

.admin-demo-box {
  display: flex;

  align-items: flex-start;

  gap: 10px;

  margin-top: 18px;

  padding: 13px;

  border: 1px dashed #ccdce4;

  border-radius: 12px;

  background: #f6fafc;
}

.admin-demo-icon {
  width: 34px;
  height: 34px;

  flex: 0 0 34px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: #c2410c;

  background: #e3f1f8;
}

.admin-demo-box > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 3px;
}

.admin-demo-box span {
  color: #718793;

  font-size: 7px;

  font-weight: 900;

  letter-spacing: .1em;
}

.admin-demo-box strong {
  color: #315266;

  font-size: 9px;
}

.admin-demo-box p {
  margin: 1px 0 0;

  color: #80919b;

  font-size: 7px;

  line-height: 1.5;
}

.admin-demo-box b {
  color: #c2410c;

  font-weight: 900;
}


/* =========================================================
   SECURITY
========================================================= */

.admin-security-row {
  display: flex;

  align-items: flex-start;

  gap: 7px;

  margin-top: 15px;

  padding-top: 13px;

  border-top: 1px solid #edf1f3;

  color: #83949d;

  font-size: 7px;

  line-height: 1.55;
}

.admin-security-row svg {
  flex: 0 0 auto;

  color: #c2410c;
}


/* =========================================================
   TRUST STRIP
========================================================= */

.admin-login-trust {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 10px;

  margin-top: 37px;

  padding:
    13px;

  border: 1px solid #fed7aa;

  border-radius: 15px;

  background: #ffffff;
}

.admin-login-trust > div {
  display: flex;

  align-items: center;

  justify-content: center;

  gap: 7px;

  min-height: 31px;

  border-right: 1px solid #e8edef;
}

.admin-login-trust > div:last-child {
  border-right: 0;
}

.admin-login-trust svg {
  flex: 0 0 auto;

  color: #166534;
}

.admin-login-trust span {
  color: #738792;

  font-size: 7px;

  font-weight: 800;
}


/* =========================================================
   FOOTER
========================================================= */

.admin-login-footer {
  display: flex;

  align-items: center;
  justify-content: space-between;

  gap: 20px;

  padding:
    21px
    7vw;

  border-top: 1px solid #e2e9ec;

  color: #83949c;

  background: #ffffff;

  font-size: 8px;
}

.admin-login-footer > div {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-login-footer strong {
  color: #31566c;

  font-family: var(--font-heading);

  font-size: 12px;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1050px) {

  .admin-login-layout {
    grid-template-columns: 1fr;

    gap: 35px;
  }

  .admin-login-intro {
    max-width: none;
  }

  .admin-login-card {
    max-width: 600px;

    width: 100%;

    margin: 0 auto;
  }

}


@media (max-width: 720px) {

  .admin-login-container {
    padding:
      35px
      18px
      55px;
  }

  .admin-login-header {
    padding:
      0
      18px;
  }

  .admin-login-intro h1 {
    font-size: 46px;
  }

  .admin-login-intro > p {
    font-size: 13px;
  }

  .admin-login-feature-grid {
    grid-template-columns: 1fr;
  }

  .admin-login-trust {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-login-trust > div {
    border-right: 0;
  }

  .admin-login-footer {
    align-items: flex-start;

    flex-direction: column;

    padding:
      20px
      18px;
  }

}


@media (max-width: 500px) {

  .admin-login-header {
    min-height: 68px;
  }

  .admin-brand-mark {
    width: 37px;
    height: 37px;
  }

  .admin-login-brand strong {
    font-size: 15px;
  }

  .admin-login-brand span {
    font-size: 7px;
  }

  .admin-login-back {
    font-size: 8px;
  }

  .admin-login-card {
    padding: 21px;

    border-radius: 19px;
  }

  .admin-login-card-heading h2 {
    font-size: 21px;
  }

  .admin-login-intro h1 {
    font-size: 40px;
  }

  .admin-workflow-steps {
    overflow-x: auto;

    justify-content: flex-start;

    padding-bottom: 4px;
  }

  .admin-workflow-step {
    flex: 0 0 52px;
  }

  .admin-workflow-line {
    min-width: 25px;
  }

  .admin-login-trust {
    grid-template-columns: 1fr;
  }

