/* =========================================================
   ADMIN LAYOUT
========================================================= */

.admin-layout {
  min-height: 100vh;

  display: flex;

  background:
    #f4f7f8;

  color: #203f51;
}

.admin-layout-main {
  min-width: 0;

  flex: 1;

  margin-left: 245px;
}

.admin-layout-content {
  width: 100%;

  min-height:
    calc(100vh - 76px);

  padding: 28px;
}


/* =========================================================
   SIDEBAR
========================================================= */

.admin-sidebar {
  position: fixed;

  z-index: 80;

  top: 0;
  left: 0;
  bottom: 0;

  width: 245px;

  display: flex;

  flex-direction: column;

  padding: 18px 13px;

  border-right: 1px solid #fed7aa;

  background:
    #ffffff;

  box-shadow:
    8px 0 30px
    rgba(
      28,
      57,
      72,
      .04
    );
}

.admin-sidebar-top {
  display: flex;

  align-items: center;

  justify-content: space-between;

  padding:
    3px
    5px
    18px;
}

.admin-sidebar-brand {
  display: flex;

  align-items: center;

  gap: 9px;

  color: inherit;

  text-decoration: none;
}

.admin-sidebar-logo {
  width: 38px;
  height: 38px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: #ffffff;

  background:
    linear-gradient(
      145deg,
      #276f9b,
      #3291bc
    );

  font-size: 10px;
  font-weight: 950;
}

.admin-sidebar-brand > div:last-child {
  display: flex;

  flex-direction: column;

  gap: 2px;
}

.admin-sidebar-brand strong {
  color: #294a5d;

  font-family: var(--font-heading);

  font-size: 15px;
}

.admin-sidebar-brand span {
  color: #8899a1;

  font-size: 7px;

  font-weight: 800;
}

.admin-sidebar-close {
  display: none;

  border: 0;

  color: #657d89;

  background: transparent;

  cursor: pointer;
}


/* =========================================================
   CENTER
========================================================= */

.admin-center-selector {
  display: flex;

  align-items: center;

  gap: 8px;

  margin-bottom: 18px;

  padding:
    10px;

  border:
    1px solid
    #dae7ec;

  border-radius: 11px;

  background:
    #f4f9fb;
}

.admin-center-selector-icon {
  width: 30px;
  height: 30px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 8px;

  color: #c2410c;

  background:
    #e0eff6;
}

.admin-center-selector > div:last-child {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-center-selector span {
  color: #8699a2;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .1em;
}

.admin-center-selector strong {
  overflow: hidden;

  color: #315266;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}


/* =========================================================
   NAV
========================================================= */

.admin-sidebar-nav {
  flex: 1;

  overflow-y: auto;

  padding-right: 2px;
}

.admin-sidebar-group {
  margin-bottom: 17px;
}

.admin-sidebar-section {
  display: block;

  padding:
    0
    9px
    7px;

  color: #a0adb3;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .13em;
}

.admin-sidebar-items {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-sidebar-link {
  position: relative;

  display: flex;

  align-items: center;

  gap: 9px;

  min-height: 39px;

  padding:
    0
    10px;

  border-radius: 9px;

  color: #68818e;

  text-decoration: none;

  font-size: 8px;

  font-weight: 800;

  transition:
    background .15s ease,
    color .15s ease;
}

.admin-sidebar-link:hover {
  color: #315d73;

  background:
    #f2f7f9;
}

.admin-sidebar-link.active {
  color: #c2410c;

  background:
    #eaf4f8;
}

.admin-sidebar-link.active svg {
  color: #c2410c;
}

.admin-sidebar-link svg {
  flex: 0 0 auto;
}

.admin-sidebar-active-dot {
  width: 5px;
  height: 5px;

  margin-left: auto;

  border-radius: 50%;

  background: #c2410c;
}


/* =========================================================
   SIDEBAR BOTTOM
========================================================= */

.admin-sidebar-bottom {
  padding-top: 15px;

  border-top:
    1px solid
    #e9eef0;
}

.admin-sidebar-status {
  display: flex;

  align-items: center;

  gap: 8px;

  padding:
    9px;

  border-radius: 9px;

  background:
    #f5f9f7;
}

.admin-sidebar-status > span {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: #166534;

  box-shadow:
    0 0 0 4px
    rgba(
      33,
      139,
      82,
      .08
    );
}

.admin-sidebar-status > div {
  display: flex;

  flex-direction: column;

  gap: 2px;
}

.admin-sidebar-status strong {
  color: #41715a;

  font-size: 7px;
}

.admin-sidebar-status small {
  color: #8a9c93;

  font-size: 6px;
}

.admin-sidebar-logout {
  display: flex;

  align-items: center;

  gap: 7px;

  margin-top: 7px;

  padding: 8px 9px;

  border-radius: 8px;

  color: #8a6666;

  font-size: 7px;

  font-weight: 800;

  text-decoration: none;
}

.admin-sidebar-logout:hover {
  color: #b04d45;

  background:
    #fff4f2;
}


/* =========================================================
   HEADER
========================================================= */

.admin-main-header {
  position: sticky;

  z-index: 40;

  top: 0;

  min-height: 76px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 20px;

  padding:
    0
    28px;

  border-bottom:
    1px solid
    #dfe7ea;

  background:
    rgba(
      255,
      255,
      255,
      .94
    );

  backdrop-filter:
    blur(13px);
}

.admin-header-left {
  display: flex;

  align-items: center;

  gap: 12px;

  min-width: 0;
}

.admin-header-left > div {
  min-width: 0;
}

.admin-header-left h1 {
  margin: 0;

  color: #28485b;

  font-family: var(--font-heading);

  font-size: 21px;
}

.admin-header-left p {
  margin: 3px 0 0;

  color: #82949d;

  font-size: 7px;
}

.admin-mobile-menu {
  display: none;

  width: 38px;
  height: 38px;

  align-items: center;
  justify-content: center;

  border:
    1px solid
    #d9e4e8;

  border-radius: 9px;

  color: #527080;

  background: #ffffff;

  cursor: pointer;
}

.admin-header-actions {
  display: flex;

  align-items: center;

  gap: 8px;
}

.admin-header-refresh,
.admin-notification-button {
  height: 36px;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 6px;

  border:
    1px solid
    #d9e4e8;

  border-radius: 9px;

  color: #5d7785;

  background: #ffffff;

  cursor: pointer;
}

.admin-header-refresh {
  padding:
    0
    10px;

  font-size: 7px;

  font-weight: 900;
}

.admin-header-refresh:disabled {
  opacity: .6;

  cursor: not-allowed;
}

.admin-header-refresh:hover:not(:disabled) {
  color: #c2410c;

  border-color:
    #b9d1db;
}

.admin-notification-button {
  position: relative;

  width: 36px;
}

.admin-notification-button > span {
  position: absolute;

  top: -4px;
  right: -3px;

  min-width: 15px;
  height: 15px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 50%;

  color: #ffffff;

  background: #d56e54;

  font-size: 6px;

  font-weight: 900;
}

.admin-operator-profile {
  display: flex;

  align-items: center;

  gap: 8px;

  margin-left: 4px;

  padding-left: 11px;

  border-left:
    1px solid
    #e4ebee;
}

.admin-operator-avatar {
  width: 33px;
  height: 33px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: #c2410c;

  background: #ffedd5;
}

.admin-operator-profile > div:last-child {
  display: flex;

  flex-direction: column;

  gap: 2px;
}

.admin-operator-profile strong {
  color: #315165;

  font-size: 8px;
}

.admin-operator-profile span {
  color: #8a9aa2;

  font-size: 6px;
}


/* =========================================================
   OVERLAY
========================================================= */

.admin-sidebar-overlay {
  display: none;
}


/* =========================================================
   ANIMATIONS
========================================================= */

.admin-refresh-spin {
  animation:
    adminRefreshSpin .7s linear infinite;
}

@keyframes adminRefreshSpin {

  to {
    transform: rotate(360deg);
  }

}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 900px) {

  .admin-layout-main {
    margin-left: 0;
  }

  .admin-sidebar {
    transform:
      translateX(-100%);

    transition:
      transform .2s ease;
  }

  .admin-sidebar.open {
    transform:
      translateX(0);
  }

  .admin-sidebar-close {
    display: flex;

    align-items: center;
    justify-content: center;
  }

  .admin-sidebar-overlay {
    position: fixed;

    z-index: 70;

    inset: 0;

    display: block;

    border: 0;

    background:
      rgba(
        20,
        42,
        53,
        .24
      );

    cursor: pointer;
  }

  .admin-mobile-menu {
    display: flex;
  }

}


@media (max-width: 600px) {

  .admin-main-header {
    padding:
      0
      16px;
  }

  .admin-layout-content {
    padding: 18px 16px;
  }

  .admin-header-refresh span {
    display: none;
  }

  .admin-operator-profile > div:last-child {
    display: none;
  }

}
/* =========================================================
   ADMIN DASHBOARD
========================================================= */

.admin-dashboard-page {
