.admin-center-chip {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  min-height: 30px;

  padding:
    0
    10px;

  border:
    1px solid
    #d9e4e8;

  border-radius: 999px;

  color: #5d7887;

  background: #ffffff;

  font-size: 7px;

  font-weight: 800;
}


/* =========================================================
   ERROR
========================================================= */

.admin-dashboard-error {
  display: flex;

  align-items: flex-start;

  gap: 9px;

  margin-bottom: 14px;

  padding:
