  background: #eee9f7;
}

.admin-panel-icon.teal {
  color: #278d8f;
  background: #e2f4f3;
}

.admin-panel-link {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  color: #4b7488;

  font-size: 7px;

  font-weight: 900;

  text-decoration: none;

  white-space: nowrap;
}

.admin-panel-link:hover {
  color: #c2410c;
}

.admin-panel-live {
  padding:
    5px
    7px;

  border-radius: 999px;

  color: #166534;

  background: #edf8f0;

  font-size: 7px;

  font-weight: 900;
}

.admin-alert-count {
  width: 25px;
  height: 25px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 8px;

  color: #b56928;

  background: #fff0dd;

  font-size: 7px;

  font-weight: 900;
}


/* =========================================================
   QUEUE SEARCH
========================================================= */

.admin-queue-controls {
  display: flex;

  gap: 7px;

  padding:
    0
    17px
    13px;
}

.admin-dashboard-search {
  flex: 1;

  height: 35px;

  display: flex;

  align-items: center;

  gap: 7px;

  padding:
    0
    10px;

  border:
    1px solid
    #fed7aa;

  border-radius: 8px;

  color: #84969e;

  background: #fff7ed;
}

.admin-dashboard-search:focus-within {
  border-color: #a6c3d0;

  background: #ffffff;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .05
    );
}

.admin-dashboard-search input {
  min-width: 0;

  flex: 1;

  height: 100%;

  padding: 0;

  outline: none;

  border: 0;

  color: #315165;

  background: transparent;

  font-size: 8px;
}

.admin-dashboard-search input::placeholder {
  color: #adb9bf;
}

.admin-filter-select {
  width: 115px;
}

.admin-filter-select select {
  width: 100%;

  height: 35px;

  padding:
    0
    9px;

  border:
    1px solid
    #fed7aa;

  border-radius: 8px;

  outline: none;

  color: #5f7785;

  background: #fff7ed;

  cursor: pointer;

  font-size: 7px;

  font-weight: 800;
}


/* =========================================================
   TABLE
========================================================= */

.admin-queue-table {
  width: 100%;

  overflow-x: auto;
}

.admin-table-head,
.admin-booking-row {
  min-width: 690px;

  display: grid;

  grid-template-columns:
    1.05fr
    1.3fr
    1fr
    1.05fr
    .85fr;

  column-gap: 10px;

  align-items: center;

  padding:
    0
    17px;
}

.admin-table-head {
  min-height: 31px;

  border-top:
    1px solid
    #edf1f3;

  border-bottom:
    1px solid
    #e8edef;

  color: #9ba8ae;

  background: #fff7ed;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .08em;

  text-transform: uppercase;
}

.admin-booking-row {
  min-height: 67px;

  border-bottom:
    1px solid
    #edf1f3;

  color: inherit;

  text-decoration: none;

  transition:
    background .12s ease;
}

.admin-booking-row:hover {
  background:
    #f8fbfc;
}

.admin-booking-row > div {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-booking-id strong {
  color: #2f566c;

  font-size: 9px;
}

.admin-booking-id span {
  color: #9aa8ae;

  font-size: 6px;
}

.admin-booking-farmer strong,
.admin-booking-produce strong,
.admin-booking-schedule strong {
  overflow: hidden;

  color: #415f70;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-booking-farmer span,
.admin-booking-produce span,
.admin-booking-schedule span {
  color: #899aa2;

  font-size: 6px;
}

.admin-booking-status {
  align-items: flex-start;
}

.admin-status-pill {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  width: fit-content;

  max-width: 100%;

  padding:
    5px
    7px;

  border-radius: 999px;

  font-size: 6px;

  font-weight: 900;

  white-space: nowrap;
}

.admin-status-pill > span {
  width: 5px;
  height: 5px;

  border-radius: 50%;

  background: currentColor;
}

.admin-status-pill.green {
  color: #166534;
  background: #eaf7ed;
}

.admin-status-pill.blue {
  color: #2a7eaa;
  background: #e8f3f8;
}

.admin-status-pill.orange {
  color: #cf7629;
  background: #fff0e4;
}

.admin-status-pill.purple {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-status-pill.gold {
  color: #bc7e17;
  background: #fff2d3;
}


/* =========================================================
   PANEL FOOTER
========================================================= */

.admin-panel-footer {
  min-height: 45px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  padding:
    0
    17px;

  color: #9aa7ad;

  font-size: 7px;
}

.admin-panel-footer > a {
  display: inline-flex;

  align-items: center;

  gap: 4px;

  color: #4f7589;

  font-size: 7px;

  font-weight: 900;

  text-decoration: none;
}


/* =========================================================
   CAPACITY
========================================================= */

.admin-capacity-meter {
  height: 8px;

  overflow: hidden;

  margin:
    0
    18px;

  border-radius: 99px;

  background: #e8edef;
}

.admin-capacity-meter > div {
  height: 100%;

  border-radius: inherit;

  background:
    linear-gradient(
      90deg,
      #166534,
      #62ad76
    );
}

.admin-capacity-summary {
  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  margin-top: 13px;

  padding:
    0
    18px;
}

.admin-capacity-summary > div {
  display: flex;

  flex-direction: column;

  gap: 3px;

  padding-right: 8px;
}

.admin-capacity-summary > div + div {
  padding-left: 10px;

  border-left:
    1px solid
    #e8edef;
}

.admin-capacity-summary span {
  color: #8999a1;

  font-size: 6px;
}

.admin-capacity-summary strong {
  color: #365667;

  font-family: var(--font-heading);

  font-size: 17px;
}

.admin-slot-list {
  display: flex;

  flex-direction: column;

  gap: 9px;

  margin:
    16px
    18px
    18px;
}

.admin-slot-row {
  display: grid;

  grid-template-columns:
    50px
    1fr
    34px;

  gap: 7px;

  align-items: center;
}

.admin-slot-row > span {
  color: #738994;

  font-size: 6px;

  font-weight: 800;
}

.admin-slot-row > strong {
  color: #667f8d;

  font-size: 6px;

  text-align: right;
}

.admin-slot-bar {
  height: 5px;

  overflow: hidden;

  border-radius: 99px;

  background: #edf1f3;
}

.admin-slot-bar > div {
  height: 100%;

  border-radius: inherit;

  background: #66ab7d;
}


/* =========================================================
   ALERTS
========================================================= */

.admin-alert-list {
  display: flex;

  flex-direction: column;

  padding:
    0
    13px
    12px;
}

.admin-alert-row {
  display: grid;

  grid-template-columns:
    29px
    1fr
    15px;

  gap: 8px;

  align-items: center;

  min-height: 51px;

  padding:
    7px
    4px;

  border-top:
    1px solid
    #edf1f3;

  color: inherit;

  text-decoration: none;
}

.admin-alert-row:first-child {
  border-top: 0;
}

.admin-alert-row > div {
  width: 29px;
  height: 29px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 8px;
}

.admin-alert-row.blue > div {
  color: #ea580c;
  background: #ffedd5;
}

.admin-alert-row.orange > div {
  color: #d1772b;
  background: #ffebdd;
}

.admin-alert-row.gold > div {
  color: #bc7e1a;
  background: #fff1d0;
}

.admin-alert-row.purple > div {
  color: #8165aa;
  background: #eee8f7;
}

.admin-alert-row > span {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-alert-row strong {
  overflow: hidden;

  color: #415e6f;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-alert-row small {
  color: #8c9ca3;

  font-size: 6px;

  line-height: 1.45;
}

.admin-alert-row > svg {
  color: #a4b2b8;
}

.admin-all-good {
  display: flex;

  align-items: center;

  gap: 8px;

  padding:
    10px
    4px;
}

.admin-all-good > svg {
  color: #166534;
}

.admin-all-good > div {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-all-good strong {
  color: #4b6b59;

  font-size: 8px;
}

.admin-all-good span {
  color: #879991;

  font-size: 6px;
}


/* =========================================================
   BOTTOM GRID
========================================================= */

.admin-dashboard-bottom-grid {
  display: grid;

  grid-template-columns:
    minmax(0, 1.2fr)
    minmax(310px, .8fr);

  gap: 15px;

  margin-top: 15px;
}


/* =========================================================
   ACTIVITY
========================================================= */

.admin-activity-list {
  display: flex;

  flex-direction: column;

  padding:
    0
    17px
    12px;
}

.admin-activity-row {
  display: grid;

  grid-template-columns:
    9px
    1fr
    45px;

  gap: 8px;

  align-items: center;

  min-height: 49px;

  border-top:
    1px solid
    #edf1f3;
}

.admin-activity-row:first-child {
  border-top: 0;
}

.admin-activity-dot {
  width: 7px;
  height: 7px;

  border-radius: 50%;
}

.admin-activity-dot.green {
  background: #166534;
}

.admin-activity-dot.blue {
  background: #ea580c;
}

.admin-activity-dot.orange {
  background: #d2782c;
}

.admin-activity-dot.purple {
  background: #8064a9;
}

.admin-activity-dot.gold {
  background: #c2871a;
}

.admin-activity-content {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-activity-content strong {
  color: #405d6e;

  font-size: 8px;
}

.admin-activity-content span {
  overflow: hidden;

  color: #8c9aa0;

  font-size: 6px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-activity-row small {
  color: #a0adb2;

  font-size: 6px;

  text-align: right;
}


/* =========================================================
   QUICK ACTIONS
========================================================= */

.admin-quick-actions {
  display: grid;

  grid-template-columns:
    repeat(2, 1fr);

  gap: 8px;

  padding:
    0
    17px
    17px;
}

.admin-quick-action {
  min-height: 75px;

  display: grid;

  grid-template-columns:
    34px
    1fr
    13px;

  gap: 8px;

  align-items: center;

  padding: 10px;

  border:
    1px solid
    #e2eaed;

  border-radius: 11px;

  color: inherit;

  text-decoration: none;

  background: #fbfcfd;

  transition:
    transform .14s ease,
    border-color .14s ease,
    background .14s ease;
}

.admin-quick-action:hover {
  transform:
    translateY(-1px);

  border-color:
    #c5d6dd;

  background:
    #ffffff;
}

.admin-quick-action-icon {
  width: 34px;
  height: 34px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 9px;
}

.admin-quick-action.blue
.admin-quick-action-icon {
  color: #ea580c;
  background: #ffedd5;
}

.admin-quick-action.purple
.admin-quick-action-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-quick-action.gold
.admin-quick-action-icon {
  color: #c2871c;
  background: #fff0cd;
}

.admin-quick-action.green
.admin-quick-action-icon {
  color: #166534;
  background: #e5f4e9;
}

.admin-quick-action > div:nth-child(2) {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-quick-action strong {
  overflow: hidden;

  color: #3c5a6c;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-quick-action span {
  color: #8a9aa1;

  font-size: 6px;

  line-height: 1.45;
}

.admin-quick-action > svg {
  color: #9eabb2;
}


/* =========================================================
   DATA FOOTER
========================================================= */

.admin-dashboard-data-footer {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  margin-top: 15px;

  padding:
    8px
    2px;

  color: #8b9aa1;

  font-size: 6px;
}

.admin-dashboard-data-footer > div {
  display: inline-flex;

  align-items: center;

  gap: 5px;
}

.admin-dashboard-data-footer > div:first-child svg {
  color: #c2410c;
}

.admin-dashboard-data-footer > div:nth-child(2) svg {
  color: #166534;
}

.admin-dashboard-data-footer button {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  padding: 6px 8px;

  border:
    1px solid
    #fed7aa;

  border-radius: 7px;

  color: #5f7a88;

  background: #ffffff;

  cursor: pointer;

  font-size: 6px;

  font-weight: 800;
}

.admin-dashboard-data-footer button:hover {
  color: #c2410c;

  border-color:
    #b8d0da;
}


/* =========================================================
   LOADING SKELETON
========================================================= */

.admin-dashboard-loading-list {
  padding:
    0
    17px;
}

.admin-skeleton-row {
  display: grid;

  grid-template-columns:
    repeat(5, 1fr);

  gap: 10px;

  min-height: 67px;

  align-items: center;

  border-bottom:
    1px solid
    #edf1f3;
}

.admin-skeleton-row span {
  height: 8px;

  border-radius: 99px;

  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f7f9fa,
      #edf2f4
    );

  background-size:
    200% 100%;

  animation:
    adminSkeleton 1.2s infinite;
}

@keyframes adminSkeleton {

  0% {
    background-position:
      200% 0;
  }

  100% {
    background-position:
      -200% 0;
  }

}


/* =========================================================
   EMPTY
========================================================= */

.admin-dashboard-empty {
  min-height: 260px;

  display: flex;

  align-items: center;
  justify-content: center;

  flex-direction: column;

  gap: 7px;

  color: #96a5ac;

  text-align: center;
}

.admin-dashboard-empty svg {
  color: #8eabb8;
}

.admin-dashboard-empty strong {
  color: #5b7481;

  font-size: 10px;
}

.admin-dashboard-empty span {
  font-size: 7px;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1250px) {

  .admin-kpi-grid {
    grid-template-columns:
      repeat(3, 1fr);
  }

}


@media (max-width: 1050px) {

  .admin-dashboard-main-grid {
    grid-template-columns:
      1fr;
  }

  .admin-dashboard-side {
    display: grid;

    grid-template-columns:
      repeat(2, 1fr);

    align-items: start;
  }

  .admin-dashboard-bottom-grid {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 800px) {

  .admin-dashboard-hero {
    flex-direction: column;
  }

  .admin-dashboard-hero-right {
    padding-top: 0;
  }

  .admin-kpi-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-dashboard-side {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 560px) {

  .admin-dashboard-page {
    width: 100%;
  }

  .admin-dashboard-hero h2 {
    font-size: 30px;
  }

  .admin-dashboard-hero p {
    font-size: 9px;
  }

  .admin-dashboard-hero-right {
    width: 100%;
  }

  .admin-live-chip,
  .admin-center-chip {
    flex: 1;
  }

  .admin-kpi-grid {
    grid-template-columns:
      1fr 1fr;

    gap: 7px;
  }

  .admin-kpi-card {
    padding: 11px;
  }

  .admin-kpi-value {
    font-size: 23px;
  }

  .admin-queue-controls {
    flex-direction: column;
  }

  .admin-filter-select {
    width: 100%;
  }

  .admin-quick-actions {
    grid-template-columns:
      1fr;
  }

  .admin-dashboard-data-footer {
    align-items: flex-start;

    flex-direction: column;
  }

}
/* =========================================================
   ADMIN QUEUE
========================================================= */

.admin-queue-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-queue-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 24px;

  margin-bottom: 18px;
}

.admin-queue-hero h2 {
  margin: 6px 0 7px;

  color: #203f52;

  font-family: var(--font-heading);

  font-size: clamp(
    28px,
    3vw,
    40px
  );

  line-height: 1;

  letter-spacing: -.035em;
}

.admin-queue-hero p {
  max-width: 720px;

  margin: 0;

  color: #7c909a;

  font-size: 10px;

  line-height: 1.65;
}

.admin-queue-hero-actions {
  display: flex;
  align-items: center;

  gap: 8px;
}

.admin-queue-live-indicator {
  display: inline-flex;
  align-items: center;

  gap: 6px;

  min-height: 32px;

  padding:
    0
    10px;

  border:
    1px solid
    #cfe4d5;

  border-radius: 999px;

  color: #166534;

  background: #eff9f1;

  font-size: 7px;

  font-weight: 900;

  letter-spacing: .07em;
}

.admin-queue-live-indicator > span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #166534;

  box-shadow:
    0 0 0 4px
    rgba(
      33,
      139,
      82,
      .08
    );
}

.admin-queue-refresh-button {
  min-height: 32px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 6px;

  padding:
    0
    10px;

  border:
    1px solid
    #d9e4e8;

  border-radius: 8px;

  color: #5f7987;

  background: #ffffff;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}

.admin-queue-refresh-button:hover:not(:disabled) {
  color: #c2410c;

  border-color:
    #b9d0da;
}

.admin-queue-refresh-button:disabled {
  opacity: .65;

  cursor: not-allowed;
}


/* =========================================================
   ERROR
========================================================= */

.admin-queue-error {
  display: flex;

  align-items: flex-start;

  gap: 9px;

  margin-bottom: 13px;

  padding:
    12px
    14px;

  border:
    1px solid
    #efd0cb;

  border-radius: 11px;

  color: #b05348;

  background: #fff4f2;
}

.admin-queue-error > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-queue-error > div {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 3px;
}

.admin-queue-error strong {
  font-size: 8px;
}

.admin-queue-error span {
  color: #8e7772;

  font-size: 7px;

  line-height: 1.5;
}

.admin-queue-error button {
  margin-left: auto;

  border: 0;

  color: #a64f44;

  background: transparent;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}


/* =========================================================
   QUEUE STATS
========================================================= */

.admin-queue-stats {
  display: grid;

  grid-template-columns:
    repeat(6, 1fr);

  gap: 9px;

  margin-bottom: 15px;
}

.admin-queue-stat {
  position: relative;

  min-width: 0;

  display: flex;

  align-items: center;

  gap: 9px;

  padding:
    12px;

  border:
    1px solid
    #fed7aa;

  border-radius: 13px;

  background: #ffffff;

  cursor: pointer;

  text-align: left;

  box-shadow:
    0 7px 20px
    rgba(
      30,
      62,
      77,
      .03
    );

  transition:
    transform .14s ease,
    box-shadow .14s ease,
    border-color .14s ease;
}

.admin-queue-stat:hover {
  transform:
    translateY(-2px);

  box-shadow:
    0 12px 25px
    rgba(
      30,
      62,
      77,
      .06
    );
}

.admin-queue-stat.active {
  border-color:
    #9fc3d1;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .06
    );
}

.admin-queue-stat-icon {
  width: 36px;
  height: 36px;

  flex: 0 0 36px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;
