  font-family: var(--font-heading);

  font-size: 18px;
}

.admin-queue-stat-arrow {
  margin-left: auto;

  color: #a8b4b9;
}


/* =========================================================
   FILTER PANEL
========================================================= */

.admin-queue-filter-panel {
  display: flex;

  align-items: center;

  gap: 7px;

  margin-bottom: 13px;

  padding: 9px;

  border:
    1px solid
    #fed7aa;

  border-radius: 12px;

  background: #ffffff;

  box-shadow:
    0 7px 22px
    rgba(
      30,
      62,
      77,
      .03
    );
}

.admin-queue-search {
  flex: 1;

  min-width: 200px;

  height: 36px;

  display: flex;

  align-items: center;

  gap: 7px;

  padding:
    0
    10px;

  border:
    1px solid
    #fed7aa;

  border-radius: 8px;

  color: #84969e;

  background: #fff7ed;
}

.admin-queue-search:focus-within {
  border-color: #a9c5d0;

  background: #ffffff;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .05
    );
}

.admin-queue-search input {
  width: 100%;
  min-width: 0;

  height: 100%;

  padding: 0;

  border: 0;
  outline: 0;

  color: #315165;

  background: transparent;

  font-size: 8px;
}

.admin-queue-search input::placeholder {
  color: #aebbc1;
}

.admin-queue-filter-control {
  height: 36px;

  display: flex;

  align-items: center;

  gap: 5px;

  padding:
    0
    8px;

  border:
    1px solid
    #fed7aa;

  border-radius: 8px;

  color: #81939d;

  background: #fff7ed;
}

.admin-queue-filter-control:focus-within {
  border-color: #abc6d0;
  background: #ffffff;
}

.admin-queue-filter-control select {
  min-width: 90px;

  height: 100%;

  padding: 0;

  border: 0;
  outline: 0;

  color: #587381;

  background: transparent;

  cursor: pointer;

  font-size: 7px;

  font-weight: 800;
}

.admin-clear-filters {
  height: 36px;

  display: inline-flex;

  align-items: center;

  gap: 5px;

  padding:
    0
    9px;

  border: 0;

  border-radius: 8px;

  color: #ac5b50;

  background: #fff3f1;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}


/* =========================================================
   QUEUE TABLE PANEL
========================================================= */

.admin-queue-table-panel {
  overflow: hidden;

  border:
    1px solid
    #fed7aa;

  border-radius: 17px;

  background: #ffffff;

  box-shadow:
    0 10px 29px
    rgba(
      30,
      62,
      77,
      .045
    );
}

.admin-queue-table-header {
  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 15px;

  padding:
    18px
    18px
    14px;
}

.admin-queue-table-header > div {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-queue-table-header h3 {
  margin: 0;

  color: #2f5063;

  font-family: var(--font-heading);

  font-size: 19px;
}

.admin-queue-result-note {
  color: #91a0a6;

  font-size: 7px;
}


/* =========================================================
   FULL TABLE
========================================================= */

.admin-full-queue-table {
  width: 100%;

  overflow-x: auto;
}

.admin-full-table-head,
.admin-full-table-row {
  min-width: 1050px;

  display: grid;

  grid-template-columns:
    1.1fr
    1.45fr
    1.15fr
    1.15fr
    .85fr
    1.15fr;

  column-gap: 10px;

  align-items: center;

  padding:
    0
    18px;
}

.admin-full-table-head {
  min-height: 34px;

  border-top:
    1px solid
    #edf1f3;

  border-bottom:
    1px solid
    #e7edef;

  color: #99a7ad;

  background: #fff7ed;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .08em;

  text-transform: uppercase;
}

.admin-full-table-row {
  min-height: 76px;

  border-bottom:
    1px solid
    #edf1f3;
}

.admin-full-table-row:hover {
  background: #fbfcfd;
}

.admin-full-table-row > div {
  min-width: 0;
}


/* =========================================================
   TABLE CELLS
========================================================= */

.admin-full-booking-cell,
.admin-full-farmer-cell,
.admin-full-produce-cell,
.admin-full-schedule-cell,
.admin-full-status-cell,
.admin-full-action-cell {
  display: flex;

  align-items: center;

  gap: 8px;
}

.admin-full-booking-cell > div:last-child,
.admin-full-farmer-cell > div:last-child,
.admin-full-produce-cell,
.admin-full-schedule-cell {
  min-width: 0;
}

.admin-full-booking-cell > div:last-child,
.admin-full-farmer-cell > div:last-child {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-token-badge,
.admin-farmer-avatar {
  width: 35px;
  height: 35px;

  flex: 0 0 35px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;
}

.admin-token-badge {
  color: #ea580c;

  background: #ffedd5;
}

.admin-farmer-avatar {
  color: #718795;

  background: #edf2f4;
}

.admin-full-booking-cell strong {
  color: #31566b;

  font-size: 9px;
}

.admin-full-booking-cell span {
  color: #9aa8ae;

  font-size: 6px;
}

.admin-full-farmer-cell strong {
  overflow: hidden;

  color: #405e70;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-full-farmer-cell span {
  color: #899aa2;

  font-size: 6px;
}

.admin-full-produce-cell {
  flex-direction: column;

  align-items: flex-start;

  gap: 4px;
}

.admin-produce-name {
  display: flex;

  align-items: center;

  gap: 5px;
}

.admin-produce-name svg {
  color: #166534;
}

.admin-produce-name strong {
  color: #3d5b6a;

  font-size: 8px;
}

.admin-full-produce-cell > span {
  color: #83959d;

  font-size: 6px;
}

.admin-full-produce-cell small {
  color: #166534;

  font-size: 5px;

  font-weight: 900;
}

.admin-full-schedule-cell {
  flex-direction: column;

  align-items: flex-start;

  gap: 4px;
}

.admin-full-schedule-cell > div {
  display: flex;

  align-items: center;

  gap: 5px;
}

.admin-full-schedule-cell svg {
  color: #73909e;
}

.admin-full-schedule-cell strong {
  color: #415f70;

  font-size: 7px;
}

.admin-full-schedule-cell > span {
  color: #8999a1;

  font-size: 6px;
}

.admin-full-status-cell {
  align-items: flex-start;
}

.admin-full-action-cell {
  flex-wrap: wrap;

  justify-content: flex-start;

  gap: 5px;
}

.admin-row-view-button,
.admin-row-action-button {
  min-height: 29px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 5px;

  padding:
    0
    8px;

  border-radius: 7px;

  cursor: pointer;

  font-size: 6px;

  font-weight: 900;
}

.admin-row-view-button {
  color: #547384;

  border:
    1px solid
    #dbe5e9;

  background: #ffffff;
}

.admin-row-view-button:hover {
  color: #ea580c;

  border-color:
    #b8d0da;
}

.admin-row-action-button {
  border: 0;

  color: #ffffff;
}

.admin-row-action-button.green {
  background: #166534;
}

.admin-row-action-button.purple {
  background: #8064a9;
}

.admin-row-action-button.gold {
  color: #664914;

  background: #efd185;
}

.admin-row-action-button.teal {
  background: #288e91;
}

.admin-row-action-button:disabled {
  opacity: .55;

  cursor: not-allowed;
}


/* =========================================================
   EMPTY / LOADING
========================================================= */

.admin-queue-empty {
  min-height: 380px;

  display: flex;

  flex-direction: column;

  align-items: center;
  justify-content: center;

  padding: 35px;

  text-align: center;
}

.admin-queue-empty-icon {
  width: 55px;
  height: 55px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 15px;

  color: #73909e;

  background: #edf3f5;
}

.admin-queue-empty h3 {
  margin: 14px 0 5px;

  color: #486474;

  font-family: var(--font-heading);

  font-size: 18px;
}

.admin-queue-empty p {
  max-width: 360px;

  margin: 0;

  color: #899ba3;

  font-size: 8px;

  line-height: 1.6;
}

.admin-queue-empty button {
  margin-top: 15px;

  min-height: 34px;

  padding:
    0
    11px;

  border: 0;

  border-radius: 8px;

  color: #ffffff;

  background: #c2410c;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}

.admin-queue-loading {
  min-width: 1050px;
}

.admin-full-skeleton-row {
  min-height: 76px;

  display: grid;

  grid-template-columns:
    1.1fr
    1.45fr
    1.15fr
    1.15fr
    .85fr
    1.15fr;

  gap: 10px;

  align-items: center;

  padding:
    0
    18px;

  border-bottom:
    1px solid
    #edf1f3;
}

.admin-full-skeleton-row span {
  height: 8px;

  border-radius: 99px;

  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );

  background-size:
    200% 100%;

  animation:
    adminQueueSkeleton 1.2s infinite;
}

@keyframes adminQueueSkeleton {

  0% {
    background-position:
      200% 0;
  }

  100% {
    background-position:
      -200% 0;
  }

}


/* =========================================================
   INFO CARDS
========================================================= */

.admin-queue-info-grid {
  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  gap: 10px;

  margin-top: 14px;
}

.admin-queue-info-card {
  display: flex;

  align-items: flex-start;

  gap: 9px;

  padding:
    14px;

  border:
    1px solid
    #fed7aa;

  border-radius: 13px;

  background: #ffffff;
}

.admin-queue-info-icon {
  width: 34px;
  height: 34px;

  flex: 0 0 34px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 9px;
}

.admin-queue-info-card.blue
.admin-queue-info-icon {
  color: #ea580c;
  background: #ffedd5;
}

.admin-queue-info-card.green
.admin-queue-info-icon {
  color: #166534;
  background: #e4f4e8;
}

.admin-queue-info-card.purple
.admin-queue-info-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-queue-info-card > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 4px;
}

.admin-queue-info-card strong {
  color: #3b5a6b;

  font-size: 8px;
}

.admin-queue-info-card span {
  color: #84959d;

  font-size: 6px;

  line-height: 1.55;
}


/* =========================================================
   DRAWER OVERLAY
========================================================= */

.admin-booking-drawer-overlay {
  position: fixed;

  z-index: 100;

  inset: 0;

  background:
    rgba(
      24,
      51,
      64,
      .28
    );
}


/* =========================================================
   DRAWER
========================================================= */

.admin-booking-drawer {
  position: fixed;

  z-index: 110;

  top: 0;
  right: 0;
  bottom: 0;

  width: min(
    480px,
    94vw
  );

  display: flex;

  flex-direction: column;

  background: #ffffff;

  box-shadow:
    -18px 0 50px
    rgba(
      27,
      54,
      68,
      .15
    );

  animation:
    adminDrawerIn .2s ease;
}

@keyframes adminDrawerIn {

  from {
    transform:
      translateX(20px);

    opacity: 0;
  }

  to {
    transform:
      translateX(0);

    opacity: 1;
  }

}

.admin-drawer-header {
  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 15px;

  padding:
    21px;

  border-bottom:
    1px solid
    #e7edef;
}

.admin-drawer-header > div {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-drawer-header h2 {
  margin: 0;

  color: #284b5e;

  font-family: var(--font-heading);

  font-size: 24px;
}

.admin-drawer-close {
  width: 34px;
  height: 34px;

  display: flex;

  align-items: center;
  justify-content: center;

  border: 1px solid #fed7aa;

  border-radius: 9px;

  color: #69818d;

  background: #ffffff;

  cursor: pointer;
}

.admin-drawer-close:hover {
  color: #b05147;

  border-color:
    #e1c1bc;
}

.admin-drawer-status {
  display: flex;

  align-items: center;

  gap: 8px;

  padding:
    13px
    21px;

  border-bottom:
    1px solid
    #edf1f3;

  background:
    #fff7ed;
}

.admin-drawer-status > span:last-child {
  min-width: 0;

  color: #82949c;

  font-size: 7px;

  line-height: 1.5;
}

.admin-drawer-body {
  flex: 1;

  overflow-y: auto;

  padding:
    7px
    21px
    20px;
}

.admin-drawer-section {
  padding:
    18px
    0;

  border-bottom:
    1px solid
    #edf1f3;
}

.admin-drawer-section-heading {
  display: flex;

  align-items: center;

  gap: 8px;

  margin-bottom: 11px;
}

.admin-drawer-section-heading > div {
  width: 31px;
  height: 31px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 8px;

  color: #ea580c;

  background: #ffedd5;
}

.admin-drawer-section-heading h3 {
  margin: 0;

  color: #426274;

  font-size: 9px;

  font-weight: 900;
}

.admin-drawer-section-content {
  display: flex;

  flex-direction: column;
}

.admin-drawer-field {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  padding: 7px 0;
}

.admin-drawer-field span {
  color: #8a9ba2;

  font-size: 7px;
}

.admin-drawer-field strong {
  max-width: 63%;

  overflow-wrap: anywhere;

  color: #466274;

  font-size: 8px;

  text-align: right;
}


/* =========================================================
   DRAWER TIMELINE
========================================================= */

.admin-drawer-mini-timeline {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-mini-timeline-item {
  display: flex;

  align-items: center;

  gap: 8px;

  min-height: 29px;
}

.admin-mini-timeline-item > div {
  width: 23px;
  height: 23px;

  display: flex;

  align-items: center;
  justify-content: center;

  border:
    1px solid
    #dae3e7;

  border-radius: 50%;

  color: #9aa8af;

  background: #ffffff;
}

.admin-mini-timeline-item > div span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #d8e0e3;
}

.admin-mini-timeline-item.complete > div {
  color: #ffffff;

  border-color:
    #166534;

  background:
    #166534;
}

.admin-mini-timeline-item.active > div {
  color: #c2410c;

  border-color:
    #8eb7c8;

  background:
    #eaf4f8;
}

.admin-mini-timeline-item > span {
  color: #8799a1;

  font-size: 7px;
}

.admin-mini-timeline-item.complete > span {
  color: #4d735c;

  font-weight: 800;
}

.admin-mini-timeline-item.active > span {
  color: #39708c;

  font-weight: 900;
}


/* =========================================================
   DRAWER ACTION
========================================================= */

.admin-drawer-action-card {
  margin-top: 17px;

  padding: 15px;

  border:
    1px solid
    #fed7aa;

  border-radius: 12px;

  background:
    #f8fbfc;
}

.admin-drawer-action-card > span {
  display: block;

  color: #8a9ba2;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .1em;
}

.admin-drawer-action-card > strong {
  display: block;

  margin-top: 5px;

  color: #35576a;

  font-size: 11px;
}

.admin-drawer-action-card p {
  margin: 6px 0 12px;

  color: #81929a;

  font-size: 7px;

  line-height: 1.55;
}

.admin-drawer-action {
  width: 100%;

  min-height: 41px;

  display: flex;

  align-items: center;

  justify-content: center;

  gap: 7px;

  border: 0;

  border-radius: 9px;

  color: #ffffff;

  background: #166534;

  cursor: pointer;

  font-size: 8px;

  font-weight: 900;
}

.admin-drawer-action.purple {
  background: #8064a9;
}

.admin-drawer-action.gold {
  color: #664914;

  background: #efd185;
}

.admin-drawer-action.teal {
  background: #288e91;
}

.admin-drawer-action:disabled {
  opacity: .6;

  cursor: not-allowed;
}


/* =========================================================
   DRAWER FOOTER
========================================================= */

.admin-drawer-footer {
  min-height: 62px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  padding:
    11px
    21px;

  border-top:
    1px solid
    #e7edef;

  background:
    #ffffff;
}

.admin-drawer-footer > button {
  min-height: 35px;

  padding:
    0
    11px;

  border:
    1px solid
    #dbe5e9;

  border-radius: 8px;

  color: #607986;

  background: #ffffff;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}

.admin-drawer-details-link {
  min-height: 35px;

  display: inline-flex;

  align-items: center;

  gap: 5px;

  padding:
    0
    10px;

  border-radius: 8px;

  color: #ea580c;

  background: #eaf4f8;

  font-size: 7px;

  font-weight: 900;

  text-decoration: none;
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 1200px) {

  .admin-queue-stats {
    grid-template-columns:
      repeat(3, 1fr);
  }

}


@media (max-width: 900px) {

  .admin-queue-hero {
    flex-direction: column;
  }

  .admin-queue-hero-actions {
    width: 100%;
  }

  .admin-queue-stats {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-queue-info-grid {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 700px) {

  .admin-queue-filter-panel {
    align-items: stretch;

    flex-wrap: wrap;
  }

  .admin-queue-search {
    flex-basis: 100%;
  }

  .admin-queue-filter-control {
    flex: 1;
  }

  .admin-queue-filter-control select {
    min-width: 80px;
  }

  .admin-clear-filters {
    flex: 0 0 auto;
  }

}


@media (max-width: 520px) {

  .admin-queue-hero h2 {
    font-size: 30px;
  }

  .admin-queue-stats {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-queue-stat {
    padding: 10px;
  }

  .admin-queue-stat-icon {
    width: 31px;
    height: 31px;

    flex-basis: 31px;
  }

  .admin-queue-stat-content strong {
    font-size: 16px;
  }

  .admin-queue-stat-arrow {
    display: none;
  }

  .admin-queue-filter-control {
    width: 100%;

    flex-basis: 100%;
  }

  .admin-clear-filters {
    width: 100%;

    justify-content: center;
  }

  .admin-queue-table-header {
    align-items: flex-start;

    flex-direction: column;
  }

}
/* =========================================================
   ADMIN WEIGHING PAGE
========================================================= */

.admin-weighing-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-weighing-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 24px;

  margin-bottom: 18px;
}

.admin-weighing-hero h2 {
  margin: 6px 0 7px;

  color: #203f52;

  font-family: var(--font-heading);

  font-size: clamp(
    29px,
    3vw,
    41px
  );

  line-height: 1;

  letter-spacing: -.035em;
}

.admin-weighing-hero p {
  max-width: 700px;

  margin: 0;

  color: #7c909a;

  font-size: 10px;

  line-height: 1.65;
}

.admin-weighing-hero-actions {
  display: flex;

  align-items: center;

  gap: 8px;
}

.admin-weighing-live {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  min-height: 32px;

  padding:
    0
    10px;

  border:
    1px solid
    #cfe4d5;

  border-radius: 999px;

  color: #166534;

  background: #eff9f1;

  font-size: 7px;

  font-weight: 900;

  letter-spacing: .07em;
}

.admin-weighing-live > span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #166534;

  box-shadow:
    0 0 0 4px
    rgba(
      33,
      139,
      82,
      .08
    );
}

.admin-weighing-refresh {
  min-height: 32px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 6px;

  padding:
    0
    10px;

  border:
    1px solid
    #d9e4e8;

  border-radius: 8px;

  color: #5d7887;

  background: #ffffff;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}

.admin-weighing-refresh:hover:not(:disabled) {
  color: #ea580c;

  border-color:
    #bad0da;
}

.admin-weighing-refresh:disabled {
  opacity: .6;

  cursor: not-allowed;
}


/* =========================================================
   FEEDBACK
========================================================= */

.admin-weighing-feedback {
  display: flex;

  align-items: flex-start;

  gap: 9px;

  margin-bottom: 13px;

  padding:
    11px
    13px;

  border-radius: 10px;
}

.admin-weighing-feedback.error {
  border:
    1px solid
    #efd0ca;

  color: #b15348;

  background: #fff4f2;
}

.admin-weighing-feedback.success {
  border:
    1px solid
    #cfe5d4;

  color: #2f7550;

  background: #eef9f1;
}

.admin-weighing-feedback > svg {
  flex: 0 0 auto;

  margin-top: 1px;
}

.admin-weighing-feedback > span {
  flex: 1;

  font-size: 8px;

  line-height: 1.5;
}

.admin-weighing-feedback button {
  display: flex;

  align-items: center;
  justify-content: center;

  padding: 2px;

  border: 0;

  color: currentColor;

  background: transparent;

  cursor: pointer;
}


/* =========================================================
   KPI
========================================================= */

.admin-weighing-kpi-grid {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 10px;

  margin-bottom: 15px;
}

.admin-weighing-stat {
  display: flex;

  align-items: center;

  gap: 10px;

  padding:
    13px;

  border:
    1px solid
    #fed7aa;

  border-radius: 14px;

  background: #ffffff;

  box-shadow:
    0 7px 22px
    rgba(
      30,
      62,
      77,
      .03
    );
}

.admin-weighing-stat-icon {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;
}

.admin-weighing-stat.blue
.admin-weighing-stat-icon {
  color: #ea580c;
  background: #ffedd5;
}

.admin-weighing-stat.orange
.admin-weighing-stat-icon {
  color: #d2772b;
  background: #ffeadc;
}

.admin-weighing-stat.purple
.admin-weighing-stat-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-weighing-stat.green
.admin-weighing-stat-icon {
  color: #166534;
  background: #e4f4e8;
}

.admin-weighing-stat > div:last-child {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-weighing-stat strong {
  color: #2f5063;

  font-family: var(--font-heading);

  font-size: 20px;
}

.admin-weighing-stat span {
  color: #84969e;

  font-size: 7px;
}


/* =========================================================
   WORKSPACE
========================================================= */

.admin-weighing-workspace {
  display: grid;

  grid-template-columns:
    350px
    minmax(0, 1fr);

  gap: 15px;

  align-items: start;
}

.admin-weighing-list-panel,
.admin-weighing-form-panel {
  min-width: 0;

  border:
    1px solid
    #fed7aa;

  border-radius: 17px;

  background: #ffffff;

  box-shadow:
    0 10px 28px
    rgba(
      30,
      62,
      77,
      .04
    );
}


/* =========================================================
   LIST
========================================================= */

.admin-weighing-panel-heading {
  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 10px;

  padding:
    17px
    17px
    13px;
}

.admin-weighing-panel-heading > div {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-weighing-panel-heading h3 {
  margin: 0;

  color: #2f5063;

  font-family: var(--font-heading);

  font-size: 17px;
}

.admin-weighing-panel-heading > span {
  color: #96a4aa;

  font-size: 7px;
}

.admin-weighing-search {
  height: 36px;

  display: flex;

  align-items: center;

  gap: 7px;

  margin:
    0
    17px
    11px;

  padding:
    0
    10px;

  border:
    1px solid
    #fed7aa;

  border-radius: 8px;

  color: #8799a1;

  background: #fff7ed;
}

.admin-weighing-search:focus-within {
  border-color:
    #a9c5d0;

  background:
    #ffffff;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .05
    );
}

.admin-weighing-search input {
  width: 100%;

  min-width: 0;

  height: 100%;

  padding: 0;

  border: 0;
  outline: 0;

  color: #315165;

  background: transparent;

  font-size: 8px;
}

.admin-weighing-search input::placeholder {
  color: #adb9bf;
}

.admin-weighing-booking-list {
  display: flex;

  flex-direction: column;

  max-height: 700px;

  overflow-y: auto;
}


/* =========================================================
   BOOKING ITEM
========================================================= */

.admin-weighing-booking-item {
  width: 100%;

  display: flex;

  align-items: center;

  gap: 9px;

  min-height: 72px;

  padding:
    10px
    17px;

  border: 0;

  border-top:
    1px solid
    #edf1f3;

  color: #315064;

  background: #ffffff;

  cursor: pointer;

  text-align: left;

  transition:
    background .13s ease,
    box-shadow .13s ease;
}

.admin-weighing-booking-item:hover {
  background:
    #f9fbfc;
}

.admin-weighing-booking-item.selected {
  background:
    #eef6f9;

  box-shadow:
    inset 3px 0 0
    #ea580c;
}

.admin-weighing-token {
  width: 35px;
  height: 35px;

  flex: 0 0 35px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: #ea580c;

  background: #ffedd5;
}

.admin-weighing-booking-main {
  min-width: 0;

  flex: 1;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-weighing-booking-main > div {
  display: flex;

  align-items: center;

  gap: 7px;
}

.admin-weighing-booking-main > div strong {
  color: #31576d;

  font-size: 9px;
}

.admin-weighing-booking-main > span {
  overflow: hidden;

  color: #587281;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-weighing-booking-main > small {
  color: #899aa2;

  font-size: 6px;
}

.admin-weighing-booking-item > svg {
  color: #a1afb5;
}


/* =========================================================
   STATUS DOT
========================================================= */

.admin-weighing-status-dot {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background:
    #166534;
}

.admin-weighing-status-dot.blue {
  background:
    #ea580c;
}

.admin-weighing-status-dot.orange {
  background:
    #d2772b;
}

.admin-weighing-status-dot.purple {
  background:
    #8064a9;
}

.admin-weighing-status-dot.gold {
  background:
    #c3871c;
}

.admin-weighing-status-dot.green {
  background:
    #166534;
}


/* =========================================================
   EMPTY LIST
========================================================= */

.admin-weighing-empty {
  min-height: 240px;

  display: flex;

  flex-direction: column;

  align-items: center;
  justify-content: center;

  gap: 6px;

  padding: 25px;

  color: #9aa8ae;

  text-align: center;
}

.admin-weighing-empty strong {
  color: #5e7784;

  font-size: 9px;
}

.admin-weighing-empty span {
  max-width: 220px;

  color: #8b9ba2;

  font-size: 7px;

  line-height: 1.5;
}


/* =========================================================
   SKELETON
========================================================= */

.admin-weighing-loading {
  display: flex;

  flex-direction: column;
}

.admin-weighing-skeleton {
  display: flex;

  align-items: center;

  gap: 10px;

  min-height: 72px;

  padding:
    0
    17px;

  border-top:
    1px solid
    #edf1f3;
}

.admin-weighing-skeleton > span {
  width: 35px;
  height: 35px;

  border-radius: 10px;

  background: #edf2f4;

  animation:
    adminWeightPulse 1.1s infinite;
}

.admin-weighing-skeleton > div {
  flex: 1;

  display: flex;

  flex-direction: column;

  gap: 6px;
}

.admin-weighing-skeleton > div span {
  height: 7px;

  border-radius: 99px;

  background:
    #edf2f4;

  animation:
    adminWeightPulse 1.1s infinite;
}

.admin-weighing-skeleton > div span:nth-child(1) {
  width: 40%;
}

.admin-weighing-skeleton > div span:nth-child(2) {
  width: 65%;
}

.admin-weighing-skeleton > div span:nth-child(3) {
  width: 45%;
}

@keyframes adminWeightPulse {

  0%,
  100% {
    opacity: .65;
  }

  50% {
    opacity: 1;
  }

}


/* =========================================================
   FORM
========================================================= */

.admin-weighing-form {
  padding: 20px;
}

.admin-weighing-form-header {
  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 15px;
}

.admin-weighing-form-token {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  color: #ea580c;

  font-size: 8px;

  font-weight: 900;
}

.admin-weighing-form-header h3 {
  margin: 7px 0 4px;

  color: #2c4f61;

  font-family: var(--font-heading);

  font-size: 23px;
}

.admin-weighing-form-header p {
  margin: 0;

  color: #85969e;

  font-size: 7px;
}

.admin-weighing-close {
  width: 33px;
  height: 33px;

  display: flex;

  align-items: center;
  justify-content: center;

  border:
    1px solid
    #dde6ea;

  border-radius: 8px;

  color: #728792;

  background: #ffffff;

  cursor: pointer;
}

.admin-weighing-close:hover {
  color: #b05046;

  border-color:
    #e2c4bf;
}


/* =========================================================
   STATUS BANNER
========================================================= */

.admin-weighing-status-banner {
  display: flex;

  align-items: center;

  gap: 8px;

  margin-top: 17px;

  padding:
    10px
    12px;

  border:
    1px solid
    #e3eaed;

  border-radius: 10px;

  background: #f8fafb;
}

.admin-weighing-status-banner > span {
  color: #81939c;

  font-size: 7px;

  line-height: 1.5;
}

.admin-weighing-status-pill {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  padding:
    5px
    7px;

  border-radius: 999px;

  font-size: 6px;

  font-weight: 900;

  white-space: nowrap;
}

.admin-weighing-status-pill > span {
  width: 5px;
  height: 5px;

  border-radius: 50%;

  background: currentColor;
}

.admin-weighing-status-pill.green {
  color: #166534;
  background: #eaf7ed;
}

.admin-weighing-status-pill.blue {
  color: #ea580c;
  background: #e7f3f8;
}

.admin-weighing-status-pill.orange {
  color: #d1772a;
  background: #fff0e5;
}

.admin-weighing-status-pill.purple {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-weighing-status-pill.gold {
  color: #bd7f18;
  background: #fff2d4;
}


/* =========================================================
   SUMMARY
========================================================= */

.admin-weighing-summary {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 8px;

  margin-top: 13px;

  padding-bottom: 15px;

  border-bottom:
    1px solid
    #e9eef0;
}

.admin-weighing-summary > div {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-weighing-summary span {
  color: #8999a1;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .04em;
}

.admin-weighing-summary strong {
  overflow: hidden;

  color: #4a6574;

  font-size: 7px;

  white-space: nowrap;

  text-overflow: ellipsis;
}


/* =========================================================
   START WEIGHING
========================================================= */

.admin-weighing-start-card {
  display: flex;

  align-items: center;

  gap: 10px;

  margin-top: 15px;

  padding: 13px;

  border:
    1px solid
    #ded3ec;

  border-radius: 11px;

  background:
    #f8f4fc;
}

.admin-weighing-start-icon {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: #8064a9;

  background: #ede6f7;
}

.admin-weighing-start-card > div:nth-child(2) {
  min-width: 0;

  flex: 1;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-weighing-start-card h4 {
  margin: 0;

  color: #5b4a72;

  font-family: var(--font-heading);

  font-size: 14px;
}

.admin-weighing-start-card p {
  margin: 0;

  color: #82768d;

  font-size: 7px;

  line-height: 1.5;
}

.admin-weighing-start-button {
  min-height: 36px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 6px;

  padding:
    0
    10px;

  border: 0;

  border-radius: 8px;

  color: #ffffff;

  background: #8064a9;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;

  white-space: nowrap;
}

.admin-weighing-start-button:disabled {
  opacity: .6;

  cursor: not-allowed;
}


/* =========================================================
   SECTION TITLES
========================================================= */

.admin-weighing-section-title {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  margin-bottom: 12px;
}

.admin-weighing-section-title > div:first-child {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-weighing-section-title h4 {
  margin: 0;

  color: #315265;

  font-family: var(--font-heading);

  font-size: 16px;
}

.admin-weight-status-mark {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  padding:
    5px
    7px;

  border-radius: 7px;

  color: #657e8b;

  background: #f0f4f5;

  font-size: 6px;

  font-weight: 900;
}


/* =========================================================
   WEIGHT ENTRY
========================================================= */

.admin-weight-entry-section {
  margin-top: 17px;

  padding: 16px;

  border:
    1px solid
    #fed7aa;

  border-radius: 13px;

  background: #fbfcfd;
}

.admin-weight-entry-section.disabled {
  opacity: .72;
}

.admin-weight-comparison {
  display: grid;

  grid-template-columns:
    1fr
    35px
    1.2fr;

  gap: 8px;

  align-items: center;
}

.admin-weight-estimated,
.admin-weight-actual {
  min-width: 0;

  padding:
    14px;

  border:
    1px solid
    #e1e8eb;

  border-radius: 11px;

  background: #ffffff;
}

.admin-weight-estimated {
  background: #f6f9fa;
}

.admin-weight-estimated,
.admin-weight-actual {
  display: flex;

  flex-direction: column;

  gap: 5px;
}

.admin-weight-estimated span,
.admin-weight-actual span {
  color: #899aa2;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .05em;
}

.admin-weight-estimated strong {
  color: #526f7e;

  font-family: var(--font-heading);

  font-size: 23px;
}

.admin-weight-estimated small {
  color: #9aa8ae;

  font-size: 7px;
}

.admin-weight-arrow {
  display: flex;

  align-items: center;

  justify-content: center;

  color: #a3b2b8;
}

.admin-weight-input-wrap {
  display: flex;

  align-items: center;

  gap: 7px;
}

.admin-weight-input-wrap input {
  width: 100%;

  height: 43px;

  padding:
    0
    11px;

  border:
    1px solid
    #cbdde4;

  border-radius: 9px;

  outline: 0;

  color: #2f576b;

  background: #ffffff;

  font-family: var(--font-heading);

  font-size: 21px;

  font-weight: 900;
}

.admin-weight-input-wrap input:focus {
  border-color:
    #ea580c;

  box-shadow:
    0 0 0 3px
    rgba(
      40,
      126,
      170,
      .07
    );
}

.admin-weight-input-wrap input:disabled {
  color: #8999a2;

  background:
    #f2f5f6;

  cursor: not-allowed;
}

.admin-weight-input-wrap > span {
  color: #718895;

  font-size: 8px;

  font-weight: 900;
}


/* =========================================================
   DIFFERENCE
========================================================= */

.admin-weight-difference {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  margin-top: 9px;

  padding:
    8px
    10px;

  border-radius: 8px;
}

.admin-weight-difference > div {
  display: flex;

  align-items: center;

  gap: 7px;
}

.admin-weight-difference span {
  color: #778b95;

  font-size: 6px;

  font-weight: 800;
}

.admin-weight-difference strong {
  font-size: 7px;
}

.admin-weight-difference.positive {
  background: #edf8f0;
}

.admin-weight-difference.positive strong {
  color: #166534;
}

.admin-weight-difference.negative {
  background: #fff3ef;
}

.admin-weight-difference.negative strong {
  color: #bd5a4e;
}

.admin-weight-difference.equal {
  background: #eef4f6;
}

.admin-weight-difference.equal strong {
  color: #537181;
}


/* =========================================================
   QUALITY
========================================================= */

.admin-quality-section {
  margin-top: 17px;
}

.admin-quality-options {
  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  gap: 8px;
}

.admin-quality-option {
  display: flex;

  align-items: flex-start;

  gap: 8px;

  padding:
    12px;

  border:
    1px solid
    #dfe7ea;

  border-radius: 10px;

  background: #ffffff;

  cursor: pointer;

  text-align: left;
}

.admin-quality-option:hover:not(:disabled) {
  border-color:
    #b9cfd7;
}

.admin-quality-option.selected {
  border-color:
    #9dc7aa;

  background:
    #f0f8f2;

  box-shadow:
    inset 0 0 0 1px
    rgba(
      33,
      139,
      82,
      .12
    );
}

.admin-quality-option:disabled {
  opacity: .6;

  cursor: not-allowed;
}

.admin-quality-radio {
  width: 18px;
  height: 18px;

  flex: 0 0 18px;

  display: flex;

  align-items: center;
  justify-content: center;

  border:
    1px solid
    #cad9de;

  border-radius: 50%;
}

.admin-quality-option.selected
.admin-quality-radio {
  border-color:
    #166534;
}

.admin-quality-radio span {
  width: 8px;
  height: 8px;

  border-radius: 50%;

  background: #166534;
}

.admin-quality-option > div:last-child {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-quality-option strong {
  color: #3b5b6d;

  font-size: 8px;
}

.admin-quality-option span {
  color: #84969f;

  font-size: 6px;

  line-height: 1.45;
}


/* =========================================================
   NOTES
========================================================= */

.admin-weighing-notes-section {
  margin-top: 17px;
}

.admin-weighing-notes-section textarea {
  width: 100%;

  min-height: 88px;

  resize: vertical;

  padding:
    10px;

  border:
    1px solid
    #dbe5e9;

  border-radius: 9px;

  outline: 0;

  color: #496677;

  background: #ffffff;

  font-family: inherit;

  font-size: 8px;

  line-height: 1.55;
}

.admin-weighing-notes-section textarea:focus {
  border-color:
    #9fbfcf;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .05
    );
}

.admin-weighing-notes-section textarea:disabled {
  color: #8999a1;

  background: #f3f6f7;

  cursor: not-allowed;
}

.admin-weighing-notes-section textarea::placeholder {
  color: #acb8bd;
}


/* =========================================================
   DISABLED NOTE
========================================================= */

.admin-weighing-disabled-note {
  display: flex;

  align-items: center;

  gap: 7px;

  margin-top: 13px;

  padding:
    9px
    10px;

  border-radius: 8px;

  color: #8c7b62;

  background: #fff8ed;

  font-size: 7px;
}

.admin-weighing-disabled-note svg {
  color: #c48a23;
}


/* =========================================================
   FORM ACTIONS
========================================================= */

.admin-weighing-form-actions {
  display: grid;

  grid-template-columns:
    .7fr
    1fr
    1.35fr;

  gap: 7px;

  margin-top: 18px;

  padding-top: 15px;

  border-top:
    1px solid
    #e8edef;
}

.admin-weighing-cancel,
.admin-weighing-save,
.admin-weighing-complete {
  min-height: 43px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 6px;

  border-radius: 9px;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}

.admin-weighing-cancel {
  border:
    1px solid
    #fed7aa;

  color: #6c828e;

  background: #ffffff;
}

.admin-weighing-save {
  border:
    1px solid
    #b9d4df;

  color: #ea580c;

  background: #edf6fa;
}

.admin-weighing-complete {
  border: 0;

  color: #ffffff;

  background: #166534;

  box-shadow:
    0 8px 18px
    rgba(
      33,
      139,
      82,
      .12
    );
}

.admin-weighing-cancel:hover:not(:disabled) {
  border-color:
    #bfd1d8;
}

.admin-weighing-save:hover:not(:disabled) {
  background: #e4f2f8;
}

.admin-weighing-complete:hover:not(:disabled) {
  background: #197342;
}

.admin-weighing-cancel:disabled,
.admin-weighing-save:disabled,
.admin-weighing-complete:disabled {
  opacity: .55;

  cursor: not-allowed;
}


/* =========================================================
   COMPLETED
========================================================= */

.admin-weighing-completed-banner {
  display: flex;

  align-items: flex-start;

  gap: 10px;

  margin-top: 17px;

  padding: 14px;

  border:
    1px solid
    #cfe5d4;

  border-radius: 11px;

  color: #166534;

  background: #eef9f1;
}

.admin-weighing-completed-banner > svg {
  flex: 0 0 auto;
}

.admin-weighing-completed-banner > div {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-weighing-completed-banner strong {
  color: #387253;

  font-size: 9px;
}

.admin-weighing-completed-banner span {
  color: #718a7a;

  font-size: 7px;

  line-height: 1.5;
}


/* =========================================================
   PROCESS NOTE
========================================================= */

.admin-weighing-note {
  display: flex;

  align-items: flex-start;

  gap: 9px;

  margin-top: 14px;

  padding:
    12px
    14px;

  border:
    1px solid
    #fed7aa;

  border-radius: 11px;

  background: #f8fafb;
}

.admin-weighing-note-icon {
  width: 30px;
  height: 30px;

  flex: 0 0 30px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 8px;

  color: #ea580c;

  background: #ffedd5;
}

.admin-weighing-note > div:last-child {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-weighing-note strong {
  color: #496576;

  font-size: 8px;
}

.admin-weighing-note p {
  margin: 0;

  color: #83949d;

  font-size: 7px;

  line-height: 1.55;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1150px) {

  .admin-weighing-workspace {
    grid-template-columns:
      300px
      minmax(0, 1fr);
  }

  .admin-weighing-summary {
    grid-template-columns:
      repeat(2, 1fr);
  }

}


@media (max-width: 950px) {

  .admin-weighing-kpi-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-weighing-workspace {
    grid-template-columns:
      1fr;
  }

  .admin-weighing-booking-list {
    max-height: 320px;
  }

}


@media (max-width: 700px) {

  .admin-weighing-hero {
    flex-direction: column;
  }

  .admin-weighing-hero-actions {
    width: 100%;
  }

  .admin-weighing-live,
  .admin-weighing-refresh {
    flex: 1;
  }

  .admin-weighing-kpi-grid {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-quality-options {
    grid-template-columns:
      1fr;
  }

  .admin-weight-comparison {
    grid-template-columns:
      1fr;
  }

  .admin-weight-arrow {
    transform:
      rotate(90deg);
  }

}


@media (max-width: 520px) {

  .admin-weighing-hero h2 {
    font-size: 30px;
  }

  .admin-weighing-form {
    padding: 16px;
  }

  .admin-weighing-summary {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-weighing-form-actions {
    grid-template-columns:
      1fr;
  }

  .admin-weighing-note {
    align-items: flex-start;
  }

}
/* =========================================================
   ADMIN PAYMENTS
========================================================= */

.admin-payments-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-payments-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 25px;

  margin-bottom: 18px;
}

.admin-payments-hero h2 {
  margin: 6px 0 7px;

  color: #203f52;

  font-family: var(--font-heading);

  font-size: clamp(
    29px,
    3vw,
    41px
  );

  line-height: 1;

  letter-spacing: -.035em;
}

.admin-payments-hero p {
  max-width: 730px;

  margin: 0;

  color: #7c909a;

  font-size: 10px;

  line-height: 1.65;
}

.admin-payments-hero-actions {
  display: flex;

  align-items: center;

  gap: 8px;
}

.admin-payment-live {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  min-height: 32px;

  padding:
    0
    10px;

  border:
    1px solid
    #cfe4d5;

  border-radius: 999px;

  color: #166534;

  background: #eff9f1;

  font-size: 7px;

  font-weight: 900;

  letter-spacing: .07em;
}

.admin-payment-live > span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #166534;

  box-shadow:
    0 0 0 4px
    rgba(
      33,
      139,
      82,
      .08
    );
}

.admin-payment-refresh {
  min-height: 32px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 6px;

  padding:
    0
    10px;

  border:
    1px solid
    #d9e4e8;

  border-radius: 8px;

  color: #5d7887;

  background: #ffffff;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}

.admin-payment-refresh:hover:not(:disabled) {
  color: #ea580c;

  border-color:
    #bad0da;
}

.admin-payment-refresh:disabled {
  opacity: .6;

  cursor: not-allowed;
}


/* =========================================================
   FEEDBACK
========================================================= */

.admin-payment-feedback {
  display: flex;

  align-items: flex-start;

  gap: 9px;

  margin-bottom: 13px;

  padding:
    11px
    13px;

  border-radius: 10px;
}

.admin-payment-feedback.error {
  border:
    1px solid
    #efd0ca;

  color: #b15348;

  background: #fff4f2;
}

.admin-payment-feedback.success {
  border:
    1px solid
    #cfe5d4;

  color: #2f7550;

  background: #eef9f1;
}

.admin-payment-feedback > svg {
  flex: 0 0 auto;

  margin-top: 1px;
}

.admin-payment-feedback > span {
  flex: 1;

  font-size: 8px;

  line-height: 1.5;
}

.admin-payment-feedback button {
  display: flex;

  align-items: center;
  justify-content: center;

  padding: 2px;

  border: 0;

  color: currentColor;

  background: transparent;

  cursor: pointer;
}


/* =========================================================
   KPI
========================================================= */

.admin-payment-kpi-grid {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 10px;

  margin-bottom: 15px;
}

.admin-payment-kpi {
  display: flex;

  align-items: flex-start;

  gap: 10px;

  padding:
    14px;

  border:
    1px solid
    #fed7aa;

  border-radius: 14px;

  background: #ffffff;

  box-shadow:
    0 7px 22px
    rgba(
      30,
      62,
      77,
      .03
    );
}

.admin-payment-kpi-icon {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;
}

.admin-payment-kpi.gold
.admin-payment-kpi-icon {
  color: #be811a;
  background: #fff0ce;
}

.admin-payment-kpi.blue
.admin-payment-kpi-icon {
  color: #ea580c;
  background: #ffedd5;
}

.admin-payment-kpi.green
.admin-payment-kpi-icon {
  color: #166534;
  background: #e4f4e8;
}

.admin-payment-kpi.purple
.admin-payment-kpi-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-payment-kpi-content {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-payment-kpi-content strong {
  overflow: hidden;

  color: #304f61;

  font-family: var(--font-heading);

  font-size: 18px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-payment-kpi-content span {
  color: #768c97;

  font-size: 7px;

  line-height: 1.4;
}

.admin-payment-kpi-content small {
  color: #9aa7ad;

  font-size: 6px;
}


/* =========================================================
   WORKSPACE
========================================================= */

.admin-payments-workspace {
  display: grid;

  grid-template-columns:
    370px
    minmax(0, 1fr);

  gap: 15px;

  align-items: start;
}

.admin-payments-list-panel,
.admin-payments-form-panel {
  min-width: 0;

  border:
    1px solid
    #fed7aa;

  border-radius: 17px;

  background: #ffffff;

  box-shadow:
    0 10px 28px
    rgba(
      30,
      62,
      77,
      .04
    );
}


/* =========================================================
   LIST PANEL
========================================================= */

.admin-payment-panel-heading {
  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 10px;

  padding:
    17px
    17px
    13px;
}

.admin-payment-panel-heading > div {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-payment-panel-heading h3 {
  margin: 0;

  color: #2f5063;

  font-family: var(--font-heading);

  font-size: 17px;
}

.admin-payment-panel-heading > span {
  color: #96a4aa;

  font-size: 7px;
}

.admin-payment-search {
  height: 36px;

  display: flex;

  align-items: center;

  gap: 7px;

  margin:
    0
    17px
    11px;

  padding:
    0
    10px;

  border:
    1px solid
    #fed7aa;

  border-radius: 8px;

  color: #8799a1;

  background: #fff7ed;
}

.admin-payment-search:focus-within {
  border-color:
    #a9c5d0;

  background:
    #ffffff;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .05
    );
}

.admin-payment-search input {
  width: 100%;

  min-width: 0;

  height: 100%;

  padding: 0;

  border: 0;
  outline: 0;

  color: #315165;

  background: transparent;

  font-size: 8px;
}

.admin-payment-search input::placeholder {
  color: #adb9bf;
}

.admin-payment-list {
  display: flex;

  flex-direction: column;

  max-height: 720px;

  overflow-y: auto;
}


/* =========================================================
   PAYMENT ITEM
========================================================= */

.admin-payment-item {
  width: 100%;

  display: grid;

  grid-template-columns:
    37px
    minmax(0, 1fr)
    auto;

  gap: 9px;

  align-items: center;

  min-height: 78px;

  padding:
    10px
    17px;

  border: 0;

  border-top:
    1px solid
    #edf1f3;

  color: #315064;

  background: #ffffff;

  cursor: pointer;

  text-align: left;

  transition:
    background .13s ease,
    box-shadow .13s ease;
}

.admin-payment-item:hover {
  background:
    #fff7ed;
}

.admin-payment-item.selected {
  background:
    #cde7d3;

  box-shadow:
    inset 3px 0 0
    #166534;
}

.admin-payment-token {
  width: 37px;
  height: 37px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: #ea580c;

  background: #ffedd5;
}

.admin-payment-item-main {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-payment-item-main > div {
  display: flex;

  align-items: center;

  gap: 6px;
}

.admin-payment-item-main > div strong {
  color: #31566b;

  font-size: 9px;
}

.admin-payment-item-main > span {
  overflow: hidden;

  color: #5a7280;

  font-size: 8px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-payment-item-main > small {
  color: #899aa2;

  font-size: 6px;
}

.admin-payment-item-amount {
  min-width: 75px;

  display: flex;

  flex-direction: column;

  align-items: flex-end;

  gap: 5px;
}

.admin-payment-item-amount > strong {
  color: #36586a;

  font-family: var(--font-heading);

  font-size: 9px;
}

.admin-payment-status-dot {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #ea580c;
}

.admin-payment-status-dot.gold {
  background: #c38a20;
}

.admin-payment-status-dot.green {
  background: #166534;
}

.admin-payment-status-dot.purple {
  background: #8064a9;
}


/* =========================================================
   STATUS PILL
========================================================= */

.admin-payment-status-pill {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  width: fit-content;

  padding:
    5px
    7px;

  border-radius: 999px;

  font-size: 6px;

  font-weight: 900;

  white-space: nowrap;
}

.admin-payment-status-pill > span {
  width: 5px;
  height: 5px;

  border-radius: 50%;

  background: currentColor;
}

.admin-payment-status-pill.purple {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-payment-status-pill.gold {
  color: #bd7f18;
  background: #fff2d4;
}

.admin-payment-status-pill.green {
  color: #166534;
  background: #eaf7ed;
}


/* =========================================================
   EMPTY / LOADING
========================================================= */

.admin-payment-empty {
  min-height: 260px;

  display: flex;

  flex-direction: column;

  align-items: center;
  justify-content: center;

  gap: 6px;

  padding: 25px;

  color: #9aa8ae;

  text-align: center;
}

.admin-payment-empty strong {
  color: #5e7784;

  font-size: 9px;
}

.admin-payment-empty span {
  max-width: 230px;

  color: #8b9ba2;

  font-size: 7px;

  line-height: 1.5;
}

.admin-payment-loading {
  display: flex;

  flex-direction: column;
}

.admin-payment-skeleton {
  display: grid;

  grid-template-columns:
    37px
    1fr
    55px;

  gap: 9px;

  align-items: center;

  min-height: 78px;

  padding:
    0
    17px;

  border-top:
    1px solid
    #edf1f3;
}

.admin-payment-skeleton > span:first-child {
  width: 37px;
  height: 37px;

  border-radius: 10px;

  background:
    #edf2f4;
}

.admin-payment-skeleton > div {
  display: flex;

  flex-direction: column;

  gap: 6px;
}

.admin-payment-skeleton > div span {
  height: 7px;

  border-radius: 99px;

  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );

  background-size:
    200% 100%;

  animation:
    adminPaymentSkeleton 1.2s infinite;
}

.admin-payment-skeleton > div span:nth-child(1) {
  width: 45%;
}

.admin-payment-skeleton > div span:nth-child(2) {
  width: 70%;
}

.admin-payment-skeleton > div span:nth-child(3) {
  width: 52%;
}

.admin-payment-skeleton > span:last-child {
  width: 50px;
  height: 8px;

  border-radius: 99px;

  background:
    #edf2f4;

  animation:
    adminPaymentSkeleton 1.2s infinite;
}

@keyframes adminPaymentSkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


/* =========================================================
   PAYMENT FORM
========================================================= */

.admin-payment-form {
  padding: 20px;
}

.admin-payment-form-header {
  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 15px;
}

.admin-payment-form-token {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  color: #ea580c;

  font-size: 8px;

  font-weight: 900;
}

.admin-payment-form-header h3 {
  margin: 7px 0 4px;

  color: #2c4f61;

  font-family: var(--font-heading);

  font-size: 23px;
}

.admin-payment-form-header p {
  margin: 0;

  color: #85969e;

  font-size: 7px;
}

.admin-payment-close {
  width: 33px;
  height: 33px;

  display: flex;

  align-items: center;
  justify-content: center;

  border:
    1px solid
    #dde6ea;

  border-radius: 8px;

  color: #728792;

  background: #ffffff;

  cursor: pointer;
}

.admin-payment-close:hover {
  color: #b05046;

  border-color:
    #e2c4bf;
}


/* =========================================================
   STATUS BANNER
========================================================= */

.admin-payment-status-banner {
  display: flex;

  align-items: center;

  gap: 8px;

  margin-top: 17px;

  padding:
    10px
    12px;

  border:
    1px solid
    #e3eaed;

  border-radius: 10px;

  background: #f8fafb;
}

.admin-payment-status-banner > span {
  color: #81939c;

  font-size: 7px;

  line-height: 1.5;
}


/* =========================================================
   SUMMARY
========================================================= */

.admin-payment-summary {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 8px;

  margin-top: 13px;

  padding-bottom: 15px;

  border-bottom:
    1px solid
    #e9eef0;
}

.admin-payment-summary > div {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-payment-summary span {
  color: #8999a1;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .04em;
}

.admin-payment-summary strong {
  overflow: hidden;

  color: #496574;

  font-size: 7px;

  white-space: nowrap;

  text-overflow: ellipsis;
}


/* =========================================================
   SECTION HEADING
========================================================= */

.admin-payment-section-heading {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  margin-bottom: 11px;
}

.admin-payment-section-heading > div:first-child {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-payment-section-heading h4 {
  margin: 0;

  color: #315265;

  font-family: var(--font-heading);

  font-size: 16px;
}

.admin-payment-calculation-badge {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  padding:
    5px
    7px;

  border-radius: 7px;

  color: #5f7785;

  background: #f0f4f5;

  font-size: 6px;

  font-weight: 900;
}


/* =========================================================
   CALCULATION
========================================================= */

.admin-payment-calculation {
  margin-top: 17px;

  padding: 16px;

  border:
    1px solid
    #fed7aa;

  border-radius: 13px;

  background: #fbfcfd;
}

.admin-payment-equation {
  display: grid;

  grid-template-columns:
    1fr
    25px
    1.15fr
    25px
    1.1fr;

  gap: 7px;

  align-items: end;
}

.admin-payment-equation > div:first-child {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 5px;

  padding:
    12px;

  border:
    1px solid
    #e1e8eb;

  border-radius: 10px;

  background: #ffffff;
}

.admin-payment-equation > div:first-child span,
.admin-payment-total-box span {
  color: #899aa1;

  font-size: 6px;

  font-weight: 900;
}

.admin-payment-equation > div:first-child strong {
  color: #526f7e;

  font-family: var(--font-heading);

  font-size: 20px;
}

.admin-payment-equation > div:first-child small {
  margin-left: 3px;

  color: #98a6ac;

  font-size: 6px;
}

.admin-payment-multiply,
.admin-payment-equals {
  display: flex;

  align-items: center;
  justify-content: center;

  min-height: 42px;

  color: #a1afb5;

  font-family: var(--font-heading);

  font-size: 16px;
}

.admin-rate-field {
  min-width: 0;
}

.admin-rate-field label {
  display: block;

  margin-bottom: 5px;

  color: #899aa1;

  font-size: 6px;

  font-weight: 900;
}

.admin-rate-field > div {
  height: 42px;

  display: flex;

  align-items: center;

  gap: 4px;

  padding:
    0
    9px;

  border:
    1px solid
    #cbdde4;

  border-radius: 9px;

  background: #ffffff;
}

.admin-rate-field > div:focus-within {
  border-color:
    #ea580c;

  box-shadow:
    0 0 0 3px
    rgba(
      40,
      126,
      170,
      .06
    );
}

.admin-rate-field > div > span {
  color: #647f8d;

  font-size: 10px;

  font-weight: 900;
}

.admin-rate-field input {
  width: 100%;
  min-width: 0;

  height: 100%;

  padding: 0;

  border: 0;
  outline: 0;

  color: #375a6c;

  background: transparent;

  font-family: var(--font-heading);

  font-size: 17px;

  font-weight: 900;
}

.admin-rate-field input:disabled {
  color: #87989f;
}

.admin-payment-total-box {
  min-width: 0;

  display: flex;

  flex-direction: column;

  justify-content: center;

  gap: 5px;

  min-height: 64px;

  padding:
    10px
    12px;

  border:
    1px solid
    #cfe5d5;

  border-radius: 10px;

  background:
    #eef8f0;
}

.admin-payment-total-box strong {
  overflow: hidden;

  color: #166534;

  font-family: var(--font-heading);

  font-size: 19px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-payment-calculation-note {
  display: flex;

  align-items: center;

  gap: 6px;

  margin-top: 9px;

  padding:
    8px
    9px;

  border-radius: 8px;

  color: #47755a;

  background: #edf8ef;

  font-size: 6px;
}

.admin-payment-calculation-note svg {
  flex: 0 0 auto;
}


/* =========================================================
   PAYMENT METHODS
========================================================= */

.admin-payment-method-section {
  margin-top: 17px;
}

.admin-payment-method-grid {
  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  gap: 8px;
}

.admin-payment-method {
  min-width: 0;

  display: grid;

  grid-template-columns:
    17px
    34px
    1fr;

  gap: 8px;

  align-items: center;

  padding:
    11px;

  border:
    1px solid
    #dfe7ea;

  border-radius: 10px;

  background: #ffffff;

  cursor: pointer;

  text-align: left;
}

.admin-payment-method:hover:not(:disabled) {
  border-color:
    #bcd0d8;
}

.admin-payment-method.selected {
  border-color:
    #a0c8ad;

  background:
    #f0f8f2;
}

.admin-payment-method:disabled {
  opacity: .65;

  cursor: not-allowed;
}

.admin-payment-method-radio {
  width: 16px;
  height: 16px;

  display: flex;

  align-items: center;
  justify-content: center;

  border:
    1px solid
    #cad9de;

  border-radius: 50%;
}

.admin-payment-method.selected
.admin-payment-method-radio {
  border-color:
    #166534;
}

.admin-payment-method-radio span {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background:
    #166534;
}

.admin-payment-method-icon {
  width: 34px;
  height: 34px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: #ea580c;

  background: #ffedd5;
}

.admin-payment-method:nth-child(2)
.admin-payment-method-icon {
  color: #288e91;
  background: #e2f4f3;
}

.admin-payment-method:nth-child(3)
.admin-payment-method-icon {
  color: #c3871d;
  background: #fff0cc;
}

.admin-payment-method > div:last-child {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-payment-method strong {
  color: #3d5c6d;

  font-size: 8px;
}

.admin-payment-method > div:last-child span {
  color: #87979f;

  font-size: 6px;

  line-height: 1.45;
}


/* =========================================================
   REFERENCE
========================================================= */

.admin-payment-reference-section {
  margin-top: 17px;
}

.admin-payment-reference-section > input {
  width: 100%;

  height: 42px;

  padding:
    0
    10px;

  border:
    1px solid
    #d7e3e8;

  border-radius: 9px;

  outline: 0;

  color: #426273;

  background: #ffffff;

  font-size: 8px;
}

.admin-payment-reference-section > input:focus {
  border-color:
    #8fb8c9;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .05
    );
}

.admin-payment-reference-section > input:disabled {
  color: #8999a1;

  background:
    #f3f6f7;
}

.admin-payment-reference-section > input::placeholder {
  color: #abb7bc;
}

.admin-payment-reference-section > small {
  display: block;

  margin-top: 5px;

  color: #919fa5;

  font-size: 6px;

  line-height: 1.5;
}


/* =========================================================
   NOTES
========================================================= */

.admin-payment-notes-section {
  margin-top: 17px;
}

.admin-payment-notes-section textarea {
  width: 100%;

  min-height: 75px;

  resize: vertical;

  padding:
    10px;

  border:
    1px solid
    #dbe5e9;

  border-radius: 9px;

  outline: 0;

  color: #4a6675;

  background: #ffffff;

  font-family: inherit;

  font-size: 8px;

  line-height: 1.55;
}

.admin-payment-notes-section textarea:focus {
  border-color:
    #9dbfcb;

  box-shadow:
    0 0 0 3px
    rgba(
      39,
      124,
      172,
      .05
    );
}

.admin-payment-notes-section textarea:disabled {
  color: #8999a1;

  background:
    #f3f6f7;
}

.admin-payment-notes-section textarea::placeholder {
  color: #aab7bc;
}


/* =========================================================
   VERIFICATION
========================================================= */

.admin-payment-verification {
  display: flex;

  align-items: flex-start;

  gap: 8px;

  margin-top: 15px;

  padding:
    10px
    11px;

  border:
    1px solid
    #dbe7ec;

  border-radius: 9px;

  color: #ea580c;

  background: #f4f9fb;
}

.admin-payment-verification > svg {
  flex: 0 0 auto;

  margin-top: 1px;
}

.admin-payment-verification > div {
  display: flex;

  flex-direction: column;

  gap: 3px;
}

.admin-payment-verification strong {
  color: #496a7b;

  font-size: 8px;
}

.admin-payment-verification span {
  color: #80929b;

  font-size: 6px;

  line-height: 1.5;
}


/* =========================================================
   ACTIONS
========================================================= */

.admin-payment-form-actions {
  display: grid;

  grid-template-columns:
    .7fr
    1fr
    1.35fr;

  gap: 7px;

  margin-top: 18px;

  padding-top: 15px;

  border-top:
    1px solid
    #e8edef;
}

.admin-payment-cancel,
.admin-payment-pending,
.admin-payment-send {
  min-height: 43px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 6px;

  border-radius: 9px;

  cursor: pointer;

  font-size: 7px;

  font-weight: 900;
}

.admin-payment-cancel {
  border:
    1px solid
    #fed7aa;

  color: #6b818d;

  background: #ffffff;
}

.admin-payment-pending {
  border:
    1px solid
    #e1cb8d;

  color: #8b671a;

  background: #fff7df;
}

.admin-payment-send {
  border: 0;

  color: #ffffff;

  background:
    linear-gradient(
      135deg,
      #166534,
      #2b9a5e
    );

  box-shadow:
    0 8px 18px
    rgba(
      33,
      139,
      82,
      .12
    );
}

.admin-payment-cancel:hover:not(:disabled) {
  border-color:
    #bdcfd6;
}

.admin-payment-pending:hover:not(:disabled) {
  background:
    #fff2c7;
}

.admin-payment-send:hover:not(:disabled) {
  background:
    #197342;
}

.admin-payment-cancel:disabled,
.admin-payment-pending:disabled,
.admin-payment-send:disabled {
  opacity: .55;

  cursor: not-allowed;
}


/* =========================================================
   COMPLETED
========================================================= */

.admin-payment-completed {
  display: flex;

  align-items: center;

  gap: 11px;

  margin-top: 17px;

  padding: 15px;

  border:
    1px solid
    #cfe5d4;

  border-radius: 12px;

  background:
    #eef9f1;
}

.admin-payment-completed-icon {
  width: 40px;
  height: 40px;

  flex: 0 0 40px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: #166534;

  background: #dff1e4;
}

.admin-payment-completed > div:last-child {
  display: flex;

  flex-direction: column;

  gap: 4px;
}

.admin-payment-completed strong {
  color: #3d7255;

  font-size: 9px;
}

.admin-payment-completed span {
  color: #718879;

  font-size: 7px;

  line-height: 1.5;
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 1200px) {

  .admin-payment-kpi-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

}


@media (max-width: 1000px) {

  .admin-payments-workspace {
    grid-template-columns:
      1fr;
  }

  .admin-payment-list {
    max-height: 330px;
  }

}


@media (max-width: 800px) {

  .admin-payments-hero {
    flex-direction: column;
  }

  .admin-payments-hero-actions {
    width: 100%;
  }

  .admin-payment-live,
  .admin-payment-refresh {
    flex: 1;
  }

  .admin-payment-summary {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-payment-method-grid {
    grid-template-columns:
      1fr;
  }

  .admin-payment-equation {
    grid-template-columns:
      1fr;
  }

  .admin-payment-multiply,
  .admin-payment-equals {
    min-height: 20px;

    transform:
      rotate(90deg);
  }

}


@media (max-width: 600px) {

  .admin-payment-kpi-grid {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-payment-kpi {
    padding: 10px;
  }

  .admin-payment-kpi-content strong {
    font-size: 15px;
  }

  .admin-payment-form {
    padding: 16px;
  }

  .admin-payment-form-actions {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 460px) {

  .admin-payment-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .admin-payment-summary {
    grid-template-columns:
      1fr;
  }

  .admin-payment-item {
    grid-template-columns:
      35px
      minmax(0, 1fr);
  }

  .admin-payment-item-amount {
    display: none;
  }

}
/* =========================================================
   ADMIN REPORTS
========================================================= */

.admin-reports-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-reports-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-reports-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-reports-hero p {
  max-width: 740px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-reports-hero-actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

.admin-report-data-chip {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #cfe4d5;
  border-radius: 999px;
  color: #166534;
  background: #eff9f1;
  font-size: 7px;
  font-weight: 900;
}

.admin-report-refresh,
.admin-report-export {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-report-refresh {
  border: 1px solid #d9e4e8;
  color: #5d7887;
  background: #ffffff;
}

.admin-report-refresh:hover:not(:disabled) {
  color: #ea580c;
  border-color: #bad0da;
}

.admin-report-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}

.admin-report-export {
  border: 0;
  color: #ffffff;
  background: #ea580c;
}

.admin-report-export:hover {
  background: #226d93;
}


/* =========================================================
   ERROR
========================================================= */

.admin-report-error {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 13px;
  padding: 12px 14px;
  border: 1px solid #efd0ca;
  border-radius: 10px;
  color: #b15348;
  background: #fff4f2;
}

.admin-report-error > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-report-error > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-report-error strong {
  font-size: 8px;
}

.admin-report-error span {
  color: #8e7772;
  font-size: 7px;
  line-height: 1.5;
}

.admin-report-error button {
  margin-left: auto;
  border: 0;
  color: #a64f44;
  background: transparent;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   FILTERS
========================================================= */

.admin-reports-filter-panel {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 14px;
  padding: 9px;
  border: 1px solid #fed7aa;
  border-radius: 12px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-reports-search {
  flex: 1;
  min-width: 190px;
  height: 36px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  color: #84969e;
  background: #fff7ed;
}

.admin-reports-search:focus-within {
  border-color: #a9c5d0;
  background: #ffffff;
  box-shadow:
    0 0 0 3px
    rgba(39, 124, 172, .05);
}

.admin-reports-search input {
  width: 100%;
  min-width: 0;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #315165;
  background: transparent;
  font-size: 8px;
}

.admin-reports-search input::placeholder {
  color: #aebbc1;
}

.admin-report-filter {
  height: 36px;
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 0 8px;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  color: #81939d;
  background: #fff7ed;
}

.admin-report-filter:focus-within {
  border-color: #abc6d0;
  background: #ffffff;
}

.admin-report-filter select {
  min-width: 88px;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #587381;
  background: transparent;
  cursor: pointer;
  font-size: 7px;
  font-weight: 800;
}

.admin-reports-clear {
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 10px;
  border: 0;
  border-radius: 8px;
  color: #a65a50;
  background: #fff3f1;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   KPI
========================================================= */

.admin-report-kpi-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 9px;
  margin-bottom: 15px;
}

.admin-report-kpi {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 13px;
  border: 1px solid #fed7aa;
  border-radius: 14px;
  background: #ffffff;
  box-shadow:
    0 7px 21px
    rgba(30, 62, 77, .03);
}

.admin-report-kpi-icon {
  width: 37px;
  height: 37px;
  flex: 0 0 37px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-report-kpi.blue .admin-report-kpi-icon {
  color: #ea580c;
  background: #ffedd5;
}

.admin-report-kpi.green .admin-report-kpi-icon {
  color: #166534;
  background: #e4f4e8;
}

.admin-report-kpi.gold .admin-report-kpi-icon {
  color: #be811a;
  background: #fff0ce;
}

.admin-report-kpi.orange .admin-report-kpi-icon {
  color: #d2772b;
  background: #ffeadc;
}

.admin-report-kpi.purple .admin-report-kpi-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-report-kpi.teal .admin-report-kpi-icon {
  color: #288e91;
  background: #e2f4f3;
}

.admin-report-kpi > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-report-kpi strong {
  overflow: hidden;
  color: #304f61;
  font-family: var(--font-heading);
  font-size: 17px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-report-kpi strong small {
  color: #8b9aa1;
  font-family: inherit;
  font-size: 7px;
}

.admin-report-kpi span {
  color: #768c97;
  font-size: 6px;
  line-height: 1.4;
}


/* =========================================================
   ANALYTICS GRID
========================================================= */

.admin-reports-analytics-grid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 14px;
}

.admin-report-panel {
  min-width: 0;
  overflow: hidden;
  border: 1px solid #fed7aa;
  border-radius: 16px;
  background: #ffffff;
  box-shadow:
    0 9px 26px
    rgba(30, 62, 77, .035);
}

.admin-report-daily-panel {
  min-height: 260px;
}

.admin-report-panel-header {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 17px 18px 13px;
}

.admin-report-panel-icon {
  width: 37px;
  height: 37px;
  flex: 0 0 37px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-report-panel-icon.blue {
  color: #ea580c;
  background: #ffedd5;
}

.admin-report-panel-icon.green {
  color: #166534;
  background: #e4f4e8;
}

.admin-report-panel-icon.gold {
  color: #be811a;
  background: #fff0ce;
}

.admin-report-panel-icon.purple {
  color: #8064a9;
  background: #eee9f7;
}

.admin-report-panel-icon.teal {
  color: #288e91;
  background: #e2f4f3;
}

.admin-report-panel-header > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-report-panel-header span {
  color: #8a9aa2;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .1em;
}

.admin-report-panel-header h3 {
  margin: 0;
  color: #345467;
  font-family: var(--font-heading);
  font-size: 15px;
}


/* =========================================================
   CROP CHART
========================================================= */

.admin-report-chart-list {
  display: flex;
  flex-direction: column;
  gap: 13px;
  padding:
    2px
    18px
    18px;
}

.admin-horizontal-bar-row {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.admin-horizontal-bar-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.admin-horizontal-bar-heading span {
  color: #607986;
  font-size: 7px;
}

.admin-horizontal-bar-heading strong {
  color: #486474;
  font-size: 7px;
}

.admin-horizontal-bar-track {
  height: 7px;
  overflow: hidden;
  border-radius: 99px;
  background: #edf2f4;
}

.admin-horizontal-bar-track > div {
  height: 100%;
  min-width: 3px;
  border-radius: inherit;
  background:
    linear-gradient(
      90deg,
      #5eaa78,
      #87c092
    );
}


/* =========================================================
   STATUS ANALYSIS
========================================================= */

.admin-status-report-list {
  display: flex;
  flex-direction: column;
  padding:
    0
    18px;
}

.admin-status-report-row {
  min-height: 37px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border-top: 1px solid #edf1f3;
}

.admin-status-report-row:first-child {
  border-top: 0;
}

.admin-status-report-row > div {
  display: flex;
  align-items: center;
  gap: 7px;
}

.admin-status-report-row > div > span:last-child {
  color: #607886;
  font-size: 7px;
}

.admin-status-report-row > strong {
  min-width: 23px;
  text-align: right;
  color: #405e70;
  font-family: var(--font-heading);
  font-size: 10px;
}

.admin-status-report-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.admin-status-report-dot.blue {
  background: #ea580c;
}

.admin-status-report-dot.green {
  background: #166534;
}

.admin-status-report-dot.orange {
  background: #d2772b;
}

.admin-status-report-dot.purple {
  background: #8064a9;
}

.admin-status-report-dot.gold {
  background: #c3871c;
}

.admin-status-total {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin:
    10px
    18px
    17px;
  padding:
    8px
    9px;
  border-radius: 8px;
  background: #f7fafb;
}

.admin-status-total span {
  color: #84969e;
  font-size: 6px;
}

.admin-status-total strong {
  color: #3f6070;
  font-family: var(--font-heading);
  font-size: 10px;
}


/* =========================================================
   PAYMENT ANALYSIS
========================================================= */

.admin-payment-analysis {
  padding:
    0
    18px
    17px;
}

.admin-payment-analysis-row {
  min-height: 37px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  border-top: 1px solid #edf1f3;
}

.admin-payment-analysis-row:first-child {
  border-top: 0;
}

.admin-payment-analysis-row > div {
  display: flex;
  align-items: center;
  gap: 7px;
}

.admin-payment-analysis-row > div > span:last-child {
  color: #687f8c;
  font-size: 7px;
}

.admin-payment-analysis-row strong {
  color: #405e70;
  font-family: var(--font-heading);
  font-size: 9px;
}

.admin-payment-analysis-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.admin-payment-analysis-dot.green {
  background: #166534;
}

.admin-payment-analysis-dot.gold {
  background: #c3871c;
}

.admin-payment-analysis-dot.blue {
  background: #ea580c;
}

.admin-payment-method-heading {
  margin:
    12px
    0
    5px;

  color: #9aa7ad;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.admin-payment-method-row {
  min-height: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid #f0f3f4;
}

.admin-payment-method-row span {
  color: #7b8e97;
  font-size: 6px;
}

.admin-payment-method-row strong {
  color: #516c7a;
  font-size: 7px;
}


/* =========================================================
   DAILY CHART
========================================================= */

.admin-daily-chart {
  min-height: 190px;
  display: flex;
  align-items: flex-end;
  gap: 8px;
  padding:
    8px
    18px
    17px;
}

.admin-daily-column {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.admin-daily-bar-area {
  width: 100%;
  height: 145px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  border-bottom:
    1px solid
    #e3eaed;
}

.admin-daily-bar {
  position: relative;
  width: 55%;
  min-width: 10px;
  max-width: 30px;
  border-radius:
    6px
    6px
    0
    0;
  background:
    linear-gradient(
      180deg,
      #8064a9,
      #a18bc2
    );
}

.admin-daily-bar span {
  position: absolute;

  top: -14px;
  left: 50%;

  transform:
    translateX(-50%);

  color: #6d7f89;

  font-size: 5px;
  font-weight: 900;
}

.admin-daily-column > span {
  overflow: hidden;
  color: #8999a1;
  font-size: 5px;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   EMPTY ANALYTICS
========================================================= */

.admin-report-empty {
  min-height: 150px;

  display: flex;
  flex-direction: column;

  align-items: center;
  justify-content: center;

  gap: 7px;

  padding: 20px;

  color: #99a8ae;

  text-align: center;
}

.admin-report-empty span {
  max-width: 220px;

  font-size: 7px;

  line-height: 1.5;
}


/* =========================================================
   DETAIL TABLE
========================================================= */

.admin-report-record-panel {
  margin-top: 0;
}

.admin-report-record-table {
  width: 100%;
  overflow-x: auto;
}

.admin-report-record-head,
.admin-report-record-row {
  min-width: 860px;

  display: grid;

  grid-template-columns:
    1fr
    1.3fr
    .9fr
    .95fr
    .95fr
    1fr;

  column-gap: 10px;

  align-items: center;

  padding:
    0
    18px;
}

.admin-report-record-head {
  min-height: 34px;

  border-top:
    1px solid
    #edf1f3;

  border-bottom:
    1px solid
    #e7edef;

  color: #99a7ad;

  background: #fff7ed;

  font-size: 6px;

  font-weight: 900;

  letter-spacing: .08em;

  text-transform: uppercase;
}

.admin-report-record-row {
  min-height: 67px;

  border-bottom:
    1px solid
    #edf1f3;
}

.admin-report-record-row:hover {
  background: #fbfcfd;
}

.admin-report-record-row > div {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-report-record-row strong {
  overflow: hidden;

  color: #456273;

  font-size: 7px;

  white-space: nowrap;

  text-overflow: ellipsis;
}

.admin-report-record-row span {
  color: #8c9ba2;

  font-size: 6px;
}

.admin-report-status {
  width: fit-content;

  padding:
    5px
    7px;

  border-radius: 999px;

  font-size: 5px !important;

  font-weight: 900;

  white-space: nowrap;
}

.admin-report-status.blue {
  color: #ea580c;
  background: #e7f3f8;
}

.admin-report-status.green {
  color: #166534;
  background: #eaf7ed;
}

.admin-report-status.orange {
  color: #d1772b;
  background: #fff0e4;
}

.admin-report-status.purple {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-report-status.gold {
  color: #bd7f18;
  background: #fff2d4;
}


/* =========================================================
   TABLE EMPTY / LOADING
========================================================= */

.admin-report-no-records {
  min-height: 260px;

  display: flex;

  align-items: center;
  justify-content: center;

  flex-direction: column;

  gap: 6px;

  padding: 30px;

  color: #9caab0;

  text-align: center;
}

.admin-report-no-records strong {
  color: #5e7784;

  font-size: 9px;
}

.admin-report-no-records span {
  color: #8c9ba2;

  font-size: 7px;

  line-height: 1.5;
}

.admin-report-loading {
  min-width: 860px;
}

.admin-report-skeleton-row {
  min-height: 67px;

  display: grid;

  grid-template-columns:
    repeat(6, 1fr);

  gap: 10px;

  align-items: center;

  padding:
    0
    18px;

  border-bottom:
    1px solid
    #edf1f3;
}

.admin-report-skeleton-row span {
  height: 8px;

  border-radius: 99px;

  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );

  background-size:
    200% 100%;

  animation:
    adminReportSkeleton 1.2s infinite;
}

@keyframes adminReportSkeleton {

  0% {
    background-position:
      200% 0;
  }

  100% {
    background-position:
      -200% 0;
  }

}

.admin-report-table-footer {
  min-height: 42px;

  display: flex;

  align-items: center;

  padding:
    0
    18px;

  color: #93a1a7;

  font-size: 6px;
}


/* =========================================================
   FOOTER
========================================================= */

.admin-reports-footer {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 12px;

  margin-top: 12px;

  padding:
    3px
    2px
    10px;

  color: #8d9ca2;

  font-size: 6px;
}

.admin-reports-footer > div {
  display: inline-flex;

  align-items: center;

  gap: 5px;
}

.admin-reports-footer svg {
  color: #ea580c;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1250px) {

  .admin-report-kpi-grid {
    grid-template-columns:
      repeat(3, 1fr);
  }

}


@media (max-width: 1000px) {

  .admin-reports-hero {
    flex-direction: column;
  }

  .admin-reports-hero-actions {
    width: 100%;
  }

  .admin-report-data-chip,
  .admin-report-refresh,
  .admin-report-export {
    flex: 1;
  }

  .admin-reports-analytics-grid {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 800px) {

  .admin-reports-filter-panel {
    flex-wrap: wrap;
  }

  .admin-reports-search {
    flex-basis: 100%;
  }

  .admin-report-filter {
    flex: 1;
  }

  .admin-report-filter select {
    min-width: 75px;
  }

  .admin-reports-clear {
    flex: 0 0 auto;
  }

}


@media (max-width: 600px) {

  .admin-report-kpi-grid {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-report-kpi {
    padding: 10px;
  }

  .admin-report-kpi-icon {
    width: 32px;
    height: 32px;
    flex-basis: 32px;
  }

  .admin-report-kpi strong {
    font-size: 15px;
  }

  .admin-reports-hero h2 {
    font-size: 30px;
  }

  .admin-reports-hero-actions {
    flex-wrap: wrap;
  }

  .admin-report-data-chip,
  .admin-report-refresh,
  .admin-report-export {
    flex: 1 1 30%;
  }

}


@media (max-width: 450px) {

  .admin-report-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .admin-report-filter {
    flex-basis: 100%;
  }

  .admin-reports-clear {
    width: 100%;
  }

}
/* =========================================================
   ADMIN FARMERS
========================================================= */

.admin-farmers-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-farmers-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-farmers-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-farmers-hero p {
  max-width: 740px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-farmers-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-farmers-live {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #cfe4d5;
  border-radius: 999px;
  color: #166534;
  background: #eff9f1;
  font-size: 7px;
  font-weight: 900;
}

.admin-farmers-refresh {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #5d7887;
  background: #ffffff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-farmers-refresh:hover:not(:disabled) {
  color: #ea580c;
  border-color: #bad0da;
}

.admin-farmers-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}


/* =========================================================
   ERROR
========================================================= */

.admin-farmers-error {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 13px;
  padding: 12px 14px;
  border: 1px solid #efd0ca;
  border-radius: 10px;
  color: #b15348;
  background: #fff4f2;
}

.admin-farmers-error > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-farmers-error > div {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-farmers-error strong {
  font-size: 8px;
}

.admin-farmers-error span {
  color: #8e7772;
  font-size: 7px;
  line-height: 1.5;
}

.admin-farmers-error button {
  border: 0;
  color: #a64f44;
  background: transparent;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   KPI
========================================================= */

.admin-farmer-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-bottom: 15px;
}

.admin-farmer-kpi {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px;
  border: 1px solid #fed7aa;
  border-radius: 14px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-farmer-kpi-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-farmer-kpi.blue
.admin-farmer-kpi-icon {
  color: #ea580c;
  background: #ffedd5;
}

.admin-farmer-kpi.green
.admin-farmer-kpi-icon {
  color: #166534;
  background: #e4f4e8;
}

.admin-farmer-kpi.purple
.admin-farmer-kpi-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-farmer-kpi.gold
.admin-farmer-kpi-icon {
  color: #c3871c;
  background: #fff0ce;
}

.admin-farmer-kpi > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-farmer-kpi strong {
  overflow: hidden;
  color: #304f61;
  font-family: var(--font-heading);
  font-size: 20px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-farmer-kpi strong small {
  color: #8b9aa1;
  font-family: inherit;
  font-size: 7px;
}

.admin-farmer-kpi span {
  color: #7b8f98;
  font-size: 7px;
}


/* =========================================================
   FILTER PANEL
========================================================= */

.admin-farmers-filter-panel {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 14px;
  padding: 9px;
  border: 1px solid #fed7aa;
  border-radius: 12px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-farmers-search {
  flex: 1;
  min-width: 200px;
  height: 36px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  color: #84969e;
  background: #fff7ed;
}

.admin-farmers-search:focus-within {
  border-color: #a9c5d0;
  background: #ffffff;
  box-shadow:
    0 0 0 3px
    rgba(39, 124, 172, .05);
}

.admin-farmers-search input {
  width: 100%;
  min-width: 0;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #315165;
  background: transparent;
  font-size: 8px;
}

.admin-farmers-search input::placeholder {
  color: #adb9bf;
}

.admin-farmers-filter {
  height: 36px;
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 0 8px;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  color: #81939d;
  background: #fff7ed;
}

.admin-farmers-filter:focus-within {
  border-color: #abc6d0;
  background: #ffffff;
}

.admin-farmers-filter select {
  min-width: 95px;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #587381;
  background: transparent;
  cursor: pointer;
  font-size: 7px;
  font-weight: 800;
}

.admin-farmers-clear {
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 10px;
  border: 0;
  border-radius: 8px;
  color: #a65a50;
  background: #fff3f1;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   TABLE PANEL
========================================================= */

.admin-farmers-table-panel {
  overflow: hidden;
  border: 1px solid #fed7aa;
  border-radius: 17px;
  background: #ffffff;
  box-shadow:
    0 10px 28px
    rgba(30, 62, 77, .04);
}

.admin-farmers-table-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  padding: 18px 18px 14px;
}

.admin-farmers-table-header > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-farmers-table-header h3 {
  margin: 0;
  color: #2f5063;
  font-family: var(--font-heading);
  font-size: 18px;
}

.admin-farmers-table-header > span {
  color: #95a3a9;
  font-size: 7px;
}


/* =========================================================
   TABLE
========================================================= */

.admin-farmers-table {
  width: 100%;
  overflow-x: auto;
}

.admin-farmers-table-head,
.admin-farmer-row {
  min-width: 1050px;
  display: grid;

  grid-template-columns:
    1.3fr
    1fr
    1.25fr
    1fr
    .75fr
    .8fr;

  column-gap: 11px;
  align-items: center;
  padding: 0 18px;
}

.admin-farmers-table-head {
  min-height: 34px;
  border-top: 1px solid #edf1f3;
  border-bottom: 1px solid #e7edef;
  color: #99a7ad;
  background: #fff7ed;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.admin-farmer-row {
  min-height: 76px;
  border-bottom: 1px solid #edf1f3;
  transition: background .13s ease;
}

.admin-farmer-row:hover {
  background: #fbfcfd;
}


/* =========================================================
   FARMER CELL
========================================================= */

.admin-farmer-main-cell,
.admin-farmer-contact-cell,
.admin-farmer-location-cell,
.admin-farmer-crop-cell,
.admin-farmer-activity-cell {
  min-width: 0;
  display: flex;
  align-items: center;
}

.admin-farmer-main-cell {
  gap: 9px;
}

.admin-farmer-large-avatar {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: #718795;
  background: #edf2f4;
}

.admin-farmer-main-cell > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-farmer-main-cell strong {
  overflow: hidden;
  color: #3d5a6b;
  font-size: 8px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-farmer-main-cell span {
  overflow: hidden;
  color: #9aa7ad;
  font-size: 6px;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   CONTACT
========================================================= */

.admin-farmer-contact-cell > div {
  display: flex;
  align-items: center;
  gap: 5px;
}

.admin-farmer-contact-cell svg {
  color: #7c97a5;
}

.admin-farmer-contact-cell span {
  color: #587381;
  font-size: 7px;
}


/* =========================================================
   LOCATION
========================================================= */

.admin-farmer-location-cell {
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
}

.admin-farmer-location-cell strong {
  overflow: hidden;
  color: #4c6877;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-farmer-location-cell span {
  overflow: hidden;
  color: #8b9ba2;
  font-size: 6px;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   CROP
========================================================= */

.admin-farmer-crop-cell > div {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.admin-farmer-crop-cell svg {
  color: #166534;
}

.admin-farmer-crop-cell strong {
  color: #496677;
  font-size: 7px;
}


/* =========================================================
   ACTIVITY
========================================================= */

.admin-farmer-activity-cell {
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
}

.admin-farmer-activity-cell strong {
  color: #3c5d6d;
  font-family: var(--font-heading);
  font-size: 13px;
}

.admin-farmer-activity-cell span {
  color: #8999a1;
  font-size: 6px;
}

.admin-farmer-activity-cell small {
  padding: 3px 5px;
  border-radius: 999px;
  color: #ea580c;
  background: #e8f3f8;
  font-size: 5px;
  font-weight: 900;
}


/* =========================================================
   ACTION
========================================================= */

.admin-farmer-view-button {
  min-height: 31px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 8px;
  border: 1px solid #dbe5e9;
  border-radius: 7px;
  color: #567483;
  background: #ffffff;
  cursor: pointer;
  font-size: 6px;
  font-weight: 900;
}

.admin-farmer-view-button:hover {
  color: #ea580c;
  border-color: #b9d1db;
  background: #f8fbfc;
}


/* =========================================================
   EMPTY
========================================================= */

.admin-farmers-empty {
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  padding: 30px;
  color: #99a8ae;
  text-align: center;
}

.admin-farmers-empty strong {
  color: #5e7784;
  font-size: 10px;
}

.admin-farmers-empty span {
  color: #8b9ba2;
  font-size: 7px;
}


/* =========================================================
   LOADING
========================================================= */

.admin-farmer-loading {
  min-width: 1050px;
}

.admin-farmer-skeleton {
  min-height: 76px;
  display: grid;
  grid-template-columns:
    1.3fr
    1fr
    1.25fr
    1fr
    .75fr
    .8fr;
  gap: 11px;
  align-items: center;
  padding: 0 18px;
  border-bottom: 1px solid #edf1f3;
}

.admin-farmer-skeleton > span:first-child {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: #edf2f4;
}

.admin-farmer-skeleton > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.admin-farmer-skeleton > div span {
  height: 7px;
  border-radius: 99px;

  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );

  background-size: 200% 100%;
  animation: adminFarmerSkeleton 1.2s infinite;
}

.admin-farmer-skeleton > div span:first-child {
  width: 55%;
}

.admin-farmer-skeleton > div span:last-child {
  width: 38%;
}

.admin-farmer-skeleton > span:not(:first-child) {
  height: 8px;
  border-radius: 99px;

  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );

  background-size: 200% 100%;
  animation: adminFarmerSkeleton 1.2s infinite;
}

@keyframes adminFarmerSkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


/* =========================================================
   FOOTER
========================================================= */

.admin-farmers-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 11px;
  padding:
    3px
    2px
    10px;
  color: #8d9ca2;
  font-size: 6px;
}


/* =========================================================
   DRAWER OVERLAY
========================================================= */

.admin-farmer-drawer-overlay {
  position: fixed;
  z-index: 100;
  inset: 0;
  background: rgba(24, 51, 64, .28);
}


/* =========================================================
   DRAWER
========================================================= */

.admin-farmer-drawer {
  position: fixed;
  z-index: 110;
  top: 0;
  right: 0;
  bottom: 0;

  width: min(
    520px,
    95vw
  );

  display: flex;
  flex-direction: column;

  background: #ffffff;

  box-shadow:
    -18px 0 50px
    rgba(27, 54, 68, .15);

  animation:
    adminFarmerDrawerIn .2s ease;
}

@keyframes adminFarmerDrawerIn {

  from {
    transform: translateX(20px);
    opacity: 0;
  }

  to {
    transform: translateX(0);
    opacity: 1;
  }

}

.admin-farmer-drawer-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
  padding: 21px;
  border-bottom: 1px solid #e7edef;
}

.admin-farmer-drawer-header > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-farmer-drawer-header h2 {
  margin: 0;
  color: #294c5f;
  font-family: var(--font-heading);
  font-size: 24px;
}

.admin-farmer-drawer-header > div > span:last-child {
  color: #96a4aa;
  font-size: 6px;
}

.admin-farmer-drawer-close {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #fed7aa;
  border-radius: 9px;
  color: #6d8390;
  background: #ffffff;
  cursor: pointer;
}

.admin-farmer-drawer-close:hover {
  color: #b05046;
  border-color: #dfc2bd;
}


/* =========================================================
   DRAWER PROFILE
========================================================= */

.admin-farmer-profile-summary {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 21px;
  border-bottom: 1px solid #edf1f3;
  background: #fff7ed;
}

.admin-farmer-profile-avatar {
  width: 45px;
  height: 45px;
  flex: 0 0 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  color: #ea580c;
  background: #ffedd5;
}

.admin-farmer-profile-summary > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-farmer-profile-summary strong {
  color: #3d5b6b;
  font-size: 10px;
}

.admin-farmer-profile-summary span {
  color: #84979f;
  font-size: 7px;
}


/* =========================================================
   DRAWER DETAILS
========================================================= */

.admin-farmer-profile-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1px;
  margin: 15px 21px 0;
  overflow: hidden;
  border: 1px solid #e5ecef;
  border-radius: 11px;
  background: #e5ecef;
}

.admin-farmer-drawer-field {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px;
  background: #ffffff;
}

.admin-farmer-drawer-field span {
  color: #8c9ba2;
  font-size: 6px;
}

.admin-farmer-drawer-field strong {
  overflow: hidden;
  color: #466474;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   DRAWER STATS
========================================================= */

.admin-farmer-profile-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 12px 21px;
}

.admin-farmer-profile-stats > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 11px;
  border: 1px solid #dfe7ea;
  border-radius: 10px;
  background: #fff7ed;
}

.admin-farmer-profile-stats strong {
  color: #37596b;
  font-family: var(--font-heading);
  font-size: 13px;
}

.admin-farmer-profile-stats span {
  color: #8999a1;
  font-size: 6px;
}


/* =========================================================
   HISTORY
========================================================= */

.admin-farmer-history {
  margin:
    4px
    21px
    18px;
}

.admin-farmer-history-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 9px;
}

.admin-farmer-history-heading > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-farmer-history-heading h3 {
  margin: 0;
  color: #3c5c6d;
  font-family: var(--font-heading);
  font-size: 15px;
}

.admin-farmer-history-heading > span {
  color: #8e9da4;
  font-size: 7px;
}

.admin-farmer-history-row {
  display: grid;
  grid-template-columns:
    58px
    1fr
    auto;
  gap: 8px;
  align-items: center;
  min-height: 54px;
  padding:
    7px
    0;
  border-top: 1px solid #edf1f3;
}

.admin-farmer-history-token {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 26px;
  padding: 0 6px;
  border-radius: 7px;
  color: #ea580c;
  background: #e7f3f8;
  font-size: 6px;
  font-weight: 900;
}

.admin-farmer-history-row > div:nth-child(2),
.admin-farmer-history-row > div:nth-child(3) {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-farmer-history-row strong {
  overflow: hidden;
  color: #496575;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-farmer-history-row span {
  color: #8b9ba2;
  font-size: 6px;
}

.admin-farmer-history-row > div:last-child {
  align-items: flex-end;
}

.admin-farmer-history-empty {
  min-height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  color: #98a6ac;
  text-align: center;
}


/* =========================================================
   DRAWER FOOTER
========================================================= */

.admin-farmer-drawer-footer {
  margin-top: auto;
  min-height: 63px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding:
    11px
    21px;
  border-top: 1px solid #e7edef;
  background: #ffffff;
}

.admin-farmer-drawer-footer button {
  min-height: 35px;
  padding: 0 12px;
  border: 1px solid #dbe5e9;
  border-radius: 8px;
  color: #617985;
  background: #ffffff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-farmer-drawer-footer button:hover {
  color: #ea580c;
  border-color: #b9d0da;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1200px) {

  .admin-farmer-kpi-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

}


@media (max-width: 900px) {

  .admin-farmers-hero {
    flex-direction: column;
  }

  .admin-farmers-actions {
    width: 100%;
  }

  .admin-farmers-live,
  .admin-farmers-refresh {
    flex: 1;
  }

}


@media (max-width: 700px) {

  .admin-farmers-filter-panel {
    flex-wrap: wrap;
  }

  .admin-farmers-search {
    flex-basis: 100%;
  }

  .admin-farmers-filter {
    flex: 1;
  }

  .admin-farmers-clear {
    flex: 0 0 auto;
  }

}


@media (max-width: 560px) {

  .admin-farmer-kpi-grid {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-farmer-kpi {
    padding: 10px;
  }

  .admin-farmer-kpi strong {
    font-size: 16px;
  }

  .admin-farmers-hero h2 {
    font-size: 30px;
  }

  .admin-farmer-profile-grid {
    grid-template-columns: 1fr;
  }

  .admin-farmer-profile-stats {
    grid-template-columns: 1fr;
  }

}


@media (max-width: 420px) {

  .admin-farmer-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .admin-farmers-filter {
    flex-basis: 100%;
  }

  .admin-farmers-clear {
    width: 100%;
  }

}
/* =========================================================
   ADMIN CENTERS
========================================================= */

.admin-centers-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-centers-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-centers-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-centers-hero p {
  max-width: 740px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-centers-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-centers-live {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #cfe4d5;
  border-radius: 999px;
  color: #166534;
  background: #eff9f1;
  font-size: 7px;
  font-weight: 900;
}

.admin-centers-refresh {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #5d7887;
  background: #ffffff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-centers-refresh:hover:not(:disabled) {
  color: #ea580c;
  border-color: #bad0da;
}

.admin-centers-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}


/* =========================================================
   ERROR
========================================================= */

.admin-centers-error {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 13px;
  padding: 12px 14px;
  border: 1px solid #efd0ca;
  border-radius: 10px;
  color: #b15348;
  background: #fff4f2;
}

.admin-centers-error > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-centers-error > div {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-centers-error strong {
  font-size: 8px;
}

.admin-centers-error span {
  color: #8e7772;
  font-size: 7px;
  line-height: 1.5;
}

.admin-centers-error button {
  border: 0;
  color: #a64f44;
  background: transparent;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   KPI
========================================================= */

.admin-center-kpi-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
  margin-bottom: 15px;
}

.admin-center-kpi {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 13px;
  border: 1px solid #fed7aa;
  border-radius: 14px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-center-kpi-icon {
  width: 37px;
  height: 37px;
  flex: 0 0 37px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-center-kpi.blue .admin-center-kpi-icon {
  color: #ea580c;
  background: #ffedd5;
}

.admin-center-kpi.green .admin-center-kpi-icon {
  color: #166534;
  background: #e4f4e8;
}

.admin-center-kpi.purple .admin-center-kpi-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-center-kpi.gold .admin-center-kpi-icon {
  color: #c3871c;
  background: #fff0ce;
}

.admin-center-kpi.teal .admin-center-kpi-icon {
  color: #288e91;
  background: #e2f4f3;
}

.admin-center-kpi > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-center-kpi strong {
  color: #304f61;
  font-family: var(--font-heading);
  font-size: 18px;
}

.admin-center-kpi span {
  color: #7b8f98;
  font-size: 6px;
}


/* =========================================================
   FILTERS
========================================================= */

.admin-centers-filter-panel {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 14px;
  padding: 9px;
  border: 1px solid #fed7aa;
  border-radius: 12px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-centers-search {
  flex: 1;
  min-width: 210px;
  height: 36px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  color: #84969e;
  background: #fff7ed;
}

.admin-centers-search:focus-within {
  border-color: #a9c5d0;
  background: #ffffff;
  box-shadow:
    0 0 0 3px
    rgba(39, 124, 172, .05);
}

.admin-centers-search input {
  width: 100%;
  min-width: 0;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #315165;
  background: transparent;
  font-size: 8px;
}

.admin-centers-search input::placeholder {
  color: #aebbc1;
}

.admin-centers-filter {
  height: 36px;
  display: flex;
  align-items: center;
  padding: 0 9px;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  background: #fff7ed;
}

.admin-centers-filter select {
  height: 100%;
  min-width: 100px;
  padding: 0;
  border: 0;
  outline: 0;
  color: #587381;
  background: transparent;
  cursor: pointer;
  font-size: 7px;
  font-weight: 800;
}

.admin-centers-clear {
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 10px;
  border: 0;
  border-radius: 8px;
  color: #a65a50;
  background: #fff3f1;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   CENTER GRID
========================================================= */

.admin-centers-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 13px;
}

.admin-center-card {
  min-width: 0;
  padding: 16px;
  border: 1px solid #fed7aa;
  border-radius: 16px;
  background: #ffffff;
  box-shadow:
    0 9px 26px
    rgba(30, 62, 77, .035);
  transition:
    transform .15s ease,
    box-shadow .15s ease,
    border-color .15s ease;
}

.admin-center-card:hover {
  transform: translateY(-2px);
  border-color: #cfdee4;
  box-shadow:
    0 14px 30px
    rgba(30, 62, 77, .06);
}

.admin-center-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.admin-center-card-icon {
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  color: #ea580c;
  background: #ffedd5;
}

.admin-center-state {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 7px;
  border-radius: 999px;
  font-size: 6px;
  font-weight: 900;
}

.admin-center-state > span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}

.admin-center-state.active {
  color: #166534;
  background: #eaf7ed;
}

.admin-center-state.active > span {
  background: #166534;
}

.admin-center-state.idle {
  color: #8899a0;
  background: #f0f3f4;
}

.admin-center-state.idle > span {
  background: #9ba9ae;
}

.admin-center-card h3 {
  margin: 13px 0 5px;
  color: #345567;
  font-family: var(--font-heading);
  font-size: 17px;
}

.admin-center-location {
  min-height: 25px;
  display: flex;
  align-items: flex-start;
  gap: 5px;
  margin: 0;
  color: #84969e;
  font-size: 7px;
  line-height: 1.5;
}

.admin-center-location svg {
  flex: 0 0 auto;
  margin-top: 1px;
  color: #89a2ad;
}


/* =========================================================
   CAPACITY
========================================================= */

.admin-center-capacity {
  margin-top: 14px;
  padding: 11px;
  border: 1px solid #e2e9ec;
  border-radius: 10px;
  background: #fff7ed;
}

.admin-center-capacity-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 7px;
}

.admin-center-capacity-heading span {
  color: #82949c;
  font-size: 6px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: .05em;
}

.admin-center-capacity-heading strong {
  color: #486575;
  font-size: 8px;
}

.admin-center-progress {
  height: 7px;
  overflow: hidden;
  border-radius: 99px;
  background: #e7eef0;
}

.admin-center-progress > div {
  height: 100%;
  min-width: 0;
  border-radius: inherit;
  background:
    linear-gradient(
      90deg,
      #5fa778,
      #86bd91
    );
  transition: width .3s ease;
}

.admin-center-utilization {
  display: block;
  margin-top: 5px;
  color: #8c9ba2;
  font-size: 6px;
}


/* =========================================================
   CARD STATS
========================================================= */

.admin-center-card-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin-top: 11px;
}

.admin-center-card-stats > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 8px;
  border-radius: 8px;
  background: #f7fafb;
}

.admin-center-card-stats span {
  overflow: hidden;
  color: #909fa5;
  font-size: 5px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-center-card-stats strong {
  overflow: hidden;
  color: #486676;
  font-size: 8px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-center-view-button {
  width: 100%;
  min-height: 35px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-top: 12px;
  border: 1px solid #dbe5e9;
  border-radius: 8px;
  color: #587483;
  background: #ffffff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-center-view-button:hover {
  color: #ea580c;
  border-color: #b9d1db;
  background: #f7fbfc;
}


/* =========================================================
   EMPTY
========================================================= */

.admin-centers-empty {
  grid-column: 1 / -1;
  min-height: 360px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  padding: 30px;
  border: 1px solid #fed7aa;
  border-radius: 16px;
  color: #99a8ae;
  background: #ffffff;
  text-align: center;
}

.admin-centers-empty strong {
  color: #5e7784;
  font-size: 10px;
}

.admin-centers-empty span {
  color: #8b9ba2;
  font-size: 7px;
}


/* =========================================================
   LOADING
========================================================= */

.admin-center-loading-grid {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 13px;
}

.admin-center-loading-card {
  min-height: 280px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
  border: 1px solid #e0e8eb;
  border-radius: 16px;
  background: #ffffff;
}

.admin-center-loading-card > span:first-child {
  width: 42px;
  height: 42px;
  border-radius: 11px;
  background: #edf2f4;
}

.admin-center-loading-card > div {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.admin-center-loading-card > div span {
  height: 8px;
  border-radius: 99px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation: adminCenterSkeleton 1.2s infinite;
}

.admin-center-loading-card > div span:nth-child(1) {
  width: 65%;
}

.admin-center-loading-card > div span:nth-child(2) {
  width: 90%;
}

.admin-center-loading-card > div span:nth-child(3) {
  width: 45%;
}

.admin-center-loading-card > span:not(:first-child) {
  height: 7px;
  border-radius: 99px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation: adminCenterSkeleton 1.2s infinite;
}

@keyframes adminCenterSkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


/* =========================================================
   FOOTER
========================================================= */

.admin-centers-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 11px;
  padding: 3px 2px 10px;
  color: #8d9ca2;
  font-size: 6px;
}


/* =========================================================
   DRAWER
========================================================= */

.admin-center-drawer-overlay {
  position: fixed;
  z-index: 100;
  inset: 0;
  background: rgba(24, 51, 64, .28);
}

.admin-center-drawer {
  position: fixed;
  z-index: 110;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(500px, 95vw);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: #ffffff;
  box-shadow:
    -18px 0 50px
    rgba(27, 54, 68, .15);
  animation:
    adminCenterDrawerIn .2s ease;
}

@keyframes adminCenterDrawerIn {

  from {
    transform: translateX(20px);
    opacity: 0;
  }

  to {
    transform: translateX(0);
    opacity: 1;
  }

}

.admin-center-drawer-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
  padding: 21px;
  border-bottom: 1px solid #e7edef;
}

.admin-center-drawer-header > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-center-drawer-header h2 {
  margin: 0;
  color: #294c5f;
  font-family: var(--font-heading);
  font-size: 24px;
}

.admin-center-drawer-header > div > span:last-child {
  color: #96a4aa;
  font-size: 6px;
}

.admin-center-drawer-close {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #fed7aa;
  border-radius: 9px;
  color: #6d8390;
  background: #ffffff;
  cursor: pointer;
}

.admin-center-drawer-close:hover {
  color: #b05046;
  border-color: #dfc2bd;
}


/* =========================================================
   DRAWER SUMMARY
========================================================= */

.admin-center-drawer-summary {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 21px;
  border-bottom: 1px solid #edf1f3;
  background: #fff7ed;
}

.admin-center-drawer-icon {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  color: #ea580c;
  background: #ffedd5;
}

.admin-center-drawer-summary > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-center-drawer-summary strong {
  color: #3c5a6b;
  font-size: 10px;
}

.admin-center-drawer-summary span {
  color: #85979f;
  font-size: 7px;
  line-height: 1.45;
}


/* =========================================================
   DRAWER DETAILS
========================================================= */

.admin-center-detail-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1px;
  margin: 15px 21px 0;
  overflow: hidden;
  border: 1px solid #e4ebee;
  border-radius: 11px;
  background: #e4ebee;
}

.admin-center-detail-grid > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px;
  background: #ffffff;
}

.admin-center-detail-grid span {
  color: #8d9ca3;
  font-size: 6px;
}

.admin-center-detail-grid strong {
  color: #476575;
  font-size: 8px;
}


/* =========================================================
   DRAWER SECTIONS
========================================================= */

.admin-center-drawer-section {
  margin: 17px 21px 0;
  padding-bottom: 16px;
  border-bottom: 1px solid #edf1f3;
}

.admin-center-drawer-section-title {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 10px;
  color: #ea580c;
}

.admin-center-drawer-section-title h3 {
  margin: 0;
  color: #466373;
  font-family: var(--font-heading);
  font-size: 14px;
}

.admin-center-no-data {
  padding: 10px;
  border-radius: 8px;
  color: #909fa5;
  background: #f7fafb;
  font-size: 7px;
}

.admin-center-crop-row {
  min-height: 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid #edf1f3;
}

.admin-center-crop-row:first-of-type {
  border-top: 0;
}

.admin-center-crop-row span {
  color: #718792;
  font-size: 7px;
}

.admin-center-crop-row strong {
  min-width: 24px;
  text-align: right;
  color: #466576;
  font-family: var(--font-heading);
  font-size: 9px;
}

.admin-center-booking-row {
  min-height: 49px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  border-top: 1px solid #edf1f3;
}

.admin-center-booking-row:first-of-type {
  border-top: 0;
}

.admin-center-booking-row > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-center-booking-row > div:last-child {
  align-items: flex-end;
}

.admin-center-booking-row strong {
  overflow: hidden;
  color: #516d7b;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-center-booking-row span {
  color: #8c9aa1;
  font-size: 6px;
}


/* =========================================================
   DRAWER FOOTER
========================================================= */

.admin-center-drawer-footer {
  margin-top: auto;
  min-height: 63px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding: 11px 21px;
  border-top: 1px solid #e7edef;
  background: #ffffff;
}

.admin-center-drawer-footer button {
  min-height: 35px;
  padding: 0 12px;
  border: 1px solid #dbe5e9;
  border-radius: 8px;
  color: #617985;
  background: #ffffff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-center-drawer-footer button:hover {
  color: #ea580c;
  border-color: #b9d0da;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1250px) {

  .admin-center-kpi-grid {
    grid-template-columns:
      repeat(3, 1fr);
  }

  .admin-centers-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .admin-center-loading-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

}


@media (max-width: 850px) {

  .admin-centers-hero {
    flex-direction: column;
  }

  .admin-centers-actions {
    width: 100%;
  }

  .admin-centers-live,
  .admin-centers-refresh {
    flex: 1;
  }

  .admin-center-kpi-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-centers-grid {
    grid-template-columns:
      1fr;
  }

  .admin-center-loading-grid {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 650px) {

  .admin-centers-filter-panel {
    flex-wrap: wrap;
  }

  .admin-centers-search {
    flex-basis: 100%;
  }

  .admin-centers-filter {
    flex: 1;
  }

  .admin-centers-clear {
    flex: 0 0 auto;
  }

}


@media (max-width: 500px) {

  .admin-center-kpi-grid {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-center-card {
    padding: 14px;
  }

  .admin-center-detail-grid {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 390px) {

  .admin-center-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .admin-centers-filter {
    flex-basis: 100%;
  }

  .admin-centers-clear {
    width: 100%;
  }

}
/* =========================================================
   ADD / EDIT CENTER MODAL
========================================================= */

.admin-center-form-overlay {
  position: fixed;
  inset: 0;
  z-index: 300;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 24px;

  background:
    rgba(26, 49, 61, .34);

  backdrop-filter:
    blur(4px);
}


/* =========================================================
   MODAL
========================================================= */

.admin-center-form-modal {
  width: min(
    780px,
    96vw
  );

  max-height: 92vh;

  overflow:
    hidden auto;

  border:
    1px solid
    #d8e3e7;

  border-radius:
    18px;

  background:
    #ffffff;

  box-shadow:
    0 28px 80px
    rgba(
      27,
      55,
      68,
      .20
    );

  animation:
    adminCenterModalIn
    .2s ease;
}

@keyframes adminCenterModalIn {

  from {
    opacity: 0;
    transform:
      translateY(12px)
      scale(.985);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }

}


/* =========================================================
   HEADER
========================================================= */

.admin-center-form-header {
  position: sticky;
  top: 0;
  z-index: 2;

  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 18px;

  padding:
    21px
    22px
    18px;

  border-bottom:
    1px solid
    #e5ecef;

  background:
    rgba(
      255,
      255,
      255,
      .97
    );
}

.admin-center-form-header > div {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 5px;
}

.admin-center-form-header h2 {
  margin: 0;

  color:
    #294d60;

  font-family:
    var(--font-heading);

  font-size:
    24px;

  line-height:
    1.1;

  letter-spacing:
    -.025em;
}

.admin-center-form-header p {
  max-width: 590px;

  margin: 0;

  color:
    #84969f;

  font-size:
    7px;

  line-height:
    1.6;
}

.admin-center-form-close {
  width: 36px;
  height: 36px;

  flex: 0 0 36px;

  display: flex;
  align-items: center;
  justify-content: center;

  border:
    1px solid
    #fed7aa;

  border-radius:
    9px;

  color:
    #6e8490;

  background:
    #ffffff;

  cursor:
    pointer;

  transition:
    .15s ease;
}

.admin-center-form-close:hover {
  color:
    #ad5147;

  border-color:
    #dfc7c2;

  background:
    #fff8f7;
}


/* =========================================================
   FORM
========================================================= */

.admin-center-form {
  padding:
    20px
    22px
    23px;
}

.admin-center-form-section {
  margin-bottom:
    20px;

  padding-bottom:
    20px;

  border-bottom:
    1px solid
    #e9eef0;
}

.admin-center-form-section:last-of-type {
  margin-bottom: 0;

  padding-bottom: 2px;

  border-bottom: 0;
}


/* =========================================================
   SECTION TITLE
========================================================= */

.admin-center-form-section-title {
  display: flex;
  align-items: center;

  gap: 7px;

  margin-bottom:
    11px;

  color:
    #ea580c;
}

.admin-center-form-section-title svg {
  width: 16px;
  height: 16px;
}

.admin-center-form-section-title h3 {
  margin: 0;

  color:
    #405f70;

  font-family:
    var(--font-heading);

  font-size:
    14px;

  letter-spacing:
    -.01em;
}


/* =========================================================
   GRID
========================================================= */

.admin-center-form-grid {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 10px;
}

.admin-center-form-grid.three {
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
}


/* =========================================================
   FIELD
========================================================= */

.admin-center-form-field {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 5px;
}

.admin-center-form-field.wide {
  grid-column:
    1 / -1;
}

.admin-center-form-field > span {
  color:
    #7d919b;

  font-size:
    6px;

  font-weight:
    900;

  letter-spacing:
    .05em;

  text-transform:
    uppercase;
}

.admin-center-form-field > span b {
  margin-left:
    2px;

  color:
    #bd5b51;
}


/* =========================================================
   INPUTS
========================================================= */

.admin-center-form-field input {
  width: 100%;

  min-height: 42px;

  padding:
    0
    11px;

  border:
    1px solid
    #d5e1e5;

  border-radius:
    8px;

  outline:
    none;

  color:
    #466473;

  background:
    #ffffff;

  font-family:
    inherit;

  font-size:
    8px;

  transition:
    border-color .15s ease,
    box-shadow .15s ease,
    background .15s ease;
}

.admin-center-form-field input:hover:not(:disabled) {
  border-color:
    #c4d4da;
}

.admin-center-form-field input:focus {
  border-color:
    #8eb7c7;

  background:
    #ffffff;

  box-shadow:
    0 0 0 3px
    rgba(
      40,
      126,
      170,
      .055
    );
}

.admin-center-form-field input:disabled {
  color:
    #97a5aa;

  background:
    #f3f6f7;

  cursor:
    not-allowed;
}

.admin-center-form-field input::placeholder {
  color:
    #acb8bd;
}


/* =========================================================
   NUMBER INPUT
========================================================= */

.admin-center-form-field input[type="number"] {
  appearance:
    textfield;
}

.admin-center-form-field input[type="number"]::-webkit-inner-spin-button,
.admin-center-form-field input[type="number"]::-webkit-outer-spin-button {
  opacity:
    .55;
}


/* =========================================================
   TIME INPUT
========================================================= */

.admin-center-form-field input[type="time"] {
  cursor:
    pointer;
}


/* =========================================================
   ACTIVE TOGGLE
========================================================= */

.admin-center-active-toggle {
  position: relative;

  display: flex;
  align-items: center;

  gap: 11px;

  margin-top:
    13px;

  padding:
    12px;

  border:
    1px solid
    #fed7aa;

  border-radius:
    10px;

  background:
    #fff7ed;

  cursor:
    pointer;

  transition:
    border-color .15s ease,
    background .15s ease;
}

.admin-center-active-toggle:hover {
  border-color:
    #c4d8df;

  background:
    #f7fbfc;
}

.admin-center-active-toggle input {
  position:
    absolute;

  opacity:
    0;

  pointer-events:
    none;
}

.admin-center-toggle-track {
  width: 40px;
  height: 22px;

  flex: 0 0 40px;

  display: flex;
  align-items: center;

  padding:
    3px;

  border-radius:
    999px;

  background:
    #c8d3d8;

  transition:
    background .17s ease;
}

.admin-center-toggle-track > span {
  width: 16px;
  height: 16px;

  border-radius:
    50%;

  background:
    #ffffff;

  box-shadow:
    0 1px 4px
    rgba(
      0,
      0,
      0,
      .14
    );

  transition:
    transform .17s ease;
}

.admin-center-active-toggle input:checked
+ .admin-center-toggle-track {
  background:
    #166534;
}

.admin-center-active-toggle input:checked
+ .admin-center-toggle-track > span {
  transform:
    translateX(18px);
}

.admin-center-active-toggle > div {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 3px;
}

.admin-center-active-toggle strong {
  color:
    #4a6675;

  font-size:
    8px;
}

.admin-center-active-toggle > div > span {
  color:
    #87989f;

  font-size:
    6px;

  line-height:
    1.45;
}


/* =========================================================
   FORM ACTIONS
========================================================= */

.admin-center-form-actions {
  position: sticky;
  bottom: 0;

  display: flex;
  justify-content: flex-end;

  gap: 8px;

  margin:
    20px
    -22px
    -23px;

  padding:
    13px
    22px;

  border-top:
    1px solid
    #e4ebee;

  background:
    rgba(
      255,
      255,
      255,
      .97
    );

  box-shadow:
    0 -5px 18px
    rgba(
      35,
      62,
      75,
      .025
    );
}

.admin-center-form-cancel,
.admin-center-form-save {
  min-height:
    41px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 6px;

  padding:
    0
    13px;

  border-radius:
    8px;

  cursor:
    pointer;

  font-size:
    7px;

  font-weight:
    900;

  transition:
    .15s ease;
}

.admin-center-form-cancel {
  border:
    1px solid
    #d8e3e7;

  color:
    #657c88;

  background:
    #ffffff;
}

.admin-center-form-cancel:hover:not(:disabled) {
  color:
    #486a79;

  border-color:
    #bdcfd6;

  background:
    #fff7ed;
}

.admin-center-form-save {
  min-width:
    135px;

  border:
    0;

  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      #166534,
      #2b9b60
    );

  box-shadow:
    0 7px 17px
    rgba(
      33,
      139,
      82,
      .13
    );
}

.admin-center-form-save:hover:not(:disabled) {
  background:
    linear-gradient(
      135deg,
      #197342,
      #166534
    );

  transform:
    translateY(-1px);

  box-shadow:
    0 9px 20px
    rgba(
      33,
      139,
      82,
      .17
    );
}

.admin-center-form-cancel:disabled,
.admin-center-form-save:disabled {
