/* =========================================================
   ADMIN SETTINGS
========================================================= */

.admin-settings-page {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-settings-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-settings-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-settings-hero p {
  max-width: 760px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-settings-hero-status {
  display: flex;
  align-items: center;
}

.admin-settings-live {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 11px;
  border: 1px solid #cfe1e7;
  border-radius: 999px;
  color: #ea580c;
  background: #edf7fa;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   FEEDBACK
========================================================= */

.admin-settings-error,
.admin-settings-success {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 13px;
  padding: 11px 13px;
  border-radius: 10px;
}

.admin-settings-error {
  border: 1px solid #efd0ca;
  color: #b15348;
  background: #fff4f2;
}

.admin-settings-success {
  border: 1px solid #cfe4d5;
  color: #2d7950;
  background: #eef9f1;
}

.admin-settings-error > svg,
.admin-settings-success > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-settings-error > div {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-settings-error strong {
  font-size: 8px;
}

.admin-settings-error span,
.admin-settings-success span {
  font-size: 7px;
  line-height: 1.5;
}

.admin-settings-error span {
  color: #8e7772;
}

.admin-settings-success span {
  color: #668977;
}

.admin-settings-error button,
.admin-settings-success button {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2px;
  border: 0;
  background: transparent;
  cursor: pointer;
}

.admin-settings-error button {
  color: #ad554a;
}

.admin-settings-success button {
  color: #40815e;
}


/* =========================================================
   SYSTEM STATUS
========================================================= */

.admin-settings-status-card {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
  padding: 15px;
  border: 1px solid #fed7aa;
  border-radius: 15px;
  background: #ffffff;
  box-shadow:
    0 8px 24px
    rgba(30, 62, 77, .035);
}

.admin-settings-status-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  color: #ea580c;
  background: #ffedd5;
}

.admin-settings-status-copy {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-settings-status-copy h3 {
  margin: 0;
  color: #36576a;
  font-family: var(--font-heading);
  font-size: 14px;
}

.admin-settings-status-copy p {
  max-width: 760px;
  margin: 0;
  color: #8798a0;
  font-size: 7px;
  line-height: 1.5;
}

.admin-settings-status-badge {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 8px;
  border-radius: 999px;
  font-size: 6px;
  font-weight: 900;
}

.admin-settings-status-badge > span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}

.admin-settings-status-badge.active {
  color: #166534;
  background: #eaf7ed;
}

.admin-settings-status-badge.active > span {
  background: #166534;
}

.admin-settings-status-badge.paused {
  color: #bb751c;
  background: #fff1d4;
}

.admin-settings-status-badge.paused > span {
  background: #bb751c;
}

.admin-settings-status-badge.warning {
  color: #b8574c;
  background: #fff0ed;
}

.admin-settings-status-badge.warning > span {
  background: #b8574c;
}


/* =========================================================
   MAIN GRID
========================================================= */

.admin-settings-grid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 14px;
}


/* =========================================================
   SECTION
========================================================= */

.admin-settings-section {
  min-width: 0;
  overflow: hidden;
  border: 1px solid #fed7aa;
  border-radius: 16px;
  background: #ffffff;
  box-shadow:
    0 8px 25px
    rgba(30, 62, 77, .035);
}

.admin-settings-section-header {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 17px 18px 13px;
  border-bottom: 1px solid #edf1f3;
}

.admin-settings-section-icon {
  width: 37px;
  height: 37px;
  flex: 0 0 37px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-settings-section-icon.blue {
  color: #ea580c;
  background: #ffedd5;
}

.admin-settings-section-icon.green {
  color: #166534;
  background: #e4f4e8;
}

.admin-settings-section-icon.gold {
  color: #be811a;
  background: #fff0ce;
}

.admin-settings-section-icon.purple {
  color: #8064a9;
  background: #eee9f7;
}

.admin-settings-section-header > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-settings-section-header > div:last-child > span {
  color: #96a4aa;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .08em;
}

.admin-settings-section-header h3 {
  margin: 0;
  color: #3c5c6e;
  font-family: var(--font-heading);
  font-size: 15px;
}

.admin-settings-section-header p {
  margin: 1px 0 0;
  color: #8999a1;
  font-size: 7px;
  line-height: 1.5;
}

.admin-settings-section-body {
  padding: 1px 18px 16px;
}


/* =========================================================
   TOGGLE
========================================================= */

.admin-setting-toggle {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 0;
  cursor: pointer;
}

.admin-setting-toggle.disabled {
  opacity: .5;
  cursor: not-allowed;
}

.admin-setting-toggle input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.admin-setting-toggle-track {
  width: 39px;
  height: 21px;
  flex: 0 0 39px;
  display: flex;
  align-items: center;
  padding: 3px;
  border-radius: 99px;
  background: #c9d4d9;
  transition: background .17s ease;
}

.admin-setting-toggle-track > span {
  width: 15px;
  height: 15px;
  border-radius: 50%;
  background: #ffffff;
  box-shadow:
    0 1px 4px
    rgba(0, 0, 0, .14);
  transition: transform .17s ease;
}

.admin-setting-toggle input:checked
+ .admin-setting-toggle-track {
  background: #166534;
}

.admin-setting-toggle input:checked
+ .admin-setting-toggle-track > span {
  transform: translateX(18px);
}

.admin-setting-toggle > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-setting-toggle strong {
  color: #4a6676;
  font-size: 8px;
}

.admin-setting-toggle > div > span {
  color: #899aa1;
  font-size: 6px;
  line-height: 1.5;
}


/* =========================================================
   DIVIDER
========================================================= */

.admin-settings-divider {
  height: 1px;
  margin: 1px 0;
  background: #edf1f3;
}


/* =========================================================
   NUMBER ROW
========================================================= */

.admin-setting-number-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 11px 0;
}

.admin-setting-number-row > div:first-child {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-setting-number-row strong {
  color: #4a6675;
  font-size: 8px;
}

.admin-setting-number-row > div:first-child span {
  color: #899aa1;
  font-size: 6px;
  line-height: 1.45;
}

.admin-setting-number {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  overflow: hidden;
  min-height: 36px;
  border: 1px solid #d8e3e7;
  border-radius: 8px;
  background: #ffffff;
}

.admin-setting-number:focus-within {
  border-color: #8fb7c6;
  box-shadow:
    0 0 0 3px
    rgba(40, 126, 170, .05);
}

.admin-setting-number input {
  width: 65px;
  height: 34px;
  padding: 0 7px;
  border: 0;
  outline: 0;
  color: #4b6877;
  background: transparent;
  text-align: right;
  font-family: inherit;
  font-size: 8px;
}

.admin-setting-number input[type="number"] {
  appearance: textfield;
}

.admin-setting-number input::-webkit-inner-spin-button,
.admin-setting-number input::-webkit-outer-spin-button {
  opacity: .45;
}

.admin-setting-number > span {
  padding: 0 8px 0 3px;
  color: #96a4aa;
  font-size: 6px;
  font-weight: 900;
}


/* =========================================================
   INFO CARD
========================================================= */

.admin-settings-info-card {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-top: 8px;
  padding: 10px;
  border: 1px solid #e2e9ec;
  border-radius: 9px;
  background: #fff7ed;
}

.admin-settings-info-icon {
  width: 31px;
  height: 31px;
  flex: 0 0 31px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  color: #166534;
  background: #e5f5e9;
}

.admin-settings-info-card > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-settings-info-card strong {
  color: #4a6676;
  font-size: 7px;
}

.admin-settings-info-card span {
  color: #899aa1;
  font-size: 6px;
  line-height: 1.5;
}


/* =========================================================
   LANGUAGE
========================================================= */

.admin-settings-language-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 11px 0;
}

.admin-settings-language-row > div {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-settings-language-row strong {
  color: #4a6675;
  font-size: 8px;
}

.admin-settings-language-row span {
  color: #899aa1;
  font-size: 6px;
  line-height: 1.45;
}

.admin-settings-language-row select {
  min-width: 105px;
  height: 36px;
  padding: 0 9px;
  border: 1px solid #d8e3e7;
  border-radius: 8px;
  outline: 0;
  color: #587381;
  background: #ffffff;
  cursor: pointer;
  font-family: inherit;
  font-size: 7px;
  font-weight: 800;
}

.admin-settings-language-row select:focus {
  border-color: #8fb7c6;
  box-shadow:
    0 0 0 3px
    rgba(40, 126, 170, .05);
}


/* =========================================================
   WARNING
========================================================= */

.admin-settings-warning-card {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 10px;
  padding: 10px;
  border: 1px solid #f0dfb9;
  border-radius: 9px;
  color: #a87a25;
  background: #fffaf0;
}

.admin-settings-warning-card > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-settings-warning-card > div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-settings-warning-card strong {
  color: #92691e;
  font-size: 7px;
}

.admin-settings-warning-card span {
  color: #9a855f;
  font-size: 6px;
  line-height: 1.5;
}


/* =========================================================
   SAVE BAR
========================================================= */

.admin-settings-save-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 14px;
  padding: 13px 15px;
  border: 1px solid #fed7aa;
  border-radius: 14px;
  background: #ffffff;
  box-shadow:
    0 8px 24px
    rgba(30, 62, 77, .035);
}

.admin-settings-save-bar.has-changes {
  border-color: #c8dce4;
  box-shadow:
    0 8px 25px
    rgba(40, 126, 170, .055);
}

.admin-settings-save-bar > div:first-child {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
}

.admin-settings-save-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #166534;
  background: #eaf7ed;
}

.admin-settings-save-bar.has-changes
.admin-settings-save-icon {
  color: #ea580c;
  background: #dcfce7;
}

.admin-settings-save-bar > div:first-child > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-settings-save-bar strong {
  color: #486575;
  font-size: 8px;
}

.admin-settings-save-bar span {
  color: #899aa1;
  font-size: 6px;
  line-height: 1.45;
}

.admin-settings-save-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
}

.admin-settings-discard,
.admin-settings-save,
.admin-settings-reset {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 10px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 6px;
  font-weight: 900;
}

.admin-settings-discard {
  border: 1px solid #dbe5e9;
  color: #697f8a;
  background: #ffffff;
}

.admin-settings-save {
  min-width: 105px;
  border: 0;
  color: #ffffff;
  background: #166534;
}

.admin-settings-reset {
  border: 1px solid #e0d4d1;
  color: #a1594f;
  background: #fff9f8;
}

.admin-settings-discard:hover:not(:disabled) {
  border-color: #becfd6;
  background: #fff7ed;
}

.admin-settings-save:hover:not(:disabled) {
  background: #197342;
}

.admin-settings-reset:hover:not(:disabled) {
  border-color: #d7b9b3;
  background: #fff4f2;
}

.admin-settings-discard:disabled,
.admin-settings-save:disabled,
.admin-settings-reset:disabled {
  opacity: .5;
  cursor: not-allowed;
}


/* =========================================================
   LOADING
========================================================= */

.admin-settings-loading-status {
  height: 75px;
  margin-bottom: 14px;
  border: 1px solid #e0e8eb;
  border-radius: 15px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation:
    adminSettingsSkeleton 1.2s infinite;
}

.admin-settings-loading-grid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.admin-settings-loading-card {
  min-height: 290px;
  padding: 17px;
  border: 1px solid #e0e8eb;
  border-radius: 16px;
  background: #ffffff;
}

.admin-settings-loading-card span {
  display: block;
  height: 8px;
  margin-bottom: 15px;
  border-radius: 99px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation:
    adminSettingsSkeleton 1.2s infinite;
}

.admin-settings-loading-card span:nth-child(1) {
  width: 30%;
  height: 28px;
  border-radius: 8px;
}

.admin-settings-loading-card span:nth-child(2) {
  width: 45%;
}

.admin-settings-loading-card span:nth-child(3) {
  width: 85%;
}

.admin-settings-loading-card span:nth-child(4) {
  width: 70%;
}

.admin-settings-loading-card span:nth-child(5) {
  width: 55%;
}

@keyframes adminSettingsSkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1100px) {

  .admin-settings-grid {
    grid-template-columns: 1fr;
  }

  .admin-settings-loading-grid {
    grid-template-columns: 1fr;
  }

}


@media (max-width: 800px) {

  .admin-settings-hero {
    flex-direction: column;
  }

  .admin-settings-hero-status {
    width: 100%;
  }

  .admin-settings-live {
    width: 100%;
  }

  .admin-settings-status-card {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .admin-settings-status-badge {
    margin-left: 52px;
  }

}


@media (max-width: 600px) {

  .admin-settings-status-card {
    flex-direction: column;
  }

  .admin-settings-status-badge {
    margin-left: 0;
  }

  .admin-settings-save-bar {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-settings-save-actions {
    width: 100%;
    flex-wrap: wrap;
  }

  .admin-settings-discard,
  .admin-settings-save,
  .admin-settings-reset {
    flex: 1;
  }

}


@media (max-width: 480px) {

  .admin-settings-form-grid,
  .admin-settings-grid {
    grid-template-columns: 1fr;
  }

  .admin-setting-number-row,
  .admin-settings-language-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-setting-number,
  .admin-settings-language-row select {
    width: 100%;
  }

  .admin-setting-number input {
    flex: 1;
    width: auto;
  }

  .admin-settings-save-actions {
    flex-direction: column;
  }

  .admin-settings-discard,
  .admin-settings-save,
  .admin-settings-reset {
    width: 100%;
  }

}
