}

.admin-procurement-empty strong {
  color: #5d7582;
  font-size: 9px;
}

.admin-procurement-empty span {
  color: #8b9aa1;
  font-size: 7px;
}

.admin-procurement-loading {
  min-width: 1120px;
}

.admin-procurement-skeleton {
  min-height: 73px;
  display: grid;
  grid-template-columns:
    1fr
    1.25fr
    .9fr
    .95fr
    .8fr
    .8fr
    .95fr
    .9fr;
  gap: 9px;
  align-items: center;
  padding: 0 18px;
  border-bottom: 1px solid #edf1f3;
}

.admin-procurement-skeleton span {
  height: 8px;
  border-radius: 99px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation: adminProcurementSkeleton 1.2s infinite;
}

@keyframes adminProcurementSkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}

.admin-procurement-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 2px;
  color: #8d9ca2;
  font-size: 6px;
}

@media (max-width: 1000px) {

  .admin-procurement-kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }

}

@media (max-width: 700px) {

  .admin-procurement-hero {
    flex-direction: column;
  }

  .admin-procurement-actions {
    width: 100%;
  }

  .admin-procurement-live,
  .admin-procurement-refresh {
    flex: 1;
  }

}

@media (max-width: 520px) {

  .admin-procurement-kpi-grid {
    grid-template-columns: 1fr;
  }

}
/* =========================================================
   ADMIN ACTIVITY LOG
========================================================= */

.admin-activity-page {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-activity-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-activity-hero h2 {
  margin: 6px 0 7px;
