  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-activity-hero p {
  max-width: 780px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-activity-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-activity-live {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #cfe1e7;
  border-radius: 999px;
  color: #ea580c;
  background: #edf7fa;
  font-size: 7px;
  font-weight: 900;
}

.admin-activity-refresh {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #5d7887;
  background: #ffffff;
