  font-size: 7px;
  font-weight: 900;
}

.admin-activity-refresh:hover:not(:disabled) {
  color: #ea580c;
  border-color: #bad0da;
}

.admin-activity-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}


