/* =========================================================
   TIMELINE
========================================================= */

.admin-activity-timeline {
  padding: 5px 18px 18px;
}

.admin-activity-event {
  position: relative;
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  gap: 10px;
}

.admin-activity-event-line {
  position: relative;
  display: flex;
  justify-content: center;
}

.admin-activity-event-line::after {
  content: "";
  position: absolute;
  top: 35px;
  bottom: -8px;
  width: 1px;
  background: #dfe8eb;
}

.admin-activity-event:last-child
.admin-activity-event-line::after {
  display: none;
}

.admin-activity-event-dot {
  position: relative;
  z-index: 1;
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 10px;
  border: 2px solid #ffffff;
  border-radius: 50%;
  box-shadow:
    0 0 0 1px #fed7aa;
}

.admin-activity-event-dot.blue {
  color: #ea580c;
  background: #e7f3f8;
}

.admin-activity-event-dot.orange {
  color: #d1772b;
  background: #fff0e4;
}

.admin-activity-event-dot.purple {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-activity-event-dot.gold {
  color: #be811a;
  background: #fff2d5;
}

.admin-activity-event-dot.green {
  color: #166534;
  background: #eaf7ed;
}

.admin-activity-event-dot.teal {
  color: #288e91;
  background: #e3f5f4;
}


