  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation: adminActivitySkeleton 1.2s infinite;
}

.admin-activity-loading-row > div span:nth-child(1) {
  width: 26%;
}

.admin-activity-loading-row > div span:nth-child(2) {
  width: 55%;
}

.admin-activity-loading-row > div span:nth-child(3) {
  width: 82%;
}

.admin-activity-loading-row > div span:nth-child(4) {
  width: 64%;
}

@keyframes adminActivitySkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


/* =========================================================
   FOOTER
========================================================= */

.admin-activity-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 2px;
  color: #8d9ca2;
  font-size: 6px;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 900px) {

  .admin-activity-kpi-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-activity-filter-panel {
    flex-wrap: wrap;
  }

  .admin-activity-search {
    flex-basis: 100%;
  }

  .admin-activity-filter-select {
    flex: 1;
  }

}


@media (max-width: 650px) {

  .admin-activity-hero {
    flex-direction: column;
  }

  .admin-activity-actions {
    width: 100%;
  }

  .admin-activity-live,
  .admin-activity-refresh {
    flex: 1;
    justify-content: center;
  }

  .admin-activity-event-top {
    align-items: flex-start;
    flex-direction: column;
    gap: 6px;
  }

  .admin-activity-filter-select {
    min-width: 0;
  }

  .admin-activity-filter-select select {
    min-width: 0;
  }

}


@media (max-width: 480px) {

  .admin-activity-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .admin-activity-filter-panel {
    flex-direction: column;
  }

  .admin-activity-search,
  .admin-activity-filter-select,
  .admin-activity-clear {
    width: 100%;
    flex-basis: auto;
  }

  .admin-activity-filter-select select {
    flex: 1;
  }

  .admin-activity-timeline {
    padding-left: 10px;
    padding-right: 10px;
  }

  .admin-activity-event {
    grid-template-columns: 31px minmax(0, 1fr);
    gap: 7px;
  }

  .admin-activity-event-dot {
    width: 27px;
    height: 27px;
    flex-basis: 27px;
  }

  .admin-activity-event-line::after {
    top: 32px;
  }

  .admin-activity-event-body {
    padding: 10px;
  }

  .admin-activity-footer {
    align-items: flex-start;
    flex-direction: column;
  }

}
/* =========================================================
   ADMIN HEADER LANGUAGE
========================================================= */

.admin-header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-language-selector {
  min-height: 34px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 9px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #718792;
  background: #ffffff;
}

.admin-language-selector svg {
  flex: 0 0 auto;
  color: #ea580c;
}

.admin-language-selector select {
  min-width: 84px;
  height: 32px;
  padding: 0;
  border: 0;
  outline: 0;
  color: #587381;
  background: transparent;
  cursor: pointer;
  font-family: inherit;
  font-size: 7px;
  font-weight: 800;
}

.admin-language-selector select:focus {
  outline: none;
}


.admin-header-refresh {
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #5d7887;
  background: #ffffff;
  cursor: pointer;
  font-family: inherit;
  font-size: 7px;
