/* =========================================================
   ADMIN WEIGHING
========================================================= */

.admin-weighing-page {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-weighing-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-weighing-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-weighing-hero p {
  max-width: 760px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-weighing-hero-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-weighing-live {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #cfe4d5;
  border-radius: 999px;
  color: #166534;
  background: #eff9f1;
  font-size: 7px;
  font-weight: 900;
}

.admin-weighing-live > span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #36a866;
  box-shadow: 0 0 0 4px rgba(54, 168, 102, .08);
}

.admin-weighing-refresh {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #5d7887;
  background: #ffffff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-weighing-refresh:hover:not(:disabled) {
  color: #ea580c;
  border-color: #b9d0da;
  background: #fff7ed;
}

.admin-weighing-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}


/* =========================================================
   FEEDBACK
========================================================= */

.admin-weighing-feedback {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 13px;
  padding: 11px 13px;
  border-radius: 10px;
  font-size: 7px;
}

.admin-weighing-feedback.error {
  border: 1px solid #efd0ca;
  color: #b15348;
  background: #fff4f2;
}

.admin-weighing-feedback.success {
  border: 1px solid #cfe4d5;
  color: #2d7950;
  background: #eef9f1;
}

.admin-weighing-feedback span {
  min-width: 0;
  flex: 1;
}

.admin-weighing-feedback button {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2px;
  border: 0;
  color: inherit;
  background: transparent;
  cursor: pointer;
}


/* =========================================================
   KPI
========================================================= */

.admin-weighing-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 14px;
}

.admin-weighing-stat {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 13px;
  border: 1px solid #fed7aa;
  border-radius: 14px;
  background: #ffffff;
  box-shadow: 0 7px 22px rgba(30, 62, 77, .03);
}

.admin-weighing-stat-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-weighing-stat.blue .admin-weighing-stat-icon {
  color: #ea580c;
  background: #ffedd5;
}

.admin-weighing-stat.orange .admin-weighing-stat-icon {
  color: #be811a;
  background: #fff0ce;
}

.admin-weighing-stat.purple .admin-weighing-stat-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-weighing-stat.green .admin-weighing-stat-icon {
  color: #166534;
  background: #e4f4e8;
}

.admin-weighing-stat > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-weighing-stat strong {
  color: #304f61;
  font-family: var(--font-heading);
  font-size: 18px;
}

.admin-weighing-stat span {
  color: #7b8f98;
  font-size: 6px;
}


/* =========================================================
   WORKSPACE
========================================================= */

.admin-weighing-workspace {
  display: grid;
  grid-template-columns: 340px minmax(0, 1fr);
  gap: 12px;
  align-items: stretch;
}


/* =========================================================
   LEFT LIST
========================================================= */

.admin-weighing-list-panel,
.admin-weighing-form-panel {
  min-width: 0;
  overflow: hidden;
  border: 1px solid #fed7aa;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 9px 26px rgba(30, 62, 77, .035);
}

.admin-weighing-list-panel {
  display: flex;
  flex-direction: column;
}

.admin-weighing-panel-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 10px;
  padding: 16px 15px 12px;
  border-bottom: 1px solid #edf1f3;
}

.admin-weighing-panel-heading h3 {
  margin: 4px 0 0;
  color: #3c5b6c;
  font-family: var(--font-heading);
  font-size: 14px;
}

.admin-weighing-panel-heading > span {
  color: #93a2a8;
  font-size: 6px;
  white-space: nowrap;
}

.admin-weighing-search {
  height: 36px;
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 10px;
  padding: 0 10px;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  color: #84969e;
  background: #fff7ed;
}

.admin-weighing-search:focus-within {
  border-color: #a9c5d0;
  background: #ffffff;
  box-shadow: 0 0 0 3px rgba(39, 124, 172, .05);
}

.admin-weighing-search input {
  width: 100%;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: 0;
  color: #315165;
  background: transparent;
  font-size: 8px;
}

.admin-weighing-search input::placeholder {
  color: #adb9bf;
}

.admin-weighing-booking-list {
  min-height: 560px;
  max-height: 760px;
  overflow-y: auto;
  padding: 0 7px 7px;
}

.admin-weighing-booking-list::-webkit-scrollbar {
  width: 5px;
}

.admin-weighing-booking-list::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: #dce5e8;
}

.admin-weighing-booking-item {
  width: 100%;
  min-height: 72px;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 15px;
  align-items: center;
  gap: 8px;
  margin-bottom: 5px;
  padding: 9px;
  border: 1px solid transparent;
  border-radius: 11px;
  color: inherit;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.admin-weighing-booking-item:hover {
  border-color: #e0e9ec;
  background: #fff7ed;
}

.admin-weighing-booking-item.selected {
  border-color: #c8dce4;
  background: #edf7fa;
}

.admin-weighing-token {
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #ea580c;
  background: #ffedd5;
}

.admin-weighing-booking-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-weighing-booking-main > div {
  display: flex;
  align-items: center;
  gap: 6px;
}

.admin-weighing-booking-main strong {
  color: #486676;
  font-size: 8px;
}

.admin-weighing-booking-main > span {
  overflow: hidden;
  color: #58717e;
  font-size: 7px;
  font-weight: 800;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-weighing-booking-main small {
  overflow: hidden;
  color: #99a7ad;
  font-size: 5px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-weighing-booking-item > svg {
  color: #a3afb4;
}

.admin-weighing-status-dot {
  width: 6px;
  height: 6px;
  flex: 0 0 6px;
  border-radius: 50%;
}

.admin-weighing-status-dot.blue {
  background: #ea580c;
}

.admin-weighing-status-dot.orange {
  background: #d1772b;
}

.admin-weighing-status-dot.purple {
  background: #8064a9;
}

.admin-weighing-status-dot.gold {
  background: #be811a;
}

.admin-weighing-status-dot.green {
  background: #166534;
}


/* =========================================================
   EMPTY / LOADING
========================================================= */

.admin-weighing-empty {
  min-height: 330px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  padding: 25px;
  color: #98a7ad;
  text-align: center;
}

.admin-weighing-empty strong {
  color: #5d7582;
  font-size: 9px;
}

.admin-weighing-empty span {
  max-width: 230px;
  color: #8d9ca2;
  font-size: 7px;
  line-height: 1.5;
}

.admin-weighing-loading {
  padding: 5px;
}

.admin-weighing-skeleton {
  min-height: 70px;
  display: grid;
  grid-template-columns: 34px 1fr;
  gap: 9px;
  align-items: center;
  padding: 8px;
  border-bottom: 1px solid #edf1f3;
}

.admin-weighing-skeleton > span {
  width: 34px;
  height: 34px;
  border-radius: 9px;
  background: linear-gradient(
    90deg,
    #edf2f4,
    #f8fafb,
    #edf2f4
  );
  background-size: 200% 100%;
  animation: adminWeighingSkeleton 1.2s infinite;
}

.admin-weighing-skeleton > div {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.admin-weighing-skeleton > div span {
  height: 7px;
  border-radius: 99px;
  background: linear-gradient(
    90deg,
    #edf2f4,
    #f8fafb,
    #edf2f4
  );
  background-size: 200% 100%;
  animation: adminWeighingSkeleton 1.2s infinite;
}

.admin-weighing-skeleton > div span:nth-child(1) {
  width: 35%;
}

.admin-weighing-skeleton > div span:nth-child(2) {
  width: 65%;
}

.admin-weighing-skeleton > div span:nth-child(3) {
  width: 48%;
}

@keyframes adminWeighingSkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


/* =========================================================
   FORM
========================================================= */

.admin-weighing-form {
  padding: 17px;
}

.admin-weighing-form-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
  padding-bottom: 14px;
  border-bottom: 1px solid #edf1f3;
}

.admin-weighing-form-token {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 7px;
  color: #ea580c;
}

.admin-weighing-form-token strong {
  font-size: 8px;
}

.admin-weighing-form-header h3 {
  margin: 0 0 4px;
  color: #334f60;
  font-family: var(--font-heading);
  font-size: 18px;
}

.admin-weighing-form-header p {
  margin: 0;
  color: #899aa1;
  font-size: 7px;
}

.admin-weighing-close {
  width: 29px;
  height: 29px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 29px;
  border: 1px solid #e0e7ea;
  border-radius: 8px;
  color: #87979e;
  background: #ffffff;
  cursor: pointer;
}

.admin-weighing-close:hover {
  color: #526d7a;
  border-color: #cfdcdf;
}


/* =========================================================
   STATUS BANNER
========================================================= */

.admin-weighing-status-banner {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 12px 0;
  padding: 9px 11px;
  border: 1px solid #e2e9ec;
  border-radius: 9px;
  background: #fff7ed;
}

.admin-weighing-status-banner > span {
  min-width: 0;
  color: #7d9098;
  font-size: 6px;
  line-height: 1.45;
}


/* =========================================================
   STATUS PILL
========================================================= */

.admin-weighing-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 7px;
  border-radius: 999px;
  font-size: 5px;
  font-weight: 900;
  white-space: nowrap;
}

.admin-weighing-status-pill > span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}

.admin-weighing-status-pill.blue {
  color: #ea580c;
  background: #e7f3f8;
}

.admin-weighing-status-pill.blue > span {
  background: #ea580c;
}

.admin-weighing-status-pill.orange {
  color: #d1772b;
  background: #fff0e4;
}

.admin-weighing-status-pill.orange > span {
  background: #d1772b;
}

.admin-weighing-status-pill.purple {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-weighing-status-pill.purple > span {
  background: #8064a9;
}

.admin-weighing-status-pill.gold {
  color: #be811a;
  background: #fff2d5;
}

.admin-weighing-status-pill.gold > span {
  background: #be811a;
}

.admin-weighing-status-pill.green {
  color: #166534;
  background: #eaf7ed;
}

.admin-weighing-status-pill.green > span {
  background: #166534;
}


/* =========================================================
   SUMMARY
========================================================= */

.admin-weighing-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 7px;
  margin-bottom: 13px;
}

.admin-weighing-summary > div {
  min-width: 0;
  padding: 9px;
  border: 1px solid #e4eaed;
  border-radius: 9px;
  background: #fbfcfd;
}

.admin-weighing-summary span {
  display: block;
  margin-bottom: 4px;
  color: #9aa8ad;
  font-size: 5px;
  font-weight: 900;
  text-transform: uppercase;
}

.admin-weighing-summary strong {
  display: block;
  overflow: hidden;
  color: #567180;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   START WEIGHING
========================================================= */

.admin-weighing-start-card {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  margin-bottom: 13px;
  padding: 11px;
  border: 1px solid #d9e8ee;
  border-radius: 11px;
  background: #f2f9fb;
}

.admin-weighing-start-icon {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #ea580c;
  background: #e2f0f6;
}

.admin-weighing-start-card > div:nth-child(2) {
  min-width: 0;
}

.admin-weighing-start-card h4 {
  margin: 4px 0 3px;
  color: #486775;
  font-family: var(--font-heading);
  font-size: 10px;
}

.admin-weighing-start-card p {
  margin: 0;
  color: #83959d;
  font-size: 6px;
  line-height: 1.45;
}

.admin-weighing-start-button {
  min-height: 33px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #bdd4de;
  border-radius: 8px;
  color: #ea580c;
  background: #ffffff;
  cursor: pointer;
  font-size: 6px;
  font-weight: 900;
}

.admin-weighing-start-button:hover:not(:disabled) {
  background: #edf7fa;
}

.admin-weighing-start-button:disabled {
  opacity: .6;
  cursor: not-allowed;
}


/* =========================================================
   SECTION TITLES
========================================================= */

.admin-weighing-section-title {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.admin-weighing-section-title h4 {
  margin: 4px 0 0;
  color: #486675;
  font-family: var(--font-heading);
  font-size: 12px;
}

.admin-weight-status-mark {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #8b9ba2;
  font-size: 6px;
  font-weight: 800;
}


/* =========================================================
   WEIGHT ENTRY
========================================================= */

.admin-weight-entry-section {
  margin-bottom: 13px;
  padding: 12px;
  border: 1px solid #dfe8eb;
  border-radius: 11px;
  background: #fbfcfd;
}

.admin-weight-entry-section.disabled {
  opacity: .68;
}

.admin-weight-comparison {
  display: grid;
  grid-template-columns: 1fr 28px 1fr;
  align-items: center;
  gap: 7px;
}

.admin-weight-estimated,
.admin-weight-actual {
  min-width: 0;
  padding: 10px;
  border: 1px solid #e3eaed;
  border-radius: 9px;
  background: #ffffff;
}

.admin-weight-estimated > span,
.admin-weight-actual > span {
  display: block;
  margin-bottom: 5px;
  color: #98a6ab;
  font-size: 5px;
  font-weight: 900;
  text-transform: uppercase;
}

.admin-weight-estimated > strong {
  color: #607985;
  font-family: var(--font-heading);
  font-size: 19px;
}

.admin-weight-estimated > small {
  margin-left: 3px;
  color: #9aa7ac;
  font-size: 6px;
}

.admin-weight-arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  color: #a5b0b5;
}

.admin-weight-input-wrap {
  height: 42px;
  display: flex;
  align-items: center;
  overflow: hidden;
  border: 1px solid #cfe0e5;
  border-radius: 8px;
  background: #ffffff;
}

.admin-weight-input-wrap:focus-within {
  border-color: #9bbdca;
  box-shadow: 0 0 0 3px rgba(39, 124, 172, .05);
}

.admin-weight-input-wrap input {
  width: 100%;
  min-width: 0;
  height: 100%;
  padding: 0 9px;
  border: 0;
  outline: 0;
  color: #436473;
  background: transparent;
  font-family: var(--font-heading);
  font-size: 17px;
}

.admin-weight-input-wrap input[type="number"] {
  appearance: textfield;
}

.admin-weight-input-wrap input::-webkit-inner-spin-button,
.admin-weight-input-wrap input::-webkit-outer-spin-button {
  opacity: .45;
}

.admin-weight-input-wrap > span {
  padding-right: 9px;
  color: #8d9ba1;
  font-size: 6px;
  font-weight: 900;
}

.admin-weight-difference {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 8px;
  padding: 8px 10px;
  border-radius: 8px;
}

.admin-weight-difference > div {
  display: flex;
  align-items: center;
  gap: 7px;
}

.admin-weight-difference span {
  color: #81939b;
  font-size: 6px;
}

.admin-weight-difference strong {
  font-size: 7px;
}

.admin-weight-difference.positive {
  border: 1px solid #cfe7d5;
  background: #eff9f1;
}

.admin-weight-difference.positive strong,
.admin-weight-difference.positive > span {
  color: #238852;
}

.admin-weight-difference.negative {
  border: 1px solid #efd0ca;
  background: #fff4f2;
}

.admin-weight-difference.negative strong,
.admin-weight-difference.negative > span {
  color: #b15348;
}

.admin-weight-difference.equal {
  border: 1px solid #dfe6e8;
  background: #f8fafb;
}

.admin-weight-difference.equal strong {
  color: #607985;
}


/* =========================================================
   QUALITY
========================================================= */

.admin-quality-section {
  margin-bottom: 13px;
}

.admin-quality-options {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
}

.admin-quality-option {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 9px;
  border: 1px solid #e1e8eb;
  border-radius: 9px;
  background: #ffffff;
  text-align: left;
  cursor: pointer;
}

.admin-quality-option:hover:not(:disabled) {
  border-color: #cfdde2;
  background: #fbfcfd;
}

.admin-quality-option.selected {
  border-color: #a9c9d4;
  background: #f1f9fb;
}

.admin-quality-option:disabled {
  opacity: .62;
  cursor: not-allowed;
}

.admin-quality-radio {
  width: 13px;
  height: 13px;
  flex: 0 0 13px;
  margin-top: 1px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #c7d4d9;
  border-radius: 50%;
}

.admin-quality-option.selected .admin-quality-radio {
  border-color: #ea580c;
}

.admin-quality-radio > span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #ea580c;
}

.admin-quality-option > div:last-child {
  min-width: 0;
}

.admin-quality-option strong {
  display: block;
  color: #56717f;
  font-size: 7px;
}

.admin-quality-option span {
  display: block;
  margin-top: 3px;
  color: #97a5ab;
  font-size: 5px;
  line-height: 1.35;
}


/* =========================================================
   NOTES
========================================================= */

.admin-weighing-notes-section {
  margin-bottom: 13px;
}

.admin-weighing-notes-section textarea {
  width: 100%;
  min-height: 75px;
  resize: vertical;
  padding: 9px 10px;
  border: 1px solid #fed7aa;
  border-radius: 9px;
  outline: 0;
  color: #516d7b;
  background: #ffffff;
  font-family: inherit;
  font-size: 7px;
  line-height: 1.5;
}

.admin-weighing-notes-section textarea::placeholder {
  color: #a9b5ba;
}

.admin-weighing-notes-section textarea:focus {
  border-color: #a7c3ce;
  box-shadow: 0 0 0 3px rgba(39, 124, 172, .05);
}


/* =========================================================
   PROCUREMENT CALCULATION
========================================================= */

.admin-procurement-calculation {
  margin-bottom: 13px;
  padding: 12px;
  border: 1px solid #dfe8eb;
  border-radius: 11px;
  background: #fbfcfd;
}

.admin-procurement-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.admin-weighing-field {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.admin-weighing-field > span {
  color: #8d9ca2;
  font-size: 5px;
  font-weight: 900;
  letter-spacing: .05em;
  text-transform: uppercase;
}

.admin-procurement-input {
  min-height: 40px;
  display: flex;
  align-items: center;
  overflow: hidden;
  border: 1px solid #d5e1e5;
  border-radius: 8px;
  background: #ffffff;
}

.admin-procurement-input:focus-within {
  border-color: #9dbfca;
  box-shadow: 0 0 0 3px rgba(39, 124, 172, .05);
}

.admin-procurement-input > span {
  padding-left: 9px;
  color: #7f929c;
  font-size: 8px;
  font-weight: 900;
}

.admin-procurement-input input {
  width: 100%;
  min-width: 0;
  height: 38px;
  padding: 0 7px;
  border: 0;
  outline: 0;
  color: #456474;
  background: transparent;
  font-family: inherit;
  font-size: 8px;
}

.admin-procurement-input small {
  padding-right: 8px;
  color: #97a5aa;
  font-size: 6px;
  white-space: nowrap;
}

.admin-procurement-breakdown {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 9px;
  padding: 9px;
  border: 1px solid #e3eaed;
  border-radius: 9px;
  background: #ffffff;
}

.admin-procurement-breakdown > div {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-procurement-breakdown > span {
  color: #a1afb4;
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 900;
}

.admin-procurement-breakdown div span {
  color: #8e9da3;
  font-size: 5px;
}

.admin-procurement-breakdown div strong {
  overflow: hidden;
  color: #526d7b;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-procurement-total {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 9px;
  padding: 10px 11px;
  border: 1px solid #cfe4d5;
  border-radius: 9px;
  background: #eef9f1;
}

.admin-procurement-total span {
  color: #587764;
  font-size: 6px;
  font-weight: 900;
}

.admin-procurement-total strong {
  color: #166534;
  font-family: var(--font-heading);
  font-size: 17px;
}


/* =========================================================
   DISABLED NOTE
========================================================= */

.admin-weighing-disabled-note {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 12px;
  padding: 8px 10px;
  border: 1px solid #eadfc1;
  border-radius: 8px;
  color: #97763d;
  background: #fffaf0;
  font-size: 6px;
  line-height: 1.45;
}


/* =========================================================
   ACTIONS
========================================================= */

.admin-weighing-form-actions {
  display: flex;
  align-items: stretch;
  justify-content: flex-end;
  gap: 7px;
  padding-top: 12px;
  border-top: 1px solid #edf1f3;
}

.admin-weighing-form-actions button {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 11px;
  border-radius: 8px;
  font-size: 6px;
  font-weight: 900;
  cursor: pointer;
}

.admin-weighing-cancel {
  border: 1px solid #dde5e8;
  color: #748992;
  background: #ffffff;
}

.admin-weighing-cancel:hover:not(:disabled) {
  background: #fff7ed;
}

.admin-weighing-save {
  border: 1px solid #bfd7e0;
  color: #ea580c;
  background: #eef8fb;
}

.admin-weighing-save:hover:not(:disabled) {
  background: #e4f3f8;
}

.admin-weighing-complete {
  min-width: 155px;
  border: 1px solid #b8d8c1;
  color: #166534;
  background: #eaf7ed;
}

.admin-weighing-complete:hover:not(:disabled) {
  background: #e1f3e6;
}

.admin-weighing-form-actions button:disabled {
  opacity: .55;
  cursor: not-allowed;
}


/* =========================================================
   COMPLETED
========================================================= */

.admin-weighing-completed-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  border: 1px solid #cfe4d5;
  border-radius: 10px;
  color: #166534;
  background: #eef9f1;
}

.admin-weighing-completed-banner > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-weighing-completed-banner strong {
  color: #367958;
  font-size: 8px;
}

.admin-weighing-completed-banner span {
  color: #769287;
  font-size: 6px;
}


/* =========================================================
   PAGE NOTE
========================================================= */

.admin-weighing-note {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-top: 13px;
  padding: 12px 13px;
  border: 1px solid #dce7ea;
  border-radius: 11px;
  background: #f8fbfc;
}

.admin-weighing-note-icon {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  color: #ea580c;
  background: #e6f3f8;
}

.admin-weighing-note strong {
  display: block;
  margin-bottom: 3px;
  color: #55717e;
  font-size: 7px;
}

.admin-weighing-note p {
  margin: 0;
  color: #87989f;
  font-size: 6px;
  line-height: 1.55;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1100px) {

  .admin-weighing-workspace {
    grid-template-columns: 300px minmax(0, 1fr);
  }

  .admin-weighing-summary {
    grid-template-columns: repeat(2, 1fr);
  }

}

@media (max-width: 900px) {

  .admin-weighing-kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .admin-weighing-workspace {
    grid-template-columns: 1fr;
  }

  .admin-weighing-booking-list {
    min-height: 300px;
    max-height: 430px;
  }

}

@media (max-width: 650px) {

  .admin-weighing-hero {
    flex-direction: column;
  }

  .admin-weighing-hero-actions {
    width: 100%;
  }

  .admin-weighing-live,
  .admin-weighing-refresh {
    flex: 1;
    justify-content: center;
  }

  .admin-weighing-summary {
    grid-template-columns: 1fr 1fr;
  }

  .admin-weighing-start-card {
    grid-template-columns: 36px minmax(0, 1fr);
  }

  .admin-weighing-start-button {
    grid-column: 1 / -1;
    width: 100%;
  }

  .admin-quality-options {
    grid-template-columns: 1fr;
  }

  .admin-procurement-grid {
    grid-template-columns: 1fr;
  }

  .admin-procurement-breakdown {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-procurement-breakdown > span {
    display: none;
  }

  .admin-weighing-form-actions {
    flex-wrap: wrap;
  }

  .admin-weighing-form-actions button {
    flex: 1 1 calc(50% - 4px);
  }

  .admin-weighing-complete {
    flex-basis: 100% !important;
  }

}

@media (max-width: 480px) {

  .admin-weighing-kpi-grid {
    grid-template-columns: 1fr;
  }

  .admin-weighing-form {
    padding: 12px;
  }

  .admin-weighing-summary {
    grid-template-columns: 1fr;
  }

  .admin-weight-comparison {
    grid-template-columns: 1fr;
  }

  .admin-weight-arrow {
    transform: rotate(90deg);
  }

  .admin-weighing-form-actions {
    flex-direction: column;
  }

  .admin-weighing-form-actions button {
    width: 100%;
    flex-basis: auto !important;
  }

  .admin-weighing-note {
    align-items: flex-start;
  }

}
/* =========================================================
   ADMIN PROCUREMENT CENTERS
========================================================= */

.admin-centers-page {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-centers-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-centers-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-centers-hero p {
  max-width: 780px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-centers-hero-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-centers-refresh,
.admin-centers-add {
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 11px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-centers-refresh {
  border: 1px solid #d9e4e8;
  color: #5d7887;
  background: #ffffff;
}

.admin-centers-refresh:hover:not(:disabled) {
  color: #ea580c;
  border-color: #bad0da;
}

.admin-centers-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}

.admin-centers-add {
  border: 1px solid #b8d8c1;
  color: #166534;
  background: #eaf7ed;
}

.admin-centers-add:hover {
  background: #e2f3e6;
}


/* =========================================================
   FEEDBACK
========================================================= */

.admin-centers-feedback {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 13px;
  padding: 11px 13px;
  border-radius: 10px;
  font-size: 7px;
}

.admin-centers-feedback.error {
  border: 1px solid #efd0ca;
  color: #b15348;
  background: #fff4f2;
}

.admin-centers-feedback.success {
  border: 1px solid #cfe4d5;
  color: #2d7950;
  background: #eef9f1;
}

.admin-centers-feedback > span {
  flex: 1;
  min-width: 0;
}


/* =========================================================
   KPI
========================================================= */

.admin-centers-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 14px;
}

.admin-centers-kpi {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  padding: 13px;
  border: 1px solid #fed7aa;
  border-radius: 14px;
  background: #ffffff;
  box-shadow: 0 7px 22px rgba(30, 62, 77, .03);
}

.admin-centers-kpi-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-centers-kpi.blue .admin-centers-kpi-icon {
  color: #ea580c;
  background: #ffedd5;
}

.admin-centers-kpi.green .admin-centers-kpi-icon {
  color: #166534;
  background: #e4f4e8;
}

.admin-centers-kpi.orange .admin-centers-kpi-icon {
  color: #be811a;
  background: #fff0ce;
}

.admin-centers-kpi.purple .admin-centers-kpi-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-centers-kpi > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.admin-centers-kpi strong {
  color: #304f61;
  font-family: var(--font-heading);
  font-size: 18px;
}

.admin-centers-kpi span {
  color: #7b8f98;
  font-size: 6px;
}


/* =========================================================
   TOOLBAR
========================================================= */

.admin-centers-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
  padding: 9px;
  border: 1px solid #fed7aa;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 7px 22px rgba(30, 62, 77, .03);
}

.admin-centers-search {
  flex: 1;
  min-width: 220px;
  height: 36px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  color: #84969e;
  background: #fff7ed;
}

.admin-centers-search:focus-within {
  border-color: #a9c5d0;
  background: #ffffff;
  box-shadow: 0 0 0 3px rgba(39, 124, 172, .05);
}

.admin-centers-search input {
  width: 100%;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: 0;
  color: #315165;
  background: transparent;
  font-size: 8px;
}

.admin-centers-search input::placeholder {
  color: #adb9bf;
}

.admin-centers-filter {
  height: 36px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 9px;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  background: #fff7ed;
}

.admin-centers-filter svg {
  color: #84969e;
}

.admin-centers-filter select {
  min-width: 110px;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #587381;
  background: transparent;
  cursor: pointer;
  font-family: inherit;
  font-size: 7px;
  font-weight: 800;
}

.admin-centers-clear {
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 9px;
  border: 1px solid #e1d4d1;
  border-radius: 8px;
  color: #a1594f;
  background: #fff9f8;
  cursor: pointer;
  font-size: 6px;
  font-weight: 900;
}


/* =========================================================
   CENTER GRID
========================================================= */

.admin-centers-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 11px;
}

.admin-center-card {
  min-width: 0;
  overflow: hidden;
  border: 1px solid #fed7aa;
  border-radius: 15px;
  background: #ffffff;
  box-shadow: 0 9px 26px rgba(30, 62, 77, .035);
  transition:
    transform .16s ease,
    box-shadow .16s ease,
    border-color .16s ease;
}

.admin-center-card:hover {
  transform: translateY(-1px);
  border-color: #cbdde3;
  box-shadow: 0 12px 30px rgba(30, 62, 77, .06);
}


/* =========================================================
   CARD HEADER
========================================================= */

.admin-center-card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 14px 14px 11px;
  border-bottom: 1px solid #edf1f3;
}

.admin-center-card-header-left {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  gap: 9px;
}

.admin-center-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: #ea580c;
  background: #e6f3f8;
}

.admin-center-card-title {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-center-card-title h3 {
  margin: 0;
  overflow: hidden;
  color: #3f5e6d;
  font-family: var(--font-heading);
  font-size: 12px;
  line-height: 1.15;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-center-card-title span {
  overflow: hidden;
  color: #94a2a7;
  font-size: 6px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-center-status {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 7px;
  border-radius: 999px;
  font-size: 5px;
  font-weight: 900;
}

.admin-center-status > span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}

.admin-center-status.active {
  color: #166534;
  background: #eaf7ed;
}

.admin-center-status.active > span {
  background: #166534;
}

.admin-center-status.inactive {
  color: #a1594f;
  background: #fff0ed;
}

.admin-center-status.inactive > span {
  background: #a1594f;
}


/* =========================================================
   CARD BODY
========================================================= */

.admin-center-card-body {
  padding: 12px 14px;
}

.admin-center-location {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  margin-bottom: 11px;
  color: #7c9099;
}

.admin-center-location svg {
  flex: 0 0 auto;
  margin-top: 1px;
  color: #ea580c;
}

.admin-center-location > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.admin-center-location strong {
  overflow: hidden;
  color: #5b7480;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-center-location span {
  overflow: hidden;
  color: #94a2a7;
  font-size: 6px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-center-info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin-bottom: 11px;
}

.admin-center-info-item {
  min-width: 0;
  padding: 8px;
  border: 1px solid #e5ebee;
  border-radius: 8px;
  background: #fbfcfd;
}

.admin-center-info-item span {
  display: block;
  margin-bottom: 4px;
  color: #9ba8ad;
  font-size: 5px;
  font-weight: 900;
  text-transform: uppercase;
}

.admin-center-info-item strong {
  overflow: hidden;
  color: #58727f;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   CAPACITY
========================================================= */

.admin-center-capacity {
  margin-bottom: 11px;
}

.admin-center-capacity-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 5px;
}

.admin-center-capacity-header span {
  color: #8c9ca3;
  font-size: 6px;
}

.admin-center-capacity-header strong {
  color: #58717d;
  font-size: 6px;
}

.admin-center-capacity-bar {
  height: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: #edf2f4;
}

.admin-center-capacity-bar > span {
  display: block;
  height: 100%;
  max-width: 100%;
  border-radius: inherit;
  background: #6da88a;
}

.admin-center-capacity-note {
  margin-top: 4px;
  color: #9ba8ad;
  font-size: 5px;
}


/* =========================================================
   SCHEDULE
========================================================= */

.admin-center-schedule {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin-bottom: 11px;
}

.admin-center-schedule-item {
  padding: 8px;
  border: 1px solid #e5ebee;
  border-radius: 8px;
  background: #ffffff;
}

.admin-center-schedule-item span {
  display: block;
  margin-bottom: 4px;
  color: #9ba8ad;
  font-size: 5px;
  text-transform: uppercase;
}

.admin-center-schedule-item strong {
  color: #58727f;
  font-size: 7px;
}


/* =========================================================
   CONTACT
========================================================= */

.admin-center-contact {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 0;
  border-top: 1px dashed #e2e9ec;
  color: #718892;
  font-size: 6px;
}

.admin-center-contact svg {
  color: #ea580c;
}

.admin-center-contact a {
  overflow: hidden;
  color: inherit;
  text-decoration: none;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-center-contact a:hover {
  color: #ea580c;
}


/* =========================================================
   CARD FOOTER
========================================================= */

.admin-center-card-footer {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 10px 14px;
  border-top: 1px solid #edf1f3;
  background: #fbfcfd;
}

.admin-center-card-footer button,
.admin-center-card-footer a {
  flex: 1;
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border-radius: 7px;
  font-size: 6px;
  font-weight: 900;
  text-decoration: none;
}

.admin-center-view-button {
  border: 1px solid #d8e3e7;
  color: #5e7885;
  background: #ffffff;
  cursor: pointer;
}

.admin-center-view-button:hover {
  background: #f4f8f9;
}

.admin-center-manage-link {
  border: 1px solid #c7dce4;
  color: #ea580c;
  background: #edf7fa;
}

.admin-center-manage-link:hover {
  background: #e4f3f7;
}


/* =========================================================
   EMPTY
========================================================= */

.admin-centers-empty {
  grid-column: 1 / -1;
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  padding: 30px;
  border: 1px solid #fed7aa;
  border-radius: 15px;
  color: #96a5ab;
  background: #ffffff;
  text-align: center;
}

.admin-centers-empty strong {
  color: #5d7582;
  font-size: 10px;
}

.admin-centers-empty span {
  max-width: 360px;
  color: #8b9aa1;
  font-size: 7px;
  line-height: 1.5;
}


/* =========================================================
   LOADING
========================================================= */

.admin-centers-loading {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 11px;
}

.admin-center-skeleton-card {
  min-height: 290px;
  overflow: hidden;
  border: 1px solid #e0e8eb;
  border-radius: 15px;
  background: #ffffff;
}

.admin-center-skeleton-line {
  height: 8px;
  margin: 12px 14px;
  border-radius: 99px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation: adminCentersSkeleton 1.2s infinite;
}

.admin-center-skeleton-line.large {
  width: 45%;
  height: 12px;
}

.admin-center-skeleton-line.medium {
  width: 62%;
}

.admin-center-skeleton-line.small {
  width: 32%;
}

.admin-center-skeleton-box {
  height: 48px;
  margin: 12px 14px;
  border-radius: 9px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation: adminCentersSkeleton 1.2s infinite;
}

@keyframes adminCentersSkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1100px) {

  .admin-centers-grid,
  .admin-centers-loading {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

}

@media (max-width: 800px) {

  .admin-centers-hero {
    flex-direction: column;
  }

  .admin-centers-hero-actions {
    width: 100%;
  }

  .admin-centers-refresh,
  .admin-centers-add {
    flex: 1;
  }

  .admin-centers-kpi-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .admin-centers-toolbar {
    flex-wrap: wrap;
  }

  .admin-centers-search {
    flex-basis: 100%;
  }

  .admin-centers-filter {
    flex: 1;
  }

}

@media (max-width: 600px) {

  .admin-centers-grid,
  .admin-centers-loading {
    grid-template-columns: 1fr;
  }

  .admin-centers-kpi-grid {
    grid-template-columns: 1fr;
  }

  .admin-centers-filter {
    width: 100%;
  }

}

@media (max-width: 450px) {

  .admin-centers-hero-actions {
    flex-direction: column;
  }

  .admin-centers-refresh,
  .admin-centers-add {
    width: 100%;
  }

  .admin-center-info-grid,
  .admin-center-schedule {
    grid-template-columns: 1fr;
  }

}
/* =========================================================
   FARMER TOKEN - HISTORY / MONTH / COMPLETION
========================================================= */

.token-payment-card,
.token-history-card,
.token-month-card {
  margin-top: 14px;
  padding: 17px;
  border: 1px solid #fed7aa;
  border-radius: 15px;
  background: #ffffff;
  box-shadow: 0 9px 26px rgba(30, 62, 77, .03);
}

.token-payment-grid,
.token-payment-summary,
.token-month-summary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-top: 13px;
}

.token-payment-item,
.token-monthly-stat {
  padding: 10px;
  border: 1px solid #e2e9ec;
  border-radius: 9px;
  background: #fbfcfd;
}

.token-payment-item span,
.token-monthly-stat span {
  display: block;
  margin-bottom: 4px;
  color: #96a5aa;
  font-size: 5px;
  font-weight: 900;
  text-transform: uppercase;
}

.token-payment-item strong,
.token-monthly-stat strong {
  display: block;
  overflow: hidden;
  color: #506c79;
  font-size: 9px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.token-payment-pending-message {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 9px;
  padding: 9px 10px;
  border: 1px solid #eadfc1;
  border-radius: 8px;
  color: #987941;
  background: #fffaf0;
  font-size: 6px;
}

.token-payment-history-list {
  margin-top: 11px;
}

.token-payment-history-row {
  display: grid;
  grid-template-columns: 80px minmax(0, 1fr) 110px 20px;
  align-items: center;
  gap: 10px;
  padding: 11px 0;
  border-bottom: 1px solid #edf1f3;
}

.token-payment-history-row:last-child {
  border-bottom: 0;
}

.token-history-date,
.token-history-crop,
.token-history-amount {
  min-width: 0;
}

.token-history-date {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.token-history-date strong {
  color: #58727f;
  font-size: 7px;
}

.token-history-date span {
  color: #9aa7ac;
  font-size: 5px;
}

.token-history-crop {
  display: flex;
  align-items: center;
  gap: 7px;
}

.token-history-crop > svg {
  flex: 0 0 auto;
  color: #6a9d7d;
}

.token-history-crop div {
  min-width: 0;
}

.token-history-crop strong,
.token-history-crop span {
  display: block;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.token-history-crop strong {
  color: #58727f;
  font-size: 7px;
}

.token-history-crop span {
  margin-top: 2px;
  color: #9aa7ac;
  font-size: 5px;
}

.token-history-amount {
  text-align: right;
}

.token-history-amount strong,
.token-history-amount span {
  display: block;
}

.token-history-amount strong {
  color: #317b51;
  font-size: 8px;
}

.token-history-amount span {
  overflow: hidden;
  margin-top: 2px;
  color: #98a5aa;
  font-size: 5px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.token-history-check {
  color: #2f965a;
}

.token-history-count {
  flex: 0 0 auto;
  padding: 5px 8px;
  border-radius: 999px;
  color: #ea580c;
  background: #edf7fa;
  font-size: 5px;
  font-weight: 900;
}

.token-history-loading,
.token-history-empty {
  min-height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  margin-top: 9px;
  color: #92a2a8;
  text-align: center;
  font-size: 6px;
}

.token-history-empty strong {
  color: #617985;
  font-size: 8px;
}

.token-history-empty span {
  max-width: 350px;
  line-height: 1.5;
}

.token-month-summary {
  grid-template-columns: repeat(3, 1fr);
}

.token-crop-breakdown {
  margin-top: 11px;
}

.token-crop-row {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 105px 15px;
  align-items: center;
  gap: 8px;
  padding: 9px 0;
  border-bottom: 1px solid #edf1f3;
}

.token-crop-row:last-child {
  border-bottom: 0;
}

.token-crop-icon {
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #5c9270;
  background: #edf7f0;
}

.token-crop-main {
  min-width: 0;
}

.token-crop-main strong,
.token-crop-main span {
  display: block;
}

.token-crop-main strong {
  color: #55717d;
  font-size: 7px;
}

.token-crop-main span {
  margin-top: 3px;
  color: #99a7ac;
  font-size: 5px;
}

.token-crop-quantity {
  text-align: right;
}

.token-crop-quantity strong,
.token-crop-quantity span {
  display: block;
}

.token-crop-quantity strong {
  color: #56717e;
  font-size: 7px;
}

.token-crop-quantity span {
  margin-top: 3px;
  color: #328052;
  font-size: 6px;
}

.token-crop-row > svg {
  color: #a2afb4;
}

.token-completion-actions {
  display: flex;
  gap: 7px;
  margin-top: 11px;
}

.token-completion-home,
.token-completion-book {
  min-height: 35px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 11px;
  border-radius: 8px;
  font-size: 6px;
  font-weight: 900;
  text-decoration: none;
}

.token-completion-home {
  border: 1px solid #dce5e8;
  color: #6a808b;
  background: #ffffff;
}

.token-completion-book {
  border: 1px solid #b8d8c1;
  color: #166534;
  background: #eaf7ed;
}

.token-payment-issue-success {
  min-height: 170px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  text-align: center;
  color: #2f8754;
}

.token-payment-issue-success strong {
  color: #426b52;
  font-size: 9px;
}

.token-payment-issue-success span {
  max-width: 350px;
  color: #83958c;
  font-size: 6px;
  line-height: 1.5;
}

.token-payment-issue-label {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-top: 11px;
}

.token-payment-issue-label > span {
  color: #82949c;
  font-size: 6px;
  font-weight: 900;
}

.token-payment-issue-label select,
.token-payment-issue-label textarea {
  width: 100%;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  outline: 0;
  color: #58717e;
  background: #fbfcfd;
  font-family: inherit;
  font-size: 7px;
}

.token-payment-issue-label select {
  min-height: 36px;
  padding: 0 8px;
}

.token-payment-issue-label textarea {
  resize: vertical;
  padding: 9px;
  line-height: 1.5;
}

.token-payment-issue-label select:focus,
.token-payment-issue-label textarea:focus {
  border-color: #a9c5d0;
  background: #ffffff;
}

@media (max-width: 700px) {

  .token-payment-grid,
  .token-payment-summary,
  .token-month-summary {
    grid-template-columns: 1fr;
  }

  .token-payment-history-row {
    grid-template-columns: 65px minmax(0, 1fr);
  }

  .token-history-amount {
    grid-column: 2;
    text-align: left;
  }

  .token-history-check {
    grid-column: 2;
  }

  .token-crop-row {
    grid-template-columns: 34px minmax(0, 1fr);
  }

  .token-crop-quantity {
    grid-column: 2;
    text-align: left;
  }

  .token-crop-row > svg {
    display: none;
  }

  .token-completion-actions {
    flex-direction: column;
  }

  .token-completion-home,
  .token-completion-book {
    width: 100%;
  }

}
/* =========================================================
   FARMER HOME - DASHBOARD
========================================================= */

.farmer-home-page {
  min-height: 100vh;
  background: #f7faf9;
}

.farmer-home-container {
  width: min(1320px, calc(100% - 32px));
  margin: 0 auto;
  padding: 28px 0 45px;
}


/* =========================================================
   WELCOME
========================================================= */

.farmer-welcome {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 20px;
}

.farmer-welcome h1 {
  margin: 6px 0 7px;
  color: #24495c;
  font-family: var(--font-heading);
  font-size: clamp(28px, 3vw, 40px);
  line-height: 1.02;
  letter-spacing: -.035em;
}

.farmer-welcome p {
  max-width: 680px;
  margin: 0;
  color: #82959e;
  font-size: 11px;
  line-height: 1.65;
}

.farmer-profile {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 220px;
  padding: 9px 10px;
  border: 1px solid #dfe8e9;
  border-radius: 13px;
  background: #ffffff;
  box-shadow: 0 8px 24px rgba(35, 73, 92, .035);
}

.farmer-avatar {
  width: 39px;
  height: 39px;
  flex: 0 0 39px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  color: #ffffff;
  background: #5f8f72;
  font-size: 10px;
  font-weight: 900;
}

.farmer-profile > div:nth-child(2) {
  min-width: 0;
  flex: 1;
}

.farmer-profile strong {
  display: block;
  overflow: hidden;
  color: #4e6b78;
  font-size: 8px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.farmer-profile span {
  display: block;
  margin-top: 3px;
  color: #99a8ad;
  font-size: 5px;
}

.farmer-refresh-button {
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #dce6e9;
  border-radius: 8px;
  color: #6e8893;
  background: #ffffff;
  cursor: pointer;
}

.farmer-refresh-button:hover:not(:disabled) {
  color: #2e7da4;
  border-color: #bfd4dd;
}

.farmer-refresh-button:disabled {
  opacity: .6;
  cursor: not-allowed;
}


/* =========================================================
   CURRENT / NEXT BOOKING
========================================================= */

.next-booking-card {
  position: relative;
  overflow: hidden;
  margin-bottom: 14px;
  padding: 19px;
  border: 1px solid #cddfe5;
  border-radius: 18px;
  background:
    linear-gradient(
      135deg,
      #f1f9fb 0%,
      #ffffff 58%,
      #f7fbfa 100%
    );
  box-shadow: 0 12px 34px rgba(36, 73, 92, .055);
}

.next-booking-card::after {
  content: "";
  position: absolute;
  right: -50px;
  top: -50px;
  width: 150px;
  height: 150px;
  border-radius: 50%;
  background: rgba(112, 168, 140, .06);
  pointer-events: none;
}

.next-booking-card.payment-complete {
  border-color: #cfe3d5;
  background:
    linear-gradient(
      135deg,
      #f0faf3 0%,
      #ffffff 58%,
      #f7fbf8 100%
    );
}

.booking-card-top,
.booking-token-row,
.booking-action-row,
.booking-main-details,
.booking-status-message,
.home-payment-complete-strip {
  display: flex;
}

.booking-card-top {
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
}

.card-eyebrow {
  display: inline-block;
  color: #8aa0a8;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .08em;
}

.booking-token-row {
  align-items: center;
  gap: 8px;
  margin-top: 7px;
}

.home-token {
  display: inline-flex;
  align-items: center;
  min-height: 31px;
  padding: 0 10px;
  border-radius: 8px;
  color: #2b6f91;
  background: #e6f3f8;
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 900;
}

.booking-confirmed-icon {
  width: 45px;
  height: 45px;
  flex: 0 0 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #d9e9ed;
  border-radius: 12px;
  color: #2c80a8;
  background: #ffffff;
}

.payment-complete .booking-confirmed-icon {
  color: #248653;
  border-color: #d6e8da;
}

.booking-status-message {
  align-items: flex-start;
  gap: 9px;
  margin-top: 13px;
  padding: 10px;
  border: 1px solid #e1eaed;
  border-radius: 10px;
  background: rgba(255,255,255,.82);
}

.status-message-icon {
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  color: #2c9a61;
  background: #e6f6eb;
}

.booking-status-message > div:last-child {
  min-width: 0;
}

.booking-status-message strong {
  display: block;
  color: #536f7b;
  font-size: 8px;
}

.booking-status-message span {
  display: block;
  margin-top: 3px;
  color: #86979e;
  font-size: 6px;
  line-height: 1.5;
}

.booking-main-details {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: 10px;
}

.home-detail {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
  padding: 10px;
  border: 1px solid #e0e8eb;
  border-radius: 10px;
  background: #ffffff;
}

.home-detail-icon {
  width: 33px;
  height: 33px;
  flex: 0 0 33px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #2e80a8;
  background: #e7f4f8;
}

.home-detail > div:last-child {
  min-width: 0;
}

.home-detail span,
.home-detail strong,
.home-detail small {
  display: block;
}

.home-detail span {
  color: #99a7ac;
  font-size: 5px;
  font-weight: 900;
  text-transform: uppercase;
}

.home-detail strong {
  overflow: hidden;
  margin-top: 3px;
  color: #58727e;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.home-detail small {
  margin-top: 3px;
  color: #91a0a6;
  font-size: 5px;
}

.booking-action-row {
  align-items: center;
  gap: 7px;
  margin-top: 12px;
}

.home-primary-action,
.home-secondary-action {
  min-height: 35px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 12px;
  border-radius: 8px;
  text-decoration: none;
  font-size: 6px;
  font-weight: 900;
}

.home-primary-action {
  border: 1px solid #b8d7c2;
  color: #218a52;
  background: #eaf7ed;
}

.home-primary-action:hover {
  background: #e1f3e6;
}

.home-secondary-action {
  border: 1px solid #d7e2e6;
  color: #627b86;
  background: #ffffff;
}

.home-secondary-action:hover {
  background: #f8fafb;
}

.home-payment-complete-strip {
  align-items: center;
  gap: 8px;
  margin-top: 10px;
}

.home-payment-complete-strip > div {
  min-width: 0;
  flex: 1;
  padding: 9px 10px;
  border: 1px solid #d7e7db;
  border-radius: 9px;
  background: #ffffff;
}

.home-payment-complete-strip span,
.home-payment-complete-strip strong {
  display: block;
}

.home-payment-complete-strip span {
  color: #97a59b;
  font-size: 5px;
  font-weight: 900;
}

.home-payment-complete-strip strong {
  margin-top: 3px;
  overflow: hidden;
  color: #35714f;
  font-size: 8px;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   QUICK ACTIONS
========================================================= */

.farmer-home-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 14px;
}

.home-feature-card {
  min-width: 0;
  min-height: 165px;
  display: block;
  padding: 15px;
  border: 1px solid #dfe8eb;
  border-radius: 15px;
  background: #ffffff;
  color: inherit;
  text-decoration: none;
  box-shadow: 0 8px 25px rgba(35, 73, 92, .028);
  transition:
    transform .16s ease,
    box-shadow .16s ease;
}

.home-feature-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 29px rgba(35, 73, 92, .055);
}

.feature-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.feature-card-top > svg {
  color: #a8b4b8;
}

.feature-icon {
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.booking-feature .feature-icon {
  color: #2f819f;
  background: #e6f4f7;
}

.status-feature .feature-icon {
  color: #7967a0;
  background: #efeafa;
}

.help-feature .feature-icon {
  color: #b17b2c;
  background: #fff2d9;
}

.home-feature-card h2 {
  margin: 14px 0 6px;
  color: #486572;
  font-family: var(--font-heading);
  font-size: 12px;
}

.home-feature-card p {
  margin: 0;
  color: #8a9aa1;
  font-size: 7px;
  line-height: 1.55;
}


/* =========================================================
   GENERIC SECTION
========================================================= */

.home-dashboard-section,
.home-month-summary-card,
.home-center-card,
.home-arrival-check-card,
.farmer-progress-card {
  margin-bottom: 14px;
  padding: 17px;
  border: 1px solid #dfe8eb;
  border-radius: 15px;
  background: #ffffff;
  box-shadow: 0 8px 25px rgba(35, 73, 92, .028);
}

.home-section-heading,
.farmer-progress-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.home-section-heading > svg,
.farmer-progress-heading > svg {
  color: #88a0aa;
}

.home-section-heading h2,
.farmer-progress-heading h2 {
  margin: 4px 0 4px;
  color: #486572;
  font-family: var(--font-heading);
  font-size: 16px;
}

.home-section-heading p,
.farmer-progress-heading p {
  margin: 0;
  color: #91a0a6;
  font-size: 6px;
  line-height: 1.5;
}


/* =========================================================
   MONTH SUMMARY
========================================================= */

.home-month-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-top: 12px;
}

.home-month-stat {
  min-width: 0;
  padding: 11px;
  border: 1px solid #e1e9ec;
  border-radius: 10px;
  background: #fbfcfd;
}

.home-month-stat span {
  display: block;
  margin-bottom: 5px;
  color: #96a4a9;
  font-size: 5px;
  font-weight: 900;
  text-transform: uppercase;
}

.home-month-stat strong {
  display: block;
  overflow: hidden;
  color: #536f7c;
  font-family: var(--font-heading);
  font-size: 17px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.home-month-stat.green {
  border-color: #d6e8da;
  background: #f5fbf6;
}

.home-month-stat.green strong {
  color: #2c7b50;
}

.home-month-stat.blue strong {
  color: #2c7497;
}

.home-month-stat.orange strong {
  color: #ae7731;
}

.home-crop-summary-list {
  margin-top: 10px;
}

.home-crop-summary-row {
  display: grid;
  grid-template-columns: 33px minmax(0, 1fr) 100px;
  align-items: center;
  gap: 8px;
  padding: 9px 0;
  border-bottom: 1px solid #edf1f3;
}

.home-crop-summary-row:last-child {
  border-bottom: 0;
}

.home-crop-summary-icon {
  width: 33px;
  height: 33px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #609274;
  background: #edf7f0;
}

.home-crop-summary-row > div:nth-child(2) {
  min-width: 0;
}

.home-crop-summary-row > div:nth-child(2) strong,
.home-crop-summary-row > div:nth-child(2) span,
.home-crop-summary-row > div:nth-child(3) strong,
.home-crop-summary-row > div:nth-child(3) span {
  display: block;
}

.home-crop-summary-row > div:nth-child(2) strong {
  color: #57717d;
  font-size: 7px;
}

.home-crop-summary-row > div:nth-child(2) span {
  margin-top: 3px;
  color: #9aa7ac;
  font-size: 5px;
}

.home-crop-summary-row > div:nth-child(3) {
  text-align: right;
}

.home-crop-summary-row > div:nth-child(3) strong {
  color: #56717c;
  font-size: 7px;
}

.home-crop-summary-row > div:nth-child(3) span {
  margin-top: 3px;
  color: #328052;
  font-size: 6px;
}

.home-inline-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 9px;
  color: #2e7ca2;
  font-size: 6px;
  font-weight: 900;
  text-decoration: none;
}

.home-inline-link:hover {
  text-decoration: underline;
}


/* =========================================================
   UPCOMING
========================================================= */

.home-upcoming-list,
.home-payment-list,
.home-recent-list {
  margin-top: 10px;
}

.home-upcoming-row,
.home-payment-row,
.home-recent-row {
  display: grid;
  align-items: center;
  gap: 9px;
  padding: 9px 0;
  border-bottom: 1px solid #edf1f3;
  color: inherit;
  text-decoration: none;
}

.home-upcoming-row {
  grid-template-columns: 45px minmax(0, 1fr) 110px 15px;
}

.home-payment-row {
  grid-template-columns: 31px minmax(0, 1fr) 100px 15px;
}

.home-recent-row {
  grid-template-columns: 46px minmax(0, 1fr) auto 15px;
}

.home-upcoming-row:last-child,
.home-payment-row:last-child,
.home-recent-row:last-child {
  border-bottom: 0;
}

.home-upcoming-row:hover,
.home-payment-row:hover,
.home-recent-row:hover {
  background: #fbfcfd;
}

.home-upcoming-token,
.home-recent-token {
  min-height: 27px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 7px;
  color: #2b7396;
  background: #eaf5f8;
  font-size: 7px;
  font-weight: 900;
}

.home-upcoming-main,
.home-payment-main,
.home-recent-main {
  min-width: 0;
}

.home-upcoming-main strong,
.home-upcoming-main span,
.home-payment-main strong,
.home-payment-main span,
.home-recent-main strong,
.home-recent-main span {
  display: block;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.home-upcoming-main strong,
.home-payment-main strong,
.home-recent-main strong {
  color: #58717d;
  font-size: 7px;
}

.home-upcoming-main span,
.home-payment-main span,
.home-recent-main span {
  margin-top: 3px;
  color: #9aa7ac;
  font-size: 5px;
}

.home-upcoming-time {
  color: #627b86;
  font-size: 6px;
  font-weight: 800;
  text-align: right;
}

.home-payment-icon {
  width: 31px;
  height: 31px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #2a9259;
  background: #eaf7ee;
}

.home-payment-amount {
  text-align: right;
}

.home-payment-amount strong,
.home-payment-amount span {
  display: block;
}

.home-payment-amount strong {
  color: #2f7f52;
  font-size: 8px;
}

.home-payment-amount span {
  margin-top: 3px;
  color: #9ba7ac;
  font-size: 5px;
}

.home-dashboard-section .home-summary-empty {
  margin-top: 10px;
}


/* =========================================================
   EMPTY
========================================================= */

.home-summary-empty {
  min-height: 115px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 6px;
  padding: 20px;
  border: 1px dashed #dce6e9;
  border-radius: 10px;
  color: #9aa8ad;
  text-align: center;
}

.home-summary-empty.large {
  min-height: 155px;
}

.home-summary-empty strong {
  color: #5d7580;
  font-size: 8px;
}

.home-summary-empty span {
  max-width: 350px;
  color: #93a1a7;
  font-size: 6px;
  line-height: 1.5;
}


/* =========================================================
   PROCUREMENT CENTER
========================================================= */

.home-center-card {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr) auto;
  align-items: center;
  gap: 15px;
}

.home-center-main {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  min-width: 0;
}

.home-center-icon {
  width: 39px;
  height: 39px;
  flex: 0 0 39px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: #166534;
  background: #dcfce7;
}

.home-center-main > div:last-child {
  min-width: 0;
}

.home-center-main h2 {
  margin: 4px 0 4px;
  overflow: hidden;
  color: #4d6976;
  font-family: var(--font-heading);
  font-size: 12px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.home-center-main p {
  margin: 0;
  overflow: hidden;
  color: #96a4a9;
  font-size: 6px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.home-center-details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
}

.home-center-details > div {
  padding: 8px;
  border: 1px solid #e4eaed;
  border-radius: 8px;
  background: #fbfcfd;
}

.home-center-details span,
.home-center-details strong {
  display: block;
}

.home-center-details span {
  color: #9aa7ac;
  font-size: 5px;
}

.home-center-details strong {
  margin-top: 4px;
  color: #5a7480;
  font-size: 6px;
}

.home-center-actions {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.home-center-actions a {
  min-width: 108px;
}


/* =========================================================
   ARRIVAL CHECKLIST
========================================================= */

.home-arrival-check-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 7px;
  margin-top: 12px;
}

.home-arrival-check {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 9px;
  border: 1px solid #e2e9eb;
  border-radius: 9px;
  background: #fbfcfd;
}

.home-arrival-check > div {
  width: 21px;
  height: 21px;
  flex: 0 0 21px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  color: #228852;
  background: #e5f5e9;
}

.home-arrival-check span {
  color: #657e89;
  font-size: 6px;
  line-height: 1.3;
}


/* =========================================================
   SMS
========================================================= */

.home-sms-card {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  margin-bottom: 14px;
  padding: 15px;
  border: 1px solid #d8e6eb;
  border-radius: 14px;
  background: #f3f9fb;
}

.home-sms-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: #2b7ea4;
  background: #e3f1f6;
}

.home-sms-card > div:last-child {
  min-width: 0;
}

.home-sms-card > div:last-child > span {
  color: #8ca0a8;
  font-size: 5px;
  font-weight: 900;
  letter-spacing: .08em;
}

.home-sms-card h3 {
  margin: 5px 0 4px;
  color: #526f7d;
  font-family: var(--font-heading);
  font-size: 11px;
}

.home-sms-card p {
  margin: 0;
  color: #85979e;
  font-size: 6px;
  line-height: 1.55;
}


/* =========================================================
   PROCUREMENT JOURNEY
========================================================= */

.farmer-progress-heading {
  align-items: center;
}

.farmer-current-stage {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 0 8px;
  border-radius: 999px;
  color: #2a7ca1;
  background: #edf7fa;
  font-size: 5px;
  font-weight: 900;
}

.farmer-progress-track {
  display: flex;
  align-items: flex-start;
  margin-top: 16px;
}

.farmer-progress-stage {
  min-width: 72px;
  display: flex;
  align-items: center;
  flex-direction: column;
  gap: 6px;
  color: #b0babf;
  text-align: center;
}

.farmer-progress-icon {
  width: 35px;
  height: 35px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #e0e7e9;
  border-radius: 10px;
  color: #a3afb4;
  background: #fff7ed;
}

.farmer-progress-stage.active .farmer-progress-icon {
  border-color: #c6dce4;
  color: #2d7da1;
  background: #edf7fa;
}

.farmer-progress-stage.complete .farmer-progress-icon {
  border-color: #cce3d2;
  color: #2b9059;
  background: #eaf7ed;
}

.farmer-progress-stage span {
  font-size: 5px;
  font-weight: 800;
}

.farmer-progress-stage.active span {
  color: #54717e;
}

.farmer-progress-stage.complete span {
  color: #49745a;
}

.farmer-progress-line {
  flex: 1;
  height: 2px;
  margin-top: 17px;
  background: #e6ecee;
}

.farmer-progress-line.active {
  background: #9fc7b0;
}

.farmer-progress-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid #edf1f3;
}

.farmer-progress-bottom span,
.farmer-progress-bottom strong {
  display: block;
}

.farmer-progress-bottom span {
  color: #9ba7ac;
  font-size: 5px;
  font-weight: 900;
}

.farmer-progress-bottom strong {
  margin-top: 3px;
  color: #59727d;
  font-size: 7px;
}

.farmer-progress-percent {
  color: #2e8254;
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 900;
}


/* =========================================================
   SUPPORT
========================================================= */

.home-support-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-top: 4px;
  color: #9aa7ac;
  font-size: 6px;
}

.home-support-row a {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #2f7da2;
  text-decoration: none;
  font-weight: 900;
}

.home-support-row a:hover {
  text-decoration: underline;
}


/* =========================================================
   LOADING / ERROR
========================================================= */

.loading-spin,
.token-spin {
  animation: farmerSpin .8s linear infinite;
}

@keyframes farmerSpin {
  to {
    transform: rotate(360deg);
  }
}

.empty-state-card {
  padding: 40px 25px;
  border: 1px solid #dfe8eb;
  border-radius: 16px;
  background: #ffffff;
  text-align: center;
  box-shadow: 0 9px 27px rgba(35, 73, 92, .03);
}

.empty-state-icon {
  width: 52px;
  height: 52px;
  margin: 0 auto 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 14px;
  color: #5f8796;
  background: #eaf4f7;
}

.empty-state-card h1 {
  margin: 6px 0;
  color: #4b6877;
  font-family: var(--font-heading);
  font-size: 19px;
}

.empty-state-card p {
  max-width: 420px;
  margin: 0 auto 14px;
  color: #8b9ba2;
  font-size: 7px;
  line-height: 1.6;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1050px) {

  .home-center-card {
    grid-template-columns: 1fr;
  }

  .home-center-actions {
    flex-direction: row;
  }

  .home-center-actions a {
    flex: 1;
  }

}

@media (max-width: 850px) {

  .farmer-welcome {
    flex-direction: column;
  }

  .farmer-profile {
    width: 100%;
  }

  .farmer-home-grid {
    grid-template-columns: 1fr;
  }

  .booking-main-details {
    grid-template-columns: 1fr;
  }

  .home-arrival-check-grid {
    grid-template-columns: repeat(2, 1fr);
  }

}

@media (max-width: 650px) {

  .farmer-home-container {
    width: min(100% - 20px, 1320px);
    padding-top: 18px;
  }

  .next-booking-card,
  .home-dashboard-section,
  .home-month-summary-card,
  .home-center-card,
  .home-arrival-check-card,
  .farmer-progress-card {
    padding: 13px;
    border-radius: 13px;
  }

  .home-month-stats {
    grid-template-columns: 1fr;
  }

  .home-upcoming-row {
    grid-template-columns: 42px minmax(0, 1fr) 80px 15px;
  }

  .home-payment-row {
    grid-template-columns: 30px minmax(0, 1fr) 80px 15px;
  }

  .home-recent-row {
    grid-template-columns: 42px minmax(0, 1fr) auto 15px;
  }

  .home-center-details {
    grid-template-columns: 1fr;
  }

  .home-arrival-check-grid {
    grid-template-columns: 1fr;
  }

  .farmer-progress-track {
    overflow-x: auto;
    padding-bottom: 5px;
  }

  .farmer-progress-stage {
    min-width: 64px;
  }

  .farmer-progress-line {
    min-width: 25px;
  }

  .booking-action-row {
    flex-direction: column;
  }

  .booking-action-row a {
    width: 100%;
  }

  .home-payment-complete-strip {
