/* =========================================================
   KRISHISETU - VISUAL POLISH LAYER
   Add at the END of src/index.css
========================================================= */


/* =========================================================
   GLOBAL
========================================================= */

:root {
  --ks-radius-xl: 22px;
  --ks-radius-lg: 17px;
  --ks-radius-md: 13px;
  --ks-radius-sm: 9px;

  --ks-space-1: 6px;
  --ks-space-2: 10px;
  --ks-space-3: 14px;
  --ks-space-4: 18px;
  --ks-space-5: 24px;
  --ks-space-6: 32px;
  --ks-space-7: 42px;

  --ks-shadow-soft:
    0 10px 35px rgba(35, 73, 92, .06);

  --ks-shadow-hover:
    0 16px 42px rgba(35, 73, 92, .10);

  --ks-border:
    #e2eaec;

  --ks-text:
    #294f61;

  --ks-text-soft:
    #70868f;

  --ks-text-muted:
    #96a5aa;
}


* {
  box-sizing: border-box;
}


button,
a,
input,
select,
textarea {
  -webkit-tap-highlight-color: transparent;
}


button,
a {
  transition:
    transform .18s ease,
    box-shadow .18s ease,
    background-color .18s ease,
    border-color .18s ease,
    color .18s ease,
    opacity .18s ease;
}


/* =========================================================
   PAGE TYPOGRAPHY
========================================================= */

.page-eyebrow,
.admin-page-eyebrow {
  letter-spacing: .12em;
  font-size: 10px;
  font-weight: 900;
}


.farmer-home-container > section h1,
.farmer-home-container > section h2,
.token-container > section h1,
.token-container > section h2,
.admin-dashboard-page h2,
.admin-queue-page h2,
.admin-payment-issues-page h2 {
  letter-spacing: -.035em;
}


.farmer-home-container > section h1 {
  font-size: clamp(
    34px,
    4vw,
    58px
  );
  line-height: 1.02;
}


.farmer-home-container > section h2,
.token-container > section h2 {
  font-size: clamp(
    26px,
    3vw,
    40px
  );
  line-height: 1.05;
}


/* =========================================================
   FARMER HOME
========================================================= */

.farmer-home-page {
  min-height: 100vh;
}


.farmer-welcome {
  gap: var(--ks-space-6);
  margin-bottom: 30px;
}


.farmer-welcome > div:first-child {
  min-width: 0;
}


.farmer-welcome h1 {
  max-width: 820px;
  margin-top: 10px;
}


.farmer-welcome p {
  max-width: 720px;
  margin-top: 12px;
  font-size: 14px;
  line-height: 1.7;
}


.farmer-profile {
  min-height: 62px;
  padding: 8px 12px 8px 8px;
  border: 1px solid var(--ks-border);
  border-radius: 16px;
  background: rgba(255,255,255,.9);
