/* =========================================================
   KRISHISETU — FARMER BOOKING PAGE
========================================================= */


/* =========================================================
   PAGE
========================================================= */

.farmer-book-page {
  min-height: 100vh;
  background:
    radial-gradient(
      circle at 5% 0%,
      rgba(33, 122, 73, .08),
      transparent 24%
    ),
    radial-gradient(
      circle at 95% 0%,
      rgba(22, 93, 128, .09),
      transparent 25%
    ),
    linear-gradient(
      180deg,
      #f1f7f7 0%,
      #f8fbfa 100%
    );
}


.farmer-book-container {
  width: min(
    1180px,
    calc(100% - 32px)
  );

  margin:
    0 auto;

  padding:
    38px 0 70px;
}


/* =========================================================
   HERO
========================================================= */

.farmer-book-hero {
  display:
    flex;

  align-items:
    flex-end;

  justify-content:
    space-between;

  gap:
    28px;

  margin-bottom:
    28px;
}


.farmer-book-hero h1 {
  margin-top:
    10px;

  color:
    var(--ks-primary-dark);

  font-size:
    clamp(
      38px,
      5vw,
      64px
    );

  line-height:
    .95;

  letter-spacing:
    -.055em;

  font-weight:
    950;

  text-wrap:
    balance;
}


.farmer-book-hero p {
  max-width:
    700px;

  margin-top:
    13px;

  color:
    var(--ks-text-soft);

  font-size:
    13px;

  line-height:
    1.75;
}


/* =========================================================
   BOOKING STEP INDICATOR
========================================================= */

.farmer-book-steps {
  display:
    flex;

  align-items:
    center;

  gap:
    10px;

  padding:
    13px 16px;

  margin-bottom:
    20px;

  border:
    1px solid var(--ks-border);

  border-radius:
    15px;

  background:
    var(--ks-surface);

  box-shadow:
    var(--ks-shadow-small);

  overflow-x:
    auto;
}


.farmer-book-step {
  display:
    flex;

  align-items:
    center;

  gap:
    8px;

  min-width:
    max-content;

  color:
    var(--ks-text-muted);

  font-size:
    10px;

  font-weight:
    900;
}


.farmer-book-step-number {
  display:
    grid;

  place-items:
    center;

  width:
    30px;

  height:
    30px;

  border-radius:
    50%;

  border:
    1px solid var(--ks-border);

  color:
    var(--ks-text-muted);

  background:
    var(--ks-surface-2);

  font-size:
    10px;

  font-weight:
    950;
}


.farmer-book-step.active {
  color:
    var(--ks-primary);
}


.farmer-book-step.active
.farmer-book-step-number {

  color:
    #ffffff;

  border-color:
    var(--ks-primary);

  background:
    var(--ks-primary);

  box-shadow:
    0 5px 14px rgba(22, 93, 128, .16);

}


.farmer-book-step.complete {
  color:
    var(--ks-green);
}


.farmer-book-step.complete
.farmer-book-step-number {

  color:
    #ffffff;

  border-color:
    var(--ks-green);

  background:
    var(--ks-green);

}


.farmer-book-step-line {
  flex:
    1;

  min-width:
    18px;

  height:
    3px;

  border-radius:
    999px;

  background:
    var(--ks-border);
}


.farmer-book-step-line.active {
  background:
    linear-gradient(
      90deg,
      var(--ks-primary),
      var(--ks-green)
    );
}


/* =========================================================
   MAIN FORM LAYOUT
========================================================= */

.farmer-book-layout {
  display:
    grid;

  grid-template-columns:
    minmax(0, 1.55fr)
    minmax(290px, .75fr);

  gap:
    22px;

  align-items:
    start;
}


/* =========================================================
   FORM CARD
========================================================= */

.farmer-book-card {
  padding:
    28px;

  border:
    1px solid var(--ks-border);

  border-radius:
    var(--ks-radius-xl);

  background:
    var(--ks-surface);

  box-shadow:
    var(--ks-shadow-medium);
}


.farmer-book-card-header {
  padding-bottom:
    20px;

  margin-bottom:
    22px;

  border-bottom:
    1px solid var(--ks-border);
}


.farmer-book-card-header h2 {
  margin-top:
    7px;

  color:
    var(--ks-primary);

  font-size:
    clamp(
      27px,
      3vw,
      39px
    );

  line-height:
    1;

  letter-spacing:
    -.04em;
}


.farmer-book-card-header p {
  max-width:
    680px;

  margin-top:
    8px;

  color:
    var(--ks-text-soft);

  font-size:
    12px;

  line-height:
    1.65;
}


/* =========================================================
   FORM SECTIONS
========================================================= */

.farmer-book-section {
  padding:
    20px 0;

  border-bottom:
    1px solid var(--ks-border);
}


.farmer-book-section:last-child {
  border-bottom:
    0;

  padding-bottom:
    0;
}


.farmer-book-section-title {
  display:
    flex;

  align-items:
    center;

  gap:
    11px;

  margin-bottom:
    16px;
}


.farmer-book-section-icon {
  display:
    grid;

  place-items:
    center;

  width:
    42px;

  height:
    42px;

  border-radius:
    12px;

  color:
    var(--ks-primary);

  background:
    var(--ks-primary-light);
}


.farmer-book-section-title h3 {
  color:
    var(--ks-heading);

  font-size:
    18px;

  letter-spacing:
    -.02em;
}


/* =========================================================
   LABELS
========================================================= */

.farmer-book-card label {
  display:
    block;

  margin-bottom:
    8px;

  color:
    var(--ks-text);

  font-size:
    12px;

  font-weight:
    900;
}


/* =========================================================
   INPUTS
========================================================= */

.farmer-book-card input,
.farmer-book-card select,
.farmer-book-card textarea {

  min-height:
    48px;

  width:
    100%;

  padding:
    0 14px;

  border:
    1px solid var(--ks-border-strong);

  border-radius:
    11px;

  color:
    var(--ks-heading);

  background:
    var(--ks-surface-2);

  font-size:
    13px;

  transition:
    border-color .2s ease,
    box-shadow .2s ease,
    background-color .2s ease;
}


.farmer-book-card textarea {
  padding:
    13px 14px;

  min-height:
    110px;
}


.farmer-book-card input:hover,
.farmer-book-card select:hover,
.farmer-book-card textarea:hover {
  border-color:
    #a9c3ca;
}


.farmer-book-card input:focus,
.farmer-book-card select:focus,
.farmer-book-card textarea:focus {

  border-color:
    var(--ks-primary);

  background:
    var(--ks-surface);

  outline:
    none;

  box-shadow:
    0 0 0 4px rgba(22, 93, 128, .09);
}


/* =========================================================
   CROP SELECTION
========================================================= */

.farmer-book-crop-grid {
  display:
    grid;

  grid-template-columns:
    repeat(
      4,
      minmax(0, 1fr)
    );

  gap:
    11px;
}


.farmer-book-crop-option {
  position:
    relative;

  min-height:
    96px;

  padding:
    14px;

  border:
    1px solid var(--ks-border);

  border-radius:
    14px;

  background:
    var(--ks-surface-2);

  text-align:
    left;

  cursor:
    pointer;
}


.farmer-book-crop-option:hover {

  transform:
    translateY(-2px);

  border-color:
    #b9d2d8;

  box-shadow:
    var(--ks-shadow-small);
}


.farmer-book-crop-option.active {

  border-color:
    var(--ks-green);

  background:
    var(--ks-green-light);

  box-shadow:
    0 0 0 3px rgba(33, 122, 73, .08);

}


.farmer-book-crop-option strong {

  display:
    block;

  margin-top:
    12px;

