  background:
    var(--ks-primary-light);

}


.farmer-book-summary-item:nth-child(2)
.farmer-book-summary-item-icon {

  color:
    var(--ks-green);

  background:
    var(--ks-green-light);

}


.farmer-book-summary-item:nth-child(3)
.farmer-book-summary-item-icon {

  color:
    var(--ks-orange);

  background:
    var(--ks-orange-light);

}


.farmer-book-summary-item span {

  display:
    block;

  color:
    var(--ks-text-muted);

  font-size:
    9px;

  font-weight:
    800;
}


.farmer-book-summary-item strong {

  display:
    block;

  margin-top:
    4px;

  color:
    var(--ks-heading);

  font-size:
    13px;

}


/* =========================================================
   SUMMARY ACTION
========================================================= */

.farmer-book-submit {

  display:
    flex;

  align-items:
    center;

  justify-content:
    space-between;

  gap:
    12px;

  width:
    100%;

  min-height:
    54px;

  margin-top:
    20px;

  padding:
    0 18px;

  border:
    0;

  border-radius:
    12px;

  color:
    #ffffff;

