    0 9px 24px rgba(33, 122, 73, .17);

  font-size:
    12px;

  font-weight:
    950;

  cursor:
    pointer;

}


.farmer-book-submit:hover {

  transform:
    translateY(-2px);

  box-shadow:
    0 14px 30px rgba(33, 122, 73, .22);

}


.farmer-book-submit:disabled {

  opacity:
    .55;

  cursor:
    not-allowed;

  transform:
    none;

}


/* =========================================================
   INFORMATION CARD
========================================================= */

.farmer-book-info {

  display:
    flex;

  align-items:
    flex-start;

  gap:
    11px;

  margin-top:
    13px;

  padding:
    13px;

  border:
    1px solid #cbdfe5;

  border-radius:
    12px;

  background:
    var(--ks-primary-light);

}


.farmer-book-info strong {

  display:
    block;

  color:
    var(--ks-primary-dark);

  font-size:
    12px;

}


.farmer-book-info span {

  display:
    block;

  margin-top:
    4px;

  color:
    var(--ks-text);

  font-size:
    10px;

  line-height:
    1.6;
}


/* =========================================================
   ERROR
========================================================= */

.farmer-book-error {

  display:
    flex;

  align-items:
    flex-start;

  gap:
    12px;

  margin-bottom:
