  border-radius:
    13px;

  color:
    var(--ks-red);

  background:
    var(--ks-red-light);

}


.farmer-book-error strong {

  display:
    block;

  font-size:
    13px;

}


.farmer-book-error span {

  display:
    block;

  margin-top:
    4px;

  color:
    #7e5b58;

  font-size:
    11px;

  line-height:
    1.5;

}


/* =========================================================
   DARK MODE
========================================================= */

html.dark .farmer-book-page,
body.dark .farmer-book-page,
html.dark-mode .farmer-book-page,
body.dark-mode .farmer-book-page,
html[data-theme="dark"] .farmer-book-page,
body[data-theme="dark"] .farmer-book-page {

  background:
    radial-gradient(
      circle at 5% 0%,
      rgba(70, 177, 120, .08),
      transparent 25%
    ),
    radial-gradient(
      circle at 95% 0%,
      rgba(74, 165, 207, .09),
      transparent 27%
    ),
    linear-gradient(
      180deg,
      #071318,
      #0d1b21
    ) !important;

}


/* Main */

html.dark .farmer-book-card,
html.dark .farmer-book-summary,
html.dark .farmer-book-steps,
body.dark .farmer-book-card,
body.dark .farmer-book-summary,
body.dark .farmer-book-steps {

  background:
    var(--ks-surface) !important;

  border-color:
    var(--ks-border) !important;

}


/* Inputs */

html.dark .farmer-book-card input,
html.dark .farmer-book-card select,
html.dark .farmer-book-card textarea {

  color:
    var(--ks-text) !important;

  background:
    #0d2027 !important;

  border-color:
    var(--ks-border-strong) !important;

}


html.dark .farmer-book-card input:focus,
html.dark .farmer-book-card select:focus,
html.dark .farmer-book-card textarea:focus {

  background:
    #10272f !important;

  border-color:
    var(--ks-primary) !important;

}


/* Crop and center */

html.dark .farmer-book-crop-option,
html.dark .farmer-book-center-option,
html.dark .farmer-book-slot-option {

  background:
    var(--ks-surface-2) !important;

  border-color:
    var(--ks-border) !important;

}


html.dark .farmer-book-crop-option.active,
html.dark .farmer-book-center-option.active,
html.dark .farmer-book-slot-option.active {

  background:
    #153744 !important;

}


/* Summary */

html.dark .farmer-book-summary-item {

  background:
    var(--ks-surface-2) !important;

  border-color:
    var(--ks-border) !important;

}


/* Info */

html.dark .farmer-book-info {

  background:
    #13333f !important;

  border-color:
    #315363 !important;

}


/* Error */

html.dark .farmer-book-error {

  background:
    #39221f !important;

  border-color:
    #5b3733 !important;

}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 950px) {

  .farmer-book-layout {

    grid-template-columns:
      1fr;

  }


  .farmer-book-summary {

    position:
      static;

  }


  .farmer-book-hero {

    flex-direction:
      column;

    align-items:
      flex-start;

  }

}


@media (max-width: 700px) {

  .farmer-book-container {

    width:
      min(
        100% - 22px,
        100%
      );

    padding-top:
      28px;

  }


  .farmer-book-card,
  .farmer-book-summary {

    padding:
      19px;

    border-radius:
      17px;

  }


  .farmer-book-hero h1 {

    font-size:
      36px;

  }


  .farmer-book-crop-grid {

    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );

  }


  .farmer-book-center-grid,
  .farmer-book-date-grid {

    grid-template-columns:
      1fr;

  }


  .farmer-book-slot-grid {

    grid-template-columns:
      1fr;

  }


  .farmer-book-quantity-card {

    grid-template-columns:
      1fr;

  }


  .farmer-book-quantity-unit {

    justify-content:
      flex-start;

  }

}


@media (max-width: 450px) {

  .farmer-book-hero h1 {

    font-size:
      32px;

  }


  .farmer-book-card-header h2 {

    font-size:
      28px;

  }


  .farmer-book-crop-grid {

    grid-template-columns:
      1fr;

  }


  .farmer-book-step {

    font-size:
      9px;

  }

}

/* =========================================================
   KRISHISETU — FARMER BOOKING
   CLEAN CIVIC DESIGN / LARGE CONTROLS / HIGH CONTRAST
========================================================= */


/* =========================================================
   PAGE
========================================================= */

.farmer-book-page {
  min-height: 100vh;

  background:
    linear-gradient(
      180deg,
      #eef5f6 0%,
      #f8fbfb 48%,
      #f1f6f5 100%
    );
}


.farmer-book-container {
  width: min(
    1180px,
    calc(100% - 36px)
  );

  margin: 0 auto;

  padding:
    42px 0 80px;
}


/* =========================================================
   HERO
========================================================= */

.farmer-book-hero {
  margin-bottom:
    26px;
}


.farmer-book-hero h1 {
  margin:
    9px 0 0;

  max-width:
    780px;

  color:
    #174c66;

  font-size:
    clamp(
      40px,
      5vw,
      64px
    );

  line-height:
    .96;

  font-weight:
    950;

  letter-spacing:
    -.055em;
}


.farmer-book-hero p {
  max-width:
    700px;

  margin-top:
    14px;

  color:
    #5e7780;

  font-size:
    14px;

  line-height:
    1.75;
}


/* =========================================================
   STEP BAR
========================================================= */

.farmer-book-steps {

  display:
    grid;

  grid-template-columns:
    repeat(
      4,
      1fr
    );

  gap:
    0;

  margin-bottom:
    22px;

  padding:
    7px;

  border:
    1px solid #d6e3e6;

  border-radius:
    16px;

  background:
    #ffffff;

  box-shadow:
    0 4px 18px rgba(35, 73, 92, .05);

}


.farmer-book-step {

  position:
    relative;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    9px;

  min-height:
    51px;

  padding:
    0 10px;

  color:
    #879ba2;

  font-size:
    11px;

  font-weight:
    900;
}


.farmer-book-step-number {

  display:
    grid;

  place-items:
    center;

  width:
    30px;

  height:
    30px;

  border-radius:
    50%;

  color:
    #879ba2;

  background:
    #edf3f4;

  font-size:
    10px;

  font-weight:
    950;
}


.farmer-book-step.active {

  color:
    #155d7d;

  background:
    #eaf5fa;

  border-radius:
    11px;

}


.farmer-book-step.active
.farmer-book-step-number {

  color:
    #ffffff;

  background:
    #216f95;

}


.farmer-book-step.complete {

  color:
    #23764a;

}


.farmer-book-step.complete
.farmer-book-step-number {

  color:
    #ffffff;

  background:
    #287c4f;

}


/* =========================================================
   MAIN LAYOUT
========================================================= */

.farmer-book-layout {

  display:
    grid;

  grid-template-columns:
    minmax(
      0,
      1fr
    )
    340px;

  gap:
    22px;

  align-items:
    start;

}


