/* =========================================================
   FARMER PAYMENTS — LARGE / CLEAR / TRUSTWORTHY
========================================================= */

.farmer-payments-page {
  min-height: 100vh;
  background:
    radial-gradient(circle at 8% 0%, rgba(40,122,77,.08), transparent 24%),
    radial-gradient(circle at 92% 0%, rgba(33,107,145,.09), transparent 25%),
    linear-gradient(180deg,#eef6f5,#f8fbfa);
}

.farmer-payments-container {
  width: min(1160px,calc(100% - 30px));
  margin: 0 auto;
  padding: 40px 0 70px;
}

/* HEADER */

.farmer-payments-header h1 {
  margin-top: 9px;
  color: #155b78;
  font-size: clamp(40px,5vw,62px);
  line-height: .95;
  letter-spacing: -.055em;
  font-weight: 950;
}

.farmer-payments-header p {
  max-width: 700px;
  margin-top: 12px;
  color: #617a83;
  font-size: 14px;
  line-height: 1.75;
}

/* SUMMARY */

.farmer-payments-summary,
.payment-summary-card {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 14px;
  margin-top: 25px;
}

.payment-summary-card {
  min-height: 125px;
  margin-top: 0;
  padding: 21px;
  border: 1px solid #d8e5e8;
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 8px 24px rgba(25,60,75,.06);
}

.payment-summary-card span {
  display: block;
  color: #71888f;
  font-size: 11px;
  font-weight: 900;
}

.payment-summary-card strong {
  display: block;
  margin-top: 10px;
  color: #174c66;
  font-size: 31px;
  line-height: 1;
  font-weight: 950;
}

.payment-summary-card:nth-child(1) strong {
  color: #287a4d;
}

.payment-summary-card:nth-child(2) strong {
  color: #166534;
}

.payment-summary-card:nth-child(3) strong {
  color: #c87920;
}

/* MAIN AREA */

.farmer-payments-grid {
  display: grid;
  grid-template-columns: minmax(0,1fr) 320px;
  gap: 20px;
  margin-top: 22px;
}

.farmer-payments-card {
  overflow: hidden;
  border: 1px solid #d8e5e8;
  border-radius: 20px;
  background: #fff;
  box-shadow: 0 10px 30px rgba(25,60,75,.06);
}

.farmer-payments-card-header {
  padding: 22px 24px;
  border-bottom: 1px solid #e6edef;
}

.farmer-payments-card-header h2 {
  margin-top: 7px;
  color: #17607e;
  font-size: 27px;
  letter-spacing: -.035em;
}

/* PAYMENT ROWS */

.farmer-payment-row,
.payment-history-item {
  display: grid;
  grid-template-columns: 58px minmax(0,1fr) auto;
  gap: 15px;
  align-items: center;
  min-height: 86px;
  padding: 14px 20px;
  border-bottom: 1px solid #edf2f3;
}

.farmer-payment-row:last-child,
.payment-history-item:last-child {
  border-bottom: 0;
}

.farmer-payment-row:hover,
.payment-history-item:hover {
  background: #f7fbfb;
}

.farmer-payment-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: 13px;
  color: #287a4d;
  background: #e8f6ed;
}

.farmer-payment-row strong,
.payment-history-item strong {
  color: #234d5d;
  font-size: 15px;
}

.farmer-payment-row span,
.payment-history-item span {
  display: block;
  margin-top: 4px;
  color: #70868e;
  font-size: 11px;
}

/* AMOUNT */

.payment-amount,
.farmer-payment-amount {
  color: #1e7448 !important;
  font-size: 20px !important;
  font-weight: 950 !important;
}

/* STATUS */

.payment-status {
  display: inline-flex;
  align-items: center;
  min-height: 29px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 950;
}

.payment-status.sent,
.payment-status.success {
  color: #216d45;
  background: #e7f6ec;
}

.payment-status.pending {
  color: #9a6725;
  background: #fff2dd;
}

.payment-status.failed {
  color: #a34c45;
  background: #fff0ee;
}

/* SMS */

.payment-sms-card {
  padding: 21px;
  border: 1px solid #cfe0e5;
  border-radius: 18px;
  background: linear-gradient(145deg,#edf7fa,#fff);
  box-shadow: 0 8px 24px rgba(25,60,75,.05);
}

.payment-sms-card h3 {
  margin-top: 8px;
  color: #185b77;
  font-size: 21px;
}

.payment-sms-card p {
  margin-top: 7px;
  color: #607a83;
  font-size: 11px;
  line-height: 1.7;
}

/* ISSUE BUTTON */

.payment-issue-button {
  min-height: 45px;
  padding: 0 15px;
  border: 1px solid #dfc59f;
  border-radius: 10px;
  color: #986321;
  background: #fff6e8;
  font-size: 11px;
  font-weight: 950;
}

.payment-issue-button:hover {
  transform: translateY(-2px);
  background: #ffefd7;
}

/* EMPTY */

.farmer-payments-empty {
  padding: 45px 25px;
  text-align: center;
  color: #728991;
}

.farmer-payments-empty h2 {
  margin-top: 10px;
  color: #21546b;
  font-size: 25px;
}

.farmer-payments-empty p {
  margin-top: 7px;
  font-size: 11px;
}

/* =========================================================
   DARK MODE
========================================================= */

html.dark .farmer-payments-page,
body.dark .farmer-payments-page,
html.dark-mode .farmer-payments-page,
body.dark-mode .farmer-payments-page,
html[data-theme="dark"] .farmer-payments-page,
body[data-theme="dark"] .farmer-payments-page {
  background:
    radial-gradient(circle at 8% 0%,rgba(59,157,103,.10),transparent 25%),
    radial-gradient(circle at 92% 0%,rgba(57,140,181,.12),transparent 28%),
    linear-gradient(180deg,#07151b,#0c1c22) !important;
}

html.dark .farmer-payments-card,
