html.dark .payment-history-item strong,
html.dark .payment-sms-card h3 {
  color: #f0f7f8 !important;
}

html.dark .farmer-payments-header p,
html.dark .payment-summary-card span,
html.dark .farmer-payment-row span,
html.dark .payment-history-item span,
html.dark .payment-sms-card p {
  color: #afc5ca !important;
}

html.dark .payment-summary-card:nth-child(1) strong {
  color: #79d79a !important;
}

html.dark .payment-summary-card:nth-child(2) strong {
  color: #7bc4e2 !important;
}

html.dark .payment-summary-card:nth-child(3) strong {
  color: #efb66b !important;
}

html.dark .payment-sms-card {
  background: linear-gradient(145deg,#14343f,#11262e) !important;
}

html.dark .payment-issue-button {
  color: #f0b66c;
  background: #382919;
  border-color: #5b482d;
}

/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 850px) {
  .farmer-payments-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 650px) {
  .farmer-payments-container {
    width: calc(100% - 20px);
    padding-top: 28px;
  }

  .farmer-payments-header h1 {
    font-size: 36px;
  }

  .farmer-payments-summary {
    grid-template-columns: 1fr;
  }

  .farmer-payment-row,
  .payment-history-item {
    grid-template-columns: 46px minmax(0,1fr);
  }

  .farmer-payment-icon {
    width: 42px;
    height: 42px;
  }

  .payment-amount,
  .farmer-payment-amount {
    grid-column: 2;
    font-size: 19px !important;
  }
}

