}


@keyframes landing-image-float {

  0%,
  100% {
    transform:
      translateY(0);
  }

  50% {
    transform:
      translateY(-7px);
  }

}


.landing-farm-illustration::before {

  content:
    "";

  position:
    absolute;

  inset:
    0;

  background:
