/* =========================================================
   MOTION ACCESSIBILITY
========================================================= */

@media (prefers-reduced-motion: reduce) {

  .landing-page *,
  .landing-page *::before,
  .landing-page *::after {

    animation:
      none !important;

    transition:
      none !important;

  }

  
}

