/* =========================================================
   TABLET
========================================================= */

@media (max-width: 900px) {

  .login-layout {

    grid-template-columns:
      1fr;

    gap:
      40px;

    min-height:
      auto;

    padding-top:
      35px;

  }


  .login-intro {

    max-width:
      760px;

  }


  .farmer-login-language {

    position:
      relative;

    top:
      auto;

    right:
      auto;

    width:
      max-content;

    margin:
      12px 14px 0 auto;

  }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 600px) {

  .login-container {

    width:
      calc(100% - 20px);

    padding:
      25px 0 55px;

  }


  .login-layout {

    gap:
      31px;

    padding-top:
      25px;

  }


  .login-intro h1 {

    font-size:
      40px;

  }


  .login-intro > p {

    font-size:
      13px;

  }


  .login-form-card {

    padding:
      21px;

    border-radius:
      19px;

  }


  .login-form-heading h2 {

    font-size:
      25px;

  }


  .login-form-heading {

    margin-bottom:
      23px;

  }


  .login-feature {

    padding:
      11px;

  }


  .login-feature strong {

    font-size:
      13px;

  }


  .login-feature span {

    font-size:
      10px;

  }


  .farmer-login-language {

    margin:
      10px 10px 0 auto;

  }


  .farmer-login-language button {

    padding:
      0 8px;

  }

}


/* =========================================================
   VERY SMALL PHONES
========================================================= */

@media (max-width: 390px) {

  .login-intro h1 {

    font-size:
      35px;

  }


  .login-form-card {

    padding:
      18px;

  }


  .login-form-heading h2 {

    font-size:
      23px;

  }


  .farmer-login-language > svg {

    display:
      none;

  }

}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

  .farmer-login-page *,
  .farmer-login-page *::before,
  .farmer-login-page *::after {

    animation:
      none !important;

    transition:
      none !important;

  }

}

/* =========================================================
   FARMER REGISTER — DARK MODE FIX
========================================================= */

.farmer-register-page {
  min-height: 100vh;

  color: #365a68;

  background:
    radial-gradient(
      circle at 5% 3%,
      rgba(25,160,91,.10),
      transparent 25%
    ),
    radial-gradient(
      circle at 95% 5%,
      rgba(25,139,207,.10),
      transparent 27%
    ),
    linear-gradient(
      180deg,
      #edf7f5,
      #f8fbfa 55%,
