/* =========================================================
   KRISHISETU HERO JOURNEY ILLUSTRATION
========================================================= */

.landing-hero-visual {
  position: relative;

  min-height: 620px;

  display: flex;

  align-items: center;

  justify-content: center;

  overflow: hidden;
}


/* =========================================================
   MAIN ILLUSTRATION
========================================================= */

.landing-journey-illustration {
  position: relative;

  width: min(560px, 90vw);

  aspect-ratio: 1;

  display: flex;

  align-items: center;

  justify-content: center;

  animation:
    heroFloat 7s ease-in-out infinite;
}


/* =========================================================
   CENTRAL CIRCLE
========================================================= */

.journey-center {
  position: relative;

  width: 190px;
  height: 190px;

  border-radius: 50%;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  gap: 5px;

  background:
    linear-gradient(
      145deg,
      rgba(255,255,255,.96),
      rgba(242,248,244,.92)
    );

  border:
    1px solid
    rgba(31,120,77,.18);

  box-shadow:
    0 25px 70px rgba(26,91,60,.16),
    inset 0 0 0 10px rgba(31,120,77,.045);

  z-index: 5;

  overflow: hidden;
}


.journey-center-glow {
  position: absolute;

  width: 150px;
  height: 150px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(48,178,111,.18),
      transparent 68%
    );

  filter: blur(4px);

  animation:
    centerGlow 3.5s ease-in-out infinite;
}


.journey-center-icon {
  position: relative;

  width: 82px;
  height: 82px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 24px;

  color: #1b8957;

  background:
    linear-gradient(
      145deg,
      rgba(38,161,96,.13),
      rgba(38,161,96,.035)
    );

  border:
    1px solid
    rgba(38,161,96,.16);

  z-index: 2;
}


.journey-center strong {
  position: relative;

  z-index: 2;

  font-size: 20px;

  font-weight: 950;

  letter-spacing: -.03em;
}


.journey-center span {
  position: relative;

  z-index: 2;

  font-size: 9px;

  letter-spacing: .18em;

  font-weight: 900;

  color: #71917f;
}


/* =========================================================
   ORBIT RINGS
========================================================= */

.journey-ring {
  position: absolute;

  border-radius: 50%;

  pointer-events: none;

  border:
    1px solid
    rgba(39,145,94,.15);
}


.ring-one {
  width: 360px;
  height: 360px;

  animation:
    rotateRing 24s linear infinite;
}


.ring-two {
  width: 500px;
  height: 500px;

  border-style: dashed;

  border-color:
    rgba(77,112,183,.13);

  animation:
    rotateRingReverse 32s linear infinite;
}


/* =========================================================
   NODES
========================================================= */

.journey-node {
  position: absolute;

  display: flex;

  align-items: center;

  gap: 10px;

  min-width: 145px;

  padding: 11px 14px;

  border-radius: 16px;

  background:
    rgba(255,255,255,.94);

  border:
    1px solid
    rgba(20,65,47,.10);

  box-shadow:
    0 14px 35px rgba(22,58,43,.09);

  backdrop-filter:
    blur(12px);

  -webkit-backdrop-filter:
    blur(12px);

  z-index: 8;

  transition:
    transform .25s ease,
    box-shadow .25s ease;
}


.journey-node:hover {
  transform:
    translateY(-6px) scale(1.035);

  box-shadow:
    0 20px 42px rgba(22,58,43,.15);
}


.journey-node-icon {
  width: 42px;
  height: 42px;

  flex: 0 0 42px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 13px;

  background:
    rgba(30,140,88,.09);

  color:
    #238a58;
}


.journey-node span {
  display: block;

  margin-bottom: 3px;

  font-size: 8px;

  letter-spacing: .13em;

  font-weight: 950;

  color: #849b91;
}


.journey-node strong {
  display: block;

  font-size: 13px;

  line-height: 1.1;

  font-weight: 900;

  color: #18382b;
}


/* =========================================================
   NODE POSITIONS
========================================================= */

.journey-farm {
  top: 7%;

  left: 12%;

  animation:
    nodeFloatOne 4.4s ease-in-out infinite;
}


.journey-token {
  top: 15%;

  right: 3%;

  animation:
    nodeFloatTwo 4.8s ease-in-out infinite;
}


.journey-weighing {
  right: 2%;

  bottom: 18%;

  animation:
    nodeFloatThree 5.1s ease-in-out infinite;
}


.journey-center-node {
  left: 4%;

  bottom: 14%;

  animation:
    nodeFloatTwo 4.7s ease-in-out infinite;
}


