   FEATURE GRID
========================================================= */

.admin-login-feature {
  position: relative;

  overflow: hidden;

  border:
    1px solid rgba(52, 83, 58, 0.08);

  background:
    rgba(255,255,255,0.68);

  backdrop-filter:
    blur(12px);

  -webkit-backdrop-filter:
    blur(12px);

  box-shadow:
    0 10px 28px
    rgba(37, 65, 42, 0.045);

  transition:
    transform 0.4s cubic-bezier(.2,.8,.2,1),
    box-shadow 0.4s ease,
    border-color 0.3s ease;
}

.admin-login-feature::after {
  content: "";

  position: absolute;

  width: 130px;
  height: 130px;

  right: -72px;
  bottom: -72px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(101, 157, 101, 0.10),
      transparent 70%
    );

  opacity: 0;

  transition:
    opacity 0.4s ease,
    transform 0.45s ease;
}

.admin-login-feature:hover {
  transform:
    translateY(-6px);

  box-shadow:
    0 20px 42px
    rgba(36, 67, 41, 0.085);

  border-color:
    rgba(70, 122, 76, 0.16);
}

.admin-login-feature:hover::after {
  opacity: 1;
  transform:
    scale(1.25);
}

.admin-login-feature-icon {
  transition:
    transform 0.35s cubic-bezier(.2,.8,.2,1),
    box-shadow 0.35s ease;
}

.admin-login-feature:hover
.admin-login-feature-icon {
  transform:
    scale(1.08)
    rotate(-4deg);

  box-shadow:
    0 10px 20px
    rgba(46, 87, 52, 0.08);
}

.admin-login-feature strong {
  font-size: 17px;
}

.admin-login-feature span {
  font-size: 14px;
  line-height: 1.6;
}


/* =========================================================
   WORKFLOW
========================================================= */

.admin-login-workflow {
  position: relative;

  border:
    1px solid rgba(53, 86, 59, 0.08);

  background:
    rgba(255,255,255,0.60);

  backdrop-filter:
    blur(12px);

  -webkit-backdrop-filter:
    blur(12px);

  box-shadow:
    0 14px 30px
    rgba(36, 64, 41, 0.05);
}

.admin-login-workflow-heading span {
  letter-spacing:
    0.14em;
}

.admin-login-workflow-heading strong {
  font-size: 17px;
}


/* workflow circles */

.admin-workflow-step {
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease;
}

.admin-workflow-step:hover {
  transform:
    translateY(-4px);
}

.admin-workflow-step span {
  transition:
    transform 0.35s ease;
}

.admin-workflow-step:hover span {
  transform:
    scale(1.08);
  box-shadow:
    0 8px 18px
    rgba(58, 104, 63, 0.12);
}

.admin-workflow-line {
  position: relative;
  overflow: hidden;
}

.admin-workflow-line::after {
  content: "";

  position: absolute;

  left: -100%;
  top: 50%;

  width: 100%;
  height: 2px;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(81, 138, 86, 0.55),
      transparent
    );

  transform:
    translateY(-50%);

  animation:
    adminWorkflowLine
    3.4s
    ease-in-out
    infinite;
}


/* =========================================================
   LOGIN CARD
========================================================= */

.admin-login-card {
  position: relative;
  z-index: 3;

  overflow: hidden;

  background:
    rgba(255,255,255,0.88);

  backdrop-filter:
    blur(22px);

  -webkit-backdrop-filter:
    blur(22px);

  border:
    1px solid rgba(43, 75, 49, 0.09);

  box-shadow:
    0 30px 80px
    rgba(31, 57, 36, 0.11),
    0 8px 25px
    rgba(31, 57, 36, 0.055);

  animation:
    adminLoginCardEnter
    0.85s
    cubic-bezier(.2,.8,.2,1)
    0.08s
    both;
}

.admin-login-card::before {
  content: "";

  position: absolute;

  left: 0;
  right: 0;
  top: 0;

  height: 3px;

  background:
    linear-gradient(
      90deg,
      #4f8a57,
      #89a95e,
      #597eaa
    );

  background-size:
    200% 100%;

  animation:
    adminCardGradient
    7s
    linear
    infinite;
}


/* =========================================================
   LOGIN HEADING
========================================================= */

.admin-login-card-heading {
  position: relative;
}

.admin-login-lock {
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease;
}

.admin-login-card:hover
.admin-login-lock {
  transform:
    scale(1.06)
    rotate(-4deg);

  box-shadow:
    0 12px 24px
    rgba(51, 102, 58, 0.11);
}

.admin-login-card-heading h2 {
  letter-spacing:
    -0.025em;
}


/* =========================================================
   FORM FIELDS
========================================================= */

.admin-login-field label {
  font-size: 15px;
  font-weight: 750;
}

.admin-login-field small {
  font-size: 13px;

  line-height: 1.5;
}


/* input container */

.admin-login-input {
  position: relative;

  transition:
    border-color 0.3s ease,
    box-shadow 0.3s ease,
    transform 0.3s ease;
}

.admin-login-input:focus-within {
  transform:
    translateY(-2px);

  border-color:
    rgba(70, 130, 79, 0.38);

  box-shadow:
    0 0 0 4px
    rgba(75, 139, 82, 0.08),
    0 10px 24px
    rgba(43, 78, 48, 0.06);
}

.admin-login-input svg {
  transition:
    transform 0.3s ease,
    color 0.3s ease;
}

.admin-login-input:focus-within svg {
  transform:
    scale(1.08);

  color:
    #4d8a55;
}


/* =========================================================
   SHOW / HIDE PASSWORD
========================================================= */

.admin-show-password {
  transition:
    color 0.25s ease,
    background-color 0.25s ease,
    transform 0.25s ease;
}

.admin-show-password:hover {
  color:
    #3f7748;

  transform:
    translateY(-1px);
}


/* =========================================================
   ERROR
========================================================= */

.admin-login-error {
  border:
    1px solid rgba(196, 75, 60, 0.14);

  box-shadow:
    0 8px 20px
    rgba(170, 68, 56, 0.045);

  animation:
    adminLoginShake
    0.35s
    ease;
}


/* =========================================================
   REMEMBER
========================================================= */

.admin-remember-row {
  transition:
    color 0.25s ease;
}

.admin-remember-row:hover {
  color:
    #3f7748;
}


/* =========================================================
   LOGIN BUTTON
========================================================= */

.admin-login-submit {
  position: relative;

  overflow: hidden;

  isolation: isolate;

  transition:
    transform 0.3s cubic-bezier(.2,.8,.2,1),
    box-shadow 0.3s ease;
}

.admin-login-submit::before {
  content: "";

  position: absolute;

  inset: 0;

  background:
    linear-gradient(
      110deg,
      transparent 18%,
      rgba(255,255,255,0.25) 48%,
      transparent 78%
    );

  transform:
    translateX(-125%);

  transition:
    transform 0.75s cubic-bezier(.2,.8,.2,1);

  z-index: -1;
}

.admin-login-submit:hover::before {
  transform:
    translateX(125%);
}

.admin-login-submit:hover:not(:disabled) {
  transform:
    translateY(-4px);

  box-shadow:
    0 17px 32px
    rgba(48, 104, 56, 0.18);
}

.admin-login-submit:active:not(:disabled) {
  transform:
    translateY(-1px)
    scale(0.99);
}


/* =========================================================
   DEMO BOX
========================================================= */

.admin-demo-box {
  position: relative;

  overflow: hidden;

  border:
    1px solid rgba(67, 103, 71, 0.10);

  background:
    linear-gradient(
      135deg,
      rgba(243, 248, 243, 0.86),
      rgba(250, 250, 246, 0.90)
    );

  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease,
    border-color 0.35s ease;
}

.admin-demo-box::before {
  content: "";

  position: absolute;

  top: 0;
  bottom: 0;
  left: -120%;

  width: 70%;

  background:
    linear-gradient(
      105deg,
      transparent,
      rgba(255,255,255,0.5),
      transparent
    );

  transform:
    skewX(-18deg);

  transition:
    transform 0.8s ease;
}

.admin-demo-box:hover {
  transform:
    translateY(-3px);

  box-shadow:
    0 12px 28px
    rgba(40, 72, 44, 0.07);

  border-color:
    rgba(67, 119, 73, 0.16);
}

.admin-demo-box:hover::before {
  transform:
    translateX(280%)
    skewX(-18deg);
}

.admin-demo-icon {
  transition:
    transform 0.35s ease;
}

.admin-demo-box:hover .admin-demo-icon {
  transform:
    rotate(-6deg)
    scale(1.06);
}

.admin-demo-box strong {
  font-size: 16px;
}

.admin-demo-box p {
  font-size: 13px;
  line-height: 1.55;
}


/* =========================================================
   SECURITY ROW
========================================================= */

.admin-security-row {
  transition:
    color 0.3s ease;
}

.admin-security-row:hover {
  color:
    #3e7447;
}


/* =========================================================
   LOWER TRUST STRIP
========================================================= */

.admin-login-trust {
  position: relative;
  z-index: 3;

  border:
    1px solid rgba(50, 83, 55, 0.075);

  background:
    rgba(255,255,255,0.66);

  backdrop-filter:
    blur(12px);

  -webkit-backdrop-filter:
    blur(12px);

  box-shadow:
    0 12px 28px
    rgba(39, 69, 44, 0.045);
}

.admin-login-trust > div {
  transition:
    transform 0.3s ease,
    background-color 0.3s ease,
    box-shadow 0.3s ease;
}

.admin-login-trust > div:hover {
  transform:
    translateY(-4px);

  background:
    rgba(255,255,255,0.75);

  box-shadow:
    0 10px 22px
    rgba(43, 76, 48, 0.06);
}


/* =========================================================
   FOOTER
========================================================= */

.admin-login-footer {
  position: relative;
  z-index: 3;

  background:
    rgba(245,248,245,0.78);

  border-top:
    1px solid rgba(48, 77, 52, 0.06);
}


/* =========================================================
   SPINNER
========================================================= */

.admin-login-spinner {
  border-color:
    rgba(255,255,255,0.35);

  border-top-color:
    #ffffff;

  animation:
    adminLoginSpin
    0.7s
    linear
    infinite;
}


/* =========================================================
   KEYFRAMES
========================================================= */

@keyframes adminLoginFadeUp {

  from {
    opacity: 0;
    transform:
      translateY(24px);
  }

  to {
    opacity: 1;
    transform:
      translateY(0);
  }

}

@keyframes adminLoginCardEnter {

  from {
    opacity: 0;

    transform:
      translateY(28px)
      scale(0.985);
  }

  to {
    opacity: 1;

    transform:
      translateY(0)
      scale(1);
  }

}

@keyframes adminLoginGradient {

  0%,
  100% {
    background-position:
      0% 50%;
  }

  50% {
    background-position:
      100% 50%;
  }

}

@keyframes adminCardGradient {

  0% {
    background-position:
      0% 50%;
  }

  100% {
    background-position:
      200% 50%;
  }

}

@keyframes adminWorkflowLine {

  0%,
  100% {
    left: -100%;
  }

  50% {
    left: 100%;
  }

}

@keyframes adminLoginOrbOne {

  0%,
  100% {
    transform:
      translate(0, 0)
      scale(1);
  }

  50% {
    transform:
      translate(35px, 25px)
      scale(1.08);
  }

}

@keyframes adminLoginOrbTwo {

  0%,
  100% {
    transform:
      translate(0, 0)
      scale(1);
  }

  50% {
    transform:
      translate(-30px, -25px)
      scale(1.08);
  }

}

@keyframes adminLoginShake {

  0%,
  100% {
    transform:
      translateX(0);
  }

  25% {
    transform:
      translateX(-4px);
  }

  75% {
    transform:
      translateX(4px);
  }

}

@keyframes adminLoginSpin {
  to {
    transform:
      rotate(360deg);
  }
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 900px) {

  .admin-login-layout {
    gap: 34px;
  }

  .admin-login-feature-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

}

@media (max-width: 650px) {

  .admin-login-feature-grid {
    grid-template-columns:
      1fr;
  }

  .admin-login-trust {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .admin-login-trust > div {
    min-width: 0;
  }

}

@media (max-width: 480px) {

  .admin-login-trust {
    grid-template-columns:
      1fr;
  }

  .admin-login-eyebrow-row {
    align-items:
      flex-start;
    flex-direction:
      column;
  }

}


/* =========================================================
   REDUCE MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

  *,
  *::before,
  *::after {
    animation-duration:
      0.01ms !important;

    animation-iteration-count:
      1 !important;

    transition-duration:
      0.01ms !important;
  }

}

/* =========================================================
   ADMIN LOGIN — KRISHISETU / FARMER-STYLE DESIGN
   Visual changes only.
========================================================= */

.admin-login-page {
  min-height: 100vh;
  position: relative;
  overflow-x: hidden;

  background:
    radial-gradient(
      circle at 8% 15%,
      rgba(96, 153, 91, 0.14),
      transparent 28%
    ),
    radial-gradient(
      circle at 92% 18%,
      rgba(221, 185, 91, 0.11),
      transparent 25%
    ),
    radial-gradient(
      circle at 75% 85%,
      rgba(81, 128, 99, 0.10),
