  background:
    radial-gradient(
      circle,
      rgba(93, 150, 87, 0.10),
      transparent 70%
    );

  pointer-events: none;

  animation:
    admin-bg-float-one
    12s
    ease-in-out
    infinite;
}

.admin-login-page::after {
  content: "";

  position: fixed;

  width: 600px;
  height: 600px;

  right: -260px;
  bottom: -260px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(209, 174, 88, 0.10),
      transparent 70%
    );

  pointer-events: none;

  animation:
    admin-bg-float-two
