/* =========================================================
   HEADER
========================================================= */

.admin-login-header {
  position: relative;
  z-index: 5;

  background:
    rgba(255, 255, 255, 0.82);

  border-bottom:
    1px solid rgba(57, 91, 61, 0.08);

