    linear-gradient(
      90deg,
      rgba(86,132,87,0.10),
      rgba(86,132,87,0.35),
      rgba(86,132,87,0.10)
    );
}


/* =========================================================
   LOGIN CARD
========================================================= */

.admin-login-card {
  width:
    100%;

  max-width:
    510px;

  justify-self:
    end;

  padding:
    34px;

  border-radius:
    26px;

  background:
    rgba(255,255,255,0.90);

  border:
    1px solid
    rgba(53,84,58,0.10);

  box-shadow:
    0 30px 70px
    rgba(38,64,42,0.10);

  animation:
    admin-login-enter-right
    0.85s
    cubic-bezier(.2,.8,.2,1)
    0.06s
    both;
}


/* =========================================================
   LOGIN CARD HEADER
========================================================= */

.admin-login-card-heading {
  display:
    flex;

  gap:
    16px;

  margin-bottom:
    30px;
}

.admin-login-lock {
  width:
    52px;

  height:
    52px;

  flex:
    0 0 52px;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  border-radius:
    16px;

  background:
    #edf6eb;

  color:
    #4d8150;
}

.admin-login-card-heading .page-eyebrow {
  font-size:
    10px;

  font-weight:
    800;

  letter-spacing:
    0.15em;

  color:
    #68806a;
}

.admin-login-card-heading h2 {
  margin:
    5px 0 6px;

  font-size:
    30px;

  letter-spacing:
    -0.035em;

  color:
    #203f26;
}

.admin-login-card-heading p {
  margin:
    0;

  font-size:
    14px;

  line-height:
    1.6;

  color:
    #718071;
}


/* =========================================================
   FORM
========================================================= */

.admin-login-field {
  margin-bottom:
    20px;
}

.admin-login-field label {
  display:
    block;

  margin-bottom:
    8px;

  font-size:
    14px;

  font-weight:
    750;

  color:
    #304f34;
}

.admin-login-field small {
  display:
    block;

  margin-top:
    7px;

  font-size:
    12px;

  line-height:
    1.5;

  color:
    #829083;
}


/* inputs */

.admin-login-input {
  min-height:
    54px;

  display:
    flex;

  align-items:
    center;

  gap:
    10px;

  padding:
    0 14px;

  border-radius:
    14px;

  background:
    #f7faf6;

  border:
    1px solid
