}

.admin-login-input svg {
  flex:
    0 0 auto;

  color:
    #709070;
}

.admin-login-input input {
  width:
    100%;

  min-width:
    0;

  border:
    none;

  outline:
    none;

  background:
    transparent;

  font-size:
    15px;

  color:
    #28452d;
}

.admin-login-input input::placeholder {
  color:
    #9aa69b;
}


/* show password */

.admin-show-password {
  flex:
    0 0 auto;

  border:
    none;

  background:
    transparent;

  color:
    #5b805d;

  font-weight:
    700;

  cursor:
    pointer;
}

.admin-show-password:hover {
  color:
    #345e39;
}


/* =========================================================
   ERROR
========================================================= */

.admin-login-error {
  display:
    flex;

  align-items:
    center;

  gap:
    9px;

  margin:
    16px 0;

  padding:
    12px 14px;

  border-radius:
    12px;

  background:
    #fff4f1;

  border:
    1px solid
    rgba(202,94,73,0.16);

  color:
    #a55442;

  font-size:
    13px;

  animation:
    admin-error-shake
    0.35s ease;
}


/* =========================================================
   REMEMBER
========================================================= */

.admin-remember-row {
  display:
    flex;

  align-items:
    center;

  gap:
    9px;

  margin:
    4px 0 20px;

  font-size:
    13px;

  color:
    #657466;

  cursor:
    pointer;
}

.admin-remember-row input {
  accent-color:
    #588856;
}


/* =========================================================
   SUBMIT
========================================================= */

.admin-login-submit {
  width:
    100%;

  min-height:
    56px;

  border:
    none;

  border-radius:
    15px;

  background:
    linear-gradient(
      135deg,
      #4f8353,
      #67975a
    );

  color:
