  font-size:
    15px;

  font-weight:
    750;

  box-shadow:
    0 12px 24px
    rgba(72,120,74,0.18);

  cursor:
    pointer;

  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease,
    filter 0.3s ease;
}

.admin-login-submit:hover:not(:disabled) {
  transform:
    translateY(-3px);

  box-shadow:
    0 18px 30px
    rgba(72,120,74,0.24);

  filter:
    saturate(1.05);
}

.admin-login-submit:active:not(:disabled) {
  transform:
    translateY(-1px);
}


/* =========================================================
   DEMO BOX
========================================================= */

.admin-demo-box {
  margin-top:
    20px;

  padding:
    16px;

  display:
    flex;

  gap:
    13px;

  border-radius:
    15px;

  background:
    #f6f5ed;

  border:
    1px solid
    #e6e1cf;
}

.admin-demo-icon {
  width:
    40px;

  height:
    40px;

  flex:
    0 0 40px;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  border-radius:
    12px;

  background:
    #eee9d7;

  color:
    #8b7947;
}

.admin-demo-box span {
  display:
    block;

  margin-bottom:
    3px;

  font-size:
    9px;

  font-weight:
    800;

  letter-spacing:
    0.14em;

  color:
    #8b7947;
}

.admin-demo-box strong {
  display:
    block;

  margin-bottom:
    4px;

  font-size:
    14px;

  color:
    #514c36;
}

.admin-demo-box p {
  margin:
    0;

  font-size:
    12px;

  color:
    #77725e;
}


/* =========================================================
   SECURITY
========================================================= */

.admin-security-row {
  display:
    flex;

  gap:
    9px;

  margin-top:
    18px;

  padding-top:
    16px;

  border-top:
    1px solid
    #edf0eb;

  color:
    #839083;

  font-size:
    11px;

  line-height:
    1.5;
}


/* =========================================================
   TRUST STRIP
========================================================= */

.admin-login-trust {
  display:
    grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap:
    14px;

  margin-top:
    42px;
}

.admin-login-trust > div {
  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    8px;

  min-height:
    58px;

  border-radius:
    14px;

  background:
    rgba(255,255,255,0.64);

  border:
    1px solid
    rgba(55,85,59,0.07);

  color:
    #607261;

  font-size:
    12px;

  transition:
    transform 0.3s ease,
    background-color 0.3s ease;
}

.admin-login-trust > div:hover {
  transform:
    translateY(-3px);

  background:
    rgba(255,255,255,0.88);
}

.admin-login-trust svg {
  color:
    #63935e;
}


/* =========================================================
   FOOTER
========================================================= */

.admin-login-footer {
  position:
    relative;

  z-index:
    3;

  margin-top:
    auto;

  padding:
    24px 6%;

  border-top:
    1px solid
    rgba(53,84,57,0.07);

  background:
    rgba(255,255,255,0.60);

  color:
    #7b877d;

  font-size:
    12px;
}

.admin-login-footer strong {
  color:
    #466747;
}


/* =========================================================
   SPINNER
========================================================= */

.admin-login-spinner {
  width:
    17px;

  height:
    17px;

  display:
    inline-block;

  border:
    2px solid
    rgba(255,255,255,0.35);

  border-top-color:
    white;

  border-radius:
    50%;

  animation:
    admin-login-spin
    0.65s
    linear
    infinite;
}


/* =========================================================
   ANIMATIONS
========================================================= */

@keyframes admin-login-enter-left {

  from {
    opacity: 0;
    transform:
      translateX(-28px);
  }

  to {
    opacity: 1;
    transform:
      translateX(0);
  }

}

@keyframes admin-login-enter-right {

  from {
    opacity: 0;
    transform:
      translateX(28px);
  }

  to {
    opacity: 1;
    transform:
      translateX(0);
  }

}

@keyframes admin-bg-float-one {

  0%,
  100% {
    transform:
      translate(0, 0)
      scale(1);
  }

  50% {
    transform:
      translate(45px, -25px)
      scale(1.08);
  }

}

@keyframes admin-bg-float-two {

  0%,
  100% {
    transform:
      translate(0, 0)
      scale(1);
  }

  50% {
    transform:
      translate(-35px, -35px)
      scale(1.06);
  }

}

@keyframes admin-secure-pulse {

  0%,
  100% {
    box-shadow:
      0 0 0 4px
      rgba(99,162,95,0.08);
  }

  50% {
    box-shadow:
      0 0 0 8px
      rgba(99,162,95,0.03);
  }

}

@keyframes admin-error-shake {

  0%,
  100% {
    transform:
      translateX(0);
  }

  25% {
    transform:
      translateX(-4px);
  }

  75% {
    transform:
      translateX(4px);
  }

}

@keyframes admin-login-spin {

  to {
    transform:
      rotate(360deg);
  }

}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1050px) {

  .admin-login-container {
    width:
      min(
        920px,
        calc(100% - 40px)
      );
  }

  .admin-login-layout {
    grid-template-columns:
      1fr;

    gap:
      44px;

    min-height:
      auto;
  }

  .admin-login-intro {
    max-width:
      none;
  }

  .admin-login-card {
    justify-self:
      center;
  }

}


@media (max-width: 700px) {

  .admin-login-container {
    width:
      calc(100% - 28px);

    padding:
      38px 0 50px;
  }

  .admin-login-feature-grid {
    grid-template-columns:
      1fr;
  }

  .admin-login-intro h1 {
    font-size:
      46px;
  }

  .admin-login-intro > p {
    font-size:
      15px;
  }

  .admin-login-card {
    padding:
      24px 20px;

    border-radius:
      20px;
  }

  .admin-login-trust {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-workflow-steps {
    overflow-x:
      auto;

    padding-bottom:
      4px;
  }

}


@media (max-width: 480px) {

  .admin-login-header {
    padding-inline:
      14px;
  }

  .admin-login-brand strong {
    font-size:
      17px;
  }

  .admin-login-brand span {
    font-size:
      11px;
  }

  .admin-login-back {
    font-size:
      12px;
  }

  .admin-login-intro h1 {
    font-size:
      39px;
  }

  .admin-login-card-heading h2 {
    font-size:
      26px;
  }

  .admin-login-trust {
    grid-template-columns:
      1fr;
  }

}
/* =========================================================
   KRISHISETU PAGE TRANSITIONS
========================================================= */

.page-transition {
  animation:
    page-enter
    0.55s
    cubic-bezier(0.22, 1, 0.36, 1)
    both;
}

.page-transition-exit {
  animation:
    page-exit
    0.28s
    ease
    both;
}


/* Destination page */

@keyframes page-enter {

  from {
    opacity: 0;
    transform:
      translateY(14px);
  }

  to {
    opacity: 1;
    transform:
      translateY(0);
  }

}


/* Leaving page */

@keyframes page-exit {

  from {
    opacity: 1;
    transform:
      translateY(0);
  }

  to {
    opacity: 0;
    transform:
      translateY(-8px);
  }

}


/* Respect reduced-motion preference */

@media (prefers-reduced-motion: reduce) {

  .page-transition,
  .page-transition-exit {
    animation: none;
  }

}
/* =========================================================
   PREMIUM PAGE TRANSITION
========================================================= */

.page-transition-overlay {
  position: fixed;
  inset: 0;
  z-index: 99999;
  pointer-events: none;
  background:
    radial-gradient(
      circle at 50% 45%,
      rgba(86, 160, 92, 0.18),
      transparent 38%
    ),
    rgba(248, 250, 246, 0.96);

  opacity: 0;
  visibility: hidden;

  transform:
    scale(1.08);

  transition:
    opacity 0.55s cubic-bezier(.76, 0, .24, 1),
    visibility 0.55s,
    transform 0.8s cubic-bezier(.76, 0, .24, 1);
}


.page-transition-overlay.active {
  opacity: 1;
  visibility: visible;
  transform: scale(1);
}


.page-transition-glow {
  position: absolute;

  width: 45vw;
  height: 45vw;

  left: 50%;
  top: 50%;

  transform:
    translate(-50%, -50%);

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(95, 170, 98, 0.14),
      rgba(95, 170, 98, 0.04) 40%,
      transparent 70%
    );

  filter:
    blur(20px);

  animation:
    page-transition-pulse
    1.1s
    ease-out
    both;
}


.page-transition-content {
  opacity: 1;

  transform:
    translateY(0)
    scale(1);

  filter:
    blur(0);

  transition:
    opacity 0.7s cubic-bezier(.22, 1, .36, 1),
    transform 0.8s cubic-bezier(.22, 1, .36, 1),
    filter 0.7s ease;
}


.page-transition-content.active {
  opacity: 0;

  transform:
    translateY(18px)
    scale(0.985);

  filter:
    blur(8px);
}


@keyframes page-transition-pulse {

  0% {
    opacity: 0;
    transform:
      translate(-50%, -50%)
      scale(0.72);
  }

  45% {
    opacity: 1;
  }

  100% {
    opacity: 0;
    transform:
      translate(-50%, -50%)
      scale(1.15);
  }

}

.page-transition {
  min-height: 100%;
  width: 100%;
  will-change: transform, opacity, filter;
}

/* =========================================================
   ADMIN DASHBOARD
========================================================= */

.admin-dashboard-page {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
  padding: 8px 4px 40px;

  color: #17231b;
  background: #f7f9f6;
}


/* =========================================================
   HERO
========================================================= */

.admin-dashboard-hero {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;

  margin-bottom: 28px;
}

.admin-dashboard-hero > div:first-child {
  max-width: 780px;
}

.admin-dashboard-hero .admin-page-eyebrow {
  display: block;

  margin-bottom: 8px;

  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;

  color: #5f7d67;
}

.admin-dashboard-hero h2 {
  margin: 0;

  font-size: clamp(30px, 3vw, 42px);
  line-height: 1.08;
  letter-spacing: -0.035em;

  color: #18251d;
}

.admin-dashboard-hero p {
  margin: 12px 0 0;

  max-width: 700px;

  font-size: 16px;
  line-height: 1.7;

  color: #617067;
}


/* =========================================================
   HERO ACTIONS
========================================================= */

.admin-dashboard-actions {
  display: flex;
  align-items: center;
  gap: 10px;

  flex-shrink: 0;
}

.admin-dashboard-live {
  display: inline-flex;
  align-items: center;
  gap: 8px;

  min-height: 38px;
  padding: 0 13px;

  border: 1px solid #d9e6db;
  border-radius: 999px;

  background: #f2f7f2;

  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.11em;

  color: #52705b;
}

.admin-dashboard-live span {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: #4d9b63;

  box-shadow:
    0 0 0 4px rgba(77, 155, 99, 0.1);

  animation:
    admin-live-pulse 2s infinite;
}

.admin-dashboard-refresh {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  min-height: 38px;
  padding: 0 15px;

  border: 1px solid #d7dfd9;
  border-radius: 10px;

  background: #ffffff;

  color: #425248;

  font-size: 13px;
  font-weight: 700;

  cursor: pointer;

  transition:
    transform 0.2s ease,
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.admin-dashboard-refresh:hover {
  transform: translateY(-1px);

  border-color: #b8cbbd;

  box-shadow:
    0 6px 18px rgba(32, 50, 39, 0.07);
}

.admin-dashboard-refresh:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}


/* =========================================================
   ERROR
========================================================= */

.admin-dashboard-error {
  display: flex;
  align-items: center;
  gap: 13px;

  margin-bottom: 22px;
  padding: 15px 17px;

  border: 1px solid #f0d0c8;
  border-radius: 13px;

  background: #fff8f6;

  color: #9b4638;
}

.admin-dashboard-error svg {
  flex-shrink: 0;
}

.admin-dashboard-error > div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-dashboard-error strong {
  font-size: 14px;
  font-weight: 800;
}

.admin-dashboard-error span {
  font-size: 13px;
  color: #9c6860;
}


/* =========================================================
   KPI GRID
========================================================= */

.admin-dashboard-kpi-grid {
  display: grid;
  grid-template-columns:
    repeat(6, minmax(0, 1fr));

  gap: 14px;

  margin-bottom: 22px;
}


/* =========================================================
   KPI CARD
========================================================= */

.admin-dashboard-kpi {
  position: relative;

  display: flex;
  align-items: center;
  gap: 13px;

  min-width: 0;
  min-height: 104px;

  padding: 18px;

  border: 1px solid #e1e7e2;
  border-radius: 16px;

  background: #ffffff;

  box-shadow:
    0 4px 16px rgba(28, 43, 33, 0.04);

  overflow: hidden;

  transition:
    transform 0.22s ease,
    box-shadow 0.22s ease,
    border-color 0.22s ease;
}

.admin-dashboard-kpi::after {
  content: "";

  position: absolute;

  right: -28px;
  bottom: -35px;

  width: 90px;
  height: 90px;

  border-radius: 50%;

  background: currentColor;

  opacity: 0.035;
}

.admin-dashboard-kpi:hover {
  transform: translateY(-3px);

  box-shadow:
    0 12px 28px rgba(28, 43, 33, 0.08);

  border-color: #d3ddd5;
}

.admin-dashboard-kpi-icon {
  display: grid;
  place-items: center;

  flex-shrink: 0;

  width: 43px;
  height: 43px;

  border-radius: 12px;
}

.admin-dashboard-kpi > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-dashboard-kpi strong {
  display: block;

  font-size: 28px;
  line-height: 1;

  font-weight: 800;
  letter-spacing: -0.025em;

  color: #18251d;
}

.admin-dashboard-kpi strong small {
  font-size: 13px;
  font-weight: 700;
}

.admin-dashboard-kpi span {
  display: block;

  font-size: 12px;
  line-height: 1.35;

  font-weight: 650;

  color: #718077;
}


