.admin-dashboard-kpi.blue {
  color: #4178a3;
}

.admin-dashboard-kpi.blue
.admin-dashboard-kpi-icon {
  background: #eef5fa;
  color: #4178a3;
}

.admin-dashboard-kpi.purple {
  color: #746aa3;
}

.admin-dashboard-kpi.purple
.admin-dashboard-kpi-icon {
  background: #f2eff9;
  color: #746aa3;
}

.admin-dashboard-kpi.gold {
  color: #a88239;
}

.admin-dashboard-kpi.gold
.admin-dashboard-kpi-icon {
  background: #faf5e7;
  color: #a88239;
}

.admin-dashboard-kpi.green {
  color: #4b8a5b;
}

.admin-dashboard-kpi.green
.admin-dashboard-kpi-icon {
  background: #edf6ef;
  color: #4b8a5b;
}

.admin-dashboard-kpi.orange {
  color: #b77b4b;
}

.admin-dashboard-kpi.orange
.admin-dashboard-kpi-icon {
  background: #fbf1e8;
  color: #b77b4b;
}

.admin-dashboard-kpi.teal {
