  line-height: 1.3;
}


/* =========================================================
   HEADER ACTIONS
========================================================= */

.farmer-home-header-actions {
  display: flex;

  align-items: center;

  gap: 9px;

  margin-left: auto;
}


/* refresh */

.farmer-refresh-button {
  width: 46px;

  height: 46px;

  border:
    1px solid
    rgba(43, 74, 53, 0.10);

  border-radius: 14px;

  background: rgba(255,255,255,0.9);

  color: #5a7161;

  display: flex;

  align-items: center;

  justify-content: center;

  cursor: pointer;

  transition:
    transform .18s ease,
    box-shadow .18s ease,
    background .18s ease;
}


.farmer-refresh-button:hover {
  transform: translateY(-2px);

  background: #ffffff;

  box-shadow:
    0 9px 20px rgba(43, 69, 52, 0.10);
}


/* =========================================================
   NOTIFICATION
========================================================= */

.farmer-notification-button {
  position: relative;

  width: 52px;

  height: 52px;

  border:
    1px solid
    rgba(196, 149, 42, 0.28);

  border-radius: 15px;

  background:
    linear-gradient(
      145deg,
      #fff8d9,
      #f3df98
    );

  color: #9a7318;

  display: flex;

  align-items: center;

  justify-content: center;

  cursor: pointer;

  box-shadow:
    0 9px 22px rgba(173, 126, 19, 0.15),
    inset 0 1px 0 rgba(255,255,255,.85);

  transition:
    transform .18s ease,
    box-shadow .18s ease;
}


.farmer-notification-button svg {
  width: 24px;

  height: 24px;
}


.farmer-notification-button:hover,
.farmer-notification-button.open {
  transform: translateY(-2px);

  box-shadow:
    0 14px 29px rgba(173, 126, 19, 0.20),
    0 0 0 5px rgba(214, 171, 65, 0.08);
}


.farmer-notification-button.has-unread {
  animation:
    farmer-bell-pulse
    2.8s
    ease-in-out
    infinite;
}


@keyframes farmer-bell-pulse {

  0%,
  100% {
    box-shadow:
      0 9px 22px rgba(173, 126, 19, 0.15),
      0 0 0 0 rgba(214, 171, 65, 0);
  }

  50% {
    box-shadow:
      0 13px 27px rgba(173, 126, 19, 0.19),
      0 0 0 7px rgba(214, 171, 65, 0.08);
  }

}


.farmer-notification-count {
  position: absolute;

  top: -8px;

  right: -8px;

  min-width: 26px;

  height: 26px;

  padding: 0 7px;

  border-radius: 999px;

  background: #d84b43;

  border: 3px solid #fff;

  color: #fff;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 12px;

  font-weight: 800;

  box-shadow:
    0 5px 14px rgba(161, 54, 48, 0.22);
}


/* =========================================================
   MAIN BOOKING
========================================================= */

.next-booking-card {
  position: relative;

  overflow: hidden;

  border:
    1px solid
    rgba(40, 89, 54, 0.12);

  border-radius: 28px;

  padding: 31px;

  background:
    linear-gradient(
      135deg,
      #ffffff 0%,
      #f4faf4 100%
    );

  box-shadow:
    0 22px 58px rgba(36, 74, 48, 0.10),
    0 4px 12px rgba(36, 74, 48, 0.04);

  animation:
    farmer-card-rise
    .55s
    cubic-bezier(.2,.8,.2,1);
}


.next-booking-card::before {
  content: "";

  position: absolute;

  width: 330px;

  height: 330px;

  top: -160px;

  right: -120px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(91, 148, 94, 0.16),
      transparent 68%
    );

  pointer-events: none;
}


.next-booking-card::after {
  content: "";

  position: absolute;

  width: 190px;

  height: 190px;

  bottom: -100px;

  left: -70px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(222, 177, 62, 0.09),
      transparent 70%
    );

  pointer-events: none;
}


@keyframes farmer-card-rise {

  from {
    opacity: 0;

    transform:
      translateY(14px);
  }

  to {
    opacity: 1;

    transform:
      translateY(0);
  }

}


.next-booking-card.payment-complete {
  background:
    linear-gradient(
      135deg,
      #f7fcf5,
      #eef7ee
    );

  border-color:
    rgba(65, 130, 77, 0.18);
}


/* booking top */

.booking-card-top {
  position: relative;

  z-index: 2;

  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 24px;
}


.card-eyebrow {
  display: block;

  color: #64806d;

  font-size: 10.5px;

  letter-spacing: .14em;

  font-weight: 800;
}


.booking-token-row {
  display: flex;

  align-items: center;

  flex-wrap: wrap;

  gap: 11px;

  margin-top: 10px;
}


.home-token {
  padding: 8px 13px;

  border-radius: 11px;

  background: #edf5ee;

  color: #2d6240;

  font-size: 15px;

  font-weight: 800;

  letter-spacing: .02em;
}


.booking-confirmed-icon {
  width: 52px;

  height: 52px;

  border-radius: 16px;

  background:
    #edf6ee;

  color: #3b8050;

  display: flex;

  align-items: center;

  justify-content: center;

  box-shadow:
    inset 0 0 0 1px rgba(55, 122, 72, .08);
}


/* status message */

.booking-status-message {
  position: relative;

  z-index: 2;

  display: flex;

  align-items: flex-start;

  gap: 13px;

  margin-top: 27px;

  padding: 17px 18px;

  border-radius: 17px;

  background:
    rgba(244, 249, 244, .9);

  border:
    1px solid
    rgba(57, 111, 69, .08);
}


.status-message-icon {
  width: 36px;

  height: 36px;

  min-width: 36px;

  border-radius: 11px;

  background: #dfeee1;

  color: #39764a;

  display: flex;

  align-items: center;

  justify-content: center;
}


.booking-status-message > div:last-child {
  display: flex;

  flex-direction: column;

  gap: 4px;
}


.booking-status-message strong {
  color: #254b31;

  font-size: 14px;

  font-weight: 750;
}


.booking-status-message span {
  color: #6c7b71;

  font-size: 13px;

  line-height: 1.55;
}


/* details */

.booking-main-details {
  position: relative;

  z-index: 2;

  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 15px;

  margin-top: 17px;
}


.home-detail {
  display: flex;

  align-items: center;

  gap: 13px;

  min-height: 84px;

  padding: 14px 16px;

  border:
    1px solid
    rgba(37, 70, 48, .08);

  border-radius: 16px;

  background:
    rgba(255,255,255,.72);
}


.home-detail-icon {
  width: 40px;

  height: 40px;

  min-width: 40px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 12px;

  background: #f1f6f1;

  color: #4d7659;
}


.home-detail > div:last-child {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}


.home-detail > div:last-child span {
  color: #8a978e;

  font-size: 10.5px;

  font-weight: 700;

  text-transform: uppercase;

  letter-spacing: .07em;
}


.home-detail > div:last-child strong {
  color: #2b4634;

  font-size: 13.5px;

  font-weight: 750;
}


.home-detail > div:last-child small {
  color: #748178;

  font-size: 11.5px;
}


/* payment strip */

.home-payment-complete-strip {
  position: relative;

  z-index: 2;

  display: grid;

  grid-template-columns:
    repeat(2, minmax(0,1fr));

  gap: 12px;

  margin-top: 15px;

  padding: 16px;

  border-radius: 16px;

  background:
    linear-gradient(
      135deg,
      #eef8ee,
      #e4f2e6
    );

  border:
    1px solid
    rgba(49, 119, 67, .09);
}


.home-payment-complete-strip > div {
  display: flex;

  flex-direction: column;

  gap: 4px;
}


.home-payment-complete-strip span {
  color: #65816c;

  font-size: 10px;

  font-weight: 800;

  letter-spacing: .10em;
}


.home-payment-complete-strip strong {
  color: #28613b;

  font-size: 18px;

  font-weight: 800;
}


/* actions */

.booking-action-row {
  position: relative;

  z-index: 2;

  display: flex;

  align-items: center;

  gap: 11px;

  flex-wrap: wrap;

  margin-top: 20px;
}


/* =========================================================
   BUTTONS
========================================================= */

.home-primary-action,
.home-secondary-action {
  min-height: 45px;

  padding:
    0
    17px;

  border-radius: 13px;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 9px;

  font-size: 13px;

  font-weight: 750;

