  background:
    rgba(255,255,255,.82);

  color: #456351;
}


.home-secondary-action:hover {
  transform: translateY(-2px);

  background: #fff;

  box-shadow:
    0 9px 20px rgba(43, 70, 52, .08);
}


/* =========================================================
   QUICK ACTION CARDS
========================================================= */

.farmer-home-grid {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 16px;

  margin-top: 18px;
}


.home-feature-card {
