  font-size: 17px;

  line-height: 1.25;

  font-weight: 760;
}


.home-feature-card p {
  margin: 0;

  max-width: 330px;

  color: #718076;

  font-size: 12.5px;

  line-height: 1.6;
}


/* =========================================================
   GENERIC DASHBOARD SECTIONS
========================================================= */

.home-dashboard-section,
.home-month-summary-card,
.home-center-card,
.home-arrival-check-card,
.home-sms-card {
  border:
    1px solid
    rgba(42, 70, 50, .08);

  border-radius: 22px;

  background:
    rgba(255,255,255,.84);

  box-shadow:
    0 12px 35px rgba(34, 67, 45, .055);
}


/* spacing */

.home-dashboard-section,
.home-month-summary-card {
  margin-top: 18px;

  padding: 23px;
}


/* headings */

.home-section-heading {
  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 20px;

  margin-bottom: 18px;
}


.home-section-heading h2 {
  margin: 5px 0 0;

  color: #203f2b;

  font-size: 20px;

  line-height: 1.25;

  font-weight: 780;

  letter-spacing: -.015em;
}


.home-section-heading p {
  margin: 5px 0 0;

  color: #7a877e;

  font-size: 12px;
}


.home-inline-link {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  color: #3d7650;

  font-size: 12px;

  font-weight: 750;

  text-decoration: none;

