}


.home-inline-link:hover {
  color: #255d38;

  transform:
    translateX(2px);
}


/* =========================================================
   MONTH SUMMARY
========================================================= */

.home-month-summary-card {
  background:
    linear-gradient(
      145deg,
      rgba(255,255,255,.95),
      rgba(244,249,244,.90)
    );
}


.home-month-stats {
