  border-radius: 16px;

  background: #f5f8f4;

  border:
    1px solid
    rgba(44, 76, 53, .07);
}


.home-month-stat span {
  display: block;

  color: #7c8a80;

  font-size: 10.5px;

  font-weight: 750;

  text-transform: uppercase;

  letter-spacing: .07em;
}


.home-month-stat strong {
  display: block;

  margin-top: 5px;

  color: #284a34;

  font-size: 21px;

  line-height: 1.15;

  font-weight: 800;
}


.home-month-stat.green {
  background:
    linear-gradient(
      145deg,
      #eef7ef,
      #f7faf6
    );
}


.home-month-stat.blue {
  background:
    linear-gradient(
      145deg,
      #f0f5f7,
      #f8faf9
    );
}


.home-month-stat.orange {
  background:
    linear-gradient(
      145deg,
      #f8f3e9,
      #fbfaf5
    );
}


/* crop rows */

.home-crop-summary-list {
  margin-top: 14px;
}


.home-crop-summary-row {
  display: grid;

  grid-template-columns:
    auto
    minmax(0,1fr)
    auto;

