}


.home-crop-summary-icon {
  width: 36px;

  height: 36px;

  border-radius: 11px;

  display: flex;

  align-items: center;

  justify-content: center;

  background: #edf5ee;

  color: #477c54;
}


.home-crop-summary-row > div:nth-child(2) {
