.home-payment-row {
  grid-template-columns:
    auto
    minmax(0,1fr)
    auto
    auto;
}


.home-recent-row {
  grid-template-columns:
    auto
    minmax(0,1fr)
    auto
    auto;
}


.home-upcoming-row:last-child,
