/* =========================================================
   SMS / STATUS CARD
========================================================= */

.home-sms-card {
  display: flex;

  align-items: flex-start;

  gap: 16px;

  margin-top: 18px;

  padding: 22px;

  background:
    linear-gradient(
      135deg,
      #fffaf0,
      #fffdf8
    );

