/* =========================================================
   FARMER NOTIFICATION PORTAL
========================================================= */

.farmer-notification-overlay {
  position: fixed;

  inset: 0;

  z-index: 2147483647;

  display: flex;

  justify-content: flex-end;

  background:
    rgba(22, 30, 24, 0.18);

  backdrop-filter:
    blur(3px);

  -webkit-backdrop-filter:
    blur(3px);

  animation:
    farmer-notification-overlay-in
    180ms
    ease-out;
}


.farmer-notification-panel {
  width: min(
    700px,
    calc(100vw - 28px)
  );

  height: calc(
    100vh - 28px
  );

  margin: 14px;

  display: flex;

  flex-direction: column;

  background: #ffffff;

  border:
    1px solid
    rgba(63, 70, 48, 0.10);

  border-radius: 26px;

  overflow: hidden;

  box-shadow:
    0 30px 90px
    rgba(28, 36, 29, 0.24);

  animation:
    farmer-notification-panel-in
    240ms
    cubic-bezier(
      .2,
      .8,
      .2,
      1
    );
}


@keyframes farmer-notification-overlay-in {

  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }

}


@keyframes farmer-notification-panel-in {

  from {
    opacity: 0;

    transform:
      translateX(32px)
      scale(.98);
  }

  to {
    opacity: 1;

    transform:
      translateX(0)
      scale(1);
  }

}


/* HEADER */

.farmer-notification-header {
  flex-shrink: 0;

  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 20px;

  padding:
    28px
    30px
    23px;

  background:
    linear-gradient(
      180deg,
      #fff8df 0%,
      #fffdf6 60%,
      #ffffff 100%
    );

  border-bottom:
    1px solid
    #eee7d6;
}


.farmer-notification-header .page-eyebrow {
  display: block;

  margin-bottom: 7px;

  color: #a07819;
}


.farmer-notification-header strong {
  display: block;

  color: #3e341d;

  font-size: 21px;

  line-height: 1.3;

  font-weight: 800;
}


/* CLOSE */

.farmer-notification-close {
  width: 40px;

  height: 40px;

  flex-shrink: 0;

  display: flex;

  align-items: center;

  justify-content: center;

  border: 0;

  border-radius: 11px;

  background:
    #f6edd0;

  color: #746b55;

  cursor: pointer;
}

.farmer-notification-close:hover {
  background:
    #efe1b8;

  color: #4d442d;
}


/* LIST */

.farmer-notification-list {
  flex: 1;

  min-height: 0;

  overflow-y: auto;

  background:
    #ffffff;
}


/* ITEM */

.farmer-notification-item {
  width: 100%;

  min-height: 125px;

  display: flex;

  align-items: flex-start;

  gap: 17px;

  padding:
    23px
    30px;

  border: 0;

  border-bottom:
    1px solid
    #ecece7;

  background:
    #ffffff;

  text-align: left;

  cursor: pointer;

  transition:
    background .18s ease,
    padding-left .18s ease;
}


.farmer-notification-item:hover {
  padding-left: 35px;

  background:
    #fffdf8;
}


.farmer-notification-item.unread {
  background:
    linear-gradient(
      90deg,
      rgba(219, 173, 43, .14),
      rgba(219, 173, 43, .025)
    );
}


/* DOT */

.farmer-notification-dot {
  width: 11px;

  height: 11px;

  min-width: 11px;

  margin-top: 7px;

  border-radius: 50%;

  background:
    #aaa69c;
}


.farmer-notification-item.unread
.farmer-notification-dot {
  background:
    #d3a22d;

  box-shadow:
    0 0 0 6px
    rgba(211, 162, 45, .12);
}


/* CONTENT */

.farmer-notification-content {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 7px;
}


.farmer-notification-content strong {
  color: #3f351f;

  font-size: 15px;

  line-height: 1.4;

  font-weight: 800;
}


.farmer-notification-content span {
  color: #716b5d;

  font-size: 13px;

  line-height: 1.65;
}


.farmer-notification-content small {
  margin-top: 2px;

  color: #999184;

  font-size: 11px;
}


/* EMPTY */

.farmer-notification-empty {
  height: 100%;

  min-height: 350px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  gap: 12px;

  color: #898477;

  font-size: 14px;

  text-align: center;
}


/* MOBILE */

@media (max-width: 700px) {

  .farmer-notification-panel {
    width: calc(
      100vw - 20px
    );

    height: calc(
      100vh - 20px
    );

    margin: 10px;

    border-radius: 22px;
  }

  .farmer-notification-header {
    padding:
      22px
      20px
      18px;
  }

  .farmer-notification-item {
    padding:
      19px
      20px;
  }

  .farmer-notification-item:hover {
    padding-left: 24px;
  }

