  justify-content: center;

  gap: 11px;

  padding: 30px;

  text-align: center;

  border:
    1px solid
    rgba(41,77,51,.09);

  border-radius: 24px;

  background:
    rgba(255,255,255,.9);

  box-shadow:
    0 16px 40px
