  background:
    linear-gradient(
      145deg,
      #f8fcf8,
      #f0f8f1
    );
}


.token-sms-card:has(
  .sms-failed
) {
  border-color:
    #e3bbb2;

  background:
    #fff9f7;
}


.token-sms-card h3 {
  margin:
    8px
    0
    7px;

  color:
    #344d3b;

  font-size:
    16px;

  line-height:
    1.3;

  font-weight:
    810;
}


.token-sms-card p {
  margin:
    0;

  color:
    #7d8980;

  font-size:
    11px;

  line-height:
    1.6;
}


