/* =========================================================
   HISTORY / MONTH
========================================================= */

.token-history-count {
  padding:
    6px
    10px;

  border-radius:
    999px;

  background:
    #eef4ee;

  color:
    #5b7461;

  font-size:
    10px;

  font-weight:
    800;
}


.token-history-loading,
