  min-height:
    190px;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  flex-direction:
    column;

  gap:
    9px;

  padding:
    25px;

  text-align:
    center;

  color:
    #89938c;

  font-size:
    12px;
}


