  border-radius:
    11px;

  background:
    #edf5ee;

  color:
    #568360;
}


.token-crop-main strong,
.token-crop-quantity strong {
  color:
    #405747;

  font-size:
    12px;

  font-weight:
    780;
}


.token-crop-main span,
.token-crop-quantity span {
  display:
    block;

  margin-top:
    2px;

  color:
    #929b95;

  font-size:
    10px;
}


.token-crop-quantity {
  text-align:
    right;
}


/* =========================================================
   BOTTOM ACTIONS
========================================================= */

.token-bottom-actions {
  display:
    flex;

  justify-content:
    space-between;

  align-items:
    center;

  gap:
    12px;

  margin-top:
    21px;
}


.token-primary-action,
.token-secondary-action {
  min-height:
    45px;

  padding:
    0
    17px;

  border-radius:
    12px;

  display:
    inline-flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    8px;

  text-decoration:
    none;

  font-size:
    12px;

  font-weight:
    760;
}


.token-primary-action {
  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      #39764a,
      #275e38
    );

  box-shadow:
    0 8px 20px
    rgba(
      40,
      101,
      59,
      .17
    );
}


.token-secondary-action {
  color:
    #64746a;

  background:
    #ffffff;

  border:
    1px solid
    #dce4dd;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1000px) {

  .token-main-layout {
    grid-template-columns:
      1fr;
  }

  .token-side-column {
    position:
      static;

    display:
      grid;

    grid-template-columns:
      repeat(
        2,
        minmax(
          0,
          1fr
        )
      );
  }

  .token-visual-card {
    grid-column:
      1 / -1;
  }

}


@media (max-width: 700px) {

  .token-container {
    width:
      calc(
        100% - 22px
      );

    padding:
      20px
      0
      45px;
  }

  .token-top-row {
    flex-direction:
      column;
  }

  .token-database-card {
    width:
      100%;

    box-sizing:
      border-box;
  }

  .token-arrival-grid {
    grid-template-columns:
      1fr;
  }

  .token-payment-grid,
  .token-month-summary {
    grid-template-columns:
      1fr;
  }

  .token-details-grid {
    grid-template-columns:
      1fr;
  }

  .token-side-column {
    grid-template-columns:
      1fr;
  }

  .token-payment-history-row {
    grid-template-columns:
      1fr
      auto;

    gap:
      8px;
  }

  .token-history-crop {
    grid-column:
      1 / -1;
  }

  .token-history-amount {
    text-align:
      left;
  }

  .token-history-check {
    display:
      none;
  }

  .token-bottom-actions {
    flex-direction:
      column-reverse;

    align-items:
      stretch;
  }

  .token-primary-action,
  .token-secondary-action {
    width:
      100%;
  }

  .token-hero-top {
    padding:
      23px
      21px
      18px;
  }

  .token-arrival-grid,
  .token-status-timeline,
  .token-payment-history-list,
  .token-crop-breakdown {
    padding-left:
      21px;

    padding-right:
      21px;
  }

  .token-section-heading {
    padding-left:
      21px;

    padding-right:
      21px;
  }

  .token-progress-bar {
    margin-left:
      21px;

    margin-right:
      21px;
  }

  .token-current-message,
  .token-arrival-reminder,
  .token-sms-confirmation {
    margin-left:
      21px;

    margin-right:
      21px;
  }

}

