  margin: 0;
  padding: 0;
}


/* Remove accidental width limits from the main landing area */
.landing-page > main {
  width: 100%;
  max-width: none;
  margin: 0;
  padding: 0;
}


/* Hero must use the complete viewport */
.landing-hero {
  width: 100%;
  max-width: none;

  margin-left: 0;
  margin-right: 0;
}


/* Prevent common global container rules from narrowing
   only the landing hero */
.landing-hero,
.landing-hero-content,
.landing-hero-visual {
  box-sizing: border-box;
}


/* =========================================================
   REMOVE SIDE GAPS CAUSED BY GLOBAL CONTAINERS
========================================================= */

.landing-hero {
  margin-inline: 0 !important;
}


/* If the hero content itself has artificial side padding,
   keep a controlled edge instead of the large empty strips */
.landing-hero-content {
  margin-left: 0;
}


/* =========================================================
   FULL-WIDTH HERO SPACE
========================================================= */

@media (min-width: 1001px) {

  .landing-hero {
    display: grid;

    grid-template-columns:
      minmax(0, 1fr)
      minmax(
        520px,
        0.95fr
      );

    width: 100%;

    max-width: none;

    padding-left: clamp(
      28px,
      4vw,
      90px
    );

    padding-right: clamp(
      20px,
      3vw,
      60px
    );

    box-sizing: border-box;
  }


  .landing-hero-content {

    grid-column: 1;

    width: 100%;

    max-width: 760px;

    margin: 0;

    position: relative;

    z-index: 5;
  }


  .landing-hero-visual {

    grid-column: 2;

    width: 100% !important;

    height: 100% !important;

    position: relative !important;

    inset: auto !important;

    transform: none !important;

    display: flex !important;

    align-items: center !important;

    justify-content: center !important;
  }

}

/* =========================================================
   LANDING RADAR — CLEAN RESET
========================================================= */

.landing-hero-visual {
  position: relative !important;

  width: 100% !important;
  height: 100% !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  overflow: visible !important;

  z-index: 2 !important;
}


/* =========================================================
   RADAR
========================================================= */

.procurement-radar {
  position: relative !important;

  width: 620px !important;
  height: 620px !important;

  max-width: 100%;
  max-height: 100%;

  flex-shrink: 0;

  isolation: isolate;
}


/* =========================================================
   GLOW
========================================================= */

.procurement-radar-glow {
  position: absolute;

  left: 8%;
  right: 8%;
  top: 8%;
  bottom: 8%;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(45, 170, 100, 0.18),
      rgba(45, 170, 100, 0.06) 42%,
      transparent 72%
    );

  filter: blur(24px);

  z-index: -2;
}


/* =========================================================
   ORBITS
========================================================= */

.procurement-radar-orbit {
  position: absolute;

  left: 50%;
  top: 50%;

  border-radius: 50%;

  transform: translate(-50%, -50%);

  pointer-events: none;
}


.procurement-radar-orbit-outer {
  width: 90%;
  height: 90%;

  border: 1px solid rgba(36, 140, 82, 0.22);

  animation:
    radar-spin-outer
    32s
    linear
    infinite;
}


.procurement-radar-orbit-middle {
  width: 69%;
  height: 69%;

  border: 1px dashed rgba(36, 140, 82, 0.20);

  animation:
    radar-spin-middle
    22s
    linear
    infinite reverse;
}


.procurement-radar-orbit-inner {
  width: 47%;
  height: 47%;

  border: 1px solid rgba(36, 140, 82, 0.14);
}


/* =========================================================
   SWEEP
========================================================= */

.procurement-radar-sweep {
  position: absolute;

  left: 50%;
  top: 50%;

  width: 45%;
  height: 45%;

  transform-origin: 0 100%;

  background:
    conic-gradient(
      from 0deg,
      transparent,
      rgba(36, 168, 94, 0.16),
      transparent 65%
    );

  clip-path:
    polygon(
      100% 100%,
      100% 0,
      0 0
    );

  animation:
    radar-sweep
    5s
    linear
    infinite;

  pointer-events: none;
}


