========================================================= */

.procurement-radar-node {
  position: absolute;

  width: 28%;

  min-height: 62px;

  padding: 10px 12px;

  display: flex;

  align-items: center;

  gap: 9px;

  border:
    1px solid
    rgba(
      36,
      126,
      81,
      0.16
    );

  border-radius: 17px;

  background:
    rgba(
      255,
      255,
      255,
      0.92
    );

  color: #174b35;

  box-shadow:
    0 16px 35px
    rgba(
      28,
      90,
      61,
      0.11
    );

  backdrop-filter: blur(12px);

  cursor: pointer;

  text-align: left;

  z-index: 10;

  transition:
    transform 0.22s ease,
    box-shadow 0.22s ease,
    border-color 0.22s ease;
}


.procurement-radar-node:hover,
.procurement-radar-node.active,
.procurement-radar-node:focus-visible {
  transform:
    translateY(-5px)
    scale(1.025);

  border-color:
    rgba(
      24,
      145,
      83,
      0.35
    );

  box-shadow:
    0 24px 44px
    rgba(
      28,
      104,
      68,
      0.18
    );

  outline: none;
}


