      255,
      255,
      0.70
    );

  color: #517968;

  font-size: 9px;

  font-weight: 800;
}


/* =========================================================
   ANIMATIONS
========================================================= */

@keyframes radar-spin-outer {

  from {
    transform:
      translate(-50%, -50%)
      rotate(0deg);
  }

  to {
    transform:
      translate(-50%, -50%)
      rotate(360deg);
  }

}


@keyframes radar-spin-middle {

  from {
    transform:
      translate(-50%, -50%)
      rotate(0deg);
  }

  to {
    transform:
      translate(-50%, -50%)
      rotate(-360deg);
  }

}


@keyframes radar-sweep {

  from {
    transform:
      translate(-100%, 0)
      rotate(0deg);
  }

  to {
    transform:
      translate(-100%, 0)
      rotate(360deg);
  }

}


@keyframes radar-pulse {

  0%,
  100% {
    transform: scale(1);
    opacity: 0.65;
  }

  50% {
    transform: scale(1.35);
    opacity: 1;
  }

}


