.orbital-field {
  position: absolute;

  left: 50%;
  top: 50%;

  width: 190%;
  height: 135%;

  transform:
    translate(-50%, -50%)
    rotate(-7deg);

  overflow: visible !important;

  pointer-events: none;
}


/* =========================================================
   KEEP CONTENT ABOVE THE ORBITS
========================================================= */

.landing-hero-content {
  position: relative !important;
  z-index: 10 !important;
}
/* =========================================================
   ELLIPSE-BOUND STATUS CARDS
   Clock = right-center of the ellipse
========================================================= */

.orbital-status-card {
  position: absolute;

  width: clamp(
    145px,
    10.5vw,
    180px
  );

  min-height: 64px;

  box-sizing: border-box;

  z-index: 8;
}


/* =========================================================
   TOP-LEFT / TOP BOUNDARY
========================================================= */

.orbital-status-one {
  left: 34%;
  top: 13%;

  transform:
    translate(-50%, -50%)
    rotate(-2deg);
}


/* =========================================================
   UPPER-RIGHT
   Closer to the clock
========================================================= */

.orbital-status-two {
  left: 72%;
  top: 29%;

  transform:
    translate(-50%, -50%)
    rotate(2deg);
}


/* =========================================================
   LOWER-RIGHT
   Closer to clock than left cards
========================================================= */

.orbital-status-three {
  left: 71%;
  top: 71%;

  transform:
    translate(-50%, -50%)
    rotate(-1.5deg);
}


/* =========================================================
   LOWER-LEFT
   Deliberately farther from clock
========================================================= */

.orbital-status-four {
  left: 28%;
  top: 76%;

  transform:
    translate(-50%, -50%)
    rotate(2deg);
}


/* =========================================================
   LEFT-MIDDLE
   Farthest point from clock
========================================================= */

.orbital-status-five {
  left: 16%;
  top: 45%;

  transform:
    translate(-50%, -50%)
    rotate(-2deg);
}
/* =========================================================
   WIDE ELLIPSE
========================================================= */

.orbital-field {
  position: absolute;

  left: 50%;
  top: 50%;

  width: 205%;
  height: 135%;

  transform:
    translate(-50%, -50%);

  overflow: visible !important;

  pointer-events: none;
}
.ring-one {
  width: 100%;
  height: 64%;
}

