  --theme-bg:
    #050607;

  --theme-surface:
    #0b0e0f;

  --theme-surface-2:
    #111516;

  --theme-surface-3:
    #171c1d;

  --theme-border:
    #263031;

  /* IMPORTANT:
     never use pure white for normal body text */
  --theme-text:
    #edf3ef;

  --theme-text-soft:
    #c4d0ca;

  --theme-text-muted:
    #98a9a1;

  --theme-primary:
    #42cf88;

  --theme-primary-strong:
    #63dda0;

  --theme-primary-soft:
    #123f2c;

  --theme-accent:
    #edbb55;

  --theme-accent-soft:
