  --theme-blue:
    #67a8ff;

  --theme-blue-soft:
    #152e4d;

  --theme-danger:
    #ff7474;

  --theme-danger-soft:
    #481c20;

  --theme-success:
    #4fdb91;

  --theme-success-soft:
    #123b29;

  --theme-shadow:
    rgba(0, 0, 0, 0.42);

