/* =========================================================
   KRISHISETU — GLOBAL STATIC BOX / HOVER FIX
   ---------------------------------------------------------
   Fixes:
   • pale static cards becoming white
   • dark text disappearing on dark themes
   • icons becoming unreadable
   • hover turning cards bright white
   • colored green/blue/gold/purple/orange boxes losing contrast

   Put this AFTER all other theme CSS.
========================================================= */


/* =========================================================
   1. GLOBAL STATIC BOX SURFACES
========================================================= */

[data-theme="dark"] [class*="card"],
[data-theme="dark"] [class*="box"],
[data-theme="dark"] [class*="panel"],
[data-theme="dark"] [class*="topic"],
[data-theme="dark"] [class*="feature"],
[data-theme="dark"] [class*="guide"],
[data-theme="dark"] [class*="contact"],
[data-theme="dark"] [class*="quick"],
[data-theme="dark"] [class*="info"],
[data-theme="dark"] [class*="demo"],
[data-theme="dark"] [class*="security"],
[data-theme="dark"] [class*="support"],
[data-theme="dark"] [class*="note"],

[data-theme="forest"] [class*="card"],
[data-theme="forest"] [class*="box"],
[data-theme="forest"] [class*="panel"],
[data-theme="forest"] [class*="topic"],
[data-theme="forest"] [class*="feature"],
[data-theme="forest"] [class*="guide"],
[data-theme="forest"] [class*="contact"],
[data-theme="forest"] [class*="quick"],
[data-theme="forest"] [class*="info"],
[data-theme="forest"] [class*="demo"],
[data-theme="forest"] [class*="security"],
[data-theme="forest"] [class*="support"],
[data-theme="forest"] [class*="note"],

[data-theme="midnight"] [class*="card"],
[data-theme="midnight"] [class*="box"],
[data-theme="midnight"] [class*="panel"],
[data-theme="midnight"] [class*="topic"],
[data-theme="midnight"] [class*="feature"],
[data-theme="midnight"] [class*="guide"],
[data-theme="midnight"] [class*="contact"],
[data-theme="midnight"] [class*="quick"],
[data-theme="midnight"] [class*="info"],
[data-theme="midnight"] [class*="demo"],
[data-theme="midnight"] [class*="security"],
[data-theme="midnight"] [class*="support"],
[data-theme="midnight"] [class*="note"] {

  background-color:
    var(--theme-surface) !important;

  color:
    var(--theme-text) !important;

  border-color:
    var(--theme-border) !important;

}


/* =========================================================
   2. COLORED STATIC BOXES
   Keep their identity, but use dark versions of the tone.
========================================================= */


/* GREEN */

[data-theme="dark"] [class*="green"],
[data-theme="forest"] [class*="green"],
[data-theme="midnight"] [class*="green"] {

  background:
    color-mix(
      in srgb,
      var(--theme-primary-soft) 78%,
      var(--theme-surface) 22%
    ) !important;

  color:
    var(--theme-text) !important;

  border-color:
    color-mix(
      in srgb,
      var(--theme-primary) 30%,
      var(--theme-border) 70%
    ) !important;
}


/* BLUE */

[data-theme="dark"] [class*="blue"],
[data-theme="forest"] [class*="blue"],
[data-theme="midnight"] [class*="blue"] {

  background:
    color-mix(
      in srgb,
      var(--theme-secondary-soft) 78%,
      var(--theme-surface) 22%
    ) !important;

  color:
    var(--theme-text) !important;

  border-color:
    color-mix(
      in srgb,
      var(--theme-secondary) 28%,
      var(--theme-border) 72%
    ) !important;
}


/* GOLD / YELLOW */

[data-theme="dark"] [class*="gold"],
[data-theme="dark"] [class*="yellow"],

[data-theme="forest"] [class*="gold"],
[data-theme="forest"] [class*="yellow"],

[data-theme="midnight"] [class*="gold"],
[data-theme="midnight"] [class*="yellow"] {

  background:
    color-mix(
      in srgb,
      var(--theme-gold-soft) 78%,
      var(--theme-surface) 22%
    ) !important;

  color:
    var(--theme-text) !important;

  border-color:
    color-mix(
      in srgb,
      var(--theme-gold) 26%,
      var(--theme-border) 74%
    ) !important;
}


/* PURPLE */

[data-theme="dark"] [class*="purple"],
[data-theme="forest"] [class*="purple"],
[data-theme="midnight"] [class*="purple"] {

  background:
    color-mix(
      in srgb,
      #3b3154 70%,
      var(--theme-surface) 30%
    ) !important;

  color:
    var(--theme-text) !important;

  border-color:
    rgba(
      173,
      143,
      220,
      0.18
    ) !important;
}


/* ORANGE */

[data-theme="dark"] [class*="orange"],
[data-theme="forest"] [class*="orange"],
[data-theme="midnight"] [class*="orange"] {

  background:
    color-mix(
      in srgb,
      #493523 72%,
      var(--theme-surface) 28%
    ) !important;

  color:
    var(--theme-text) !important;

  border-color:
    rgba(
      214,
      156,
      85,
      0.18
    ) !important;
}


/* TEAL */

[data-theme="dark"] [class*="teal"],
[data-theme="forest"] [class*="teal"],
[data-theme="midnight"] [class*="teal"] {

  background:
    color-mix(
