  color:
    var(--theme-text) !important;

  border-color:
    var(--theme-border) !important;

}


/* =========================================================
   6. HOVERED TEXT MUST STAY VISIBLE
========================================================= */

[data-theme="dark"] [class*="card"]:hover h1,
[data-theme="dark"] [class*="card"]:hover h2,
[data-theme="dark"] [class*="card"]:hover h3,
[data-theme="dark"] [class*="card"]:hover h4,
[data-theme="dark"] [class*="card"]:hover strong,

