[data-theme="dark"] [class*="input"],
[data-theme="dark"] [class*="field"],
[data-theme="dark"] [class*="row"],

[data-theme="forest"] [class*="input"],
[data-theme="forest"] [class*="field"],
[data-theme="forest"] [class*="row"],

