   Catch common old rules.
========================================================= */

[data-theme="dark"] [class*="card"]:hover,
[data-theme="dark"] [class*="box"]:hover,
[data-theme="dark"] [class*="panel"]:hover,

[data-theme="forest"] [class*="card"]:hover,
[data-theme="forest"] [class*="box"]:hover,
[data-theme="forest"] [class*="panel"]:hover,

[data-theme="midnight"] [class*="card"]:hover,
[data-theme="midnight"] [class*="box"]:hover,
[data-theme="midnight"] [class*="panel"]:hover {

  filter:
    none !important;
}


/* =========================================================
   10. KEEP BOX SHADOWS SUBTLE
========================================================= */

[data-theme="dark"] [class*="card"],
[data-theme="dark"] [class*="box"],
[data-theme="dark"] [class*="panel"],

[data-theme="forest"] [class*="card"],
[data-theme="forest"] [class*="box"],
