/* =========================================================
   KRISHISETU — FINAL THEME STABILITY LAYER
   ---------------------------------------------------------
   Production-style theme architecture:
   • semantic color tokens
   • stable dark surfaces
   • intentional hover states
   • no white hover flash
   • no scroll color flicker
   • no layout changes
   • no backend changes
========================================================= */


/* =========================================================
   1. THEME TOKENS
========================================================= */

:root {
  --theme-page-bg: #f5f7f5;

  --theme-surface-1: #ffffff;
  --theme-surface-2: #f2f5f3;
  --theme-surface-hover: #e9efeb;

  --theme-border: #d9e1dc;

  --theme-heading: #1b382b;
  --theme-text: #355244;
  --theme-muted: #71857b;

  --theme-green: #2a7c53;
  --theme-blue: #547da0;
  --theme-gold: #b98732;

  --theme-shadow:
    0 14px 34px rgba(20, 53, 39, 0.09);
}


/* =========================================================
   2. DARK
========================================================= */

[data-theme="dark"] {
  --theme-page-bg: #0b0d0e;

  --theme-surface-1: #121516;
  --theme-surface-2: #181c1d;
  --theme-surface-hover: #1d2324;

  --theme-border: #2b3334;

  --theme-heading: #e3ebe6;
  --theme-text: #c3d0c9;
  --theme-muted: #91a099;

  --theme-green: #69b28a;
  --theme-blue: #7f9fbc;
  --theme-gold: #c7a45f;

  --theme-shadow:
    0 14px 36px rgba(0, 0, 0, 0.34);
}


/* =========================================================
   3. FOREST
========================================================= */

[data-theme="forest"] {
  --theme-page-bg: #0d1912;

  --theme-surface-1: #12251a;
  --theme-surface-2: #173020;
  --theme-surface-hover: #1d3a27;

  --theme-border: #31503b;

  --theme-heading: #e5ece2;
  --theme-text: #c8d5c7;
  --theme-muted: #9eae9d;

  --theme-green: #82b878;
  --theme-blue: #7ca28c;
  --theme-gold: #c5a15a;

  --theme-shadow:
    0 14px 36px rgba(0, 0, 0, 0.30);
}


/* =========================================================
