}


/* =========================================================
   URGENCY
========================================================= */

.admin-full-status-cell {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 5px;
}

.admin-queue-urgency {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  padding: 3px 6px;
  border-radius: 999px;
