/* =========================================================
   BOOKING CONFIRMATION OVERLAY
========================================================= */

.booking-confirmed-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(10, 25, 18, 0.58);
  backdrop-filter: blur(8px);
}

.booking-confirmed-card {
  width: min(420px, 100%);
  padding: 32px 28px;
  text-align: center;
  border-radius: 22px;
  background: var(--theme-surface, #ffffff);
  border: 1px solid var(--theme-border, rgba(120, 140, 130, 0.18));
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.22);
}

.booking-confirmed-icon {
  width: 58px;
  height: 58px;
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 18px;
  background: rgba(45, 124, 84, 0.12);
  color: var(--theme-primary, #2d7c54);
}

.booking-confirmed-card h2 {
  margin: 8px 0 10px;
}

.booking-confirmed-card p {
  margin: 0 0 18px;
  opacity: 0.72;
  line-height: 1.55;
}

.slot-card.past {
  opacity: 0.42;
  cursor: not-allowed;
}

.slot-card.past:hover {
  transform: none !important;
}

.slot-card.past .slot-card-footer {
  opacity: 0.7;
}


/* =========================================================
   PAYMENT PAGE - NEW ENHANCEMENTS
   Add this at the END of your existing admin CSS
========================================================= */


/* =========================================================
   PAYMENT INSIGHT STRIP
========================================================= */

.admin-payment-insight-strip {

  display: flex;

  align-items: center;

  gap: 14px;

  width: 100%;

  padding: 15px 18px;

  margin: 18px 0;

  border: 1px solid
    color-mix(
      in srgb,
      var(--admin-accent, #4f8f68) 20%,
      transparent
    );

  border-radius: 14px;

  background:
    color-mix(
      in srgb,
      var(--admin-surface, #ffffff) 94%,
      var(--admin-accent, #4f8f68)
    );

  box-sizing: border-box;

}


.admin-payment-insight-icon {

  width: 38px;

  height: 38px;

  min-width: 38px;

  display: grid;

  place-items: center;

  border-radius: 11px;

  background:
    rgba(61, 126, 87, 0.12);

  color:
    #3d7e57;

}


.admin-payment-insight-strip > div:nth-child(2) {

  min-width: 0;

  flex: 1;

}


.admin-payment-insight-strip strong {

  display: block;

  margin-bottom: 3px;

  font-size: 14px;

  line-height: 1.35;

  font-weight: 700;

}


.admin-payment-insight-strip span {

  display: block;

  font-size: 12px;

  line-height: 1.5;

  opacity: 0.72;

}


.admin-payment-insight-amount {

  text-align: right;

  flex-shrink: 0;

}


.admin-payment-insight-amount span {

  margin-bottom: 3px;

  font-size: 10px;

  text-transform: uppercase;

  letter-spacing: 0.08em;

}


.admin-payment-insight-amount strong {

  margin: 0;

  font-size: 16px;

}


/* =========================================================
   PAYMENT MODAL SUMMARY
========================================================= */

.admin-payment-form-summary {

  display: flex;

  flex-direction: column;

  gap: 14px;

  padding: 15px;

  margin-bottom: 18px;

  border: 1px solid
    rgba(120, 140, 125, 0.16);

  border-radius: 14px;

  background:
    rgba(120, 140, 125, 0.045);

}


.admin-payment-form-booking {

  display: flex;

  align-items: center;

  gap: 12px;

}


.admin-payment-form-token {

  display: inline-flex;

  align-items: center;

  justify-content: center;

  min-width: 58px;

  padding: 8px 10px;

  border-radius: 9px;

  background:
    rgba(58, 111, 77, 0.1);

  color:
    #3a704d;

  font-size: 14px;

  font-weight: 800;

  letter-spacing: 0.02em;

}


.admin-payment-form-booking > div:last-child {

  min-width: 0;

}


.admin-payment-form-booking strong {

  display: block;

  font-size: 14px;

  line-height: 1.35;

}


.admin-payment-form-booking span {

  display: block;

  margin-top: 2px;

  font-size: 11px;

  opacity: 0.65;

}


/* =========================================================
   PAYMENT VERIFICATION GRID
========================================================= */

.admin-payment-form-verification {

  display: grid;

  grid-template-columns:
    repeat(
      4,
      minmax(0, 1fr)
    );

  gap: 10px;

}


.admin-payment-form-verification > div {

  min-width: 0;

  padding: 10px 11px;

  border-radius: 10px;

  background:
    rgba(255, 255, 255, 0.45);

  border: 1px solid
    rgba(100, 120, 108, 0.08);

}


.admin-payment-form-verification span {

  display: block;

  margin-bottom: 4px;

  font-size: 9px;

  line-height: 1.3;

  text-transform: uppercase;

  letter-spacing: 0.07em;

  opacity: 0.58;

}


.admin-payment-form-verification strong {

  display: block;

  font-size: 12px;

  line-height: 1.4;

  overflow-wrap: anywhere;

}


/* =========================================================
   AMOUNT WARNING
========================================================= */

.payment-amount-warning {

  display: block;

  margin-top: 6px;

  font-size: 11px;

  line-height: 1.4;

}


.payment-amount-warning.positive {

  color:
    #a66b13;

}


.payment-amount-warning.negative {

  color:
    #a84747;

}


/* =========================================================
   UPI HELPER
========================================================= */

.admin-payment-upi-helper {

  display: flex;

  align-items: end;

  gap: 10px;

  padding: 11px;

  border-radius: 12px;

  background:
    rgba(68, 117, 87, 0.055);

  border: 1px solid
    rgba(68, 117, 87, 0.12);

}


.admin-payment-upi-helper .admin-payment-field {

  flex: 1;

  min-width: 0;

  margin: 0;

}


.admin-payment-open-upi {

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 7px;

  min-height: 42px;

  padding: 0 13px;

  border: 1px solid
    rgba(61, 126, 87, 0.22);

  border-radius: 10px;

  background:
    rgba(61, 126, 87, 0.1);

  color:
    #3d7e57;

  font-size: 12px;

  font-weight: 700;

  white-space: nowrap;

  cursor: pointer;

  transition:
    background-color 0.16s ease,
    border-color 0.16s ease,
    transform 0.16s ease;

}


.admin-payment-open-upi:hover:not(:disabled) {

  background:
    rgba(61, 126, 87, 0.16);

  border-color:
    rgba(61, 126, 87, 0.3);

  transform:
    translateY(-1px);

}


.admin-payment-open-upi:disabled {

  opacity: 0.42;

  cursor: not-allowed;

  transform: none;

}


/* =========================================================
   BANK HELPER
========================================================= */

.admin-payment-bank-helper {

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  padding: 12px 13px;

  border-radius: 12px;

  border: 1px solid
    rgba(74, 100, 128, 0.14);

  background:
    rgba(74, 100, 128, 0.055);

}


.admin-payment-bank-helper > div {

  display: flex;

  align-items: flex-start;

  gap: 9px;

  min-width: 0;

}


.admin-payment-bank-helper > div svg {

  flex-shrink: 0;

  margin-top: 1px;

  color:
    #52728e;

}


.admin-payment-bank-helper span {

  font-size: 11px;

  line-height: 1.5;

  opacity: 0.72;

}


.admin-payment-bank-helper button {

  flex-shrink: 0;

  display: inline-flex;

  align-items: center;

  gap: 6px;

  min-height: 35px;

  padding: 0 11px;

  border: 1px solid
    rgba(82, 114, 142, 0.2);

  border-radius: 9px;

  background:
    rgba(82, 114, 142, 0.09);

  color:
    #52728e;

  font-size: 11px;

  font-weight: 700;

  cursor: pointer;

}


.admin-payment-bank-helper button:hover {

  background:
    rgba(82, 114, 142, 0.15);

}


/* =========================================================
   REFERENCE INPUT + COPY BUTTON
========================================================= */

.admin-payment-reference-input {

  display: flex;

  align-items: stretch;

  width: 100%;

}


.admin-payment-reference-input input {

  flex: 1;

  min-width: 0;

  border-top-right-radius: 0;

  border-bottom-right-radius: 0;

}


.admin-payment-reference-input button {

