) {

  .admin-payment-form-verification {

    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );

  }


  .admin-payment-bank-helper {

    flex-direction: column;

    align-items: stretch;

  }


  .admin-payment-bank-helper button {

    width: 100%;

  }

}


@media (
  max-width: 640px
) {

  .admin-payment-insight-strip {

    align-items: flex-start;

  }


  .admin-payment-insight-amount {

    display: none;

  }


  .admin-payment-form-verification {

    grid-template-columns:
      1fr;

  }


  .admin-payment-upi-helper {

    flex-direction: column;

    align-items: stretch;

  }


  .admin-payment-open-upi {

    width: 100%;

  }


  .admin-payment-form-actions {

    flex-direction: column-reverse;

    align-items: stretch;

  }


  .admin-payment-form-actions button {

    width: 100%;

  }

}


/* =========================================================
   ACCESSIBILITY
========================================================= */

.admin-payment-open-upi:focus-visible,
.admin-payment-bank-helper button:focus-visible,
.admin-payment-reference-input button:focus-visible {

  outline:
    2px solid
    currentColor;

  outline-offset:
    2px;

}


/* =========================================================
   REDUCE MOTION
========================================================= */

@media (
  prefers-reduced-motion: reduce
) {

  .admin-payment-open-upi,
  .admin-payment-reference-input button {

    transition:
      none;

  }

}

/* =========================================================
   FINAL PROCUREMENT RECEIPT
========================================================= */

.token-completion-receipt-actions {
  width: 100%;
  display: flex;
  justify-content: center;
  margin-top: 14px;
}


.token-receipt-download-button {
  width: 100%;
  min-height: 48px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;

  border: 1px solid rgba(27, 83, 56, 0.18);
  border-radius: 12px;

  background: #f4f8f5;
  color: #1b5338;

  font-size: 14px;
  font-weight: 700;

  cursor: pointer;

  transition:
    background 0.18s ease,
    border-color 0.18s ease,
    transform 0.18s ease,
    box-shadow 0.18s ease;
}


.token-receipt-download-button:hover {
  background: #eaf3ed;
  border-color: rgba(27, 83, 56, 0.3);

  transform: translateY(-1px);

  box-shadow:
    0 7px 18px rgba(27, 83, 56, 0.08);
}


.token-receipt-download-button:active {
  transform: translateY(0);
}


.token-receipt-download-button svg {
  flex-shrink: 0;
}



/* =========================================================
   PAYMENT RECEIPT INLINE CARD
========================================================= */

.token-payment-receipt-inline {
  width: 100%;

  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 13px;

  margin-top: 16px;
  padding: 14px 15px;

  border: 1px solid rgba(27, 83, 56, 0.14);
  border-radius: 14px;

  background: #f7faf8;
}


.token-payment-receipt-inline-icon {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  background: #e2efe6;
  color: #1b5338;

  flex-shrink: 0;
}


.token-payment-receipt-inline > div:nth-child(2) {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 3px;
}


.token-payment-receipt-inline strong {
  color: #21392c;

  font-size: 13px;
  line-height: 1.35;
}


.token-payment-receipt-inline span {
  color: #728078;

  font-size: 12px;
  line-height: 1.5;
}


.token-receipt-inline-button {
  min-height: 38px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;

  padding: 0 13px;

  border: 1px solid rgba(27, 83, 56, 0.18);
  border-radius: 9px;

  background: #ffffff;
  color: #1b5338;

  font-size: 12px;
  font-weight: 700;

  white-space: nowrap;

  cursor: pointer;

  transition:
    background 0.18s ease,
    border-color 0.18s ease,
    transform 0.18s ease;
}


.token-receipt-inline-button:hover {
  background: #eef6f1;
  border-color: rgba(27, 83, 56, 0.28);

  transform: translateY(-1px);
}


.token-receipt-inline-button:active {
  transform: translateY(0);
}



/* =========================================================
   SIDE RECEIPT BUTTON
========================================================= */

.token-receipt-side-button {
  width: 100%;
  min-height: 43px;

  margin-top: 10px;

  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  border: 1px solid rgba(27, 83, 56, 0.2);
  border-radius: 11px;

  background: #ffffff;
  color: #1b5338;

  font-size: 13px;
  font-weight: 700;

  cursor: pointer;

  transition:
    background 0.18s ease,
    border-color 0.18s ease,
    transform 0.18s ease,
    box-shadow 0.18s ease;
}


.token-receipt-side-button:hover {
  background: #eef6f1;
  border-color: rgba(27, 83, 56, 0.3);

  transform: translateY(-1px);

  box-shadow:
    0 6px 16px rgba(27, 83, 56, 0.07);
}


.token-receipt-side-button:active {
  transform: translateY(0);
}


.token-receipt-side-button svg {
  flex-shrink: 0;
}



/* =========================================================
   COMPLETED CARD SPACING
========================================================= */

.token-completed-card
  .token-completion-actions {
  margin-bottom: 2px;
}


.token-completed-card
  .token-payment-issue-button {
  margin-top: 12px;
}



/* =========================================================
   DISABLED STATES
========================================================= */

.token-receipt-download-button:disabled,
.token-receipt-inline-button:disabled,
.token-receipt-side-button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}



/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 700px) {

  .token-payment-receipt-inline {
    grid-template-columns: auto 1fr;
  }


  .token-receipt-inline-button {
    grid-column: 1 / -1;
    width: 100%;
  }


  .token-receipt-download-button {
    min-height: 50px;

    font-size: 13px;
  }


  .token-receipt-side-button {
    min-height: 46px;
  }

}


/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 480px) {

  .token-payment-receipt-inline {
    gap: 10px;

    padding: 12px;
  }


  .token-payment-receipt-inline-icon {
    width: 34px;
    height: 34px;
  }


  .token-payment-receipt-inline strong {
    font-size: 12px;
  }


  .token-payment-receipt-inline span {
    font-size: 11px;
  }


  .token-receipt-download-button {
    padding: 0 12px;
  }

}

/* =========================================================
   LIVE QUEUE POSITION
========================================================= */

.token-queue-position-card {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 16px;
  padding: 16px 18px;
  border: 1px solid #dfe9e3;
  border-radius: 16px;
  background: linear-gradient(
    135deg,
    #f5faf6 0%,
    #ffffff 100%
  );
  box-shadow: 0 8px 24px rgba(27, 83, 56, 0.06);
}

.token-queue-position-icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 13px;
  background: #e7f3eb;
  color: #1b5338;
}

.token-queue-position-content {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.token-queue-position-content > span {
  margin-bottom: 3px;
  color: #718077;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.token-queue-position-content > strong {
  color: #1b5338;
  font-size: 23px;
  line-height: 1.15;
  font-weight: 800;
}

.token-queue-position-content > p {
  margin: 4px 0 0;
  color: #66756c;
  font-size: 12px;
  line-height: 1.5;
}

.token-queue-wait {
  min-width: 118px;
  padding: 10px 13px;
  border: 1px solid #e0e9e3;
  border-radius: 12px;
  background: #ffffff;
  text-align: right;
}

.token-queue-wait span {
  display: block;
  margin-bottom: 3px;
  color: #7d8982;
  font-size: 10px;
  font-weight: 700;
}

.token-queue-wait strong {
  display: block;
  color: #263c30;
  font-size: 14px;
  font-weight: 800;
}


/* =========================================================
   RECEIPT ACTIONS
========================================================= */

.token-completion-receipt-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 18px;
}

.token-receipt-download-button,
.token-receipt-inline-button,
.token-receipt-side-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid #d8e5dc;
  border-radius: 11px;
  background: #ffffff;
  color: #1b5338;
  font-weight: 750;
  cursor: pointer;
  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease,
    background 0.18s ease,
    border-color 0.18s ease;
}

.token-receipt-download-button {
  width: 100%;
  min-height: 44px;
  padding: 11px 16px;
}

.token-receipt-download-button:hover,
.token-receipt-inline-button:hover,
.token-receipt-side-button:hover {
  background: #f2f8f4;
  border-color: #bfd6c6;
  box-shadow: 0 7px 18px rgba(27, 83, 56, 0.08);
  transform: translateY(-1px);
}

.token-receipt-inline-button {
  flex: 0 0 auto;
  min-height: 38px;
  padding: 8px 13px;
}

.token-receipt-side-button {
  width: 100%;
  min-height: 42px;
  margin-top: 10px;
  padding: 10px 14px;
}


/* =========================================================
   INLINE RECEIPT CARD
========================================================= */

.token-payment-receipt-inline {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-top: 16px;
  padding: 14px;
  border: 1px solid #dce8df;
  border-radius: 15px;
  background: #f7fbf8;
}

.token-payment-receipt-inline-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  background: #e3f1e7;
  color: #1b5338;
}

.token-payment-receipt-inline > div:nth-child(2) {
  min-width: 0;
  flex: 1;
}

.token-payment-receipt-inline > div:nth-child(2) strong {
  display: block;
  margin-bottom: 3px;
  color: #294136;
  font-size: 13px;
}

.token-payment-receipt-inline > div:nth-child(2) span {
  display: block;
  color: #748178;
  font-size: 11px;
  line-height: 1.5;
}


/* =========================================================
   PAYMENT COMPLETED CARD
========================================================= */

.token-completed-card {
  position: relative;
  overflow: hidden;
}

.token-completed-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: #1b5338;
}

.token-completed-header {
  display: flex;
  align-items: flex-start;
  gap: 15px;
}

.token-completed-icon {
  width: 52px;
  height: 52px;
  flex: 0 0 52px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 15px;
  background: #e5f3e9;
  color: #1b5338;
}


/* =========================================================
   PAYMENT SUMMARY
========================================================= */

.token-payment-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 20px;
}

.token-payment-item {
  min-width: 0;
  padding: 14px;
  border: 1px solid #e2e9e4;
  border-radius: 13px;
  background: #fafcfb;
}

.token-payment-item span {
  display: block;
  margin-bottom: 6px;
  color: #7a877f;
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.token-payment-item strong {
  display: block;
  color: #263d31;
  font-size: 14px;
  font-weight: 800;
  line-height: 1.35;
  overflow-wrap: anywhere;
}


/* =========================================================
   SMS CONFIRMATION
========================================================= */

.token-sms-confirmation {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-top: 16px;
  padding: 14px;
  border-radius: 14px;
  border: 1px solid #dde8df;
}

.token-sms-confirmation.sent {
  background: #f0f8f3;
  border-color: #cae2d1;
}

.token-sms-confirmation.failed {
  background: #fff5f3;
  border-color: #efd5d0;
}

.token-sms-confirmation.not-sent {
  background: #f8faf9;
  border-color: #e1e7e3;
}

.token-sms-confirmation-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
}

.token-sms-confirmation.sent .token-sms-confirmation-icon {
  background: #dcefe2;
  color: #1b5338;
}

.token-sms-confirmation.failed .token-sms-confirmation-icon {
  background: #f9dfda;
  color: #b84a3d;
}

.token-sms-confirmation.not-sent .token-sms-confirmation-icon {
  background: #edf1ef;
  color: #64726a;
}

.token-sms-confirmation-content {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.token-sms-status-label {
  margin-bottom: 3px;
  color: #78857d;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.11em;
}

.token-sms-confirmation-content strong {
  color: #263d31;
  font-size: 13px;
  line-height: 1.35;
}

.token-sms-confirmation-content > span:last-child {
  margin-top: 3px;
  color: #718078;
  font-size: 11px;
  line-height: 1.45;
}

.token-sms-time {
  flex: 0 0 auto;
  color: #7c8981;
  font-size: 10px;
  white-space: nowrap;
}


/* =========================================================
   QUEUE + COUNTDOWN SPACING
========================================================= */

.token-queue-position-card + .token-arrival-countdown {
  margin-top: 12px;
}


/* =========================================================
   BUTTON INTERACTIONS
========================================================= */

.token-receipt-download-button:active,
.token-receipt-inline-button:active,
.token-receipt-side-button:active {
  transform: translateY(0);
}

.token-receipt-download-button:disabled,
.token-receipt-inline-button:disabled,
.token-receipt-side-button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}


/* =========================================================
   TOKEN VISUAL RECEIPT BUTTON
========================================================= */

.token-visual-card .token-receipt-side-button {
  margin-top: 10px;
}


/* =========================================================
   PAYMENT MODAL
========================================================= */

.token-payment-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(20, 35, 28, 0.52);
  backdrop-filter: blur(7px);
}

.token-payment-modal {
  width: min(560px, 100%);
  max-height: min(760px, calc(100vh - 48px));
  overflow-y: auto;
  padding: 22px;
  border: 1px solid #dce6df;
  border-radius: 20px;
  background: #ffffff;
  box-shadow: 0 24px 70px rgba(17, 36, 26, 0.2);
}

.token-payment-modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 20px;
}

.token-payment-modal-header h2 {
  margin: 6px 0 0;
  color: #21392b;
  font-size: 24px;
  line-height: 1.15;
}

.token-payment-modal-header > button {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #dfe7e2;
  border-radius: 10px;
  background: #ffffff;
  color: #617066;
  cursor: pointer;
}

.token-payment-modal-header > button:hover {
  background: #f4f7f5;
}


/* =========================================================
   PAYMENT ISSUE FORM
========================================================= */

.token-payment-issue-label {
  display: block;
  margin-top: 16px;
}

.token-payment-issue-label > span {
  display: block;
  margin-bottom: 7px;
  color: #3a4e43;
  font-size: 12px;
  font-weight: 750;
}

.token-payment-issue-label select,
.token-payment-issue-label textarea {
  width: 100%;
  border: 1px solid #d9e3dd;
  border-radius: 11px;
  outline: none;
  background: #ffffff;
  color: #2c4034;
  font: inherit;
  transition:
    border-color 0.18s ease,
    box-shadow 0.18s ease;
}

.token-payment-issue-label select {
  min-height: 43px;
  padding: 9px 12px;
}

.token-payment-issue-label textarea {
  min-height: 100px;
  padding: 11px 12px;
  resize: vertical;
}

.token-payment-issue-label select:focus,
.token-payment-issue-label textarea:focus {
  border-color: #91b49c;
  box-shadow: 0 0 0 3px rgba(69, 118, 82, 0.1);
}

.token-payment-support-details {
  display: grid;
  gap: 6px;
  margin-top: 15px;
  padding: 12px 14px;
  border-radius: 11px;
  background: #f6f9f7;
  color: #68776e;
  font-size: 11px;
}

.token-payment-modal-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 18px;
}

.token-payment-help-link,
.token-payment-modal-close {
  min-height: 40px;
  padding: 9px 14px;
  border-radius: 10px;
  font-size: 12px;
  font-weight: 750;
  cursor: pointer;
}

.token-payment-help-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid #1b5338;
  background: #1b5338;
  color: #ffffff;
}

.token-payment-modal-close {
  border: 1px solid #dce5df;
  background: #ffffff;
  color: #53645a;
}

.token-payment-issue-success {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 9px;
  padding: 28px 12px 12px;
  text-align: center;
  color: #1b5338;
}

.token-payment-issue-success strong {
  color: #263d31;
  font-size: 16px;
}

.token-payment-issue-success span {
  max-width: 410px;
  color: #708077;
  font-size: 12px;
  line-height: 1.55;
}


/* =========================================================
   SPINNER
========================================================= */

.token-spin {
  animation: token-spin-animation 0.9s linear infinite;
}

@keyframes token-spin-animation {
  to {
    transform: rotate(360deg);
  }
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 900px) {

  .token-payment-summary {
    grid-template-columns: 1fr;
  }

  .token-queue-position-card {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .token-queue-position-content {
    min-width: calc(100% - 58px);
  }

  .token-queue-wait {
    width: 100%;
    min-width: 0;
    text-align: left;
  }

}


@media (max-width: 640px) {

  .token-queue-position-card {
    gap: 11px;
    padding: 14px;
  }

  .token-queue-position-icon {
    width: 38px;
    height: 38px;
    flex-basis: 38px;
    border-radius: 11px;
  }

  .token-queue-position-content > strong {
    font-size: 20px;
  }

  .token-completion-receipt-actions {
    margin-top: 14px;
  }

  .token-receipt-download-button {
    min-height: 42px;
    padding: 10px 13px;
    font-size: 12px;
  }

  .token-payment-receipt-inline {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .token-payment-receipt-inline > div:nth-child(2) {
    flex-basis: calc(100% - 51px);
  }

  .token-receipt-inline-button {
    width: 100%;
  }

  .token-sms-confirmation {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .token-sms-time {
    width: 100%;
    margin-left: 51px;
  }

  .token-payment-modal-backdrop {
    padding: 12px;
  }

  .token-payment-modal {
    max-height: calc(100vh - 24px);
    padding: 17px;
    border-radius: 16px;
  }

  .token-payment-modal-header h2 {
    font-size: 21px;
  }

  .token-payment-modal-actions {
    flex-direction: column-reverse;
    align-items: stretch;
  }

  .token-payment-help-link,
  .token-payment-modal-close {
    width: 100%;
    justify-content: center;
  }

}


/* =========================================================
   MOBILE HEADER
========================================================= */

@media (max-width: 700px) {

  .app-header {
    width: 100%;
    padding: 8px 12px;
    min-height: 56px;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
  }


  /* =======================================================
     LOGO
  ======================================================= */

  .app-header-brand {
    flex: 0 0 auto;
    width: 40px;
    max-width: 40px;
    overflow: hidden;
    display: flex;
    align-items: center;
  }


  .app-header-brand .logo-name,
  .app-header-brand .logo-text {
    display: none !important;
  }


  .app-header-brand span {
    display: none !important;
  }


  .app-header-brand img,
  .app-header-brand svg {
    width: 38px;
    height: 38px;
    flex-shrink: 0;
  }


  /* =======================================================
     HEADER ACTIONS
  ======================================================= */

  .app-header-actions {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
