/* =========================================================
   VOICE ASSISTANT
========================================================= */

.voice-assistant-floating {
  position: fixed;
  right: 24px;
  bottom: 24px;
  width: 52px;
  height: 52px;
  border: 0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 9998;
  color: white;
  background: linear-gradient(
    135deg,
    #0f766e,
    #15803d
  );
  box-shadow:
    0 10px 28px rgba(
      0,
      0,
      0,
      0.18
    ),
    0 3px 8px rgba(
      15,
      118,
      110,
      0.22
    );
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.voice-assistant-floating:hover {
  transform:
    translateY(-2px)
    scale(1.03);
}

.voice-assistant-floating:active {
  transform:
    scale(0.96);
}

.voice-assistant-floating.listening {
  background:
    linear-gradient(
      135deg,
      #dc2626,
      #ea580c
    );
}

.voice-assistant-pulse {
  position: absolute;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  border: 2px solid rgba(
    255,
    255,
    255,
    0.65
  );
  animation:
    voice-assistant-pulse 1.4s
    ease-out infinite;
}

@keyframes voice-assistant-pulse {

  0% {
    transform: scale(1);
    opacity: 0.9;
  }

  70% {
    transform: scale(1.45);
    opacity: 0;
  }

  100% {
    transform: scale(1.45);
    opacity: 0;
  }

}


/* ---------------------------------------------------------
   PANEL
--------------------------------------------------------- */

.voice-assistant-panel {
  position: fixed;
  right: 24px;
  bottom: 88px;
  width: min(
    390px,
    calc(100vw - 32px)
  );
  max-height: min(
    650px,
    calc(100vh - 112px)
  );
  overflow: auto;
  z-index: 9999;

  border: 1px solid rgba(
    15,
    118,
    110,
    0.16
  );

  border-radius: 24px;

  background:
    rgba(
      255,
      255,
      255,
      0.97
    );

  box-shadow:
    0 25px 70px rgba(
      0,
      0,
      0,
      0.17
    ),
    0 8px 24px rgba(
      0,
      0,
      0,
      0.08
    );

  backdrop-filter:
    blur(18px);

  -webkit-backdrop-filter:
    blur(18px);

  animation:
    voice-assistant-panel-in
    0.24s
    ease-out;
}

@keyframes voice-assistant-panel-in {

  from {
    opacity: 0;
    transform:
      translateY(12px)
      scale(0.97);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }

}


/* ---------------------------------------------------------
   HEADER
--------------------------------------------------------- */

.voice-assistant-panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 17px 18px;
  border-bottom: 1px solid rgba(
    15,
    23,
    42,
    0.08
  );
}

.voice-assistant-heading {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}

.voice-assistant-heading-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(
    21,
    128,
    61,
    0.10
  );
  color: #15803d;
}

.voice-assistant-heading > div:last-child {
  min-width: 0;
}

.voice-assistant-heading strong {
  display: block;
  color: #17251e;
  font-size: 14px;
  font-weight: 800;
  line-height: 1.25;
}

.voice-assistant-heading span {
  display: block;
  margin-top: 3px;
  color: #66736b;
  font-size: 11px;
  line-height: 1.35;
}

.voice-assistant-close {
  width: 34px;
  height: 34px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #67736c;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.voice-assistant-close:hover {
  background: rgba(
    15,
    23,
    42,
    0.06
  );
}


/* ---------------------------------------------------------
   BODY
--------------------------------------------------------- */

.voice-assistant-body {
  padding: 20px;
}

.voice-assistant-orb {
  position: relative;
  width: 76px;
  height: 76px;
  margin: 2px auto 12px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  background:
    linear-gradient(
      145deg,
      #0f766e,
      #15803d
    );
  box-shadow:
    0 12px 35px rgba(
      15,
      118,
      110,
      0.22
    );
}

.voice-assistant-orb.listening {
  background:
    linear-gradient(
      145deg,
      #dc2626,
      #ea580c
    );
}

.voice-orb-wave {
  position: absolute;
  inset: -7px;
  border: 1px solid rgba(
    22,
    101,
    52,
    0.20
  );
  border-radius: 50%;
  animation:
    voice-orb-wave 1.8s
    ease-out infinite;
}

.wave-two {
  inset: -14px;
  animation-delay: 0.35s;
}

.wave-three {
  inset: -21px;
  animation-delay: 0.7s;
}

@keyframes voice-orb-wave {

  0% {
    transform: scale(0.88);
    opacity: 0.75;
  }

  80% {
    transform: scale(1.08);
    opacity: 0;
  }

  100% {
    opacity: 0;
  }

}


.voice-assistant-state {
  text-align: center;
  margin-bottom: 17px;
}

.voice-assistant-state strong {
  display: block;
  color: #18241e;
  font-size: 13px;
  font-weight: 800;
}

.voice-assistant-error {
  display: block;
  margin-top: 7px;
  color: #b91c1c;
