  --ai-blue: #8ebbd4;
  --ai-blue-soft: #edf7fb;

  --ai-white: #ffffff;
  --ai-cream: #faf9f3;

  --ai-text: #183226;
  --ai-text-soft: #63746a;

  --ai-border: rgba(47, 125, 74, 0.14);

