    ai-spin
    0.8s
    linear
    infinite;
}

@keyframes ai-spin {

  to {

    transform:
      rotate(360deg);

  }

}


/* =========================================================
   REDUCE MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

  .voice-assistant-floating,
  .voice-assistant-floating.listening,
  .voice-assistant-floating.listening::before,
  .voice-assistant-main-button.stop svg,
  .voice-assistant-panel,
  .voice-assistant-text-form button,
  .voice-assistant-example-list button {

    animation:
      none !important;

    transition:
      none !important;
  }

}


