/* =========================================================
   KRISHISETU AI — FLOATING ASSISTANT
========================================================= */

.voice-assistant-floating {

  position: fixed;

  right: 28px;
  bottom: 92px;

  z-index: 9999;

  width: 76px;
  height: 76px;

  border: 0;
  border-radius: 24px;

  display: flex;
  align-items: center;
  justify-content: center;

  cursor: pointer;

  color: #ffffff;

  background:
    linear-gradient(
      145deg,
      #4f8f58,
      #367744
    );

  box-shadow:
    0 14px 35px rgba(46, 93, 56, 0.25),
    0 5px 15px rgba(46, 93, 56, 0.12),
    inset 0 1px 0 rgba(255,255,255,0.20);

  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    width 180ms ease,
    border-radius 180ms ease;

  overflow: visible;
}


.voice-assistant-floating::before {

  content: "";

  position: absolute;

  inset: -5px;

  border-radius: 29px;

  background:
    linear-gradient(
      135deg,
      rgba(225,210,139,0.48),
      rgba(82,145,91,0.18),
      rgba(144,190,211,0.28)
    );

  opacity: 0.55;

  z-index: -1;

  filter: blur(7px);

  pointer-events: none;
}


.voice-assistant-floating:hover {

  transform:
    translateY(-4px)
    scale(1.025);

  box-shadow:
    0 19px 42px rgba(46, 93, 56, 0.30),
    0 6px 18px rgba(46, 93, 56, 0.15),
    inset 0 1px 0 rgba(255,255,255,0.22);

  filter: none;
}


.voice-assistant-floating:active {

  transform:
    translateY(-1px)
    scale(0.98);
}


.voice-assistant-floating-icon {

  width: 42px;
  height: 42px;

  border-radius: 14px;

  display: flex;
  align-items: center;
  justify-content: center;

  background:
    linear-gradient(
      145deg,
      rgba(242,225,156,0.95),
      rgba(214,225,166,0.90)
    );

  color:
    #315f3b;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.55),
    0 4px 12px rgba(0,0,0,0.08);

  transition:
    transform 180ms ease,
    background 180ms ease;
}


.voice-assistant-floating:hover
.voice-assistant-floating-icon {

  transform:
    rotate(-4deg)
    scale(1.05);
}


/* Small label that appears beside it */

.voice-assistant-floating-label {

  position: absolute;

  right: calc(100% + 12px);

  white-space: nowrap;

  padding:
    9px 13px;

  border-radius: 12px;

  font-size: 12px;
  font-weight: 750;

  color:
    var(--ai-text, #26452d);

  background:
    var(--ai-surface, rgba(255,255,255,0.94));

  border:
    1px solid
    var(--ai-border, rgba(63,134,86,0.15));

  box-shadow:
    0 8px 24px rgba(0,0,0,0.09);

  backdrop-filter:
    blur(14px);

  -webkit-backdrop-filter:
    blur(14px);

  opacity: 0;

  transform:
    translateX(8px);

  pointer-events:
    none;

  transition:
    opacity 170ms ease,
    transform 170ms ease;
}


.voice-assistant-floating:hover
.voice-assistant-floating-label {

  opacity: 1;

  transform:
    translateX(0);
}


/* Listening state */

.voice-assistant-floating.listening {

  background:
    linear-gradient(
      145deg,
      #c98f45,
      #a96c2e
    );

  box-shadow:
    0 0 0 7px rgba(201,143,69,0.10),
    0 17px 38px rgba(169,108,46,0.28);

  animation:
    assistantListeningPulse 1.65s ease-in-out infinite;
}


.voice-assistant-floating.listening
.voice-assistant-floating-icon {

  color: #6b3e1d;

  background:
    linear-gradient(
      145deg,
      #f4dd9e,
      #f2c76a
    );
}


.voice-assistant-floating.typing {

  background:
    linear-gradient(
      145deg,
      #4f8f58,
      #316f70
    );
}


.voice-assistant-floating-live-dot {

  position: absolute;

  top: 9px;
  right: 9px;

  width: 10px;
  height: 10px;

  border-radius: 50%;

  background:
    #f5dc7f;

  border:
    2px solid rgba(255,255,255,0.75);

  box-shadow:
    0 0 0 4px rgba(245,220,127,0.18);

  animation:
    assistantLiveDot 1s ease-in-out infinite;
}


@keyframes assistantListeningPulse {

  0%,
  100% {
    box-shadow:
      0 0 0 5px rgba(201,143,69,0.07),
      0 17px 38px rgba(169,108,46,0.23);
  }

  50% {
    box-shadow:
      0 0 0 11px rgba(201,143,69,0.13),
      0 20px 44px rgba(169,108,46,0.30);
  }
}


@keyframes assistantLiveDot {

  0%,
  100% {
    transform: scale(0.85);
    opacity: 0.65;
  }

  50% {
    transform: scale(1.18);
    opacity: 1;
  }
}

.voice-assistant-panel {

  position: fixed;

  right: 28px;
  bottom: 28px;

  width: 560px;
  max-width: calc(100vw - 40px);

  height: min(720px, calc(100vh - 56px));

  max-height: calc(100vh - 56px);

