  margin-top: 8px;

  padding: 6px;

  border-radius: 17px;

  background:
    rgba(255,255,255,0.72);

  border:
    1px solid rgba(63,134,86,0.18);

  box-shadow:
    0 5px 18px rgba(40,75,48,0.06);
}


.voice-assistant-text-form input {

  flex: 1;

  min-width: 0;

  height: 45px;

  padding:
    0 12px;

  border: 0;

  outline: none;

  background:
    transparent;

  color:
    var(--ai-text, #26352a);

  font-size: 13.5px;
}


.voice-assistant-text-form input::placeholder {

  color:
    rgba(67,91,73,0.52);
}


.voice-assistant-text-form button {

  flex-shrink: 0;

  width: 45px;
  height: 45px;

  border: 0;

  border-radius: 13px;

  display: flex;

  align-items: center;
  justify-content: center;

  color:
    white;

  background:
    linear-gradient(
      145deg,
      #4f8f58,
      #367744
    );

  cursor: pointer;

  box-shadow:
    0 6px 14px rgba(63,134,86,0.17);

  transition:
    transform 160ms ease,
    opacity 160ms ease;
}


.voice-assistant-text-form button:hover:not(:disabled) {

  transform:
    translateY(-1px)
    scale(1.03);
}


.voice-assistant-text-form button:disabled {

  opacity:
    0.38;

  cursor:
    not-allowed;
}

@media (max-width: 700px) {

  .voice-assistant-panel {

    right: 12px;
    left: 12px;
    bottom: 12px;

    width: auto;

    max-width: none;

    height:
      calc(100vh - 24px);

    max-height:
      calc(100vh - 24px);

    border-radius: 24px;
  }


  .voice-assistant-floating {

    right: 18px;
    bottom: 22px;

    width: 68px;
    height: 68px;

    border-radius: 21px;
  }


  .voice-assistant-floating-label {

    display: none;
  }


  .voice-assistant-message-bubble {

    max-width: 91%;
  }

}

.voice-assistant-backdrop {

  position: fixed;

  inset: 0;

  z-index: 9998;

  display: flex;

  align-items: flex-end;

  justify-content: flex-end;

  padding:
    28px;

  background:
    rgba(22,39,26,0.045);

  animation:
    assistantBackdropIn 160ms ease;
}


@keyframes assistantBackdropIn {

  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}


@media (max-width: 700px) {

  .voice-assistant-backdrop {

    padding: 12px;

    align-items: flex-end;
  }

}


/* =========================================================
   KRISHISETU AI ASSISTANT
   Premium farmer-friendly floating assistant
   ========================================================= */

/* =========================================================
   THEME TOKENS
   These intentionally use existing/current CSS variables
   when available, with safe fallbacks.
   ========================================================= */

.voice-assistant-floating,
.voice-assistant-backdrop,
.voice-assistant-panel {

  --ai-green:
    var(--primary-green, #2f7d4a);

  --ai-green-dark:
    var(--green-dark, #205a35);

  --ai-green-soft:
    var(--pale-green, #e9f6ec);

  --ai-yellow:
    var(--primary-yellow, #e9c46a);

  --ai-yellow-soft:
    var(--pale-yellow, #fff7d6);

  --ai-blue:
    var(--primary-blue, #6fa8dc);

  --ai-blue-soft:
    var(--pale-blue, #eaf4fc);

  --ai-white:
    #ffffff;

  --ai-text:
    var(--text-primary, #1d2a22);

  --ai-text-soft:
    var(--text-secondary, #657268);

  --ai-border:
    rgba(53, 91, 67, 0.13);

  --ai-shadow:
    0 24px 70px rgba(20, 45, 29, 0.18);

}


/* =========================================================
   FLOATING BUTTON
   ========================================================= */

.voice-assistant-floating {

  position: fixed;

  right:
    clamp(18px, 2.5vw, 34px);

  bottom:
    clamp(24px, 5vh, 48px);

  z-index:
    9998;

  display:
    flex;

  align-items:
    center;

  gap:
    10px;

  min-height:
    56px;

  padding:
    8px 15px 8px 9px;

  border:
    1px solid
    rgba(255, 255, 255, 0.42);

  border-radius:
    999px;

  cursor:
    pointer;

  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      #2f7d4a 0%,
      #3f9660 52%,
      #568cb8 100%
    );

  box-shadow:
    0 12px 35px
      rgba(34, 86, 53, 0.28),

    0 4px 14px
      rgba(34, 86, 53, 0.16),

    inset 0 1px 0
      rgba(255, 255, 255, 0.38);

  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    filter 180ms ease;

  overflow:
    hidden;

  isolation:
    isolate;

}


.voice-assistant-floating::before {

  content:
    "";

  position:
    absolute;

  inset:
    0;

  background:
    linear-gradient(
      110deg,
      transparent 18%,
      rgba(255, 255, 255, 0.24) 48%,
      transparent 78%
    );

  transform:
    translateX(-130%);

  transition:
    transform 500ms ease;

  pointer-events:
    none;

  z-index:
    -1;

}


.voice-assistant-floating:hover {

  transform:
    translateY(-3px)
    scale(1.02);

  box-shadow:
    0 17px 42px
      rgba(34, 86, 53, 0.34),

    0 6px 18px
      rgba(34, 86, 53, 0.18),

    inset 0 1px 0
      rgba(255, 255, 255, 0.48);

}


.voice-assistant-floating:hover::before {

  transform:
    translateX(130%);

}


.voice-assistant-floating:active {

  transform:
    translateY(0)
    scale(0.98);

}


.voice-assistant-floating.panel-open {

  opacity:
    0.92;

}


/* =========================================================
   FLOATING ICON
   ========================================================= */

.voice-assistant-floating-icon {

  width:
    40px;

  height:
    40px;

  flex:
    0 0 40px;

  display:
    grid;

  place-items:
    center;

  border-radius:
    50%;

  color:
    #234d31;

  background:
    rgba(255, 255, 255, 0.93);

  box-shadow:
    inset 0 1px 2px
      rgba(255, 255, 255, 0.8),

    0 2px 8px
      rgba(16, 47, 28, 0.16);

  transition:
    transform 180ms ease,
    background 180ms ease;

}


.voice-assistant-floating:hover
.voice-assistant-floating-icon {

  transform:
    rotate(-4deg)
    scale(1.04);

  background:
    #ffffff;

}


/* =========================================================
   FLOATING LABEL
   ========================================================= */

.voice-assistant-floating-label {

  font-size:
    14px;

  line-height:
    1;

  font-weight:
    700;

  letter-spacing:
    0.01em;

  white-space:
    nowrap;

}


.voice-assistant-floating-live-dot {

  width:
    8px;

  height:
    8px;

  margin-left:
    1px;

  border-radius:
    50%;

  background:
    #ffe082;

  box-shadow:
    0 0 0 4px
      rgba(255, 224, 130, 0.18);

  animation:
    voice-assistant-live-dot 1.15s
    ease-in-out infinite;

}


/* =========================================================
   LISTENING FLOATING BUTTON
   ========================================================= */

.voice-assistant-floating.listening {

  background:
    linear-gradient(
      135deg,
      #24683d 0%,
      #318451 48%,
      #4d83a8 100%
    );

  box-shadow:
    0 14px 44px
      rgba(42, 110, 67, 0.34),

    0 0 0 5px
      rgba(65, 150, 91, 0.10);

}


.voice-assistant-floating.listening
.voice-assistant-floating-icon {

  color:
    #ffffff;

  background:
    rgba(255, 255, 255, 0.15);

  box-shadow:
    inset 0 0 0 1px
      rgba(255, 255, 255, 0.25);

  animation:
    assistant-mic-breathe 1.35s
    ease-in-out infinite;

}


/* =========================================================
   BACKDROP
   ========================================================= */

.voice-assistant-backdrop {

  position:
    fixed;

  inset:
    0;

  z-index:
    9997;

  display:
    flex;

  align-items:
    flex-end;

  justify-content:
    flex-end;

  padding:
    24px;

  background:
    rgba(12, 28, 18, 0.18);

  backdrop-filter:
    blur(4px);

  -webkit-backdrop-filter:
    blur(4px);

  animation:
    voice-assistant-backdrop-in
    180ms ease-out;

}


/* =========================================================
   MAIN PANEL
   ========================================================= */

.voice-assistant-panel {

  position:
    relative;

  width:
    min(
      620px,
      calc(100vw - 36px)
    );

  height:
    min(
      760px,
      calc(100vh - 50px)
    );

  min-height:
    560px;

  display:
    flex;

  flex-direction:
    column;

  overflow:
    hidden;

  border:
    1px solid
    rgba(255, 255, 255, 0.60);

  border-radius:
    28px;

  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.92),
      rgba(247, 251, 247, 0.84)
    );

  box-shadow:
    0 34px 100px
      rgba(22, 47, 30, 0.23),

    0 12px 34px
      rgba(22, 47, 30, 0.14),

    inset 0 1px 0
      rgba(255, 255, 255, 0.85);

  backdrop-filter:
    blur(20px)
    saturate(125%);

  -webkit-backdrop-filter:
    blur(20px)
    saturate(125%);

  color:
    var(--ai-text);

  animation:
    voice-assistant-panel-in
    220ms cubic-bezier(
      0.22,
      1,
      0.36,
      1
    );

}


/* =========================================================
   PANEL DECORATION
   ========================================================= */

.voice-assistant-panel::before {

  content:
    "";

  position:
    absolute;

  top:
    -150px;

  right:
    -120px;

  width:
    320px;

  height:
    320px;

  border-radius:
    50%;

  background:
    radial-gradient(
      circle,
      rgba(92, 160, 108, 0.18),
      transparent 68%
    );

  pointer-events:
    none;

}


.voice-assistant-panel::after {

  content:
    "";

  position:
    absolute;

  bottom:
    -140px;

  left:
    -110px;

  width:
    300px;

  height:
    300px;

  border-radius:
    50%;

  background:
    radial-gradient(
      circle,
      rgba(111, 168, 220, 0.12),
      transparent 68%
    );

  pointer-events:
    none;

}


/* =========================================================
   HEADER
   ========================================================= */

.voice-assistant-panel-header {

  position:
    relative;

  z-index:
    2;

  flex:
    0 0 auto;

  display:
    flex;

  align-items:
    center;

  justify-content:
    space-between;

  gap:
    18px;

  padding:
    18px 20px;

  border-bottom:
    1px solid
    rgba(53, 91, 67, 0.10);

  background:
    linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.86),
      rgba(242, 248, 243, 0.62)
    );

}


/* =========================================================
   HEADING
   ========================================================= */

.voice-assistant-heading {

  min-width:
    0;

  display:
    flex;

  align-items:
    center;

  gap:
    12px;

}


.voice-assistant-heading-icon {

  width:
    44px;

  height:
    44px;

  flex:
    0 0 44px;

  display:
    grid;

  place-items:
    center;

  border-radius:
    14px;

  color:
    #27653d;

  background:
    linear-gradient(
      145deg,
      #e5f5e8,
      #d9edfc
    );

  border:
    1px solid
    rgba(51, 109, 72, 0.10);

  box-shadow:
    inset 0 1px 0
      rgba(255, 255, 255, 0.85);

}


.voice-assistant-title-row {

  display:
    flex;

  align-items:
    center;

  gap:
    8px;

}


.voice-assistant-title-row strong {

  color:
    #285d3d;

  font-size:
    17px;

  font-weight:
    800;

  letter-spacing:
    -0.01em;

}


.voice-assistant-heading > div:last-child > span {

  display:
    block;

  margin-top:
    2px;

  color:
    #69766d;

  font-size:
    12px;

  line-height:
    1.35;

}


/* =========================================================
   STATUS DOT
   ========================================================= */

.voice-assistant-status-dot {

  width:
    7px;

  height:
    7px;

  border-radius:
    50%;

}


.voice-assistant-status-dot.online {

  background:
    #4b9f62;

  box-shadow:
    0 0 0 4px
      rgba(75, 159, 98, 0.10);

}


.voice-assistant-status-dot.offline {

  background:
    #b9705c;

  box-shadow:
    0 0 0 4px
      rgba(185, 112, 92, 0.10);

}


/* =========================================================
   HEADER BUTTONS
   ========================================================= */

.voice-assistant-header-actions {

  display:
    flex;

  align-items:
    center;

  gap:
    8px;

}


.voice-assistant-reset,
.voice-assistant-close {

  width:
    40px;

  height:
    40px;

  flex:
    0 0 40px;

  display:
    grid;

  place-items:
    center;

  border:
    1px solid
    rgba(43, 80, 56, 0.12);

  border-radius:
    12px;

  cursor:
    pointer;

  transition:
    transform 160ms ease,
    background 160ms ease,
    color 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease;

}


/* Reset */

.voice-assistant-reset {

  color:
    #4b7560;

  background:
    rgba(232, 244, 235, 0.85);

}


.voice-assistant-reset:hover:not(:disabled) {

  color:
    #ffffff;

  background:
    #398057;

  border-color:
    #398057;

  transform:
    translateY(-2px)
    rotate(-7deg);

  box-shadow:
    0 8px 18px
      rgba(57, 128, 87, 0.20);

}


/* Close */

.voice-assistant-close {

  color:
    #7c6863;

  background:
    rgba(255, 243, 238, 0.90);

}


.voice-assistant-close:hover {

  color:
    #ffffff;

  background:
    #c86655;

  border-color:
    #c86655;

  transform:
    translateY(-2px)
    scale(1.04);

  box-shadow:
    0 8px 18px
      rgba(200, 102, 85, 0.20);

}


.voice-assistant-reset:disabled {

  opacity:
    0.38;

  cursor:
    default;

}


/* =========================================================
   BODY
   ========================================================= */

.voice-assistant-body {

  position:
    relative;

  z-index:
    1;

  flex:
    1 1 auto;

  min-height:
    0;

  overflow-y:
    auto;

  overflow-x:
    hidden;

  padding:
    18px 18px 14px;

  scroll-behavior:
    smooth;

  overscroll-behavior:
    contain;

  scrollbar-width:
    thin;

  scrollbar-color:
    rgba(68, 119, 81, 0.30)
    transparent;

}


.voice-assistant-body::-webkit-scrollbar {

  width:
    7px;

}


.voice-assistant-body::-webkit-scrollbar-track {

  background:
    transparent;

}


.voice-assistant-body::-webkit-scrollbar-thumb {

  border-radius:
    99px;

  background:
    rgba(67, 117, 79, 0.28);

}


.voice-assistant-body::-webkit-scrollbar-thumb:hover {

  background:
    rgba(67, 117, 79, 0.42);

}


/* =========================================================
   CONNECTIVITY
   ========================================================= */

.voice-assistant-connectivity {

  width:
    fit-content;

  display:
    inline-flex;

  align-items:
    center;

  gap:
    6px;

  margin:
    0 auto 13px;

  padding:
    5px 9px;

  border-radius:
    999px;

  color:
    #447253;

  background:
    rgba(229, 243, 232, 0.82);

  border:
    1px solid
    rgba(61, 118, 77, 0.10);

  font-size:
    10px;

  font-weight:
    700;

}


.voice-assistant-connectivity.offline {

  color:
    #925e4f;

  background:
    rgba(252, 237, 231, 0.88);

  border-color:
    rgba(150, 89, 70, 0.12);

}


/* =========================================================
   WELCOME
   ========================================================= */

.voice-assistant-welcome {

  position:
    relative;

  display:
    flex;

  flex-direction:
    column;

  align-items:
    center;

  justify-content:
    center;

  min-height:
    300px;

  padding:
    20px 12px;

  text-align:
    center;

}


.voice-assistant-welcome-glow {

  position:
    absolute;

  top:
    45px;

  left:
    50%;

  width:
    240px;

  height:
    170px;

  transform:
    translateX(-50%);

  border-radius:
    50%;

  background:
    radial-gradient(
      ellipse,
      rgba(
        64,
        145,
        86,
        calc(
          0.17 +
          var(--voice-intensity, 0) * 0.18
        )
      ),
      transparent 70%
    );

  filter:
    blur(8px);

  transition:
    opacity 160ms ease,
    transform 100ms ease;

}


.voice-assistant-orb {

  position:
    relative;

  width:
    88px;

  height:
    88px;

  display:
    grid;

  place-items:
    center;

  border:
    1px solid
    rgba(255, 255, 255, 0.85);

  border-radius:
    50%;

  color:
    #2f7348;

  background:
    linear-gradient(
      145deg,
      rgba(228, 246, 231, 0.94),
      rgba(224, 240, 252, 0.88)
    );

  box-shadow:
    0 16px 32px
      rgba(47, 101, 66, 0.14),

    inset 0 2px 0
      rgba(255, 255, 255, 0.95),

    0 0
      calc(
        8px +
        var(--voice-intensity, 0) * 32px
      )
      rgba(
        67,
        153,
        92,
        calc(
          var(--voice-intensity, 0) * 0.22
        )
      );

  transition:
    box-shadow 100ms linear,
    transform 100ms linear;

}


.voice-assistant-orb.listening {

  color:
    #ffffff;

  background:
    linear-gradient(
      145deg,
      #3c9560,
      #5d9dca
    );

  transform:
    scale(
      calc(
        1 +
        var(--voice-intensity, 0) * 0.055
      )
    );

  animation:
    assistant-listening-breathe
    1.35s ease-in-out infinite;

}


.voice-assistant-state {

  max-width:
    460px;

  margin-top:
    20px;

}


.voice-assistant-state strong {

  display:
    block;

  color:
    #285d3d;

  font-size:
    clamp(
      19px,
      2vw,
      23px
    );

  font-weight:
    800;

  letter-spacing:
    -0.025em;

}


.voice-assistant-state span {

  display:
    block;

  margin-top:
    7px;

  color:
    #718078;

  font-size:
    13px;

  line-height:
    1.6;

}


/* =========================================================
   VOICE VOLUME METER
   ========================================================= */

.voice-assistant-volume-meter {

  height:
    24px;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    3px;

  margin-top:
    18px;

}


.voice-assistant-volume-meter span {

  width:
    4px;

  height:
    18px;

  border-radius:
    99px;

  background:
    rgba(61, 123, 76, 0.17);

  transform-origin:
    center;

  transition:
    background 70ms linear,
    transform 70ms linear;

}


.voice-assistant-volume-meter span.active {

  background:
    linear-gradient(
      180deg,
      #73ae79,
      #4a9160
    );

}


/* =========================================================
   CHAT
   ========================================================= */

.voice-assistant-conversation {

  display:
    flex;

  flex-direction:
    column;

  gap:
    20px;

}


.voice-assistant-message {

  width:
    100%;

  display:
    flex;

  flex-direction:
    column;

  animation:
    voice-assistant-message-in
    180ms ease-out;

}


.voice-assistant-message.user {

  align-items:
    flex-end;

}


.voice-assistant-message.assistant {

  align-items:
    flex-start;

}


/* =========================================================
   MESSAGE META
   ========================================================= */

.voice-assistant-message-meta {

  display:
    flex;

  align-items:
    center;

  gap:
    7px;

  margin:
    0 8px 6px;

}


.voice-assistant-message.user
.voice-assistant-message-meta {

  flex-direction:
    row-reverse;

}


.voice-assistant-message-label {

  color:
    #547162;

  font-size:
    10px;

  font-weight:
    800;

  letter-spacing:
    0.06em;

  text-transform:
    uppercase;

}


.voice-assistant-message-time {

  display:
    inline-flex;

  align-items:
    center;

  gap:
    3px;

  color:
    #929c96;

  font-size:
    9px;

  font-weight:
    500;

}


/* =========================================================
   MESSAGE BUBBLES
   ========================================================= */

.voice-assistant-message-bubble {

  max-width:
    min(
      86%,
      510px
    );

  padding:
    12px 15px;

  border-radius:
    17px;

  font-size:
    13px;

  line-height:
    1.62;

  overflow-wrap:
    anywhere;

}


/* User */

.voice-assistant-message.user
.voice-assistant-message-bubble {

  color:
    #204d30;

  background:
    linear-gradient(
      145deg,
      #e5f5e8,
      #eaf4fc
    );

  border:
    1px solid
    rgba(72, 130, 88, 0.11);

  border-bottom-right-radius:
    5px;

  box-shadow:
    0 6px 18px
      rgba(42, 96, 61, 0.07);

}


/* Assistant */

.voice-assistant-message.assistant
.voice-assistant-message-bubble {

  color:
    #38483e;

  background:
    rgba(255, 255, 255, 0.76);

  border:
    1px solid
    rgba(55, 87, 66, 0.10);

  border-bottom-left-radius:
    5px;

  box-shadow:
    0 6px 20px
      rgba(35, 65, 46, 0.06),

    inset 0 1px 0
      rgba(255, 255, 255, 0.80);

}


/* Failed response */

.voice-assistant-message.failed
.voice-assistant-message.assistant
.voice-assistant-message-bubble {

  background:
    rgba(255, 243, 236, 0.80);

  border-color:
    rgba(170, 104, 79, 0.15);

}


/* =========================================================
   MESSAGE TOOLS
   ========================================================= */

.voice-assistant-message-tools {

  display:
    flex;

  align-items:
    center;

  gap:
    5px;

  margin:
    6px 8px 0;

  opacity:
    0.62;

  transition:
    opacity 150ms ease;

}


.voice-assistant-message:hover
.voice-assistant-message-tools {

  opacity:
    1;

}


.voice-assistant-message-tools button {

  display:
    inline-flex;

  align-items:
    center;

  gap:
    4px;

  min-height:
    25px;

  padding:
    4px 7px;

  border:
    1px solid
    transparent;

  border-radius:
    7px;

  cursor:
    pointer;

  color:
    #60746a;

  background:
    transparent;

  font-size:
    9px;

  transition:
    color 150ms ease,
    background 150ms ease,
    border-color 150ms ease;

}


.voice-assistant-message-tools button:hover {

  color:
    #2d6942;

  background:
    #edf7ef;

  border-color:
    rgba(55, 110, 70, 0.10);

}


/* =========================================================
   THINKING
   ========================================================= */

.voice-assistant-thinking {

  display:
    inline-flex;

  align-items:
    center;

  gap:
    9px;

  color:
    #688073;

}


.voice-assistant-thinking-dots {

  display:
    inline-flex;

  align-items:
    center;

  gap:
    3px;

}


.voice-assistant-thinking-dots i {

  width:
    5px;

  height:
    5px;

  border-radius:
    50%;

  background:
    #4c9161;

  animation:
    assistant-thinking-dot
    1.15s infinite ease-in-out;

}


.voice-assistant-thinking-dots i:nth-child(2) {

  animation-delay:
    120ms;

}


.voice-assistant-thinking-dots i:nth-child(3) {

  animation-delay:
    240ms;

}


/* =========================================================
   LIVE TRANSCRIPT
   ========================================================= */

.voice-assistant-live-transcript {

  margin:
    17px 4px 4px;

  padding:
    11px 13px;

  border:
    1px solid
    rgba(67, 133, 84, 0.13);

  border-radius:
    13px;

  background:
    rgba(231, 245, 235, 0.68);

}


.voice-assistant-live-transcript > div {

  display:
    flex;

  align-items:
    center;

  gap:
    6px;

  color:
    #477658;

  font-size:
    10px;

  font-weight:
    800;

  text-transform:
    uppercase;

}


.voice-assistant-live-transcript p {

  margin:
    5px 0 0;

  color:
    #375340;

  font-size:
    12px;

  line-height:
    1.55;

}


/* =========================================================
   ERROR
   ========================================================= */

.voice-assistant-error-card {

  margin:
    12px 2px;

  padding:
    9px 12px;

  border:
    1px solid
    rgba(175, 99, 75, 0.13);

  border-radius:
    11px;

  color:
    #875c50;

  background:
    rgba(255, 242, 237, 0.76);

  font-size:
    11px;

  line-height:
    1.45;

}


/* =========================================================
   SUGGESTIONS
   ========================================================= */

.voice-assistant-suggestions {

  margin:
    16px 0 0;

}


.voice-assistant-suggestions-title {

  display:
    block;

  margin:
    0 0 8px 3px;

  color:
    #728078;

  font-size:
    10px;

  font-weight:
    800;

}


.voice-assistant-suggestions > div {

  display:
    flex;

  flex-wrap:
    wrap;

  gap:
    7px;

}


.voice-assistant-suggestions button {

  max-width:
    100%;

  padding:
    8px 11px;

  border:
    1px solid
    rgba(63, 119, 77, 0.12);

  border-radius:
    999px;

  cursor:
    pointer;

  color:
    #456b53;

  background:
    rgba(237, 247, 239, 0.84);

  font-size:
    10px;

  line-height:
    1.35;

  text-align:
    left;

  transition:
    transform 150ms ease,
    background 150ms ease,
    color 150ms ease,
    border-color 150ms ease,
    box-shadow 150ms ease;

}


.voice-assistant-suggestions button:hover {

  transform:
    translateY(-1px);

  color:
    #245e39;

  background:
    #e3f3e7;

  border-color:
    rgba(63, 119, 77, 0.20);

  box-shadow:
    0 5px 13px
      rgba(46, 100, 62, 0.08);

}


/* =========================================================
   COMPOSER
   ========================================================= */

.voice-assistant-composer {

  position:
    relative;

  z-index:
    3;

  flex:
    0 0 auto;

  padding:
    12px 16px 15px;

  border-top:
    1px solid
    rgba(53, 91, 67, 0.09);

  background:
    linear-gradient(
      180deg,
      rgba(246, 250, 247, 0.74),
      rgba(255, 255, 255, 0.86)
    );

  backdrop-filter:
    blur(18px);

  -webkit-backdrop-filter:
    blur(18px);

}


/* =========================================================
   TEXT INPUT
   ========================================================= */

.voice-assistant-text-form {

  display:
    flex;

  align-items:
    center;

  gap:
    8px;

  min-height:
    50px;

  padding:
    5px 5px 5px 15px;

  border:
    1px solid
    rgba(60, 111, 75, 0.14);

  border-radius:
    15px;

  background:
    rgba(255, 255, 255, 0.91);

  box-shadow:
    0 7px 22px
      rgba(38, 78, 49, 0.06),

    inset 0 1px 0
      rgba(255, 255, 255, 0.85);

  transition:
    border-color 160ms ease,
    box-shadow 160ms ease;

}


.voice-assistant-text-form:focus-within {

  border-color:
    rgba(60, 127, 78, 0.36);

  box-shadow:
    0 8px 24px
      rgba(38, 100, 57, 0.08),

    0 0 0 3px
      rgba(72, 151, 89, 0.08);

}


.voice-assistant-text-form input {

  min-width:
    0;

  flex:
    1 1 auto;

  height:
    40px;

  padding:
    0;

  border:
    0;

  outline:
    0;

  color:
    #304139;

  background:
    transparent;

  font:
    inherit;

  font-size:
    13px;

}


.voice-assistant-text-form input::placeholder {

  color:
    #95a19b;

}


.voice-assistant-text-form input:disabled {

  opacity:
    0.56;

}


/* =========================================================
   SEND BUTTON
   ========================================================= */

.voice-assistant-text-form > button {

  width:
    40px;

  height:
    40px;

  flex:
    0 0 40px;

  display:
    grid;

  place-items:
    center;

  border:
    0;

  border-radius:
    11px;

  cursor:
    pointer;

  color:
    #ffffff;

  background:
    linear-gradient(
      145deg,
      #3b8a56,
      #5d8fb3
    );

  box-shadow:
    0 6px 15px
      rgba(52, 115, 70, 0.17);

  transition:
    transform 150ms ease,
    filter 150ms ease,
    opacity 150ms ease;

}


.voice-assistant-text-form > button:hover:not(:disabled) {

  transform:
    translateY(-1px)
    scale(1.03);

  filter:
    brightness(1.04);

}


.voice-assistant-text-form > button:disabled {

  opacity:
    0.38;

  cursor:
    default;

  box-shadow:
    none;

}


/* =========================================================
   MAIN VOICE BUTTON
   ========================================================= */

.voice-assistant-main-button {

  position:
    relative;

  width:
    100%;

  min-height:
    48px;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    9px;

  margin-top:
    9px;

  overflow:
    hidden;

  border:
    1px solid
    rgba(56, 120, 75, 0.18);

  border-radius:
    13px;

  cursor:
    pointer;

  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      #3b8e58,
      #4c9071
    );

  font-size:
    12px;

  font-weight:
    800;

  box-shadow:
    0 7px 20px
      rgba(45, 111, 63, 0.14);

  transition:
    transform 160ms ease,
    filter 160ms ease,
    box-shadow 160ms ease;

}


.voice-assistant-main-button::before {

  content:
    "";

  position:
    absolute;

  inset:
    0;

  background:
    linear-gradient(
      100deg,
      transparent 15%,
      rgba(255, 255, 255, 0.17) 48%,
      transparent 82%
    );

  transform:
    translateX(-120%);

  transition:
    transform 500ms ease;

}


.voice-assistant-main-button:hover:not(:disabled) {

  transform:
    translateY(-2px);

  filter:
    brightness(1.025);

  box-shadow:
    0 10px 25px
      rgba(45, 111, 63, 0.20);

}


.voice-assistant-main-button:hover::before {

  transform:
    translateX(120%);

}


.voice-assistant-main-button.stop {

  background:
    linear-gradient(
      135deg,
      #bd6552,
      #ab7155
    );

  border-color:
    rgba(165, 78, 60, 0.24);

  box-shadow:
    0 7px 20px
      rgba(162, 83, 68, 0.15);

}


.voice-assistant-main-button:disabled {

  opacity:
    0.50;

  cursor:
    default;

  transform:
    none;

}


/* =========================================================
   BUTTON PULSE
   ========================================================= */

.voice-assistant-button-pulse {

  position:
    absolute;

  right:
    18px;

  width:
    8px;

  height:
    8px;

  border-radius:
    50%;

  background:
    #ffe28a;

  box-shadow:
    0 0 0 0
      rgba(255, 226, 138, 0.45);

  animation:
    assistant-button-pulse
    1.15s infinite;

}


/* =========================================================
   CONTROL ROW
   ========================================================= */

.voice-assistant-control-row {

  display:
    flex;

  align-items:
    center;

  gap:
    7px;

  min-height:
    31px;

  margin-top:
    8px;

}


.voice-assistant-control-button,
.voice-assistant-stop-speaking {

  display:
    inline-flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    5px;

  min-height:
    29px;

  padding:
    5px 9px;

  border:
    1px solid
    rgba(57, 102, 69, 0.11);

  border-radius:
    8px;

  cursor:
    pointer;

  color:
    #557364;

  background:
    rgba(232, 243, 234, 0.75);

  font-size:
    9px;

  font-weight:
    700;

  transition:
    color 150ms ease,
    background 150ms ease,
    transform 150ms ease;

}


.voice-assistant-control-button:hover,
.voice-assistant-stop-speaking:hover {

  color:
    #245d39;

  background:
    #e1f2e5;

  transform:
    translateY(-1px);

}


.voice-assistant-stop-speaking {

  color:
    #915d50;

  background:
    rgba(253, 239, 233, 0.84);

}


.voice-assistant-stop-speaking:hover {

  color:
    #ffffff;

  background:
    #bd6956;

}


.voice-assistant-page-indicator {

  margin-left:
    auto;

  min-width:
    0;

  overflow:
    hidden;

  color:
    #98a19c;

  font-size:
    9px;

  text-overflow:
    ellipsis;

  white-space:
    nowrap;

}


/* =========================================================
   PRIVACY / SHORTCUT
   ========================================================= */

.voice-assistant-privacy {

  display:
    flex;

  align-items:
    center;

  gap:
    5px;

  margin-top:
    8px;

  color:
    #98a29c;

  font-size:
    8.5px;

  line-height:
    1.35;

}


.voice-assistant-privacy svg {

  flex:
    0 0 auto;

  color:
    #6ca078;

}


.voice-assistant-shortcut {

  margin-left:
    auto;

  padding:
    3px 6px;

  border-radius:
    5px;

  color:
    #7c8e83;

  background:
    rgba(227, 237, 229, 0.72);

  font-size:
    8px;

  font-weight:
    700;

}


/* =========================================================
   ANIMATIONS
   ========================================================= */

@keyframes voice-assistant-panel-in {

  from {

    opacity:
      0;

    transform:
      translateY(18px)
      scale(0.97);

  }

  to {

    opacity:
      1;

    transform:
      translateY(0)
      scale(1);

  }

}


@keyframes voice-assistant-backdrop-in {

  from {

    opacity:
      0;

  }

  to {

    opacity:
      1;

  }

}


@keyframes voice-assistant-message-in {

  from {

    opacity:
      0;

    transform:
      translateY(7px);

  }

  to {

    opacity:
      1;

    transform:
      translateY(0);

  }

}


@keyframes assistant-mic-breathe {

  0%,
  100% {

    box-shadow:
      inset 0 0 0 1px
        rgba(255, 255, 255, 0.22),

      0 0 0 0
        rgba(69, 149, 91, 0.24);

  }

  50% {

    box-shadow:
      inset 0 0 0 1px
        rgba(255, 255, 255, 0.30),

      0 0 0 11px
        rgba(69, 149, 91, 0.07);

  }

}


@keyframes assistant-listening-breathe {

  0%,
  100% {

    box-shadow:
      0 16px 32px
        rgba(47, 101, 66, 0.14),

      0 0 0 0
        rgba(69, 149, 91, 0.24);

  }

  50% {

    box-shadow:
      0 18px 38px
        rgba(47, 101, 66, 0.18),

      0 0 0 10px
        rgba(69, 149, 91, 0.06);

  }

}


@keyframes assistant-thinking-dot {

  0%,
  60%,
  100% {

    opacity:
      0.30;

    transform:
      translateY(0);

  }

  30% {

    opacity:
      1;

    transform:
      translateY(-3px);

  }

}


@keyframes voice-assistant-live-dot {

  0%,
  100% {

    transform:
      scale(0.82);

    opacity:
      0.65;

  }

  50% {

    transform:
      scale(1.18);

    opacity:
      1;

  }

}


@keyframes assistant-button-pulse {

  0% {

    box-shadow:
      0 0 0 0
      rgba(255, 226, 138, 0.42);

  }

  70% {

    box-shadow:
      0 0 0 8px
      rgba(255, 226, 138, 0);

  }

  100% {

    box-shadow:
      0 0 0 0
      rgba(255, 226, 138, 0);

  }

}


