    rgba(206, 221, 239, 0.09);

}


[data-theme="midnight"]
.voice-assistant-message.user
.voice-assistant-message-bubble,
.midnight
.voice-assistant-message.user
.voice-assistant-message-bubble {

  color:
    #dcecf0;

  background:
    linear-gradient(
      145deg,
      rgba(52, 107, 79, 0.57),
      rgba(53, 92, 124, 0.56)
    );

}


[data-theme="midnight"]
.voice-assistant-composer,
.midnight
.voice-assistant-composer {

  background:
    linear-gradient(
      180deg,
      rgba(20, 31, 44, 0.84),
      rgba(17, 27, 39, 0.96)
    );

}


[data-theme="midnight"]
.voice-assistant-text-form,
.midnight
.voice-assistant-text-form {

  background:
    rgba(28, 40, 55, 0.92);

  border-color:
    rgba(211, 225, 242, 0.11);

}


[data-theme="midnight"]
.voice-assistant-text-form input,
.midnight
.voice-assistant-text-form input {

  color:
    #e7eef8;

}


/* =========================================================
   HIGH CONTRAST / REDUCED MOTION
   ========================================================= */

@media (
  prefers-reduced-motion: reduce
) {

  .voice-assistant-floating,
  .voice-assistant-panel,
  .voice-assistant-message,
  .voice-assistant-orb,
  .voice-assistant-main-button,
  .voice-assistant-floating-icon {

    animation:
      none !important;

    transition:
      none !important;

  }

}


/* =========================================================
   MOBILE
   ========================================================= */

@media (
  max-width: 700px
) {

  .voice-assistant-floating {

    right:
      15px;

    bottom:
      18px;

    min-height:
      54px;

  }


  .voice-assistant-backdrop {

    align-items:
      flex-end;

    justify-content:
      center;

    padding:
      10px;

  }


  .voice-assistant-panel {

    width:
      100%;

    max-width:
      none;

    height:
      min(
        820px,
        calc(100vh - 20px)
      );

    min-height:
      0;

    border-radius:
      24px;

  }


  .voice-assistant-body {

    padding:
      15px 13px 11px;

  }


  .voice-assistant-message-bubble {

    max-width:
      90%;

  }


  .voice-assistant-welcome {

    min-height:
      255px;

  }


  .voice-assistant-floating-label {

    font-size:
      13px;

  }

}


/* =========================================================
   SMALL PHONE
   ========================================================= */

@media (
  max-width: 430px
) {

  .voice-assistant-floating {

    padding-right:
      11px;

  }


  .voice-assistant-floating-label {

    display:
      none;

  }


  .voice-assistant-floating-icon {

    width:
      42px;

    height:
      42px;

  }


  .voice-assistant-panel-header {

    padding:
      14px;

  }


  .voice-assistant-heading-icon {

    width:
      40px;

    height:
      40px;

  }


  .voice-assistant-message-bubble {

    font-size:
      12px;

  }


  .voice-assistant-page-indicator {

    display:
      none;

  }

  .voice-assistant-body {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
}
}


/* =========================================================
   KRISHISETU AI ASSISTANT
   Responsive / stable / floating-window implementation
   ========================================================= */

.voice-assistant-floating {

  position: fixed;

  right:
    clamp(16px, 2.4vw, 32px);

  bottom:
    clamp(22px, 4vh, 42px);

  z-index:
    9998;

  display:
    inline-flex;

  align-items:
    center;

  gap:
    10px;

  min-width:
    0;

  min-height:
    58px;

  padding:
    8px 16px 8px 9px;

  border:
    1px solid
    rgba(255,255,255,0.48);

  border-radius:
    999px;

  cursor:
    pointer;

  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      #2f7d4a 0%,
      #408d5b 52%,
      #5b91bb 100%
    );

  box-shadow:
    0 14px 38px
      rgba(34,82,51,0.26),

    0 4px 12px
      rgba(34,82,51,0.14),

    inset 0 1px 0
      rgba(255,255,255,0.42);

  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    filter 180ms ease;

  isolation:
    isolate;

}


.voice-assistant-floating:hover {

  transform:
    translateY(-3px);

  box-shadow:
    0 18px 44px
      rgba(34,82,51,0.31),

    0 5px 14px
      rgba(34,82,51,0.16),

    inset 0 1px 0
      rgba(255,255,255,0.52);

}


.voice-assistant-floating:active {

  transform:
    translateY(0)
    scale(0.985);

}


.voice-assistant-floating-icon {

  width:
    42px;

  height:
    42px;

  flex:
    0 0 42px;

  display:
    grid;

  place-items:
    center;

  border-radius:
    50%;

  color:
    #285f3b;

  background:
    rgba(255,255,255,0.94);

  box-shadow:
    inset 0 1px 0
      rgba(255,255,255,0.92),

    0 3px 10px
      rgba(20,54,31,0.15);

}


.voice-assistant-floating-label {

  font-size:
    14px;

  font-weight:
    800;

  white-space:
    nowrap;

}


.voice-assistant-floating-live-dot {

  width:
    8px;

  height:
    8px;

  flex:
    0 0 8px;

  border-radius:
    50%;

  background:
    #ffe08a;

  box-shadow:
    0 0 0 5px
      rgba(255,224,138,0.14);

  animation:
    ai-live-dot
    1.1s ease-in-out infinite;

}


/* =========================================================
   BACKDROP
   ========================================================= */

.voice-assistant-backdrop {

  position:
    fixed;

  inset:
    0;

  z-index:
    9997;

  display:
    flex;

  align-items:
    flex-end;

  justify-content:
    flex-end;

  padding:
    clamp(12px, 2.5vw, 26px);

  box-sizing:
    border-box;

  background:
    rgba(17,35,23,0.13);

  backdrop-filter:
    blur(3px);

  -webkit-backdrop-filter:
    blur(3px);

  overflow:
    hidden;

  overscroll-behavior:
    none;

  animation:
    ai-backdrop-in
    160ms ease-out;

}


/* =========================================================
   PANEL
   ========================================================= */

.voice-assistant-panel {

  position:
    relative;

  width:
    min(
      640px,
      calc(100vw - 28px)
    );

  height:
    min(
      760px,
      calc(100dvh - 28px)
    );

  max-height:
    calc(100dvh - 28px);

  min-height:
    0;

  display:
    flex;

  flex-direction:
    column;

  flex:
    0 1 auto;

  overflow:
    hidden;

  box-sizing:
    border-box;

  border:
    1px solid
    rgba(255,255,255,0.62);

  border-radius:
    28px;

  color:
    #29382f;

  background:
    linear-gradient(
      145deg,
      rgba(255,255,255,0.94),
      rgba(242,248,244,0.90)
    );

  box-shadow:
    0 32px 90px
      rgba(24,53,34,0.22),

    0 10px 28px
      rgba(24,53,34,0.12),

    inset 0 1px 0
      rgba(255,255,255,0.92);

  backdrop-filter:
    blur(22px)
    saturate(125%);

  -webkit-backdrop-filter:
    blur(22px)
    saturate(125%);

  animation:
    ai-panel-in
    220ms
    cubic-bezier(
      0.22,
      1,
      0.36,
      1
    );

}


/* =========================================================
   HEADER
   ========================================================= */

.voice-assistant-panel-header {

  position:
    relative;

  z-index:
    5;

  flex:
    0 0 auto;

  display:
    flex;

  align-items:
    center;

  justify-content:
    space-between;

  gap:
    12px;

  min-height:
    76px;

  padding:
    14px 16px;

  box-sizing:
    border-box;

  border-bottom:
    1px solid
    rgba(48,87,61,0.10);

  background:
    linear-gradient(
      180deg,
      rgba(255,255,255,0.88),
      rgba(242,248,244,0.70)
    );

}


/* =========================================================
   HEADING
   ========================================================= */

.voice-assistant-heading {

  min-width:
    0;

  display:
    flex;

  align-items:
    center;

  gap:
    11px;

}


.voice-assistant-heading-icon {

  width:
    43px;

  height:
    43px;

  flex:
    0 0 43px;

  display:
    grid;

  place-items:
    center;

  border-radius:
    13px;

  color:
    #2c7046;

  background:
    linear-gradient(
      145deg,
      #e3f2e6,
      #e3eff9
    );

  border:
    1px solid
    rgba(61,119,78,0.10);

}


.voice-assistant-title-row {

  display:
    flex;

  align-items:
    center;

  gap:
    7px;

}


.voice-assistant-title-row strong {

  color:
    #275d3c;

  font-size:
    17px;

  line-height:
    1.2;

  font-weight:
    850;

}


.voice-assistant-heading >
div:last-child >
span {

  display:
    block;

  margin-top:
    3px;

  color:
    #6b7a70;

  font-size:
    11px;

  line-height:
    1.35;

}


.voice-assistant-status-dot {

  width:
    7px;

  height:
    7px;

  border-radius:
    50%;

}


.voice-assistant-status-dot.online {

  background:
    #4c9a63;

  box-shadow:
    0 0 0 4px
      rgba(76,154,99,0.10);

}


.voice-assistant-status-dot.offline {

  background:
    #b66c57;

  box-shadow:
    0 0 0 4px
      rgba(182,108,87,0.10);

}


/* =========================================================
   HEADER CONTROLS
   ========================================================= */

.voice-assistant-header-actions {

  display:
    flex;

  align-items:
    center;

  gap:
    7px;

}


.voice-assistant-reset,
.voice-assistant-close {

  width:
    40px;

  height:
    40px;

  flex:
    0 0 40px;

  display:
    grid;

  place-items:
    center;

  border:
    1px solid
    rgba(55,95,67,0.11);

  border-radius:
    11px;

  cursor:
    pointer;

  transition:
    transform 160ms ease,
    color 160ms ease,
    background 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease;

}


.voice-assistant-reset {

  color:
    #527260;

  background:
    rgba(231,243,234,0.82);

}


.voice-assistant-reset:hover:not(:disabled) {

  color:
    #ffffff;

  background:
    #3e8257;

  border-color:
    #3e8257;

  transform:
    translateY(-2px)
    rotate(-7deg);

  box-shadow:
    0 7px 17px
      rgba(62,130,87,0.18);

}


.voice-assistant-close {

  color:
    #856a63;

  background:
    rgba(251,239,235,0.88);

}


.voice-assistant-close:hover {

  color:
    #ffffff;

  background:
    #c96957;

  border-color:
    #c96957;

  transform:
    translateY(-2px)
    scale(1.04);

  box-shadow:
    0 7px 17px
      rgba(201,105,87,0.20);

}


.voice-assistant-reset:disabled {

  opacity:
    0.35;

  cursor:
    default;

}


/* =========================================================
   SCROLLABLE BODY
   ========================================================= */

.voice-assistant-body {

  position:
    relative;

  z-index:
    1;

  flex:
    1 1 auto;

  min-height:
    0;

  width:
    100%;

  overflow-y:
    auto;

  overflow-x:
    hidden;

  box-sizing:
    border-box;

  padding:
    16px 17px 18px;

  overscroll-behavior:
    contain;

  -webkit-overflow-scrolling:
    touch;

  touch-action:
    pan-y;

  scrollbar-width:
    thin;

  scrollbar-color:
    rgba(67,119,80,0.27)
    transparent;

}


.voice-assistant-body::-webkit-scrollbar {

  width:
    7px;

}


.voice-assistant-body::-webkit-scrollbar-track {

  background:
    transparent;

}


.voice-assistant-body::-webkit-scrollbar-thumb {

  border-radius:
    99px;

  background:
    rgba(67,119,80,0.25);

}


.voice-assistant-body::-webkit-scrollbar-thumb:hover {

  background:
    rgba(67,119,80,0.40);

}


/* =========================================================
   CONNECTION PILL
   ========================================================= */

.voice-assistant-connectivity {

  width:
    max-content;

  max-width:
    100%;

  display:
    flex;

  align-items:
    center;

  gap:
    6px;

  margin:
    0 auto 12px;

  padding:
    5px 9px;

  border:
    1px solid
    rgba(69,126,82,0.10);

  border-radius:
    999px;

  color:
    #4f785d;

  background:
    rgba(229,243,232,0.76);

  font-size:
    9px;

  font-weight:
    750;

}


.voice-assistant-connectivity.offline {

  color:
    #986252;

  background:
    rgba(252,238,233,0.82);

  border-color:
    rgba(153,92,73,0.11);

}


/* =========================================================
   WELCOME
   ========================================================= */

.voice-assistant-welcome {

  position:
    relative;

  min-height:
    clamp(
      240px,
      38vh,
      320px
    );

  display:
    flex;

  flex-direction:
    column;

  align-items:
    center;

  justify-content:
    center;

  padding:
    22px 10px;

  text-align:
    center;

}


.voice-assistant-welcome-glow {

  position:
    absolute;

  top:
    50%;

  left:
    50%;

  width:
    250px;

  height:
    190px;

  transform:
    translate(
      -50%,
      -55%
    );

  border-radius:
    50%;

  background:
    radial-gradient(
      ellipse,
      rgba(
        76,
        151,
        93,
        calc(
          0.10 +
          var(--voice-intensity,0) *
          0.20
        )
      ),
      transparent 70%
    );

  filter:
    blur(11px);

  pointer-events:
    none;

}


.voice-assistant-orb {

  position:
    relative;

  width:
    88px;

  height:
    88px;

  flex:
    0 0 88px;

  display:
    grid;

  place-items:
    center;

  border:
    1px solid
    rgba(255,255,255,0.86);

  border-radius:
    50%;

  color:
    #2d7449;

  background:
    linear-gradient(
      145deg,
      rgba(226,245,230,0.95),
      rgba(224,239,250,0.92)
    );

  box-shadow:
    0 18px 35px
      rgba(47,102,65,0.13),

    inset 0 2px 0
      rgba(255,255,255,0.96),

    0 0
      calc(
        9px +
        var(--voice-intensity,0) *
        30px
      )
      rgba(
        67,
        150,
        88,
        calc(
          var(--voice-intensity,0) *
          0.20
        )
      );

  transition:
    transform 70ms linear,
    box-shadow 70ms linear;

}


.voice-assistant-orb.listening {

  color:
    #ffffff;

  background:
    linear-gradient(
      145deg,
      #378b58,
      #5792be
    );

  transform:
    scale(
      calc(
        1 +
        var(--voice-intensity,0) *
        0.055
      )
    );

  animation:
    ai-listening-breathe
    1.35s
    ease-in-out infinite;

}


.voice-assistant-state {

  max-width:
    460px;

  margin-top:
    18px;

}


.voice-assistant-state strong {

  display:
    block;

  color:
    #285f3f;

  font-size:
    clamp(
      18px,
      2.6vw,
      23px
    );

  line-height:
    1.25;

  font-weight:
    850;

}


.voice-assistant-state span {

  display:
    block;

  margin-top:
    7px;

  color:
    #748178;

  font-size:
    12px;

  line-height:
    1.55;

}


/* =========================================================
   VOICE METER
   ========================================================= */

.voice-assistant-volume-meter {

  height:
    24px;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    3px;

  margin-top:
    16px;

}


.voice-assistant-volume-meter span {

  width:
    4px;

  height:
    18px;

  border-radius:
    99px;

  background:
    rgba(66,127,82,0.15);

  transform-origin:
    center;

  transition:
    transform 65ms linear,
    background 65ms linear;

}


.voice-assistant-volume-meter span.active {

  background:
    linear-gradient(
      180deg,
      #74ad7e,
      #468c5a
    );

}


/* =========================================================
   CONVERSATION
   ========================================================= */

.voice-assistant-conversation {

  display:
    flex;

  flex-direction:
    column;

  gap:
    20px;

  min-width:
    0;

}


.voice-assistant-message {

  width:
    100%;

  min-width:
    0;

  display:
    flex;

  flex-direction:
    column;

  animation:
    ai-message-in
    180ms ease-out;

}


.voice-assistant-message.user {

  align-items:
    flex-end;

}


.voice-assistant-message.assistant {

  align-items:
    flex-start;

}


.voice-assistant-message-meta {

  display:
    flex;

  align-items:
    center;

  gap:
    7px;

  margin:
    0 7px 6px;

}


.voice-assistant-message.user
.voice-assistant-message-meta {

  flex-direction:
    row-reverse;

}


.voice-assistant-message-label {

  color:
    #557665;

  font-size:
    9px;

  line-height:
    1;

  font-weight:
    850;

  letter-spacing:
    0.065em;

  text-transform:
    uppercase;

}


.voice-assistant-message-time {

  display:
    inline-flex;

  align-items:
    center;

  gap:
    3px;

  color:
    #98a29c;

  font-size:
    9px;

}


/* =========================================================
   CHAT BUBBLES
   ========================================================= */

.voice-assistant-message-bubble {

  max-width:
    min(
      88%,
      540px
    );

  padding:
    12px 15px;

  border-radius:
    17px;

  box-sizing:
    border-box;

  overflow-wrap:
    anywhere;

  word-break:
    break-word;

  font-size:
    12.5px;

  line-height:
    1.62;

}


.voice-assistant-message.user
.voice-assistant-message-bubble {

  color:
    #214e31;

  background:
    linear-gradient(
      145deg,
      #e4f4e8,
      #eaf3fb
    );

  border:
    1px solid
    rgba(70,124,84,0.10);

  border-bottom-right-radius:
    5px;

  box-shadow:
    0 7px 17px
      rgba(41,93,57,0.06);

}


.voice-assistant-message.assistant
.voice-assistant-message-bubble {

  color:
    #37483d;

  background:
    rgba(255,255,255,0.78);

  border:
    1px solid
    rgba(57,90,68,0.10);

  border-bottom-left-radius:
    5px;

  box-shadow:
    0 7px 18px
      rgba(33,63,44,0.055),

    inset 0 1px 0
      rgba(255,255,255,0.84);

}


.voice-assistant-message.failed
.voice-assistant-message-bubble {

  color:
    #855a4f;

  background:
    rgba(255,241,235,0.78);

  border-color:
    rgba(166,95,74,0.13);

}


/* =========================================================
   MESSAGE TOOLS
   ========================================================= */

.voice-assistant-message-tools {

  display:
    flex;

  align-items:
    center;

  gap:
    5px;

  margin:
    6px 7px 0;

  opacity:
    0.62;

  transition:
    opacity 150ms ease;

}


.voice-assistant-message:hover
.voice-assistant-message-tools {

  opacity:
    1;

}


.voice-assistant-message-tools button {

  display:
    inline-flex;

  align-items:
    center;

  gap:
    4px;

  min-height:
    25px;

  padding:
    4px 7px;

  border:
    1px solid
    transparent;

  border-radius:
    7px;

  cursor:
    pointer;

  color:
    #63776c;

  background:
    transparent;

  font-size:
    9px;

  transition:
    color 150ms ease,
    background 150ms ease,
    border-color 150ms ease;

}


.voice-assistant-message-tools button:hover {

  color:
    #2b6941;

  background:
    #eaf6ed;

  border-color:
    rgba(58,111,73,0.10);

}


/* =========================================================
   THINKING
   ========================================================= */

.voice-assistant-thinking {

  display:
    inline-flex;

  align-items:
    center;

  gap:
    9px;

  color:
    #668073;

}


.voice-assistant-thinking-dots {

  display:
    inline-flex;

  align-items:
    center;

  gap:
    3px;

}


.voice-assistant-thinking-dots i {

  width:
    5px;

  height:
    5px;

  border-radius:
    50%;

  background:
    #4b9160;

  animation:
    ai-thinking-dot
    1.1s
    ease-in-out
    infinite;

}


.voice-assistant-thinking-dots i:nth-child(2) {

  animation-delay:
    110ms;

}


.voice-assistant-thinking-dots i:nth-child(3) {

  animation-delay:
    220ms;

}


/* =========================================================
   LIVE TRANSCRIPT
   ========================================================= */

.voice-assistant-live-transcript {

  margin:
    14px 2px 2px;

  padding:
    10px 12px;

  border:
    1px solid
    rgba(66,130,82,0.12);

  border-radius:
    12px;

  background:
    rgba(231,245,235,0.68);

}


.voice-assistant-live-transcript > div {

  display:
    flex;

  align-items:
    center;

  gap:
    6px;

  color:
    #4a7758;

  font-size:
    9px;

  font-weight:
    800;

  text-transform:
    uppercase;

}


.voice-assistant-live-transcript p {

  margin:
    5px 0 0;

  color:
    #3c5946;

  font-size:
    11px;

  line-height:
    1.55;

  overflow-wrap:
    anywhere;

}


/* =========================================================
   ERROR
   ========================================================= */

.voice-assistant-error-card {

  margin:
    12px 2px 0;

  padding:
    9px 11px;

  border:
    1px solid
    rgba(172,101,76,0.12);

  border-radius:
    11px;

  color:
    #875c50;

  background:
    rgba(255,242,237,0.78);

  font-size:
    10.5px;

  line-height:
    1.45;

}


/* =========================================================
   SUGGESTIONS
   ========================================================= */

.voice-assistant-suggestions {

  margin:
    17px 0 0;

}


.voice-assistant-suggestions-title {

  display:
    block;

  margin:
    0 0 8px 2px;

  color:
    #78857d;

  font-size:
    9px;

  font-weight:
    800;

}


.voice-assistant-suggestions > div {

  display:
    flex;

  flex-wrap:
    wrap;

  gap:
    7px;

}


.voice-assistant-suggestions button {

  max-width:
    100%;

  padding:
    7px 10px;

  border:
    1px solid
    rgba(63,119,77,0.11);

  border-radius:
    999px;

  cursor:
    pointer;

  color:
    #486d56;

  background:
    rgba(238,247,240,0.85);

  font-size:
    9.5px;

  line-height:
    1.35;

  text-align:
    left;

  transition:
    transform 150ms ease,
    background 150ms ease,
    color 150ms ease,
    border-color 150ms ease;

}


.voice-assistant-suggestions button:hover {

  transform:
    translateY(-1px);

  color:
    #285f3d;

  background:
    #e2f3e6;

  border-color:
    rgba(63,119,77,0.18);

}


/* =========================================================
   COMPOSER
   ========================================================= */

.voice-assistant-composer {

  position:
    relative;

  z-index:
    6;

  flex:
    0 0 auto;

  width:
    100%;

  min-width:
    0;

  box-sizing:
    border-box;

  padding:
    11px 15px 14px;

  border-top:
    1px solid
    rgba(53,92,67,0.09);

  background:
    linear-gradient(
      180deg,
      rgba(247,251,248,0.82),
      rgba(255,255,255,0.92)
    );

  backdrop-filter:
    blur(18px);

  -webkit-backdrop-filter:
    blur(18px);

}


/* =========================================================
   INPUT
   ========================================================= */

.voice-assistant-text-form {

  width:
    100%;

  min-height:
    50px;

  display:
    flex;

  align-items:
    center;

  gap:
    7px;

  box-sizing:
    border-box;

  padding:
    5px 5px 5px 14px;

  border:
    1px solid
    rgba(59,111,74,0.14);

  border-radius:
    15px;

  background:
    rgba(255,255,255,0.94);

  box-shadow:
    0 7px 20px
      rgba(39,79,50,0.055),

    inset 0 1px 0
      rgba(255,255,255,0.90);

}


.voice-assistant-text-form:focus-within {

  border-color:
    rgba(61,127,78,0.34);

  box-shadow:
    0 7px 22px
      rgba(42,101,61,0.08),

    0 0 0 3px
      rgba(71,149,88,0.07);

}


.voice-assistant-text-form input {

  min-width:
    0;

  flex:
    1 1 auto;

  height:
    39px;

  padding:
    0;

  border:
    0;

  outline:
    0;

  color:
    #314139;

  background:
    transparent;

  font:
    inherit;

  font-size:
    12.5px;

}


.voice-assistant-text-form input::placeholder {

  color:
    #98a49d;

}


.voice-assistant-text-form
input:disabled {

  opacity:
    0.55;

}


.voice-assistant-text-form > button {

  width:
    40px;

  height:
    40px;

  flex:
    0 0 40px;

  display:
    grid;

  place-items:
    center;

  border:
    0;

  border-radius:
    11px;

  cursor:
    pointer;

  color:
    #ffffff;

  background:
    linear-gradient(
      145deg,
      #3b8d59,
      #5a8fb4
    );

  box-shadow:
    0 6px 15px
      rgba(54,116,71,0.16);

  transition:
    transform 150ms ease,
    filter 150ms ease;

}


.voice-assistant-text-form > button:hover:not(:disabled) {

  transform:
    translateY(-1px)
    scale(1.03);

  filter:
    brightness(1.04);

}


.voice-assistant-text-form > button:disabled {

  opacity:
    0.35;

  cursor:
    default;

}


/* =========================================================
   MAIN VOICE BUTTON
   ========================================================= */

.voice-assistant-main-button {

  position:
    relative;

  width:
    100%;

  min-height:
    47px;

  margin-top:
    8px;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    8px;

  overflow:
    hidden;

  border:
    1px solid
    rgba(55,118,74,0.17);

  border-radius:
    13px;

  cursor:
    pointer;

  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      #3d8d59,
      #4f936f
    );

  font-size:
    11.5px;

  font-weight:
    800;

  box-shadow:
    0 7px 19px
      rgba(45,111,63,0.13);

  transition:
    transform 160ms ease,
    box-shadow 160ms ease,
    filter 160ms ease;

}


.voice-assistant-main-button:hover:not(:disabled) {

  transform:
    translateY(-2px);

  filter:
    brightness(1.025);

  box-shadow:
    0 10px 24px
      rgba(45,111,63,0.18);

}


.voice-assistant-main-button.stop {

  background:
    linear-gradient(
      135deg,
      #bb6653,
      #ae7659
    );

  border-color:
    rgba(166,83,65,0.20);

  box-shadow:
    0 7px 19px
      rgba(162,83,68,0.14);

}


.voice-assistant-main-button:disabled {

  opacity:
    0.50;

  cursor:
    default;

  transform:
    none;

}


.voice-assistant-button-pulse {

  position:
    absolute;

  right:
    17px;

  width:
    8px;

  height:
    8px;

  border-radius:
    50%;

  background:
    #ffe18b;

  box-shadow:
    0 0 0 0
      rgba(255,225,139,0.42);

  animation:
    ai-button-pulse
    1.15s infinite;

}


/* =========================================================
   CONTROLS
   ========================================================= */

.voice-assistant-control-row {

  display:
    flex;

  align-items:
    center;

  gap:
    7px;

  width:
    100%;

  min-width:
    0;

  min-height:
    29px;

  margin-top:
    8px;

}


.voice-assistant-control-button,
.voice-assistant-stop-speaking {

  min-height:
    29px;

  display:
    inline-flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    5px;

  padding:
    5px 9px;

  border:
    1px solid
    rgba(57,103,69,0.10);

  border-radius:
    8px;

  cursor:
    pointer;

  color:
    #557465;

  background:
    rgba(232,243,234,0.76);

  font-size:
    8.5px;

  font-weight:
    750;

  white-space:
    nowrap;

  transition:
    color 150ms ease,
    background 150ms ease,
    transform 150ms ease;

}


.voice-assistant-control-button:hover,
.voice-assistant-stop-speaking:hover {

  transform:
    translateY(-1px);

  color:
    #285f3d;

  background:
    #e3f3e6;

}


.voice-assistant-stop-speaking {

  color:
    #8f5d50;

  background:
    rgba(252,239,234,0.82);

}


.voice-assistant-stop-speaking:hover {

  color:
    #ffffff;

  background:
    #bd6956;

}


.voice-assistant-page-indicator {

  min-width:
    0;

  margin-left:
    auto;

  overflow:
    hidden;

  color:
    #97a19b;

  font-size:
    8px;

  text-overflow:
    ellipsis;

  white-space:
    nowrap;

}


/* =========================================================
   PRIVACY
   ========================================================= */

.voice-assistant-privacy {

  display:
    flex;

  align-items:
    center;

  gap:
    5px;

  width:
    100%;

  min-width:
    0;

  margin-top:
    7px;

  color:
    #99a39d;

  font-size:
    8px;

  line-height:
    1.35;

}


.voice-assistant-privacy > span:first-of-type {

  min-width:
    0;

}


.voice-assistant-shortcut {

  margin-left:
    auto;

  flex:
    0 0 auto;

  padding:
    3px 6px;

  border-radius:
    5px;

  color:
    #7b8b81;

  background:
    rgba(225,235,227,0.72);

  font-size:
    7.5px;

  font-weight:
    750;

}


/* =========================================================
   ANIMATIONS
   ========================================================= */

.voice-assistant-spin {

  animation:
    ai-spin
    0.85s
    linear
    infinite;

}


@keyframes ai-spin {

  to {

    transform:
      rotate(360deg);

  }

}


@keyframes ai-panel-in {

  from {

    opacity:
      0;

    transform:
      translateY(16px)
      scale(0.975);

  }

  to {

    opacity:
      1;

    transform:
      translateY(0)
      scale(1);

  }

}


@keyframes ai-backdrop-in {

  from {

    opacity:
      0;

  }

  to {

    opacity:
      1;

  }

}


@keyframes ai-message-in {

  from {

    opacity:
      0;

    transform:
      translateY(6px);

  }

  to {

    opacity:
      1;

    transform:
      translateY(0);

  }

}


@keyframes ai-listening-breathe {

  0%,
  100% {

    box-shadow:
      0 18px 35px
        rgba(47,102,65,0.13),

      0 0 0 0
        rgba(69,149,91,0.24);

  }

  50% {

    box-shadow:
      0 20px 38px
        rgba(47,102,65,0.18),

      0 0 0 10px
        rgba(69,149,91,0.06);

  }

}


@keyframes ai-live-dot {

  0%,
  100% {

    transform:
      scale(0.82);

    opacity:
      0.65;

  }

  50% {

    transform:
      scale(1.18);

    opacity:
      1;

  }

}


@keyframes ai-button-pulse {

  0% {

    box-shadow:
      0 0 0 0
      rgba(255,225,139,0.40);

  }

  70% {

    box-shadow:
      0 0 0 8px
      rgba(255,225,139,0);

  }

  100% {

    box-shadow:
      0 0 0 0
      rgba(255,225,139,0);

  }

}


@keyframes ai-thinking-dot {

  0%,
  60%,
  100% {

    opacity:
      0.25;

    transform:
      translateY(0);

  }

  30% {

    opacity:
      1;

    transform:
      translateY(-3px);

  }

}


