/* =========================================================
   TABLET / SMALL LAPTOP
   ========================================================= */

@media (
  max-height: 760px
) and (
  min-width: 701px
) {

  .voice-assistant-backdrop {

    padding:
      10px;

  }


  .voice-assistant-panel {

    height:
      calc(100dvh - 20px);

    max-height:
      calc(100dvh - 20px);

    border-radius:
      23px;

  }


  .voice-assistant-panel-header {

    min-height:
      68px;

    padding:
      11px 14px;

  }


  .voice-assistant-body {

    padding:
      12px 14px 14px;

  }


  .voice-assistant-welcome {

    min-height:
      210px;

  }


  .voice-assistant-orb {

    width:
      76px;

    height:
      76px;

    flex-basis:
      76px;

  }

}


