   MOBILE
   ========================================================= */

@media (
  max-width: 700px
) {

  .voice-assistant-backdrop {

    align-items:
      flex-end;

    justify-content:
      center;

    padding:
      8px;

  }


  .voice-assistant-panel {

    width:
      100%;

    max-width:
      640px;

    height:
      min(
        820px,
        calc(100dvh - 16px)
      );

    max-height:
      calc(100dvh - 16px);

    border-radius:
      24px;

  }


  .voice-assistant-floating {

    right:
      14px;

    bottom:
      16px;

  }


  .voice-assistant-panel-header {

    min-height:
      70px;

    padding:
      11px 13px;

  }


  .voice-assistant-body {

    padding:
      13px 12px 14px;

  }


  .voice-assistant-composer {

    padding:
      9px 11px 11px;

  }


  .voice-assistant-message-bubble {

    max-width:
      91%;

  }


  .voice-assistant-welcome {

    min-height:
      230px;

  }


  .voice-assistant-orb {

    width:
      78px;

    height:
      78px;

    flex-basis:
      78px;

  }


  .voice-assistant-state strong {

    font-size:
      19px;

  }

}


