/* =========================================================
   PHASE 1 — FARMER BOOK EDIT MODE
   Scoped additions only. Existing rules are untouched.
========================================================= */

.farmer-book-page > .booking-error.prominent {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 12px 16px;
  border: 1px solid #dbe8df;
  border-radius: 12px;
  background: #f7fbf8;
  color: #496456;
  box-sizing: border-box;
}

.farmer-book-page > .booking-error.prominent .loading-spin {
  flex: 0 0 auto;
}

.farmer-book-page .booking-confirmed-card h2 {
  max-width: 620px;
}

/* =========================================================
   PHASE 1 — FARMER TOKEN ACTIONS
   Scoped additions only. Existing rules are untouched.
========================================================= */

.farmer-token-page > .booking-error.prominent {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 12px 16px;
  border: 1px solid #dbe8df;
  border-radius: 12px;
  background: #f7fbf8;
  box-sizing: border-box;
}

/* Cancel confirmation modal introduced in Phase 1. */
.farmer-token-page [aria-labelledby="cancel-booking-title"] {
  box-sizing: border-box;
}

.farmer-token-page [aria-labelledby="cancel-booking-title"] textarea {
  display: block;
  min-height: 92px;
  line-height: 1.5;
  color: #30493d;
  background: #fcfefd;
  outline: none;
  transition: border-color .18s ease, box-shadow .18s ease;
}

.farmer-token-page [aria-labelledby="cancel-booking-title"] textarea:focus {
  border-color: #93b9a0 !important;
  box-shadow: 0 0 0 3px rgba(72, 125, 88, .10);
}

.farmer-token-page [aria-labelledby="cancel-booking-title"] .token-inline-action {
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid #d6e2da;
  border-radius: 10px;
  background: #ffffff;
  color: #3f5b4d;
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: transform .16s ease, box-shadow .16s ease, border-color .16s ease, background .16s ease;
}

.farmer-token-page [aria-labelledby="cancel-booking-title"] .token-inline-action:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 7px 18px rgba(31, 58, 42, .08);
  border-color: #b9cec0;
  background: #fbfdfb;
}

.farmer-token-page [aria-labelledby="cancel-booking-title"] .token-inline-action:disabled {
  opacity: .58;
  cursor: not-allowed;
}

@media (max-width: 560px) {
  .farmer-token-page [aria-labelledby="cancel-booking-title"] {
    padding: 20px !important;
    border-radius: 16px !important;
  }

  .farmer-token-page [aria-labelledby="cancel-booking-title"] .token-inline-action {
    width: 100%;
  }
}



/* =========================================================
   KRISHISETU
   GLOBAL DESIGN SYSTEM
   PART 1 — FOUNDATION
========================================================= */

:root {
  color-scheme: light;

  --primary: #f97316;
  --primary-strong: #0f6299;
  --primary-soft: #e8f5fc;
  --primary-soft-strong: #d6edf9;

  --success: #16865a;
  --success-soft: #e9f8f1;

  --warning: #b97805;
  --warning-soft: #fff5dc;

  --danger: #c73730;
  --danger-soft: #fff0ee;

  --text-main: #173047;
  --text-strong: #27445a;
  --text-body: #536b7d;
  --text-muted: #728698;
  --text-faint: #96a6b3;
  --text-on-primary: #ffffff;

  --background: #f4f8fb;
  --background-soft: #edf4f8;

  --surface: #ffffff;
  --surface-soft: #f8fbfd;
  --surface-hover: #f1f7fa;

  --border: #d9e4eb;
  --border-strong: #c4d4de;

  --overlay: rgba(17, 40, 58, 0.48);

  --shadow-sm:
    0 4px 16px rgba(31, 63, 84, 0.05);

  --shadow-md:
    0 12px 34px rgba(31, 63, 84, 0.08);

  --shadow-lg:
    0 24px 70px rgba(31, 63, 84, 0.12);

  --radius-xs: 7px;
  --radius-sm: 10px;
  --radius-md: 13px;
  --radius-lg: 17px;
  --radius-xl: 22px;
  --radius-pill: 999px;

  --font-body:
    "DM Sans",
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  --font-heading:
    "Manrope",
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  --text-xs: 11px;
  --text-sm: 13px;
  --text-md: 15px;
  --text-lg: 18px;
  --text-xl: 24px;
  --text-2xl: 32px;
  --text-3xl: 42px;
  --text-4xl: 52px;

  --content-width: 1120px;

  --header-height: 74px;

  --touch-target: 46px;

  --transition-fast: 150ms ease;
  --transition-normal: 220ms ease;
}

[data-theme="dark"] {
  color-scheme: dark;

  --primary: #4bb8ed;
  --primary-strong: #68c7f3;
  --primary-soft: #12384c;
  --primary-soft-strong: #194c65;

  --success: #52d198;
  --success-soft: #123b2b;

  --warning: #f2bd5b;
  --warning-soft: #493715;

  --danger: #ff8177;
  --danger-soft: #49211f;

  --text-main: #f1f6f9;
  --text-strong: #e2ecf2;
  --text-body: #bdccd5;
  --text-muted: #99adb9;
  --text-faint: #758996;
  --text-on-primary: #092131;

  --background: #0d1923;
  --background-soft: #13232f;

  --surface: #172733;
  --surface-soft: #1b2c38;
  --surface-hover: #213844;

  --border: #29404e;
  --border-strong: #3b5666;

  --overlay: rgba(0, 0, 0, 0.66);

  --shadow-sm:
    0 4px 16px rgba(0, 0, 0, 0.16);

  --shadow-md:
    0 12px 34px rgba(0, 0, 0, 0.21);

  --shadow-lg:
    0 24px 70px rgba(0, 0, 0, 0.30);
}


/* =========================================================
   RESET
========================================================= */

* {
  box-sizing: border-box;
}

html {
  min-height: 100%;

  background: var(--background);

  scroll-behavior: smooth;
}

body {
  min-width: 320px;
  min-height: 100vh;

  margin: 0;

  font-family: var(--font-body);

  font-size: var(--text-md);
  line-height: 1.5;

  color: var(--text-main);
  background: var(--background);

  font-synthesis: none;
  text-rendering: optimizeLegibility;

  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;

  transition:
    background-color var(--transition-normal),
    color var(--transition-normal);
}

html,
body,
#root {
  min-height: 100%;
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  border: 0;
  outline: 0;

  color: inherit;
  background: transparent;

  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
}

img,
svg {
  display: block;
}

img {
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

h1,
h2,
h3,
h4,
h5,
h6,
p {
  margin-top: 0;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: var(--font-heading);
}

input,
textarea {
  outline: 0;
}

input::placeholder,
textarea::placeholder {
  color: var(--text-faint);
  opacity: 1;
}

::selection {
  color: var(--text-on-primary);
  background: var(--primary);
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid
    color-mix(
      in srgb,
      var(--primary) 32%,
      transparent
    );

  outline-offset: 2px;
}


/* =========================================================
   GLOBAL HELPERS
========================================================= */

.page-eyebrow {
  display: inline-block;

  color: var(--primary);

  font-size: 10px;
  font-weight: 800;

  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.card-eyebrow {
  display: inline-block;

  color: var(--text-faint);

  font-size: 9px;
  font-weight: 800;

  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.readable-text {
  color: var(--text-body);

  font-size: 13px;
  line-height: 1.65;
}

.readable-small {
  color: var(--text-muted);

  font-size: 11px;
  line-height: 1.55;
}

.important-text {
  color: var(--text-strong);
  font-weight: 800;
}


/* =========================================================
   GENERIC BUTTON STATES
========================================================= */

button,
a,
input,
textarea,
select,
.surface-transition {
  transition:
    background-color var(--transition-normal),
    border-color var(--transition-normal),
    color var(--transition-normal),
    box-shadow var(--transition-normal),
    transform var(--transition-fast);
}


/* =========================================================
   SCROLLBAR
========================================================= */

* {
  scrollbar-width: thin;
  scrollbar-color:
    var(--border-strong)
    transparent;
}

*::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

*::-webkit-scrollbar-track {
  background: transparent;
}

*::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: var(--radius-pill);

  background: var(--border-strong);

  background-clip: padding-box;
}


/* =========================================================
   RESPONSIVE FOUNDATION
========================================================= */

@media (max-width: 760px) {
  :root {
    --text-3xl: 36px;
    --text-4xl: 44px;

    --header-height: 68px;
  }
}

@media (max-width: 480px) {
  :root {
    --text-3xl: 32px;
    --text-4xl: 39px;
  }
}
/* =========================================================
   KRISHISETU
   GLOBAL UI
   PART 2 — HEADER / BUTTONS / LANGUAGE / THEME
========================================================= */


/* =========================================================
   HEADER
========================================================= */

.app-header {
  position: sticky;
  top: 0;
  z-index: 100;

  width: 100%;
  min-height: var(--header-height);

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;

  padding: 12px max(
    20px,
    calc((100vw - var(--content-width)) / 2)
  );

  border-bottom: 1px solid var(--border);

  background: color-mix(
    in srgb,
    var(--surface) 94%,
    transparent
  );

  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);

  box-shadow: var(--shadow-sm);
}

.app-header-brand {
  min-width: 0;

  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.app-header-logo {
  width: 40px;
  height: 40px;

  flex: 0 0 auto;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  color: var(--text-on-primary);
  background: var(--primary);

  box-shadow:
    0 8px 20px
      color-mix(
        in srgb,
        var(--primary) 22%,
        transparent
      );
}

.app-header-logo svg {
  width: 21px;
  height: 21px;
}

.app-header-brand > div:last-child {
  min-width: 0;
}

.app-header-name {
  overflow: hidden;

  color: var(--text-strong);

  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 800;

  line-height: 1.1;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.app-header-subtitle {
  margin-top: 3px;

  overflow: hidden;

  color: var(--text-muted);

  font-size: 9px;
  font-weight: 600;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.app-header-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.header-language-button,
.header-help-button {
  min-height: 40px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;

  padding: 0 11px;

  border: 1px solid var(--border);
  border-radius: 12px;

  color: var(--text-body);
  background: var(--surface);

  font-size: 10px;
  font-weight: 800;
}

.header-language-button:hover,
.header-help-button:hover {
  color: var(--text-strong);
  background: var(--surface-hover);
  border-color: var(--border-strong);
}

.header-help-button svg {
  color: var(--primary);
}

@media (max-width: 600px) {
  .app-header {
    padding:
      10px 12px;
  }

  .app-header-subtitle {
    display: none;
  }

  .app-header-name {
    font-size: 14px;
  }

  .app-header-actions {
    gap: 6px;
  }

  .header-help-button span {
    display: none;
  }

  .header-help-button {
    width: 40px;
    padding: 0;
  }
}


/* =========================================================
   THEME TOGGLE
========================================================= */

.theme-toggle {
  min-height: 40px;

  padding: 0 11px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;

  border: 1px solid var(--border);
  border-radius: 12px;

  color: var(--text-body);
  background: var(--surface);

  font-size: 10px;
  font-weight: 800;
}

.theme-toggle:hover {
  color: var(--text-strong);
  background: var(--surface-hover);
  border-color: var(--border-strong);

  transform: translateY(-1px);
}

.theme-toggle svg {
  color: var(--primary);
}

@media (max-width: 600px) {
  .theme-toggle {
    width: 40px;
    padding: 0;
  }

  .theme-toggle span {
    display: none;
  }
}


/* =========================================================
   LANGUAGE SELECTOR
========================================================= */

.language-selector {
  position: relative;
}

.language-selector-button {
  min-height: 40px;

  padding: 0 9px 0 7px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;

  border: 1px solid var(--border);
  border-radius: 12px;

  color: var(--text-body);
  background: var(--surface);

  font-size: 10px;
  font-weight: 800;
}

.language-selector-button:hover {
  color: var(--text-strong);
  background: var(--surface-hover);
  border-color: var(--border-strong);
}

.language-globe {
  width: 26px;
  height: 26px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 8px;

  color: var(--primary);
  background: var(--primary-soft);

  font-size: 9px;
  font-weight: 900;
}

.language-current-label {
  max-width: 80px;

  overflow: hidden;

  color: var(--text-body);

  font-size: 10px;
  font-weight: 800;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.language-chevron {
  color: var(--text-faint);

  transition:
    transform var(--transition-fast);
}

.language-chevron.open {
  transform: rotate(180deg);
}

.language-dropdown {
  position: absolute;
  z-index: 120;

  top: calc(100% + 8px);
  right: 0;

  width: 220px;

  overflow: hidden;

  padding: 7px;

  border: 1px solid var(--border);
  border-radius: 15px;

  background: var(--surface);

  box-shadow: var(--shadow-md);
}

.language-dropdown-heading {
  padding: 9px 9px 8px;

  color: var(--text-faint);

  font-size: 8px;
  font-weight: 800;

  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.language-option {
  width: 100%;
  min-height: 50px;

  padding: 7px 8px;

  display: flex;
  align-items: center;
  gap: 9px;

  border-radius: 10px;

  color: var(--text-body);
  background: transparent;

  text-align: left;
}

.language-option:hover,
.language-option.active {
  background: var(--surface-hover);
}

.language-option-code {
  width: 32px;
  height: 32px;

  flex: 0 0 auto;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: var(--primary);
  background: var(--primary-soft);

  font-size: 9px;
  font-weight: 900;
}

.language-option-text {
  min-width: 0;
  flex: 1;
}

.language-option-text strong,
.language-option-text span {
  display: block;
}

.language-option-text strong {
  overflow: hidden;

  color: var(--text-strong);

  font-size: 10px;
  font-weight: 800;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.language-option-text span {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 8px;
}

.language-active-dot {
  width: 7px;
  height: 7px;

  flex: 0 0 auto;

  border-radius: 50%;

  background: var(--success);
}

@media (max-width: 600px) {
  .language-selector-button {
    width: 40px;
    padding: 0;
  }

  .language-current-label {
    display: none;
  }

  .language-dropdown {
    right: -7px;
    width: 210px;
  }
}


/* =========================================================
   BUTTON SYSTEM
========================================================= */

.app-button {
  min-height: var(--touch-target);

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  padding: 0 16px;

  border: 1px solid transparent;
  border-radius: var(--radius-md);

  color: var(--text-on-primary);
  background: var(--primary);

  font-size: 12px;
  font-weight: 800;

  line-height: 1;

  box-shadow:
    0 7px 18px
      color-mix(
        in srgb,
        var(--primary) 17%,
        transparent
      );
}

.app-button:hover:not(:disabled) {
  background: var(--primary-strong);

  transform: translateY(-1px);

  box-shadow:
    0 10px 22px
      color-mix(
        in srgb,
        var(--primary) 23%,
        transparent
      );
}

.app-button:active:not(:disabled) {
  transform: translateY(0);
}

.app-button:disabled {
  opacity: 0.48;
  box-shadow: none;
}

.app-button.full-width {
  width: 100%;
}

.app-button.secondary {
  color: var(--primary);

  border-color: var(--border);

  background: var(--surface);
}

.app-button.secondary:hover:not(:disabled) {
  background: var(--surface-hover);
  border-color: var(--border-strong);
}

.app-button.success {
  color: white;
  background: var(--success);
}

.app-button.success:hover:not(:disabled) {
  background:
    color-mix(
      in srgb,
      var(--success) 85%,
      black
    );
}

.app-button.warning {
  color: #3b2905;
  background: var(--warning);
}

.app-button.danger {
  color: white;
  background: var(--danger);
}


/* =========================================================
   GENERIC EMPTY STATE
========================================================= */

.empty-state-card {
  max-width: 620px;

  margin: 70px auto 0;

  padding: 42px 32px;

  border: 1px solid var(--border);
  border-radius: var(--radius-xl);

  background: var(--surface);

  box-shadow: var(--shadow-md);

  text-align: center;
}

.empty-state-icon {
  width: 62px;
  height: 62px;

  margin: 0 auto 20px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 17px;

  color: var(--primary);
  background: var(--primary-soft);
}

.empty-state-card h1 {
  margin: 9px 0;

  color: var(--text-strong);

  font-family: var(--font-heading);
  font-size: 29px;
  line-height: 1.1;

  letter-spacing: -0.04em;
}

.empty-state-card p {
  max-width: 440px;

  margin: 0 auto 23px;

  color: var(--text-muted);

  font-size: 13px;
  line-height: 1.65;
}

.empty-state-card .home-primary-action {
  width: fit-content;

  margin: 0 auto;
}


/* =========================================================
   GENERIC BACK LINK
========================================================= */

.back-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;

  color: var(--text-muted);

  font-size: 11px;
  font-weight: 800;
}

.back-link:hover {
  color: var(--primary);
}


/* =========================================================
   DARK MODE — GENERIC SURFACES
========================================================= */

[data-theme="dark"] .app-header {
  box-shadow:
    0 5px 24px rgba(0, 0, 0, 0.18);
}

[data-theme="dark"] .empty-state-card {
  box-shadow:
    0 16px 45px rgba(0, 0, 0, 0.22);
}


/* =========================================================
   MOBILE GLOBAL
========================================================= */

@media (max-width: 480px) {
  .app-header-logo {
    width: 37px;
    height: 37px;

    border-radius: 11px;
  }

  .app-header-name {
    font-size: 13px;
  }

  .empty-state-card {
    padding:
      32px
      20px;
  }
}
/* =========================================================
   KRISHISETU
   PART 3 — LANDING PAGE
========================================================= */


/* =========================================================
   LANDING PAGE
========================================================= */

.landing-page {
  min-height: 100vh;

  overflow-x: hidden;

  color: var(--text-main);
  background:
    radial-gradient(
      circle at 8% 8%,
      color-mix(
        in srgb,
        var(--primary) 10%,
        transparent
      ),
      transparent 31%
    ),
    radial-gradient(
      circle at 92% 18%,
      color-mix(
        in srgb,
        var(--success) 7%,
        transparent
      ),
      transparent 28%
    ),
    var(--background);
}


/* =========================================================
   LANDING HERO
========================================================= */

.landing-hero {
  position: relative;

  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  min-height: 570px;

  margin: 0 auto;

  display: grid;
  grid-template-columns:
    minmax(0, 1.1fr)
    minmax(360px, 0.9fr);

  align-items: center;

  gap: 30px;

  padding: 15px 0 15px;
}

.landing-hero::before {
  content: "";

  position: absolute;

  top: 35px;
  left: -120px;

  width: 270px;
  height: 270px;

  border-radius: 50%;

  background:
    color-mix(
      in srgb,
      var(--primary) 5%,
      transparent
    );

  pointer-events: none;
}

.landing-hero-content {
  position: relative;
  z-index: 1;
}

.landing-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;

  min-height: 30px;

  padding: 0 10px;

  border: 1px solid
    color-mix(
      in srgb,
      var(--primary) 18%,
      var(--border)
    );

  border-radius: var(--radius-pill);

  color: var(--primary);

  background:
    color-mix(
      in srgb,
      var(--primary) 7%,
      var(--surface)
    );

  font-size: 9px;
  font-weight: 800;

  letter-spacing: 0.03em;
}

.landing-badge-dot {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: var(--success);
}

.landing-hero h1 {
  max-width: 700px;

  margin: 5px 0 10px;

  color: var(--text-main);

  font-family: var(--font-heading);

  font-size: var(--text-4xl);

  line-height: 1.02;

  letter-spacing: -0.055em;
}

.landing-hero h1 span {
  display: block;

  color: var(--primary);
}

.landing-hero-description {
  max-width: 610px;

  margin: 0;

  color: var(--text-body);

  font-size: 15px;
  line-height: 1.75;
}

.landing-hero-actions {
  margin-top: 27px;

  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}

.landing-primary-action,
.landing-secondary-action {
  min-height: 50px;

  padding: 0 17px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  border-radius: 13px;

  font-size: 11px;
  font-weight: 800;
}

.landing-primary-action {
  color: var(--text-on-primary);

  background: var(--primary);

  box-shadow:
    0 9px 24px
      color-mix(
        in srgb,
        var(--primary) 20%,
        transparent
      );
}

.landing-primary-action:hover {
  background: var(--primary-strong);

  transform: translateY(-2px);

  box-shadow:
    0 13px 28px
      color-mix(
        in srgb,
        var(--primary) 25%,
        transparent
      );
}

.landing-secondary-action {
  color: var(--text-strong);

  border: 1px solid var(--border);

  background: var(--surface);
}

.landing-secondary-action:hover {
  background: var(--surface-hover);
  border-color: var(--border-strong);

  transform: translateY(-1px);
}

.landing-action-note {
  display: flex;
  align-items: center;
  gap: 7px;

  margin-top: 13px;

  color: var(--text-muted);

  font-size: 10px;
}

.landing-action-note svg {
  flex: 0 0 auto;

  color: var(--success);
}


/* =========================================================
   LANDING HERO VISUAL
========================================================= */

.landing-visual {
  position: relative;

  min-height: 450px;

  display: flex;
  align-items: center;
  justify-content: center;
}

.landing-visual-glow {
  position: absolute;

  width: 350px;
  height: 350px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      color-mix(
        in srgb,
        var(--primary) 15%,
        transparent
      ),
      transparent 68%
    );

  filter: blur(5px);
}

.landing-phone {
  position: relative;
  z-index: 2;

  width: 285px;

  padding: 12px;

  border: 1px solid
    color-mix(
      in srgb,
      var(--border-strong) 80%,
      transparent
    );

  border-radius: 31px;

  background:
    color-mix(
      in srgb,
      var(--surface) 96%,
      transparent
    );

  box-shadow:
    0 30px 80px
      color-mix(
        in srgb,
        var(--primary) 14%,
        transparent
      );

  transform: rotate(1.5deg);
}

.landing-phone-top {
  height: 26px;

  display: flex;
  align-items: center;
  justify-content: center;
}

.landing-phone-speaker {
  width: 58px;
  height: 5px;

  border-radius: var(--radius-pill);

  background: var(--border);
}

.landing-phone-screen {
  overflow: hidden;

  min-height: 445px;

  padding: 17px;

  border: 1px solid var(--border);

  border-radius: 22px;

  background:
    linear-gradient(
      180deg,
      var(--surface-soft),
      var(--surface)
    );
}

.landing-phone-header {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-bottom: 19px;
}

.landing-phone-brand {
  display: flex;
  align-items: center;
  gap: 7px;
}

.landing-phone-brand-icon {
  width: 27px;
  height: 27px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 8px;

  color: var(--text-on-primary);
  background: var(--primary);
}

.landing-phone-brand strong {
  color: var(--text-strong);

  font-family: var(--font-heading);
  font-size: 10px;
}

.landing-phone-language {
  padding: 4px 7px;

  border-radius: 7px;

  color: var(--primary);

  background: var(--primary-soft);

  font-size: 7px;
  font-weight: 900;
}

.landing-phone-greeting {
  margin-bottom: 17px;
}

.landing-phone-greeting span {
  display: block;

  color: var(--text-muted);

  font-size: 8px;
}

.landing-phone-greeting strong {
  display: block;

  margin-top: 4px;

  color: var(--text-strong);

  font-family: var(--font-heading);
  font-size: 16px;
}

.landing-phone-token {
  padding: 15px;

  border-radius: 15px;

  color: white;

  background:
    linear-gradient(
      135deg,
      var(--primary-strong),
      var(--primary)
    );

  box-shadow:
    0 10px 25px
      color-mix(
        in srgb,
        var(--primary) 18%,
        transparent
      );
}

.landing-phone-token > span {
  color: rgba(255, 255, 255, 0.68);

  font-size: 7px;
  font-weight: 800;

  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.landing-phone-token-number {
  margin-top: 5px;

  font-family: var(--font-heading);

  font-size: 31px;
  font-weight: 800;

  line-height: 1;
}

.landing-phone-token-info {
  display: grid;
  grid-template-columns: 1fr 1fr;

  gap: 7px;

  margin-top: 13px;
}

.landing-mini-info {
  padding: 9px;

  border-radius: 10px;

  background:
    rgba(255, 255, 255, 0.10);
}

.landing-mini-info span,
.landing-mini-info strong {
  display: block;
}

.landing-mini-info span {
  color: rgba(255, 255, 255, 0.60);

  font-size: 6px;
  font-weight: 700;
}

.landing-mini-info strong {
  margin-top: 3px;

  color: white;

  font-size: 8px;
}

.landing-phone-status {
  margin-top: 11px;

  padding: 11px;

  border: 1px solid var(--border);

  border-radius: 12px;

  background: var(--surface);
}

.landing-phone-status-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.landing-phone-status-header span:first-child {
  color: var(--text-muted);

  font-size: 7px;
  font-weight: 800;
}

.landing-phone-status-live {
  display: inline-flex;
  align-items: center;
  gap: 4px;

  color: var(--success);

  font-size: 7px;
  font-weight: 800;
}

.landing-phone-status-live span {
  width: 5px;
  height: 5px;

  border-radius: 50%;

  background: var(--success);
}

.landing-phone-progress {
  margin-top: 10px;
}

.landing-phone-progress-line {
  position: relative;

  height: 5px;

  overflow: hidden;

  border-radius: var(--radius-pill);

  background: var(--background-soft);
}

.landing-phone-progress-line::after {
  content: "";

  position: absolute;

  inset: 0 auto 0 0;

  width: 58%;

  border-radius: inherit;

  background: var(--success);
}

.landing-phone-progress-labels {
  margin-top: 6px;

  display: flex;
  justify-content: space-between;

  color: var(--text-faint);

  font-size: 6px;
}

.landing-phone-help {
  margin-top: 10px;

  padding: 10px;

  display: flex;
  align-items: center;
  gap: 7px;

  border-radius: 11px;

  background: var(--surface-hover);
}

.landing-phone-help-icon {
  width: 24px;
  height: 24px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 7px;

  color: var(--primary);

  background: var(--primary-soft);
}

.landing-phone-help span {
  display: block;

  color: var(--text-muted);

  font-size: 6px;
}

.landing-phone-help strong {
  display: block;

  margin-top: 2px;

  color: var(--text-strong);

  font-size: 7px;
}


/* =========================================================
   FLOATING VISUAL CARDS
========================================================= */

.landing-float-card {
  position: absolute;
  z-index: 5;

  padding: 12px;

  border: 1px solid var(--border);

  border-radius: 13px;

  background: var(--surface);

  box-shadow: var(--shadow-md);
}

.landing-float-card strong,
.landing-float-card span {
  display: block;
}

.landing-float-card strong {
  color: var(--text-strong);

  font-size: 10px;
  font-weight: 800;
}

.landing-float-card span {
  margin-top: 3px;

  color: var(--text-muted);

  font-size: 7px;
}

.landing-float-card.top {
  top: 58px;
  right: 10px;
}

.landing-float-card.bottom {
  bottom: 65px;
  left: 3px;
}

.landing-float-icon {
  width: 28px;
  height: 28px;

  margin-bottom: 8px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 8px;

  color: var(--primary);
  background: var(--primary-soft);
}

.landing-float-card.success .landing-float-icon {
  color: var(--success);
  background: var(--success-soft);
}


/* =========================================================
   TRUST STRIP
========================================================= */

.landing-trust-strip {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  margin: 0 auto 45px;

  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 10px;
}

.landing-trust-item {
  min-height: 62px;

  padding: 11px 13px;

  display: flex;
  align-items: center;
  gap: 9px;

  border: 1px solid var(--border);

  border-radius: 14px;

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.landing-trust-icon {
  width: 34px;
  height: 34px;

  flex: 0 0 auto;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: var(--primary);
  background: var(--primary-soft);
}

.landing-trust-item strong,
.landing-trust-item span {
  display: block;
}

.landing-trust-item strong {
  color: var(--text-strong);

  font-size: 10px;
  font-weight: 800;
}

.landing-trust-item span {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 8px;
}


/* =========================================================
   HOW IT WORKS
========================================================= */

.landing-how {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  margin: 0 auto;

  padding: 62px 0 65px;

  border-top: 1px solid var(--border);
}

.landing-section-heading {
  max-width: 700px;

  margin-bottom: 28px;
}

.landing-section-heading h2 {
  margin: 8px 0 9px;

  color: var(--text-main);

  font-family: var(--font-heading);

  font-size: var(--text-2xl);

  line-height: 1.08;

  letter-spacing: -0.045em;
}

.landing-section-heading p {
  max-width: 620px;

  margin: 0;

  color: var(--text-muted);

  font-size: 13px;
  line-height: 1.65;
}

.landing-steps {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 13px;
}

.landing-step-card {
  position: relative;

  min-height: 220px;

  padding: 21px;

  border: 1px solid var(--border);

  border-radius: var(--radius-lg);

  background: var(--surface);

  box-shadow: var(--shadow-sm);

  overflow: hidden;
}

.landing-step-card::after {
  content: "";

  position: absolute;

  right: -55px;
  bottom: -70px;

  width: 170px;
  height: 170px;

  border-radius: 50%;

  background:
    color-mix(
      in srgb,
      var(--primary) 6%,
      transparent
    );
}

.landing-step-number {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  color: var(--primary);

  background: var(--primary-soft);

  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 800;
}

.landing-step-card h3 {
  margin: 22px 0 7px;

  color: var(--text-strong);

  font-size: 16px;
  letter-spacing: -0.025em;
}

.landing-step-card p {
  max-width: 300px;

  margin: 0;

  color: var(--text-muted);

  font-size: 11px;
  line-height: 1.65;
}


/* =========================================================
   LOW CONNECTIVITY SECTION
========================================================= */

.landing-sms-section {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  margin: 0 auto 62px;

  padding: 25px;

  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    minmax(260px, 0.55fr);

  gap: 25px;

  align-items: center;

  border: 1px solid
    color-mix(
      in srgb,
      var(--success) 17%,
      var(--border)
    );

  border-radius: var(--radius-xl);

  background:
    linear-gradient(
      135deg,
      color-mix(
        in srgb,
        var(--success) 7%,
        var(--surface)
      ),
      var(--surface)
    );
}

.landing-sms-copy > span {
  color: var(--success);

  font-size: 9px;
  font-weight: 800;

  letter-spacing: 0.12em;
}

.landing-sms-copy h2 {
  max-width: 590px;

  margin: 8px 0 8px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 25px;

  line-height: 1.1;

  letter-spacing: -0.04em;
}

.landing-sms-copy p {
  max-width: 620px;

  margin: 0;

  color: var(--text-body);

  font-size: 12px;

  line-height: 1.65;
}

.landing-sms-points {
  margin-top: 17px;

  display: flex;
  flex-wrap: wrap;

  gap: 8px;
}

.landing-sms-point {
  min-height: 33px;

  padding: 0 9px;

  display: inline-flex;
  align-items: center;
  gap: 5px;

  border: 1px solid var(--border);

  border-radius: 9px;

  color: var(--text-body);

  background: var(--surface);

  font-size: 9px;
  font-weight: 700;
}

.landing-sms-point svg {
  color: var(--success);
}

.landing-sms-preview {
  padding: 17px;

  border: 1px solid var(--border);

  border-radius: 17px;

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.landing-sms-preview-header {
  display: flex;
  align-items: center;
  gap: 8px;

  padding-bottom: 11px;

  border-bottom: 1px solid var(--border);
}

.landing-sms-preview-icon {
  width: 32px;
  height: 32px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: var(--success);

  background: var(--success-soft);
}

.landing-sms-preview-header span {
  display: block;

  color: var(--text-faint);

  font-size: 7px;
  font-weight: 800;

  letter-spacing: 0.1em;
}

.landing-sms-preview-header strong {
  display: block;

  margin-top: 3px;

  color: var(--text-strong);

  font-size: 9px;
}

.landing-sms-message {
  margin-top: 13px;

  padding: 13px;

  border-radius: 13px;

  color: var(--text-body);

  background: var(--surface-soft);

  font-size: 10px;
  line-height: 1.65;
}

.landing-sms-status {
  margin-top: 10px;

  display: flex;
  align-items: center;
  gap: 5px;

  color: var(--success);

  font-size: 8px;
  font-weight: 800;
}

.landing-sms-status span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: var(--success);
}


/* =========================================================
   AVAILABILITY PREVIEW
========================================================= */

.landing-availability {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  margin: 0 auto 70px;

  padding: 0;
}

.landing-availability-heading {
  display: flex;
  justify-content: space-between;

  gap: 20px;

  align-items: flex-end;

  margin-bottom: 20px;
}

.landing-availability-heading h2 {
  margin: 7px 0 0;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 23px;

  letter-spacing: -0.035em;
}

.landing-availability-heading p {
  margin: 4px 0 0;

  color: var(--text-muted);

  font-size: 11px;
}

.landing-availability-badge {
  min-height: 34px;

  padding: 0 10px;

  display: inline-flex;
  align-items: center;
  gap: 6px;

  border: 1px solid
    color-mix(
      in srgb,
      var(--success) 16%,
      var(--border)
    );

  border-radius: 10px;

  color: var(--success);

  background: var(--success-soft);

  font-size: 9px;
  font-weight: 800;
}

.landing-availability-badge span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: var(--success);
}

.landing-slot-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 10px;
}

.landing-slot {
  padding: 15px;

  border: 1px solid var(--border);

  border-radius: 14px;

  background: var(--surface);
}

.landing-slot-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.landing-slot-icon {
  width: 31px;
  height: 31px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: var(--primary);
  background: var(--primary-soft);
}

.landing-slot-state {
  color: var(--success);

  font-size: 8px;
  font-weight: 800;
}

.landing-slot strong {
  display: block;

  margin-top: 15px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 11px;
}

.landing-slot span {
  display: block;

  margin-top: 4px;

  color: var(--text-muted);

  font-size: 8px;
}

.landing-slot-capacity {
  margin-top: 12px;

  height: 4px;

  overflow: hidden;

  border-radius: var(--radius-pill);

  background: var(--background-soft);
}

.landing-slot-capacity span {
  width: 72%;
  height: 100%;

  margin: 0;

  border-radius: inherit;

  background: var(--success);
}

.landing-slot-footer {
  margin-top: 9px;

  display: flex;
  align-items: center;
  justify-content: space-between;
}

.landing-slot-footer span {
  margin: 0;

  font-size: 8px;
}

.landing-slot-footer svg {
  color: var(--primary);
}


/* =========================================================
   LANDING FOOTER
========================================================= */

.landing-footer {
  border-top: 1px solid var(--border);

  background: var(--surface);
}

.landing-footer-inner {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  min-height: 82px;

  margin: 0 auto;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 20px;
}

.landing-footer-brand {
  display: flex;
  align-items: center;
  gap: 9px;
}

.landing-footer-logo {
  width: 33px;
  height: 33px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: var(--text-on-primary);
  background: var(--primary);
}

.landing-footer-brand strong {
  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 11px;
}

.landing-footer-brand span {
  display: block;

  margin-top: 2px;

  color: var(--text-muted);

  font-size: 8px;
}

.landing-footer-copy {
  color: var(--text-faint);

  font-size: 8px;
}


/* =========================================================
   LANDING RESPONSIVE
========================================================= */

@media (max-width: 1000px) {
  .landing-hero {
    grid-template-columns: 1fr;

    gap: 25px;

    padding-top: 50px;
  }

  .landing-visual {
    min-height: 420px;
  }

  .landing-hero-content {
    max-width: 760px;
  }

  .landing-float-card.top {
    right: calc(50% - 230px);
  }

  .landing-float-card.bottom {
    left: calc(50% - 230px);
  }
}

@media (max-width: 780px) {
  .landing-hero,
  .landing-trust-strip,
  .landing-how,
  .landing-sms-section,
  .landing-availability {
    width: min(
      calc(100% - 24px),
      var(--content-width)
    );
  }

  .landing-hero {
    min-height: auto;

    padding:
      38px 0
      40px;
  }

  .landing-hero h1 {
    font-size: 42px;
  }

  .landing-trust-strip {
    grid-template-columns: 1fr;

    margin-bottom: 30px;
  }

  .landing-steps {
    grid-template-columns: 1fr;
  }

  .landing-sms-section {
    grid-template-columns: 1fr;

    margin-bottom: 45px;
  }

  .landing-slot-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .landing-footer-inner {
    width: min(
      calc(100% - 24px),
      var(--content-width)
    );

    align-items: flex-start;

    flex-direction: column;

    padding:
      18px 0;
  }
}

@media (max-width: 550px) {
  .landing-hero h1 {
    font-size: 34px;
  }

  .landing-hero-description {
    font-size: 13px;
  }

  .landing-hero-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .landing-primary-action,
  .landing-secondary-action {
    width: 100%;
  }

  .landing-visual {
    min-height: 390px;
  }

  .landing-phone {
    width: 245px;
  }

  .landing-phone-screen {
    min-height: 405px;
  }

  .landing-float-card {
    transform: scale(0.88);
  }

  .landing-float-card.top {
    top: 50px;
    right: -4px;
  }

  .landing-float-card.bottom {
    bottom: 50px;
    left: -4px;
  }

  .landing-slot-grid {
    grid-template-columns: 1fr;
  }

  .landing-availability-heading {
    align-items: flex-start;

    flex-direction: column;
  }

  .landing-section-heading h2 {
    font-size: 27px;
  }

  .landing-sms-copy h2 {
    font-size: 22px;
  }
}
/* =========================================================
   KRISHISETU
   PART 4 — FARMER LOGIN + REGISTRATION
========================================================= */


/* =========================================================
   FARMER LOGIN PAGE
========================================================= */

.farmer-login-page {
  min-height: 100vh;

  background:
    radial-gradient(
      circle at 7% 12%,
      color-mix(
        in srgb,
        var(--primary) 9%,
        transparent
      ),
      transparent 30%
    ),
    radial-gradient(
      circle at 94% 88%,
      color-mix(
        in srgb,
        var(--success) 6%,
        transparent
      ),
      transparent 27%
    ),
    var(--background);
}

.farmer-login-container {
  width: min(
    calc(100% - 40px),
    1080px
  );

  min-height:
    calc(100vh - var(--header-height));

  margin: 0 auto;

  display: grid;

  grid-template-columns:
    minmax(0, 0.9fr)
    minmax(350px, 0.7fr);

  align-items: center;

  gap: 80px;

  padding: 55px 0;
}

.farmer-login-intro {
  max-width: 560px;
}

.farmer-login-intro h1 {
  margin: 10px 0 13px;

  color: var(--text-main);

  font-family: var(--font-heading);

  font-size: var(--text-3xl);

  line-height: 1.02;

  letter-spacing: -0.05em;
}

.farmer-login-intro h1 span {
  display: block;

  color: var(--primary);
}

.farmer-login-intro > p {
  max-width: 500px;

  margin: 0;

  color: var(--text-body);

  font-size: 14px;

  line-height: 1.7;
}

.farmer-login-benefits {
  margin-top: 30px;

  display: flex;
  flex-direction: column;

  gap: 13px;
}

.farmer-login-benefit {
  display: flex;
  align-items: center;

  gap: 11px;

  padding: 12px 13px;

  border: 1px solid var(--border);

  border-radius: var(--radius-md);

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.farmer-login-benefit-icon {
  width: 37px;
  height: 37px;

  flex: 0 0 auto;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: var(--primary);
  background: var(--primary-soft);
}

.farmer-login-benefit strong,
.farmer-login-benefit span {
  display: block;
}

.farmer-login-benefit strong {
  color: var(--text-strong);

  font-size: 11px;
  font-weight: 800;
}

.farmer-login-benefit span {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.45;
}


/* =========================================================
   LOGIN CARD
========================================================= */

.farmer-login-card {
  width: 100%;

  padding: 29px;

  border: 1px solid var(--border);

  border-radius: var(--radius-xl);

  background: var(--surface);

  box-shadow: var(--shadow-lg);
}

.farmer-login-card-heading {
  margin-bottom: 25px;
}

.farmer-login-card-heading h2 {
  margin: 7px 0 6px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 21px;

  letter-spacing: -0.035em;
}

.farmer-login-card-heading p {
  margin: 0;

  color: var(--text-muted);

  font-size: 10px;

  line-height: 1.6;
}

.farmer-login-field {
  margin-bottom: 16px;
}

.farmer-login-field label {
  display: block;

  margin-bottom: 7px;

  color: var(--text-body);

  font-size: 10px;
  font-weight: 800;
}

.farmer-login-input {
  min-height: 54px;

  display: flex;
  align-items: center;
  gap: 8px;

  padding: 0 13px;

  border: 1px solid var(--border);

  border-radius: var(--radius-md);

  background: var(--surface-soft);
}

.farmer-login-input:focus-within {
  border-color: var(--primary);

  box-shadow:
    0 0 0 4px
      color-mix(
        in srgb,
        var(--primary) 10%,
        transparent
      );
}

.farmer-login-input svg {
  flex: 0 0 auto;

  color: var(--text-faint);
}

.farmer-login-input input {
  min-width: 0;
  flex: 1;

  height: 50px;

  border: 0;
  outline: 0;

  color: var(--text-strong);

  background: transparent;

  font-size: 13px;
  font-weight: 600;
}

.farmer-login-input input::placeholder {
  color: var(--text-faint);
}

.farmer-login-country {
  color: var(--text-body);

  font-size: 12px;
  font-weight: 800;
}

.farmer-login-error {
  margin:
    8px
    0
    15px;

  padding: 11px 12px;

  border: 1px solid
    color-mix(
      in srgb,
      var(--danger) 18%,
      var(--border)
    );

  border-radius: var(--radius-sm);

  color: var(--danger);

  background: var(--danger-soft);

  font-size: 10px;

  line-height: 1.5;
}

.farmer-login-note {
  margin-top: 13px;

  display: flex;
  align-items: flex-start;

  gap: 7px;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.55;
}

.farmer-login-note svg {
  flex: 0 0 auto;

  margin-top: 1px;

  color: var(--success);
}


/* =========================================================
   NEW FARMER AREA
========================================================= */

.farmer-new-user {
  margin-top: 23px;

  padding-top: 20px;

  border-top: 1px solid var(--border);

  text-align: center;
}

.farmer-new-user > span {
  display: block;

  margin-bottom: 5px;

  color: var(--text-faint);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 0.12em;

  text-transform: uppercase;
}

.farmer-new-user a {
  color: var(--primary);

  font-size: 11px;

  font-weight: 800;
}

.farmer-new-user a:hover {
  color: var(--primary-strong);
}


/* =========================================================
   OTP AREA
========================================================= */

.farmer-otp-card {
  text-align: center;
}

.farmer-otp-icon {
  width: 52px;
  height: 52px;

  margin: 0 auto 15px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 15px;

  color: var(--primary);

  background: var(--primary-soft);
}

.farmer-otp-sent {
  margin: 5px auto 20px;

  color: var(--text-muted);

  font-size: 11px;

  line-height: 1.6;
}

.farmer-otp-sent strong {
  color: var(--text-strong);
}

.farmer-otp-inputs {
  display: flex;

  justify-content: center;

  gap: 7px;

  margin-bottom: 18px;
}

.farmer-otp-input {
  width: 46px;
  height: 50px;

  border: 1px solid var(--border);

  border-radius: 11px;

  color: var(--text-strong);

  background: var(--surface-soft);

  font-family: var(--font-heading);

  font-size: 18px;

  font-weight: 800;

  text-align: center;
}

.farmer-otp-input:focus {
  border-color: var(--primary);

  box-shadow:
    0 0 0 4px
      color-mix(
        in srgb,
        var(--primary) 10%,
        transparent
      );
}

.farmer-otp-resend {
  margin-top: 13px;

  color: var(--primary);

  font-size: 10px;

  font-weight: 800;
}

.farmer-otp-change {
  margin-top: 8px;

  color: var(--text-muted);

  font-size: 9px;

  font-weight: 700;
}


/* =========================================================
   REGISTRATION
========================================================= */

.farmer-register-page {
  min-height: 100vh;

  background:
    radial-gradient(
      circle at 7% 8%,
      color-mix(
        in srgb,
        var(--primary) 7%,
        transparent
      ),
      transparent 29%
    ),
    radial-gradient(
      circle at 94% 90%,
      color-mix(
        in srgb,
        var(--success) 5%,
        transparent
      ),
      transparent 27%
    ),
    var(--background);
}

.register-container {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  margin: 0 auto;

  padding: 28px 0 65px;
}

.register-back-row {
  margin-bottom: 18px;
}

.register-layout {
  display: grid;

  grid-template-columns:
    minmax(0, 0.72fr)
    minmax(500px, 1.28fr);

  gap: 45px;

  align-items: start;
}

.register-intro {
  position: sticky;

  top: 98px;

  padding-top: 20px;
}

.register-intro h1 {
  max-width: 500px;

  margin: 10px 0 15px;

  color: var(--text-main);

  font-family: var(--font-heading);

  font-size: 39px;

  line-height: 1.04;

  letter-spacing: -0.05em;
}

.register-intro h1 span {
  display: block;

  color: var(--primary);
}

.register-intro > p {
  max-width: 430px;

  margin: 0;

  color: var(--text-body);

  font-size: 13px;

  line-height: 1.72;
}

.register-benefits {
  margin-top: 32px;

  display: flex;
  flex-direction: column;

  gap: 12px;
}

.register-benefits > div {
  display: flex;

  gap: 10px;
}

.register-benefit-icon {
  width: 39px;
  height: 39px;

  flex: 0 0 auto;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid var(--border);

  border-radius: 11px;

  color: var(--primary);

  background: var(--surface);
}

.register-benefits strong,
.register-benefits span {
  display: block;
}

.register-benefits strong {
  color: var(--text-strong);

  font-size: 11px;

  font-weight: 800;
}

.register-benefits span {
  margin-top: 3px;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.5;
}


/* =========================================================
   REGISTRATION FORM CARD
========================================================= */

.register-form-card {
  padding: 30px;

  border: 1px solid var(--border);

  border-radius: var(--radius-xl);

  background: var(--surface);

  box-shadow: var(--shadow-lg);
}

.register-form-heading {
  display: flex;

  align-items: center;

  gap: 11px;

  padding-bottom: 21px;

  border-bottom: 1px solid var(--border);
}

.register-form-icon {
  width: 44px;
  height: 44px;

  flex: 0 0 auto;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 13px;

  color: var(--primary);

  background: var(--primary-soft);
}

.register-form-heading h2 {
  margin: 0;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 18px;

  letter-spacing: -0.03em;
}

.register-form-heading p {
  margin: 4px 0 0;

  color: var(--text-muted);

  font-size: 9px;
}

.register-section {
  padding: 23px 0;

  border-bottom: 1px solid var(--border);
}

.register-section-label {
  margin-bottom: 16px;

  color: var(--text-faint);

  font-size: 9px;

  font-weight: 800;

  letter-spacing: 0.12em;

  text-transform: uppercase;
}

.register-field {
  position: relative;

  margin-bottom: 15px;
}

.register-field:last-child {
  margin-bottom: 0;
}

.register-field > label {
  display: block;

  margin-bottom: 7px;

  color: var(--text-body);

  font-size: 11px;

  font-weight: 800;
}

.register-input {
  width: 100%;

  min-height: 52px;

  display: flex;

  align-items: center;

  gap: 8px;

  padding: 0 13px;

  border: 1px solid var(--border);

  border-radius: var(--radius-md);

  background: var(--surface-soft);
}

.register-input:focus-within {
  border-color: var(--primary);

  box-shadow:
    0 0 0 4px
      color-mix(
        in srgb,
        var(--primary) 10%,
        transparent
      );
}

.register-input > svg {
  flex: 0 0 auto;

  color: var(--text-faint);
}

.register-input input {
  min-width: 0;

  flex: 1;

  height: 50px;

  border: 0;

  outline: 0;

  color: var(--text-strong);

  background: transparent;

  font-size: 12px;

  font-weight: 600;
}

.register-input input::placeholder {
  color: var(--text-faint);
}

.register-input-error {
  border-color: var(--danger);
}

.register-error {
  display: block;

  margin-top: 6px;

  color: var(--danger);

  font-size: 10px;

  font-weight: 700;

  line-height: 1.45;
}

.register-hint {
  display: block;

  margin-top: 6px;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.5;
}

.verified-input {
  background:
    color-mix(
      in srgb,
      var(--success) 3%,
      var(--surface-soft)
    );
}

.verified-country {
  color: var(--text-body);

  font-size: 11px;

  font-weight: 800;
}

.verified-mark {
  min-height: 24px;

  display: inline-flex;

  align-items: center;

  gap: 4px;

  padding: 0 7px;

  border-radius: var(--radius-pill);

  color: var(--success);

  background: var(--success-soft);

  font-size: 8px;

  font-weight: 800;
}


/* =========================================================
   REGISTRATION GRIDS
========================================================= */

.register-two-column {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 13px;
}


/* =========================================================
   SELECT CONTROLS
========================================================= */

.register-select {
  position: relative;
}

.register-select > button {
  width: 100%;

  min-height: 52px;

  padding: 5px 11px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  border: 1px solid var(--border);

  border-radius: var(--radius-md);

  color: var(--text-body);

  background: var(--surface-soft);

  text-align: left;
}

.register-select > button:hover:not(:disabled) {
  background: var(--surface-hover);

  border-color: var(--border-strong);
}

.register-select > button:disabled {
  opacity: 0.55;

  cursor: not-allowed;
}

.register-select-main {
  min-width: 0;

  display: flex;

  align-items: center;

  gap: 9px;
}

.register-select-main > div:last-child {
  min-width: 0;
}

.register-select-main strong,
.register-select-main span {
  display: block;

  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;
}

.register-select-main strong {
  color: var(--text-strong);

  font-size: 10px;

  font-weight: 800;
}

.register-select-main span {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 8px;
}

.register-select > button > svg {
  flex: 0 0 auto;

  color: var(--text-faint);
}

.register-select-icon {
  width: 31px;
  height: 31px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 9px;

  color: var(--primary);

  background: var(--primary-soft);
}

.register-crop-emoji {
  width: 31px;
  height: 31px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 9px;

  background: var(--surface-hover);

  font-size: 17px;
}


/* =========================================================
   DROPDOWN
========================================================= */

.register-dropdown {
  position: absolute;

  z-index: 150;

  left: 0;
  right: 0;

  top: calc(100% + 7px);

  max-height: 280px;

  overflow-y: auto;

  padding: 6px;

  border: 1px solid var(--border);

  border-radius: var(--radius-md);

  background: var(--surface);

  box-shadow: var(--shadow-md);
}

.register-dropdown > button {
  width: 100%;

  min-height: 45px;

  padding: 6px 7px;

  display: flex;

  align-items: center;

  gap: 8px;

  border-radius: 9px;

  color: var(--text-body);

  background: transparent;

  text-align: left;
}

.register-dropdown > button:hover {
  background: var(--surface-hover);
}

.register-dropdown > button > div:nth-child(2) {
  min-width: 0;

  flex: 1;
}

.register-dropdown strong,
.register-dropdown span {
  display: block;
}

.register-dropdown strong {
  color: var(--text-strong);

  font-size: 10px;

  font-weight: 800;
}

.register-dropdown span {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 8px;
}

.register-dropdown > button > svg {
  flex: 0 0 auto;

  color: var(--primary);
}

.register-dropdown-icon {
  width: 30px;
  height: 30px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 9px;

  color: var(--primary);

  background: var(--primary-soft);
}


/* =========================================================
   LOCATION SUMMARY
========================================================= */

.location-path-card {
  margin-top: 15px;

  display: flex;

  align-items: flex-start;

  gap: 10px;

  padding: 13px;

  border: 1px solid
    color-mix(
      in srgb,
      var(--primary) 15%,
      var(--border)
    );

  border-radius: var(--radius-md);

  background:
    color-mix(
      in srgb,
      var(--primary) 4%,
      var(--surface)
    );
}

.location-path-icon {
  width: 34px;
  height: 34px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 9px;

  color: var(--primary);

  background: var(--surface);
}

.location-path-card > div:last-child {
  min-width: 0;
}

.location-path-card span,
.location-path-card strong,
.location-path-card small {
  display: block;
}

.location-path-card span {
  color: var(--text-faint);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 0.1em;
}

.location-path-card strong {
  margin-top: 4px;

  color: var(--text-strong);

  font-size: 10px;

  line-height: 1.5;
}

.location-path-card small {
  margin-top: 4px;

  color: var(--text-muted);

  font-size: 8px;

  line-height: 1.5;
}

.register-select-button-error {
  border-color: var(--danger) !important;
}


/* =========================================================
   LANGUAGE OPTIONS IN REGISTRATION
========================================================= */

.language-options {
  display: flex;

  flex-wrap: wrap;

  gap: 8px;
}

.language-option {
  min-height: 42px;

  padding: 0 12px;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 6px;

  border: 1px solid var(--border);

  border-radius: var(--radius-md);

  color: var(--text-body);

  background: var(--surface-soft);

  font-size: 10px;

  font-weight: 700;
}

.language-option:hover {
  background: var(--surface-hover);

  border-color: var(--border-strong);
}

.language-option.selected {
  border-color: var(--primary);

  color: var(--primary);

  background: var(--primary-soft);
}


/* =========================================================
   REGISTRATION FOOTER
========================================================= */

.register-submit-area {
  padding-top: 22px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 20px;
}

.register-submit-area > div span,
.register-submit-area > div strong {
  display: block;
}

.register-submit-area > div span {
  color: var(--text-muted);

  font-size: 8px;
}

.register-submit-area > div strong {
  margin-top: 3px;

  color: var(--text-strong);

  font-size: 10px;

  font-weight: 800;
}

.register-submit-area .app-button {
  min-width: 175px;
}

.register-terms {
  margin: 12px 0 0;

  color: var(--text-faint);

  font-size: 9px;

  line-height: 1.55;

  text-align: right;
}


/* =========================================================
   FARMER AUTH RESPONSIVE
========================================================= */

@media (max-width: 950px) {
  .farmer-login-container {
    grid-template-columns: 1fr;

    gap: 30px;

    max-width: 650px;
  }

  .farmer-login-intro {
    max-width: none;
  }

  .farmer-login-benefits {
    display: grid;

    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }

  .register-layout {
    grid-template-columns: 1fr;

    gap: 20px;
  }

  .register-intro {
    position: static;

    padding-top: 0;
  }

  .register-intro h1,
  .register-intro > p {
    max-width: 700px;
  }

  .register-benefits {
    display: grid;

    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 700px) {
  .farmer-login-container,
  .register-container {
    width: min(
      calc(100% - 24px),
      var(--content-width)
    );
  }

  .farmer-login-container {
    padding:
      35px
      0
      45px;
  }

  .farmer-login-intro h1,
  .register-intro h1 {
    font-size: 33px;
  }

  .farmer-login-benefits,
  .register-benefits {
    display: flex;
  }

  .farmer-login-card,
  .register-form-card {
    padding: 22px 19px;

    border-radius: 19px;
  }

  .register-two-column {
    grid-template-columns: 1fr;
  }

  .register-submit-area {
    align-items: stretch;

    flex-direction: column;
  }

  .register-submit-area .app-button {
    width: 100%;
  }

  .register-terms {
    text-align: left;
  }
}

@media (max-width: 480px) {
  .farmer-login-intro h1,
  .register-intro h1 {
    font-size: 29px;
  }

  .farmer-otp-inputs {
    gap: 5px;
  }

  .farmer-otp-input {
    width: 41px;
    height: 47px;
  }

  .language-options {
    flex-direction: column;
  }

  .language-option {
    width: 100%;
  }
}
/* =========================================================
   KRISHISETU
   PART 5 — FARMER HOME
========================================================= */


/* =========================================================
   FARMER HOME PAGE
========================================================= */

.farmer-home-page {
  min-height: 100vh;

  background:
    radial-gradient(
      circle at 6% 7%,
      color-mix(
        in srgb,
        var(--primary) 7%,
        transparent
      ),
      transparent 28%
    ),
    radial-gradient(
      circle at 94% 88%,
      color-mix(
        in srgb,
        var(--success) 5%,
        transparent
      ),
      transparent 28%
    ),
    var(--background);
}

.farmer-home-container {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  margin: 0 auto;

  padding: 32px 0 65px;
}


/* =========================================================
   WELCOME HEADER
========================================================= */

.farmer-welcome {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 25px;

  margin-bottom: 23px;
}

.farmer-welcome h1 {
  margin: 8px 0 5px;

  color: var(--text-main);

  font-family: var(--font-heading);

  font-size: 32px;

  line-height: 1.05;

  letter-spacing: -0.045em;
}

.farmer-welcome p {
  margin: 0;

  color: var(--text-muted);

  font-size: 12px;

  line-height: 1.55;
}

.farmer-profile {
  display: flex;

  align-items: center;

  gap: 9px;

  padding: 8px 11px 8px 8px;

  border: 1px solid var(--border);

  border-radius: var(--radius-md);

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.farmer-avatar {
  width: 38px;
  height: 38px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  color: var(--text-on-primary);

  background:
    linear-gradient(
      135deg,
      var(--primary),
      var(--primary-strong)
    );

  font-family: var(--font-heading);

  font-size: 12px;

  font-weight: 800;
}

.farmer-profile strong,
.farmer-profile span {
  display: block;
}

.farmer-profile strong {
  color: var(--text-strong);

  font-size: 10px;

  font-weight: 800;
}

.farmer-profile span {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 8px;
}


/* =========================================================
   NEXT BOOKING CARD
========================================================= */

.next-booking-card {
  position: relative;

  overflow: hidden;

  margin-bottom: 15px;

  padding: 25px;

  border: 1px solid
    color-mix(
      in srgb,
      var(--primary) 17%,
      var(--border)
    );

  border-radius: var(--radius-xl);

  background:
    linear-gradient(
      135deg,
      color-mix(
        in srgb,
        var(--primary) 4%,
        var(--surface)
      ),
      var(--surface)
    );

  box-shadow: var(--shadow-md);
}

.next-booking-card::before {
  content: "";

  position: absolute;

  top: -85px;
  right: -70px;

  width: 220px;
  height: 220px;

  border-radius: 50%;

  background:
    color-mix(
      in srgb,
      var(--primary) 6%,
      transparent
    );

  pointer-events: none;
}

.booking-card-top {
  position: relative;
  z-index: 1;

  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 20px;
}

.booking-token-row {
  display: flex;

  align-items: center;

  gap: 10px;

  margin-top: 9px;
}

.home-token {
  color: var(--primary);

  font-family: var(--font-heading);

  font-size: 31px;

  font-weight: 800;

  line-height: 1;

  letter-spacing: -0.04em;
}

.booking-confirmed-icon {
  width: 49px;
  height: 49px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 14px;

  color: var(--primary);

  background: var(--primary-soft);
}

.booking-main-details {
  position: relative;
  z-index: 1;

  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 11px;

  margin-top: 23px;
}

.home-detail {
  min-height: 84px;

  display: flex;

  align-items: flex-start;

  gap: 11px;

  padding: 13px;

  border: 1px solid var(--border);

  border-radius: 14px;

  background: var(--surface);
}

.home-detail-icon {
  width: 35px;
  height: 35px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 10px;

  color: var(--primary);

  background: var(--primary-soft);
}

.home-detail > div:last-child {
  min-width: 0;
}

.home-detail span,
.home-detail strong,
.home-detail small {
  display: block;
}

.home-detail span {
  color: var(--text-faint);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 0.05em;

  text-transform: uppercase;
}

.home-detail strong {
  overflow: hidden;

  margin-top: 4px;

  color: var(--text-strong);

  font-size: 11px;

  font-weight: 800;

  text-overflow: ellipsis;

  white-space: nowrap;
}

.home-detail small {
  margin-top: 3px;

  overflow: hidden;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.45;

  text-overflow: ellipsis;

  white-space: nowrap;
}

.booking-action-row {
  position: relative;
  z-index: 1;

  margin-top: 15px;

  display: flex;

  flex-wrap: wrap;

  align-items: center;

  gap: 8px;
}

.home-primary-action,
.home-secondary-action {
  min-height: 46px;

  padding: 0 14px;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 7px;

  border-radius: 11px;

  font-size: 10px;

  font-weight: 800;
}

.home-primary-action {
  color: var(--text-on-primary);

  background: var(--primary);

  box-shadow:
    0 7px 18px
      color-mix(
        in srgb,
        var(--primary) 19%,
        transparent
      );
}

.home-primary-action:hover {
  background: var(--primary-strong);

  transform: translateY(-1px);

  box-shadow:
    0 10px 22px
      color-mix(
        in srgb,
        var(--primary) 24%,
        transparent
      );
}

.home-secondary-action {
  color: var(--text-body);

  border: 1px solid var(--border);

  background: var(--surface);
}

.home-secondary-action:hover {
  color: var(--text-strong);

  border-color: var(--border-strong);

  background: var(--surface-hover);
}


/* =========================================================
   HOME FEATURE GRID
========================================================= */

.farmer-home-grid {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 11px;

  margin-bottom: 15px;
}

.home-feature-card {
  min-height: 175px;

  padding: 19px;

  display: flex;

  flex-direction: column;

  border: 1px solid var(--border);

  border-radius: var(--radius-lg);

  background: var(--surface);

  box-shadow: var(--shadow-sm);

  transition:
    transform var(--transition-fast),
    box-shadow var(--transition-normal),
    border-color var(--transition-fast),
    background-color var(--transition-normal);
}

.home-feature-card:hover {
  transform: translateY(-3px);

  border-color:
    color-mix(
      in srgb,
      var(--primary) 25%,
      var(--border)
    );

  box-shadow: var(--shadow-md);
}

.feature-card-top {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;
}

.feature-card-top > svg {
  color: var(--text-faint);
}

.feature-icon {
  width: 40px;
  height: 40px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  color: var(--primary);

  background: var(--primary-soft);
}

.home-feature-card h2 {
  margin: auto 0 6px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 14px;

  line-height: 1.25;

  letter-spacing: -0.025em;
}

.home-feature-card p {
  max-width: 300px;

  margin: 0;

  color: var(--text-muted);

  font-size: 10px;

  line-height: 1.6;
}

.booking-feature .feature-icon {
  color: var(--primary);

  background: var(--primary-soft);
}

.status-feature .feature-icon {
  color: var(--success);

  background: var(--success-soft);
}

.help-feature .feature-icon {
  color: var(--warning);

  background: var(--warning-soft);
}


/* =========================================================
   SMS CARD
========================================================= */

.home-sms-card {
  min-height: 96px;

  padding: 17px;

  display: flex;

  align-items: flex-start;

  gap: 12px;

  margin-bottom: 13px;

  border: 1px solid
    color-mix(
      in srgb,
      var(--success) 15%,
      var(--border)
    );

  border-radius: var(--radius-lg);

  background:
    linear-gradient(
      135deg,
      color-mix(
        in srgb,
        var(--success) 5%,
        var(--surface)
      ),
      var(--surface)
    );
}

.home-sms-icon {
  width: 39px;
  height: 39px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  color: var(--success);

  background: var(--success-soft);
}

.home-sms-card > div:last-child {
  min-width: 0;
}

.home-sms-card span {
  display: block;

  color: var(--success);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 0.1em;

  text-transform: uppercase;
}

.home-sms-card h3 {
  margin: 5px 0 4px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 13px;

  line-height: 1.3;
}

.home-sms-card p {
  margin: 0;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.55;
}


/* =========================================================
   HOME SUPPORT ROW
========================================================= */

.home-support-row {
  min-height: 38px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  padding-top: 7px;
}

.home-support-row > span {
  color: var(--text-faint);

  font-size: 8px;
}

.home-support-row > a {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  color: var(--primary);

  font-size: 9px;

  font-weight: 800;
}

.home-support-row > a:hover {
  color: var(--primary-strong);
}


/* =========================================================
   STATUS BADGE
========================================================= */

.status-badge {
  min-height: 25px;

  padding: 0 8px;

  display: inline-flex;

  align-items: center;

  gap: 5px;

  border: 1px solid transparent;

  border-radius: var(--radius-pill);

  font-size: 8px;

  font-weight: 800;

  white-space: nowrap;
}

.status-dot {
  width: 6px;
  height: 6px;

  flex: 0 0 auto;

  border-radius: 50%;

  background: currentColor;
}

.status-confirmed {
  color: var(--primary);

  border-color:
    color-mix(
      in srgb,
      var(--primary) 16%,
      var(--border)
    );

  background: var(--primary-soft);
}

.status-arrived {
  color: var(--success);

  border-color:
    color-mix(
      in srgb,
      var(--success) 16%,
      var(--border)
    );

  background: var(--success-soft);
}

.status-late {
  color: var(--warning);

  border-color:
    color-mix(
      in srgb,
      var(--warning) 16%,
      var(--border)
    );

  background: var(--warning-soft);
}

.status-weighing {
  color: #7257b5;

  border-color:
    color-mix(
      in srgb,
      #7257b5 16%,
      var(--border)
    );

  background: #f0ebfa;
}

.status-procured {
  color: var(--success);

  border-color:
    color-mix(
      in srgb,
      var(--success) 17%,
      var(--border)
    );

  background: var(--success-soft);
}

.status-payment-pending {
  color: var(--warning);

  border-color:
    color-mix(
      in srgb,
      var(--warning) 18%,
      var(--border)
    );

  background: var(--warning-soft);
}

.status-payment-sent {
  color: var(--success);

  border-color:
    color-mix(
      in srgb,
      var(--success) 18%,
      var(--border)
    );

  background: var(--success-soft);
}

.status-unknown {
  color: var(--text-muted);

  border-color: var(--border);

  background: var(--surface-soft);
}


/* =========================================================
   EMPTY FARMER HOME
========================================================= */

.farmer-home-container > .empty-state-card {
  margin-top: 30px;
}


/* =========================================================
   FARMER HOME RESPONSIVE
========================================================= */

@media (max-width: 850px) {
  .farmer-home-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .help-feature {
    grid-column: 1 / -1;
  }

  .farmer-welcome {
    align-items: flex-start;
  }
}

@media (max-width: 700px) {
  .farmer-home-container {
    width: min(
      calc(100% - 24px),
      var(--content-width)
    );

    padding-top: 24px;
  }

  .farmer-welcome {
    align-items: flex-start;

    flex-direction: column;
  }

  .farmer-profile {
    width: 100%;
  }

  .booking-main-details {
    grid-template-columns: 1fr;
  }

  .next-booking-card {
    padding: 19px;
  }

  .farmer-home-grid {
    grid-template-columns: 1fr;
  }

  .help-feature {
    grid-column: auto;
  }

  .booking-action-row {
    flex-direction: column;
    align-items: stretch;
  }

  .home-primary-action,
  .home-secondary-action {
    width: 100%;
  }

  .home-support-row {
    align-items: flex-start;

    flex-direction: column;

    gap: 5px;
  }
}

@media (max-width: 450px) {
  .farmer-welcome h1 {
    font-size: 28px;
  }

  .booking-card-top {
    align-items: flex-start;
  }

  .booking-confirmed-icon {
    width: 43px;
    height: 43px;
  }

  .home-token {
    font-size: 28px;
  }

  .booking-token-row {
    align-items: flex-start;

    flex-direction: column;

    gap: 7px;
  }

  .home-sms-card {
    padding: 14px;
  }
}
/* =========================================================
   KRISHISETU
   PART 6 — FARMER BOOKING
========================================================= */


/* =========================================================
   BOOKING PAGE
========================================================= */

.farmer-book-page {
  min-height: 100vh;

  background:
    radial-gradient(
      circle at 7% 7%,
      color-mix(
        in srgb,
        var(--primary) 6%,
        transparent
      ),
      transparent 28%
    ),
    var(--background);
}

.booking-container {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  margin: 0 auto;

  padding: 30px 0 65px;
}


/* =========================================================
   BOOKING TOP
========================================================= */

.booking-top-row {
  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 30px;

  margin-bottom: 25px;
}

.booking-top-row h1 {
  margin: 8px 0 7px;

  color: var(--text-main);

  font-family: var(--font-heading);

  font-size: 33px;

  line-height: 1.05;

  letter-spacing: -0.045em;
}

.booking-top-row p {
  max-width: 590px;

  margin: 0;

  color: var(--text-muted);

  font-size: 12px;

  line-height: 1.6;
}


/* =========================================================
   BOOKING STEPS
========================================================= */

.booking-step-indicator {
  min-width: 335px;

  display: flex;

  align-items: center;

  justify-content: flex-end;

  padding-bottom: 2px;
}

.booking-step {
  display: flex;

  align-items: center;

  gap: 6px;

  color: var(--text-faint);

  font-size: 8px;

  font-weight: 800;

  white-space: nowrap;
}

.booking-step span {
  width: 27px;
  height: 27px;

  display: flex;

  align-items: center;

  justify-content: center;

  border: 1px solid var(--border);

  border-radius: 50%;

  color: var(--text-muted);

  background: var(--surface);

  font-size: 9px;
}

.booking-step.active {
  color: var(--primary);
}

.booking-step.active span {
  color: var(--text-on-primary);

  border-color: var(--primary);

  background: var(--primary);
}

.booking-step-line {
  width: 30px;
  height: 1px;

  margin: 0 6px;

  background: var(--border);
}


/* =========================================================
   BOOKING LAYOUT
========================================================= */

.booking-layout {
  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    minmax(280px, 0.42fr);

  align-items: start;

  gap: 16px;
}

.booking-form-column {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 14px;
}

.booking-panel {
  padding: 22px;

  border: 1px solid var(--border);

  border-radius: var(--radius-xl);

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.booking-panel-heading {
  display: flex;

  align-items: center;

  gap: 10px;

  padding-bottom: 19px;

  margin-bottom: 19px;

  border-bottom: 1px solid var(--border);
}

.panel-icon {
  width: 41px;
  height: 41px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 12px;

  color: var(--primary);

  background: var(--primary-soft);
}

.booking-panel-heading h2 {
  margin: 0;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 16px;

  line-height: 1.2;
}

.booking-panel-heading p {
  margin: 4px 0 0;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.5;
}


/* =========================================================
   BOOKING FORM
========================================================= */

.form-grid {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 13px;
}

.booking-form-field {
  min-width: 0;
}

.booking-form-field > label {
  display: block;

  margin-bottom: 7px;

  color: var(--text-body);

  font-size: 10px;

  font-weight: 800;
}

.custom-select {
  position: relative;
}

.select-control {
  width: 100%;

  min-height: 52px;

  padding: 6px 11px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

  border: 1px solid var(--border);

  border-radius: var(--radius-md);

  color: var(--text-body);

  background: var(--surface-soft);

  text-align: left;
}

.select-control:hover {
  background: var(--surface-hover);

  border-color: var(--border-strong);
}

.select-main {
  min-width: 0;

  display: flex;

  align-items: center;

  gap: 9px;
}

.select-main > span:last-child {
  overflow: hidden;

  color: var(--text-strong);

  font-size: 11px;

  font-weight: 800;

  text-overflow: ellipsis;

  white-space: nowrap;
}

.crop-emoji {
  width: 31px;
  height: 31px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 9px;

  background: var(--surface-hover);

  font-size: 17px;
}

.select-control > svg {
  flex: 0 0 auto;

  color: var(--text-faint);
}

.select-menu {
  position: absolute;

  z-index: 150;

  top: calc(100% + 7px);

  left: 0;
  right: 0;

  max-height: 280px;

  overflow-y: auto;

  padding: 6px;

  border: 1px solid var(--border);

  border-radius: var(--radius-md);

  background: var(--surface);

  box-shadow: var(--shadow-md);
}

.select-option {
  width: 100%;

  min-height: 44px;

  padding: 6px 8px;

  display: flex;

  align-items: center;

  gap: 8px;

  border-radius: 9px;

  color: var(--text-body);

  text-align: left;
}

.select-option:hover,
.select-option.selected {
  background: var(--surface-hover);
}

.select-option > span:nth-child(2) {
  flex: 1;

  color: var(--text-strong);

  font-size: 10px;

  font-weight: 800;
}

.select-option > svg {
  flex: 0 0 auto;

  color: var(--primary);
}


/* =========================================================
   CENTER SELECT
========================================================= */

.center-select-icon,
.center-option-icon {
  width: 32px;
  height: 32px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 9px;

  color: var(--primary);

  background: var(--primary-soft);
}

.center-select-text {
  min-width: 0;
}

.center-select-text strong,
.center-select-text span {
  display: block;

  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;
}

.center-select-text strong {
  color: var(--text-strong);

  font-size: 10px;

  font-weight: 800;
}

.center-select-text span {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 8px;
}

.center-option {
  width: 100%;

  min-height: 54px;

  padding: 7px 8px;

  display: flex;

  align-items: center;

  gap: 9px;

  border-radius: 10px;

  color: var(--text-body);

  text-align: left;
}

.center-option:hover,
.center-option.selected {
  background: var(--surface-hover);
}

.center-option > div:nth-child(2) {
  min-width: 0;

  flex: 1;
}

.center-option strong,
.center-option span {
  display: block;

  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;
}

.center-option strong {
  color: var(--text-strong);

  font-size: 10px;

  font-weight: 800;
}

.center-option span {
  margin-top: 3px;

  color: var(--text-muted);

  font-size: 8px;
}

.center-option > svg {
  flex: 0 0 auto;

  color: var(--primary);
}


/* =========================================================
   QUANTITY INPUT
========================================================= */

.quantity-input {
  min-height: 52px;

  padding: 0 12px;

  display: flex;

  align-items: center;

  gap: 8px;

  border: 1px solid var(--border);

  border-radius: var(--radius-md);

  background: var(--surface-soft);
}

.quantity-input:focus-within {
  border-color: var(--primary);

  box-shadow:
    0 0 0 4px
      color-mix(
        in srgb,
        var(--primary) 9%,
        transparent
      );
}

.quantity-input > svg {
  flex: 0 0 auto;

  color: var(--text-faint);
}

.quantity-input input {
  width: 100%;

  min-width: 0;

  height: 49px;

  border: 0;

  outline: 0;

  color: var(--text-strong);

  background: transparent;

  font-size: 12px;

  font-weight: 700;
}

.quantity-input > span {
  flex: 0 0 auto;

  color: var(--text-muted);

  font-size: 10px;

  font-weight: 800;
}

.booking-input-error {
  border-color: var(--danger);
}

.quantity-note {
  margin-top: 10px;

  padding: 10px 11px;

  display: flex;

  align-items: flex-start;

  gap: 7px;

  border: 1px solid var(--border);

  border-radius: 10px;

  color: var(--text-muted);

  background: var(--surface-soft);

  font-size: 9px;

  line-height: 1.55;
}

.quantity-note > span {
  min-height: 20px;

  padding: 0 6px;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  border-radius: 6px;

  color: var(--primary);

  background: var(--primary-soft);

  font-size: 7px;

  font-weight: 900;

  letter-spacing: 0.07em;

  text-transform: uppercase;
}


/* =========================================================
   DATE OPTIONS
========================================================= */

.date-field {
  margin-top: 18px;
}

.date-options {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 8px;
}

.date-option {
  position: relative;

  min-height: 76px;

  padding: 10px;

  display: flex;

  flex-direction: column;

  align-items: flex-start;

  justify-content: center;

  border: 1px solid var(--border);

  border-radius: 13px;

  color: var(--text-body);

  background: var(--surface-soft);

  text-align: left;
}

.date-option:hover {
  border-color: var(--border-strong);

  background: var(--surface-hover);
}

.date-option.selected {
  border-color: var(--primary);

  background: var(--primary-soft);
}

.date-option > span {
  color: var(--text-muted);

  font-size: 8px;

  font-weight: 700;
}

.date-option > strong {
  margin-top: 4px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 17px;

  line-height: 1;
}

.date-option > small {
  margin-top: 3px;

  color: var(--text-muted);

  font-size: 8px;

  font-weight: 800;
}

.date-check {
  position: absolute;

  top: 8px;
  right: 8px;

  width: 20px;
  height: 20px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 50%;

  color: var(--text-on-primary);

  background: var(--primary);
}


/* =========================================================
   BOOKING ERROR
========================================================= */

.booking-error {
  margin: 14px 0;

  padding: 11px 12px;

  border: 1px solid
    color-mix(
      in srgb,
      var(--danger) 18%,
      var(--border)
    );

  border-radius: 10px;

  color: var(--danger);

  background: var(--danger-soft);

  font-size: 10px;

  font-weight: 700;

  line-height: 1.5;
}


/* =========================================================
   BOOKING SUMMARY
========================================================= */

.booking-summary-column {
  position: sticky;

  top: 98px;
}

.booking-summary-card {
  overflow: hidden;

  border: 1px solid var(--border);

  border-radius: var(--radius-xl);

  background: var(--surface);

  box-shadow: var(--shadow-md);
}

.summary-header {
  min-height: 58px;

  padding: 0 18px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  border-bottom: 1px solid var(--border);
}

.summary-header span {
  color: var(--text-faint);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 0.12em;

  text-transform: uppercase;
}

.summary-header svg {
  color: var(--primary);
}

.summary-crop {
  padding: 18px;

  display: flex;

  align-items: center;

  gap: 10px;
}

.summary-crop-icon {
  width: 43px;
  height: 43px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 12px;

  background: var(--surface-hover);

  font-size: 23px;
}

.summary-crop span,
.summary-crop strong {
  display: block;
}

.summary-crop span {
  color: var(--text-muted);

  font-size: 8px;
}

.summary-crop strong {
  margin-top: 3px;

  color: var(--text-strong);

  font-size: 13px;

  font-weight: 800;
}

.summary-list {
  padding: 0 18px;
}

.summary-list > div {
  min-height: 54px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 12px;

  border-top: 1px solid var(--border);
}

.summary-list span {
  color: var(--text-muted);

  font-size: 9px;
}

.summary-list strong {
  max-width: 58%;

  overflow: hidden;

  color: var(--text-strong);

  font-size: 9px;

  font-weight: 800;

  text-align: right;

  text-overflow: ellipsis;
}

.summary-available {
  margin: 14px;

  padding: 11px;

  display: flex;

  align-items: flex-start;

  gap: 8px;

  border-radius: 11px;

  background: var(--success-soft);
}

.summary-available-icon {
  width: 25px;
  height: 25px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 7px;

  color: var(--success);

  background: var(--surface);
}

.summary-available strong,
.summary-available span {
  display: block;
}

.summary-available strong {
  color: var(--success);

  font-size: 9px;

  font-weight: 800;
}

.summary-available span {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 8px;

  line-height: 1.45;
}


/* =========================================================
   AVAILABILITY
========================================================= */

.availability-section {
  margin-top: 16px;

  padding: 23px;

  border: 1px solid var(--border);

  border-radius: var(--radius-xl);

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.availability-heading {
  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 20px;

  margin-bottom: 19px;
}

.availability-heading h2 {
  margin: 7px 0 4px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 20px;

  letter-spacing: -0.035em;
}

.availability-heading p {
  margin: 0;

  color: var(--text-muted);

  font-size: 9px;
}

.availability-heading p strong {
  color: var(--text-body);

  font-weight: 800;
}

.capacity-note {
  min-width: 105px;

  padding: 9px 11px;

  border: 1px solid var(--border);

  border-radius: 10px;

  text-align: right;

  background: var(--surface-soft);
}

.capacity-note span,
.capacity-note strong {
  display: block;
}

.capacity-note span {
  color: var(--text-muted);

  font-size: 8px;
}

.capacity-note strong {
  margin-top: 2px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 17px;
}


/* =========================================================
   SLOT GRID
========================================================= */

.slot-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 9px;
}

.slot-card {
  position: relative;

  min-height: 154px;

  padding: 14px;

  display: flex;

  flex-direction: column;

  align-items: stretch;

  border: 1px solid var(--border);

  border-radius: 14px;

  color: var(--text-body);

  background: var(--surface-soft);

  text-align: left;
}

.slot-card:hover:not(:disabled) {
  transform: translateY(-2px);

  border-color:
    color-mix(
      in srgb,
      var(--primary) 28%,
      var(--border)
    );

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.slot-card.selected {
  border-color: var(--primary);

  background: var(--primary-soft);

  box-shadow:
    0 8px 25px
      color-mix(
        in srgb,
        var(--primary) 10%,
        transparent
      );
}

.slot-card:disabled,
.slot-card.slot-full {
  opacity: 0.48;

  cursor: not-allowed;
}

.slot-card:disabled:hover {
  transform: none;

  box-shadow: none;
}

.slot-top {
  display: flex;

  align-items: center;

  justify-content: space-between;
}

.slot-icon {
  width: 34px;
  height: 34px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 10px;

  color: var(--primary);

  background: var(--primary-soft);
}

.slot-check {
  width: 22px;
  height: 22px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 50%;

  color: var(--text-on-primary);

  background: var(--primary);
}

.slot-time {
  margin-top: 17px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 11px;

  line-height: 1.35;
}

.slot-load {
  width: fit-content;

  min-height: 22px;

  margin-top: 7px;

  padding: 0 7px;

  display: inline-flex;

  align-items: center;

  border-radius: 7px;

  font-size: 7px;

  font-weight: 800;
}

.slot-load.normal {
  color: var(--success);

  background: var(--success-soft);
}

.slot-load.limited {
  color: var(--warning);

  background: var(--warning-soft);
}

.slot-load.busy {
  color: var(--danger);

  background: var(--danger-soft);
}

.slot-bottom {
  margin-top: auto;

  padding-top: 13px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 8px;

  border-top: 1px solid var(--border);
}

.slot-bottom span {
  color: var(--text-muted);

  font-size: 8px;

  font-weight: 700;
}

.slot-bottom svg {
  color: var(--primary);
}


/* =========================================================
   AVAILABILITY FOOTER
========================================================= */

.availability-footer {
  margin-top: 17px;

  padding-top: 17px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  border-top: 1px solid var(--border);
}

.availability-info {
  min-width: 0;

  display: flex;

  align-items: flex-start;

  gap: 7px;
}

.info-dot {
  width: 7px;
  height: 7px;

  flex: 0 0 auto;

  margin-top: 4px;

  border-radius: 50%;

  background: var(--primary);
}

.availability-info p {
  max-width: 500px;

  margin: 0;

  color: var(--text-muted);

  font-size: 8px;

  line-height: 1.5;
}


/* =========================================================
   TRUST STRIP
========================================================= */

.booking-trust-strip {
  margin-top: 14px;

  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 9px;
}

.booking-trust-strip > div {
  min-height: 50px;

  padding: 10px;

  display: flex;

  align-items: center;

  gap: 7px;

  border: 1px solid var(--border);

  border-radius: 11px;

  background: var(--surface);
}

.booking-trust-strip svg {
  flex: 0 0 auto;

  color: var(--success);
}

.booking-trust-strip span {
  color: var(--text-muted);

  font-size: 8px;

  line-height: 1.45;
}


/* =========================================================
   BOOKING RESPONSIVE
========================================================= */

@media (max-width: 1000px) {
  .booking-layout {
    grid-template-columns: 1fr;
  }

  .booking-summary-column {
    position: static;
  }

  .booking-summary-card {
    width: 100%;
  }

  .slot-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 800px) {
  .booking-top-row {
    align-items: flex-start;

    flex-direction: column;
  }

  .booking-step-indicator {
    min-width: 0;

    width: 100%;

    justify-content: flex-start;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }

  .date-options {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 650px) {
  .booking-container {
    width: min(
      calc(100% - 24px),
      var(--content-width)
    );

    padding-top: 23px;
  }

  .booking-top-row h1 {
    font-size: 29px;
  }

  .booking-step {
    font-size: 7px;
  }

  .booking-step span {
    width: 25px;
    height: 25px;
  }

  .booking-step-line {
    width: 18px;

    margin: 0 4px;
  }

  .booking-panel,
  .availability-section {
    padding: 18px;
  }

  .date-options {
    gap: 6px;
  }

  .date-option {
    min-height: 70px;

    padding: 8px;
  }

  .slot-grid {
    grid-template-columns: 1fr;
  }

  .availability-heading {
    align-items: flex-start;

    flex-direction: column;
  }

  .capacity-note {
    width: 100%;

    text-align: left;
  }

  .availability-footer {
    align-items: stretch;

    flex-direction: column;
  }

  .availability-footer .app-button {
    width: 100%;
  }

  .booking-trust-strip {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 450px) {
  .booking-step-indicator {
    justify-content: space-between;
  }

  .booking-step-line {
    flex: 1;
  }

  .date-option > strong {
    font-size: 15px;
  }
}
/* =========================================================
   KRISHISETU
   PART 7 — FARMER TOKEN / TRACKING
========================================================= */


/* =========================================================
   TOKEN PAGE
========================================================= */

.farmer-token-page {
  min-height: 100vh;

  background:
    radial-gradient(
      circle at 7% 7%,
      color-mix(
        in srgb,
        var(--primary) 7%,
        transparent
      ),
      transparent 29%
    ),
    radial-gradient(
      circle at 93% 90%,
      color-mix(
        in srgb,
        var(--success) 5%,
        transparent
      ),
      transparent 27%
    ),
    var(--background);
}

.token-container {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  margin: 0 auto;

  padding: 30px 0 65px;
}

.token-back-row {
  margin-bottom: 20px;
}


/* =========================================================
   TOKEN HEADING
========================================================= */

.token-heading-row {
  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 30px;

  margin-bottom: 23px;
}

.token-heading-row h1 {
  margin: 8px 0 7px;

  color: var(--text-main);

  font-family: var(--font-heading);

  font-size: 33px;

  line-height: 1.04;

  letter-spacing: -0.045em;
}

.token-heading-row p {
  max-width: 600px;

  margin: 0;

  color: var(--text-muted);

  font-size: 12px;

  line-height: 1.6;
}

.last-updated {
  min-width: 115px;

  padding: 10px 12px;

  border: 1px solid var(--border);

  border-radius: 12px;

  background: var(--surface);

  text-align: right;

  box-shadow: var(--shadow-sm);
}

.last-updated span,
.last-updated strong,
.last-updated small {
  display: block;
}

.last-updated span {
  color: var(--text-faint);

  font-size: 7px;

  font-weight: 800;

  letter-spacing: 0.1em;

  text-transform: uppercase;
}

.last-updated strong {
  margin-top: 4px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 15px;
}

.last-updated small {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 7px;
}


/* =========================================================
   TOKEN LAYOUT
========================================================= */

.token-layout {
  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    minmax(285px, 0.40fr);

  align-items: start;

  gap: 15px;
}

.token-main-column {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 15px;
}

.token-side-column {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 13px;
}


/* =========================================================
   BIG TOKEN CARD
========================================================= */

.big-token-card {
  position: relative;

  overflow: hidden;

  padding: 25px;

  border: 1px solid
    color-mix(
      in srgb,
      var(--primary) 17%,
      var(--border)
    );

  border-radius: var(--radius-xl);

  background:
    linear-gradient(
      135deg,
      color-mix(
        in srgb,
        var(--primary) 5%,
        var(--surface)
      ),
      var(--surface)
    );

  box-shadow: var(--shadow-md);
}

.big-token-card::after {
  content: "";

  position: absolute;

  top: -100px;
  right: -80px;

  width: 260px;
  height: 260px;

  border-radius: 50%;

  background:
    color-mix(
      in srgb,
      var(--primary) 7%,
      transparent
    );

  pointer-events: none;
}

.token-card-header {
  position: relative;
  z-index: 1;

  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 20px;
}

.token-label {
  display: block;

  color: var(--text-faint);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 0.12em;

  text-transform: uppercase;
}

.token-number {
  margin-top: 7px;

  color: var(--primary);

  font-family: var(--font-heading);

  font-size: 49px;

  font-weight: 800;

  line-height: 0.95;

  letter-spacing: -0.06em;
}


/* =========================================================
   ARRIVAL BOX
========================================================= */

.token-arrival-box {
  position: relative;
  z-index: 1;

  margin-top: 23px;

  padding: 15px;

  display: flex;

  align-items: flex-start;

  gap: 11px;

  border: 1px solid var(--border);

  border-radius: 15px;

  background: var(--surface);
}

.token-arrival-icon {
  width: 43px;
  height: 43px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  color: var(--primary);

  background: var(--primary-soft);
}

.token-arrival-content {
  min-width: 0;
}

.token-arrival-content > span {
  display: block;

  color: var(--text-faint);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 0.08em;

  text-transform: uppercase;
}

.token-arrival-content > strong {
  display: block;

  margin-top: 4px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 14px;
}

.token-arrival-content h2 {
  margin: 4px 0 4px;

  color: var(--primary);

  font-family: var(--font-heading);

  font-size: 23px;

  line-height: 1.1;

  letter-spacing: -0.03em;
}

.token-arrival-content p {
  margin: 0;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.55;
}


/* =========================================================
   CENTER SUMMARY
========================================================= */

.center-summary {
  position: relative;
  z-index: 1;

  margin-top: 11px;

  min-height: 63px;

  padding: 10px 11px;

  display: flex;

  align-items: center;

  gap: 10px;

  border: 1px solid var(--border);

  border-radius: 13px;

  background: var(--surface);
}

.center-summary-icon {
  width: 35px;
  height: 35px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 9px;

  color: var(--primary);

  background: var(--primary-soft);
}

.center-summary > div:nth-child(2) {
  min-width: 0;

  flex: 1;
}

.center-summary span,
.center-summary strong,
.center-summary small {
  display: block;

  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;
}

.center-summary span {
  color: var(--text-faint);

  font-size: 7px;

  font-weight: 800;

  letter-spacing: 0.08em;

  text-transform: uppercase;
}

.center-summary strong {
  margin-top: 2px;

  color: var(--text-strong);

  font-size: 10px;

  font-weight: 800;
}

.center-summary small {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 8px;
}

.center-help-button {
  width: 31px;
  height: 31px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border: 1px solid var(--border);

  border-radius: 8px;

  color: var(--primary);

  background: var(--surface-soft);
}

.center-help-button:hover {
  background: var(--surface-hover);

  border-color: var(--border-strong);
}


/* =========================================================
   TIMELINE CARD
========================================================= */

.timeline-card {
  padding: 22px;

  border: 1px solid var(--border);

  border-radius: var(--radius-xl);

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.timeline-header {
  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 15px;

  padding-bottom: 17px;

  border-bottom: 1px solid var(--border);
}

.timeline-header h2 {
  margin: 6px 0 0;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 18px;

  letter-spacing: -0.03em;
}

.live-status {
  min-height: 27px;

  padding: 0 8px;

  display: inline-flex;

  align-items: center;

  gap: 5px;

  border-radius: var(--radius-pill);

  color: var(--success);

  background: var(--success-soft);

  font-size: 8px;

  font-weight: 800;
}

.live-status span {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: var(--success);
}


/* =========================================================
   TIMELINE
========================================================= */

.timeline {
  padding-top: 18px;
}

.timeline-item {
  display: grid;

  grid-template-columns: 37px minmax(0, 1fr);

  gap: 9px;

  min-height: 82px;
}

.timeline-rail {
  position: relative;

  display: flex;

  flex-direction: column;

  align-items: center;
}

.timeline-icon {
  width: 32px;
  height: 32px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border: 1px solid var(--border);

  border-radius: 50%;

  color: var(--text-faint);

  background: var(--surface-soft);
}

.timeline-line {
  width: 1px;

  flex: 1;

  margin-top: 4px;

  background: var(--border);
}

.timeline-content {
  min-width: 0;

  padding:
    1px
    0
    20px;
}

.timeline-title-row {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;
}

.timeline-title-row strong {
  color: var(--text-muted);

  font-family: var(--font-heading);

  font-size: 11px;

  font-weight: 800;
}

.timeline-title-row span {
  color: var(--text-faint);

  font-size: 8px;

  white-space: nowrap;
}

.timeline-content p {
  max-width: 500px;

  margin: 4px 0 0;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.55;
}

.timeline-current-note {
  width: fit-content;

  min-height: 22px;

  margin-top: 6px;

  padding: 0 7px;

  display: inline-flex;

  align-items: center;

  gap: 5px;

  border-radius: 7px;

  color: var(--primary);

  background: var(--primary-soft);

  font-size: 7px;

  font-weight: 800;
}

.timeline-current-note span {
  width: 5px;
  height: 5px;

  border-radius: 50%;

  background: var(--primary);
}


/* =========================================================
   TIMELINE COMPLETE / CURRENT
========================================================= */

.timeline-completed .timeline-icon {
  color: var(--success);

  border-color:
    color-mix(
      in srgb,
      var(--success) 20%,
      var(--border)
    );

  background: var(--success-soft);
}

.timeline-completed .timeline-line {
  background:
    color-mix(
      in srgb,
      var(--success) 28%,
      var(--border)
    );
}

.timeline-completed
  .timeline-title-row
  strong {
  color: var(--text-strong);
}

.timeline-current .timeline-icon {
  color: var(--primary);

  border-color: var(--primary);

  background: var(--primary-soft);

  box-shadow:
    0 0 0 5px
      color-mix(
        in srgb,
        var(--primary) 8%,
        transparent
      );
}

.timeline-current
  .timeline-title-row
  strong {
  color: var(--primary);
}


/* =========================================================
   TIMELINE NOTE
========================================================= */

.timeline-note {
  margin-top: 1px;

  padding: 11px 12px;

  border-radius: 10px;

  color: var(--text-muted);

  background: var(--surface-soft);

  font-size: 8px;

  line-height: 1.55;
}


/* =========================================================
   SIDE CARDS
========================================================= */

.booking-details-card,
.sms-token-card,
.help-token-card {
  padding: 19px;

  border: 1px solid var(--border);

  border-radius: var(--radius-lg);

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.side-card-heading {
  display: flex;

  align-items: center;

  gap: 9px;

  padding-bottom: 14px;

  border-bottom: 1px solid var(--border);
}

.side-card-icon {
  width: 36px;
  height: 36px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 10px;

  color: var(--primary);

  background: var(--primary-soft);
}

.side-card-heading span {
  display: block;

  color: var(--text-faint);

  font-size: 7px;

  font-weight: 800;

  letter-spacing: 0.1em;

  text-transform: uppercase;
}

.side-card-heading h2 {
  margin: 3px 0 0;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 13px;
}

.details-list {
  padding-top: 7px;
}

.details-list > div {
  min-height: 48px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 12px;

  border-bottom: 1px solid var(--border);
}

.details-list > div:last-child {
  border-bottom: 0;
}

.details-list span {
  color: var(--text-muted);

  font-size: 8px;
}

.details-list strong {
  max-width: 62%;

  overflow: hidden;

  color: var(--text-strong);

  font-size: 9px;

  font-weight: 800;

  text-align: right;

  text-overflow: ellipsis;
}


/* =========================================================
   SMS TOKEN CARD
========================================================= */

.sms-token-card {
  border-color:
    color-mix(
      in srgb,
      var(--success) 15%,
      var(--border)
    );

  background:
    linear-gradient(
      135deg,
      color-mix(
        in srgb,
        var(--success) 5%,
        var(--surface)
      ),
      var(--surface)
    );
}

.sms-token-icon {
  width: 41px;
  height: 41px;

  margin-bottom: 12px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  color: var(--success);

  background: var(--success-soft);
}

.sms-token-card > span {
  display: block;

  color: var(--success);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 0.1em;

  text-transform: uppercase;
}

.sms-token-card h3 {
  margin: 6px 0;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 13px;

  line-height: 1.4;
}

.sms-token-card p {
  margin: 0;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.6;
}

.sms-instructions-button {
  width: 100%;

  min-height: 39px;

  margin-top: 13px;

  padding: 0 10px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  border: 1px solid var(--border);

  border-radius: 10px;

  color: var(--success);

  background: var(--surface);

  font-size: 9px;

  font-weight: 800;
}

.sms-instructions-button:hover {
  background: var(--surface-hover);

  border-color: var(--border-strong);
}


/* =========================================================
   HELP TOKEN CARD
========================================================= */

.help-token-card {
  display: flex;

  flex-direction: column;
}

.help-token-icon {
  width: 40px;
  height: 40px;

  margin-bottom: 11px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  color: var(--warning);

  background: var(--warning-soft);
}

.help-token-card span {
  color: var(--text-faint);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 0.1em;

  text-transform: uppercase;
}

.help-token-card h3 {
  margin: 5px 0 4px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 13px;
}

.help-token-card p {
  margin: 0;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.6;
}

.help-actions {
  margin-top: 13px;

  display: grid;

  grid-template-columns: 1fr 1fr;

  gap: 7px;
}

.help-actions a,
.help-actions button {
  min-height: 37px;

  display: flex;

  align-items: center;

  justify-content: center;

  gap: 5px;

  border: 1px solid var(--border);

  border-radius: 10px;

  color: var(--text-body);

  background: var(--surface-soft);

  font-size: 8px;

  font-weight: 800;

  text-align: center;
}

.help-actions a:hover,
.help-actions button:hover {
  color: var(--primary);

  border-color: var(--border-strong);

  background: var(--surface-hover);
}


/* =========================================================
   TOKEN BOTTOM ACTIONS
========================================================= */

.token-bottom-actions {
  margin-top: 15px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 12px;
}

.token-home-action,
.token-new-booking-action {
  min-height: 44px;

  padding: 0 13px;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 7px;

  border-radius: 11px;

  font-size: 9px;

  font-weight: 800;
}

.token-home-action {
  color: var(--text-body);

  border: 1px solid var(--border);

  background: var(--surface);
}

.token-home-action:hover {
  background: var(--surface-hover);

  border-color: var(--border-strong);
}

.token-new-booking-action {
  color: var(--text-on-primary);

  background: var(--primary);

  box-shadow:
    0 7px 18px
      color-mix(
        in srgb,
        var(--primary) 18%,
        transparent
      );
}

.token-new-booking-action:hover {
  background: var(--primary-strong);

  transform: translateY(-1px);
}


/* =========================================================
   TOKEN RESPONSIVE
========================================================= */

@media (max-width: 1000px) {
  .token-layout {
    grid-template-columns: 1fr;
  }

  .token-side-column {
    display: grid;

    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .booking-details-card {
    grid-row: span 2;
  }

  .help-token-card {
    grid-column: 1 / -1;
  }
}

@media (max-width: 760px) {
  .token-heading-row {
    align-items: flex-start;

    flex-direction: column;
  }

  .last-updated {
    width: 100%;

    text-align: left;
  }

  .token-side-column {
    display: flex;
  }
}

@media (max-width: 650px) {
  .token-container {
    width: min(
      calc(100% - 24px),
      var(--content-width)
    );

    padding-top: 23px;
  }

  .token-heading-row h1 {
    font-size: 29px;
  }

  .big-token-card {
    padding: 19px;
  }

  .token-number {
    font-size: 42px;
  }

  .timeline-card {
    padding: 18px;
  }

  .timeline-title-row {
    align-items: flex-start;

    flex-direction: column;

    gap: 3px;
  }

  .token-bottom-actions {
    align-items: stretch;

    flex-direction: column;
  }

  .token-home-action,
  .token-new-booking-action {
    width: 100%;
  }
}

@media (max-width: 450px) {
  .token-card-header {
    align-items: flex-start;

    flex-direction: column;

    gap: 10px;
  }

  .token-arrival-box {
    padding: 12px;
  }

  .token-arrival-content h2 {
    font-size: 20px;
  }

  .center-summary {
    align-items: flex-start;
  }

  .help-actions {
    grid-template-columns: 1fr;
  }

  .timeline-item {
    grid-template-columns: 31px minmax(0, 1fr);

    gap: 7px;
  }

  .timeline-icon {
    width: 28px;
    height: 28px;
  }
}
/* =========================================================
   KRISHISETU
   PART 8 — FARMER HELP / FAQ
========================================================= */


/* =========================================================
   HELP PAGE
========================================================= */

.farmer-help-page {
  min-height: 100vh;

  background:
    radial-gradient(
      circle at 7% 7%,
      color-mix(
        in srgb,
        var(--primary) 6%,
        transparent
      ),
      transparent 29%
    ),
    radial-gradient(
      circle at 92% 90%,
      color-mix(
        in srgb,
        var(--success) 5%,
        transparent
      ),
      transparent 27%
    ),
    var(--background);
}

.help-container {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  margin: 0 auto;

  padding: 30px 0 70px;
}

.help-back-row {
  margin-bottom: 20px;
}


/* =========================================================
   HELP HERO
========================================================= */

.help-hero {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 30px;

  padding-bottom: 25px;

  border-bottom: 1px solid var(--border);
}

.help-hero h1 {
  margin: 9px 0 9px;

  color: var(--text-main);

  font-family: var(--font-heading);

  font-size: 37px;

  line-height: 1.03;

  letter-spacing: -0.05em;
}

.help-hero h1 span {
  color: var(--primary);
}

.help-hero p {
  max-width: 600px;

  margin: 0;

  color: var(--text-body);

  font-size: 13px;

  line-height: 1.7;
}

.help-hero-icon {
  width: 75px;
  height: 75px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border: 1px solid
    color-mix(
      in srgb,
      var(--primary) 18%,
      var(--border)
    );

  border-radius: 21px;

  color: var(--primary);

  background: var(--primary-soft);
}


/* =========================================================
   HELP MAIN GRID
========================================================= */

.help-main-grid {
  display: grid;

  grid-template-columns:
    minmax(0, 1.28fr)
    minmax(310px, 0.72fr);

  gap: 16px;

  margin-top: 24px;

  align-items: start;
}

.faq-section {
  min-width: 0;

  padding: 22px;

  border: 1px solid var(--border);

  border-radius: var(--radius-xl);

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.help-section-heading {
  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 15px;

  padding-bottom: 16px;

  border-bottom: 1px solid var(--border);
}

.help-section-heading > div:first-child > span {
  color: var(--text-faint);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 0.12em;

  text-transform: uppercase;
}

.help-section-heading h2 {
  margin: 5px 0 0;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 19px;

  letter-spacing: -0.03em;
}

.faq-count {
  min-height: 27px;

  padding: 0 8px;

  display: inline-flex;

  align-items: center;

  border: 1px solid var(--border);

  border-radius: var(--radius-pill);

  color: var(--text-muted);

  background: var(--surface-soft);

  font-size: 8px;

  font-weight: 800;
}


/* =========================================================
   FAQ
========================================================= */

.faq-list {
  padding-top: 5px;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-item:last-child {
  border-bottom: 0;
}

.faq-question {
  width: 100%;

  min-height: 62px;

  padding: 0 2px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  color: var(--text-strong);

  text-align: left;

  font-size: 12px;

  font-weight: 800;
}

.faq-question:hover {
  color: var(--primary);
}

.faq-chevron {
  flex: 0 0 auto;

  color: var(--text-faint);

  transition:
    transform var(--transition-fast);
}

.faq-chevron.rotated {
  transform: rotate(180deg);

  color: var(--primary);
}

.faq-answer {
  padding:
    0
    28px
    17px
    2px;
}

.faq-answer p {
  margin: 0;

  color: var(--text-body);

  font-size: 11px;

  line-height: 1.72;
}


/* =========================================================
   HELP SIDE
========================================================= */

.help-side {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 13px;
}


/* =========================================================
   CENTER CONTACT CARD
========================================================= */

.contact-card {
  padding: 21px;

  border: 1px solid var(--border);

  border-radius: var(--radius-lg);

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.contact-card-icon {
  width: 43px;
  height: 43px;

  margin-bottom: 13px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  color: var(--primary);

  background: var(--primary-soft);
}

.contact-card > span {
  display: block;

  color: var(--text-faint);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 0.12em;

  text-transform: uppercase;
}

.contact-card h2 {
  margin: 6px 0 6px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 16px;

  line-height: 1.25;
}

.contact-card > p {
  margin: 0;

  color: var(--text-muted);

  font-size: 10px;

  line-height: 1.6;
}

.contact-detail {
  min-height: 43px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 12px;

  border-top: 1px solid var(--border);
}

.contact-detail:first-of-type {
  margin-top: 13px;
}

.contact-detail span {
  color: var(--text-muted);

  font-size: 9px;
}

.contact-detail strong {
  max-width: 65%;

  color: var(--text-strong);

  font-size: 9px;

  font-weight: 800;

  text-align: right;
}

.contact-primary-button {
  width: 100%;

  min-height: 45px;

  margin-top: 13px;

  display: flex;

  align-items: center;

  justify-content: center;

  gap: 7px;

  border-radius: 11px;

  color: var(--text-on-primary);

  background: var(--primary);

  font-size: 10px;

  font-weight: 800;

  box-shadow:
    0 7px 18px
      color-mix(
        in srgb,
        var(--primary) 16%,
        transparent
      );
}

.contact-primary-button:hover {
  background: var(--primary-strong);

  transform: translateY(-1px);
}

.contact-secondary-row {
  display: grid;

  grid-template-columns: 1fr 1fr;

  gap: 8px;

  margin-top: 8px;
}

.contact-secondary-row button {
  min-height: 39px;

  display: flex;

  align-items: center;

  justify-content: center;

  gap: 5px;

  border: 1px solid var(--border);

  border-radius: 10px;

  color: var(--text-body);

  background: var(--surface-soft);

  font-size: 9px;

  font-weight: 800;
}

.contact-secondary-row button:hover {
  color: var(--primary);

  background: var(--surface-hover);

  border-color: var(--border-strong);
}


/* =========================================================
   CENTER INSTRUCTIONS
========================================================= */

.center-instructions {
  margin-top: 10px;

  padding: 12px;

  border: 1px solid var(--border);

  border-radius: 11px;

  background: var(--surface-soft);
}

.center-instructions > span {
  display: block;

  color: var(--text-faint);

  font-size: 7px;

  font-weight: 800;

  letter-spacing: 0.11em;

  text-transform: uppercase;
}

.center-instructions ul {
  margin: 7px 0 0;

  padding-left: 16px;
}

.center-instructions li {
  margin-bottom: 5px;

  color: var(--text-body);

  font-size: 9px;

  line-height: 1.5;
}

.center-instructions li:last-child {
  margin-bottom: 0;
}


/* =========================================================
   OFFLINE / LOW CONNECTIVITY CARD
========================================================= */

.offline-help-card {
  padding: 20px;

  border: 1px solid
    color-mix(
      in srgb,
      var(--success) 17%,
      var(--border)
    );

  border-radius: var(--radius-lg);

  background:
    linear-gradient(
      135deg,
      color-mix(
        in srgb,
        var(--success) 6%,
        var(--surface)
      ),
      var(--surface)
    );
}

.offline-help-icon {
  width: 42px;
  height: 42px;

  margin-bottom: 13px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  color: var(--success);

  background: var(--success-soft);
}

.offline-help-card > span {
  display: block;

  color: var(--success);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 0.11em;

  text-transform: uppercase;
}

.offline-help-card h2 {
  margin: 7px 0 6px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 15px;

  line-height: 1.35;
}

.offline-help-card p {
  margin: 0;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.65;
}

.offline-help-card button {
  width: 100%;

  min-height: 40px;

  margin-top: 14px;

  padding: 0 11px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  border: 1px solid var(--border);

  border-radius: 10px;

  color: var(--success);

  background: var(--surface);

  font-size: 9px;

  font-weight: 800;
}

.offline-help-card button:hover {
  background: var(--surface-hover);
}


/* =========================================================
   LANGUAGE HELP CARD
========================================================= */

.language-help-card {
  padding: 20px;

  border: 1px solid var(--border);

  border-radius: var(--radius-lg);

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.language-help-icon {
  width: 42px;
  height: 42px;

  margin-bottom: 13px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  color: var(--primary);

  background: var(--primary-soft);
}

.language-help-card > div:nth-child(2) > span {
  display: block;

  color: var(--text-faint);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 0.11em;

  text-transform: uppercase;
}

.language-help-card h3 {
  margin: 6px 0 4px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 14px;

  line-height: 1.35;
}

.language-help-card p {
  margin: 0;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.6;
}

.language-pills {
  margin-top: 13px;

  display: flex;

  flex-wrap: wrap;

  gap: 6px;
}

.language-pills span {
  min-height: 27px;

  padding: 0 8px;

  display: inline-flex;

  align-items: center;

  border: 1px solid var(--border);

  border-radius: 8px;

  color: var(--text-body);

  background: var(--surface-soft);

  font-size: 8px;

  font-weight: 800;
}


/* =========================================================
   SMS MODAL
========================================================= */

.sms-modal-backdrop {
  position: fixed;

  z-index: 500;

  inset: 0;

  padding: 20px;

  display: flex;

  align-items: center;

  justify-content: center;

  background: var(--overlay);

  backdrop-filter: blur(6px);

  -webkit-backdrop-filter: blur(6px);
}

.sms-modal {
  width: min(
    470px,
    100%
  );

  max-height:
    calc(100vh - 40px);

  overflow-y: auto;

  padding: 22px;

  border: 1px solid var(--border);

  border-radius: var(--radius-xl);

  background: var(--surface);

  box-shadow: var(--shadow-lg);
}

.sms-modal-header {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  padding-bottom: 16px;

  border-bottom: 1px solid var(--border);
}

.sms-modal-title {
  min-width: 0;

  display: flex;

  align-items: center;

  gap: 9px;
}

.sms-modal-icon {
  width: 40px;
  height: 40px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  color: var(--success);

  background: var(--success-soft);
}

.sms-modal-title span {
  display: block;

  color: var(--text-faint);

  font-size: 7px;

  font-weight: 800;

  letter-spacing: 0.1em;

  text-transform: uppercase;
}

.sms-modal-title h2 {
  margin: 3px 0 0;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 14px;
}

.sms-modal-close {
  width: 35px;
  height: 35px;

  flex: 0 0 auto;

  display: flex;

  align-items: center;

  justify-content: center;

  border: 1px solid var(--border);

  border-radius: 9px;

  color: var(--text-muted);

  background: var(--surface-soft);
}

.sms-modal-close:hover {
  color: var(--text-strong);

  background: var(--surface-hover);
}

.sms-bubble {
  margin-top: 20px;

  padding: 14px;

  border-radius:
    16px
    16px
    16px
    5px;

  background: var(--success-soft);
}

.sms-bubble-time {
  margin-bottom: 7px;

  color: var(--text-muted);

  font-size: 8px;

  font-weight: 700;

  text-align: right;
}

.sms-bubble p {
  margin: 0;

  color: var(--text-strong);

  font-size: 10px;

  line-height: 1.65;
}

.sms-modal-info {
  margin-top: 14px;

  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 7px;
}

.sms-modal-info > div {
  min-height: 61px;

  padding: 9px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  gap: 5px;

  border: 1px solid var(--border);

  border-radius: 10px;

  color: var(--text-muted);

  background: var(--surface-soft);

  font-size: 8px;

  line-height: 1.35;

  text-align: center;
}

.sms-modal-info svg {
  color: var(--success);
}

.sms-modal-done {
  width: 100%;

  min-height: 44px;

  margin-top: 14px;

  display: flex;

  align-items: center;

  justify-content: center;

  gap: 7px;

  border-radius: 11px;

  color: var(--text-on-primary);

  background: var(--primary);

  font-size: 10px;

  font-weight: 800;
}

.sms-modal-done:hover {
  background: var(--primary-strong);
}


/* =========================================================
   HELP RESPONSIVE
========================================================= */

@media (max-width: 900px) {
  .help-main-grid {
    grid-template-columns: 1fr;
  }

  .help-side {
    display: grid;

    grid-template-columns:
      repeat(2, minmax(0, 1fr));

    align-items: start;
  }

  .language-help-card {
    grid-column: 1 / -1;
  }
}

@media (max-width: 700px) {
  .help-container {
    width: min(
      calc(100% - 24px),
      var(--content-width)
    );

    padding-top: 23px;
  }

  .help-hero {
    align-items: flex-start;
  }

  .help-hero h1 {
    font-size: 32px;
  }

  .help-hero-icon {
    width: 60px;
    height: 60px;
  }

  .help-side {
    display: flex;
  }

  .faq-section {
    padding: 18px;
  }

  .faq-question {
    min-height: 58px;

    font-size: 11px;
  }
}

@media (max-width: 500px) {
  .help-hero-icon {
    display: none;
  }

  .help-hero h1 {
    font-size: 29px;
  }

  .help-hero p {
    font-size: 12px;
  }

  .help-section-heading {
    align-items: flex-start;

    flex-direction: column;
  }

  .contact-secondary-row {
    grid-template-columns: 1fr;
  }

  .sms-modal-info {
    grid-template-columns: 1fr;
  }

  .sms-modal {
    padding: 18px;
  }
}
/* =========================================================
   KRISHISETU
   PART 9 — BRAND + FARMER-WIDE POLISH
========================================================= */


/* =========================================================
   BRAND POLISH
========================================================= */

.app-header-logo,
.admin-shield-icon,
.landing-footer-logo {
  position: relative;

  overflow: hidden;

  background:
    linear-gradient(
      145deg,
      var(--primary),
      var(--primary-strong)
    );
}

.app-header-logo::after,
.admin-shield-icon::after,
.landing-footer-logo::after {
  content: "";

  position: absolute;

  top: -35%;
  right: -25%;

  width: 70%;
  height: 70%;

  border-radius: 50%;

  background:
    rgba(255, 255, 255, 0.13);

  pointer-events: none;
}

.app-header-logo svg {
  position: relative;
  z-index: 1;

  stroke-width: 2;
}


/* =========================================================
   BRAND NAME
========================================================= */

.app-header-name {
  letter-spacing: -0.025em;
}

.app-header-subtitle {
  letter-spacing: 0.01em;
}


/* =========================================================
   IMPROVED PAGE HEADINGS
========================================================= */

.farmer-login-intro h1,
.register-intro h1,
.farmer-welcome h1,
.booking-top-row h1,
.token-heading-row h1,
.help-hero h1,
.landing-hero h1 {
  text-wrap: balance;
}

.farmer-login-intro > p,
.register-intro > p,
.booking-top-row p,
.token-heading-row p,
.help-hero p,
.landing-hero-description {
  max-width: 62ch;
}


/* =========================================================
   IMPORTANT INFORMATION SHOULD STAND OUT
========================================================= */

.home-token,
.token-number {
  text-shadow:
    0 1px 0
      color-mix(
        in srgb,
        var(--primary) 8%,
        transparent
      );
}

.home-detail strong,
.summary-list strong,
.details-list strong,
.contact-detail strong {
  line-height: 1.4;
}


/* =========================================================
   BETTER FORM FIELD HIERARCHY
========================================================= */

.register-field > label,
.booking-form-field > label,
.farmer-login-field label,
.admin-login-field label {
  color: var(--text-strong);

  letter-spacing: 0.01em;
}

.register-input,
.register-select > button,
.select-control,
.quantity-input,
.farmer-login-input,
.admin-login-input {
  background:
    color-mix(
      in srgb,
      var(--surface-soft) 88%,
      var(--surface)
    );
}

.register-input:hover,
.register-select > button:hover:not(:disabled),
.select-control:hover,
.quantity-input:hover,
.farmer-login-input:hover,
.admin-login-input:hover {
  border-color:
    color-mix(
      in srgb,
      var(--primary) 25%,
      var(--border-strong)
    );
}


/* =========================================================
   PRIMARY ACTION EMPHASIS
========================================================= */

.home-primary-action,
.landing-primary-action,
.contact-primary-button,
.sms-modal-done,
.token-new-booking-action,
.app-button:not(.secondary):not(.success):not(.warning):not(.danger) {
  position: relative;

  overflow: hidden;
}

.home-primary-action::after,
.landing-primary-action::after,
.contact-primary-button::after,
.sms-modal-done::after,
.token-new-booking-action::after,
.app-button:not(.secondary):not(.success):not(.warning):not(.danger)::after {
  content: "";

  position: absolute;

  top: 0;
  bottom: 0;
  left: -40%;

  width: 28%;

  transform: skewX(-18deg);

  background:
    rgba(255, 255, 255, 0.09);

  transition:
    left 420ms ease;

  pointer-events: none;
}

.home-primary-action:hover::after,
.landing-primary-action:hover::after,
.contact-primary-button:hover::after,
.sms-modal-done:hover::after,
.token-new-booking-action:hover::after,
.app-button:not(.secondary):not(.success):not(.warning):not(.danger):hover::after {
  left: 120%;
}


/* =========================================================
   FARMER-FRIENDLY TOUCH TARGETS
========================================================= */

.home-primary-action,
.home-secondary-action,
.landing-primary-action,
.landing-secondary-action,
.contact-primary-button,
.sms-modal-done,
.token-home-action,
.token-new-booking-action {
  min-height: 46px;
}

.faq-question {
  min-height: 60px;
}


/* =========================================================
   STATUS VISIBILITY
========================================================= */

.status-badge {
  border-width: 1px;

  box-shadow:
    0 1px 4px
      color-mix(
        in srgb,
        currentColor 7%,
        transparent
      );
}


/* =========================================================
   DARK MODE REFINEMENT
========================================================= */

[data-theme="dark"] .landing-phone,
[data-theme="dark"] .landing-phone-screen,
[data-theme="dark"] .next-booking-card,
[data-theme="dark"] .big-token-card,
[data-theme="dark"] .availability-section,
[data-theme="dark"] .landing-sms-section {
  box-shadow:
    0 20px 55px rgba(0, 0, 0, 0.22);
}

[data-theme="dark"] .location-path-card,
[data-theme="dark"] .center-instructions {
  background:
    color-mix(
      in srgb,
      var(--primary) 5%,
      var(--surface)
    );
}

[data-theme="dark"] .offline-help-card,
[data-theme="dark"] .home-sms-card {
  background:
    linear-gradient(
      135deg,
      color-mix(
        in srgb,
        var(--success) 8%,
        var(--surface)
      ),
      var(--surface)
    );
}

[data-theme="dark"] .status-weighing {
  color: #c8b7f5;

  background: #302652;

  border-color: #493b70;
}


/* =========================================================
   BETTER SMALL TEXT CONTRAST
========================================================= */

.page-eyebrow,
.card-eyebrow,
.register-section-label,
.contact-card > span,
.offline-help-card > span,
.language-help-card > div:nth-child(2) > span,
.token-label,
.sms-token-card > span,
.center-instructions > span {
  line-height: 1.35;
}

.card-eyebrow,
.register-section-label {
  color: var(--text-muted);
}


/* =========================================================
   LINK HOVERS
========================================================= */

.home-feature-card,
.landing-step-card,
.landing-trust-item,
.booking-panel,
.faq-item,
.contact-card,
.offline-help-card,
.language-help-card {
  transition:
    transform var(--transition-fast),
    border-color var(--transition-fast),
    box-shadow var(--transition-normal),
    background-color var(--transition-normal);
}

.home-feature-card:hover,
.landing-step-card:hover,
.landing-trust-item:hover {
  border-color:
    color-mix(
      in srgb,
      var(--primary) 19%,
      var(--border)
    );
}


/* =========================================================
   MOBILE READABILITY
========================================================= */

@media (max-width: 600px) {
  .page-eyebrow {
    font-size: 9px;
  }

  .register-field > label,
  .booking-form-field > label,
  .farmer-login-field label {
    font-size: 11px;
  }

  .register-input input,
  .quantity-input input,
  .farmer-login-input input {
    font-size: 13px;
  }

  .home-detail small,
  .summary-list span,
  .details-list span {
    font-size: 9px;
  }

  .home-detail strong,
  .summary-list strong,
  .details-list strong {
    font-size: 10px;
  }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;

    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
/* =========================================================
   KRISHISETU BRAND MARK
========================================================= */

.krishisetu-logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;

  min-width: 0;
}

.krishisetu-logo-mark {
  flex: 0 0 auto;

  filter:
    drop-shadow(
      0 7px 15px
      color-mix(
        in srgb,
        var(--primary) 18%,
        transparent
      )
    );
}

.krishisetu-logo-wordmark {
  min-width: 0;
}

.krishisetu-logo-wordmark strong,
.krishisetu-logo-wordmark span {
  display: block;
}

.krishisetu-logo-wordmark strong {
  overflow: hidden;

  color: var(--text-strong);

  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 800;

  letter-spacing: -0.025em;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.krishisetu-logo-wordmark span {
  margin-top: 3px;

  overflow: hidden;

  color: var(--text-muted);

  font-size: 8px;
  font-weight: 600;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.krishisetu-logo-compact {
  gap: 0;
}

.krishisetu-logo-compact
  .krishisetu-logo-wordmark {
  display: none;
}
.app-header-brand {
  min-width: 0;

  display: inline-flex;
  align-items: center;
}

.app-header-brand:hover {
  opacity: 0.94;
}

.app-header-logo {
  display: none;
}

.app-header-brand
  .krishisetu-logo-wordmark {
  display: block;
}
/* =========================================================
   CROP SELECTION — LARGER FARMER-FRIENDLY VISUALS
========================================================= */

.register-crop-emoji {
  width: 46px;
  height: 46px;

  flex: 0 0 auto;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 13px;

  background: var(--primary-soft);

  font-size: 26px;
  line-height: 1;
}

.register-select-main .register-crop-emoji {
  width: 43px;
  height: 43px;

  font-size: 24px;
}

.register-dropdown
  > button
  .register-crop-emoji {
  width: 38px;
  height: 38px;

  border-radius: 10px;

  font-size: 21px;
}

.register-crop-emoji + div strong {
  font-size: 11px;
}

.register-crop-emoji + div span {
  font-size: 9px;
}
.register-field:has(.register-crop-emoji)
  .register-select > button {
  min-height: 60px;
}

.register-field:has(.register-crop-emoji)
  .register-dropdown {
  padding: 8px;
}

.register-field:has(.register-crop-emoji)
  .register-dropdown > button {
  min-height: 52px;

  padding: 7px 9px;

  gap: 10px;
}
/* =========================================================
   CROP VISUAL SYSTEM
========================================================= */

.crop-visual {
  width: 48px;
  height: 48px;

  flex: 0 0 auto;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 14px;

  color: var(--primary);
  background: var(--primary-soft);
}

.crop-visual-large {
  width: 60px;
  height: 60px;

  border-radius: 17px;
}

.crop-visual-small {
  width: 36px;
  height: 36px;

  border-radius: 10px;
}

.crop-visual svg {
  display: block;
}

.crop-visual-large svg {
  width: 35px;
  height: 35px;
}

.crop-visual-small svg {
  width: 21px;
  height: 21px;
}

.crop-visual.wheat {
  color: var(--warning);
  background: var(--warning-soft);
}

.crop-visual.paddy {
  color: var(--success);
  background: var(--success-soft);
}

.crop-visual.maize {
  color: var(--primary);
  background: var(--primary-soft);
}

.crop-visual.cotton {
  color: #8064b7;
  background: #f0ebfa;
}
/* =========================================================
   CROP ILLUSTRATION POLISH
========================================================= */

.crop-visual {
  position: relative;

  overflow: hidden;

  border: 1px solid
    color-mix(
      in srgb,
      currentColor 12%,
      var(--border)
    );

  box-shadow:
    inset 0 1px 0
      rgba(255, 255, 255, 0.35);
}

.crop-visual::after {
  content: "";

  position: absolute;

  width: 55%;
  height: 55%;

  top: -20%;
  right: -14%;

  border-radius: 50%;

  background:
    rgba(255, 255, 255, 0.22);
}

.crop-visual-large {
  width: 56px;
  height: 56px;

  border-radius: 16px;
}

.crop-visual-large svg {
  width: 37px;
  height: 37px;
}

.crop-visual-small {
  width: 38px;
  height: 38px;

  border-radius: 11px;
}

.crop-visual-small svg {
  width: 22px;
  height: 22px;
}

.register-select-main
  .crop-visual {
  width: 47px;
  height: 47px;

  border-radius: 13px;
}

.register-select-main
  .crop-visual svg {
  width: 29px;
  height: 29px;
}

.register-dropdown
  .crop-visual {
  width: 41px;
  height: 41px;

  border-radius: 12px;
}

.register-dropdown
  .crop-visual svg {
  width: 25px;
  height: 25px;
}
.krishisetu-logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.krishisetu-logo-mark {
  flex: 0 0 auto;
}

.krishisetu-logo-wordmark {
  min-width: 0;
}

.krishisetu-logo-wordmark strong,
.krishisetu-logo-wordmark span {
  display: block;
}

.krishisetu-logo-wordmark strong {
  color: var(--text-strong);
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 800;
  line-height: 1.1;
}

.krishisetu-logo-wordmark span {
  margin-top: 3px;
  color: var(--text-muted);
  font-size: 8px;
  font-weight: 600;
}

.krishisetu-logo-mark-only {
  gap: 0;
}
/* =========================================================
   ADMIN DASHBOARD
========================================================= */

.admin-dashboard-page {
  min-height: 100vh;
  background: var(--background);
}

.admin-dashboard-container {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  margin: 0 auto;

  padding: 31px 0 65px;
}

.admin-dashboard-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 25px;

  margin-bottom: 23px;
}

.admin-dashboard-heading h1 {
  margin: 8px 0 7px;

  color: var(--text-main);

  font-family: var(--font-heading);

  font-size: 32px;
  line-height: 1.05;

  letter-spacing: -0.045em;
}

.admin-dashboard-heading p {
  max-width: 650px;

  margin: 0;

  color: var(--text-muted);

  font-size: 12px;
  line-height: 1.65;
}

.admin-center-selector {
  min-width: 150px;

  padding: 10px 12px;

  display: flex;
  align-items: center;
  gap: 8px;

  border: 1px solid var(--border);
  border-radius: 12px;

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.admin-center-selector > svg {
  color: var(--primary);
}

.admin-center-selector span,
.admin-center-selector strong {
  display: block;
}

.admin-center-selector span {
  color: var(--text-faint);

  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.admin-center-selector strong {
  margin-top: 2px;

  color: var(--text-strong);

  font-size: 10px;
}


/* STATS */

.admin-stat-grid {
  display: grid;

  grid-template-columns:
    repeat(6, minmax(0, 1fr));

  gap: 9px;

  margin-bottom: 15px;
}

.admin-stat-card {
  min-width: 0;

  min-height: 145px;

  padding: 14px;

  border: 1px solid var(--border);
  border-radius: var(--radius-lg);

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.admin-stat-icon {
  width: 36px;
  height: 36px;

  margin-bottom: 12px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: var(--primary);
  background: var(--primary-soft);
}

.admin-stat-card > span {
  display: block;

  overflow: hidden;

  color: var(--text-muted);

  font-size: 8px;
  font-weight: 700;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-stat-card > strong {
  display: block;

  margin-top: 5px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 27px;
  line-height: 1;
}

.admin-stat-card > small {
  display: block;

  margin-top: 7px;

  color: var(--text-faint);

  font-size: 7px;

  line-height: 1.45;
}

.admin-stat-card.success .admin-stat-icon {
  color: var(--success);
  background: var(--success-soft);
}

.admin-stat-card.warning .admin-stat-icon {
  color: var(--warning);
  background: var(--warning-soft);
}

.admin-stat-card.primary {
  border-color:
    color-mix(
      in srgb,
      var(--primary) 18%,
      var(--border)
    );
}


/* MAIN GRID */

.admin-dashboard-grid {
  display: grid;

  grid-template-columns:
    minmax(0, 1.15fr)
    minmax(300px, 0.65fr);

  gap: 15px;

  margin-bottom: 15px;
}

.admin-queue-card,
.admin-actions-card,
.admin-recent-card {
  padding: 21px;

  border: 1px solid var(--border);
  border-radius: var(--radius-xl);

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.admin-card-heading {
  display: flex;

  align-items: flex-end;
  justify-content: space-between;

  gap: 15px;

  padding-bottom: 15px;

  border-bottom: 1px solid var(--border);
}

.admin-card-heading span {
  display: block;

  color: var(--text-faint);

  font-size: 7px;
  font-weight: 800;

  letter-spacing: 0.11em;
}

.admin-card-heading h2 {
  margin: 5px 0 0;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 17px;
}

.admin-view-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;

  color: var(--primary);

  font-size: 8px;
  font-weight: 800;
}


/* STATUS LIST */

.admin-status-list {
  padding-top: 5px;
}

.admin-status-row {
  min-height: 61px;

  display: flex;
  align-items: center;

  gap: 10px;

  border-bottom: 1px solid var(--border);
}

.admin-status-row:last-child {
  border-bottom: 0;
}

.admin-status-icon {
  width: 34px;
  height: 34px;

  flex: 0 0 auto;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: var(--primary);
  background: var(--primary-soft);
}

.admin-status-row > div:nth-child(2) {
  min-width: 0;
  flex: 1;
}

.admin-status-row > div:nth-child(2) strong,
.admin-status-row > div:nth-child(2) span {
  display: block;
}

.admin-status-row > div:nth-child(2) strong {
  color: var(--text-strong);

  font-size: 10px;
  font-weight: 800;
}

.admin-status-row > div:nth-child(2) span {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 8px;
}

.admin-status-count {
  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 18px;
}


/* ACTIONS */

.admin-action-grid {
  padding-top: 13px;

  display: grid;

  grid-template-columns: 1fr 1fr;

  gap: 8px;
}

.admin-action-button {
  min-height: 91px;

  padding: 11px;

  display: flex;

  flex-direction: column;

  align-items: flex-start;

  justify-content: space-between;

  border: 1px solid var(--border);

  border-radius: 12px;

  color: var(--text-body);

  background: var(--surface-soft);
}

.admin-action-button:hover {
  color: var(--primary);

  border-color:
    color-mix(
      in srgb,
      var(--primary) 22%,
      var(--border)
    );

  background: var(--surface-hover);

  transform: translateY(-2px);
}

.admin-action-button > div {
  width: 31px;
  height: 31px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  color: var(--primary);
  background: var(--primary-soft);
}

.admin-action-button > span {
  color: var(--text-strong);

  font-size: 9px;
  font-weight: 800;
}

.admin-action-button > svg {
  align-self: flex-end;

  color: var(--text-faint);
}


/* RECENT TABLE */

.admin-recent-card {
  overflow: hidden;
}

.admin-booking-table {
  margin-top: 4px;
}

.admin-table-head,
.admin-table-row {
  display: grid;

  grid-template-columns:
    0.5fr
    1fr
    1.25fr
    0.75fr
    0.8fr;

  align-items: center;

  gap: 10px;
}

.admin-table-head {
  min-height: 39px;

  color: var(--text-faint);

  font-size: 7px;
  font-weight: 800;

  letter-spacing: 0.08em;

  text-transform: uppercase;
}

.admin-table-row {
  min-height: 53px;

  border-top: 1px solid var(--border);

  color: var(--text-body);

  font-size: 8px;
}

.admin-table-row:hover {
  color: var(--primary);

  background: var(--surface-hover);
}

.admin-table-row strong {
  color: var(--primary);

  font-size: 10px;
}

.admin-table-row span {
  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;
}

.admin-empty {
  padding: 35px 0;

  color: var(--text-muted);

  font-size: 11px;

  text-align: center;
}


/* ADMIN RESPONSIVE */

@media (max-width: 1100px) {
  .admin-stat-grid {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 800px) {
  .admin-dashboard-heading {
    align-items: flex-start;

    flex-direction: column;
  }

  .admin-center-selector {
    width: 100%;
  }

  .admin-dashboard-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 650px) {
  .admin-dashboard-container {
    width: min(
      calc(100% - 24px),
      var(--content-width)
    );
  }

  .admin-stat-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .admin-queue-card,
  .admin-actions-card,
  .admin-recent-card {
    padding: 17px;
  }

  .admin-table-head {
    display: none;
  }

  .admin-table-row {
    grid-template-columns:
      0.5fr
      1fr
      0.8fr;

    padding: 11px 0;
  }

  .admin-table-row span:nth-child(3) {
    display: none;
  }
}

@media (max-width: 430px) {
  .admin-stat-grid {
    grid-template-columns: 1fr;
  }

  .admin-action-grid {
    grid-template-columns: 1fr;
  }
}
/* =========================================================
   ADMIN LOGIN — FINAL
========================================================= */

.admin-login-page {
  min-height: 100vh;

  background:
    radial-gradient(
      circle at 8% 8%,
      color-mix(
        in srgb,
        var(--primary) 8%,
        transparent
      ),
      transparent 30%
    ),
