.queue-toolbar {
  margin-bottom: 13px;

  display: flex;
  align-items: center;

  justify-content: space-between;

  gap: 12px;
}

.queue-search {
  width: 290px;

  min-height: 43px;

  padding: 0 11px;

  display: flex;
  align-items: center;

  gap: 7px;

  border: 1px solid var(--border);
  border-radius: 11px;

  background: var(--surface);
}

.queue-search svg {
  flex: 0 0 auto;

  color: var(--text-faint);
}

.queue-search input {
  min-width: 0;
  flex: 1;

  border: 0;
  outline: 0;

  color: var(--text-strong);
  background: transparent;

  font-size: 9px;
  font-weight: 600;
}

.queue-filters {
