  justify-content: center;

  gap: 7px;

  border-radius: 11px;

  color: var(--text-on-primary);
  background: var(--primary);

  font-size: 9px;
  font-weight: 800;

  box-shadow:
    0 7px 18px
      color-mix(
        in srgb,
        var(--primary) 18%,
        transparent
      );
}

.queue-process-button:hover {
  background: var(--primary-strong);

  transform: translateY(-1px);
}


/* WORKFLOW */

.queue-workflow {
  margin-top: 18px;

  padding-top: 15px;

  border-top: 1px solid var(--border);
}

.queue-workflow > span {
  display: block;

  margin-bottom: 12px;

  color: var(--text-faint);

  font-size: 7px;
  font-weight: 800;

  letter-spacing: 0.1em;
}

.queue-workflow > div {
  display: grid;

  grid-template-columns:
    repeat(5, 1fr);

  gap: 4px;
}

.workflow-step {
  position: relative;

  display: flex;
  flex-direction: column;

  align-items: center;

  gap: 6px;

  text-align: center;
}

.workflow-step::after {
  content: "";

  position: absolute;

  top: 6px;
  left: 61%;

  width: 78%;
  height: 1px;

  background: var(--border);
}

.workflow-step:last-child::after {
