/* =========================================================
   ADMIN REPORTS
========================================================= */

.admin-reports-page {
  min-height: 100vh;
  background: var(--background);
}

.admin-reports-container {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  margin: 0 auto;
  padding: 30px 0 65px;
}

.admin-reports-top {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;

  margin-bottom: 21px;
}

.admin-reports-top h1 {
  margin: 8px 0 7px;

  color: var(--text-main);

  font-family: var(--font-heading);
  font-size: 32px;
  line-height: 1.05;
  letter-spacing: -0.045em;
}

.admin-reports-top p {
  margin: 0;

  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.6;
}

.report-export-button {
  min-height: 43px;

  padding: 0 12px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;

  border: 1px solid var(--border);
  border-radius: 10px;

  color: var(--text-body);
  background: var(--surface);

  font-size: 9px;
  font-weight: 800;
}

.report-export-button:hover {
  color: var(--primary);
  background: var(--surface-hover);
}

.report-date-bar {
  min-height: 57px;

  padding: 0 14px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  border: 1px solid var(--border);
  border-radius: 13px;

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.report-date-bar > div:first-child {
  display: flex;
  align-items: center;
  gap: 7px;
}

.report-date-bar svg {
  color: var(--primary);
}

.report-date-bar span {
  margin-left: 4px;

  color: var(--text-faint);

  font-size: 7px;
  font-weight: 800;
}

.report-date-bar strong {
  color: var(--text-strong);

  font-size: 9px;
}

.report-period {
  min-height: 29px;

  padding: 0 8px;

  display: inline-flex;
  align-items: center;

  border-radius: 8px;

  color: var(--primary);
  background: var(--primary-soft);

  font-size: 8px;
  font-weight: 800;
}

.report-kpi-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 9px;

  margin-top: 13px;
}

.report-kpi {
  min-height: 145px;

  padding: 14px;

  border: 1px solid var(--border);
  border-radius: var(--radius-lg);

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.report-kpi-icon {
  width: 36px;
  height: 36px;

  margin-bottom: 12px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  color: var(--primary);
  background: var(--primary-soft);
}

.report-kpi.success .report-kpi-icon {
  color: var(--success);
  background: var(--success-soft);
}

.report-kpi > span,
.report-kpi > strong,
.report-kpi > small {
  display: block;
}

.report-kpi > span {
  color: var(--text-muted);

  font-size: 8px;
  font-weight: 700;
}

.report-kpi > strong {
  margin-top: 5px;

  color: var(--text-strong);

  font-family: var(--font-heading);
  font-size: 25px;
  line-height: 1;
}

.report-kpi > small {
  margin-top: 7px;

  color: var(--text-faint);

  font-size: 7px;
}

.report-main-grid {
  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    minmax(0, 1fr);

  gap: 13px;

  margin-top: 13px;
}

.report-card {
  padding: 20px;

  border: 1px solid var(--border);
  border-radius: var(--radius-xl);

  background: var(--surface);

  box-shadow: var(--shadow-sm);
}

.report-card-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;

  gap: 10px;

  padding-bottom: 14px;

  border-bottom: 1px solid var(--border);
}

.report-card-heading span {
  display: block;

  color: var(--text-faint);

  font-size: 7px;
  font-weight: 800;

  letter-spacing: 0.1em;
}

.report-card-heading h2 {
  margin: 5px 0 0;

  color: var(--text-strong);

  font-family: var(--font-heading);
  font-size: 16px;
}

.report-card-heading > svg {
  color: var(--primary);
}

.crop-report-list,
.center-report-list {
  padding-top: 5px;
}

.crop-report-row {
  padding: 13px 0;

  border-bottom: 1px solid var(--border);
}

.crop-report-row:last-child {
  border-bottom: 0;
}

.crop-report-top {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 10px;
}

.crop-report-top > div:first-child {
  min-width: 0;
}

.crop-report-top strong,
.crop-report-top span {
  display: block;
}

.crop-report-top strong {
  color: var(--text-strong);

  font-size: 10px;
  font-weight: 800;
}

.crop-report-top span {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 7px;
}

.crop-report-top > strong {
  color: var(--text-body);
}

.crop-report-bar {
  height: 6px;

  margin-top: 8px;

  overflow: hidden;

  border-radius: var(--radius-pill);

  background: var(--background-soft);
}

.crop-report-bar span {
  display: block;

  height: 100%;

  border-radius: inherit;

  background: var(--primary);
}

.center-report-row {
  min-height: 71px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 13px;

  border-bottom: 1px solid var(--border);
}

.center-report-row:last-child {
  border-bottom: 0;
}

.center-report-row > div:first-child {
  min-width: 0;
}

.center-report-row strong,
.center-report-row span {
  display: block;
}

.center-report-row > div:first-child strong {
  overflow: hidden;

  color: var(--text-strong);

  font-size: 9px;
  font-weight: 800;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.center-report-row > div:first-child span {
  margin-top: 3px;

  color: var(--text-muted);

  font-size: 7px;
}

.center-utilization {
  width: 85px;

  flex: 0 0 auto;

  text-align: right;
}

.center-utilization > strong {
  color: var(--text-strong);

  font-size: 11px;
}

.center-utilization > div {
  height: 5px;

  margin-top: 5px;

  overflow: hidden;

  border-radius: var(--radius-pill);

  background: var(--background-soft);
}

.center-utilization > div span {
  height: 100%;

  border-radius: inherit;

  background: var(--success);
}

.report-summary-card {
  margin-top: 13px;

  padding: 17px;

  display: flex;
  align-items: flex-start;

  gap: 11px;

  border: 1px solid
    color-mix(
      in srgb,
      var(--success) 17%,
      var(--border)
    );

  border-radius: var(--radius-lg);

  background:
    color-mix(
      in srgb,
      var(--success) 5%,
      var(--surface)
    );
}

.report-summary-icon {
  width: 41px;
  height: 41px;

  flex: 0 0 auto;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  color: var(--success);
  background: var(--success-soft);
}

.report-summary-card > div:last-child {
  min-width: 0;
}

.report-summary-card span {
  color: var(--success);

  font-size: 7px;
  font-weight: 800;

  letter-spacing: 0.1em;
}

.report-summary-card h2 {
  margin: 5px 0 4px;

  color: var(--text-strong);

  font-family: var(--font-heading);
  font-size: 14px;
}

.report-summary-card p {
  margin: 0;

  color: var(--text-muted);

  font-size: 8px;
  line-height: 1.55;
}

.report-summary-card p strong {
  color: var(--text-strong);
}

@media (max-width: 850px) {
  .report-kpi-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .report-main-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 600px) {
  .admin-reports-container {
    width: min(
      calc(100% - 24px),
      var(--content-width)
    );
  }

  .admin-reports-top {
    align-items: flex-start;
    flex-direction: column;
  }

  .report-export-button {
    width: 100%;
  }

  .report-date-bar {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;

    padding:
      11px 13px;
  }

  .report-kpi-grid {
    grid-template-columns: 1fr;
  }

  .report-card {
    padding: 17px;
  }
}
/* =========================================================
   FINAL LANDING PAGE
========================================================= */

.landing-page-final {
  min-height: 100vh;

  background:
    radial-gradient(
      circle at 7% 10%,
      color-mix(
        in srgb,
        var(--primary) 8%,
        transparent
      ),
      transparent 31%
    ),
    radial-gradient(
      circle at 92% 80%,
      color-mix(
        in srgb,
        var(--success) 6%,
        transparent
      ),
      transparent 28%
    ),
    var(--background);
}

.landing-header-final {
  min-height: var(--header-height);

  padding:
    10px max(
      20px,
      calc(
        (100vw - var(--content-width)) / 2
      )
    );

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 20px;

  border-bottom: 1px solid var(--border);

  background:
    color-mix(
      in srgb,
      var(--surface) 92%,
      transparent
    );

  backdrop-filter: blur(10px);
}

.landing-brand-final {
  min-width: 0;
}

.landing-admin-link {
  min-height: 37px;

  padding: 0 11px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 6px;

  border: 1px solid var(--border);

  border-radius: 9px;

  color: var(--text-body);

  background: var(--surface);

  font-size: 9px;
  font-weight: 800;
}

.landing-admin-link:hover {
  color: var(--primary);

  background: var(--surface-hover);
}

.landing-main-final {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  margin: 0 auto;

  padding: 62px 0 55px;
}

.landing-hero-final {
  display: grid;

  grid-template-columns:
    minmax(0, 1.1fr)
    minmax(310px, 0.7fr);

  align-items: center;

  gap: 30px;
}

.landing-hero-copy-final h1 {
  max-width: 700px;

  margin: 10px 0 14px;

  color: var(--text-main);

  font-family: var(--font-heading);

  font-size: clamp(
    42px,
    5vw,
    64px
  );

  line-height: 0.98;

  letter-spacing: -0.065em;
}

.landing-hero-copy-final h1 span {
  display: block;

  color: var(--primary);
}

.landing-hero-copy-final > p {
  max-width: 600px;

  margin: 0;

  color: var(--text-body);

  font-size: 13px;

  line-height: 1.75;
}

.landing-primary-actions-final {
  margin-top: 24px;

  display: flex;

  flex-wrap: wrap;

  gap: 8px;
}

.landing-main-button,
.landing-outline-button {
  min-height: 49px;

  padding: 0 14px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 7px;

  border-radius: 11px;

  font-size: 10px;

  font-weight: 800;
}

.landing-main-button {
  color: var(--text-on-primary);

  background: var(--primary);

  box-shadow:
    0 9px 25px
      color-mix(
        in srgb,
        var(--primary) 18%,
        transparent
      );
}

.landing-main-button:hover {
  background: var(--primary-strong);

  transform: translateY(-2px);
}

.landing-outline-button {
  color: var(--text-body);

  border: 1px solid var(--border);

  background: var(--surface);
}

.landing-outline-button:hover {
  color: var(--primary);

  border-color:
    color-mix(
      in srgb,
      var(--primary) 25%,
      var(--border)
    );

  background: var(--surface-hover);
}

.landing-trust-row-final {
  margin-top: 17px;

  display: flex;
  flex-wrap: wrap;

  gap: 12px;
}

.landing-trust-row-final > div {
  display: flex;
  align-items: center;

  gap: 5px;

  color: var(--text-muted);

  font-size: 8px;
}

.landing-trust-row-final svg {
  color: var(--success);
}

.landing-flow-card-final {
  padding: 22px;

  border: 1px solid var(--border);

  border-radius: 22px;

  background: var(--surface);

  box-shadow: var(--shadow-lg);
}

.landing-flow-heading {
  padding-bottom: 14px;

  border-bottom: 1px solid var(--border);
}

.landing-flow-heading span {
  display: block;

  color: var(--text-faint);

  font-size: 7px;

  font-weight: 800;

  letter-spacing: 0.12em;
}

.landing-flow-heading strong {
  display: block;

  margin-top: 5px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 17px;
}

.landing-flow-step-final {
  position: relative;

  min-height: 86px;

  padding: 16px 0;

  display: grid;

  grid-template-columns: 37px minmax(0, 1fr);

  gap: 10px;
}

.landing-flow-step-final:not(.last)::after {
  content: "";

  position: absolute;

  top: 53px;
  left: 17px;

  width: 1px;
  bottom: -2px;

  background: var(--border);
}

.landing-flow-number-final {
  position: relative;
  z-index: 1;

  width: 35px;
  height: 35px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid var(--border);

  border-radius: 11px;

  color: var(--primary);

  background: var(--primary-soft);

  font-family: var(--font-heading);

  font-size: 9px;

  font-weight: 800;
}

.landing-flow-step-final strong {
  color: var(--text-strong);

  font-size: 10px;

  font-weight: 800;
}

.landing-flow-step-final p {
  margin: 4px 0 0;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.5;
}

.landing-role-section-final {
  margin-top: 70px;
}

.landing-role-heading-final {
  margin-bottom: 16px;
}

.landing-role-heading-final > span {
  color: var(--text-faint);

  font-size: 7px;

  font-weight: 800;

  letter-spacing: 0.12em;
}

.landing-role-heading-final h2 {
  margin: 6px 0 0;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 25px;

  letter-spacing: -0.035em;
}

.landing-role-grid-final {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 11px;
}

.landing-role-card-final {
  min-height: 160px;

  padding: 20px;

  display: grid;

  grid-template-columns: 46px minmax(0, 1fr) 18px;

  align-items: start;

  gap: 12px;

  border: 1px solid var(--border);

  border-radius: 18px;

  color: var(--text-body);

  background: var(--surface);

  box-shadow: var(--shadow-sm);

  transition:
    transform var(--transition-fast),
    box-shadow var(--transition-normal),
    border-color var(--transition-fast);
}

.landing-role-card-final:hover {
  transform: translateY(-3px);

  box-shadow: var(--shadow-md);

  border-color:
    color-mix(
      in srgb,
      var(--primary) 20%,
      var(--border)
    );
}

.landing-role-icon-final {
  width: 46px;
  height: 46px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 13px;

  color: var(--primary);

  background: var(--primary-soft);
}

.landing-role-card-final.admin
  .landing-role-icon-final {
  color: var(--success);

  background: var(--success-soft);
}

.landing-role-card-final > div:nth-child(2) {
  min-width: 0;
}

.landing-role-card-final > div:nth-child(2) > span {
  color: var(--text-faint);

  font-size: 7px;

  font-weight: 800;

  letter-spacing: 0.1em;
}

.landing-role-card-final h3 {
  margin: 5px 0 5px;

  color: var(--text-strong);

  font-family: var(--font-heading);

  font-size: 15px;
}

.landing-role-card-final p {
  margin: 0;

  color: var(--text-muted);

  font-size: 9px;

  line-height: 1.6;
}

.landing-role-card-final
  > svg {
  color: var(--text-faint);
}

.landing-footer-final {
  width: min(
    calc(100% - 40px),
    var(--content-width)
  );

  min-height: 50px;

  margin: 0 auto;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 15px;

  border-top: 1px solid var(--border);

  color: var(--text-faint);

  font-size: 8px;
}

@media (max-width: 850px) {
  .landing-main-final {
    padding-top: 42px;
  }

  .landing-hero-final {
    grid-template-columns: 1fr;

    gap: 28px;
  }

  .landing-flow-card-final {
    max-width: 600px;
  }

  .landing-role-section-final {
    margin-top: 45px;
  }
}

@media (max-width: 600px) {
  .landing-header-final {
    padding:
      9px 12px;
  }

  .landing-admin-link {
    font-size: 8px;
  }

  .landing-main-final {
    width: min(
      calc(100% - 24px),
      var(--content-width)
    );

    padding-top: 35px;
  }

  .landing-hero-copy-final h1 {
    font-size: 40px;
  }

  .landing-primary-actions-final {
    flex-direction: column;
  }

  .landing-main-button,
  .landing-outline-button {
    width: 100%;
  }

  .landing-role-grid-final {
    grid-template-columns: 1fr;
  }

  .landing-footer-final {
    width: min(
      calc(100% - 24px),
      var(--content-width)
    );

    align-items: flex-start;

    flex-direction: column;

    justify-content: center;

    padding: 12px 0;
  }
}
/* =========================================================
   FARMER REGISTER — MOBILE NUMBER
========================================================= */

.verified-input {
  min-height: 52px;

  display: flex;
  align-items: center;

  gap: 8px;

  padding: 0 11px;

  border: 1px solid var(--border);

  border-radius: var(--radius-md);

  background: var(--surface-soft);
}

.verified-input > svg {
  flex: 0 0 auto;

  color: var(--text-faint);
}

.verified-country {
  flex: 0 0 auto;

  padding-right: 8px;

  border-right: 1px solid var(--border);

  color: var(--text-muted);

  font-size: 10px;

  font-weight: 800;
}

.verified-input input {
  min-width: 0;

  flex: 1;

  height: 48px;

  padding: 0;

  border: 0;

  outline: 0;

  color: var(--text-strong);

  background: transparent;

  font-size: 12px;

  font-weight: 700;
