.verified-mark {
  min-height: 25px;

  padding: 0 7px;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 4px;

  flex: 0 0 auto;

  border-radius: 7px;

  color: var(--success);

  background: var(--success-soft);

  font-size: 7px;

  font-weight: 800;
}

.register-hint {
  display: block;

  margin-top: 6px;

  color: var(--text-muted);

  font-size: 8px;

  line-height: 1.5;
