  .verified-input {
    min-height: 50px;

    padding: 0 9px;

    gap: 6px;
  }

  .verified-input input {
    font-size: 11px;
  }

  .verified-country {
    padding-right: 6px;

    font-size: 9px;
  }

  .verified-mark {
    padding: 0 5px;

    min-height: 23px;

    font-size: 6px;
  }
}
