  margin: 0;

  color: var(--text-body);

  font-size: 12px;

  line-height: 1.7;
}

.farmer-login-form-new {
  margin-top: 26px;

  display: flex;

  flex-direction: column;

  gap: 11px;
}

.farmer-login-form-new label {
