  gap: 12px;

  border: 1px solid var(--border);

  border-radius: 11px;

  background: var(--surface-soft);
}

.farmer-login-number-confirmed-new span,
.farmer-login-number-confirmed-new strong {
  display: block;
}

.farmer-login-number-confirmed-new span {
  color: var(--text-faint);

  font-size: 7px;

  font-weight: 800;

  letter-spacing: 0.1em;
}

.farmer-login-number-confirmed-new strong {
  margin-top: 4px;

  color: var(--text-strong);

  font-size: 11px;
}

.farmer-login-number-confirmed-new button {
  color: var(--primary);

  font-size: 8px;

  font-weight: 800;
}

.farmer-login-otp-new {
