  font-size: 7px;

  font-weight: 800;

  letter-spacing: 0.11em;
}

.farmer-login-register-new a {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  color: var(--primary);

  font-size: 10px;

  font-weight: 800;
}

.farmer-login-register-new a:hover {
  color: var(--primary-strong);
}


/* FOOTER */

.farmer-login-footer-new {
  margin-top: 18px;

  text-align: center;
}

.farmer-login-footer-new a {
  display: inline-flex;

  align-items: center;

  gap: 5px;

  color: var(--text-muted);

  font-size: 8px;

  font-weight: 700;
}

.farmer-login-footer-new a:hover {
  color: var(--primary);
}


/* MOBILE */

