/* =========================================================
   KRISHISETU LANDING PAGE
========================================================= */

.landing-page {
  min-height: 100vh;
  color: #19344a;
  background:
    linear-gradient(
      180deg,
      #fffdf8 0%,
      #f8fbf4 48%,
      #ffffff 100%
    );
}


/* =========================================================
   HEADER
========================================================= */

.landing-header {
  position: sticky;
  top: 0;
  z-index: 50;

  width: 100%;
  min-height: 82px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 14px 6vw;

  border-bottom: 1px solid rgba(25, 52, 74, 0.08);

  background: rgba(255, 255, 255, 0.92);

  backdrop-filter: blur(16px);
}

.landing-brand {
  display: flex;
  align-items: center;

  color: inherit;
  text-decoration: none;
}

.landing-nav {
  display: flex;
  align-items: center;
  gap: 34px;
}

.landing-nav a {
  color: #567081;
  font-size: 14px;
  font-weight: 700;
  text-decoration: none;
}

.landing-nav a:hover {
  color: #1777b8;
}

.landing-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.landing-nav-farmer,
.landing-nav-admin {
  min-height: 42px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  padding: 0 18px;

  border-radius: 11px;

  font-size: 12px;
  font-weight: 800;
  text-decoration: none;
}

.landing-nav-farmer {
  color: #ffffff;
  background: #166534;
}

.landing-nav-farmer:hover {
  background: #197342;
}

.landing-nav-admin {
  color: #28536b;
  border: 1px solid #d8e4ea;
  background: #ffffff;
}

.landing-nav-admin:hover {
  border-color: #b8d2df;
  background: #f5f9fb;
}

.landing-mobile-menu-button {
  display: none;

  width: 44px;
  height: 44px;

  align-items: center;
  justify-content: center;

  border: 1px solid #d7e3e8;
  border-radius: 11px;

  color: #25485d;
  background: #ffffff;
}

.landing-mobile-menu {
  display: none;
}


/* =========================================================
   HERO
========================================================= */

.landing-hero {
  position: relative;

  min-height: 750px;

  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(420px, 0.95fr);

  align-items: center;
  gap: 5vw;

  padding: 90px 7vw 110px;

  overflow: hidden;

  background:
    radial-gradient(
      circle at 8% 15%,
      rgba(124, 191, 132, 0.18),
      transparent 28%
    ),
    radial-gradient(
      circle at 88% 20%,
      rgba(242, 187, 66, 0.18),
      transparent 30%
    ),
    linear-gradient(
      135deg,
      #fffdf8,
      #f2f8ef
    );
}

.landing-hero::before {
  content: "";

  position: absolute;

  width: 360px;
  height: 360px;

  right: -110px;
  top: -120px;

  border-radius: 50%;

  background: rgba(73, 161, 204, 0.10);
}

.landing-hero-content {
  position: relative;
  z-index: 2;

  max-width: 700px;
}

.landing-hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 9px;

  padding: 9px 13px;

  border: 1px solid rgba(33, 139, 82, 0.24);
  border-radius: 999px;

  color: #237247;
  background: #edf8ef;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.landing-hero-logo {
  margin-top: 34px;
  margin-bottom: 22px;
}

.landing-hero-logo .logo {
  transform-origin: left center;
}

.landing-hero h1 {
  max-width: 710px;

  margin: 0;

  color: #17384e;

  font-family: var(--font-heading);
  font-size: clamp(52px, 6vw, 82px);
  line-height: 0.99;
  letter-spacing: -0.045em;
}

.landing-hero h1 span {
  display: block;
  color: #18804a;
}

.landing-hero-description {
  max-width: 650px;

  margin: 28px 0 0;

  color: #5d7483;

  font-size: 19px;
  line-height: 1.75;
}

.landing-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;

  margin-top: 34px;
}

.landing-primary-button,
.landing-secondary-button {
  min-height: 56px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 11px;

  padding: 0 24px;

  border-radius: 13px;

  font-size: 14px;
  font-weight: 900;
  text-decoration: none;
}

.landing-primary-button {
  color: #ffffff;
  background: #166534;

  box-shadow:
    0 12px 28px rgba(33, 139, 82, 0.20);
}

.landing-primary-button:hover {
  transform: translateY(-2px);
  background: #197342;
}

.landing-secondary-button {
  color: #28536b;
  border: 1px solid #d5e3e8;
  background: #ffffff;
}

.landing-secondary-button:hover {
  border-color: #afcbd8;
  background: #f8fbfd;
}

.landing-hero-points {
  display: flex;
  flex-wrap: wrap;
  gap: 18px 24px;

  margin-top: 29px;
}

.landing-hero-points div {
  display: flex;
  align-items: center;
  gap: 8px;

  color: #607886;

  font-size: 12px;
  font-weight: 800;
}

.landing-hero-points svg {
  color: #166534;
}


/* =========================================================
   HERO VISUAL
========================================================= */

.landing-hero-visual {
  position: relative;

  min-height: 570px;

  display: flex;
  align-items: center;
  justify-content: center;
}

.landing-orbit {
  position: absolute;

  border: 1px dashed rgba(33, 139, 82, 0.23);

  border-radius: 50%;
}

.landing-orbit-one {
  width: 500px;
  height: 500px;

  transform: rotate(9deg);
}

.landing-orbit-two {
  width: 390px;
  height: 390px;

  border-color: rgba(241, 173, 44, 0.28);

  transform: rotate(-13deg);
}

.landing-farm-illustration {
  position: relative;

  width: min(510px, 90%);
  height: 450px;

  overflow: hidden;

  border-radius: 36px;

  background:
    linear-gradient(
      180deg,
      #bfe6f3 0%,
      #e6f4ea 45%,
      #9acb7f 46%,
      #4f9d5b 100%
    );

  box-shadow:
    0 30px 70px rgba(39, 73, 47, 0.19);
}

.landing-sun {
  position: absolute;

  width: 92px;
  height: 92px;

  top: 44px;
  right: 58px;

  border-radius: 50%;

  background: #f2ba42;

  box-shadow:
    0 0 0 17px rgba(242, 186, 66, 0.15);
}

.landing-cloud {
  position: absolute;

  width: 110px;
  height: 27px;

  border-radius: 999px;

  background: rgba(255, 255, 255, 0.78);
}

.landing-cloud::before,
.landing-cloud::after {
  content: "";

  position: absolute;

  border-radius: 50%;

  background: inherit;
}

.landing-cloud::before {
  width: 42px;
  height: 42px;

  left: 20px;
  bottom: 5px;
}

.landing-cloud::after {
  width: 52px;
  height: 52px;

  right: 18px;
  bottom: 2px;
}

.cloud-one {
  top: 90px;
  left: 56px;
}

.cloud-two {
  top: 153px;
  left: 205px;

  transform: scale(0.72);
}

.landing-field {
  position: absolute;

  left: -8%;
  width: 120%;

  border-radius: 50% 50% 0 0;
}

.field-one {
  height: 170px;
  bottom: 80px;

  background: #79ba67;

  transform: rotate(-3deg);
}

.field-two {
  height: 150px;
  bottom: 25px;

  background: #4f9955;

  transform: rotate(4deg);
}

.field-three {
  height: 120px;
  bottom: -48px;

  background: #34784b;
}

.landing-farm-tile {
  position: absolute;

  left: 50%;
  top: 50%;

  transform: translate(-50%, -50%);

  width: 150px;
  height: 150px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;

  border: 2px solid rgba(255, 255, 255, 0.75);
  border-radius: 28px;

  color: #ffffff;

  background: rgba(29, 103, 59, 0.72);

  backdrop-filter: blur(12px);
}

.landing-farm-tile span {
  font-size: 12px;
  font-weight: 900;
