  background: rgba(255, 255, 255, 0.94);

  box-shadow:
    0 14px 32px rgba(35, 65, 51, 0.15);
}

.floating-card-icon {
  width: 39px;
  height: 39px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  color: #ffffff;
}

.landing-floating-card span {
  display: block;

  margin-bottom: 2px;

  color: #778a95;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.landing-floating-card strong {
  color: #24465b;
  font-size: 13px;
}

.card-token {
  top: 78px;
  left: 24px;
}

.card-token .floating-card-icon {
  background: #277db1;
}

.card-weighing {
  right: 20px;
  bottom: 102px;
}

.card-weighing .floating-card-icon {
  background: #dd8d2f;
}

.card-payment {
  left: 36px;
  bottom: 37px;
}

.card-payment .floating-card-icon {
  background: #166534;
}


/* =========================================================
   PURPOSE
========================================================= */

.landing-purpose-section {
  padding: 120px 7vw 110px;
  background: #ffffff;
}

.landing-section-heading {
  max-width: 850px;
}

.landing-section-heading.centered {
  margin: 0 auto;
  text-align: center;
}

.landing-section-heading > span,
.landing-portals-intro > span {
  color: #d68e27;

  font-size: 11px;
  font-weight: 900;

  letter-spacing: 0.13em;
}

.landing-section-heading h2,
.landing-portals-intro h2 {
  margin: 13px 0 0;

  color: #1c3e54;

  font-family: var(--font-heading);
  font-size: clamp(36px, 4vw, 54px);
  line-height: 1.08;
  letter-spacing: -0.025em;
}

.landing-section-heading p,
.landing-portals-intro p {
  max-width: 730px;

  margin: 20px auto 0;

  color: #657b89;

  font-size: 17px;
  line-height: 1.75;
}

.landing-purpose-section > .landing-section-heading p {
  margin-left: 0;
}

.landing-purpose-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);

  gap: 22px;

  margin-top: 54px;
}

.purpose-card {
  min-height: 310px;

  display: flex;
  flex-direction: column;

  padding: 30px;

  border-radius: 25px;

  box-shadow:
    0 18px 50px rgba(31, 63, 77, 0.07);
}

.purpose-card-icon {
  width: 58px;
  height: 58px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-bottom: 30px;

  border-radius: 16px;
}

.purpose-card > span {
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.purpose-card h3 {
  margin: 11px 0 12px;

  color: #203f53;

  font-family: var(--font-heading);
  font-size: 28px;
}

.purpose-card p {
  margin: 0;

  color: #617887;

  font-size: 15px;
  line-height: 1.7;
}

.purpose-green {
  background: #eef8f0;
}

.purpose-green .purpose-card-icon {
  color: #166534;
  background: #d6eedc;
}

.purpose-green > span {
  color: #166534;
}

.purpose-gold {
  background: #fff7e7;
}

.purpose-gold .purpose-card-icon {
  color: #c38217;
  background: #fae6af;
}

.purpose-gold > span {
  color: #c38217;
}

.purpose-blue {
  background: #eef7fc;
}

.purpose-blue .purpose-card-icon {
  color: #2879ab;
  background: #d8ebf7;
}

.purpose-blue > span {
  color: #2879ab;
}


/* =========================================================
   PROCESS
========================================================= */

.landing-process-section {
  padding: 120px 7vw 125px;

  background:
    linear-gradient(
      180deg,
      #f5f9f7 0%,
      #ffffff 100%
    );
}

.landing-process-track {
  max-width: 1450px;

  display: flex;
  align-items: stretch;

  margin: 60px auto 0;
}

.landing-process-step {
  flex: 1;

  min-width: 0;

  padding: 24px 20px;

  border-radius: 20px;

  background: #ffffff;

  box-shadow:
    0 13px 40px rgba(29, 62, 75, 0.07);
}

.process-step-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.process-step-top > span {
  color: #a8b7bf;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.process-step-icon {
  width: 52px;
  height: 52px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 14px;
}

.landing-process-step h3 {
  margin: 22px 0 9px;

  color: #24445a;

  font-family: var(--font-heading);
  font-size: 21px;
}

.landing-process-step p {
  margin: 0;

  color: #708592;

  font-size: 13px;
  line-height: 1.65;
}

.landing-process-step.tone-green .process-step-icon {
  color: #166534;
  background: #e3f4e7;
}

.landing-process-step.tone-gold .process-step-icon {
  color: #cb8b1b;
  background: #fff0c8;
}

.landing-process-step.tone-blue .process-step-icon {
  color: #277bae;
  background: #e0f0f8;
}

.landing-process-step.tone-orange .process-step-icon {
  color: #db7d28;
  background: #ffead8;
}

.landing-process-connector {
  width: 44px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex: 0 0 44px;

  color: #a4b4bd;
}


/* =========================================================
   PORTALS
========================================================= */

.landing-portals-section {
  padding: 125px 7vw;

  background:
    radial-gradient(
      circle at 0% 0%,
      rgba(33, 139, 82, 0.09),
      transparent 30%
    ),
    #fffdf8;
}

.landing-portals-intro {
  max-width: 800px;
}

.landing-portals-intro p {
  margin-left: 0;
}

.landing-portal-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);

  gap: 28px;

  margin-top: 58px;
}

.landing-portal-card {
  position: relative;

  min-height: 570px;

  display: flex;
  flex-direction: column;

  padding: 34px;

  overflow: hidden;

  border-radius: 30px;

  color: inherit;
  text-decoration: none;

  transition:
    transform 180ms ease,
    box-shadow 180ms ease;
}

.landing-portal-card:hover {
  transform: translateY(-6px);

  box-shadow:
    0 24px 60px rgba(29, 61, 76, 0.14);
}

.landing-portal-card.farmer {
  background:
    radial-gradient(
      circle at 87% 10%,
      rgba(255, 211, 97, 0.28),
      transparent 26%
    ),
    linear-gradient(
      145deg,
      #ecf8ef,
      #d8f0de
    );
}

.landing-portal-card.operations {
  background:
    radial-gradient(
      circle at 84% 15%,
      rgba(74, 164, 206, 0.18),
      transparent 27%
    ),
    linear-gradient(
      145deg,
      #eef7fc,
      #dbeaf5
    );
}

.portal-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.portal-number {
  color: rgba(27, 65, 79, 0.35);

  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.13em;
}

.portal-card-icon {
  width: 65px;
  height: 65px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 19px;

  color: #ffffff;
}

.landing-portal-card.farmer
.portal-card-icon {
  background: #166534;
}

.landing-portal-card.operations
.portal-card-icon {
  background: #277bae;
}

.portal-card-content {
  margin-top: 48px;
}

.portal-card-content > span {
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.13em;
}

.landing-portal-card.farmer
.portal-card-content > span {
  color: #166534;
}

.landing-portal-card.operations
.portal-card-content > span {
  color: #277bae;
}

.portal-card-content h3 {
  max-width: 540px;

  margin: 14px 0 18px;

  color: #1e4054;

  font-family: var(--font-heading);
  font-size: clamp(31px, 3vw, 43px);
  line-height: 1.08;
  letter-spacing: -0.025em;
}

.portal-card-content p {
  max-width: 520px;

  margin: 0;

  color: #607985;

  font-size: 16px;
  line-height: 1.72;
}

.portal-card-features {
  display: grid;
  gap: 13px;

  margin-top: 31px;
}

.portal-card-features span {
  display: flex;
  align-items: center;
  gap: 9px;

  color: #456677;

  font-size: 13px;
  font-weight: 800;
}

.portal-card-features svg {
  flex: 0 0 auto;
}

.landing-portal-card.farmer
.portal-card-features svg {
  color: #166534;
}

.landing-portal-card.operations
.portal-card-features svg {
  color: #277bae;
}

.portal-card-action {
  margin-top: auto;
  padding-top: 34px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  color: #1f4459;

  font-size: 14px;
  font-weight: 900;
}

.portal-card-action > div {
  width: 48px;
  height: 48px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  color: #ffffff;
}

.landing-portal-card.farmer
.portal-card-action > div {
  background: #166534;
}

.landing-portal-card.operations
.portal-card-action > div {
  background: #277bae;
}


/* =========================================================
   FEATURES
========================================================= */

.landing-features-section {
  padding: 125px 7vw;

  background: #ffffff;
}

.landing-feature-grid {
  max-width: 1350px;

  display: grid;
  grid-template-columns: repeat(3, 1fr);

  gap: 20px;

  margin: 60px auto 0;
}

.landing-feature-card {
  min-height: 210px;

  display: flex;
  align-items: flex-start;
  gap: 18px;

  padding: 28px;

  border-radius: 22px;

  border: 1px solid rgba(23, 57, 73, 0.08);

  background: #ffffff;

  box-shadow:
    0 11px 35px rgba(31, 61, 75, 0.05);
}

.landing-feature-icon {
  width: 52px;
  height: 52px;

  flex: 0 0 52px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 15px;
}

.landing-feature-card h3 {
  margin: 3px 0 9px;

  color: #27455a;

  font-family: var(--font-heading);
  font-size: 21px;
}

.landing-feature-card p {
  margin: 0;

  color: #728692;

  font-size: 13px;
  line-height: 1.7;
}

.tone-green .landing-feature-icon {
  color: #166534;
  background: #e5f4e8;
}

.tone-blue .landing-feature-icon {
  color: #287caf;
  background: #e1f1f8;
}

.tone-orange .landing-feature-icon {
  color: #dc7d28;
  background: #ffe9d7;
}

.tone-gold .landing-feature-icon {
  color: #c78a1a;
  background: #fff1cd;
}

.tone-purple .landing-feature-icon {
  color: #7f5eb0;
  background: #eee7f8;
}

.tone-teal .landing-feature-icon {
  color: #258e91;
  background: #e1f4f2;
}


/* =========================================================
   FINAL PURPOSE
========================================================= */

.landing-purpose-final-section {
  padding: 75px 7vw 110px;

  background: #ffffff;
}

.landing-purpose-final-card {
  max-width: 1250px;
  min-height: 260px;

  display: flex;
  align-items: center;
  gap: 28px;

  margin: 0 auto;

  padding: 44px;

  border-radius: 30px;

  background:
    linear-gradient(
      135deg,
      #1e7044,
      #285f8c
    );

  box-shadow:
    0 24px 65px rgba(31, 86, 76, 0.18);
}

.landing-purpose-final-mark {
  width: 80px;
  height: 80px;

  flex: 0 0 80px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 23px;

  color: #ffffff;

  background: rgba(255, 255, 255, 0.15);
}

.landing-purpose-final-card span {
  color: #f9d273;

  font-size: 11px;
  font-weight: 900;

  letter-spacing: 0.14em;
}

.landing-purpose-final-card h2 {
  max-width: 780px;

  margin: 11px 0 13px;

  color: #ffffff;

  font-family: var(--font-heading);
  font-size: clamp(31px, 4vw, 49px);
  line-height: 1.08;
}

.landing-purpose-final-card p {
  max-width: 850px;

  margin: 0;

  color: rgba(255, 255, 255, 0.82);

  font-size: 16px;
  line-height: 1.7;
}


/* =========================================================
   FINAL CTA
========================================================= */

.landing-final-cta {
  position: relative;

  min-height: 480px;

  display: flex;
  align-items: center;

  padding: 85px 7vw;

  overflow: hidden;

  background:
    linear-gradient(
      120deg,
      #fff0c9 0%,
      #f8dfae 42%,
      #f0d1b7 100%
    );
}

.landing-final-cta-content {
  position: relative;
  z-index: 2;

  max-width: 810px;
}

.landing-final-cta-content > span {
  color: #a56d17;

  font-size: 11px;
  font-weight: 900;

  letter-spacing: 0.15em;
}

.landing-final-cta h2 {
  margin: 13px 0 13px;

  color: #294254;

  font-family: var(--font-heading);
  font-size: clamp(39px, 5vw, 65px);
  line-height: 1.04;
}

.landing-final-cta p {
  max-width: 720px;

  margin: 0;

  color: #65727b;

  font-size: 17px;
  line-height: 1.72;
}

.landing-final-cta-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 13px;

  margin-top: 30px;
}

.landing-final-farmer-button,
.landing-final-admin-button {
  min-height: 55px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;

  padding: 0 21px;

  border-radius: 13px;

  font-size: 13px;
  font-weight: 900;

  text-decoration: none;
}

.landing-final-farmer-button {
  color: #ffffff;
  background: #166534;
}

.landing-final-admin-button {
  color: #28536b;
  border: 1px solid rgba(40, 83, 107, 0.22);
  background: rgba(255, 255, 255, 0.62);
}

.landing-final-cta-decoration {
  position: absolute;

  right: 5vw;
  top: 50%;

  width: 470px;
  height: 470px;

  transform: translateY(-50%);

  pointer-events: none;
}

.landing-final-cta-decoration div {
  position: absolute;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;
}

.landing-final-cta-decoration div:nth-child(1) {
  width: 210px;
  height: 210px;

  top: 10px;
  right: 24px;

  color: #166534;

  background: rgba(255, 255, 255, 0.40);
}

.landing-final-cta-decoration div:nth-child(2) {
  width: 160px;
  height: 160px;

  left: 20px;
  top: 175px;

  color: #d58526;

  background: rgba(255, 255, 255, 0.34);
}

.landing-final-cta-decoration div:nth-child(3) {
  width: 140px;
  height: 140px;

  right: 38px;
  bottom: 18px;

  color: #327dac;

  background: rgba(255, 255, 255, 0.34);
}


/* =========================================================
   FOOTER
========================================================= */

.landing-footer {
  color: rgba(255, 255, 255, 0.82);

  background: #19394b;
}

.landing-footer-main {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);

  gap: 30px;

  padding: 70px 7vw;
}

.landing-footer-logo {
  display: inline-flex;

  text-decoration: none;
}

.landing-footer-brand p {
  max-width: 320px;

  margin: 20px 0 0;

  color: rgba(255, 255, 255, 0.67);

  font-size: 13px;
  line-height: 1.7;
}

.landing-footer-column {
  display: flex;
  flex-direction: column;
  gap: 13px;
}

.landing-footer-column strong {
  margin-bottom: 6px;

  color: #f4cd69;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.landing-footer-column a {
  color: rgba(255, 255, 255, 0.70);

  font-size: 12px;
  font-weight: 600;

  text-decoration: none;
}

.landing-footer-column a:hover {
  color: #ffffff;
}

.landing-footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  padding: 20px 7vw;

  border-top: 1px solid rgba(255, 255, 255, 0.09);

  color: rgba(255, 255, 255, 0.52);

  font-size: 10px;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1100px) {

  .landing-nav {
    gap: 20px;
  }

  .landing-hero {
    grid-template-columns: 1fr;

    padding-top: 70px;
  }

  .landing-hero-content {
    max-width: 800px;
  }

  .landing-hero-visual {
    min-height: 500px;
  }

  .landing-purpose-grid {
    grid-template-columns: 1fr;
  }

  .purpose-card {
    min-height: 250px;
  }

  .landing-process-track {
    flex-wrap: wrap;
    gap: 16px;
  }

  .landing-process-step {
    flex: 1 1 calc(33.333% - 16px);
  }

  .landing-process-connector {
    display: none;
  }

  .landing-feature-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .landing-final-cta-decoration {
    opacity: 0.45;
    right: -90px;
  }

}


@media (max-width: 800px) {

  .landing-header {
    min-height: 72px;
    padding: 11px 20px;
  }

  .landing-nav,
  .landing-header-actions {
    display: none;
  }

  .landing-mobile-menu-button {
    display: inline-flex;
  }

  .landing-mobile-menu {
    position: fixed;
    z-index: 49;

    top: 72px;
    left: 0;
    right: 0;

    display: flex;
    flex-direction: column;
    gap: 5px;

    padding: 15px 20px 20px;

    border-bottom: 1px solid #dce6eb;

    background: #ffffff;

    box-shadow:
      0 18px 30px rgba(29, 60, 76, 0.10);
  }

  .landing-mobile-menu a {
    padding: 13px 10px;

    color: #31566c;

    font-size: 13px;
    font-weight: 800;

    text-decoration: none;
  }

  .landing-mobile-menu a:last-child {
    margin-top: 4px;

    border-radius: 10px;

    color: #ffffff;
    background: #166534;
    text-align: center;
  }

  .landing-hero {
    min-height: auto;

    padding: 55px 20px 65px;
  }

  .landing-hero h1 {
    font-size: 52px;
  }

  .landing-hero-description {
    font-size: 16px;
  }

  .landing-hero-visual {
    min-height: 450px;
  }

  .landing-farm-illustration {
    height: 390px;
  }

  .landing-orbit {
    display: none;
  }

  .landing-purpose-section,
  .landing-process-section,
  .landing-portals-section,
  .landing-features-section {
    padding: 80px 20px;
  }

  .landing-portal-grid {
    grid-template-columns: 1fr;
  }

  .landing-feature-grid {
    grid-template-columns: 1fr;
  }

  .landing-process-step {
    flex: 1 1 100%;
  }

  .landing-purpose-final-section {
    padding: 50px 20px 80px;
  }

  .landing-purpose-final-card {
    align-items: flex-start;
    flex-direction: column;

    padding: 30px;
  }

  .landing-final-cta {
    min-height: auto;

    padding: 70px 20px;
  }

  .landing-final-cta-decoration {
    display: none;
  }

  .landing-footer-main {
    grid-template-columns: 1fr 1fr;

    gap: 40px;

    padding: 55px 20px;
  }

  .landing-footer-brand {
    grid-column: 1 / -1;
  }

  .landing-footer-bottom {
    flex-direction: column;
    align-items: flex-start;

    padding: 18px 20px;
  }

}


@media (max-width: 520px) {

  .landing-hero h1 {
    font-size: 43px;
  }

  .landing-hero-badge {
    font-size: 9px;
  }

  .landing-hero-points {
    flex-direction: column;
    gap: 10px;
  }

  .landing-hero-actions {
    flex-direction: column;
  }

  .landing-primary-button,
  .landing-secondary-button {
    width: 100%;
  }

  .landing-hero-visual {
    min-height: 380px;
  }

  .landing-farm-illustration {
    width: 100%;
    height: 330px;

    border-radius: 25px;
  }

  .landing-floating-card {
    min-width: 145px;
    padding: 9px;
  }

  .landing-floating-card span {
    font-size: 7px;
  }

  .landing-floating-card strong {
    font-size: 11px;
  }

  .card-token {
    left: 10px;
    top: 43px;
  }

  .card-weighing {
    right: 10px;
    bottom: 76px;
  }

  .card-payment {
    left: 18px;
    bottom: 15px;
  }

  .landing-farm-tile {
    width: 115px;
    height: 115px;
  }

  .landing-farm-tile svg {
    width: 50px;
    height: 50px;
  }

  .landing-portal-card {
    min-height: 520px;

    padding: 25px;
  }

  .portal-card-content h3 {
    font-size: 29px;
  }

  .portal-card-content p {
    font-size: 14px;
  }

  .landing-purpose-final-card h2 {
    font-size: 31px;
  }

  .landing-final-cta h2 {
    font-size: 39px;
