  display: flex;

  background:
    #f4f7f8;

  color: #203f51;
}

.admin-layout-main {
  min-width: 0;

  flex: 1;

  margin-left: 245px;
}

.admin-layout-content {
  width: 100%;

  min-height:
    calc(100vh - 76px);

  padding: 28px;
}


/* =========================================================
   SIDEBAR
========================================================= */

.admin-sidebar {
  position: fixed;

  z-index: 80;

  top: 0;
  left: 0;
  bottom: 0;

  width: 245px;

  display: flex;

  flex-direction: column;

  padding: 18px 13px;

  border-right: 1px solid #fed7aa;

  background:
    #ffffff;

  box-shadow:
    8px 0 30px
    rgba(
      28,
      57,
      72,
      .04
    );
