}

.admin-report-status.orange {
  color: #d1772b;
  background: #fff0e4;
}

.admin-report-status.purple {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-report-status.gold {
  color: #bd7f18;
  background: #fff2d4;
}


/* =========================================================
   TABLE EMPTY / LOADING
========================================================= */

.admin-report-no-records {
  min-height: 260px;

  display: flex;

  align-items: center;
  justify-content: center;

  flex-direction: column;

  gap: 6px;

  padding: 30px;

  color: #9caab0;

  text-align: center;
}

.admin-report-no-records strong {
  color: #5e7784;

  font-size: 9px;
}

.admin-report-no-records span {
  color: #8c9ba2;

  font-size: 7px;

  line-height: 1.5;
}

.admin-report-loading {
  min-width: 860px;
}

.admin-report-skeleton-row {
  min-height: 67px;

  display: grid;

  grid-template-columns:
    repeat(6, 1fr);

  gap: 10px;

  align-items: center;

  padding:
    0
    18px;

  border-bottom:
    1px solid
    #edf1f3;
}

.admin-report-skeleton-row span {
  height: 8px;

  border-radius: 99px;

  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );

  background-size:
    200% 100%;

  animation:
    adminReportSkeleton 1.2s infinite;
}

@keyframes adminReportSkeleton {

  0% {
    background-position:
      200% 0;
  }

  100% {
    background-position:
      -200% 0;
  }

}

.admin-report-table-footer {
  min-height: 42px;

  display: flex;

  align-items: center;

  padding:
    0
    18px;

  color: #93a1a7;

  font-size: 6px;
