/* =========================================================
   FOOTER
========================================================= */

.admin-reports-footer {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 12px;

  margin-top: 12px;

  padding:
    3px
    2px
    10px;

  color: #8d9ca2;

  font-size: 6px;
}

.admin-reports-footer > div {
  display: inline-flex;

  align-items: center;

  gap: 5px;
}

.admin-reports-footer svg {
  color: #ea580c;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1250px) {

  .admin-report-kpi-grid {
    grid-template-columns:
      repeat(3, 1fr);
  }

}


@media (max-width: 1000px) {

  .admin-reports-hero {
    flex-direction: column;
  }

  .admin-reports-hero-actions {
    width: 100%;
  }

  .admin-report-data-chip,
  .admin-report-refresh,
  .admin-report-export {
    flex: 1;
  }

  .admin-reports-analytics-grid {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 800px) {

  .admin-reports-filter-panel {
    flex-wrap: wrap;
  }

  .admin-reports-search {
    flex-basis: 100%;
  }

  .admin-report-filter {
    flex: 1;
  }

  .admin-report-filter select {
    min-width: 75px;
  }

  .admin-reports-clear {
    flex: 0 0 auto;
  }

}


@media (max-width: 600px) {

  .admin-report-kpi-grid {
    grid-template-columns:
      1fr 1fr;
  }

  .admin-report-kpi {
    padding: 10px;
  }

  .admin-report-kpi-icon {
    width: 32px;
    height: 32px;
    flex-basis: 32px;
  }

  .admin-report-kpi strong {
    font-size: 15px;
  }

  .admin-reports-hero h2 {
    font-size: 30px;
  }

  .admin-reports-hero-actions {
    flex-wrap: wrap;
  }

  .admin-report-data-chip,
  .admin-report-refresh,
  .admin-report-export {
    flex: 1 1 30%;
  }

}


@media (max-width: 450px) {

  .admin-report-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .admin-report-filter {
    flex-basis: 100%;
  }

  .admin-reports-clear {
    width: 100%;
  }

}
/* =========================================================
   ADMIN FARMERS
========================================================= */

.admin-farmers-page {
  width: 100%;
  max-width: 1550px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-farmers-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-farmers-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-farmers-hero p {
  max-width: 740px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-farmers-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-farmers-live {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #cfe4d5;
  border-radius: 999px;
  color: #166534;
  background: #eff9f1;
  font-size: 7px;
  font-weight: 900;
}

.admin-farmers-refresh {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #5d7887;
  background: #ffffff;
