}


/* =========================================================
   ERROR
========================================================= */

.admin-farmers-error {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 13px;
  padding: 12px 14px;
  border: 1px solid #efd0ca;
  border-radius: 10px;
  color: #b15348;
  background: #fff4f2;
}

.admin-farmers-error > svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-farmers-error > div {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-farmers-error strong {
  font-size: 8px;
}

.admin-farmers-error span {
  color: #8e7772;
  font-size: 7px;
  line-height: 1.5;
}

.admin-farmers-error button {
  border: 0;
  color: #a64f44;
  background: transparent;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   KPI
========================================================= */

.admin-farmer-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
