  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-farmer-kpi.blue
.admin-farmer-kpi-icon {
  color: #ea580c;
  background: #ffedd5;
}

.admin-farmer-kpi.green
.admin-farmer-kpi-icon {
  color: #166534;
  background: #e4f4e8;
}

.admin-farmer-kpi.purple
.admin-farmer-kpi-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-farmer-kpi.gold
