  color: #c3871c;
  background: #fff0ce;
}

.admin-farmer-kpi > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-farmer-kpi strong {
  overflow: hidden;
  color: #304f61;
  font-family: var(--font-heading);
  font-size: 20px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-farmer-kpi strong small {
  color: #8b9aa1;
  font-family: inherit;
  font-size: 7px;
}

.admin-farmer-kpi span {
  color: #7b8f98;
  font-size: 7px;
}


/* =========================================================
   FILTER PANEL
========================================================= */

.admin-farmers-filter-panel {
  display: flex;
  align-items: center;
  gap: 7px;
