}

.admin-farmers-search input {
  width: 100%;
  min-width: 0;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #315165;
  background: transparent;
  font-size: 8px;
}

.admin-farmers-search input::placeholder {
  color: #adb9bf;
}

.admin-farmers-filter {
  height: 36px;
  display: flex;
  align-items: center;
