.admin-farmers-clear {
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 10px;
  border: 0;
  border-radius: 8px;
  color: #a65a50;
  background: #fff3f1;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}


/* =========================================================
   TABLE PANEL
========================================================= */

.admin-farmers-table-panel {
  overflow: hidden;
  border: 1px solid #fed7aa;
  border-radius: 17px;
  background: #ffffff;
  box-shadow:
    0 10px 28px
    rgba(30, 62, 77, .04);
}

.admin-farmers-table-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  padding: 18px 18px 14px;
}

.admin-farmers-table-header > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-farmers-table-header h3 {
  margin: 0;
  color: #2f5063;
  font-family: var(--font-heading);
  font-size: 18px;
}

.admin-farmers-table-header > span {
  color: #95a3a9;
