   TABLE
========================================================= */

.admin-farmers-table {
  width: 100%;
  overflow-x: auto;
}

.admin-farmers-table-head,
.admin-farmer-row {
  min-width: 1050px;
  display: grid;

  grid-template-columns:
    1.3fr
    1fr
    1.25fr
    1fr
    .75fr
    .8fr;

  column-gap: 11px;
  align-items: center;
  padding: 0 18px;
}

.admin-farmers-table-head {
  min-height: 34px;
  border-top: 1px solid #edf1f3;
  border-bottom: 1px solid #e7edef;
