  background: #fff7ed;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.admin-farmer-row {
  min-height: 76px;
  border-bottom: 1px solid #edf1f3;
  transition: background .13s ease;
}

.admin-farmer-row:hover {
  background: #fbfcfd;
}


/* =========================================================
   FARMER CELL
========================================================= */

.admin-farmer-main-cell,
.admin-farmer-contact-cell,
.admin-farmer-location-cell,
