  height: 36px;
  flex: 0 0 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: #718795;
  background: #edf2f4;
}

.admin-farmer-main-cell > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-farmer-main-cell strong {
  overflow: hidden;
  color: #3d5a6b;
  font-size: 8px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-farmer-main-cell span {
  overflow: hidden;
  color: #9aa7ad;
  font-size: 6px;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   CONTACT
========================================================= */

.admin-farmer-contact-cell > div {
  display: flex;
  align-items: center;
  gap: 5px;
}

.admin-farmer-contact-cell svg {
  color: #7c97a5;
}

.admin-farmer-contact-cell span {
  color: #587381;
  font-size: 7px;
}


/* =========================================================
   LOCATION
========================================================= */

.admin-farmer-location-cell {
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
}

.admin-farmer-location-cell strong {
  overflow: hidden;
  color: #4c6877;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-farmer-location-cell span {
  overflow: hidden;
  color: #8b9ba2;
  font-size: 6px;
  white-space: nowrap;
  text-overflow: ellipsis;
