.admin-procurement-kpi.blue .admin-procurement-kpi-icon {
  color: #ea580c;
  background: #ffedd5;
}

.admin-procurement-kpi.green .admin-procurement-kpi-icon {
  color: #166534;
  background: #e4f4e8;
}

.admin-procurement-kpi.gold .admin-procurement-kpi-icon {
  color: #be811a;
  background: #fff0ce;
