.admin-procurement-kpi.purple .admin-procurement-kpi-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-procurement-kpi > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-procurement-kpi strong {
