}

.admin-procurement-kpi strong small {
  color: #8a999f;
  font-size: 7px;
}

.admin-procurement-kpi span {
  color: #7b8f98;
  font-size: 6px;
}

.admin-procurement-filter-panel {
  display: flex;
  align-items: center;
  gap: 9px;
