  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-procurement-booking strong {
  color: #ea580c;
  font-size: 7px;
}

.admin-procurement-booking span,
.admin-procurement-farmer span,
.admin-procurement-quantity span,
.admin-procurement-rate span {
  color: #8b9aa1;
  font-size: 6px;
}

.admin-procurement-farmer strong,
.admin-procurement-quantity strong,
.admin-procurement-rate strong {
  overflow: hidden;
  color: #526d7b;
  font-size: 7px;
