  gap: 5px;
  color: #557280;
}

.admin-procurement-crop svg {
  flex: 0 0 auto;
  color: #166534;
}

.admin-procurement-crop span {
  overflow: hidden;
  font-size: 7px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.admin-procurement-quality,
.admin-procurement-status {
  width: fit-content;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 7px;
  border-radius: 999px;
  font-size: 5px;
  font-weight: 900;
}

.admin-procurement-quality.good {
  color: #166534;
  background: #eaf7ed;
}

.admin-procurement-quality.average {
  color: #bd811a;
  background: #fff2d4;
}

.admin-procurement-quality.poor {
  color: #b15348;
  background: #fff0ed;
}

.admin-procurement-quality:not(.good):not(.average):not(.poor) {
  color: #839299;
  background: #f1f4f5;
}

.admin-procurement-amount strong {
  color: #456474;
  font-family: var(--font-heading);
  font-size: 10px;
}

.admin-procurement-status > span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}

.admin-procurement-status.paid {
  color: #166534;
  background: #eaf7ed;
}

.admin-procurement-status.paid > span {
  background: #166534;
}

.admin-procurement-status.pending {
  color: #bd811a;
  background: #fff2d4;
}

.admin-procurement-status.pending > span {
  background: #bd811a;
}

.admin-procurement-empty {
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  color: #97a6ac;
}

.admin-procurement-empty strong {
  color: #5d7582;
  font-size: 9px;
}

.admin-procurement-empty span {
  color: #8b9aa1;
  font-size: 7px;
}

.admin-procurement-loading {
  min-width: 1120px;
}

.admin-procurement-skeleton {
  min-height: 73px;
  display: grid;
  grid-template-columns:
    1fr
    1.25fr
    .9fr
    .95fr
    .8fr
    .8fr
    .95fr
    .9fr;
  gap: 9px;
  align-items: center;
  padding: 0 18px;
  border-bottom: 1px solid #edf1f3;
}

.admin-procurement-skeleton span {
  height: 8px;
  border-radius: 99px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation: adminProcurementSkeleton 1.2s infinite;
}

@keyframes adminProcurementSkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}

.admin-procurement-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 2px;
  color: #8d9ca2;
  font-size: 6px;
}

@media (max-width: 1000px) {

  .admin-procurement-kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }

}

@media (max-width: 700px) {

  .admin-procurement-hero {
    flex-direction: column;
  }

  .admin-procurement-actions {
    width: 100%;
  }

  .admin-procurement-live,
  .admin-procurement-refresh {
    flex: 1;
  }

}

@media (max-width: 520px) {

  .admin-procurement-kpi-grid {
    grid-template-columns: 1fr;
  }

}
/* =========================================================
   ADMIN ACTIVITY LOG
========================================================= */

.admin-activity-page {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
}


/* =========================================================
   HERO
========================================================= */

.admin-activity-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.admin-activity-hero h2 {
  margin: 6px 0 7px;
  color: #203f52;
  font-family: var(--font-heading);
  font-size: clamp(29px, 3vw, 41px);
  line-height: 1;
  letter-spacing: -.035em;
}

.admin-activity-hero p {
  max-width: 780px;
  margin: 0;
  color: #7c909a;
  font-size: 10px;
  line-height: 1.65;
}

.admin-activity-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-activity-live {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #cfe1e7;
  border-radius: 999px;
  color: #ea580c;
  background: #edf7fa;
  font-size: 7px;
  font-weight: 900;
}

.admin-activity-refresh {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #5d7887;
  background: #ffffff;
  cursor: pointer;
  font-size: 7px;
  font-weight: 900;
}

.admin-activity-refresh:hover:not(:disabled) {
  color: #ea580c;
  border-color: #bad0da;
}

.admin-activity-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}


/* =========================================================
   FEEDBACK
========================================================= */

.admin-activity-feedback {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 13px;
  padding: 11px 13px;
  border-radius: 10px;
  font-size: 7px;
}

.admin-activity-feedback.error {
  border: 1px solid #efd0ca;
  color: #b15348;
  background: #fff4f2;
}

.admin-activity-feedback.success {
  border: 1px solid #cfe4d5;
  color: #2d7950;
  background: #eef9f1;
}

.admin-activity-feedback > span {
  min-width: 0;
  flex: 1;
}

.admin-activity-feedback button {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2px;
  border: 0;
  background: transparent;
  cursor: pointer;
}

.admin-activity-feedback.error button {
  color: #b15348;
}

.admin-activity-feedback.success button {
  color: #2d7950;
}


/* =========================================================
   KPI GRID
========================================================= */

.admin-activity-kpi-grid {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 14px;
}

.admin-activity-kpi {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 13px;
  border: 1px solid #fed7aa;
  border-radius: 14px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-activity-kpi-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-activity-kpi.blue
.admin-activity-kpi-icon {
  color: #ea580c;
  background: #ffedd5;
}

.admin-activity-kpi.green
.admin-activity-kpi-icon {
  color: #166534;
  background: #e4f4e8;
}

.admin-activity-kpi.purple
.admin-activity-kpi-icon {
  color: #8064a9;
  background: #eee9f7;
}

.admin-activity-kpi.gold
.admin-activity-kpi-icon {
  color: #be811a;
  background: #fff0ce;
}

.admin-activity-kpi > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-activity-kpi strong {
  color: #304f61;
  font-family: var(--font-heading);
  font-size: 18px;
}

.admin-activity-kpi span {
  color: #7b8f98;
  font-size: 6px;
}


/* =========================================================
   FILTERS
========================================================= */

.admin-activity-filter-panel {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 14px;
  padding: 9px;
  border: 1px solid #fed7aa;
  border-radius: 12px;
  background: #ffffff;
  box-shadow:
    0 7px 22px
    rgba(30, 62, 77, .03);
}

.admin-activity-search {
  flex: 1;
  min-width: 230px;
  height: 36px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  color: #84969e;
  background: #fff7ed;
}

.admin-activity-search:focus-within {
  border-color: #a9c5d0;
  background: #ffffff;
  box-shadow:
    0 0 0 3px
    rgba(39, 124, 172, .05);
}

.admin-activity-search input {
  width: 100%;
  min-width: 0;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #315165;
  background: transparent;
  font-size: 8px;
}

.admin-activity-search input::placeholder {
  color: #adb9bf;
}

.admin-activity-filter-select {
  height: 36px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 8px;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  background: #fff7ed;
}

.admin-activity-filter-select svg {
  color: #84969e;
}

.admin-activity-filter-select select {
  min-width: 112px;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: #587381;
  background: transparent;
  cursor: pointer;
  font-family: inherit;
  font-size: 7px;
  font-weight: 800;
}

.admin-activity-clear {
  height: 36px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 0 9px;
  border: 1px solid #e1d4d1;
  border-radius: 8px;
  color: #a1594f;
  background: #fff9f8;
  cursor: pointer;
  font-size: 6px;
  font-weight: 900;
}

.admin-activity-clear:hover {
  border-color: #d6b8b2;
  background: #fff4f2;
}


/* =========================================================
   PANEL
========================================================= */

.admin-activity-panel {
  overflow: hidden;
  border: 1px solid #fed7aa;
  border-radius: 16px;
  background: #ffffff;
  box-shadow:
    0 9px 26px
    rgba(30, 62, 77, .035);
}

.admin-activity-panel-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  padding: 17px 18px 14px;
  border-bottom: 1px solid #edf1f3;
}

.admin-activity-panel-header > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-activity-panel-header h3 {
  margin: 0;
  color: #3c5b6c;
  font-family: var(--font-heading);
  font-size: 15px;
}

.admin-activity-panel-header > span {
  color: #95a3a9;
  font-size: 6px;
}


/* =========================================================
   TIMELINE
========================================================= */

.admin-activity-timeline {
  padding: 5px 18px 18px;
}

.admin-activity-event {
  position: relative;
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  gap: 10px;
}

.admin-activity-event-line {
  position: relative;
  display: flex;
  justify-content: center;
}

.admin-activity-event-line::after {
  content: "";
  position: absolute;
  top: 35px;
  bottom: -8px;
  width: 1px;
  background: #dfe8eb;
}

.admin-activity-event:last-child
.admin-activity-event-line::after {
  display: none;
}

.admin-activity-event-dot {
  position: relative;
  z-index: 1;
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 10px;
  border: 2px solid #ffffff;
  border-radius: 50%;
  box-shadow:
    0 0 0 1px #fed7aa;
}

.admin-activity-event-dot.blue {
  color: #ea580c;
  background: #e7f3f8;
}

.admin-activity-event-dot.orange {
  color: #d1772b;
  background: #fff0e4;
}

.admin-activity-event-dot.purple {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-activity-event-dot.gold {
  color: #be811a;
  background: #fff2d5;
}

.admin-activity-event-dot.green {
  color: #166534;
  background: #eaf7ed;
}

.admin-activity-event-dot.teal {
  color: #288e91;
  background: #e3f5f4;
}


/* =========================================================
   EVENT BODY
========================================================= */

.admin-activity-event-body {
  min-width: 0;
  margin: 7px 0;
  padding: 12px 13px;
  border: 1px solid #e3eaed;
  border-radius: 11px;
  background: #fbfcfd;
}

.admin-activity-event-body:hover {
  border-color: #d5e1e6;
  background: #fff7ed;
}

.admin-activity-event-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
}

.admin-activity-event-top > div {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 7px;
}

.admin-activity-status {
  display: inline-flex;
  align-items: center;
  padding: 5px 7px;
  border-radius: 999px;
  font-size: 5px;
  font-weight: 900;
  white-space: nowrap;
}

.admin-activity-status.blue {
  color: #ea580c;
  background: #e7f3f8;
}

.admin-activity-status.orange {
  color: #d1772b;
  background: #fff0e4;
}

.admin-activity-status.purple {
  color: #8064a9;
  background: #f0ebf7;
}

.admin-activity-status.gold {
  color: #be811a;
  background: #fff2d5;
}

.admin-activity-status.green {
  color: #166534;
  background: #eaf7ed;
}

.admin-activity-status.teal {
  color: #288e91;
  background: #e3f5f4;
}

.admin-activity-event-top strong {
  color: #4f6977;
  font-size: 7px;
}

.admin-activity-event-top time {
  flex: 0 0 auto;
  color: #97a5aa;
  font-size: 6px;
}

.admin-activity-event-content {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-activity-event-content > strong {
  color: #496574;
  font-family: var(--font-heading);
  font-size: 10px;
}

.admin-activity-event-content p {
  margin: 0;
  color: #82949c;
  font-size: 7px;
  line-height: 1.55;
}


/* =========================================================
   META
========================================================= */

.admin-activity-event-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 10px;
}

.admin-activity-event-meta span {
  padding: 4px 6px;
  border: 1px solid #e1e8eb;
  border-radius: 6px;
  color: #81929a;
  background: #ffffff;
  font-size: 5px;
}

.admin-activity-changes {
  margin-top: 9px;
  padding-top: 9px;
  border-top: 1px dashed #dfe7ea;
}

.admin-activity-changes > span {
  display: block;
  margin-bottom: 4px;
  color: #98a6ab;
  font-size: 5px;
  font-weight: 900;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.admin-activity-changes > div {
  color: #67808d;
  font-size: 6px;
  line-height: 1.5;
}


/* =========================================================
   EMPTY
========================================================= */

.admin-activity-empty {
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  padding: 30px;
  color: #98a7ad;
  text-align: center;
}

.admin-activity-empty strong {
  color: #5c7582;
  font-size: 10px;
}

.admin-activity-empty span {
  max-width: 360px;
  color: #8b9ba2;
  font-size: 7px;
  line-height: 1.5;
}


/* =========================================================
   LOADING
========================================================= */

.admin-activity-loading {
  padding: 8px 18px 18px;
}

.admin-activity-loading-row {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  gap: 10px;
  min-height: 105px;
}

.admin-activity-loading-row > span {
  width: 30px;
  height: 30px;
  margin-top: 14px;
  border-radius: 50%;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation: adminActivitySkeleton 1.2s infinite;
}

.admin-activity-loading-row > div {
  margin-top: 8px;
  padding: 12px;
  border: 1px solid #e6ecef;
  border-radius: 11px;
}

.admin-activity-loading-row > div span {
  display: block;
  height: 8px;
  margin-bottom: 9px;
  border-radius: 99px;
  background:
    linear-gradient(
      90deg,
      #edf2f4,
      #f8fafb,
      #edf2f4
    );
  background-size: 200% 100%;
  animation: adminActivitySkeleton 1.2s infinite;
}

.admin-activity-loading-row > div span:nth-child(1) {
  width: 26%;
}

.admin-activity-loading-row > div span:nth-child(2) {
  width: 55%;
}

.admin-activity-loading-row > div span:nth-child(3) {
  width: 82%;
}

.admin-activity-loading-row > div span:nth-child(4) {
  width: 64%;
}

@keyframes adminActivitySkeleton {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


/* =========================================================
   FOOTER
========================================================= */

.admin-activity-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 2px;
  color: #8d9ca2;
  font-size: 6px;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 900px) {

  .admin-activity-kpi-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-activity-filter-panel {
    flex-wrap: wrap;
  }

  .admin-activity-search {
    flex-basis: 100%;
  }

  .admin-activity-filter-select {
    flex: 1;
  }

}


@media (max-width: 650px) {

  .admin-activity-hero {
    flex-direction: column;
  }

  .admin-activity-actions {
    width: 100%;
  }

  .admin-activity-live,
  .admin-activity-refresh {
    flex: 1;
    justify-content: center;
  }

  .admin-activity-event-top {
    align-items: flex-start;
    flex-direction: column;
    gap: 6px;
  }

  .admin-activity-filter-select {
    min-width: 0;
  }

  .admin-activity-filter-select select {
    min-width: 0;
  }

}


@media (max-width: 480px) {

  .admin-activity-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .admin-activity-filter-panel {
    flex-direction: column;
  }

  .admin-activity-search,
  .admin-activity-filter-select,
  .admin-activity-clear {
    width: 100%;
    flex-basis: auto;
  }

  .admin-activity-filter-select select {
    flex: 1;
  }

  .admin-activity-timeline {
    padding-left: 10px;
    padding-right: 10px;
  }

  .admin-activity-event {
    grid-template-columns: 31px minmax(0, 1fr);
    gap: 7px;
  }

  .admin-activity-event-dot {
    width: 27px;
    height: 27px;
    flex-basis: 27px;
  }

  .admin-activity-event-line::after {
    top: 32px;
  }

  .admin-activity-event-body {
    padding: 10px;
  }

  .admin-activity-footer {
    align-items: flex-start;
    flex-direction: column;
  }

}
/* =========================================================
   ADMIN HEADER LANGUAGE
========================================================= */

