  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-language-selector {
  min-height: 34px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 9px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #718792;
  background: #ffffff;
}

.admin-language-selector svg {
  flex: 0 0 auto;
  color: #ea580c;
}

.admin-language-selector select {
  min-width: 84px;
  height: 32px;
  padding: 0;
  border: 0;
  outline: 0;
  color: #587381;
  background: transparent;
  cursor: pointer;
  font-family: inherit;
  font-size: 7px;
  font-weight: 800;
}

.admin-language-selector select:focus {
  outline: none;
}


.admin-header-refresh {
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #d9e4e8;
  border-radius: 8px;
  color: #5d7887;
  background: #ffffff;
  cursor: pointer;
  font-family: inherit;
  font-size: 7px;
  font-weight: 900;
}

.admin-header-refresh:hover:not(:disabled) {
  color: #ea580c;
  border-color: #b9d0da;
  background: #fff7ed;
}

.admin-header-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}


@media (max-width: 650px) {

  .admin-header-actions {
    gap: 5px;
  }

  .admin-language-selector {
    padding: 0 7px;
  }

  .admin-language-selector select {
    min-width: 66px;
  }

  .admin-header-refresh span {
    display: none;
  }

  .admin-header-refresh {
    width: 34px;
    padding: 0;
  }

