}

.feature-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.feature-card-top > svg {
  color: #a8b4b8;
}

.feature-icon {
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.booking-feature .feature-icon {
  color: #2f819f;
  background: #e6f4f7;
}

.status-feature .feature-icon {
  color: #7967a0;
  background: #efeafa;
}

.help-feature .feature-icon {
  color: #b17b2c;
  background: #fff2d9;
}

.home-feature-card h2 {
  margin: 14px 0 6px;
  color: #486572;
  font-family: var(--font-heading);
  font-size: 12px;
}

.home-feature-card p {
  margin: 0;
  color: #8a9aa1;
  font-size: 7px;
  line-height: 1.55;
}


/* =========================================================
   GENERIC SECTION
========================================================= */

.home-dashboard-section,
.home-month-summary-card,
.home-center-card,
.home-arrival-check-card,
.farmer-progress-card {
  margin-bottom: 14px;
  padding: 17px;
  border: 1px solid #dfe8eb;
  border-radius: 15px;
  background: #ffffff;
  box-shadow: 0 8px 25px rgba(35, 73, 92, .028);
}

.home-section-heading,
.farmer-progress-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.home-section-heading > svg,
.farmer-progress-heading > svg {
  color: #88a0aa;
}

.home-section-heading h2,
.farmer-progress-heading h2 {
  margin: 4px 0 4px;
  color: #486572;
  font-family: var(--font-heading);
  font-size: 16px;
}

.home-section-heading p,
.farmer-progress-heading p {
  margin: 0;
  color: #91a0a6;
  font-size: 6px;
  line-height: 1.5;
}


/* =========================================================
   MONTH SUMMARY
========================================================= */

.home-month-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-top: 12px;
}

.home-month-stat {
  min-width: 0;
  padding: 11px;
  border: 1px solid #e1e9ec;
  border-radius: 10px;
  background: #fbfcfd;
}

.home-month-stat span {
  display: block;
  margin-bottom: 5px;
  color: #96a4a9;
  font-size: 5px;
  font-weight: 900;
  text-transform: uppercase;
}

.home-month-stat strong {
  display: block;
  overflow: hidden;
  color: #536f7c;
  font-family: var(--font-heading);
  font-size: 17px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.home-month-stat.green {
  border-color: #d6e8da;
  background: #f5fbf6;
}

.home-month-stat.green strong {
  color: #2c7b50;
}

.home-month-stat.blue strong {
  color: #2c7497;
}

.home-month-stat.orange strong {
  color: #ae7731;
}

.home-crop-summary-list {
  margin-top: 10px;
}

.home-crop-summary-row {
  display: grid;
  grid-template-columns: 33px minmax(0, 1fr) 100px;
  align-items: center;
  gap: 8px;
  padding: 9px 0;
  border-bottom: 1px solid #edf1f3;
}

.home-crop-summary-row:last-child {
  border-bottom: 0;
}

.home-crop-summary-icon {
  width: 33px;
  height: 33px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #609274;
  background: #edf7f0;
}

.home-crop-summary-row > div:nth-child(2) {
  min-width: 0;
}

.home-crop-summary-row > div:nth-child(2) strong,
.home-crop-summary-row > div:nth-child(2) span,
.home-crop-summary-row > div:nth-child(3) strong,
.home-crop-summary-row > div:nth-child(3) span {
  display: block;
}

.home-crop-summary-row > div:nth-child(2) strong {
  color: #57717d;
  font-size: 7px;
}

.home-crop-summary-row > div:nth-child(2) span {
  margin-top: 3px;
  color: #9aa7ac;
  font-size: 5px;
}

.home-crop-summary-row > div:nth-child(3) {
  text-align: right;
}

.home-crop-summary-row > div:nth-child(3) strong {
  color: #56717c;
  font-size: 7px;
}

.home-crop-summary-row > div:nth-child(3) span {
  margin-top: 3px;
  color: #328052;
  font-size: 6px;
}

.home-inline-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 9px;
  color: #2e7ca2;
  font-size: 6px;
  font-weight: 900;
  text-decoration: none;
}

.home-inline-link:hover {
  text-decoration: underline;
}


/* =========================================================
   UPCOMING
========================================================= */

.home-upcoming-list,
.home-payment-list,
.home-recent-list {
  margin-top: 10px;
}

.home-upcoming-row,
.home-payment-row,
.home-recent-row {
  display: grid;
  align-items: center;
  gap: 9px;
  padding: 9px 0;
  border-bottom: 1px solid #edf1f3;
  color: inherit;
  text-decoration: none;
}

.home-upcoming-row {
  grid-template-columns: 45px minmax(0, 1fr) 110px 15px;
}

.home-payment-row {
  grid-template-columns: 31px minmax(0, 1fr) 100px 15px;
}

.home-recent-row {
  grid-template-columns: 46px minmax(0, 1fr) auto 15px;
}

.home-upcoming-row:last-child,
.home-payment-row:last-child,
.home-recent-row:last-child {
  border-bottom: 0;
}

.home-upcoming-row:hover,
.home-payment-row:hover,
.home-recent-row:hover {
  background: #fbfcfd;
}

.home-upcoming-token,
.home-recent-token {
  min-height: 27px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 7px;
  color: #2b7396;
  background: #eaf5f8;
  font-size: 7px;
  font-weight: 900;
}

.home-upcoming-main,
.home-payment-main,
.home-recent-main {
  min-width: 0;
}

.home-upcoming-main strong,
.home-upcoming-main span,
.home-payment-main strong,
.home-payment-main span,
.home-recent-main strong,
.home-recent-main span {
  display: block;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.home-upcoming-main strong,
.home-payment-main strong,
.home-recent-main strong {
  color: #58717d;
  font-size: 7px;
}

.home-upcoming-main span,
.home-payment-main span,
.home-recent-main span {
  margin-top: 3px;
  color: #9aa7ac;
  font-size: 5px;
}

.home-upcoming-time {
  color: #627b86;
  font-size: 6px;
  font-weight: 800;
  text-align: right;
}

.home-payment-icon {
  width: 31px;
  height: 31px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #2a9259;
  background: #eaf7ee;
}

.home-payment-amount {
  text-align: right;
}

.home-payment-amount strong,
.home-payment-amount span {
  display: block;
}

.home-payment-amount strong {
  color: #2f7f52;
  font-size: 8px;
}

.home-payment-amount span {
  margin-top: 3px;
  color: #9ba7ac;
  font-size: 5px;
}

.home-dashboard-section .home-summary-empty {
  margin-top: 10px;
}


/* =========================================================
   EMPTY
========================================================= */

.home-summary-empty {
  min-height: 115px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 6px;
  padding: 20px;
  border: 1px dashed #dce6e9;
  border-radius: 10px;
  color: #9aa8ad;
  text-align: center;
}

.home-summary-empty.large {
  min-height: 155px;
}

.home-summary-empty strong {
  color: #5d7580;
  font-size: 8px;
}

.home-summary-empty span {
  max-width: 350px;
  color: #93a1a7;
  font-size: 6px;
  line-height: 1.5;
}


/* =========================================================
   PROCUREMENT CENTER
========================================================= */

.home-center-card {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr) auto;
  align-items: center;
  gap: 15px;
}

.home-center-main {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  min-width: 0;
}

.home-center-icon {
  width: 39px;
  height: 39px;
  flex: 0 0 39px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: #166534;
  background: #dcfce7;
}

.home-center-main > div:last-child {
  min-width: 0;
}

.home-center-main h2 {
  margin: 4px 0 4px;
  overflow: hidden;
  color: #4d6976;
  font-family: var(--font-heading);
  font-size: 12px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.home-center-main p {
  margin: 0;
  overflow: hidden;
  color: #96a4a9;
  font-size: 6px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.home-center-details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
}

.home-center-details > div {
  padding: 8px;
  border: 1px solid #e4eaed;
  border-radius: 8px;
  background: #fbfcfd;
}

.home-center-details span,
.home-center-details strong {
  display: block;
}

.home-center-details span {
  color: #9aa7ac;
  font-size: 5px;
}

.home-center-details strong {
  margin-top: 4px;
  color: #5a7480;
  font-size: 6px;
}

.home-center-actions {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.home-center-actions a {
  min-width: 108px;
}


/* =========================================================
   ARRIVAL CHECKLIST
========================================================= */

.home-arrival-check-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 7px;
  margin-top: 12px;
}

.home-arrival-check {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 9px;
  border: 1px solid #e2e9eb;
  border-radius: 9px;
  background: #fbfcfd;
}

.home-arrival-check > div {
  width: 21px;
  height: 21px;
  flex: 0 0 21px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  color: #228852;
  background: #e5f5e9;
}

.home-arrival-check span {
  color: #657e89;
  font-size: 6px;
  line-height: 1.3;
}


/* =========================================================
   SMS
========================================================= */

.home-sms-card {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  margin-bottom: 14px;
  padding: 15px;
  border: 1px solid #d8e6eb;
  border-radius: 14px;
  background: #f3f9fb;
}

.home-sms-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: #2b7ea4;
  background: #e3f1f6;
}

.home-sms-card > div:last-child {
  min-width: 0;
}

.home-sms-card > div:last-child > span {
  color: #8ca0a8;
  font-size: 5px;
  font-weight: 900;
  letter-spacing: .08em;
}

.home-sms-card h3 {
  margin: 5px 0 4px;
  color: #526f7d;
  font-family: var(--font-heading);
  font-size: 11px;
}

.home-sms-card p {
  margin: 0;
  color: #85979e;
  font-size: 6px;
  line-height: 1.55;
}


/* =========================================================
   PROCUREMENT JOURNEY
========================================================= */

.farmer-progress-heading {
  align-items: center;
}

.farmer-current-stage {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 0 8px;
  border-radius: 999px;
  color: #2a7ca1;
  background: #edf7fa;
  font-size: 5px;
  font-weight: 900;
}

.farmer-progress-track {
  display: flex;
  align-items: flex-start;
  margin-top: 16px;
}

.farmer-progress-stage {
  min-width: 72px;
  display: flex;
  align-items: center;
  flex-direction: column;
  gap: 6px;
  color: #b0babf;
  text-align: center;
}

.farmer-progress-icon {
  width: 35px;
  height: 35px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #e0e7e9;
  border-radius: 10px;
  color: #a3afb4;
  background: #fff7ed;
}

.farmer-progress-stage.active .farmer-progress-icon {
  border-color: #c6dce4;
  color: #2d7da1;
  background: #edf7fa;
}

.farmer-progress-stage.complete .farmer-progress-icon {
  border-color: #cce3d2;
  color: #2b9059;
  background: #eaf7ed;
}

.farmer-progress-stage span {
  font-size: 5px;
  font-weight: 800;
}

.farmer-progress-stage.active span {
  color: #54717e;
}

.farmer-progress-stage.complete span {
  color: #49745a;
}

.farmer-progress-line {
  flex: 1;
  height: 2px;
  margin-top: 17px;
  background: #e6ecee;
}

.farmer-progress-line.active {
  background: #9fc7b0;
}

.farmer-progress-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid #edf1f3;
}

.farmer-progress-bottom span,
.farmer-progress-bottom strong {
  display: block;
}

.farmer-progress-bottom span {
  color: #9ba7ac;
  font-size: 5px;
  font-weight: 900;
}

.farmer-progress-bottom strong {
  margin-top: 3px;
  color: #59727d;
  font-size: 7px;
}

.farmer-progress-percent {
  color: #2e8254;
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 900;
}


/* =========================================================
   SUPPORT
========================================================= */

.home-support-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-top: 4px;
  color: #9aa7ac;
  font-size: 6px;
}

.home-support-row a {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #2f7da2;
  text-decoration: none;
  font-weight: 900;
}

.home-support-row a:hover {
  text-decoration: underline;
}


/* =========================================================
   LOADING / ERROR
========================================================= */

.loading-spin,
.token-spin {
  animation: farmerSpin .8s linear infinite;
}

@keyframes farmerSpin {
  to {
    transform: rotate(360deg);
  }
}

.empty-state-card {
  padding: 40px 25px;
  border: 1px solid #dfe8eb;
  border-radius: 16px;
  background: #ffffff;
  text-align: center;
  box-shadow: 0 9px 27px rgba(35, 73, 92, .03);
}

.empty-state-icon {
  width: 52px;
  height: 52px;
  margin: 0 auto 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 14px;
  color: #5f8796;
  background: #eaf4f7;
}

.empty-state-card h1 {
  margin: 6px 0;
  color: #4b6877;
  font-family: var(--font-heading);
  font-size: 19px;
}

.empty-state-card p {
  max-width: 420px;
  margin: 0 auto 14px;
  color: #8b9ba2;
  font-size: 7px;
  line-height: 1.6;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1050px) {

  .home-center-card {
    grid-template-columns: 1fr;
  }

  .home-center-actions {
    flex-direction: row;
  }

  .home-center-actions a {
    flex: 1;
  }

}

@media (max-width: 850px) {

  .farmer-welcome {
    flex-direction: column;
  }

  .farmer-profile {
    width: 100%;
  }

  .farmer-home-grid {
    grid-template-columns: 1fr;
  }

  .booking-main-details {
    grid-template-columns: 1fr;
  }

  .home-arrival-check-grid {
    grid-template-columns: repeat(2, 1fr);
  }

}

@media (max-width: 650px) {

  .farmer-home-container {
    width: min(100% - 20px, 1320px);
    padding-top: 18px;
  }

  .next-booking-card,
  .home-dashboard-section,
  .home-month-summary-card,
  .home-center-card,
  .home-arrival-check-card,
  .farmer-progress-card {
    padding: 13px;
    border-radius: 13px;
  }

  .home-month-stats {
    grid-template-columns: 1fr;
  }

  .home-upcoming-row {
    grid-template-columns: 42px minmax(0, 1fr) 80px 15px;
  }

  .home-payment-row {
    grid-template-columns: 30px minmax(0, 1fr) 80px 15px;
  }

  .home-recent-row {
    grid-template-columns: 42px minmax(0, 1fr) auto 15px;
  }

  .home-center-details {
    grid-template-columns: 1fr;
  }

  .home-arrival-check-grid {
    grid-template-columns: 1fr;
  }

  .farmer-progress-track {
    overflow-x: auto;
    padding-bottom: 5px;
  }

  .farmer-progress-stage {
    min-width: 64px;
  }

  .farmer-progress-line {
    min-width: 25px;
  }

  .booking-action-row {
    flex-direction: column;
  }

  .booking-action-row a {
    width: 100%;
  }

  .home-payment-complete-strip {
    flex-direction: column;
  }

  .home-payment-complete-strip > div {
    width: 100%;
  }

}

@media (max-width: 450px) {

  .farmer-welcome h1 {
    font-size: 28px;
  }

  .booking-card-top {
    gap: 8px;
  }

  .booking-confirmed-icon {
    width: 39px;
    height: 39px;
    flex-basis: 39px;
  }

  .home-upcoming-time {
    font-size: 5px;
  }

}
/* =========================================================
   FARMER HISTORY + PAYMENTS
   LARGE FARMER-FRIENDLY UI
========================================================= */

.farmer-history-page,
.farmer-payments-page {
  min-height: 100vh;
  background: #f7faf8;
}

.farmer-history-container,
.farmer-payments-container {
  width: min(1250px, calc(100% - 32px));
  margin: 0 auto;
  padding: 34px 0 55px;
}


/* =========================================================
   HEADER
========================================================= */

.farmer-history-top,
.farmer-payments-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 24px;
}

.farmer-history-top h1,
.farmer-payments-top h1 {
  margin: 8px 0 8px;
  color: #234a5c;
  font-family: var(--font-heading);
  font-size: clamp(34px, 4vw, 52px);
  line-height: 1.03;
  letter-spacing: -.035em;
}

.farmer-history-top p,
.farmer-payments-top p {
  max-width: 760px;
  margin: 0;
  color: #738a95;
  font-size: 15px;
  line-height: 1.6;
}

.farmer-history-refresh,
.farmer-payments-refresh {
  min-height: 46px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 16px;
  border: 1px solid #d5e3e7;
  border-radius: 10px;
  color: #55727f;
  background: #ffffff;
  cursor: pointer;
  font-size: 13px;
  font-weight: 800;
}

.farmer-history-refresh:hover:not(:disabled),
.farmer-payments-refresh:hover:not(:disabled) {
  color: #287ea5;
  border-color: #bcd3dc;
}

.farmer-history-refresh:disabled,
.farmer-payments-refresh:disabled {
  opacity: .55;
  cursor: not-allowed;
}


/* =========================================================
   SUMMARY CARDS
========================================================= */

.farmer-history-stats,
.farmer-payments-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 16px;
}

.farmer-history-stat,
.farmer-payments-stat {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 17px;
  border: 1px solid #dce7e9;
  border-radius: 14px;
  background: #ffffff;
  box-shadow: 0 8px 24px rgba(35, 73, 92, .035);
}

.farmer-history-stat-icon,
.farmer-payments-stat-icon {
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  color: #166534;
  background: #dcfce7;
}

.farmer-history-stat > div:last-child,
.farmer-payments-stat > div:last-child {
  min-width: 0;
}

.farmer-history-stat span,
.farmer-payments-stat span {
  display: block;
  margin-bottom: 5px;
  color: #82969f;
  font-size: 11px;
  font-weight: 800;
}

.farmer-history-stat strong,
.farmer-payments-stat strong {
  display: block;
  overflow: hidden;
  color: #365b6b;
  font-family: var(--font-heading);
  font-size: 25px;
  line-height: 1.1;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   FILTERS
========================================================= */

.farmer-history-filter-bar,
.farmer-payments-filter-bar {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 16px;
  padding: 10px;
  border: 1px solid #dce7e9;
  border-radius: 12px;
  background: #ffffff;
}

.farmer-history-search,
.farmer-payments-search {
  flex: 1;
  min-width: 240px;
  height: 44px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 12px;
  border: 1px solid #d8e3e7;
  border-radius: 9px;
  color: #8598a0;
  background: #fbfcfd;
}

.farmer-history-search:focus-within,
.farmer-payments-search:focus-within {
  border-color: #a8c4ce;
  background: #ffffff;
  box-shadow: 0 0 0 3px rgba(47, 126, 163, .06);
}

.farmer-history-search input,
.farmer-payments-search input {
  width: 100%;
  height: 100%;
  border: 0;
  outline: 0;
  color: #466676;
  background: transparent;
  font-size: 13px;
}

.farmer-history-search input::placeholder,
.farmer-payments-search input::placeholder {
  color: #a2afb4;
}

.farmer-history-filter-bar select,
.farmer-payments-filter-bar select {
  height: 44px;
  min-width: 155px;
  padding: 0 12px;
  border: 1px solid #d8e3e7;
  border-radius: 9px;
  outline: 0;
  color: #57727e;
  background: #fbfcfd;
  cursor: pointer;
  font-size: 12px;
  font-weight: 800;
}

.farmer-history-filter-bar > button,
.farmer-payments-filter-bar > button {
  height: 44px;
  padding: 0 13px;
  border: 1px solid #e0d4d0;
  border-radius: 9px;
  color: #a05d51;
  background: #fff8f6;
  cursor: pointer;
  font-size: 11px;
  font-weight: 900;
}


/* =========================================================
   MAIN LIST CARD
========================================================= */

.farmer-history-list-card,
.farmer-payments-list-card {
  overflow: hidden;
  border: 1px solid #dce7e9;
  border-radius: 15px;
  background: #ffffff;
  box-shadow: 0 8px 25px rgba(35, 73, 92, .035);
}

.farmer-history-list-heading,
.farmer-payments-list-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 19px 20px;
  border-bottom: 1px solid #edf1f2;
}

.farmer-history-list-heading h2,
.farmer-payments-list-heading h2 {
  margin: 5px 0 0;
  color: #496776;
  font-family: var(--font-heading);
  font-size: 22px;
}


/* =========================================================
   HISTORY RECORD
========================================================= */

.farmer-history-record {
  display: grid;
  grid-template-columns: 70px minmax(0, 1fr) 130px 130px 18px;
  align-items: center;
  gap: 14px;
  min-height: 88px;
  padding: 13px 20px;
  border-bottom: 1px solid #edf1f2;
  color: inherit;
  text-decoration: none;
}

.farmer-history-record:last-child {
  border-bottom: 0;
}

.farmer-history-record:hover {
  background: #fbfcfd;
}

.farmer-history-token {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #2d7598;
  background: #e9f5f8;
  font-size: 13px;
  font-weight: 900;
}

.farmer-history-crop {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
}

.farmer-history-crop-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #619475;
  background: #edf7f0;
}

.farmer-history-crop > div:last-child {
  min-width: 0;
}

.farmer-history-crop strong,
.farmer-history-crop span {
  display: block;
}

.farmer-history-crop strong {
  overflow: hidden;
  color: #496875;
  font-size: 14px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.farmer-history-crop span {
  margin-top: 4px;
  color: #8b9da4;
  font-size: 11px;
}

.farmer-history-status {
  justify-self: start;
}

.farmer-history-amount {
  text-align: right;
}

.farmer-history-amount strong,
.farmer-history-amount span {
  display: block;
}

.farmer-history-amount strong {
  color: #307b52;
  font-family: var(--font-heading);
  font-size: 16px;
}

.farmer-history-amount span {
  margin-top: 3px;
  color: #8ea096;
  font-size: 10px;
}


/* =========================================================
   PAYMENT RECORD
========================================================= */

.farmer-payment-record {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 135px 150px auto 18px;
  align-items: center;
  gap: 13px;
  min-height: 92px;
  padding: 14px 20px;
  border-bottom: 1px solid #edf1f2;
  color: inherit;
  text-decoration: none;
}

.farmer-payment-record:last-child {
  border-bottom: 0;
}

.farmer-payment-record:hover {
  background: #fbfcfd;
}

.farmer-payment-record-icon {
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
}

.farmer-payment-record-icon.paid {
  color: #2c8d59;
  background: #e9f7ed;
}

.farmer-payment-record-icon.pending {
  color: #b57e27;
  background: #fff3db;
}

.farmer-payment-record-main {
  min-width: 0;
}

.farmer-payment-record-main > div {
  display: flex;
  align-items: center;
  gap: 7px;
}

.farmer-payment-record-main strong {
  overflow: hidden;
  color: #4b6976;
  font-size: 14px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.farmer-payment-record-main > div span {
  color: #8e9da3;
  font-size: 11px;
}

.farmer-payment-record-main p {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 5px 0 0;
  color: #8e9da3;
  font-size: 10px;
}

.farmer-payment-record-amount {
  text-align: right;
}

.farmer-payment-record-amount strong,
.farmer-payment-record-amount span {
  display: block;
}

.farmer-payment-record-amount strong {
  color: #2c7d50;
  font-family: var(--font-heading);
  font-size: 17px;
}

.farmer-payment-record-amount span {
  margin-top: 3px;
  color: #8fa096;
  font-size: 10px;
}

.farmer-payment-record-reference {
  min-width: 0;
}

.farmer-payment-record-reference span,
.farmer-payment-record-reference strong {
  display: block;
}

.farmer-payment-record-reference span {
  margin-bottom: 4px;
  color: #98a5aa;
  font-size: 9px;
  font-weight: 900;
}

.farmer-payment-record-reference strong {
  overflow: hidden;
  color: #617d88;
  font-size: 10px;
  white-space: nowrap;
  text-overflow: ellipsis;
}


/* =========================================================
   EMPTY / LOADING
========================================================= */

.farmer-history-loading,
.farmer-history-empty,
.farmer-payments-state,
.farmer-payments-empty {
  min-height: 280px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 10px;
  padding: 35px;
  color: #8ea0a7;
  text-align: center;
}

.farmer-history-empty strong,
.farmer-payments-state strong,
.farmer-payments-empty h1 {
  color: #58727e;
  font-family: var(--font-heading);
  font-size: 19px;
}

.farmer-history-empty span,
.farmer-payments-state span,
.farmer-payments-empty p {
  max-width: 470px;
  color: #8c9ba1;
  font-size: 12px;
  line-height: 1.6;
}


/* =========================================================
   PAYMENT HELP
========================================================= */

.farmer-payments-help {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 15px;
  padding: 15px 17px;
  border: 1px solid #e4ddd0;
  border-radius: 13px;
  background: #fffaf2;
}

.farmer-payments-help-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: #ae7b2c;
  background: #fff0cd;
}

.farmer-payments-help > div:nth-child(2) {
  min-width: 0;
  flex: 1;
}

.farmer-payments-help strong {
  display: block;
  color: #715c38;
  font-size: 13px;
}

.farmer-payments-help span {
  display: block;
  margin-top: 3px;
  color: #95866c;
  font-size: 10px;
}


/* =========================================================
   FOOTER ACTIONS
========================================================= */

.farmer-history-footer,
.farmer-payments-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 17px;
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 1050px) {

  .farmer-history-stats,
  .farmer-payments-summary {
    grid-template-columns: repeat(2, 1fr);
  }

  .farmer-history-record {
    grid-template-columns: 60px minmax(0, 1fr) 110px 18px;
  }

  .farmer-history-status {
    grid-column: 3;
  }

  .farmer-history-amount {
    grid-column: 2;
    text-align: left;
  }

  .farmer-payment-record {
    grid-template-columns: 42px minmax(0, 1fr) 110px 18px;
  }

  .farmer-payment-record-reference,
  .farmer-payment-record .admin-status-pill {
    display: none;
  }

}


@media (max-width: 760px) {

  .farmer-history-container,
  .farmer-payments-container {
    width: min(100% - 20px, 1250px);
    padding-top: 20px;
  }

  .farmer-history-top,
  .farmer-payments-top {
    flex-direction: column;
  }

  .farmer-history-refresh,
  .farmer-payments-refresh {
    width: 100%;
  }

  .farmer-history-top h1,
  .farmer-payments-top h1 {
    font-size: 36px;
  }

  .farmer-history-top p,
  .farmer-payments-top p {
    font-size: 14px;
  }

  .farmer-history-filter-bar,
  .farmer-payments-filter-bar {
    flex-direction: column;
    align-items: stretch;
  }

  .farmer-history-search,
  .farmer-payments-search {
    min-width: 0;
  }

  .farmer-history-filter-bar select,
  .farmer-payments-filter-bar select,
  .farmer-history-filter-bar > button,
  .farmer-payments-filter-bar > button {
    width: 100%;
  }

  .farmer-history-stats,
  .farmer-payments-summary {
    grid-template-columns: 1fr;
  }

  .farmer-history-record {
    grid-template-columns: 48px minmax(0, 1fr) 18px;
    gap: 9px;
    min-height: 76px;
    padding: 10px 12px;
  }

  .farmer-history-status,
  .farmer-history-amount {
    grid-column: auto;
  }

  .farmer-history-amount {
    display: none;
  }

  .farmer-history-record .admin-status-pill {
    display: none;
  }

  .farmer-payment-record {
    grid-template-columns: 40px minmax(0, 1fr) 18px;
    gap: 9px;
    min-height: 78px;
    padding: 11px 12px;
  }

  .farmer-payment-record-amount {
    grid-column: 2;
    text-align: left;
  }

  .farmer-payment-record-reference,
  .farmer-payment-record .admin-status-pill {
    display: none;
  }

  .farmer-history-footer,
  .farmer-payments-footer {
    flex-direction: column;
  }

  .farmer-history-footer a,
  .farmer-payments-footer a {
    width: 100%;
  }

  .farmer-payments-help {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .farmer-payments-help a {
    width: 100%;
  }

}
/* =========================================================
   FARMER HISTORY - GRAPH
========================================================= */

.farmer-history-chart-card {
  margin-bottom: 18px;
  padding: 24px;
  border: 1px solid #dce7e9;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 8px 25px rgba(35, 73, 92, .04);
}

.farmer-history-chart-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
  margin-bottom: 20px;
}

.farmer-history-chart-heading h2 {
  margin: 6px 0 5px;
  color: #496875;
  font-family: var(--font-heading);
  font-size: 22px;
}

.farmer-history-chart-heading p {
  margin: 0;
  color: #8c9ca3;
  font-size: 12px;
}

.farmer-history-chart-heading > svg {
  color: #629476;
}

.farmer-history-chart {
  display: flex;
  flex-direction: column;
  gap: 17px;
}

.farmer-history-chart-row {
  display: grid;
  grid-template-columns: 145px minmax(0, 1fr) 130px;
  align-items: center;
  gap: 15px;
}

.farmer-history-chart-label {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
}

.farmer-history-chart-icon {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #5f9273;
  background: #edf7f0;
}

.farmer-history-chart-label strong {
  overflow: hidden;
  color: #526f7b;
  font-size: 13px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.farmer-history-chart-track {
  position: relative;
  width: 100%;
  height: 24px;
  overflow: hidden;
  border-radius: 999px;
  background: #edf2f3;
}

.farmer-history-chart-bar {
  height: 100%;
  min-width: 18px;
  border-radius: 999px;
  background: #6fa37e;
  transition: width .35s ease;
}

.farmer-history-chart-value {
  min-width: 0;
  text-align: right;
}

.farmer-history-chart-value strong,
.farmer-history-chart-value span {
  display: block;
}

.farmer-history-chart-value strong {
  color: #4f6d79;
  font-size: 14px;
}

.farmer-history-chart-value span {
  margin-top: 4px;
  color: #318152;
  font-size: 11px;
  font-weight: 700;
}


/* =========================================================
   GRAPH EMPTY STATE
========================================================= */

.farmer-history-chart-empty {
  min-height: 220px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 9px;
  text-align: center;
  color: #98a7ac;
}

.farmer-history-chart-empty strong {
  color: #57727e;
  font-family: var(--font-heading);
  font-size: 18px;
}

.farmer-history-chart-empty span {
  max-width: 430px;
  color: #8f9da2;
  font-size: 12px;
  line-height: 1.55;
}


/* =========================================================
   MONTH SELECTOR
========================================================= */

.farmer-history-filter-bar select {
  min-width: 175px;
  height: 46px;
  padding: 0 14px;
  border: 1px solid #d5e2e6;
  border-radius: 9px;
  outline: none;
  color: #526f7c;
  background: #ffffff;
  font-family: inherit;
  font-size: 13px;
  font-weight: 700;
}

.farmer-history-filter-bar select:focus {
  border-color: #9ebfca;
  box-shadow: 0 0 0 3px rgba(47, 126, 163, .06);
}


/* =========================================================
   CROP CARDS
========================================================= */

.farmer-history-crop-summary {
  margin-bottom: 18px;
  padding: 24px;
  border: 1px solid #dce7e9;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 8px 25px rgba(35, 73, 92, .04);
}

.farmer-history-crop-cards {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-top: 15px;
}

.farmer-history-crop-card {
  padding: 15px;
  border: 1px solid #e0e9eb;
  border-radius: 12px;
  background: #fbfcfc;
}

.farmer-history-crop-card-icon {
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 10px;
  border-radius: 10px;
  color: #5d9472;
  background: #edf7f0;
}

.farmer-history-crop-card strong,
.farmer-history-crop-card span,
.farmer-history-crop-card small {
  display: block;
}

.farmer-history-crop-card strong {
  color: #4f6c78;
  font-size: 14px;
}

.farmer-history-crop-card span {
  margin-top: 6px;
  color: #5e7680;
  font-size: 16px;
  font-weight: 800;
}

.farmer-history-crop-card small {
  margin-top: 3px;
  color: #348052;
  font-size: 11px;
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 850px) {

  .farmer-history-chart-row {
    grid-template-columns: 120px minmax(0, 1fr) 95px;
    gap: 9px;
  }

  .farmer-history-crop-cards {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

}

@media (max-width: 600px) {

  .farmer-history-chart-card,
  .farmer-history-crop-summary {
    padding: 17px;
  }

  .farmer-history-chart-row {
    grid-template-columns: 1fr;
    gap: 7px;
  }

  .farmer-history-chart-track {
    height: 20px;
  }

  .farmer-history-chart-value {
    text-align: left;
  }

  .farmer-history-crop-cards {
    grid-template-columns: 1fr;
  }

}
/* =========================================================
   ADMIN PAYMENT ISSUES
========================================================= */

.admin-payment-issues-page {
  width: 100%;
}


/* =========================================================
   HERO
========================================================= */

.admin-payment-issues-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 20px;
}

.admin-payment-issues-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 12px;
  color: #6f8791;
  font-size: 11px;
  font-weight: 700;
  text-decoration: none;
}

.admin-payment-issues-back:hover {
  color: #2d7da1;
}

.admin-payment-issues-hero h2 {
  margin: 7px 0 7px;
  color: #294f61;
  font-family: var(--font-heading);
  font-size: 31px;
  line-height: 1.08;
}

.admin-payment-issues-hero p {
  max-width: 670px;
  margin: 0;
  color: #81959e;
  font-size: 12px;
  line-height: 1.6;
}

.admin-payment-issues-refresh {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 14px;
  border: 1px solid #d9e5e8;
  border-radius: 9px;
  color: #5d7884;
  background: #ffffff;
  cursor: pointer;
  font-size: 10px;
  font-weight: 800;
}

.admin-payment-issues-refresh:hover:not(:disabled) {
  color: #2d7da1;
  border-color: #bed5de;
}

.admin-payment-issues-refresh:disabled {
  opacity: .6;
  cursor: not-allowed;
}


/* =========================================================
   ERROR
========================================================= */

.admin-payment-issues-error {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 14px;
  padding: 11px 13px;
  border: 1px solid #ecd6d1;
  border-radius: 10px;
  color: #9a5e54;
  background: #fff8f6;
  font-size: 10px;
}

.admin-payment-issues-error span {
  flex: 1;
}

.admin-payment-issues-error button {
  width: 27px;
  height: 27px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 7px;
  color: #9a665e;
  background: transparent;
  cursor: pointer;
}


/* =========================================================
   STATS
========================================================= */

.admin-payment-issues-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 14px;
}

.admin-payment-issue-stat {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px;
  border: 1px solid #dfe8ea;
  border-radius: 12px;
  background: #ffffff;
}

.admin-payment-issue-stat-icon {
  width: 37px;
  height: 37px;
  flex: 0 0 37px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: #edf4f6;
  color: #63808b;
}

.admin-payment-issue-stat span,
.admin-payment-issue-stat strong {
  display: block;
}

.admin-payment-issue-stat span {
  color: #91a1a7;
  font-size: 7px;
  font-weight: 800;
}

.admin-payment-issue-stat strong {
  margin-top: 3px;
  color: #526d78;
  font-family: var(--font-heading);
  font-size: 21px;
}

.admin-payment-issue-stat.orange .admin-payment-issue-stat-icon {
  color: #ae772c;
  background: #fff1d8;
}

.admin-payment-issue-stat.green .admin-payment-issue-stat-icon {
  color: #2d8955;
  background: #e8f6eb;
}

.admin-payment-issue-stat.blue .admin-payment-issue-stat-icon {
  color: #166534;
  background: #dcfce7;
}


/* =========================================================
   FILTER
========================================================= */

.admin-payment-issues-filter {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
  padding: 9px;
  border: 1px solid #dfe8ea;
  border-radius: 11px;
  background: #ffffff;
}

.admin-payment-issues-search {
  flex: 1;
  min-width: 240px;
  height: 38px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 11px;
  border: 1px solid #d9e3e6;
  border-radius: 8px;
  color: #879ba3;
  background: #fbfcfc;
}

.admin-payment-issues-search:focus-within {
  border-color: #aac5cf;
  box-shadow: 0 0 0 3px rgba(45, 125, 161, .05);
}

.admin-payment-issues-search input {
  width: 100%;
  height: 100%;
  border: 0;
  outline: 0;
  color: #506e79;
  background: transparent;
  font-size: 10px;
}

.admin-payment-issues-search input::placeholder {
  color: #a1afb4;
}

.admin-payment-issues-filter select {
  height: 38px;
  min-width: 135px;
  padding: 0 10px;
  border: 1px solid #d9e3e6;
  border-radius: 8px;
  outline: 0;
  color: #5a7480;
  background: #fbfcfd;
  cursor: pointer;
  font-size: 9px;
  font-weight: 800;
}


/* =========================================================
   LIST
========================================================= */

.admin-payment-issues-list-card {
  overflow: hidden;
  border: 1px solid #dfe8ea;
  border-radius: 13px;
  background: #ffffff;
  box-shadow: 0 7px 23px rgba(35, 73, 92, .025);
}

.admin-payment-issues-list-header {
  padding: 15px 16px;
  border-bottom: 1px solid #edf1f2;
}

.admin-payment-issues-list-header h3 {
  margin: 5px 0 0;
  color: #516c78;
  font-family: var(--font-heading);
  font-size: 16px;
}


/* =========================================================
   ISSUE ROW
========================================================= */

.admin-payment-issue-row {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) 180px;
  gap: 12px;
  align-items: start;
  padding: 15px 16px;
  border-bottom: 1px solid #edf1f2;
}

.admin-payment-issue-row:last-child {
  border-bottom: 0;
}

.admin-payment-issue-row:hover {
  background: #fcfdfd;
}

.admin-payment-issue-icon {
  width: 39px;
  height: 39px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
}

.admin-payment-issue-icon.open {
  color: #b4762a;
  background: #fff0d5;
}

.admin-payment-issue-icon.resolved {
  color: #2a8a56;
  background: #e8f6eb;
}

.admin-payment-issue-main {
  min-width: 0;
}

.admin-payment-issue-title {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-payment-issue-title strong {
  color: #4f6a76;
  font-size: 11px;
}

.admin-payment-issue-status {
  display: inline-flex;
  align-items: center;
  min-height: 20px;
  padding: 0 7px;
  border-radius: 999px;
  font-size: 6px;
  font-weight: 900;
  text-transform: uppercase;
}

.admin-payment-issue-status.open {
  color: #a66c24;
  background: #fff1d9;
}

.admin-payment-issue-status.resolved {
  color: #2b8352;
  background: #e8f6eb;
}

.admin-payment-issue-farmer {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 6px;
  color: #84979f;
  font-size: 8px;
}

.admin-payment-issue-main p {
  margin: 8px 0 5px;
  color: #627b85;
  font-size: 9px;
  line-height: 1.55;
}

.admin-payment-issue-main small {
  color: #a1adb1;
  font-size: 6px;
}

.admin-payment-issue-actions {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 6px;
}

.admin-payment-issue-view,
.admin-payment-issue-resolve,
.admin-payment-issue-reopen {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 10px;
  border-radius: 7px;
  font-size: 7px;
  font-weight: 900;
  text-decoration: none;
  cursor: pointer;
}

.admin-payment-issue-view {
  border: 1px solid #d7e4e8;
  color: #477182;
  background: #ffffff;
}

.admin-payment-issue-view:hover {
  background: #f5f9fa;
}

.admin-payment-issue-resolve {
  border: 1px solid #c9e2d2;
  color: #287a4d;
  background: #edf8f0;
}

.admin-payment-issue-resolve:hover:not(:disabled) {
  background: #e3f4e8;
}

.admin-payment-issue-reopen {
  border: 1px solid #e0d5ca;
  color: #946e47;
  background: #fffaf5;
}

.admin-payment-issue-resolve:disabled,
.admin-payment-issue-reopen:disabled {
  opacity: .55;
  cursor: not-allowed;
}


/* =========================================================
   EMPTY / LOADING
========================================================= */

.admin-payment-issues-state {
  min-height: 230px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 8px;
  padding: 28px;
  color: #93a2a7;
  text-align: center;
}

.admin-payment-issues-state strong {
  color: #5a7480;
  font-family: var(--font-heading);
  font-size: 14px;
}

.admin-payment-issues-state span {
  color: #96a3a8;
  font-size: 8px;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 800px) {

  .admin-payment-issues-hero {
    flex-direction: column;
  }

  .admin-payment-issues-refresh {
    width: 100%;
  }

  .admin-payment-issues-stats {
    grid-template-columns: 1fr;
  }

  .admin-payment-issues-filter {
    flex-direction: column;
    align-items: stretch;
  }

  .admin-payment-issues-search {
    min-width: 0;
  }

  .admin-payment-issues-filter select {
    width: 100%;
  }

  .admin-payment-issue-row {
    grid-template-columns: 40px minmax(0, 1fr);
  }

  .admin-payment-issue-actions {
    grid-column: 2;
    flex-direction: row;
  }

  .admin-payment-issue-actions > * {
    flex: 1;
  }

}

@media (max-width: 500px) {

  .admin-payment-issues-hero h2 {
    font-size: 26px;
  }

  .admin-payment-issues-hero p {
    font-size: 10px;
  }

  .admin-payment-issue-row {
    padding: 12px;
  }

  .admin-payment-issue-title {
    flex-wrap: wrap;
  }

  .admin-payment-issue-actions {
    flex-direction: column;
  }

}
/* =========================================================
   ADMIN DASHBOARD - PAYMENT ISSUES
========================================================= */

.admin-dashboard-payment-issues-card {
