  border: 1px solid var(--ks-border);
  background: #fff;
  box-shadow: var(--ks-shadow-soft);
}


.next-booking-card::after {
  content: "";
  position: absolute;
  right: -100px;
  top: -100px;
  width: 240px;
  height: 240px;
  border-radius: 50%;
  background:
    radial-gradient(
      circle,
      rgba(82, 151, 113, .08),
      transparent 68%
    );
  pointer-events: none;
}


.booking-card-top {
