  }

  .booking-main-details {
    grid-template-columns: 1fr;
  }

  .admin-dashboard-kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }

}


@media (max-width: 600px) {

  .farmer-home-container > section h1 {
    font-size: 34px;
  }

  .farmer-home-container > section h2,
  .token-container > section h2 {
    font-size: 27px;
  }

  .next-booking-card,
  .token-hero-card,
  .token-status-card,
  .token-details-card,
  .farmer-progress-card {
    padding: 20px;
    border-radius: 17px;
  }

  .home-token {
    font-size: 46px;
  }

  .token-number {
    font-size: 52px;
  }

  .booking-action-row {
    flex-direction: column;
  }

  .home-primary-action,
  .home-secondary-action {
    width: 100%;
    justify-content: center;
  }

  .farmer-home-grid {
    grid-template-columns: 1fr;
  }

  .admin-dashboard-kpi-grid {
    grid-template-columns: 1fr;
  }

  .admin-dashboard-payment-issues-card {
    grid-template-columns: 42px 1fr;
  }

  .admin-dashboard-payment-issues-count,
  .admin-dashboard-payment-issues-button {
    grid-column: 2;
  }

}


@media (prefers-reduced-motion: reduce) {

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition: none !important;
    animation: none !important;
  }

}


/* =========================================================
   KRISHISETU — CIVIC / GOVERNMENT PORTAL UI
   Replace the previous visual-polish block with this.
========================================================= */


/* =========================================================
   DESIGN TOKENS
========================================================= */

:root {

  --ks-navy: #173f5f;
  --ks-blue: #166534;
  --ks-blue-dark: #15506f;
  --ks-sky: #eaf5fa;

  --ks-green: #287a4d;
  --ks-green-dark: #1d633d;
  --ks-green-soft: #e9f6ee;

  --ks-saffron: #d88726;
  --ks-saffron-soft: #fff3df;

  --ks-red: #bd554c;
  --ks-red-soft: #fff0ee;

  --ks-purple: #6b5aa8;
  --ks-purple-soft: #f1eefb;

  --ks-teal: #237f7b;
  --ks-teal-soft: #e8f7f6;

  --ks-gold: #a77824;
  --ks-gold-soft: #fff5dc;

  --ks-bg: #f3f7f7;
  --ks-bg-deep: #eaf1f2;

  --ks-surface: #ffffff;
  --ks-surface-soft: #f9fbfb;

  --ks-border: #dce7e9;
  --ks-border-strong: #c8d9dd;

  --ks-text: #254b5d;
  --ks-text-2: #52707c;
  --ks-text-3: #83979f;
  --ks-text-4: #a1afb4;

  --ks-shadow-1:
    0 2px 7px rgba(24, 59, 75, .035);

  --ks-shadow-2:
    0 10px 28px rgba(24, 59, 75, .065);

  --ks-shadow-3:
    0 18px 46px rgba(24, 59, 75, .09);

  --ks-radius-xl: 24px;
  --ks-radius-lg: 18px;
  --ks-radius-md: 13px;
  --ks-radius-sm: 9px;

  --ks-ease:
    cubic-bezier(.2,.7,.2,1);
}


/* =========================================================
   GLOBAL
========================================================= */

html {
  scroll-behavior: smooth;
}


body {
  background:
    linear-gradient(
      180deg,
      #eef5f6 0%,
      #f7faf9 38%,
      #f4f8f7 100%
    );
}


button,
input,
select,
textarea {
  font: inherit;
}


button,
a {
  -webkit-tap-highlight-color: transparent;
}


button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid rgba(33, 107, 145, .18);
  outline-offset: 2px;
}


button,
a {
  transition:
    transform .22s var(--ks-ease),
    box-shadow .22s var(--ks-ease),
    border-color .22s var(--ks-ease),
    background-color .22s var(--ks-ease),
    color .22s var(--ks-ease),
    opacity .22s var(--ks-ease);
}


/* =========================================================
   PAGE BACKGROUND / CONTAINERS
========================================================= */

.farmer-home-page,
.farmer-token-page {
  min-height: 100vh;
  background:
    radial-gradient(
      circle at 10% 0%,
      rgba(65, 147, 100, .08),
      transparent 26%
    ),
    radial-gradient(
      circle at 100% 8%,
      rgba(33, 107, 145, .08),
      transparent 25%
    );
}


.admin-dashboard-page,
.admin-queue-page,
.admin-payment-issues-page {
  position: relative;
}


.farmer-home-container,
.token-container {
  position: relative;
}


/* =========================================================
   CIVIC TOP STRIPE
========================================================= */

.farmer-home-page::before,
.farmer-token-page::before,
.admin-dashboard-page::before,
.admin-queue-page::before,
.admin-payment-issues-page::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 4px;
  background:
    linear-gradient(
      90deg,
      #d98220 0 33.33%,
      #f7f7f7 33.33% 66.66%,
      #2f8653 66.66% 100%
    );
  pointer-events: none;
}


/* =========================================================
   TYPOGRAPHY
========================================================= */

.page-eyebrow,
.admin-page-eyebrow,
.card-eyebrow,
.token-card-label {
  color: var(--ks-blue);
  letter-spacing: .13em;
  font-size: 10px;
  font-weight: 900;
}


.farmer-welcome h1 {
  color: var(--ks-navy);
  font-size: clamp(
    38px,
    4.6vw,
    62px
  );
  line-height: .98;
  letter-spacing: -.045em;
}


.farmer-welcome p {
  color: var(--ks-text-2);
  font-size: 14px;
  line-height: 1.75;
}


.next-booking-card h2,
.token-section-heading h2,
.farmer-progress-heading h2,
.token-details-card h2 {
  color: var(--ks-navy);
  letter-spacing: -.035em;
}


.admin-dashboard-hero h2,
.admin-queue-hero h2,
.admin-payment-issues-hero h2 {
  color: var(--ks-navy);
  font-size: clamp(
    36px,
    4.2vw,
    54px
  );
  line-height: .96;
  letter-spacing: -.045em;
}


.admin-dashboard-hero p,
.admin-queue-hero p,
.admin-payment-issues-hero p {
  color: var(--ks-text-2);
  font-size: 12px;
  line-height: 1.75;
}


/* =========================================================
   PROFILE
========================================================= */

.farmer-profile {
  border: 1px solid var(--ks-border);
  border-radius: 17px;
  background:
    linear-gradient(
      180deg,
      #ffffff,
      #f8fbfb
    );
  box-shadow: var(--ks-shadow-1);
}


.farmer-profile strong {
  color: var(--ks-navy);
  font-size: 13px;
}


.farmer-profile span {
  color: var(--ks-text-3);
  font-size: 8px;
}


.farmer-avatar {
  width: 48px;
  height: 48px;
  border-radius: 13px;
  color: #fff;
  background:
    linear-gradient(
      135deg,
      var(--ks-blue),
      var(--ks-green)
    );
  font-size: 14px;
  font-weight: 900;
  box-shadow:
    0 7px 18px rgba(33, 107, 145, .16);
}


/* =========================================================
   REFRESH BUTTON
========================================================= */

.farmer-refresh-button,
.token-refresh-button,
.admin-dashboard-refresh,
.admin-queue-refresh-button,
.admin-payment-issues-refresh {
  border: 1px solid var(--ks-border);
  border-radius: 10px;
  color: var(--ks-blue-dark);
  background: #fff;
  font-weight: 800;
}


.farmer-refresh-button:hover,
.token-refresh-button:hover,
.admin-dashboard-refresh:hover,
.admin-queue-refresh-button:hover,
.admin-payment-issues-refresh:hover {
  border-color: #b8cfd6;
  background: #f7fbfc;
  box-shadow: var(--ks-shadow-1);
}


/* =========================================================
   MAIN BOOKING CARD
========================================================= */

.next-booking-card,
.token-hero-card,
.token-status-card,
.token-details-card,
.farmer-progress-card,
.home-sms-card {
  border: 1px solid var(--ks-border);
  border-radius: var(--ks-radius-xl);
  background:
    linear-gradient(
      180deg,
      #ffffff,
      #fbfdfd
    );
  box-shadow: var(--ks-shadow-2);
}


.next-booking-card {
  padding: 30px;
}


.next-booking-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 5px;
  border-radius: 24px 0 0 24px;
  background:
    linear-gradient(
      180deg,
      var(--ks-saffron),
      var(--ks-green)
    );
}


/* =========================================================
   TOKEN / LARGE NUMBERS
========================================================= */

.home-token {
  color: var(--ks-navy);
  font-size: clamp(
    42px,
    6vw,
    68px
  );
  line-height: .9;
  letter-spacing: -.06em;
  font-weight: 950;
}


.token-number {
  color: var(--ks-navy);
  font-size: clamp(
    48px,
    7vw,
    78px
  );
  line-height: .88;
  letter-spacing: -.065em;
  font-weight: 950;
}


/* =========================================================
   STATUS MESSAGE
========================================================= */

.booking-status-message,
.token-current-message {
  border: 1px solid #dbe9df;
  border-radius: 15px;
  background:
    linear-gradient(
      135deg,
      #f3fbf5,
      #fbfdfb
    );
}


.booking-status-message strong,
.token-current-message strong {
  color: var(--ks-green-dark);
  font-size: 18px;
}


.booking-status-message span,
.token-current-message p {
  color: var(--ks-text-2);
  line-height: 1.6;
}


/* =========================================================
   DETAIL CARDS
========================================================= */

.home-detail,
.token-arrival-card,
.token-detail-item {
  border: 1px solid #e1eaec;
  background:
    linear-gradient(
      180deg,
      #ffffff,
      #f8fbfb
    );
  border-radius: 14px;
  box-shadow:
    0 2px 8px rgba(24, 59, 75, .025);
}


.home-detail:hover,
.token-arrival-card:hover,
.token-detail-item:hover {
  transform: translateY(-2px);
  border-color: #cbdde1;
  box-shadow: var(--ks-shadow-1);
}


.home-detail-icon,
.token-arrival-icon,
.token-detail-icon {
  border-radius: 12px;
}


/* =========================================================
   COLOURFUL ICON SYSTEM
========================================================= */

.home-detail:nth-child(1) .home-detail-icon,
.token-arrival-card:nth-child(1) .token-arrival-icon {
  color: var(--ks-blue);
  background: var(--ks-sky);
}


.home-detail:nth-child(2) .home-detail-icon,
.token-arrival-card:nth-child(2) .token-arrival-icon {
  color: var(--ks-saffron);
  background: var(--ks-saffron-soft);
}


.home-detail:nth-child(3) .home-detail-icon,
.token-arrival-card:nth-child(3) .token-arrival-icon {
  color: var(--ks-green);
  background: var(--ks-green-soft);
}


.token-detail-item:nth-child(1) .token-detail-icon {
  color: var(--ks-green);
  background: var(--ks-green-soft);
}


.token-detail-item:nth-child(2) .token-detail-icon {
  color: var(--ks-purple);
  background: var(--ks-purple-soft);
}


.token-detail-item:nth-child(3) .token-detail-icon {
  color: var(--ks-blue);
  background: var(--ks-sky);
}


.token-detail-item:nth-child(4) .token-detail-icon {
  color: var(--ks-saffron);
  background: var(--ks-saffron-soft);
}


.token-detail-item:nth-child(5) .token-detail-icon {
  color: var(--ks-green-dark);
  background: var(--ks-green-soft);
}


.token-detail-item:nth-child(6) .token-detail-icon {
  color: var(--ks-teal);
  background: var(--ks-teal-soft);
}


/* =========================================================
   PRIMARY ACTIONS
========================================================= */

.home-primary-action,
.token-primary-action {
  min-height: 50px;
  padding: 0 20px;
  border: 1px solid var(--ks-blue-dark);
  border-radius: 11px;
  color: #fff;
  background:
    linear-gradient(
      135deg,
      var(--ks-blue),
      var(--ks-blue-dark)
    );
  box-shadow:
    0 7px 18px rgba(33, 107, 145, .15);
  font-size: 11px;
  font-weight: 900;
}


.home-primary-action:hover,
.token-primary-action:hover {
  transform: translateY(-2px);
  box-shadow:
    0 12px 27px rgba(33, 107, 145, .19);
}


.home-secondary-action,
.token-secondary-action {
  min-height: 50px;
  padding: 0 19px;
  border: 1px solid var(--ks-border-strong);
  border-radius: 11px;
  color: var(--ks-text);
  background: #fff;
  font-size: 10px;
  font-weight: 850;
}


.home-secondary-action:hover,
.token-secondary-action:hover {
  border-color: #aec8d0;
  background: #f8fbfc;
}


/* =========================================================
   FEATURE CARDS
========================================================= */

.home-feature-card {
  position: relative;
  min-height: 215px;
  padding: 25px;
  overflow: hidden;
  border: 1px solid var(--ks-border);
  border-radius: var(--ks-radius-lg);
  background: #fff;
  box-shadow: var(--ks-shadow-1);
}


.home-feature-card::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 4px;
}


.home-feature-card:nth-child(1)::before {
  background: var(--ks-green);
}


.home-feature-card:nth-child(2)::before {
  background: var(--ks-blue);
}


.home-feature-card:nth-child(3)::before {
  background: var(--ks-saffron);
}


.home-feature-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--ks-shadow-3);
}


.home-feature-card h2 {
  color: var(--ks-navy);
  font-size: 23px;
  line-height: 1.05;
  letter-spacing: -.03em;
}


.home-feature-card p {
  color: var(--ks-text-2);
  font-size: 10px;
  line-height: 1.7;
}


.feature-icon {
  width: 50px;
  height: 50px;
  border-radius: 14px;
}


.booking-feature .feature-icon {
  color: var(--ks-green);
  background: var(--ks-green-soft);
}


.status-feature .feature-icon {
  color: var(--ks-blue);
  background: var(--ks-sky);
}


.help-feature .feature-icon {
  color: var(--ks-saffron);
  background: var(--ks-saffron-soft);
}


/* =========================================================
   JOURNEY / PROGRESS
========================================================= */

.farmer-progress-card {
  padding: 28px;
}


.farmer-current-stage {
  padding: 8px 11px;
  border: 1px solid #cbe2d2;
  border-radius: 999px;
  color: var(--ks-green-dark);
  background: var(--ks-green-soft);
  font-size: 8px;
  font-weight: 900;
}


.farmer-progress-stage span {
  color: var(--ks-text-2);
  font-size: 9px;
  font-weight: 900;
}


.farmer-progress-icon {
  width: 50px;
  height: 50px;
  border: 1px solid var(--ks-border);
  color: var(--ks-text-3);
  background: #fff;
  box-shadow: var(--ks-shadow-1);
}


.farmer-progress-stage.active .farmer-progress-icon {
  border-color: #bfd8e0;
  color: var(--ks-blue);
  background: var(--ks-sky);
}


.farmer-progress-stage.complete .farmer-progress-icon {
  border-color: #c4dfcd;
  color: var(--ks-green);
  background: var(--ks-green-soft);
}


.farmer-progress-line {
  height: 4px;
  border-radius: 999px;
  background: #dce7e9;
}


.farmer-progress-line.active {
  background:
    linear-gradient(
      90deg,
      var(--ks-blue),
      var(--ks-green)
    );
}


/* =========================================================
   SMS CARD
========================================================= */

.home-sms-card {
  padding: 22px;
  border-color: #cfdee3;
  background:
    linear-gradient(
      135deg,
      #f5fafc,
      #ffffff
    );
}


.home-sms-icon {
  width: 50px;
  height: 50px;
  border-radius: 14px;
  color: var(--ks-blue);
  background: var(--ks-sky);
}


.home-sms-card h3 {
  color: var(--ks-navy);
  font-size: 21px;
  letter-spacing: -.025em;
}


.home-sms-card p {
  color: var(--ks-text-2);
  font-size: 10px;
  line-height: 1.7;
}


/* =========================================================
   HISTORY
========================================================= */

.home-history-section {
  margin-top: 30px;
}


.home-history-list {
  overflow: hidden;
  border: 1px solid var(--ks-border);
  border-radius: 15px;
  background: #fff;
  box-shadow: var(--ks-shadow-1);
}


.home-history-item {
  min-height: 70px;
  border-bottom: 1px solid #edf2f3;
}


.home-history-item:last-child {
  border-bottom: 0;
}


.home-history-item:hover {
  background: #f7fbfb;
}


/* =========================================================
   TOKEN TIMELINE
========================================================= */

.token-status-card {
  padding: 30px;
}


.token-progress-bar {
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: #e3ecee;
}


.token-progress-bar > div {
  min-width: 3px;
  border-radius: inherit;
  background:
    linear-gradient(
      90deg,
      var(--ks-blue),
      var(--ks-green)
    );
}


.token-timeline-marker {
  width: 44px;
  height: 44px;
  border: 2px solid #dbe7ea;
  color: var(--ks-text-3);
  background: #fff;
}


.token-timeline-item.active
.token-timeline-marker {
  border-color: #b8d4df;
  color: var(--ks-blue);
  background: var(--ks-sky);
  box-shadow:
    0 0 0 6px rgba(33, 107, 145, .06);
}


.token-timeline-item.complete
.token-timeline-marker {
  border-color: #bddcc7;
  color: var(--ks-green);
  background: var(--ks-green-soft);
}


.token-timeline-title-row strong {
  color: var(--ks-navy);
  font-size: 14px;
}


.token-timeline-content p {
  color: var(--ks-text-2);
  font-size: 10px;
  line-height: 1.65;
}


.token-now-pill {
  padding: 5px 8px;
  border-radius: 999px;
  color: var(--ks-blue-dark);
  background: var(--ks-sky);
  font-size: 6px;
  font-weight: 900;
}


/* =========================================================
   TOKEN SIDE CARDS
========================================================= */

.token-side-card,
.token-visual-card {
  border: 1px solid var(--ks-border);
  border-radius: var(--ks-radius-lg);
  box-shadow: var(--ks-shadow-1);
}


.token-visual-card {
  overflow: hidden;
  background:
    linear-gradient(
      145deg,
      var(--ks-navy),
      var(--ks-blue-dark)
    );
  color: #fff;
}


.token-visual-number {
  font-size: clamp(
    42px,
    5vw,
    58px
  );
  font-weight: 950;
  letter-spacing: -.06em;
}


.token-visual-top span,
.token-visual-label {
  opacity: .85;
  font-weight: 900;
}


.token-visual-decoration span {
  background: rgba(255,255,255,.55);
}


.token-side-card {
  background: #fff;
}


.token-side-icon.green {
  color: var(--ks-green);
  background: var(--ks-green-soft);
}


.token-side-icon.blue {
  color: var(--ks-blue);
  background: var(--ks-sky);
}


.token-side-icon.gold {
  color: var(--ks-saffron);
  background: var(--ks-saffron-soft);
}


/* =========================================================
   ADMIN DASHBOARD
========================================================= */

.admin-dashboard-kpi-grid {
  gap: 13px;
}


.admin-dashboard-kpi {
  min-height: 116px;
  padding: 20px;
  border: 1px solid var(--ks-border);
  border-radius: 16px;
  background: #fff;
  box-shadow: var(--ks-shadow-1);
}


.admin-dashboard-kpi:hover {
  transform: translateY(-3px);
  box-shadow: var(--ks-shadow-2);
}


.admin-dashboard-kpi-icon {
  width: 45px;
  height: 45px;
  border-radius: 12px;
}


.admin-dashboard-kpi strong {
  color: var(--ks-navy);
  font-size: 29px;
  letter-spacing: -.03em;
}


.admin-dashboard-kpi span {
  color: var(--ks-text-3);
  font-size: 8px;
  font-weight: 900;
}


/* KPI palette */

.admin-dashboard-kpi.blue
.admin-dashboard-kpi-icon {
  color: var(--ks-blue);
  background: var(--ks-sky);
}


.admin-dashboard-kpi.purple
.admin-dashboard-kpi-icon {
  color: var(--ks-purple);
  background: var(--ks-purple-soft);
}


.admin-dashboard-kpi.gold
.admin-dashboard-kpi-icon {
  color: var(--ks-gold);
  background: var(--ks-gold-soft);
}


.admin-dashboard-kpi.green
.admin-dashboard-kpi-icon {
  color: var(--ks-green);
  background: var(--ks-green-soft);
}


.admin-dashboard-kpi.orange
.admin-dashboard-kpi-icon {
  color: var(--ks-saffron);
  background: var(--ks-saffron-soft);
}


.admin-dashboard-kpi.teal
.admin-dashboard-kpi-icon {
  color: var(--ks-teal);
  background: var(--ks-teal-soft);
}


/* =========================================================
   ADMIN PANELS
========================================================= */

.admin-dashboard-panel,
.admin-dashboard-alerts-panel,
.admin-dashboard-recent-panel,
.admin-payment-issues-list-card {
  border: 1px solid var(--ks-border);
  border-radius: var(--ks-radius-lg);
  background: #fff;
  box-shadow: var(--ks-shadow-1);
}


.admin-dashboard-panel-header {
  padding: 17px 18px 14px;
  border-bottom: 1px solid #edf2f3;
}


.admin-dashboard-panel-header h3,
.admin-payment-issues-list-header h3 {
  color: var(--ks-navy);
  font-size: 20px;
  letter-spacing: -.025em;
}


.admin-dashboard-panel-link {
  color: var(--ks-blue);
  font-weight: 900;
}


/* =========================================================
   ALERTS
========================================================= */

.admin-dashboard-alert-row {
  min-height: 62px;
  border-bottom: 1px solid #edf2f3;
}


.admin-dashboard-alert-row:hover {
  background: #f8fbfb;
}


.admin-dashboard-alert-icon {
  width: 38px;
  height: 38px;
  border-radius: 10px;
}


.admin-dashboard-alert-row.orange
.admin-dashboard-alert-icon {
  color: var(--ks-saffron);
  background: var(--ks-saffron-soft);
}


.admin-dashboard-alert-row.gold
.admin-dashboard-alert-icon {
  color: var(--ks-gold);
  background: var(--ks-gold-soft);
}


.admin-dashboard-alert-row.red
.admin-dashboard-alert-icon {
  color: var(--ks-red);
  background: var(--ks-red-soft);
}


.admin-dashboard-alert-row.purple
.admin-dashboard-alert-icon {
  color: var(--ks-purple);
  background: var(--ks-purple-soft);
}


/* =========================================================
   PAYMENT ISSUES FEATURE
========================================================= */

.admin-dashboard-payment-issues-card {
  position: relative;
  overflow: hidden;
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 16px;
  min-height: 118px;
  margin-bottom: 18px;
  padding: 20px;
  border-color: #ead9be;
  background:
    linear-gradient(
      135deg,
      #fff9f0,
      #ffffff
    );
}


.admin-dashboard-payment-issues-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 5px;
  background: var(--ks-saffron);
}


.admin-dashboard-payment-issues-icon {
  width: 48px;
  height: 48px;
  border-radius: 13px;
  color: var(--ks-saffron);
  background: var(--ks-saffron-soft);
}


.admin-dashboard-payment-issues-content h3 {
  color: var(--ks-navy);
  font-size: 21px;
}


.admin-dashboard-payment-issues-content p {
  color: var(--ks-text-2);
  font-size: 9px;
  line-height: 1.6;
}


.admin-dashboard-payment-issues-count strong {
  color: #a86925;
  font-size: 31px;
}


.admin-dashboard-payment-issues-count span {
  color: #9a866d;
  font-size: 7px;
  font-weight: 900;
}


.admin-dashboard-payment-issues-button {
  min-height: 40px;
  padding: 0 13px;
  border: 1px solid #dec7a4;
  border-radius: 9px;
  color: #8d632c;
  background: #fff8ec;
  font-size: 8px;
  font-weight: 900;
}


.admin-dashboard-payment-issues-button:hover {
  background: #fff0d7;
  transform: translateY(-1px);
}


/* =========================================================
   ADMIN QUEUE
========================================================= */

.admin-queue-filter-panel {
  border: 1px solid var(--ks-border);
  border-radius: 15px;
  background: #fff;
  box-shadow: var(--ks-shadow-1);
}


.admin-queue-search {
  border-color: #d8e4e7;
  background: #f9fbfb;
}


.admin-full-queue-table {
  overflow: hidden;
  border: 1px solid var(--ks-border);
  border-radius: 16px;
  background: #fff;
  box-shadow: var(--ks-shadow-1);
}


.admin-full-table-head {
  color: #67818b;
  background: #f2f7f8;
  border-bottom: 1px solid var(--ks-border);
  font-size: 8px;
  font-weight: 900;
}


.admin-full-table-row {
  min-height: 77px;
  border-bottom: 1px solid #edf2f3;
}


.admin-full-table-row:hover {
  background: #f8fbfb;
}


/* =========================================================
   STATUS PILLS
========================================================= */

.admin-status-pill,
.admin-dashboard-status {
  border-radius: 999px;
  font-weight: 900;
}


.admin-status-pill.blue,
.admin-dashboard-status.blue {
  color: var(--ks-blue-dark);
  background: var(--ks-sky);
}


.admin-status-pill.green,
.admin-dashboard-status.green {
  color: var(--ks-green-dark);
  background: var(--ks-green-soft);
}


.admin-status-pill.orange,
.admin-dashboard-status.orange {
  color: #a76420;
  background: var(--ks-saffron-soft);
}


.admin-status-pill.purple,
.admin-dashboard-status.purple {
  color: #625094;
  background: var(--ks-purple-soft);
}


.admin-status-pill.gold,
.admin-dashboard-status.gold {
  color: #946c21;
  background: var(--ks-gold-soft);
}


/* =========================================================
   ADMIN PAYMENT ISSUES
========================================================= */

.admin-payment-issues-filter {
  border: 1px solid var(--ks-border);
  border-radius: 14px;
  background: #fff;
  box-shadow: var(--ks-shadow-1);
}


.admin-payment-issues-search {
  border-color: #d8e4e7;
  background: #f9fbfb;
}


.admin-payment-issue-row {
  border-bottom: 1px solid #edf2f3;
}


.admin-payment-issue-row:hover {
  background: #f8fbfb;
}


.admin-payment-issue-icon.open {
  color: var(--ks-saffron);
  background: var(--ks-saffron-soft);
}


.admin-payment-issue-icon.resolved {
  color: var(--ks-green);
  background: var(--ks-green-soft);
}


.admin-payment-issue-status.open {
  color: #9e6724;
  background: var(--ks-saffron-soft);
}


.admin-payment-issue-status.resolved {
  color: var(--ks-green-dark);
  background: var(--ks-green-soft);
}


/* =========================================================
   EMPTY STATES
========================================================= */

.empty-state-card,
.admin-dashboard-empty,
.admin-queue-empty,
.admin-payment-issues-state,
.token-error-card,
.token-loading-card {
  border: 1px solid var(--ks-border);
  border-radius: var(--ks-radius-xl);
  background:
    linear-gradient(
      180deg,
      #ffffff,
      #f8fbfb
    );
  box-shadow: var(--ks-shadow-1);
}


.empty-state-icon,
.token-error-icon,
.token-loading-icon {
  width: 62px;
  height: 62px;
  border-radius: 17px;
  color: var(--ks-blue);
  background: var(--ks-sky);
}


/* =========================================================
   FOOTERS / SUPPORT LINKS
========================================================= */

.home-support-row {
  color: var(--ks-text-3);
  font-size: 8px;
}


.home-support-row a {
  color: var(--ks-blue);
  font-weight: 900;
}


/* =========================================================
   SMOOTH HOVER SYSTEM
========================================================= */

.next-booking-card,
.token-hero-card,
.token-status-card,
.token-details-card,
.farmer-progress-card,
.home-sms-card,
.admin-dashboard-panel,
.admin-dashboard-kpi,
.admin-dashboard-alerts-panel,
.admin-dashboard-payment-issues-card,
.admin-payment-issues-list-card {
  transition:
    box-shadow .25s var(--ks-ease),
    transform .25s var(--ks-ease),
    border-color .25s var(--ks-ease);
}


.next-booking-card:hover,
.token-hero-card:hover,
.token-status-card:hover,
.token-details-card:hover,
.farmer-progress-card:hover {
  box-shadow: var(--ks-shadow-3);
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 900px) {

  .farmer-welcome {
    align-items: stretch;
    flex-direction: column;
  }


  .farmer-profile {
    width: 100%;
  }


  .booking-main-details {
    grid-template-columns: 1fr;
  }


  .admin-dashboard-kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }


  .admin-dashboard-payment-issues-card {
    grid-template-columns: 48px minmax(0, 1fr);
  }


  .admin-dashboard-payment-issues-count,
  .admin-dashboard-payment-issues-button {
    grid-column: 2;
  }

}


@media (max-width: 650px) {

  .farmer-welcome h1 {
    font-size: 36px;
  }


  .admin-dashboard-hero h2,
  .admin-queue-hero h2,
  .admin-payment-issues-hero h2 {
    font-size: 36px;
  }


  .next-booking-card,
  .token-hero-card,
  .token-status-card,
  .token-details-card,
  .farmer-progress-card {
    padding: 20px;
    border-radius: 18px;
  }


  .home-token {
    font-size: 47px;
  }


  .token-number {
    font-size: 54px;
  }


  .booking-action-row,
  .token-bottom-actions {
    flex-direction: column;
  }


  .home-primary-action,
  .home-secondary-action,
  .token-primary-action,
  .token-secondary-action {
    width: 100%;
    justify-content: center;
  }


  .farmer-home-grid {
    grid-template-columns: 1fr;
  }


  .admin-dashboard-kpi-grid {
    grid-template-columns: 1fr;
  }


  .admin-dashboard-payment-issues-card {
    grid-template-columns: 1fr;
  }


  .admin-dashboard-payment-issues-icon {
    width: 48px;
  }


  .admin-dashboard-payment-issues-count,
  .admin-dashboard-payment-issues-button {
    grid-column: auto;
  }


  .admin-dashboard-payment-issues-button {
    width: 100%;
  }


  .admin-full-table-head {
    font-size: 7px;
  }

}


@media (max-width: 450px) {

  .farmer-welcome h1,
  .admin-dashboard-hero h2,
  .admin-queue-hero h2,
  .admin-payment-issues-hero h2 {
    font-size: 32px;
  }


  .home-token {
    font-size: 42px;
  }


  .token-number {
    font-size: 48px;
  }


  .home-feature-card {
    min-height: 180px;
  }


  .home-feature-card h2 {
    font-size: 20px;
  }

}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

  html {
    scroll-behavior: auto;
  }


  *,
  *::before,
  *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }

}


/* =========================================================
   KRISHISETU — FINAL UI SYSTEM
   Strong hierarchy + colourful text + clear navigation
   + complete dark mode
========================================================= */


/* =========================================================
   1. LIGHT THEME
========================================================= */

:root {

  --ks-bg: #f2f7f8;
  --ks-bg-2: #e8f1f3;

  --ks-surface: #ffffff;
  --ks-surface-2: #f8fbfb;
  --ks-surface-3: #eef5f6;

  --ks-primary: #165d80;
  --ks-primary-dark: #0d4662;
  --ks-primary-light: #e6f3f8;

  --ks-green: #217a49;
  --ks-green-light: #e8f6ed;

  --ks-orange: #c87820;
  --ks-orange-light: #fff1de;

  --ks-red: #b94f47;
  --ks-red-light: #fff0ee;

  --ks-purple: #66529b;
  --ks-purple-light: #f0edfa;

  --ks-teal: #177a76;
  --ks-teal-light: #e7f7f5;

  --ks-gold: #98701f;
  --ks-gold-light: #fff5dc;

  --ks-heading: #153f57;
  --ks-text: #365d6c;
  --ks-text-soft: #6b858e;
  --ks-text-muted: #91a2a8;

  --ks-border: #d9e5e8;
  --ks-border-strong: #bfd1d6;

  --ks-shadow-small:
    0 3px 12px rgba(20, 57, 73, .05);

  --ks-shadow-medium:
    0 10px 28px rgba(20, 57, 73, .08);

  --ks-shadow-large:
    0 20px 55px rgba(20, 57, 73, .11);

  --ks-radius-sm: 9px;
  --ks-radius-md: 14px;
  --ks-radius-lg: 18px;
  --ks-radius-xl: 24px;
}


/* =========================================================
   2. REAL PAGE BACKGROUND
========================================================= */

html,
body,
#root {

  min-height: 100%;

}


body {

  margin: 0;

  color: var(--ks-text);

  background:
    radial-gradient(
      circle at 0% 0%,
      rgba(33, 122, 73, .08),
      transparent 24%
    ),
    radial-gradient(
      circle at 100% 0%,
      rgba(22, 93, 128, .10),
      transparent 26%
    ),
    linear-gradient(
      180deg,
      var(--ks-bg),
      #f8fbfa
    );

}


.farmer-home-page,
.farmer-token-page,
.admin-dashboard-page,
.admin-queue-page,
.admin-payment-issues-page {

  min-height: 100vh;

  background: transparent;

}


/* =========================================================
   3. GOVERNMENT-STYLE TOP STRIPE
========================================================= */

.farmer-home-page::before,
.farmer-token-page::before,
.admin-dashboard-page::before,
.admin-queue-page::before,
.admin-payment-issues-page::before {

  content: "";

  position: fixed;

  top: 0;
  left: 0;
  right: 0;

  z-index: 1000;

  height: 4px;

  background:
    linear-gradient(
      90deg,
      #d47a20 0 33.33%,
      #f8faf9 33.33% 66.66%,
      #318552 66.66% 100%
    );

}


/* =========================================================
   4. HEADINGS
========================================================= */

.farmer-welcome h1,
.admin-dashboard-hero h2,
.admin-queue-hero h2,
.admin-payment-issues-hero h2 {

  margin-bottom: 10px;

  color: var(--ks-heading);

  font-weight: 950;

  letter-spacing: -.045em;

  text-wrap: balance;

}


.farmer-welcome h1 {

  font-size: clamp(
    38px,
    5vw,
    64px
  );

  line-height: .96;

}


.admin-dashboard-hero h2,
.admin-queue-hero h2,
.admin-payment-issues-hero h2 {

  font-size: clamp(
    38px,
    4.7vw,
    58px
  );

  line-height: .94;

}


.farmer-welcome h1::first-line,
.admin-dashboard-hero h2::first-line,
.admin-queue-hero h2::first-line {

  color: var(--ks-primary);

}


.farmer-welcome p,
.admin-dashboard-hero p,
.admin-queue-hero p {

  color: var(--ks-text-soft);

  font-size: 13px;

  line-height: 1.75;

}


/* =========================================================
   5. EYEBROWS — STRONG COLOUR
========================================================= */

.page-eyebrow,
.admin-page-eyebrow,
.card-eyebrow,
.token-card-label {

  display: inline-block;

  color: var(--ks-orange);

  font-size: 10px;

  font-weight: 950;

  letter-spacing: .15em;

}


.page-eyebrow::before,
.admin-page-eyebrow::before {

  content: "";

  display: inline-block;

  width: 7px;
  height: 7px;

  margin-right: 7px;

  border-radius: 50%;

  background: currentColor;

  vertical-align: middle;

}


/* =========================================================
   6. PROFILE / USER AREA
========================================================= */

.farmer-profile {

  border:
    1px solid var(--ks-border);

  border-radius:
    var(--ks-radius-lg);

  background:
    linear-gradient(
      135deg,
      var(--ks-surface),
      var(--ks-surface-2)
    );

  box-shadow:
    var(--ks-shadow-small);

}


.farmer-profile strong {

  color: var(--ks-heading);

  font-size: 14px;

}


.farmer-profile span {

  color: var(--ks-text-soft);

}


/* =========================================================
   7. MAIN PRIORITY CARD
========================================================= */

.next-booking-card {

  position: relative;

  overflow: hidden;

  padding: 30px;

  border:
    1px solid var(--ks-border);

  border-radius:
    var(--ks-radius-xl);

  background:
    linear-gradient(
      145deg,
      #ffffff,
      #f7fbfa
    );

  box-shadow:
    var(--ks-shadow-medium);

}


.next-booking-card::before {

  content: "";

  position: absolute;

  left: 0;
  top: 0;
  bottom: 0;

  width: 6px;

  background:
    linear-gradient(
      180deg,
      var(--ks-orange),
      var(--ks-green)
    );

}


.next-booking-card::after {

  content: "";

  position: absolute;

  width: 250px;
  height: 250px;

  right: -120px;
  top: -120px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(33, 122, 73, .11),
      transparent 68%
    );

  pointer-events: none;

}


/* =========================================================
   8. TOKEN NUMBER
========================================================= */

.home-token,
.token-number {

  color: var(--ks-primary-dark);

  font-weight: 950;

  letter-spacing: -.065em;

  text-shadow:
    0 2px 0 rgba(255,255,255,.7);

}


.home-token {

  font-size: clamp(
    46px,
    6vw,
    72px
  );

}


.token-number {

  font-size: clamp(
    52px,
    7vw,
    82px
  );

}


/* =========================================================
   9. STATUS MESSAGE
========================================================= */

.booking-status-message {

  border:
    1px solid #cfe4d5;

  border-radius:
    var(--ks-radius-md);

  background:
    linear-gradient(
      135deg,
      var(--ks-green-light),
      #ffffff
    );

}


.booking-status-message strong {

  color: var(--ks-green-dark, #1d663e);

  font-size: 18px;

}


.booking-status-message span {

  color: var(--ks-text);

}


/* =========================================================
   10. DETAIL CARDS
========================================================= */

.home-detail,
.token-arrival-card,
.token-detail-item {

  border:
    1px solid var(--ks-border);

  border-radius:
    var(--ks-radius-md);

  background:
    var(--ks-surface);

  box-shadow:
    var(--ks-shadow-small);

}


.home-detail:hover,
.token-arrival-card:hover,
.token-detail-item:hover {

  transform:
    translateY(-3px);

  border-color:
    var(--ks-border-strong);

  box-shadow:
    var(--ks-shadow-medium);

}


/* =========================================================
   11. COLOURFUL DETAIL ICONS
========================================================= */

.home-detail:nth-child(1) .home-detail-icon,
.token-arrival-card:nth-child(1) .token-arrival-icon {

  color: var(--ks-primary);

  background: var(--ks-primary-light);

}


.home-detail:nth-child(2) .home-detail-icon,
.token-arrival-card:nth-child(2) .token-arrival-icon {

  color: var(--ks-orange);

  background: var(--ks-orange-light);

}


.home-detail:nth-child(3) .home-detail-icon,
.token-arrival-card:nth-child(3) .token-arrival-icon {

  color: var(--ks-green);

  background: var(--ks-green-light);

}


/* =========================================================
   12. BIG PRIMARY BUTTONS
========================================================= */

.home-primary-action,
.token-primary-action {

  min-height: 52px;

  padding:
    0 22px;

  border:
    1px solid var(--ks-primary-dark);

  border-radius:
    12px;

  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      var(--ks-primary),
      var(--ks-primary-dark)
    );

  box-shadow:
    0 8px 22px rgba(22, 93, 128, .18);

  font-size:
    11px;

  font-weight:
    950;

}


.home-primary-action:hover,
.token-primary-action:hover {

  transform:
    translateY(-3px);

  box-shadow:
    0 14px 30px rgba(22, 93, 128, .23);

}


/* =========================================================
   13. SECONDARY BUTTON
========================================================= */

.home-secondary-action,
.token-secondary-action {

  min-height: 52px;

  padding:
    0 20px;

  border:
    1px solid var(--ks-border-strong);

  border-radius:
    12px;

  color:
    var(--ks-primary-dark);

  background:
    var(--ks-surface);

  font-size:
    10px;

  font-weight:
    900;

}


.home-secondary-action:hover,
.token-secondary-action:hover {

  color:
    var(--ks-primary);

  border-color:
    var(--ks-primary);

  background:
    var(--ks-primary-light);

}


/* =========================================================
   14. FEATURE CARDS — MAKE DESTINATIONS OBVIOUS
========================================================= */

.farmer-home-grid {

  gap: 16px;

}


.home-feature-card {

  position: relative;

  min-height: 225px;

  padding: 26px;

  overflow: hidden;

  border:
    1px solid var(--ks-border);

  border-radius:
    var(--ks-radius-lg);

  background:
    var(--ks-surface);

  box-shadow:
    var(--ks-shadow-small);

}


.home-feature-card::before {

  content: "";

  position: absolute;

  left: 0;
  right: 0;
  top: 0;

  height: 5px;

}


.home-feature-card:nth-child(1)::before {

  background: var(--ks-green);

}


.home-feature-card:nth-child(2)::before {

  background: var(--ks-primary);

}


.home-feature-card:nth-child(3)::before {

  background: var(--ks-orange);

}


.home-feature-card:hover {

  transform:
    translateY(-6px);

  box-shadow:
    var(--ks-shadow-large);

}


/* BIG CLICKABLE TITLE */

.home-feature-card h2 {

  margin-top: 30px;

  color:
    var(--ks-heading);

  font-size:
    24px;

  line-height:
    1.04;

  letter-spacing:
    -.035em;

}


/* MAKE DESTINATION WORDS COLOURFUL */

.booking-feature h2 {

  color:
    var(--ks-green);

}


.status-feature h2 {

  color:
    var(--ks-primary);

}


.help-feature h2 {

  color:
    var(--ks-orange);

}


.home-feature-card p {

  color:
    var(--ks-text-soft);

  font-size:
    11px;

  line-height:
    1.7;

}


/* CLICK / OPEN HINT */

.home-feature-card::after {

  content:
    "OPEN";

  position:
    absolute;

  right:
    22px;

  bottom:
    20px;

  padding:
    6px 9px;

  border-radius:
    999px;

  font-size:
    7px;

  font-weight:
    950;

  letter-spacing:
    .08em;

  opacity:
    .78;

}


.booking-feature::after {

  color:
    var(--ks-green);

  background:
    var(--ks-green-light);

}


.status-feature::after {

  color:
    var(--ks-primary);

  background:
    var(--ks-primary-light);

}


.help-feature::after {

  color:
    var(--ks-orange);

  background:
