/* =========================================================
   27. MOBILE
========================================================= */

@media (max-width: 900px) {

  .farmer-welcome {

    flex-direction:
      column;

    align-items:
      stretch;

  }


  .admin-dashboard-kpi-grid {

    grid-template-columns:
      repeat(2, 1fr);

  }

}


@media (max-width: 650px) {

  .farmer-welcome h1,
  .admin-dashboard-hero h2,
  .admin-queue-hero h2,
  .admin-payment-issues-hero h2 {

    font-size:
      34px;

  }


  .next-booking-card,
  .token-status-card,
  .token-details-card,
  .farmer-progress-card {

    padding:
      20px;

    border-radius:
      18px;

  }


  .home-token {

    font-size:
      46px;

  }


  .token-number {

    font-size:
      52px;

  }


  .booking-action-row,
  .token-bottom-actions {

    flex-direction:
      column;

  }


  .home-primary-action,
  .home-secondary-action,
  .token-primary-action,
  .token-secondary-action {

    width:
      100%;

    justify-content:
      center;

  }


  .farmer-home-grid {

    grid-template-columns:
      1fr;

  }


  .admin-dashboard-kpi-grid {

    grid-template-columns:
      1fr;

  }


  .admin-dashboard-payment-issues-card {

    grid-template-columns:
      1fr;

  }

}


@media (prefers-reduced-motion: reduce) {

  html {

    scroll-behavior:
      auto;

  }


  *,
  *::before,
  *::after {

    animation:
      none !important;

    transition:
      none !important;

  }

}


