    var(--ks-text-soft) !important;

}


/* =========================================================
   DARK — COLOURFUL LARGE NUMBERS
========================================================= */

html.dark .home-token,
html.dark .token-number {

  color:
    var(--ks-primary-dark) !important;

}


/* =========================================================
   DARK — FEATURE TITLE COLOURS
========================================================= */

html.dark .booking-feature h2 {
  color: var(--ks-green) !important;
}


html.dark .status-feature h2 {
  color: var(--ks-primary-dark) !important;
}


html.dark .help-feature h2 {
  color: var(--ks-orange) !important;
}


/* =========================================================
   DARK — STATUS MESSAGE
========================================================= */

html.dark .booking-status-message,
html.dark .token-current-message {

  border-color:
    #315b44 !important;

  background:
    linear-gradient(
      135deg,
      #15372a,
      #10242c
    ) !important;

}


html.dark .booking-status-message strong,
html.dark .token-current-message strong {

  color:
    var(--ks-green) !important;

}


/* =========================================================
   DARK — SMS CARD
========================================================= */

html.dark .home-sms-card {

  border-color:
    #315360 !important;

  background:
    linear-gradient(
      135deg,
      #12313d,
      #10242c
    ) !important;

}


/* =========================================================
   DARK — PAYMENT ISSUE
========================================================= */

html.dark .admin-dashboard-payment-issues-card {

  border-color:
    #5c482b !important;

  background:
    linear-gradient(
      135deg,
      #332817,
      #18252a
    ) !important;

}


html.dark .admin-dashboard-payment-issues-content h3 {

  color:
    #f0c078 !important;

}


/* =========================================================
   DARK — INPUTS
========================================================= */

html.dark input,
html.dark select,
html.dark textarea {

  color:
    var(--ks-text) !important;

  background:
    #0d2027 !important;

  border-color:
    var(--ks-border) !important;

}


html.dark input:focus,
html.dark select:focus,
html.dark textarea:focus {

  border-color:
    var(--ks-primary) !important;

  box-shadow:
    0 0 0 3px rgba(109, 192, 223, .10);

}


html.dark input::placeholder,
html.dark textarea::placeholder {

  color:
    var(--ks-text-muted) !important;

}


/* =========================================================
   DARK — TABLE
========================================================= */

html.dark .admin-full-table-head {

  color:
    var(--ks-text-soft) !important;

  background:
    #162d35 !important;

  border-color:
    var(--ks-border) !important;

}


html.dark .admin-full-table-row {

  color:
    var(--ks-text) !important;

  background:
    var(--ks-surface) !important;

  border-color:
    #243c44 !important;

}


html.dark .admin-full-table-row:hover {

  background:
    #19323b !important;

}


/* =========================================================
   DARK — BUTTONS
========================================================= */

html.dark .home-secondary-action,
html.dark .token-secondary-action,
html.dark .farmer-refresh-button,
html.dark .token-refresh-button,
html.dark .admin-dashboard-refresh,
html.dark .admin-queue-refresh-button {

  color:
    var(--ks-primary-dark) !important;

  background:
    #142b34 !important;

  border-color:
    var(--ks-border-strong) !important;

}


html.dark .home-secondary-action:hover,
html.dark .token-secondary-action:hover,
html.dark .farmer-refresh-button:hover,
html.dark .token-refresh-button:hover {

  background:
    #19353e !important;

}


/* =========================================================
   DARK — PRIMARY ACTION
========================================================= */

html.dark .home-primary-action,
html.dark .token-primary-action {

  color:
    #06141a !important;

  background:
    linear-gradient(
      135deg,
      #70c2df,
      #68c995
    ) !important;

  border-color:
    transparent !important;

  box-shadow:
    0 10px 26px rgba(0,0,0,.25);

}


html.dark .home-primary-action:hover,
html.dark .token-primary-action:hover {

  box-shadow:
    0 15px 32px rgba(0,0,0,.32);

}


/* =========================================================
   DARK — STATUS PILLS
========================================================= */

html.dark .admin-status-pill.blue,
html.dark .admin-dashboard-status.blue {

  color:
    #93d8ef !important;

  background:
    #173a48 !important;

}


html.dark .admin-status-pill.green,
html.dark .admin-dashboard-status.green {

  color:
    #88dda3 !important;

  background:
    #183b2a !important;

}


html.dark .admin-status-pill.orange,
html.dark .admin-dashboard-status.orange {

  color:
    #f2bb73 !important;

  background:
    #3d2c1c !important;

}


html.dark .admin-status-pill.purple,
html.dark .admin-dashboard-status.purple {

  color:
    #b9a8ed !important;

  background:
    #2c2542 !important;

}


html.dark .admin-status-pill.gold,
html.dark .admin-dashboard-status.gold {

  color:
    #e2c571 !important;

  background:
    #392f1b !important;

}


/* =========================================================
   DARK — PROGRESS
========================================================= */

html.dark .farmer-progress-line,
html.dark .token-progress-bar {

  background:
    #20383f !important;

}


html.dark .farmer-progress-line.active,
html.dark .token-progress-bar > div {

  background:
    linear-gradient(
      90deg,
      #66b7d8,
      #68c78e
    ) !important;

}


/* =========================================================
   DARK — VISUAL TOKEN CARD
========================================================= */

html.dark .token-visual-card {

  background:
    linear-gradient(
      145deg,
      #0f3243,
      #12392f
    ) !important;

}


/* =========================================================
   DARK — DRAWERS / OVERLAYS
========================================================= */

html.dark .admin-booking-drawer,
html.dark .admin-booking-drawer > div {

  color:
    var(--ks-text);

}


html.dark .admin-booking-drawer {

  background:
    var(--ks-surface) !important;

}


/* =========================================================
   28. MOBILE READABILITY
========================================================= */

@media (max-width: 650px) {

  .page-eyebrow,
  .admin-page-eyebrow,
  .card-eyebrow,
  .token-card-label {
    font-size: 11px !important;
  }


  .home-detail span,
  .home-detail small,
  .token-arrival-card span,
  .token-detail-item span,
  .token-timeline-content p,
  .home-feature-card p,
  .home-sms-card p {
    font-size: 11px !important;
  }


  .home-detail strong,
  .token-arrival-card strong,
  .token-detail-item strong {
    font-size: 14px !important;
  }


  .home-feature-card h2 {
    font-size: 22px !important;
  }


  .admin-dashboard-panel-header h3,
  .admin-payment-issues-list-header h3 {
    font-size: 20px !important;
  }


  .home-primary-action,
  .home-secondary-action,
  .token-primary-action,
  .token-secondary-action {
    font-size: 12px !important;
  }

}

/* =========================================================
   KRISHISETU — FARMER BOOKING PAGE
========================================================= */


/* =========================================================
   PAGE
========================================================= */

.farmer-book-page {
  min-height: 100vh;
  background:
    radial-gradient(
      circle at 5% 0%,
      rgba(33, 122, 73, .08),
      transparent 24%
    ),
    radial-gradient(
      circle at 95% 0%,
      rgba(22, 93, 128, .09),
      transparent 25%
    ),
    linear-gradient(
      180deg,
      #f1f7f7 0%,
      #f8fbfa 100%
    );
}


.farmer-book-container {
  width: min(
    1180px,
    calc(100% - 32px)
  );

  margin:
    0 auto;

  padding:
    38px 0 70px;
}


/* =========================================================
   HERO
========================================================= */

.farmer-book-hero {
  display:
    flex;

  align-items:
    flex-end;

  justify-content:
    space-between;

  gap:
    28px;

  margin-bottom:
    28px;
}


.farmer-book-hero h1 {
  margin-top:
    10px;

  color:
    var(--ks-primary-dark);

  font-size:
    clamp(
      38px,
      5vw,
      64px
    );

  line-height:
    .95;

  letter-spacing:
    -.055em;

  font-weight:
    950;

  text-wrap:
    balance;
}


.farmer-book-hero p {
  max-width:
    700px;

  margin-top:
    13px;

  color:
    var(--ks-text-soft);

  font-size:
    13px;

  line-height:
    1.75;
}


/* =========================================================
   BOOKING STEP INDICATOR
========================================================= */

.farmer-book-steps {
  display:
    flex;

  align-items:
    center;

  gap:
    10px;

  padding:
    13px 16px;

  margin-bottom:
    20px;

  border:
    1px solid var(--ks-border);

  border-radius:
    15px;

  background:
    var(--ks-surface);

  box-shadow:
    var(--ks-shadow-small);

  overflow-x:
    auto;
}


.farmer-book-step {
  display:
    flex;

  align-items:
    center;

  gap:
    8px;

  min-width:
    max-content;

  color:
    var(--ks-text-muted);

  font-size:
    10px;

  font-weight:
    900;
}


.farmer-book-step-number {
  display:
    grid;

  place-items:
    center;

  width:
    30px;

  height:
    30px;

  border-radius:
    50%;

  border:
    1px solid var(--ks-border);

  color:
    var(--ks-text-muted);

  background:
    var(--ks-surface-2);

  font-size:
    10px;

  font-weight:
    950;
}


.farmer-book-step.active {
  color:
    var(--ks-primary);
}


.farmer-book-step.active
.farmer-book-step-number {

  color:
    #ffffff;

  border-color:
    var(--ks-primary);

  background:
    var(--ks-primary);

  box-shadow:
    0 5px 14px rgba(22, 93, 128, .16);

}


.farmer-book-step.complete {
  color:
    var(--ks-green);
}


.farmer-book-step.complete
.farmer-book-step-number {

  color:
    #ffffff;

  border-color:
    var(--ks-green);

  background:
    var(--ks-green);

}


.farmer-book-step-line {
  flex:
    1;

  min-width:
    18px;

  height:
    3px;

  border-radius:
    999px;

  background:
    var(--ks-border);
}


.farmer-book-step-line.active {
  background:
    linear-gradient(
      90deg,
      var(--ks-primary),
      var(--ks-green)
    );
}


/* =========================================================
   MAIN FORM LAYOUT
========================================================= */

.farmer-book-layout {
  display:
    grid;

  grid-template-columns:
    minmax(0, 1.55fr)
    minmax(290px, .75fr);

  gap:
    22px;

  align-items:
    start;
}


/* =========================================================
   FORM CARD
========================================================= */

.farmer-book-card {
  padding:
    28px;

  border:
    1px solid var(--ks-border);

  border-radius:
    var(--ks-radius-xl);

  background:
    var(--ks-surface);

  box-shadow:
    var(--ks-shadow-medium);
}


.farmer-book-card-header {
  padding-bottom:
    20px;

  margin-bottom:
    22px;

  border-bottom:
    1px solid var(--ks-border);
}


.farmer-book-card-header h2 {
  margin-top:
    7px;

  color:
    var(--ks-primary);

  font-size:
    clamp(
      27px,
      3vw,
      39px
    );

  line-height:
    1;

  letter-spacing:
    -.04em;
}


.farmer-book-card-header p {
  max-width:
    680px;

  margin-top:
    8px;

  color:
    var(--ks-text-soft);

  font-size:
    12px;

  line-height:
    1.65;
}


/* =========================================================
   FORM SECTIONS
========================================================= */

.farmer-book-section {
  padding:
    20px 0;

  border-bottom:
    1px solid var(--ks-border);
}


.farmer-book-section:last-child {
  border-bottom:
    0;

  padding-bottom:
    0;
}


.farmer-book-section-title {
  display:
    flex;

  align-items:
    center;

  gap:
    11px;

  margin-bottom:
    16px;
}


.farmer-book-section-icon {
  display:
    grid;

  place-items:
    center;

  width:
    42px;

  height:
    42px;

  border-radius:
    12px;

  color:
    var(--ks-primary);

  background:
    var(--ks-primary-light);
}


.farmer-book-section-title h3 {
  color:
    var(--ks-heading);

  font-size:
    18px;

  letter-spacing:
    -.02em;
}


/* =========================================================
   LABELS
========================================================= */

.farmer-book-card label {
  display:
    block;

  margin-bottom:
    8px;

  color:
    var(--ks-text);

  font-size:
    12px;

  font-weight:
    900;
}


/* =========================================================
   INPUTS
========================================================= */

.farmer-book-card input,
.farmer-book-card select,
.farmer-book-card textarea {

  min-height:
    48px;

  width:
    100%;

  padding:
    0 14px;

  border:
    1px solid var(--ks-border-strong);

  border-radius:
    11px;

  color:
    var(--ks-heading);

  background:
    var(--ks-surface-2);

  font-size:
    13px;

  transition:
    border-color .2s ease,
    box-shadow .2s ease,
    background-color .2s ease;
}


.farmer-book-card textarea {
  padding:
    13px 14px;

  min-height:
    110px;
}


.farmer-book-card input:hover,
.farmer-book-card select:hover,
.farmer-book-card textarea:hover {
  border-color:
    #a9c3ca;
}


.farmer-book-card input:focus,
.farmer-book-card select:focus,
.farmer-book-card textarea:focus {

  border-color:
    var(--ks-primary);

  background:
    var(--ks-surface);

  outline:
    none;

  box-shadow:
    0 0 0 4px rgba(22, 93, 128, .09);
}


/* =========================================================
   CROP SELECTION
========================================================= */

.farmer-book-crop-grid {
  display:
    grid;

  grid-template-columns:
    repeat(
      4,
      minmax(0, 1fr)
    );

  gap:
    11px;
}


.farmer-book-crop-option {
  position:
    relative;

  min-height:
    96px;

  padding:
    14px;

  border:
    1px solid var(--ks-border);

  border-radius:
    14px;

  background:
    var(--ks-surface-2);

  text-align:
    left;

  cursor:
    pointer;
}


.farmer-book-crop-option:hover {

  transform:
    translateY(-2px);

  border-color:
    #b9d2d8;

  box-shadow:
    var(--ks-shadow-small);
}


.farmer-book-crop-option.active {

  border-color:
    var(--ks-green);

  background:
    var(--ks-green-light);

  box-shadow:
    0 0 0 3px rgba(33, 122, 73, .08);

}


.farmer-book-crop-option strong {

  display:
    block;

  margin-top:
    12px;

  color:
    var(--ks-heading);

  font-size:
    14px;
}


.farmer-book-crop-option.active strong {
  color:
    var(--ks-green);
}


/* =========================================================
   QUANTITY
========================================================= */

.farmer-book-quantity-card {

  display:
    grid;

  grid-template-columns:
    minmax(0, 1fr)
    auto;

  gap:
    15px;

  align-items:
    end;

}


.farmer-book-quantity-unit {

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  min-height:
    48px;

  padding:
    0 18px;

  border-radius:
    11px;

  color:
    var(--ks-green);

  background:
    var(--ks-green-light);

  font-size:
    13px;

  font-weight:
    950;
}


/* =========================================================
   CENTER CARDS
========================================================= */

.farmer-book-center-grid {

  display:
    grid;

  grid-template-columns:
    repeat(
      2,
      minmax(0, 1fr)
    );

  gap:
    12px;
}


.farmer-book-center-option {

  position:
    relative;

  display:
    flex;

  align-items:
    flex-start;

  gap:
    12px;

  padding:
    16px;

  border:
    1px solid var(--ks-border);

  border-radius:
    14px;

  background:
    var(--ks-surface-2);

  text-align:
    left;

  cursor:
    pointer;
}


.farmer-book-center-option:hover {

  transform:
    translateY(-2px);

  border-color:
    #b9d2d8;

}


.farmer-book-center-option.active {

  border-color:
    var(--ks-primary);

  background:
    var(--ks-primary-light);

  box-shadow:
    0 0 0 3px rgba(22, 93, 128, .07);

}


.farmer-book-center-icon {

  display:
    grid;

  place-items:
    center;

  width:
    42px;

  height:
    42px;

  flex:
    0 0 42px;

  border-radius:
    11px;

  color:
    var(--ks-primary);

  background:
    #dceff6;

}


.farmer-book-center-option strong {

  color:
    var(--ks-heading);

  font-size:
    14px;

}


.farmer-book-center-option span {

  display:
    block;

  margin-top:
    4px;

  color:
    var(--ks-text-soft);

  font-size:
    10px;

  line-height:
    1.5;
}


/* =========================================================
   DATE / SLOT
========================================================= */

.farmer-book-date-grid {

  display:
    grid;

  grid-template-columns:
    repeat(
      2,
      minmax(0, 1fr)
    );

  gap:
    12px;

}


.farmer-book-slot-grid {

  display:
    grid;

  grid-template-columns:
    repeat(
      2,
      minmax(0, 1fr)
    );

  gap:
    10px;

  margin-top:
    12px;
}


.farmer-book-slot-option {

  min-height:
    62px;

  padding:
    12px;

  border:
    1px solid var(--ks-border);

  border-radius:
    12px;

  color:
    var(--ks-text);

  background:
    var(--ks-surface-2);

  text-align:
    left;

  cursor:
    pointer;
}


.farmer-book-slot-option:hover {

  transform:
    translateY(-2px);

  border-color:
    #b6d0d8;

}


.farmer-book-slot-option.active {

  color:
    var(--ks-primary-dark);

  border-color:
    var(--ks-primary);

  background:
    var(--ks-primary-light);

}


.farmer-book-slot-option strong {

  display:
    block;

  font-size:
    13px;
}


.farmer-book-slot-option span {

  display:
    block;

  margin-top:
    4px;

  color:
    var(--ks-text-soft);

  font-size:
    10px;
}


/* =========================================================
   SIDEBAR SUMMARY
========================================================= */

.farmer-book-summary {

  position:
    sticky;

  top:
    90px;

  padding:
    23px;

  border:
    1px solid var(--ks-border);

  border-radius:
    var(--ks-radius-lg);

  background:
    linear-gradient(
      145deg,
      #ffffff,
      #f6fbfa
    );

  box-shadow:
    var(--ks-shadow-medium);

}


.farmer-book-summary-title {

  color:
    var(--ks-primary);

  font-size:
    12px;

  font-weight:
    950;

  letter-spacing:
    .12em;
}


.farmer-book-summary h2 {

  margin-top:
    8px;

  color:
    var(--ks-heading);

  font-size:
    28px;

  line-height:
    1.05;

  letter-spacing:
    -.035em;

}


.farmer-book-summary-list {

  display:
    grid;

  gap:
    10px;

  margin-top:
    20px;

}


.farmer-book-summary-item {

  display:
    grid;

  grid-template-columns:
    38px minmax(0, 1fr);

  gap:
    10px;

  padding:
    12px;

  border:
    1px solid var(--ks-border);

  border-radius:
    12px;

  background:
    var(--ks-surface);

}


.farmer-book-summary-item-icon {

  display:
    grid;

  place-items:
    center;

  width:
    38px;

  height:
    38px;

  border-radius:
    10px;

  color:
    var(--ks-blue);

  background:
    var(--ks-primary-light);

}


.farmer-book-summary-item:nth-child(2)
.farmer-book-summary-item-icon {

  color:
    var(--ks-green);

  background:
    var(--ks-green-light);

}


.farmer-book-summary-item:nth-child(3)
.farmer-book-summary-item-icon {

  color:
    var(--ks-orange);

  background:
    var(--ks-orange-light);

}


.farmer-book-summary-item span {

  display:
    block;

  color:
    var(--ks-text-muted);

  font-size:
    9px;

  font-weight:
    800;
}


.farmer-book-summary-item strong {

  display:
    block;

  margin-top:
    4px;

  color:
    var(--ks-heading);

  font-size:
    13px;

}


/* =========================================================
   SUMMARY ACTION
========================================================= */

.farmer-book-submit {

  display:
    flex;

  align-items:
    center;

  justify-content:
    space-between;

  gap:
    12px;

  width:
    100%;

  min-height:
    54px;

  margin-top:
    20px;

  padding:
    0 18px;

  border:
    0;

  border-radius:
    12px;

  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      var(--ks-green),
      var(--ks-green-dark, #1b633b)
    );

  box-shadow:
    0 9px 24px rgba(33, 122, 73, .17);

  font-size:
    12px;

  font-weight:
    950;

  cursor:
    pointer;

}


.farmer-book-submit:hover {

  transform:
    translateY(-2px);

  box-shadow:
