body.dark .farmer-history-page,
html.dark-mode .farmer-history-page,
body.dark-mode .farmer-history-page,
html[data-theme="dark"] .farmer-history-page,
body[data-theme="dark"] .farmer-history-page {
  background:
    radial-gradient(
      circle at 7% 0%,
      rgba(52,155,102,.10),
      transparent 25%
    ),
    radial-gradient(
      circle at 93% 0%,
      rgba(55,140,183,.12),
      transparent 28%
    ),
    linear-gradient(
      180deg,
      #07151b,
      #0c1c23
    ) !important;
}


html.dark .farmer-history-summary-card,
html.dark .farmer-history-toolbar,
html.dark .farmer-history-card,
html.dark .farmer-history-chart-card,
html.dark .farmer-history-crop-card,
body.dark .farmer-history-summary-card,
body.dark .farmer-history-toolbar,
body.dark .farmer-history-card,
body.dark .farmer-history-chart-card,
body.dark .farmer-history-crop-card {
  color: #e6f0f2 !important;
  background: #11262e !important;
  border-color: #2a4750 !important;
}


html.dark .farmer-history-row {
  background: #11262e !important;
  border-color: #253e46 !important;
}


html.dark .farmer-history-row:hover {
  background: #18323b !important;
}


html.dark .farmer-history-header h1,
html.dark .farmer-history-card-header h2,
html.dark .farmer-history-chart-card h2,
html.dark .farmer-history-toolbar-title,
html.dark .farmer-history-main strong,
html.dark .farmer-history-quantity,
html.dark .farmer-history-crop-card strong,
html.dark .farmer-history-empty h2 {
  color: #f0f7f8 !important;
}


html.dark .farmer-history-header p,
html.dark .farmer-history-toolbar-subtitle,
html.dark .farmer-history-main span,
html.dark .farmer-history-date,
html.dark .farmer-history-chart-card p,
html.dark .farmer-history-crop-card span,
html.dark .farmer-history-summary-card span {
  color: #aec4c9 !important;
}


html.dark .farmer-history-summary-card:nth-child(1) strong {
  color: #7bd79a !important;
}


html.dark .farmer-history-summary-card:nth-child(2) strong {
  color: #7bc5e4 !important;
}


html.dark .farmer-history-summary-card:nth-child(3) strong {
  color: #efb66c !important;
}


html.dark .farmer-history-summary-card:nth-child(4) strong {
  color: #b19de9 !important;
}


html.dark .farmer-history-token {
  color: #8ed0e9 !important;
  background: #173744 !important;
}


html.dark .farmer-history-crop,
html.dark .farmer-history-amount {
  color: #79d99a !important;
}


html.dark .farmer-history-chart,
html.dark .history-chart,
html.dark .history-graph {
  background: #0c2027 !important;
  border-color: #2c4750 !important;
}


html.dark .farmer-history-view {
  color: #8ed0e9 !important;
  background: #14343f !important;
  border-color: #345563 !important;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 950px) {

  .farmer-history-summary {
    grid-template-columns:
      repeat(2,minmax(0,1fr));
  }


  .farmer-history-grid {
    grid-template-columns:
      1fr;
  }


  .farmer-history-crop-breakdown {
    grid-template-columns:
      repeat(2,minmax(0,1fr));
  }


  .farmer-history-row {
    grid-template-columns:
      52px
      minmax(0,1fr)
      auto;
  }


  .farmer-history-date,
  .farmer-history-crop {
    display: none;
  }

}


@media (max-width: 600px) {

  .farmer-history-container {
    width:
      calc(100% - 20px);

    padding-top:
      28px;
  }


  .farmer-history-header h1 {
    font-size:
      36px;
  }


  .farmer-history-summary {
    grid-template-columns:
      1fr 1fr;
  }


  .farmer-history-summary-card {
    min-height:
      110px;

    padding:
      16px;
  }


  .farmer-history-summary-card strong {
    font-size:
      25px;
  }


  .farmer-history-card-header,
  .farmer-history-chart-card {
    padding:
      19px;
  }


  .farmer-history-row {
    grid-template-columns:
      46px
      minmax(0,1fr);

    gap:
      11px;

    padding:
      13px;
  }


  .farmer-history-token {
    width:
      42px;

    height:
      42px;
  }


  .farmer-history-quantity,
  .farmer-history-amount,
  .farmer-history-status,
  .farmer-history-view {
    grid-column:
      2;
  }


  .farmer-history-crop-breakdown {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 430px) {

  .farmer-history-summary {
    grid-template-columns:
      1fr;
  }


  .farmer-history-header h1 {
    font-size:
      32px;
  }

}

/* =========================================================
   KRISHISETU — LANDING PAGE FINAL CSS
========================================================= */

.landing-page {
  --lp-navy: #123d55;
  --lp-blue: #17749b;
  --lp-blue-soft: #e8f5fa;

  --lp-green: #277c4d;
  --lp-green-soft: #e8f6ed;

  --lp-orange: #cf7b20;
  --lp-orange-soft: #fff1dc;

  --lp-purple: #6956a0;
  --lp-purple-soft: #f0edfa;

  --lp-teal: #217f7a;
  --lp-teal-soft: #e8f7f5;

  --lp-text: #385b68;
  --lp-soft: #718891;
  --lp-border: #d8e5e8;
  --lp-bg: #f3f8f8;

  min-height: 100vh;
  overflow: hidden;

  color: var(--lp-text);

  background:
    radial-gradient(
      circle at 0% 0%,
      rgba(39,124,77,.08),
      transparent 27%
    ),
    radial-gradient(
      circle at 100% 8%,
      rgba(23,116,155,.10),
      transparent 29%
    ),
    linear-gradient(
      180deg,
      #eef6f6 0%,
      #f9fbfb 42%,
      #f1f7f6 100%
    );
}


/* =========================================================
   HEADER
========================================================= */

.landing-header {
  position: sticky;
  top: 0;
  z-index: 100;

  display: flex;
  align-items: center;
  justify-content: space-between;

  min-height: 88px;

  padding:
    8px
    clamp(18px, 4.5vw, 64px);

  border-bottom:
    1px solid rgba(206,222,226,.9);

  background:
    rgba(255,255,255,.90);

  backdrop-filter:
    blur(18px);

  -webkit-backdrop-filter:
    blur(18px);
}


.landing-brand {
  display: flex;
  align-items: center;

  min-width: 255px;

  color:
    var(--lp-navy);

  text-decoration:
    none;
}


.landing-brand svg {
  transform:
    scale(1.14);

  transform-origin:
    left center;
}


/* =========================================================
   NAVIGATION
========================================================= */

.landing-nav {
  display:
    flex;

  align-items:
    center;

  gap:
    32px;
}


.landing-nav a {
  position:
    relative;

  color:
    #55707a;

  font-size:
    12px;

  font-weight:
    850;

  text-decoration:
    none;
}


.landing-nav a::after {
  content:
    "";

  position:
    absolute;

  left:
    0;

  right:
    100%;

  bottom:
    -8px;

  height:
    2px;

  border-radius:
    999px;

  background:
    var(--lp-green);

  transition:
    right .25s ease;
}


.landing-nav a:hover {
  color:
    var(--lp-blue);
}


.landing-nav a:hover::after {
  right:
    0;
}


/* =========================================================
   HEADER ACTIONS
========================================================= */

.landing-header-actions {
  display:
    flex;

  align-items:
    center;

  gap:
    8px;
}


.landing-nav-farmer,
.landing-nav-admin {
  display:
    inline-flex;

  align-items:
    center;

  justify-content:
    center;

  min-height:
    42px;

  padding:
    0 15px;

  border-radius:
    10px;

  font-size:
    10px;

  font-weight:
    950;

  text-decoration:
    none;
}


.landing-nav-farmer {
  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      #2c8253,
      #1d633f
    );

  box-shadow:
    0 7px 17px rgba(40,125,78,.16);
}


.landing-nav-admin {
  color:
    var(--lp-blue);

  border:
    1px solid #c9dde4;

  background:
    #f7fbfc;
}


.landing-nav-farmer:hover,
.landing-nav-admin:hover {
  transform:
    translateY(-2px);
}


/* =========================================================
   MOBILE NAV
========================================================= */

.landing-mobile-menu-button {
  display:
    none;

  place-items:
    center;

  width:
    44px;

  height:
    44px;

  border:
    1px solid var(--lp-border);

  border-radius:
    11px;

  color:
    var(--lp-blue);

  background:
    #ffffff;
}


.landing-mobile-menu {
  display:
    none;
}


/* =========================================================
   HERO
========================================================= */

.landing-hero {
  position:
    relative;

  display:
    grid;

  grid-template-columns:
    minmax(0, 1.05fr)
    minmax(430px, .95fr);

  gap:
    35px;

  min-height:
    690px;

  padding:
    72px
    clamp(22px, 7vw, 100px)
    72px;

  overflow:
    hidden;
}


.landing-hero-background {
  position:
    absolute;

  inset:
    0;

  pointer-events:
    none;
}


.landing-glow {
  position:
    absolute;

  border-radius:
    50%;

  filter:
    blur(2px);

}


.landing-glow-one {
  width:
    520px;

  height:
    520px;

  left:
    -220px;

  top:
    -230px;

  background:
    rgba(39,124,77,.08);
}


.landing-glow-two {
  width:
    570px;

  height:
    570px;

  right:
    -240px;

  bottom:
    -300px;

  background:
    rgba(23,116,155,.09);
}


.landing-grid-pattern {
  position:
    absolute;

  inset:
    0;

  opacity:
    .55;

  background-image:
    linear-gradient(
      rgba(25,75,95,.035) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(25,75,95,.035) 1px,
      transparent 1px
    );

  background-size:
    52px 52px;
}


/* =========================================================
   HERO CONTENT
========================================================= */

.landing-hero-content {
  position:
    relative;

  z-index:
    2;

  align-self:
    center;

  max-width:
    750px;
}


.landing-hero-badge {
  display:
    inline-flex;

  align-items:
    center;

  gap:
    8px;

  min-height:
    35px;

  padding:
    0 12px;

  border:
    1px solid #c9dfd1;

  border-radius:
    999px;

  color:
    var(--lp-green);

  background:
    rgba(232,246,237,.88);

  font-size:
    9px;

  font-weight:
    950;

  letter-spacing:
    .12em;
}


/* =========================================================
   LARGE BRAND
========================================================= */

.landing-hero-logo {
  margin:
    28px 0 28px;

  min-height:
    125px;

  display:
    flex;

  align-items:
    center;
}


.landing-hero-logo svg {
  transform:
    scale(0.95);

  transform-origin:
    left center;
}


/* =========================================================
   HERO TITLE
========================================================= */

.landing-hero-content h1 {
  max-width:
    720px;

  margin:
    7px 0 0;

  color:
    var(--lp-navy);

  font-size:
    clamp(
      50px,
      6vw,
      82px
    );

  line-height:
    .89;

  letter-spacing:
    -.065em;

  font-weight:
    950;
}


.landing-hero-content h1 span {
  display:
    block;

  margin-top:
    11px;

  color:
    var(--lp-green);
}


/* =========================================================
   HERO DESCRIPTION
========================================================= */

.landing-hero-description {
  max-width:
    660px;

  margin-top:
    23px;

  color:
    #55737d;

  font-size:
    14px;

  line-height:
    1.8;
}


/* =========================================================
   HERO ACTIONS
========================================================= */

.landing-hero-actions {
  display:
    flex;

  align-items:
    center;

  gap:
    11px;

  margin-top:
    28px;
}


.landing-primary-button,
.landing-secondary-button {
  display:
    inline-flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    10px;

  min-height:
    55px;

  padding:
    0 20px;

  border-radius:
    12px;

  font-size:
    11px;

  font-weight:
    950;

  text-decoration:
    none;

}


.landing-primary-button {
  color:
    #ffffff;

  background:
    linear-gradient(
      135deg,
      #2d8253,
      #1d633e
    );

  box-shadow:
    0 10px 25px rgba(39,126,78,.18);
}


.landing-secondary-button {
  color:
    var(--lp-blue);

  border:
    1px solid #c7dce3;

  background:
    #ffffff;
}


.landing-primary-button:hover,
.landing-secondary-button:hover {
  transform:
    translateY(-3px);
}


/* =========================================================
   HERO POINTS
========================================================= */

.landing-hero-points {
  display:
    flex;

  flex-wrap:
    wrap;

  gap:
    19px;

  margin-top:
    23px;
}


.landing-hero-points div {
  display:
    flex;

  align-items:
    center;

  gap:
    7px;

  color:
    #5b757e;

  font-size:
    10px;

  font-weight:
    850;
}


.landing-hero-points svg {
  color:
    var(--lp-green);
}


/* =========================================================
   HERO VISUAL
========================================================= */

.landing-hero-visual {
  position:
    relative;

  display:
    grid;

  place-items:
    center;

  min-height:
    540px;
}


.landing-visual-glow {
  position:
    absolute;

  width:
    450px;

  height:
    450px;

  border-radius:
    50%;

  background:
    radial-gradient(
      circle,
      rgba(64,153,97,.15),
      rgba(42,122,151,.07) 45%,
      transparent 71%
    );

  filter:
    blur(2px);
}


/* =========================================================
   ORBITS
========================================================= */

.landing-orbit {
  position:
    absolute;

  border:
    1px dashed rgba(43,116,138,.19);

  border-radius:
    50%;
}


.landing-orbit-one {
  width:
    500px;

  height:
    500px;

  animation:
    landing-spin 28s linear infinite;
}


.landing-orbit-two {
  width:
    355px;

  height:
    355px;

  animation:
    landing-spin-reverse 21s linear infinite;
}


@keyframes landing-spin {

  from {
    transform:
      rotate(0deg);
  }

  to {
    transform:
      rotate(360deg);
  }

}


@keyframes landing-spin-reverse {

  from {
    transform:
      rotate(360deg);
  }

  to {
    transform:
      rotate(0deg);
  }

}


/* =========================================================
   FARM SCENE
========================================================= */

.landing-farm-illustration {
  position:
    relative;

  width:
    min(
      500px,
      100%
    );

  height:
    450px;

  overflow:
    hidden;

  border:
    1px solid rgba(183,210,202,.75);

  border-radius:
    42px;

  background:
    linear-gradient(
      180deg,
      #deeff3 0%,
      #edf6e9 48%,
      #79a860 49%,
      #4d8248 100%
    );

  box-shadow:
    0 28px 62px rgba(28,71,74,.15);
}


.landing-farm-illustration::after {
  content:
    "";

  position:
    absolute;

  inset:
    auto 0 0;

  height:
    48%;

  background:
    repeating-linear-gradient(
      150deg,
      rgba(255,255,255,.08) 0 5px,
      transparent 5px 17px
    );

  opacity:
    .55;
}


.landing-sun {
  position:
    absolute;

  right:
    62px;

  top:
    51px;

  width:
    82px;

  height:
    82px;

  border-radius:
    50%;

  background:
    radial-gradient(
      circle,
      #ffe7af,
      #f5b95e
    );

  box-shadow:
    0 0 48px rgba(245,184,93,.40);
}


.landing-sun span {
  position:
    absolute;

  inset:
    -14px;

  border:
    1px solid rgba(235,178,86,.32);

  border-radius:
    50%;
}


.landing-cloud {
  position:
    absolute;

  height:
    17px;

  border-radius:
    999px;

  background:
    rgba(255,255,255,.76);
}


.cloud-one {
  top:
    79px;

  left:
    48px;

  width:
    108px;
}


.cloud-two {
  top:
    127px;

  left:
    126px;

  width:
    74px;

  opacity:
    .60;
}


/* fields */

.landing-field {
  position:
    absolute;

  left:
    -5%;

  right:
    -5%;

  border-radius:
    50%;
}


.field-one {
  bottom:
    135px;

  height:
    90px;

  background:
    #79a75e;
}


.field-two {
  bottom:
    63px;

  height:
    100px;

  background:
    #5f944c;
}


.field-three {
  bottom:
    -30px;

  height:
    115px;

  background:
    #477b43;
}


/* centre */

.landing-farm-tile {
  position:
    absolute;

  z-index:
    4;

  left:
    50%;

  top:
    50%;

  transform:
    translate(-50%,-50%);

  display:
    flex;

  flex-direction:
    column;

  align-items:
    center;

  justify-content:
    center;

  width:
    185px;

  height:
    185px;

  border:
    1px solid rgba(255,255,255,.5);

  border-radius:
    34px;

  color:
    #ffffff;

  background:
    linear-gradient(
      145deg,
      rgba(24,87,63,.87),
      rgba(22,108,83,.76)
    );

  backdrop-filter:
    blur(14px);

  box-shadow:
    0 20px 46px rgba(20,72,48,.23);
}


.landing-farm-tile span {
  margin-top:
    10px;

  font-size:
    11px;

  font-weight:
    950;

  letter-spacing:
    .18em;
}


/* =========================================================
   FLOATING CARDS
========================================================= */

.landing-floating-card {
  position:
    absolute;

  z-index:
    6;

  display:
    flex;

  align-items:
    center;

  gap:
    11px;

  min-width:
    172px;

  min-height:
    67px;

  padding:
    10px 12px;

  border:
    1px solid rgba(255,255,255,.74);

  border-radius:
    15px;

  background:
    rgba(255,255,255,.92);

  backdrop-filter:
    blur(15px);

  box-shadow:
    0 14px 30px rgba(35,70,77,.15);
}


.floating-card-icon {
  display:
    grid;

  place-items:
    center;

  width:
    41px;

  height:
    41px;

  border-radius:
    11px;
}


.card-token {
  left:
    19px;

  top:
    103px;
}


.card-token .floating-card-icon {
  color:
    var(--lp-blue);

  background:
    var(--lp-blue-soft);
}


.card-weighing {
  right:
    17px;

  top:
    214px;
}


.card-weighing .floating-card-icon {
  color:
    var(--lp-orange);

  background:
    var(--lp-orange-soft);
}


.card-payment {
  left:
    42px;

  bottom:
    38px;
}


.card-payment .floating-card-icon {
  color:
    var(--lp-green);

  background:
    var(--lp-green-soft);
}


.landing-floating-card span {
  display:
    block;

  color:
    #84999f;

  font-size:
    7px;

  font-weight:
    950;

  letter-spacing:
    .10em;
}


.landing-floating-card strong {
  display:
    block;

  margin-top:
    3px;

  color:
    var(--lp-navy);

  font-size:
    15px;
}


/* =========================================================
   TRUST STRIP
========================================================= */

.landing-trust-strip {
  display:
    grid;

  grid-template-columns:
    repeat(4,1fr);

  gap:
    1px;

  margin:
    0
    clamp(14px,7vw,100px);

  overflow:
    hidden;

  border:
    1px solid var(--lp-border);

  border-radius:
    17px;

  background:
    var(--lp-border);

  box-shadow:
    0 9px 27px rgba(30,68,81,.045);
}


.landing-trust-strip > div {
  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    9px;

  min-height:
    70px;

  padding:
    9px;

  color:
    #58727d;

  background:
    #ffffff;

  font-size:
    10px;

  font-weight:
    900;

  text-align:
    center;
}


.landing-trust-strip svg {
  flex:
    0 0 auto;

  color:
    var(--lp-green);
}


/* =========================================================
   SECTION HEADINGS
========================================================= */

.landing-purpose-section,
.landing-process-section,
.landing-portals-section,
.landing-features-section,
.landing-support-section {

  padding:
    105px
    clamp(20px,7vw,100px);

}


.landing-section-heading {
  max-width:
    780px;
}


.landing-section-heading.centered {
  margin:
    0 auto 46px;

  text-align:
    center;
}


.landing-section-heading > span,
.landing-portals-intro > span {

  color:
    var(--lp-orange);

  font-size:
