   DARK MODE
========================================================= */

html.dark .landing-page,
body.dark .landing-page,
html.dark-mode .landing-page,
body.dark-mode .landing-page,
html[data-theme="dark"] .landing-page,
body[data-theme="dark"] .landing-page {

  --lp-blue: #5ec4f0;
  --lp-blue-dark: #8dd9f5;
  --lp-blue-soft: #173b4a;

  --lp-green: #62d894;
  --lp-green-dark: #7fe4a8;
  --lp-green-soft: #153b2a;

  --lp-orange: #ffb75e;
  --lp-orange-soft: #3c2a19;

  --lp-purple: #b19ce9;
  --lp-purple-soft: #30274a;

  --lp-teal: #61d1c9;
  --lp-teal-soft: #183d3a;

  --lp-navy: #f2f9fa;
  --lp-text: #d9e8eb;
  --lp-soft: #afc4ca;
  --lp-border: #29464f;
  --lp-bg: #08171d;
  --lp-card: #11262e;


  background:
    radial-gradient(
      circle at 5% 0%,
