   LEFT INTRO
========================================================= */

.login-intro {
  position:
    relative;
}


.login-intro::before {
  content:
    "";

  position:
    absolute;

  width:
    250px;

  height:
    250px;

  left:
    -110px;

  top:
    -100px;

  border-radius:
    50%;

  background:
    rgba(28,157,90,.05);

  filter:
    blur(4px);

  pointer-events:
    none;
}


.page-eyebrow {
  display:
    inline-block;

  color:
    #df7c1d;

  font-size:
    10px;

  font-weight:
    950;

  letter-spacing:
    .16em;
}


.login-intro h1 {
  position:
    relative;

  max-width:
    690px;

  margin-top:
    13px;

  color:
    #123f57;

  font-size:
    clamp(
      47px,
      5.8vw,
      76px
    );

  line-height:
    .91;

  letter-spacing:
    -.062em;

  font-weight:
    950;
}


.login-intro h1 span {
  display:
    block;

  margin-top:
    8px;

  color:
    #198750;

  text-shadow:
    0 3px 0 rgba(25,135,80,.03);
}


.login-intro > p {
  max-width:
    635px;

  margin-top:
    22px;

  color:
    #587580;

  font-size:
    14px;

  line-height:
    1.82;
}


/* =========================================================
   BENEFITS
========================================================= */

.login-feature-list {
  display:
    grid;

  gap:
    13px;

  max-width:
    630px;

  margin-top:
    30px;
}


.login-feature {
  display:
    flex;

  align-items:
    center;

  gap:
    14px;

  padding:
    13px 16px;

  border:
    1px solid #d7e7e9;

  border-radius:
    15px;

  background:
    rgba(255,255,255,.79);

  box-shadow:
    0 6px 20px rgba(28,70,84,.045);

  transition:
    transform .2s ease,
