.login-feature:hover {
  transform:
    translateX(4px);

  box-shadow:
    0 10px 27px rgba(28,70,84,.08);
}


.login-feature-icon {
  display:
    grid;

  place-items:
    center;

  width:
    43px;

  height:
    43px;

  flex:
    0 0 43px;

  border-radius:
    12px;

  color:
    #18834f;

  background:
    #e4f7eb;
}


.login-feature strong {
  display:
    block;

  color:
    #295668;

  font-size:
    14px;

  font-weight:
    900;
}


.login-feature span {
  display:
    block;

  margin-top:
    3px;

  color:
    #748b93;

  font-size:
    11px;

  line-height:
    1.5;
}


/* =========================================================
   LOGIN CARD
========================================================= */

.login-form-card {
  position:
    relative;

  overflow:
    hidden;

  padding:
    31px;

  border:
    1px solid #d3e4e7;

  border-radius:
    24px;

  background:
    rgba(255,255,255,.94);

