.login-form-heading h2 {
  margin-top:
    5px;

  color:
    #143f55;

  font-size:
    29px;

  line-height:
    1.05;

  letter-spacing:
    -.035em;

  font-weight:
    950;
}


.login-form-heading p {
  margin-top:
    6px;

  color:
    #748a92;

