  gap:
    8px;

  min-height:
    48px;

  border:
    1px solid #c9dfe5;

  border-radius:
    11px;

  color:
    #17749d;

  background:
    #f3fafc;

  font-size:
    11px;

  font-weight:
    950;

  text-decoration:
    none;

  transition:
    .2s ease;
