  box-shadow:
    0 11px 25px rgba(24,164,93,.20);
}


.help-secondary-action {
  color:
    var(--help-blue-dark);

  border:
    1px solid #bcd9e3;

  background:
    #ffffff;
}


.help-primary-action:hover,
.help-secondary-action:hover {
  transform:
    translateY(-3px);
}


/* =========================================================
   HERO QUICK HELP CARD
========================================================= */

.help-hero-card {
  position:
    relative;

  overflow:
    hidden;

  padding:
    26px;

  border:
    1px solid #d1e4e7;

  border-radius:
    23px;

  background:
    linear-gradient(
      145deg,
      #ffffff,
      #f0f9f8
    );

  box-shadow:
    0 24px 55px rgba(27,72,84,.10);
}


.help-hero-card::before {
  content:
    "";

  position:
    absolute;

  left:
    0;

  right:
    0;

  top:
    0;

  height:
    6px;

  background:
    linear-gradient(
      90deg,
      var(--help-green),
      var(--help-blue),
      var(--help-orange)
