.help-hero-card-top {
  display:
    flex;

  align-items:
    center;

  gap:
    14px;
}


.help-hero-card-icon {
  display:
    grid;

  place-items:
    center;

  width:
    54px;

  height:
    54px;

  flex:
    0 0 54px;

  border-radius:
    15px;

  color:
    var(--help-blue);

  background:
    var(--help-blue-soft);
}


.help-hero-card-top span {
  display:
    block;

  color:
    var(--help-orange);

  font-size:
    9px;

  font-weight:
    950;

  letter-spacing:
    .14em;
}


.help-hero-card-top strong {
  display:
    block;

  margin-top:
    5px;

  color:
    var(--help-navy);

  font-size:
    23px;

  line-height:
    1.1;
}


.help-hero-check-list {
  display:
    grid;

  gap:
    11px;

  margin-top:
    25px;

  padding-top:
    21px;

  border-top:
    1px solid #e0ebed;
}


.help-check-row {
  display:
    flex;

  align-items:
    flex-start;

  gap:
    9px;

  color:
    #4e6f7b;

  font-size:
    11px;

  line-height:
    1.55;
}


.help-check-row svg {
  flex:
    0 0 auto;

  margin-top:
    1px;

  color:
    var(--help-green);
}


/* =========================================================
   SECTION HEADINGS
========================================================= */

.help-section-heading {
  margin-bottom:
    34px;
}


.help-section-heading .page-eyebrow {
  color:
    var(--help-orange);

  font-size:
    10px;

  font-weight:
    950;

  letter-spacing:
    .15em;
}


.help-section-heading h2 {
  max-width:
    800px;

  margin-top:
