      4.7vw,
      55px
    );

  line-height:
    .97;

  letter-spacing:
    -.05em;

  font-weight:
    950;
}


.help-section-heading p {
  max-width:
    740px;

  margin-top:
    12px;

  color:
    var(--help-muted);

  font-size:
    13px;

  line-height:
    1.75;
}


/* =========================================================
   QUICK TOPICS
========================================================= */

.help-quick-section {
  padding:
    55px 0 105px;
}


.help-topic-grid {
  display:
    grid;

  grid-template-columns:
    repeat(3,minmax(0,1fr));

  gap:
    14px;
}


.help-topic-card {
  display:
    grid;

  grid-template-columns:
    auto 1fr auto;

  align-items:
    center;

  gap:
    13px;

  min-height:
    126px;

  padding:
    17px;

  border:
    1px solid var(--help-border);

  border-radius:
    18px;

  color:
    inherit;

  background:
    var(--help-card);

  box-shadow:
    0 7px 21px rgba(27,72,84,.045);

  text-align:
    left;

  cursor:
    pointer;

  transition:
    transform .2s ease,
    box-shadow .2s ease,
    border-color .2s ease;
}


.help-topic-card:hover {
  transform:
    translateY(-5px);

  box-shadow:
    0 17px 35px rgba(27,72,84,.085);
}


.help-topic-icon {
  display:
    grid;

  place-items:
    center;

  width:
    48px;

  height:
    48px;

  border-radius:
    13px;
}


.help-topic-card.green .help-topic-icon {
  color:
    var(--help-green);

  background:
    var(--help-green-soft);
}


.help-topic-card.blue .help-topic-icon {
  color:
    var(--help-blue);

  background:
    var(--help-blue-soft);
}


.help-topic-card.orange .help-topic-icon {
  color:
    var(--help-orange);

  background:
    var(--help-orange-soft);
}


.help-topic-card.purple .help-topic-icon {
  color:
    var(--help-purple);

  background:
    var(--help-purple-soft);
}


.help-topic-card.gold .help-topic-icon {
  color:
    var(--help-gold);

  background:
    var(--help-gold-soft);
}


.help-topic-card.teal .help-topic-icon {
  color:
    var(--help-teal);

  background:
    var(--help-teal-soft);
}


.help-topic-card strong {
  display:
    block;

  color:
    var(--help-navy);

  font-size:
    16px;

  font-weight:
    950;
}


.help-topic-card p {
  margin-top:
    5px;

  color:
    var(--help-muted);

  font-size:
    10px;

  line-height:
