    95px 0;

  background:
    rgba(255,255,255,.42);
}


.help-checklist-grid {
  display:
    grid;

  grid-template-columns:
    repeat(4,minmax(0,1fr));

  gap:
    14px;
}


.help-checklist-card {
  min-height:
    205px;

  padding:
    20px;

  border:
    1px solid var(--help-border);

  border-radius:
    18px;

