  display:
    inline-flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    8px;

  min-height:
    42px;

  padding:
    0 13px;

  border:
    1px solid var(--border);

  border-radius:
    10px;

  color:
    var(--text);

  background:
    var(--surface);

  font-size:
    11px;

  font-weight:
    850;

  cursor:
    pointer;

  transition:
    transform .18s ease,
