  letter-spacing: .14em;

  color: var(--muted);
}


/* =========================
   NAVIGATION
========================= */

.admin-sidebar-items {
  display: grid;

  gap: 6px;
}


.admin-sidebar-link {
  position: relative;

  display: flex;

  align-items: center;

  gap: 13px;

  min-height: 52px;

  padding: 0 15px;

  border: 1px solid transparent;

  border-radius: 13px;

  overflow: hidden;

  color: var(--muted);

  font-size: 14px !important;

  font-weight: 900 !important;

  text-decoration: none;

  transition:
    color .2s ease,
    background .2s ease,
    border-color .2s ease,
    transform .2s ease,
    padding-left .2s ease,
    box-shadow .2s ease;
}


/* Animated glow strip */

.admin-sidebar-link::before {
  content: "";

  position: absolute;

  left: 0;
  top: 0;

  width: 4px;
  height: 100%;

  border-radius: 0 4px 4px 0;

  background:
    linear-gradient(
      180deg,
      #19a9e8,
      #1aa261
    );

  transform:
    scaleY(0);

  transform-origin:
    center;

  transition:
    transform .2s ease;
}


/* Hover */

.admin-sidebar-link:hover {
  color: var(--text);

  padding-left: 20px;

  transform:
    translateX(4px);

  border-color:
    rgba(22,159,229,.18);

  background:
    linear-gradient(
      90deg,
      rgba(22,159,229,.10),
      rgba(22,159,229,.03)
    );

  box-shadow:
    0 7px 18px rgba(0,0,0,.045);
}


.admin-sidebar-link:hover::before {
  transform:
    scaleY(.65);
}


/* Icon animation */

.admin-sidebar-link svg {
  flex: 0 0 auto;

  width: 19px !important;
  height: 19px !important;

  transition:
    transform .2s ease,
    color .2s ease;
}


.admin-sidebar-link:hover svg {
  transform:
    translateX(2px)
    scale(1.12);

  color:
    var(--primary);
}


/* Active */

.admin-sidebar-link.active {
  color:
    var(--primary);

  border-color:
    rgba(22,159,229,.22);

  background:
    linear-gradient(
      135deg,
      rgba(22,159,229,.15),
      rgba(22,159,229,.045)
    );

  box-shadow:
    inset 4px 0 0 var(--primary),
    0 6px 18px rgba(22,159,229,.08);
}


.admin-sidebar-link.active::before {
  transform:
    scaleY(.75);
}


.admin-sidebar-link.active svg {
  color:
    var(--primary);

  transform:
    scale(1.08);
}


