  border-radius: 10px;

  overflow: hidden;

  background:
    var(--surface);
}


.admin-settings-page .admin-setting-number input {
  width: 72px;

  min-height: 42px;

  padding:
    0 10px;

  border: 0;

  outline: 0;

  color: var(--text);

  background:
