  margin-top: 3px;

  font-size: 10px !important;

  line-height: 1.4;

  font-weight: 650 !important;

  color: var(--muted);
}


.admin-settings-page .admin-settings-save-actions {
  display: flex;

  align-items: center;

  gap: 8px;

  flex: 0 0 auto;
}


.admin-settings-page .admin-settings-save-actions button {
  min-height: 42px;

  padding:
