  z-index: 3;
}

.landing-hero-visual {
  position: absolute;
  inset: -12% -8% -12% 42%;
  z-index: 1;
  pointer-events: none;
  overflow: visible;
}

.landing-hero-visual::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(
      circle at 55% 50%,
      rgba(255,255,255,0.08),
      transparent 42%
    );
  pointer-events: none;
}

.landing-journey-illustration {
  position: absolute;
  width: 720px;
  height: 720px;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  overflow: visible;
}

.journey-ring {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}

.ring-one {
  inset: 5%;
}

.ring-two {
  inset: 15%;
}

.journey-center,
.journey-node {
  position: absolute;
  z-index: 4;
