/* =========================================================
   ADMIN LOGIN — PREMIUM UI
   Visual-only changes.
   Authentication/backend logic untouched.
========================================================= */

.admin-login-page {
  position: relative;
  min-height: 100vh;
  overflow-x: hidden;

  background:
    radial-gradient(
      circle at 18% 20%,
      rgba(76, 137, 82, 0.10),
      transparent 28%
    ),
    radial-gradient(
      circle at 84% 72%,
      rgba(76, 116, 160, 0.08),
      transparent 30%
    ),
    linear-gradient(
      135deg,
      #f7faf7 0%,
      #eef5ef 48%,
      #f8faf8 100%
    );
}


/* =========================================================
   ATMOSPHERIC BACKGROUND
========================================================= */

.admin-login-page::before,
.admin-login-page::after {
  content: "";

  position: fixed;

  width: 420px;
  height: 420px;

  border-radius: 50%;

  pointer-events: none;

  filter: blur(10px);

  opacity: 0.65;

  z-index: 0;
}

.admin-login-page::before {
  top: -180px;
  left: -150px;

  background:
    radial-gradient(
      circle,
      rgba(94, 153, 96, 0.12),
      transparent 68%
    );

  animation:
    adminLoginOrbOne 10s ease-in-out infinite;
}

.admin-login-page::after {
  right: -180px;
  bottom: -190px;

  background:
    radial-gradient(
      circle,
      rgba(91, 128, 172, 0.10),
      transparent 68%
    );

  animation:
    adminLoginOrbTwo 12s ease-in-out infinite;
}


/* =========================================================
   HEADER
========================================================= */

.admin-login-header {
  position: relative;
  z-index: 10;

  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);

  background:
    rgba(255,255,255,0.82);

  border-bottom:
    1px solid rgba(41, 72, 46, 0.08);

  box-shadow:
    0 8px 30px
    rgba(33, 61, 38, 0.04);
}

.admin-login-brand {
  transition:
    transform 0.35s ease,
    filter 0.35s ease;
}

.admin-login-brand:hover {
  transform:
    translateY(-2px);

  filter:
    drop-shadow(
      0 8px 18px
      rgba(55, 110, 62, 0.12)
    );
}

.admin-login-back {
  transition:
    transform 0.3s ease,
    color 0.3s ease,
    background-color 0.3s ease;
}

.admin-login-back:hover {
  transform:
    translateX(4px);

  color:
    #3c7044;
}


/* =========================================================
   MAIN CONTAINER
========================================================= */

.admin-login-container {
  position: relative;
  z-index: 2;
}


/* =========================================================
   MAIN LAYOUT
========================================================= */

.admin-login-layout {
  position: relative;
}


/* =========================================================
   LEFT INTRO
========================================================= */

.admin-login-intro {
  animation:
    adminLoginFadeUp
    0.8s
    cubic-bezier(.2,.8,.2,1)
    both;
}

.admin-login-intro h1 {
  letter-spacing:
    -0.04em;
}

.admin-login-intro h1 span {
  display: block;

  background:
    linear-gradient(
      120deg,
      #386b40 0%,
      #588f5b 48%,
      #7fa66a 100%
    );

  background-size:
    180% auto;

  -webkit-background-clip: text;
  background-clip: text;

  -webkit-text-fill-color:
    transparent;

  animation:
    adminLoginGradient
    8s
    ease-in-out
    infinite;
}


/* =========================================================
   EYEBROW
========================================================= */

.admin-login-eyebrow-row {
  display: flex;

  align-items: center;

  flex-wrap: wrap;

  gap: 12px;
}

.admin-login-eyebrow-row .page-eyebrow {
  letter-spacing:
    0.16em;
}


/* =========================================================
   SECURE PILL
========================================================= */

.admin-secure-pill {
  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease,
    background-color 0.3s ease;
}

.admin-secure-pill:hover {
  transform:
    translateY(-2px);

  box-shadow:
    0 10px 25px
    rgba(54, 91, 60, 0.08);

  background:
    rgba(255,255,255,0.78);
}


/* =========================================================
   FEATURE GRID
========================================================= */

.admin-login-feature {
  position: relative;

  overflow: hidden;

  border:
    1px solid rgba(52, 83, 58, 0.08);

  background:
    rgba(255,255,255,0.68);

  backdrop-filter:
    blur(12px);

  -webkit-backdrop-filter:
    blur(12px);

  box-shadow:
    0 10px 28px
    rgba(37, 65, 42, 0.045);

  transition:
    transform 0.4s cubic-bezier(.2,.8,.2,1),
    box-shadow 0.4s ease,
    border-color 0.3s ease;
}

.admin-login-feature::after {
  content: "";

  position: absolute;

  width: 130px;
  height: 130px;

  right: -72px;
  bottom: -72px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(101, 157, 101, 0.10),
      transparent 70%
    );

  opacity: 0;

  transition:
    opacity 0.4s ease,
    transform 0.45s ease;
}

.admin-login-feature:hover {
  transform:
    translateY(-6px);

  box-shadow:
    0 20px 42px
    rgba(36, 67, 41, 0.085);

  border-color:
    rgba(70, 122, 76, 0.16);
}

.admin-login-feature:hover::after {
  opacity: 1;
  transform:
    scale(1.25);
}

.admin-login-feature-icon {
  transition:
    transform 0.35s cubic-bezier(.2,.8,.2,1),
    box-shadow 0.35s ease;
}

.admin-login-feature:hover
.admin-login-feature-icon {
  transform:
    scale(1.08)
    rotate(-4deg);

  box-shadow:
    0 10px 20px
    rgba(46, 87, 52, 0.08);
}

.admin-login-feature strong {
  font-size: 17px;
}

.admin-login-feature span {
  font-size: 14px;
  line-height: 1.6;
}


/* =========================================================
   WORKFLOW
========================================================= */

.admin-login-workflow {
  position: relative;

  border:
    1px solid rgba(53, 86, 59, 0.08);

  background:
    rgba(255,255,255,0.60);

  backdrop-filter:
    blur(12px);

  -webkit-backdrop-filter:
    blur(12px);

  box-shadow:
    0 14px 30px
    rgba(36, 64, 41, 0.05);
}

.admin-login-workflow-heading span {
  letter-spacing:
    0.14em;
}

.admin-login-workflow-heading strong {
  font-size: 17px;
}


/* workflow circles */

.admin-workflow-step {
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease;
}

.admin-workflow-step:hover {
  transform:
    translateY(-4px);
}

.admin-workflow-step span {
  transition:
    transform 0.35s ease;
}

.admin-workflow-step:hover span {
  transform:
    scale(1.08);
  box-shadow:
    0 8px 18px
    rgba(58, 104, 63, 0.12);
}

.admin-workflow-line {
  position: relative;
  overflow: hidden;
}

.admin-workflow-line::after {
  content: "";

  position: absolute;

  left: -100%;
  top: 50%;

  width: 100%;
  height: 2px;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(81, 138, 86, 0.55),
      transparent
    );

  transform:
    translateY(-50%);

  animation:
    adminWorkflowLine
    3.4s
    ease-in-out
    infinite;
}


/* =========================================================
   LOGIN CARD
========================================================= */

.admin-login-card {
  position: relative;
  z-index: 3;

  overflow: hidden;

  background:
    rgba(255,255,255,0.88);

  backdrop-filter:
    blur(22px);

  -webkit-backdrop-filter:
    blur(22px);

  border:
    1px solid rgba(43, 75, 49, 0.09);

  box-shadow:
    0 30px 80px
    rgba(31, 57, 36, 0.11),
    0 8px 25px
    rgba(31, 57, 36, 0.055);

  animation:
    adminLoginCardEnter
    0.85s
    cubic-bezier(.2,.8,.2,1)
    0.08s
    both;
}

.admin-login-card::before {
  content: "";

  position: absolute;

  left: 0;
  right: 0;
  top: 0;

  height: 3px;

  background:
    linear-gradient(
      90deg,
      #4f8a57,
      #89a95e,
      #597eaa
    );

  background-size:
    200% 100%;

  animation:
    adminCardGradient
    7s
    linear
    infinite;
}


/* =========================================================
   LOGIN HEADING
========================================================= */

.admin-login-card-heading {
  position: relative;
}

.admin-login-lock {
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease;
}

.admin-login-card:hover
.admin-login-lock {
  transform:
    scale(1.06)
    rotate(-4deg);

  box-shadow:
    0 12px 24px
    rgba(51, 102, 58, 0.11);
}

.admin-login-card-heading h2 {
  letter-spacing:
    -0.025em;
}


/* =========================================================
   FORM FIELDS
========================================================= */

.admin-login-field label {
  font-size: 15px;
  font-weight: 750;
}

.admin-login-field small {
  font-size: 13px;

  line-height: 1.5;
}


/* input container */

.admin-login-input {
  position: relative;

  transition:
    border-color 0.3s ease,
    box-shadow 0.3s ease,
    transform 0.3s ease;
}

.admin-login-input:focus-within {
  transform:
    translateY(-2px);

  border-color:
    rgba(70, 130, 79, 0.38);

  box-shadow:
    0 0 0 4px
    rgba(75, 139, 82, 0.08),
    0 10px 24px
    rgba(43, 78, 48, 0.06);
}

.admin-login-input svg {
  transition:
    transform 0.3s ease,
    color 0.3s ease;
}

.admin-login-input:focus-within svg {
  transform:
    scale(1.08);

  color:
    #4d8a55;
}


/* =========================================================
   SHOW / HIDE PASSWORD
========================================================= */

.admin-show-password {
  transition:
    color 0.25s ease,
    background-color 0.25s ease,
    transform 0.25s ease;
}

.admin-show-password:hover {
  color:
    #3f7748;

  transform:
    translateY(-1px);
}


/* =========================================================
   ERROR
========================================================= */

.admin-login-error {
  border:
    1px solid rgba(196, 75, 60, 0.14);

  box-shadow:
    0 8px 20px
    rgba(170, 68, 56, 0.045);

  animation:
    adminLoginShake
    0.35s
    ease;
}


/* =========================================================
   REMEMBER
========================================================= */

.admin-remember-row {
  transition:
    color 0.25s ease;
}

.admin-remember-row:hover {
  color:
    #3f7748;
}


/* =========================================================
   LOGIN BUTTON
========================================================= */

.admin-login-submit {
  position: relative;

  overflow: hidden;

  isolation: isolate;

  transition:
    transform 0.3s cubic-bezier(.2,.8,.2,1),
    box-shadow 0.3s ease;
}

.admin-login-submit::before {
  content: "";

  position: absolute;

  inset: 0;

  background:
    linear-gradient(
      110deg,
      transparent 18%,
      rgba(255,255,255,0.25) 48%,
      transparent 78%
    );

  transform:
    translateX(-125%);

  transition:
    transform 0.75s cubic-bezier(.2,.8,.2,1);

  z-index: -1;
}

.admin-login-submit:hover::before {
