}


/* =========================================================
   SPINNER
========================================================= */

.admin-login-spinner {
  border-color:
    rgba(255,255,255,0.35);

  border-top-color:
    #ffffff;

  animation:
    adminLoginSpin
    0.7s
    linear
    infinite;
}


/* =========================================================
   KEYFRAMES
========================================================= */

@keyframes adminLoginFadeUp {

  from {
    opacity: 0;
    transform:
      translateY(24px);
  }

  to {
    opacity: 1;
    transform:
      translateY(0);
  }

}

@keyframes adminLoginCardEnter {

  from {
    opacity: 0;

    transform:
      translateY(28px)
      scale(0.985);
  }

  to {
    opacity: 1;

    transform:
      translateY(0)
      scale(1);
  }

}

@keyframes adminLoginGradient {

  0%,
  100% {
    background-position:
      0% 50%;
  }

  50% {
    background-position:
      100% 50%;
  }

}

@keyframes adminCardGradient {

  0% {
    background-position:
      0% 50%;
  }

  100% {
    background-position:
      200% 50%;
  }

}

@keyframes adminWorkflowLine {

  0%,
  100% {
    left: -100%;
  }

  50% {
    left: 100%;
  }

}

@keyframes adminLoginOrbOne {

  0%,
  100% {
    transform:
      translate(0, 0)
      scale(1);
  }

  50% {
    transform:
      translate(35px, 25px)
      scale(1.08);
  }

}

@keyframes adminLoginOrbTwo {

  0%,
  100% {
    transform:
      translate(0, 0)
      scale(1);
  }

  50% {
    transform:
      translate(-30px, -25px)
      scale(1.08);
  }

}

@keyframes adminLoginShake {

  0%,
  100% {
    transform:
      translateX(0);
  }

  25% {
    transform:
      translateX(-4px);
  }

  75% {
    transform:
      translateX(4px);
  }

}

@keyframes adminLoginSpin {
  to {
    transform:
      rotate(360deg);
  }
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 900px) {

  .admin-login-layout {
    gap: 34px;
  }

  .admin-login-feature-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

}

@media (max-width: 650px) {

  .admin-login-feature-grid {
    grid-template-columns:
      1fr;
  }

  .admin-login-trust {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .admin-login-trust > div {
    min-width: 0;
  }

}

@media (max-width: 480px) {

  .admin-login-trust {
    grid-template-columns:
      1fr;
  }

  .admin-login-eyebrow-row {
    align-items:
      flex-start;
    flex-direction:
      column;
  }

}


/* =========================================================
   REDUCE MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

  *,
  *::before,
  *::after {
    animation-duration:
      0.01ms !important;

    animation-iteration-count:
      1 !important;

    transition-duration:
      0.01ms !important;
  }

}

