  padding-top:
    16px;

  border-top:
    1px solid
    #edf0eb;

  color:
    #839083;

  font-size:
    11px;

  line-height:
    1.5;
}


/* =========================================================
   TRUST STRIP
========================================================= */

.admin-login-trust {
  display:
    grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap:
    14px;

  margin-top:
    42px;
}

.admin-login-trust > div {
  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    8px;

  min-height:
    58px;

  border-radius:
    14px;

  background:
    rgba(255,255,255,0.64);

  border:
    1px solid
    rgba(55,85,59,0.07);

  color:
    #607261;

  font-size:
    12px;

  transition:
    transform 0.3s ease,
    background-color 0.3s ease;
}

.admin-login-trust > div:hover {
  transform:
    translateY(-3px);

  background:
    rgba(255,255,255,0.88);
}

.admin-login-trust svg {
  color:
    #63935e;
}


/* =========================================================
   FOOTER
========================================================= */

.admin-login-footer {
  position:
    relative;

  z-index:
    3;

  margin-top:
    auto;

  padding:
    24px 6%;

  border-top:
    1px solid
    rgba(53,84,57,0.07);

  background:
    rgba(255,255,255,0.60);

  color:
    #7b877d;

  font-size:
    12px;
}

.admin-login-footer strong {
  color:
    #466747;
}


/* =========================================================
   SPINNER
========================================================= */

.admin-login-spinner {
  width:
    17px;

  height:
    17px;

  display:
    inline-block;

  border:
    2px solid
    rgba(255,255,255,0.35);

  border-top-color:
    white;

  border-radius:
    50%;

  animation:
    admin-login-spin
    0.65s
    linear
    infinite;
}


/* =========================================================
   ANIMATIONS
========================================================= */

@keyframes admin-login-enter-left {

  from {
    opacity: 0;
    transform:
      translateX(-28px);
  }

  to {
    opacity: 1;
    transform:
      translateX(0);
  }

}

@keyframes admin-login-enter-right {

  from {
    opacity: 0;
    transform:
      translateX(28px);
  }

  to {
    opacity: 1;
    transform:
      translateX(0);
  }

}

@keyframes admin-bg-float-one {

  0%,
  100% {
    transform:
      translate(0, 0)
      scale(1);
  }

  50% {
    transform:
      translate(45px, -25px)
      scale(1.08);
  }

}

@keyframes admin-bg-float-two {

  0%,
  100% {
    transform:
      translate(0, 0)
      scale(1);
  }

  50% {
    transform:
      translate(-35px, -35px)
      scale(1.06);
  }

}

@keyframes admin-secure-pulse {

  0%,
  100% {
    box-shadow:
      0 0 0 4px
      rgba(99,162,95,0.08);
  }

  50% {
    box-shadow:
      0 0 0 8px
      rgba(99,162,95,0.03);
  }

}

@keyframes admin-error-shake {

  0%,
  100% {
    transform:
      translateX(0);
  }

  25% {
    transform:
      translateX(-4px);
  }

  75% {
    transform:
      translateX(4px);
  }

}

@keyframes admin-login-spin {

  to {
    transform:
      rotate(360deg);
  }

}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1050px) {

  .admin-login-container {
    width:
      min(
        920px,
        calc(100% - 40px)
      );
  }

  .admin-login-layout {
    grid-template-columns:
      1fr;

    gap:
      44px;

    min-height:
      auto;
  }

  .admin-login-intro {
    max-width:
      none;
  }

  .admin-login-card {
    justify-self:
      center;
  }

}


@media (max-width: 700px) {

  .admin-login-container {
    width:
      calc(100% - 28px);

    padding:
      38px 0 50px;
  }

  .admin-login-feature-grid {
    grid-template-columns:
      1fr;
  }

  .admin-login-intro h1 {
    font-size:
      46px;
  }

  .admin-login-intro > p {
    font-size:
      15px;
  }

  .admin-login-card {
    padding:
      24px 20px;

    border-radius:
      20px;
  }

  .admin-login-trust {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .admin-workflow-steps {
    overflow-x:
      auto;

    padding-bottom:
      4px;
  }

}


@media (max-width: 480px) {

  .admin-login-header {
    padding-inline:
      14px;
  }

  .admin-login-brand strong {
    font-size:
      17px;
  }

  .admin-login-brand span {
    font-size:
      11px;
  }

  .admin-login-back {
    font-size:
      12px;
  }

  .admin-login-intro h1 {
    font-size:
      39px;
  }

  .admin-login-card-heading h2 {
    font-size:
      26px;
  }

  .admin-login-trust {
    grid-template-columns:
      1fr;
  }

}
/* =========================================================
   KRISHISETU PAGE TRANSITIONS
========================================================= */

.page-transition {
  animation:
    page-enter
    0.55s
    cubic-bezier(0.22, 1, 0.36, 1)
    both;
}

.page-transition-exit {
  animation:
    page-exit
    0.28s
    ease
    both;
}


/* Destination page */

@keyframes page-enter {

  from {
    opacity: 0;
    transform:
      translateY(14px);
  }

  to {
    opacity: 1;
    transform:
      translateY(0);
  }

}


/* Leaving page */

@keyframes page-exit {

  from {
    opacity: 1;
    transform:
      translateY(0);
  }

  to {
    opacity: 0;
    transform:
      translateY(-8px);
  }

}


/* Respect reduced-motion preference */

@media (prefers-reduced-motion: reduce) {

  .page-transition,
  .page-transition-exit {
    animation: none;
  }

}
/* =========================================================
   PREMIUM PAGE TRANSITION
========================================================= */

.page-transition-overlay {
  position: fixed;
  inset: 0;
  z-index: 99999;
  pointer-events: none;
  background:
    radial-gradient(
      circle at 50% 45%,
      rgba(86, 160, 92, 0.18),
      transparent 38%
    ),
    rgba(248, 250, 246, 0.96);

  opacity: 0;
  visibility: hidden;

  transform:
    scale(1.08);

  transition:
    opacity 0.55s cubic-bezier(.76, 0, .24, 1),
    visibility 0.55s,
    transform 0.8s cubic-bezier(.76, 0, .24, 1);
}


.page-transition-overlay.active {
  opacity: 1;
  visibility: visible;
  transform: scale(1);
}


.page-transition-glow {
  position: absolute;

  width: 45vw;
  height: 45vw;

  left: 50%;
  top: 50%;

  transform:
    translate(-50%, -50%);

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(95, 170, 98, 0.14),
      rgba(95, 170, 98, 0.04) 40%,
      transparent 70%
    );

  filter:
    blur(20px);

  animation:
    page-transition-pulse
    1.1s
    ease-out
    both;
}


.page-transition-content {
  opacity: 1;

  transform:
    translateY(0)
    scale(1);

  filter:
    blur(0);

  transition:
    opacity 0.7s cubic-bezier(.22, 1, .36, 1),
    transform 0.8s cubic-bezier(.22, 1, .36, 1),
    filter 0.7s ease;
}


.page-transition-content.active {
  opacity: 0;

  transform:
    translateY(18px)
    scale(0.985);

  filter:
    blur(8px);
}


@keyframes page-transition-pulse {

  0% {
    opacity: 0;
    transform:
      translate(-50%, -50%)
      scale(0.72);
  }

  45% {
    opacity: 1;
  }

  100% {
    opacity: 0;
    transform:
      translate(-50%, -50%)
      scale(1.15);
  }

}

.page-transition {
  min-height: 100%;
  width: 100%;
  will-change: transform, opacity, filter;
}

/* =========================================================
   ADMIN DASHBOARD
========================================================= */

.admin-dashboard-page {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
  padding: 8px 4px 40px;

  color: #17231b;
  background: #f7f9f6;
}


/* =========================================================
   HERO
========================================================= */

.admin-dashboard-hero {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;

  margin-bottom: 28px;
}

.admin-dashboard-hero > div:first-child {
