}

.admin-dashboard-hero .admin-page-eyebrow {
  display: block;

  margin-bottom: 8px;

  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;

  color: #5f7d67;
}

.admin-dashboard-hero h2 {
  margin: 0;

  font-size: clamp(30px, 3vw, 42px);
  line-height: 1.08;
  letter-spacing: -0.035em;

  color: #18251d;
}

.admin-dashboard-hero p {
  margin: 12px 0 0;

  max-width: 700px;

  font-size: 16px;
  line-height: 1.7;

  color: #617067;
}


/* =========================================================
   HERO ACTIONS
========================================================= */

.admin-dashboard-actions {
  display: flex;
  align-items: center;
  gap: 10px;

  flex-shrink: 0;
}

.admin-dashboard-live {
  display: inline-flex;
  align-items: center;
  gap: 8px;

  min-height: 38px;
  padding: 0 13px;

  border: 1px solid #d9e6db;
  border-radius: 999px;

  background: #f2f7f2;

  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.11em;

  color: #52705b;
}

.admin-dashboard-live span {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: #4d9b63;

  box-shadow:
    0 0 0 4px rgba(77, 155, 99, 0.1);

  animation:
    admin-live-pulse 2s infinite;
}

.admin-dashboard-refresh {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  min-height: 38px;
  padding: 0 15px;

  border: 1px solid #d7dfd9;
  border-radius: 10px;

  background: #ffffff;

  color: #425248;

  font-size: 13px;
  font-weight: 700;

  cursor: pointer;

  transition:
    transform 0.2s ease,
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.admin-dashboard-refresh:hover {
  transform: translateY(-1px);

  border-color: #b8cbbd;

  box-shadow:
    0 6px 18px rgba(32, 50, 39, 0.07);
}

.admin-dashboard-refresh:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}


/* =========================================================
   ERROR
========================================================= */

.admin-dashboard-error {
  display: flex;
  align-items: center;
  gap: 13px;

  margin-bottom: 22px;
  padding: 15px 17px;

  border: 1px solid #f0d0c8;
  border-radius: 13px;

  background: #fff8f6;

  color: #9b4638;
}

.admin-dashboard-error svg {
  flex-shrink: 0;
}

.admin-dashboard-error > div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-dashboard-error strong {
  font-size: 14px;
  font-weight: 800;
}

.admin-dashboard-error span {
  font-size: 13px;
  color: #9c6860;
}


/* =========================================================
   KPI GRID
========================================================= */

.admin-dashboard-kpi-grid {
  display: grid;
  grid-template-columns:
    repeat(6, minmax(0, 1fr));

  gap: 14px;

  margin-bottom: 22px;
}


/* =========================================================
   KPI CARD
========================================================= */

.admin-dashboard-kpi {
  position: relative;

  display: flex;
  align-items: center;
  gap: 13px;

  min-width: 0;
  min-height: 104px;

  padding: 18px;

  border: 1px solid #e1e7e2;
  border-radius: 16px;

  background: #ffffff;

  box-shadow:
    0 4px 16px rgba(28, 43, 33, 0.04);

  overflow: hidden;

  transition:
    transform 0.22s ease,
    box-shadow 0.22s ease,
    border-color 0.22s ease;
}

.admin-dashboard-kpi::after {
  content: "";

  position: absolute;

  right: -28px;
  bottom: -35px;

  width: 90px;
  height: 90px;

  border-radius: 50%;

  background: currentColor;

  opacity: 0.035;
}

.admin-dashboard-kpi:hover {
  transform: translateY(-3px);

  box-shadow:
    0 12px 28px rgba(28, 43, 33, 0.08);

  border-color: #d3ddd5;
}

.admin-dashboard-kpi-icon {
  display: grid;
  place-items: center;

  flex-shrink: 0;

  width: 43px;
  height: 43px;

  border-radius: 12px;
}

.admin-dashboard-kpi > div:last-child {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 4px;
}

.admin-dashboard-kpi strong {
  display: block;

  font-size: 28px;
  line-height: 1;

  font-weight: 800;
  letter-spacing: -0.025em;

  color: #18251d;
}

.admin-dashboard-kpi strong small {
  font-size: 13px;
  font-weight: 700;
}

.admin-dashboard-kpi span {
  display: block;

  font-size: 12px;
  line-height: 1.35;

  font-weight: 650;

  color: #718077;
}


/* restrained KPI tones */

.admin-dashboard-kpi.blue {
  color: #4178a3;
}

.admin-dashboard-kpi.blue
.admin-dashboard-kpi-icon {
  background: #eef5fa;
  color: #4178a3;
}

.admin-dashboard-kpi.purple {
  color: #746aa3;
}

.admin-dashboard-kpi.purple
.admin-dashboard-kpi-icon {
  background: #f2eff9;
  color: #746aa3;
}

.admin-dashboard-kpi.gold {
  color: #a88239;
}

.admin-dashboard-kpi.gold
.admin-dashboard-kpi-icon {
  background: #faf5e7;
  color: #a88239;
}

.admin-dashboard-kpi.green {
  color: #4b8a5b;
}

.admin-dashboard-kpi.green
.admin-dashboard-kpi-icon {
  background: #edf6ef;
  color: #4b8a5b;
}

.admin-dashboard-kpi.orange {
  color: #b77b4b;
}

.admin-dashboard-kpi.orange
.admin-dashboard-kpi-icon {
  background: #fbf1e8;
  color: #b77b4b;
}

.admin-dashboard-kpi.teal {
  color: #397f7a;
}

.admin-dashboard-kpi.teal
.admin-dashboard-kpi-icon {
  background: #eaf5f3;
  color: #397f7a;
}


/* =========================================================
   GENERIC PANEL
========================================================= */

.admin-dashboard-panel,
.admin-dashboard-alerts-panel,
.admin-dashboard-recent-panel {
  border: 1px solid #e1e7e2;
  border-radius: 18px;

  background: #ffffff;

  box-shadow:
    0 5px 20px rgba(28, 43, 33, 0.035);
}


/* =========================================================
   PANEL HEADER
========================================================= */

.admin-dashboard-panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  padding: 21px 23px 17px;

  border-bottom: 1px solid #edf0ed;
}

.admin-dashboard-panel-header > div:first-child {
