}

.admin-dashboard-panel-header .admin-page-eyebrow {
  display: block;

  margin-bottom: 5px;

  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.15em;

  color: #849189;
}

.admin-dashboard-panel-header h3 {
  margin: 0;

  font-size: 20px;
  line-height: 1.25;

  font-weight: 800;
  letter-spacing: -0.015em;

  color: #203027;
}

.admin-dashboard-panel-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;

  flex-shrink: 0;

