    repeat(2, minmax(0, 1fr));

  gap: 20px;

  margin-bottom: 20px;
}


/* =========================================================
   CENTER LOAD
========================================================= */

.admin-dashboard-center-list {
  padding: 5px 22px 12px;
}

.admin-dashboard-center-row {
  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    minmax(180px, 0.85fr);

  gap: 22px;

  align-items: center;

  padding: 16px 0;

  border-bottom: 1px solid #edf0ed;
}

.admin-dashboard-center-row:last-child {
  border-bottom: 0;
}

.admin-dashboard-center-name {
  display: flex;
  align-items: center;
  gap: 11px;

  min-width: 0;
}

.admin-dashboard-center-name > div {
  display: grid;
  place-items: center;

  width: 36px;
  height: 36px;

  flex-shrink: 0;

  border-radius: 10px;

  background: #ffedd5;

  color: #ea580c;
}

.admin-dashboard-center-name span {
  min-width: 0;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  font-size: 14px;
  font-weight: 750;

  color: #2e3b32;
}

.admin-dashboard-center-load > div:first-child {
  display: flex;
  justify-content: space-between;
  align-items: center;

  margin-bottom: 7px;
}

.admin-dashboard-center-load > div:first-child span {
  font-size: 12px;
  font-weight: 650;

  color: #77837a;
}

.admin-dashboard-center-load > div:first-child strong {
  font-size: 12px;
  font-weight: 800;

  color: #526057;
}

.admin-dashboard-mini-progress {
  width: 100%;
  height: 7px;

  overflow: hidden;

  border-radius: 999px;

  background: #edf1ed;
}

.admin-dashboard-mini-progress > div {
  height: 100%;

  border-radius: inherit;

  background:
    linear-gradient(
      90deg,
      #72a87d,
      #4d8d5c
    );

  transition:
    width 0.6s ease;
}


/* =========================================================
   WORKFLOW
========================================================= */

.admin-dashboard-workflow {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 10px;

  padding: 20px 22px 22px;
}

.admin-dashboard-workflow-step {
  position: relative;

  display: flex;
  flex-direction: column;
  align-items: flex-start;

  min-height: 88px;

  padding: 15px;

  border: 1px solid #e7ebe7;
  border-radius: 13px;

  background: #fbfcfb;
}

.admin-dashboard-workflow-dot {
  width: 9px;
  height: 9px;

  margin-bottom: 13px;

  border-radius: 50%;

  background: currentColor;

  box-shadow:
    0 0 0 5px rgba(0, 0, 0, 0.025);
}

.admin-dashboard-workflow-step span {
  font-size: 12px;
  font-weight: 700;

  color: #6e7b72;
}

.admin-dashboard-workflow-step strong {
  margin-top: 4px;

  font-size: 24px;
  line-height: 1;

  font-weight: 850;

  color: #202e26;
}


/* workflow tones are muted */

.admin-dashboard-workflow-step.blue {
  color: #547c9e;
  background: #fff7ed;
}

.admin-dashboard-workflow-step.purple {
  color: #817ba5;
  background: #fbfafd;
}

.admin-dashboard-workflow-step.gold {
  color: #a08d4d;
  background: #fdfcf9;
}

.admin-dashboard-workflow-step.green {
  color: #5b8d65;
  background: #fafcfa;
}

.admin-dashboard-workflow-step.orange {
  color: #ad8056;
  background: #fdfbf9;
}

.admin-dashboard-workflow-step.teal {
  color: #4d827e;
  background: #f9fcfb;
}


/* =========================================================
   MONEY
========================================================= */

.admin-dashboard-money {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 10px;

  padding: 20px 22px 22px;
}

.admin-dashboard-money-card {
  min-width: 0;

  padding: 17px;

  border: 1px solid #e7ebe7;
  border-radius: 13px;

  background: #fbfcfb;
}

.admin-dashboard-money-card span {
  display: block;

  margin-bottom: 8px;

  font-size: 11px;
  font-weight: 750;

  color: #7b877e;
}

.admin-dashboard-money-card strong {
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  font-size: clamp(15px, 1.5vw, 22px);
  line-height: 1.15;

  font-weight: 850;
  letter-spacing: -0.025em;

  color: #243229;
}

.admin-dashboard-money-card.paid {
  background: #f8fcf9;
  border-color: #dfece1;
}

.admin-dashboard-money-card.pending {
  background: #fffaf5;
  border-color: #eee3d4;
}

.admin-dashboard-money-card.total {
  background: #f8fbfc;
  border-color: #dfe9eb;
}


/* =========================================================
   QUICK ACTIONS
========================================================= */

.admin-dashboard-quick-actions {
  display: grid;

  grid-template-columns:
    1fr 1fr;

  gap: 10px;

  padding: 20px 22px 22px;
}

.admin-dashboard-quick-action {
  display: grid;

  grid-template-columns:
    auto
    minmax(0, 1fr)
    auto;

  align-items: center;

  gap: 11px;

  min-width: 0;

  padding: 13px;

  border: 1px solid #e7ebe7;
  border-radius: 13px;

  background: #fbfcfb;

  text-decoration: none;

  transition:
    transform 0.2s ease,
    border-color 0.2s ease,
    background 0.2s ease,
    box-shadow 0.2s ease;
}

.admin-dashboard-quick-action:hover {
  transform: translateY(-2px);

  border-color: #cfdbd1;

  background: #ffffff;

  box-shadow:
    0 8px 22px rgba(32, 48, 38, 0.06);
}

.admin-dashboard-quick-icon {
  display: grid;
  place-items: center;

  width: 38px;
  height: 38px;

  border-radius: 10px;

  background: #eff5f0;

  color: #55775d;
}

.admin-dashboard-quick-action > div:nth-child(2) {
  min-width: 0;
}

.admin-dashboard-quick-action strong {
  display: block;

  font-size: 13px;
  font-weight: 800;

  color: #2d3a31;
}

.admin-dashboard-quick-action span {
  display: block;

  margin-top: 3px;

  font-size: 11px;
  line-height: 1.45;

  color: #7a857d;
}

.admin-dashboard-quick-action > svg {
  color: #a3aca6;
}


/* =========================================================
   RECENT BOOKINGS
========================================================= */

.admin-dashboard-recent-panel {
  overflow: hidden;
}

.admin-dashboard-recent-list {
  width: 100%;
}

.admin-dashboard-recent-row {
  display: grid;

  grid-template-columns:
    90px
    minmax(150px, 1.3fr)
    minmax(95px, 0.8fr)
    minmax(90px, 0.8fr)
    120px;

  gap: 16px;

  align-items: center;

  padding: 14px 22px;

  border-top: 1px solid #edf0ed;
}

.admin-dashboard-recent-row:hover {
  background: #fbfcfb;
}

.admin-dashboard-recent-token {
  font-size: 14px;
  font-weight: 850;

  color: #385a43;
}

.admin-dashboard-recent-farmer {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-dashboard-recent-farmer strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  font-size: 14px;
  font-weight: 800;

  color: #26352c;
}

.admin-dashboard-recent-farmer span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  font-size: 12px;

  color: #7b877e;
}

.admin-dashboard-recent-crop {
  display: flex;
  align-items: center;
  gap: 6px;

  min-width: 0;
}

.admin-dashboard-recent-crop svg {
  flex-shrink: 0;

  color: #679070;
}

.admin-dashboard-recent-crop span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  font-size: 12px;
  font-weight: 700;

  color: #637168;
}

.admin-dashboard-recent-row > div:nth-child(4) {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-dashboard-recent-row > div:nth-child(4) strong {
  font-size: 13px;
  font-weight: 800;

  color: #344139;
}

.admin-dashboard-recent-row > div:nth-child(4) span {
  font-size: 10px;
  font-weight: 700;

  color: #909b93;
}

.admin-dashboard-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  width: fit-content;

  min-height: 28px;
  padding: 0 9px;

  border-radius: 999px;

  font-size: 10px;
  font-weight: 800;

  white-space: nowrap;
}

.admin-dashboard-status.blue {
  background: #eef5fa;
  color: #4e7597;
}

.admin-dashboard-status.orange {
  background: #fbf1e8;
  color: #aa7544;
}

.admin-dashboard-status.purple {
  background: #f2eff9;
  color: #746d9c;
}

.admin-dashboard-status.gold {
  background: #faf5e6;
  color: #9f873f;
}

.admin-dashboard-status.green {
  background: #edf6ef;
  color: #4e8459;
}

.admin-dashboard-status.teal {
  background: #eaf5f3;
  color: #477d78;
}


/* =========================================================
   EMPTY
========================================================= */

.admin-dashboard-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 11px;

  min-height: 150px;

  padding: 24px;

  color: #7a857d;

  font-size: 14px;
  font-weight: 650;
}

.admin-dashboard-empty svg {
  color: #7fa187;
}


/* =========================================================
   LOADING
========================================================= */

.admin-dashboard-loading {
  padding: 12px 22px 20px;
}

.admin-dashboard-skeleton {
  display: grid;

  grid-template-columns:
    80px
    1fr
    1fr
    100px;

  gap: 18px;

  padding: 15px 0;

  border-bottom: 1px solid #edf0ed;
}

.admin-dashboard-skeleton span {
  height: 13px;

  border-radius: 999px;

  background:
    linear-gradient(
      90deg,
      #edf0ed,
      #f5f7f5,
      #edf0ed
    );

  background-size: 200% 100%;

  animation:
    admin-dashboard-skeleton-shimmer
    1.4s
    infinite;
}


/* =========================================================
   FOOTER
========================================================= */

.admin-dashboard-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;

  margin-top: 18px;

  font-size: 11px;
  font-weight: 650;

  color: #8a958d;
}

.admin-dashboard-footer svg {
  color: #76917d;
}


/* =========================================================
   ANIMATION
========================================================= */

@keyframes admin-live-pulse {

  0%,
  100% {
    box-shadow:
      0 0 0 4px rgba(77, 155, 99, 0.08);
  }

  50% {
    box-shadow:
      0 0 0 7px rgba(77, 155, 99, 0.03);
  }

}

@keyframes admin-dashboard-skeleton-shimmer {

  0% {
    background-position:
      200% 0;
  }

  100% {
    background-position:
      -200% 0;
  }

}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1250px) {

  .admin-dashboard-kpi-grid {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }

}


@media (max-width: 1050px) {

  .admin-dashboard-main-grid {
    grid-template-columns:
      1fr;
  }

  .admin-dashboard-payment-issues-card {
    grid-template-columns:
      auto
      minmax(0, 1fr)
      auto;
  }

  .admin-dashboard-payment-issues-button {
    grid-column:
      2 / -1;

    justify-self:
      start;
  }

}


@media (max-width: 850px) {

  .admin-dashboard-hero {
    align-items: flex-start;

    flex-direction: column;
  }

  .admin-dashboard-actions {
    width: 100%;
  }

  .admin-dashboard-refresh {
    margin-left: auto;
  }

  .admin-dashboard-workflow {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .admin-dashboard-recent-row {
    grid-template-columns:
      75px
      minmax(140px, 1fr)
      minmax(90px, 0.7fr)
      100px;
  }

  .admin-dashboard-recent-crop {
    display: none;
  }

}


@media (max-width: 650px) {

  .admin-dashboard-page {
    padding:
      4px
      0
      28px;
  }

  .admin-dashboard-hero h2 {
    font-size: 29px;
  }

  .admin-dashboard-hero p {
    font-size: 14px;
  }

  .admin-dashboard-kpi-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .admin-dashboard-kpi {
    min-height: 94px;
    padding: 14px;
  }

  .admin-dashboard-kpi strong {
    font-size: 24px;
  }

  .admin-dashboard-panel-header {
    padding:
      18px
      17px
      15px;
  }

  .admin-dashboard-panel-header h3 {
    font-size: 18px;
  }

  .admin-dashboard-workflow {
    grid-template-columns:
      1fr 1fr;

    padding:
      16px
      17px
      18px;
  }

  .admin-dashboard-money {
    grid-template-columns:
      1fr;

    padding:
      16px
      17px
      18px;
  }

  .admin-dashboard-quick-actions {
    grid-template-columns:
      1fr;

    padding:
      16px
      17px
      18px;
  }

  .admin-dashboard-center-list {
    padding:
      3px
      17px
      12px;
  }

  .admin-dashboard-center-row {
    grid-template-columns:
      1fr;

    gap: 10px;
  }

  .admin-dashboard-payment-issues-card {
    grid-template-columns:
      auto
      minmax(0, 1fr);

    gap: 13px;

    padding: 17px;
  }

  .admin-dashboard-payment-issues-count {
    display: none;
  }

  .admin-dashboard-payment-issues-button {
    grid-column:
      1 / -1;

    justify-self:
      stretch;

    justify-content:
      center;
  }

  .admin-dashboard-recent-row {
    grid-template-columns:
      68px
      minmax(0, 1fr)
      90px;
  }

  .admin-dashboard-recent-row > div:nth-child(4) {
    display: none;
  }

  .admin-dashboard-recent-row {
    padding:
      13px
      17px;
  }

}


@media (max-width: 430px) {

  .admin-dashboard-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .admin-dashboard-workflow {
    grid-template-columns:
      1fr;
  }

  .admin-dashboard-actions {
    flex-wrap: wrap;
  }

  .admin-dashboard-live {
    flex: 1;
  }

  .admin-dashboard-refresh {
    margin-left: 0;
  }

}
.farmer-home-header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  position: relative;
}

.farmer-notification-wrap {
  position: relative;
}

.farmer-notification-button {
  position: relative;
  width: 38px;
  height: 38px;
  border: 1px solid rgba(27, 50, 35, 0.10);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.88);
  color: #284d37;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition:
    transform 180ms ease,
    background 180ms ease,
    box-shadow 180ms ease,
    border-color 180ms ease;
}

.farmer-notification-button:hover,
.farmer-notification-button.open {
  transform: translateY(-1px);
  background: #ffffff;
  border-color: rgba(39, 92, 59, 0.18);
  box-shadow: 0 8px 20px rgba(28, 58, 40, 0.08);
}

.farmer-notification-count {
  position: absolute;
  top: -4px;
  right: -4px;
  min-width: 18px;
  height: 18px;
  padding: 0 4px;
  border-radius: 999px;
  background: #d94f45;
  color: #fff;
  font-size: 10px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid #fff;
}

.farmer-notification-panel {
  position: absolute;
  top: calc(100% + 12px);
  right: 0;
  width: 360px;
  max-width: calc(100vw - 32px);
  background: rgba(255, 255, 255, 0.97);
  border: 1px solid rgba(35, 61, 44, 0.10);
  border-radius: 18px;
  box-shadow: 0 20px 55px rgba(26, 48, 34, 0.14);
  overflow: hidden;
  z-index: 1000;
  animation: farmerNotificationOpen 180ms ease-out;
  transform-origin: top right;
}

@keyframes farmerNotificationOpen {
  from {
    opacity: 0;
    transform: translateY(-6px) scale(0.98);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.farmer-notification-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  padding: 17px 18px 15px;
  border-bottom: 1px solid rgba(35, 61, 44, 0.08);
}

.farmer-notification-header > div {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.farmer-notification-header strong {
  font-size: 14px;
  font-weight: 700;
  color: #183524;
}

.farmer-notification-close {
  width: 30px;
  height: 30px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: #718078;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.farmer-notification-close:hover {
  background: rgba(30, 60, 40, 0.06);
  color: #213c2b;
}

.farmer-notification-list {
  max-height: 390px;
  overflow-y: auto;
}

.farmer-notification-item {
  width: 100%;
  display: flex;
  align-items: flex-start;
  gap: 11px;
  padding: 15px 18px;
  border: 0;
  border-bottom: 1px solid rgba(35, 61, 44, 0.06);
  background: transparent;
  text-align: left;
  cursor: pointer;
  transition: background 160ms ease;
}

.farmer-notification-item:last-child {
  border-bottom: 0;
}

.farmer-notification-item:hover {
  background: rgba(43, 102, 68, 0.035);
}

.farmer-notification-item.unread {
  background: rgba(43, 102, 68, 0.045);
}

.farmer-notification-item.read {
  opacity: 0.78;
}

.farmer-notification-dot {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  margin-top: 6px;
  border-radius: 50%;
  background: #6c9d78;
}

.farmer-notification-item.unread .farmer-notification-dot {
  background: #2f7d4a;
  box-shadow: 0 0 0 4px rgba(47, 125, 74, 0.10);
}

.farmer-notification-content {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.farmer-notification-content strong {
  font-size: 13px;
  line-height: 1.35;
  color: #193625;
}

.farmer-notification-content span {
  font-size: 12px;
  line-height: 1.5;
  color: #637267;
}

.farmer-notification-content small {
  font-size: 10.5px;
  line-height: 1.3;
  color: #8a958e;
}

.farmer-notification-empty {
  min-height: 150px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 9px;
  text-align: center;
  color: #87938b;
  font-size: 12px;
}

@media (max-width: 700px) {
  .farmer-notification-panel {
    position: fixed;
    top: 74px;
    right: 16px;
    left: 16px;
    width: auto;
    max-width: none;
  }
}
/* =========================================================
   FARMER NOTIFICATIONS — PREMIUM / SPOTABLE
========================================================= */

.farmer-home-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  position: relative;
}

.farmer-notification-wrap {
  position: relative;
}

/* Main bell button */
.farmer-notification-button {
  position: relative;
  width: 46px;
  height: 46px;
  border: 1px solid rgba(38, 104, 62, 0.18);
  border-radius: 14px;
  background:
    linear-gradient(
      145deg,
      #edf8ef 0%,
      #dff1e3 100%
    );
  color: #23723f;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;

  box-shadow:
    0 7px 18px rgba(39, 105, 61, 0.10),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);

  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    background 180ms ease,
    border-color 180ms ease;
}

.farmer-notification-button:hover,
.farmer-notification-button.open {
  transform: translateY(-2px);

  background:
    linear-gradient(
      145deg,
      #e8f6eb 0%,
      #d5ebda 100%
    );

  border-color: rgba(38, 104, 62, 0.28);

  box-shadow:
    0 11px 25px rgba(39, 105, 61, 0.15),
    0 0 0 4px rgba(57, 139, 79, 0.06);
}

/* Strong unread indication */
.farmer-notification-button.has-unread {
  animation: farmerNotificationPulse 2.8s ease-in-out infinite;
}

@keyframes farmerNotificationPulse {
  0%,
  100% {
    box-shadow:
      0 7px 18px rgba(39, 105, 61, 0.10),
      0 0 0 0 rgba(47, 125, 74, 0);
  }

  50% {
    box-shadow:
      0 10px 22px rgba(39, 105, 61, 0.14),
      0 0 0 7px rgba(47, 125, 74, 0.08);
  }
}

/* Bigger notification badge */
.farmer-notification-count {
  position: absolute;
  top: -7px;
  right: -7px;

  min-width: 23px;
  height: 23px;
  padding: 0 6px;

  border-radius: 999px;

  background: #d84b43;
  color: #ffffff;

  border: 3px solid #ffffff;

  font-size: 11px;
  line-height: 1;
  font-weight: 800;

  display: flex;
  align-items: center;
