    1px solid
    rgba(37, 70, 48, .08);

  border-radius: 16px;

  background:
    rgba(255,255,255,.72);
}


.home-detail-icon {
  width: 40px;

  height: 40px;

  min-width: 40px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 12px;

  background: #f1f6f1;

  color: #4d7659;
}


.home-detail > div:last-child {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}


.home-detail > div:last-child span {
  color: #8a978e;

  font-size: 10.5px;

  font-weight: 700;

  text-transform: uppercase;

  letter-spacing: .07em;
}


.home-detail > div:last-child strong {
  color: #2b4634;

  font-size: 13.5px;

  font-weight: 750;
}


.home-detail > div:last-child small {
  color: #748178;

  font-size: 11.5px;
}


/* payment strip */

.home-payment-complete-strip {
  position: relative;

  z-index: 2;

  display: grid;

  grid-template-columns:
    repeat(2, minmax(0,1fr));

  gap: 12px;

  margin-top: 15px;

  padding: 16px;

  border-radius: 16px;

  background:
    linear-gradient(
      135deg,
      #eef8ee,
      #e4f2e6
    );

  border:
    1px solid
    rgba(49, 119, 67, .09);
}


.home-payment-complete-strip > div {
  display: flex;

  flex-direction: column;

  gap: 4px;
}


.home-payment-complete-strip span {
  color: #65816c;

  font-size: 10px;

  font-weight: 800;

  letter-spacing: .10em;
}


.home-payment-complete-strip strong {
  color: #28613b;

  font-size: 18px;

  font-weight: 800;
}


/* actions */

.booking-action-row {
  position: relative;

  z-index: 2;

  display: flex;

  align-items: center;

  gap: 11px;

  flex-wrap: wrap;

  margin-top: 20px;
}


/* =========================================================
   BUTTONS
========================================================= */

.home-primary-action,
.home-secondary-action {
  min-height: 45px;

  padding:
    0
    17px;

  border-radius: 13px;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 9px;

  font-size: 13px;

  font-weight: 750;

  text-decoration: none;

  transition:
    transform .18s ease,
    box-shadow .18s ease,
    background .18s ease;
}


.home-primary-action {
  border: 0;

  background:
    linear-gradient(
      135deg,
      #39784d,
      #28633c
    );

  color: #fff;

  box-shadow:
    0 9px 20px rgba(40, 99, 60, .18);
}


.home-primary-action:hover {
  transform: translateY(-2px);

  box-shadow:
    0 13px 25px rgba(40, 99, 60, .23);
}


.home-secondary-action {
  border:
    1px solid
    rgba(43, 76, 54, .10);

  background:
    rgba(255,255,255,.82);

  color: #456351;
}


.home-secondary-action:hover {
  transform: translateY(-2px);

  background: #fff;

  box-shadow:
    0 9px 20px rgba(43, 70, 52, .08);
}


/* =========================================================
   QUICK ACTION CARDS
========================================================= */

.farmer-home-grid {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 16px;

  margin-top: 18px;
}


.home-feature-card {
  position: relative;

  min-height: 180px;

  padding: 22px;

  border:
    1px solid
    rgba(41, 70, 50, .09);

  border-radius: 22px;

  background:
    rgba(255,255,255,.84);

  box-shadow:
    0 12px 35px rgba(36, 67, 47, .06);

  text-decoration: none;

  overflow: hidden;

  transition:
    transform .22s ease,
    box-shadow .22s ease,
    border-color .22s ease;
}


.home-feature-card::after {
  content: "";

  position: absolute;

  width: 120px;

  height: 120px;

  right: -45px;

  bottom: -55px;

  border-radius: 50%;

  background:
    rgba(83, 136, 88, .07);
}


.home-feature-card:hover {
  transform: translateY(-5px);

  border-color:
    rgba(46, 106, 62, .15);

  box-shadow:
    0 18px 42px rgba(36, 67, 47, .11);
}


.feature-card-top {
  display: flex;

  align-items: center;

  justify-content: space-between;
}


.feature-icon {
  width: 43px;

  height: 43px;

  border-radius: 13px;

  display: flex;

  align-items: center;

  justify-content: center;

  background: #eef5ee;

  color: #3f7650;
}


.feature-card-top > svg {
  color: #8a988f;
}


.home-feature-card h2 {
  margin: 18px 0 7px;

  color: #23432e;

  font-size: 17px;

  line-height: 1.25;

  font-weight: 760;
}


.home-feature-card p {
  margin: 0;

  max-width: 330px;

  color: #718076;

  font-size: 12.5px;

  line-height: 1.6;
}


/* =========================================================
   GENERIC DASHBOARD SECTIONS
========================================================= */

.home-dashboard-section,
.home-month-summary-card,
.home-center-card,
.home-arrival-check-card,
.home-sms-card {
  border:
    1px solid
    rgba(42, 70, 50, .08);

  border-radius: 22px;

  background:
    rgba(255,255,255,.84);

  box-shadow:
    0 12px 35px rgba(34, 67, 45, .055);
}


/* spacing */

.home-dashboard-section,
.home-month-summary-card {
  margin-top: 18px;

  padding: 23px;
}


/* headings */

.home-section-heading {
  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 20px;

  margin-bottom: 18px;
}


.home-section-heading h2 {
  margin: 5px 0 0;

  color: #203f2b;

  font-size: 20px;

  line-height: 1.25;

  font-weight: 780;

  letter-spacing: -.015em;
}


.home-section-heading p {
  margin: 5px 0 0;

  color: #7a877e;

  font-size: 12px;
}


.home-inline-link {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  color: #3d7650;

  font-size: 12px;

  font-weight: 750;

  text-decoration: none;

  white-space: nowrap;

  transition:
    transform .17s ease,
    color .17s ease;
}


.home-inline-link:hover {
  color: #255d38;

  transform:
    translateX(2px);
}


/* =========================================================
   MONTH SUMMARY
========================================================= */

.home-month-summary-card {
  background:
    linear-gradient(
      145deg,
      rgba(255,255,255,.95),
      rgba(244,249,244,.90)
    );
}


.home-month-stats {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0,1fr));

  gap: 12px;
}


.home-month-stat {
  padding: 16px;

  border-radius: 16px;

  background: #f5f8f4;

  border:
    1px solid
    rgba(44, 76, 53, .07);
}


.home-month-stat span {
  display: block;

  color: #7c8a80;

  font-size: 10.5px;

  font-weight: 750;

  text-transform: uppercase;

  letter-spacing: .07em;
}


.home-month-stat strong {
  display: block;

  margin-top: 5px;

  color: #284a34;

  font-size: 21px;

  line-height: 1.15;

  font-weight: 800;
}


.home-month-stat.green {
  background:
    linear-gradient(
      145deg,
      #eef7ef,
      #f7faf6
    );
}


.home-month-stat.blue {
  background:
    linear-gradient(
      145deg,
      #f0f5f7,
      #f8faf9
    );
}


.home-month-stat.orange {
  background:
    linear-gradient(
      145deg,
      #f8f3e9,
      #fbfaf5
    );
}


/* crop rows */

.home-crop-summary-list {
  margin-top: 14px;
}


.home-crop-summary-row {
  display: grid;

  grid-template-columns:
    auto
    minmax(0,1fr)
    auto;

  align-items: center;

  gap: 12px;

  padding: 13px 0;

  border-bottom:
    1px solid
    rgba(42,70,50,.065);
}


.home-crop-summary-row:last-child {
  border-bottom: 0;
}


.home-crop-summary-icon {
  width: 36px;

  height: 36px;

  border-radius: 11px;

  display: flex;

  align-items: center;

  justify-content: center;

  background: #edf5ee;

  color: #477c54;
}


.home-crop-summary-row > div:nth-child(2) {
  display: flex;

  flex-direction: column;

  gap: 2px;
}


.home-crop-summary-row > div:nth-child(2) strong,
.home-crop-summary-row > div:nth-child(3) strong {
  color: #294535;

  font-size: 13px;

  font-weight: 750;
}


.home-crop-summary-row span {
  color: #88948c;

  font-size: 10.5px;
}


.home-crop-summary-row > div:nth-child(3) {
  display: flex;

  flex-direction: column;

  align-items: flex-end;

  gap: 2px;
}


/* =========================================================
   UPCOMING / PAYMENT / RECENT ROWS
========================================================= */

.home-upcoming-list,
.home-payment-list,
.home-recent-list {
  overflow: hidden;

  border:
    1px solid
    rgba(42,70,50,.07);

  border-radius: 16px;

  background:
    rgba(255,255,255,.55);
}


.home-upcoming-row,
.home-payment-row,
.home-recent-row {
  display: grid;

  align-items: center;

  gap: 13px;

  padding:
    14px
    16px;

  text-decoration: none;

  border-bottom:
    1px solid
    rgba(42,70,50,.06);

  transition:
    background .17s ease,
    padding .17s ease;
}


.home-upcoming-row {
  grid-template-columns:
    auto
    minmax(0,1fr)
    auto
    auto;
}


.home-payment-row {
  grid-template-columns:
    auto
    minmax(0,1fr)
    auto
    auto;
}


.home-recent-row {
  grid-template-columns:
    auto
    minmax(0,1fr)
    auto
    auto;
}


.home-upcoming-row:last-child,
.home-payment-row:last-child,
.home-recent-row:last-child {
  border-bottom: 0;
}


.home-upcoming-row:hover,
.home-payment-row:hover,
.home-recent-row:hover {
  background: #f7faf7;

  padding-left: 19px;
}


.home-upcoming-token,
.home-recent-token {
  padding: 7px 9px;

  border-radius: 9px;

  background: #edf5ee;

  color: #37704a;

  font-size: 11px;

  font-weight: 800;
}


.home-upcoming-main,
.home-payment-main,
.home-recent-main {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 3px;
}


.home-upcoming-main strong,
.home-payment-main strong,
.home-recent-main strong {
  color: #294635;

  font-size: 13px;

  font-weight: 750;
}


.home-upcoming-main span,
.home-payment-main span,
.home-recent-main span {
  color: #849088;

  font-size: 10.5px;
}


.home-upcoming-time {
  color: #53675a;

  font-size: 11.5px;

  font-weight: 700;

  white-space: nowrap;
}


.home-payment-icon {
  width: 34px;

  height: 34px;

  border-radius: 10px;

  background: #eaf5ec;

  color: #3a8050;

  display: flex;

  align-items: center;

  justify-content: center;
}


.home-payment-amount {
  display: flex;

  flex-direction: column;

  align-items: flex-end;

  gap: 2px;
}


.home-payment-amount strong {
  color: #2d6940;

  font-size: 14px;

  font-weight: 800;
}


.home-payment-amount span {
  color: #829088;

  font-size: 10px;
}


/* =========================================================
   CENTER CARD
========================================================= */

.home-center-card {
  margin-top: 18px;

  padding: 25px;

  background:
    linear-gradient(
      145deg,
      #f9fcf8,
      #f0f6f0
    );
}


.home-center-main {
  display: flex;

  align-items: flex-start;

  gap: 14px;
}


.home-center-icon {
  width: 46px;

  height: 46px;

  min-width: 46px;

  border-radius: 14px;

  background: #e3f0e4;

  color: #3d7950;

  display: flex;

  align-items: center;

  justify-content: center;
}


.home-center-main h2 {
  margin: 5px 0 3px;

  color: #24432f;

  font-size: 20px;

  font-weight: 780;
}


.home-center-main p {
  margin: 0;

  color: #79877d;

  font-size: 12px;
}


.home-center-details {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0,1fr));

  gap: 10px;

  margin-top: 20px;
}


.home-center-details > div {
  padding: 13px 14px;

  border-radius: 13px;

  background:
    rgba(255,255,255,.70);

  border:
    1px solid
    rgba(44,75,53,.07);
}


.home-center-details span {
  display: block;

  color: #8a978f;

  font-size: 10px;

  font-weight: 750;

  text-transform: uppercase;

  letter-spacing: .07em;
}


.home-center-details strong {
  display: block;

  margin-top: 4px;

  color: #35503e;

  font-size: 12.5px;
}


.home-center-actions {
  display: flex;

  justify-content: flex-end;

  gap: 10px;

  margin-top: 18px;
}


/* =========================================================
   ARRIVAL CHECK
========================================================= */

.home-arrival-check-card {
  margin-top: 18px;

  padding: 23px;
}


.home-arrival-check-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0,1fr));

  gap: 10px;
}


.home-arrival-check {
  display: flex;

  align-items: center;

  gap: 9px;

  padding: 12px;

  border-radius: 13px;

  background: #f5f8f4;

  border:
    1px solid
    rgba(43,75,51,.06);
}


.home-arrival-check > div {
  width: 25px;

  height: 25px;

  border-radius: 8px;

  background: #dfeee1;

  color: #39774a;

  display: flex;

  align-items: center;

  justify-content: center;
}


.home-arrival-check span {
  color: #52655a;

  font-size: 11px;

  line-height: 1.35;

  font-weight: 650;
}


/* =========================================================
   SMS / STATUS CARD
========================================================= */

.home-sms-card {
  display: flex;

  align-items: flex-start;

  gap: 16px;

  margin-top: 18px;

  padding: 22px;

  background:
    linear-gradient(
      135deg,
      #fffaf0,
      #fffdf8
    );

  border-color:
    rgba(192, 152, 48, .13);
}


.home-sms-icon {
  width: 47px;

  height: 47px;

  min-width: 47px;

  border-radius: 14px;

  display: flex;

  align-items: center;

  justify-content: center;

  background: #f8edc9;

  color: #a07817;
}


.home-sms-card > div:last-child span {
  color: #9c7b29;

  font-size: 10px;

  font-weight: 800;

  letter-spacing: .12em;
}


.home-sms-card h3 {
  margin: 6px 0 5px;

  color: #493d23;

  font-size: 16px;

  line-height: 1.35;

  font-weight: 760;
}


.home-sms-card p {
  margin: 0;

  color: #837761;

  font-size: 12px;

  line-height: 1.55;
}


/* =========================================================
   EMPTY STATES
========================================================= */

.home-summary-empty {
  min-height: 110px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  gap: 8px;

  padding: 20px;

  text-align: center;

  color: #87938b;
}


.home-summary-empty.large {
  min-height: 150px;
}


.home-summary-empty strong {
  color: #475d4e;

  font-size: 13px;
}


.home-summary-empty span {
  max-width: 420px;

  color: #8a968e;

  font-size: 11px;

  line-height: 1.5;
}


/* =========================================================
   NOTIFICATION PANEL
========================================================= */

.farmer-notification-panel {
  position: absolute;

  top: calc(100% + 14px);

  right: 0;

  width: 400px;

  max-width:
    calc(100vw - 30px);

  background:
    rgba(255,255,255,.98);

  border:
    1px solid
    rgba(62, 66, 47, .10);

  border-radius: 21px;

  overflow: hidden;

  box-shadow:
    0 28px 70px rgba(45, 45, 25, .17);

  z-index: 1000;

  animation:
    farmer-notification-in
    .22s
    cubic-bezier(.2,.8,.2,1);
}


@keyframes farmer-notification-in {

  from {
    opacity: 0;

    transform:
      translateY(-9px)
      scale(.97);
  }

  to {
    opacity: 1;

    transform:
      translateY(0)
      scale(1);
  }

}


.farmer-notification-header {
  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  padding: 19px 20px 17px;

  background:
    linear-gradient(
      180deg,
      #fff9e8,
      #ffffff
    );

  border-bottom:
    1px solid
    rgba(62,66,47,.08);
}


.farmer-notification-header > div {
  display: flex;

  flex-direction: column;

  gap: 5px;
}


.farmer-notification-header strong {
  color: #493d23;

  font-size: 15px;

  font-weight: 760;
}


.farmer-notification-close {
  width: 32px;

  height: 32px;

  border: 0;

  border-radius: 9px;

  background:
    rgba(171,135,41,.08);

  color: #756d5b;

  display: flex;

  align-items: center;

  justify-content: center;

  cursor: pointer;
}


.farmer-notification-list {
  max-height: 440px;

  overflow-y: auto;
}


.farmer-notification-item {
  width: 100%;

  display: flex;

  align-items: flex-start;

  gap: 13px;

  padding: 17px 20px;

  border: 0;

  border-bottom:
    1px solid
    rgba(60,60,35,.06);

  background:
    #fff;

  text-align: left;

  cursor: pointer;

  transition:
    background .16s ease;
}


.farmer-notification-item:hover {
  background: #fffdf8;
}


.farmer-notification-item.unread {
  background:
    linear-gradient(
      90deg,
      rgba(223,175,48,.11),
      rgba(223,175,48,.025)
    );
}


.farmer-notification-dot {
  width: 10px;

  height: 10px;

  min-width: 10px;

  margin-top: 6px;

  border-radius: 50%;

  background: #b4b0a4;
}


.farmer-notification-item.unread
.farmer-notification-dot {
  background: #d4a32e;

  box-shadow:
    0 0 0 5px rgba(212,163,46,.11);
}


.farmer-notification-content {
  min-width: 0;

  display: flex;

  flex-direction: column;

  gap: 5px;
}


.farmer-notification-content strong {
  color: #453a24;

  font-size: 13.5px;

  line-height: 1.35;

  font-weight: 750;
}


.farmer-notification-content span {
  color: #756e61;

  font-size: 12px;

  line-height: 1.55;
}


.farmer-notification-content small {
  color: #9a9284;

  font-size: 10.5px;
}


/* =========================================================
   FOOTER SUPPORT
========================================================= */

.home-support-row {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 20px;

  margin-top: 26px;

  padding:
    0
    4px;
}


.home-support-row > span {
  color: #87948b;

  font-size: 11px;
}


.home-support-row > div {
  display: flex;

  align-items: center;

  gap: 16px;
}


.home-support-row a {
  color: #60776a;

  font-size: 11px;

  font-weight: 700;

  text-decoration: none;
}


.home-support-row a:hover {
  color: #2d6840;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1000px) {

  .farmer-home-container {
    width:
      min(
        100% - 34px,
        900px
      );
  }

  .farmer-welcome {
    align-items: flex-start;

    flex-direction: column;
  }

  .farmer-profile {
    width: 100%;

    max-width: 420px;
  }

  .farmer-home-grid {
    grid-template-columns:
      1fr;
  }

  .home-center-details {
    grid-template-columns:
      1fr 1fr;
  }

  .home-arrival-check-grid {
    grid-template-columns:
      1fr 1fr;
  }

}


@media (max-width: 720px) {

  .farmer-home-container {
    width:
      calc(100% - 24px);

    padding-top: 20px;
  }

  .farmer-welcome h1 {
    font-size: 31px;
  }

  .farmer-welcome p {
    font-size: 14px;
  }

  .next-booking-card {
    padding: 21px;

    border-radius: 22px;
  }

  .booking-main-details,
  .home-payment-complete-strip,
  .home-month-stats,
  .home-center-details {
    grid-template-columns:
      1fr;
  }

  .home-arrival-check-grid {
    grid-template-columns:
      1fr 1fr;
  }

  .home-sms-card {
    flex-direction: column;
  }

  .home-upcoming-row,
  .home-payment-row,
  .home-recent-row {
    grid-template-columns:
      auto
      minmax(0,1fr)
      auto;
  }

  .home-upcoming-time {
    grid-column: 2 / -1;
  }

  .home-support-row {
    flex-direction: column;

    align-items: flex-start;
  }

}


@media (max-width: 500px) {

  .farmer-profile {
    min-width: 0;
  }

  .farmer-avatar {
    width: 52px;

    height: 52px;

    min-width: 52px;
  }

  .farmer-notification-button {
    width: 48px;

