  justify-content: space-between;

  gap: 30px;

  margin-bottom: 24px;

  padding:
    27px
    29px;

  border:
    1px solid
    rgba(41, 77, 51, .09);

  border-radius: 24px;

  background:
    linear-gradient(
      135deg,
      rgba(255,255,255,.93),
      rgba(239,247,239,.86)
    );

  box-shadow:
    0 16px 40px
    rgba(38, 69, 47, .07);
}

.farmer-settings-hero h1 {
  margin: 7px 0 7px;

  color: #1b3a26;

  font-size:
    clamp(28px, 4vw, 39px);

  line-height: 1.05;

  letter-spacing: -.035em;

  font-weight: 820;
}

.farmer-settings-hero p {
  margin: 0;

  max-width: 650px;

  color: #718076;

  font-size: 13px;

  line-height: 1.6;
}

.farmer-settings-hero-icon {
  width: 62px;

  height: 62px;

  min-width: 62px;

  border-radius: 19px;

  display: flex;

  align-items: center;

  justify-content: center;

  background:
    linear-gradient(
      145deg,
      #e6f3e7,
      #d6ebda
    );

  color: #3d7650;

  box-shadow:
    inset 0 1px 0
    rgba(255,255,255,.9);
}


/* =========================================================
   SETTINGS LAYOUT
========================================================= */

.farmer-settings-layout {
  display: flex;

  flex-direction: column;

  gap: 17px;
}


/* =========================================================
   CARD
========================================================= */

.farmer-settings-card {
  padding:
    24px
    25px;

  border:
    1px solid
    rgba(41, 77, 51, .085);

  border-radius: 20px;

  background:
    rgba(255,255,255,.90);

  box-shadow:
    0 10px 31px
    rgba(36, 66, 45, .05);
}


/* =========================================================
   SECTION HEADING
========================================================= */

.farmer-settings-section-heading {
  display: flex;

  align-items: flex-start;

  gap: 13px;

  margin-bottom: 22px;
}

.farmer-settings-section-icon {
  width: 42px;

  height: 42px;

  min-width: 42px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 12px;

  background: #edf5ee;

  color: #427653;
}

.farmer-settings-section-icon.green {
  background: #e9f5ea;

  color: #39764a;
}

.farmer-settings-section-icon.gold {
  background: #fbf3d9;

  color: #a17b21;
}

.farmer-settings-section-heading h2 {
  margin: 1px 0 4px;

  color: #294535;

  font-size: 17px;

  font-weight: 780;
}

.farmer-settings-section-heading p {
  margin: 0;

  color: #849088;

  font-size: 11.5px;

  line-height: 1.5;
}


/* =========================================================
   FIELD GRID
========================================================= */

.farmer-settings-grid {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 16px;
}

.farmer-settings-field.full {
  grid-column:
    1 / -1;
}


/* =========================================================
   FIELD
========================================================= */

.farmer-settings-field {
  display: flex;

  flex-direction: column;

  gap: 8px;
}

.farmer-settings-label {
  display: flex;

  align-items: center;

  gap: 7px;

  color: #55695c;

  font-size: 11px;

  font-weight: 800;

  letter-spacing: .02em;
}

.farmer-settings-label svg {
  color: #66816d;
}

.farmer-settings-field input,
.farmer-settings-field select {
  width: 100%;

  min-height: 47px;

  box-sizing: border-box;

  padding:
    0
    14px;

  border:
    1px solid
    #dfe6e0;

  border-radius: 12px;

  outline: none;

  background:
    #fbfcfb;

  color: #2d4535;

  font-family: inherit;

  font-size: 13px;

  font-weight: 550;

  transition:
    border-color .18s ease,
    background .18s ease,
    box-shadow .18s ease;
}

.farmer-settings-field input:focus,
.farmer-settings-field select:focus {
  border-color:
    #78a082;

  background:
    #ffffff;

  box-shadow:
    0 0 0 4px
    rgba(74, 133, 84, .09);
}

.farmer-settings-field input::placeholder {
  color: #a0aaa3;
}


/* =========================================================
   QUANTITY
========================================================= */

.farmer-settings-input-with-suffix {
  position: relative;
}

.farmer-settings-input-with-suffix input {
  padding-right: 48px;
}

.farmer-settings-input-with-suffix span {
  position: absolute;

  right: 14px;

  top: 50%;

  transform:
    translateY(-50%);

  color: #87938a;

  font-size: 11px;

  font-weight: 750;
}


/* =========================================================
   NOTIFICATION PREFERENCES
========================================================= */

.farmer-settings-preferences {
  display: flex;

  flex-direction: column;

  gap: 9px;
}

.farmer-settings-preference {
  display: flex;

  align-items: center;

  gap: 13px;

  padding:
    15px
    16px;

  border:
    1px solid
    #e8ece8;

  border-radius: 14px;

  background:
    #fafcf9;

  transition:
    border-color .18s ease,
    background .18s ease;
}

.farmer-settings-preference:hover {
  border-color:
    #d8e2d9;

  background:
    #ffffff;
}

.farmer-settings-preference-icon {
  width: 38px;

  height: 38px;

  min-width: 38px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  background: #edf5ee;

  color: #487859;
}

.farmer-settings-preference-copy {
  min-width: 0;

  flex: 1;

  display: flex;

  flex-direction: column;

  gap: 3px;
}

.farmer-settings-preference-copy strong {
  color: #304838;

  font-size: 13px;

  font-weight: 760;
}

.farmer-settings-preference-copy span {
  color: #829087;

  font-size: 11px;

  line-height: 1.45;
}


/* toggle */

.farmer-settings-toggle {
  width: 47px;

  height: 27px;

  padding: 3px;

  border: 0;

  border-radius: 999px;

  background: #d7ddd8;

  cursor: pointer;

  transition:
    background .18s ease;
}

.farmer-settings-toggle span {
  display: block;

  width: 21px;

  height: 21px;

  border-radius: 50%;

  background: #fff;

  box-shadow:
    0 2px 5px
    rgba(25, 45, 31, .16);

  transition:
    transform .18s ease;
}

.farmer-settings-toggle.active {
  background: #4f8a5d;
}

.farmer-settings-toggle.active span {
  transform:
    translateX(20px);
}


/* =========================================================
   ERROR
========================================================= */

.farmer-settings-error {
  display: flex;

  align-items: center;

  gap: 9px;

  padding:
    13px
    15px;

  border:
    1px solid
    #ecd7d2;

  border-radius: 12px;

  background:
    #fff8f6;

  color: #a3574b;

  font-size: 12px;

  font-weight: 650;
}


/* =========================================================
   SAVE ROW
========================================================= */

.farmer-settings-save-row {
  display: flex;

  justify-content: flex-end;

  align-items: center;

  gap: 10px;

  padding-top: 4px;
}

.farmer-settings-primary,
.farmer-settings-secondary {
  min-height: 45px;

  padding:
    0
    17px;

  border-radius: 12px;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 8px;

  font-size: 12.5px;

  font-weight: 750;

  text-decoration: none;

  cursor: pointer;

  transition:
    transform .18s ease,
    box-shadow .18s ease,
    background .18s ease;
}

.farmer-settings-primary {
  border: 0;

  background:
    linear-gradient(
      135deg,
      #3c7c4e,
      #28623b
    );

  color: #ffffff;

  box-shadow:
    0 8px 18px
    rgba(42, 99, 58, .17);
}

.farmer-settings-primary:hover {
  transform:
    translateY(-2px);

  box-shadow:
    0 12px 23px
    rgba(42, 99, 58, .22);
}

.farmer-settings-primary:disabled {
  opacity: .62;

  cursor: not-allowed;

  transform: none;
}

.farmer-settings-secondary {
  border:
    1px solid
    #dce3dd;

  background:
    #ffffff;

  color: #617066;
}

.farmer-settings-secondary:hover {
  background:
    #f7faf7;
}


/* =========================================================
   EMPTY
========================================================= */

.farmer-settings-empty {
  min-height: 420px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  gap: 11px;

  padding: 30px;

  text-align: center;

  border:
    1px solid
    rgba(41,77,51,.09);

  border-radius: 24px;

  background:
    rgba(255,255,255,.9);

  box-shadow:
    0 16px 40px
    rgba(38,69,47,.07);

  color: #748178;
}

.farmer-settings-empty h1 {
  margin: 4px 0;

  color: #294635;

  font-size: 24px;
}

.farmer-settings-empty p {
  margin: 0;

  font-size: 13px;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 700px) {

  .farmer-settings-container {
    width:
      calc(100% - 24px);

    padding-bottom: 45px;
  }

  .farmer-settings-hero {
    align-items: flex-start;

    padding: 22px;
  }

  .farmer-settings-hero-icon {
    display: none;
  }

  .farmer-settings-grid {
    grid-template-columns: 1fr;
  }

  .farmer-settings-field.full {
    grid-column: auto;
  }

  .farmer-settings-save-row {
    flex-direction: column-reverse;

    align-items: stretch;
  }

  .farmer-settings-primary,
  .farmer-settings-secondary {
    width: 100%;
  }

}

