  overflow: visible;

  transition:
    transform .2s ease,
    box-shadow .2s ease,
    filter .2s ease !important;
}


.farmer-notification-button::before {
  content: "";

  position: absolute;

  inset: -4px;

  border-radius: 16px;

  background:
    rgba(255, 215, 55, .22);

  filter: blur(7px);

  z-index: -1;

