/* =========================================================
   FARMER LOGOUT — COMPACT → EXPANDED HOVER
========================================================= */

.farmer-logout-button {
  position: relative;

  width: 42px;
  height: 42px;
  min-width: 42px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 0;

  padding: 0;

  overflow: hidden;

  border: 1px solid #e1c9c5;
  border-radius: 12px;

  background:
    linear-gradient(
      145deg,
      #fff9f7,
      #fff3f0
    );

  color: #b95d50;

  cursor: pointer;

  white-space: nowrap;

  transition:
    width .3s cubic-bezier(.2,.8,.2,1),
    padding .3s ease,
    gap .25s ease,
    background .25s ease,
    color .25s ease,
    border-color .25s ease,
    box-shadow .25s ease,
    transform .2s ease;
}


/* Icon stays visible */

.farmer-logout-button svg {
  flex-shrink: 0;

  transition:
    transform .3s ease;
}


/* Hidden text is created from the button title */

.farmer-logout-button::after {
  content: "Logout";

  max-width: 0;

  margin-left: 0;

  overflow: hidden;

  opacity: 0;

  color: inherit;

  font-size: 11px;
  font-weight: 850;

  transition:
    max-width .3s cubic-bezier(.2,.8,.2,1),
    margin-left .25s ease,
    opacity .2s ease;
}


