/* =========================================================
   KRISHISETU — PREMIUM HERO VISUAL
   Self-contained illustration
========================================================= */

/* ---------------------------------------------------------
   VISUAL STAGE
--------------------------------------------------------- */

.landing-hero-visual {
  position: relative !important;

  width: 100% !important;
  height: 100% !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  overflow: visible !important;

  pointer-events: none;

  z-index: 2;
}


/* ---------------------------------------------------------
   MAIN CANVAS
--------------------------------------------------------- */

.procurement-radar {
  --green-deep: #124b36;
  --green-main: #198755;
  --green-bright: #35b875;
  --green-soft: #bfe8cf;

  position: relative;

  width: 680px;
  height: 560px;

  max-width: 96%;
  max-height: 96%;

  flex-shrink: 0;

  isolation: isolate;

  pointer-events: none;
}


/* ---------------------------------------------------------
   AMBIENT LIGHT
--------------------------------------------------------- */

.procurement-radar-glow {
  position: absolute;

  width: 72%;
  height: 72%;

  left: 14%;
  top: 14%;

  border-radius: 50%;

  background:
    radial-gradient(
      ellipse at center,
      rgba(47, 183, 111, 0.17) 0%,
      rgba(47, 183, 111, 0.08) 35%,
      rgba(47, 183, 111, 0.025) 58%,
      transparent 76%
    );

  filter: blur(34px);

  animation:
    hero-glow-breathe
    6s
    ease-in-out
    infinite;

  z-index: -5;
}


/* ---------------------------------------------------------
   ORBIT GROUP
--------------------------------------------------------- */

.procurement-radar-orbit {
  position: absolute;

  left: 50%;
  top: 50%;

  border-radius: 50%;

  pointer-events: none;

  transform:
    translate(-50%, -50%);
}


/* outer orbital shell */

.procurement-radar-orbit-outer {

  width: 92%;
  height: 84%;

  border:
    1px solid
    rgba(
      24,
      133,
      81,
      0.16
    );

  transform:
    translate(-50%, -50%)
    rotate(-7deg);

  box-shadow:
    0 0 0 1px
      rgba(
        255,
        255,
        255,
        0.18
      )
      inset;

  animation:
    premium-orbit-one
    34s
    linear
    infinite;
}


/* middle orbital shell */

.procurement-radar-orbit-middle {

  width: 74%;
  height: 67%;

  border:
    1px solid
    rgba(
      30,
      151,
      92,
      0.13
    );

  transform:
    translate(-50%, -50%)
    rotate(9deg);

  animation:
    premium-orbit-two
    25s
    linear
    infinite
    reverse;
}


/* inner orbital shell */

.procurement-radar-orbit-inner {

  width: 54%;
  height: 48%;

  border:
    1px dashed
    rgba(
      30,
      151,
      92,
      0.13
    );

  transform:
    translate(-50%, -50%)
    rotate(-4deg);

}


/* ---------------------------------------------------------
   ORBIT ACCENT LIGHTS
--------------------------------------------------------- */

.procurement-radar-orbit-outer::before,
.procurement-radar-orbit-outer::after {

  content: "";

  position: absolute;

  width: 7px;
  height: 7px;

  border-radius: 50%;

  background:
    var(--green-bright);

  box-shadow:
    0 0 0 5px
      rgba(
        53,
        184,
        117,
        0.08
      ),
    0 0 20px
      rgba(
        53,
        184,
        117,
        0.45
      );

}


/* deliberately asymmetric positions */

.procurement-radar-orbit-outer::before {

  left: 16%;
  top: 3%;

}


.procurement-radar-orbit-outer::after {

  right: 10%;
  bottom: 7%;

}


/* ---------------------------------------------------------
   CONNECTION LINES
--------------------------------------------------------- */

.procurement-radar::before {

  content: "";

  position: absolute;

  left: 15%;
  right: 15%;

  top: 50%;

  height: 1px;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(
        26,
        145,
        87,
        0.13
      ),
      rgba(
        26,
        145,
        87,
        0.28
      ),
      rgba(
        26,
        145,
        87,
        0.13
      ),
      transparent
    );

  transform:
    rotate(
      -9deg
    );

  opacity:
    0.75;

  z-index:
    0;

}


/* ---------------------------------------------------------
   CENTER HUB
--------------------------------------------------------- */

.procurement-radar-center {

  position: absolute;

  left: 50%;
  top: 50%;

  width: 122px;
  height: 122px;

  transform:
    translate(-50%, -50%);

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  z-index:
    10;

}


/* outer hub halo */

.procurement-radar-center::before {

  content: "";

  position: absolute;

  inset: -13px;

  border-radius: 50%;

  border:
    1px solid
    rgba(
      31,
      152,
      91,
      0.13
