[data-theme="dark"] textarea:hover,
[data-theme="dark"] select:hover,

[data-theme="forest"] input:hover,
[data-theme="forest"] textarea:hover,
[data-theme="forest"] select:hover,

[data-theme="midnight"] input:hover,
