    var(--theme-surface-2) !important;

  border-color:
    var(--theme-border) !important;
}


/* =========================================================
   21. BUTTON HOVER SAFETY
   Don't recolor every button.
   Only prevent a WHITE background from old theme rules.
========================================================= */

[data-theme="dark"] button:hover,
[data-theme="forest"] button:hover,
[data-theme="midnight"] button:hover {

  filter:
    none !important;
}


/* =========================================================
   22. REMOVE TRANSITION-BASED COLOR FLICKER
========================================================= */

/*
   The problem is often a transition between:
     light theme color
         ↓
     dark theme color

   during scroll/repaint.

   For theme-sensitive properties, remove interpolation.
*/

[data-theme="dark"] *,
[data-theme="forest"] *,
[data-theme="midnight"] * {
  transition-property:
    transform,
    opacity,
    box-shadow,
    border-color !important;
}


/* =========================================================
   23. EXPLICITLY DISABLE COLOR TRANSITIONS
========================================================= */

[data-theme="dark"] *,
[data-theme="forest"] *,
[data-theme="midnight"] * {
  transition:
    transform 0.25s ease,
    opacity 0.25s ease,
    box-shadow 0.25s ease !important;
}


/* =========================================================
   24. PREVENT FLASHING FILTER EFFECTS
========================================================= */

[data-theme="dark"] *,
[data-theme="forest"] *,
[data-theme="midnight"] * {
  filter:
    none;
}


/* =========================================================
   25. FINAL SCROLL STABILITY
========================================================= */

[data-theme="dark"],
[data-theme="dark"] body,
[data-theme="dark"] #root,

[data-theme="forest"],
[data-theme="forest"] body,
[data-theme="forest"] #root,

[data-theme="midnight"],
[data-theme="midnight"] body,
[data-theme="midnight"] #root {
  color-scheme:
    dark;
}


