[data-theme="dark"] input:disabled,
[data-theme="dark"] select:disabled,
[data-theme="dark"] textarea:disabled,

[data-theme="forest"] button:disabled,
[data-theme="forest"] input:disabled,
[data-theme="forest"] select:disabled,
[data-theme="forest"] textarea:disabled,

[data-theme="midnight"] button:disabled,
[data-theme="midnight"] input:disabled,
[data-theme="midnight"] select:disabled,
