/* =========================================================
   SCHEDULE DETAILS
========================================================= */

.admin-full-schedule-cell {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.admin-full-schedule-cell .admin-queue-waiting {
  width: fit-content;
  margin-top: 2px;
}

.admin-queue-waiting {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  padding: 3px 6px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 800;
}

.admin-queue-waiting.normal {
  background: var(--theme-surface-2, #f0f3f1);
}

.admin-queue-waiting.active {
  background: rgba(45, 124, 84, 0.11);
  color: var(--theme-primary, #2d7c54);
}

.admin-queue-waiting.waiting {
  background: rgba(187, 122, 46, 0.12);
  color: var(--theme-orange, #b67832);
}

.admin-queue-waiting.complete {
  background: rgba(45, 124, 84, 0.10);
  color: var(--theme-primary, #2d7c54);
}

.admin-queue-waiting.payment {
  background: rgba(170, 125, 49, 0.12);
  color: var(--theme-gold, #aa7d31);
}


/* =========================================================
   URGENCY
========================================================= */

.admin-full-status-cell {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 5px;
}

.admin-queue-urgency {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  padding: 3px 6px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 800;
}

.admin-queue-urgency.normal {
  background: var(--theme-surface-2, #f0f3f1);
  color: inherit;
  opacity: 0.68;
}

.admin-queue-urgency.soon {
  background: rgba(185, 138, 57, 0.12);
  color: var(--theme-gold, #aa7d31);
}

.admin-queue-urgency.active {
  background: rgba(45, 124, 84, 0.11);
  color: var(--theme-primary, #2d7c54);
}

.admin-queue-urgency.urgent {
  background: rgba(182, 111, 49, 0.13);
  color: var(--theme-orange, #b66f31);
}

.admin-queue-urgency.late {
  background: rgba(179, 75, 72, 0.12);
  color: var(--theme-danger, #b34b48);
}


/* =========================================================
   DRAWER PRIORITY
========================================================= */

.admin-drawer-priority-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding: 10px 18px;
  border-top: 1px solid var(--theme-border, rgba(120, 140, 130, 0.14));
  border-bottom: 1px solid var(--theme-border, rgba(120, 140, 130, 0.14));
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 760px) {

  .admin-queue-live-meta {
    flex-wrap: wrap;
  }

  .admin-queue-health {
    flex-direction: column;
    align-items: flex-start;
  }

  .admin-queue-health-metrics {
    width: 100%;
    justify-content: space-between;
  }

  .admin-queue-table-meta {
    flex-wrap: wrap;
  }

}

/* =========================================================
   BOOKING CONFIRMATION OVERLAY
========================================================= */

.booking-confirmed-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(10, 25, 18, 0.58);
  backdrop-filter: blur(8px);
}

.booking-confirmed-card {
  width: min(420px, 100%);
  padding: 32px 28px;
  text-align: center;
  border-radius: 22px;
  background: var(--theme-surface, #ffffff);
  border: 1px solid var(--theme-border, rgba(120, 140, 130, 0.18));
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.22);
}

.booking-confirmed-icon {
  width: 58px;
  height: 58px;
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 18px;
  background: rgba(45, 124, 84, 0.12);
  color: var(--theme-primary, #2d7c54);
}

.booking-confirmed-card h2 {
  margin: 8px 0 10px;
}

.booking-confirmed-card p {
  margin: 0 0 18px;
  opacity: 0.72;
  line-height: 1.55;
}

.slot-card.past {
  opacity: 0.42;
  cursor: not-allowed;
}

.slot-card.past:hover {
  transform: none !important;
}

.slot-card.past .slot-card-footer {
  opacity: 0.7;
}


/* =========================================================
   PAYMENT PAGE - NEW ENHANCEMENTS
   Add this at the END of your existing admin CSS
========================================================= */


/* =========================================================
   PAYMENT INSIGHT STRIP
========================================================= */

.admin-payment-insight-strip {

  display: flex;

  align-items: center;

  gap: 14px;

  width: 100%;

  padding: 15px 18px;

  margin: 18px 0;

  border: 1px solid
    color-mix(
      in srgb,
      var(--admin-accent, #4f8f68) 20%,
      transparent
    );

  border-radius: 14px;

  background:
    color-mix(
      in srgb,
      var(--admin-surface, #ffffff) 94%,
      var(--admin-accent, #4f8f68)
    );

  box-sizing: border-box;

}


.admin-payment-insight-icon {

  width: 38px;

  height: 38px;

  min-width: 38px;

  display: grid;

  place-items: center;

  border-radius: 11px;

  background:
    rgba(61, 126, 87, 0.12);

  color:
    #3d7e57;

}


.admin-payment-insight-strip > div:nth-child(2) {

  min-width: 0;

  flex: 1;

}


.admin-payment-insight-strip strong {

  display: block;

  margin-bottom: 3px;

  font-size: 14px;

  line-height: 1.35;

  font-weight: 700;

}


.admin-payment-insight-strip span {

  display: block;

  font-size: 12px;

  line-height: 1.5;

  opacity: 0.72;

}


.admin-payment-insight-amount {

  text-align: right;

  flex-shrink: 0;

}


.admin-payment-insight-amount span {

  margin-bottom: 3px;

  font-size: 10px;

  text-transform: uppercase;

  letter-spacing: 0.08em;

}


.admin-payment-insight-amount strong {

  margin: 0;

  font-size: 16px;

}


/* =========================================================
   PAYMENT MODAL SUMMARY
========================================================= */

.admin-payment-form-summary {

  display: flex;

  flex-direction: column;

  gap: 14px;

  padding: 15px;

  margin-bottom: 18px;

  border: 1px solid
    rgba(120, 140, 125, 0.16);

  border-radius: 14px;

  background:
    rgba(120, 140, 125, 0.045);

}


.admin-payment-form-booking {

  display: flex;

  align-items: center;

  gap: 12px;

}


.admin-payment-form-token {

  display: inline-flex;

  align-items: center;

  justify-content: center;

  min-width: 58px;

  padding: 8px 10px;

  border-radius: 9px;

  background:
    rgba(58, 111, 77, 0.1);

  color:
    #3a704d;

  font-size: 14px;

  font-weight: 800;

  letter-spacing: 0.02em;

}


.admin-payment-form-booking > div:last-child {

  min-width: 0;

}


.admin-payment-form-booking strong {

  display: block;

  font-size: 14px;

  line-height: 1.35;

}


.admin-payment-form-booking span {

  display: block;

  margin-top: 2px;

  font-size: 11px;

  opacity: 0.65;

}


/* =========================================================
   PAYMENT VERIFICATION GRID
========================================================= */

.admin-payment-form-verification {

  display: grid;

  grid-template-columns:
    repeat(
      4,
      minmax(0, 1fr)
    );

  gap: 10px;

}


.admin-payment-form-verification > div {

  min-width: 0;

  padding: 10px 11px;

  border-radius: 10px;

  background:
    rgba(255, 255, 255, 0.45);

  border: 1px solid
    rgba(100, 120, 108, 0.08);

}


.admin-payment-form-verification span {

  display: block;

  margin-bottom: 4px;

  font-size: 9px;

  line-height: 1.3;

  text-transform: uppercase;

  letter-spacing: 0.07em;

  opacity: 0.58;

}


.admin-payment-form-verification strong {

  display: block;

  font-size: 12px;

  line-height: 1.4;

  overflow-wrap: anywhere;

}


/* =========================================================
   AMOUNT WARNING
========================================================= */

.payment-amount-warning {

  display: block;

  margin-top: 6px;

  font-size: 11px;

  line-height: 1.4;

}


.payment-amount-warning.positive {

  color:
    #a66b13;

}


.payment-amount-warning.negative {

  color:
    #a84747;

}


/* =========================================================
   UPI HELPER
========================================================= */

.admin-payment-upi-helper {

  display: flex;

  align-items: end;

  gap: 10px;

  padding: 11px;

  border-radius: 12px;

  background:
    rgba(68, 117, 87, 0.055);

  border: 1px solid
    rgba(68, 117, 87, 0.12);

}


.admin-payment-upi-helper .admin-payment-field {

  flex: 1;

  min-width: 0;

  margin: 0;

}


.admin-payment-open-upi {

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 7px;

  min-height: 42px;

  padding: 0 13px;

  border: 1px solid
    rgba(61, 126, 87, 0.22);

  border-radius: 10px;

  background:
    rgba(61, 126, 87, 0.1);

  color:
    #3d7e57;

  font-size: 12px;

  font-weight: 700;

  white-space: nowrap;

  cursor: pointer;

  transition:
    background-color 0.16s ease,
    border-color 0.16s ease,
    transform 0.16s ease;

}


.admin-payment-open-upi:hover:not(:disabled) {

  background:
    rgba(61, 126, 87, 0.16);

  border-color:
    rgba(61, 126, 87, 0.3);

  transform:
    translateY(-1px);

}


.admin-payment-open-upi:disabled {

  opacity: 0.42;

  cursor: not-allowed;

  transform: none;

}


/* =========================================================
   BANK HELPER
========================================================= */

.admin-payment-bank-helper {

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  padding: 12px 13px;

  border-radius: 12px;

  border: 1px solid
    rgba(74, 100, 128, 0.14);

  background:
    rgba(74, 100, 128, 0.055);

}


.admin-payment-bank-helper > div {

  display: flex;

  align-items: flex-start;

  gap: 9px;

  min-width: 0;

}


.admin-payment-bank-helper > div svg {

  flex-shrink: 0;

  margin-top: 1px;

  color:
    #52728e;

}


.admin-payment-bank-helper span {

  font-size: 11px;

  line-height: 1.5;

  opacity: 0.72;

}


.admin-payment-bank-helper button {

  flex-shrink: 0;

  display: inline-flex;

  align-items: center;

  gap: 6px;

  min-height: 35px;

  padding: 0 11px;

  border: 1px solid
    rgba(82, 114, 142, 0.2);

  border-radius: 9px;

  background:
    rgba(82, 114, 142, 0.09);

  color:
    #52728e;

  font-size: 11px;

  font-weight: 700;

  cursor: pointer;

}


.admin-payment-bank-helper button:hover {

  background:
    rgba(82, 114, 142, 0.15);

}


/* =========================================================
   REFERENCE INPUT + COPY BUTTON
========================================================= */

.admin-payment-reference-input {

  display: flex;

  align-items: stretch;

  width: 100%;

}


.admin-payment-reference-input input {

  flex: 1;

  min-width: 0;

  border-top-right-radius: 0;

  border-bottom-right-radius: 0;

}


.admin-payment-reference-input button {

  width: 43px;

  min-width: 43px;

  display: grid;

  place-items: center;

  border: 1px solid
    rgba(120, 140, 125, 0.2);

  border-left: 0;

  border-top-right-radius: 9px;

  border-bottom-right-radius: 9px;

  background:
    rgba(120, 140, 125, 0.07);

  color:
    inherit;

  cursor: pointer;

  transition:
    background-color 0.16s ease;

}


.admin-payment-reference-input button:hover:not(:disabled) {

  background:
    rgba(120, 140, 125, 0.13);

}


.admin-payment-reference-input button:disabled {

  opacity: 0.35;

  cursor: not-allowed;

}


/* =========================================================
   PAYMENT FORM SPACING
========================================================= */

.admin-payment-form {

  display: flex;

  flex-direction: column;

  gap: 14px;

}


.admin-payment-form .admin-payment-field {

  margin: 0;

}


/* =========================================================
   IMPROVED PAYMENT WARNING
========================================================= */

.admin-payment-form-warning {

  display: flex;

  align-items: flex-start;

  gap: 9px;

  padding: 11px 13px;

  border-radius: 11px;

  border: 1px solid
    rgba(177, 130, 44, 0.17);

  background:
    rgba(177, 130, 44, 0.065);

}


.admin-payment-form-warning svg {

  flex-shrink: 0;

  margin-top: 1px;

}


.admin-payment-form-warning span {

  font-size: 11px;

  line-height: 1.5;

  opacity: 0.78;

}


/* =========================================================
   FORM BUTTONS
========================================================= */

.admin-payment-form-actions {

  display: flex;

  align-items: center;

  justify-content: flex-end;

  gap: 10px;

  margin-top: 4px;

}


.admin-payment-form-submit {

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 7px;

}


.admin-payment-form-cancel {

  display: inline-flex;

  align-items: center;

  justify-content: center;

}


/* =========================================================
   TABLE PAYMENT AMOUNT EXTRA LINE
========================================================= */

.admin-payment-amount small {

  display: block;

  margin-top: 3px;

  font-size: 10px;

  opacity: 0.52;

}


/* =========================================================
   PAYMENT INSIGHT DARK THEME
========================================================= */

[data-theme="dark"] .admin-payment-insight-strip,
.dark .admin-payment-insight-strip {

  background:
    rgba(255, 255, 255, 0.025);

  border-color:
    rgba(130, 170, 145, 0.16);

}


[data-theme="dark"] .admin-payment-form-summary,
.dark .admin-payment-form-summary {

  background:
    rgba(255, 255, 255, 0.025);

  border-color:
    rgba(255, 255, 255, 0.07);

}


[data-theme="dark"] .admin-payment-form-verification > div,
.dark .admin-payment-form-verification > div {

  background:
    rgba(255, 255, 255, 0.025);

  border-color:
    rgba(255, 255, 255, 0.055);

}


/* =========================================================
   FOREST THEME
========================================================= */

[data-theme="forest"] .admin-payment-insight-strip,
.forest .admin-payment-insight-strip {

  background:
    rgba(30, 74, 48, 0.16);

  border-color:
    rgba(112, 169, 128, 0.18);

}


[data-theme="forest"] .admin-payment-insight-icon,
.forest .admin-payment-insight-icon {

  background:
    rgba(112, 169, 128, 0.14);

  color:
    #8fbd9a;

}


/* =========================================================
   MIDNIGHT THEME
========================================================= */

[data-theme="midnight"] .admin-payment-insight-strip,
.midnight .admin-payment-insight-strip {

  background:
    rgba(50, 73, 105, 0.14);

  border-color:
    rgba(110, 145, 190, 0.18);

}


[data-theme="midnight"] .admin-payment-insight-icon,
.midnight .admin-payment-insight-icon {

  background:
    rgba(110, 145, 190, 0.13);

  color:
    #8faed3;

}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (
  max-width: 900px
) {

  .admin-payment-form-verification {

    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );

  }


  .admin-payment-bank-helper {

    flex-direction: column;

    align-items: stretch;

  }


  .admin-payment-bank-helper button {

    width: 100%;

  }

}


@media (
  max-width: 640px
) {

  .admin-payment-insight-strip {

    align-items: flex-start;

  }


  .admin-payment-insight-amount {

    display: none;

  }


  .admin-payment-form-verification {

    grid-template-columns:
      1fr;

  }


  .admin-payment-upi-helper {

    flex-direction: column;

    align-items: stretch;

  }


  .admin-payment-open-upi {

    width: 100%;

  }


  .admin-payment-form-actions {

    flex-direction: column-reverse;

    align-items: stretch;

  }


  .admin-payment-form-actions button {

    width: 100%;

  }

}


/* =========================================================
   ACCESSIBILITY
========================================================= */

.admin-payment-open-upi:focus-visible,
.admin-payment-bank-helper button:focus-visible,
.admin-payment-reference-input button:focus-visible {

  outline:
    2px solid
    currentColor;

  outline-offset:
    2px;

}


/* =========================================================
   REDUCE MOTION
========================================================= */

@media (
  prefers-reduced-motion: reduce
) {

  .admin-payment-open-upi,
  .admin-payment-reference-input button {

    transition:
      none;

  }

}

/* =========================================================
   FINAL PROCUREMENT RECEIPT
========================================================= */

.token-completion-receipt-actions {
  width: 100%;
  display: flex;
  justify-content: center;
  margin-top: 14px;
}


.token-receipt-download-button {
  width: 100%;
  min-height: 48px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;

  border: 1px solid rgba(27, 83, 56, 0.18);
  border-radius: 12px;

  background: #f4f8f5;
  color: #1b5338;

  font-size: 14px;
  font-weight: 700;

  cursor: pointer;

  transition:
    background 0.18s ease,
    border-color 0.18s ease,
    transform 0.18s ease,
    box-shadow 0.18s ease;
}


.token-receipt-download-button:hover {
  background: #eaf3ed;
  border-color: rgba(27, 83, 56, 0.3);

  transform: translateY(-1px);

  box-shadow:
    0 7px 18px rgba(27, 83, 56, 0.08);
}


.token-receipt-download-button:active {
  transform: translateY(0);
}


.token-receipt-download-button svg {
  flex-shrink: 0;
}



/* =========================================================
   PAYMENT RECEIPT INLINE CARD
========================================================= */

.token-payment-receipt-inline {
  width: 100%;

  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 13px;

  margin-top: 16px;
  padding: 14px 15px;

  border: 1px solid rgba(27, 83, 56, 0.14);
  border-radius: 14px;

  background: #f7faf8;
}


.token-payment-receipt-inline-icon {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  background: #e2efe6;
  color: #1b5338;

  flex-shrink: 0;
}


.token-payment-receipt-inline > div:nth-child(2) {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 3px;
}


.token-payment-receipt-inline strong {
  color: #21392c;

  font-size: 13px;
  line-height: 1.35;
}


.token-payment-receipt-inline span {
  color: #728078;

  font-size: 12px;
  line-height: 1.5;
}


.token-receipt-inline-button {
  min-height: 38px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;

  padding: 0 13px;

  border: 1px solid rgba(27, 83, 56, 0.18);
  border-radius: 9px;

  background: #ffffff;
  color: #1b5338;

  font-size: 12px;
  font-weight: 700;

  white-space: nowrap;

  cursor: pointer;

  transition:
    background 0.18s ease,
    border-color 0.18s ease,
    transform 0.18s ease;
}


.token-receipt-inline-button:hover {
  background: #eef6f1;
  border-color: rgba(27, 83, 56, 0.28);

  transform: translateY(-1px);
}


.token-receipt-inline-button:active {
  transform: translateY(0);
}



/* =========================================================
   SIDE RECEIPT BUTTON
========================================================= */

.token-receipt-side-button {
  width: 100%;
  min-height: 43px;

  margin-top: 10px;

  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  border: 1px solid rgba(27, 83, 56, 0.2);
  border-radius: 11px;

  background: #ffffff;
  color: #1b5338;

  font-size: 13px;
  font-weight: 700;

  cursor: pointer;

  transition:
    background 0.18s ease,
    border-color 0.18s ease,
    transform 0.18s ease,
    box-shadow 0.18s ease;
}


.token-receipt-side-button:hover {
  background: #eef6f1;
  border-color: rgba(27, 83, 56, 0.3);

  transform: translateY(-1px);

  box-shadow:
    0 6px 16px rgba(27, 83, 56, 0.07);
}


.token-receipt-side-button:active {
  transform: translateY(0);
}


.token-receipt-side-button svg {
  flex-shrink: 0;
}



/* =========================================================
   COMPLETED CARD SPACING
========================================================= */

.token-completed-card
  .token-completion-actions {
  margin-bottom: 2px;
}


.token-completed-card
  .token-payment-issue-button {
  margin-top: 12px;
}



/* =========================================================
   DISABLED STATES
========================================================= */

.token-receipt-download-button:disabled,
.token-receipt-inline-button:disabled,
.token-receipt-side-button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}



/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 700px) {

  .token-payment-receipt-inline {
    grid-template-columns: auto 1fr;
  }


  .token-receipt-inline-button {
    grid-column: 1 / -1;
    width: 100%;
  }


  .token-receipt-download-button {
    min-height: 50px;

    font-size: 13px;
  }


  .token-receipt-side-button {
    min-height: 46px;
  }

}


/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 480px) {

  .token-payment-receipt-inline {
    gap: 10px;

    padding: 12px;
  }


  .token-payment-receipt-inline-icon {
    width: 34px;
    height: 34px;
  }


  .token-payment-receipt-inline strong {
    font-size: 12px;
  }


  .token-payment-receipt-inline span {
    font-size: 11px;
  }


  .token-receipt-download-button {
    padding: 0 12px;
  }

}

/* =========================================================
   LIVE QUEUE POSITION
========================================================= */

.token-queue-position-card {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 16px;
  padding: 16px 18px;
  border: 1px solid #dfe9e3;
  border-radius: 16px;
  background: linear-gradient(
    135deg,
    #f5faf6 0%,
    #ffffff 100%
  );
  box-shadow: 0 8px 24px rgba(27, 83, 56, 0.06);
}

.token-queue-position-icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 13px;
  background: #e7f3eb;
  color: #1b5338;
}

.token-queue-position-content {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.token-queue-position-content > span {
  margin-bottom: 3px;
  color: #718077;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.token-queue-position-content > strong {
  color: #1b5338;
  font-size: 23px;
  line-height: 1.15;
  font-weight: 800;
}

.token-queue-position-content > p {
  margin: 4px 0 0;
  color: #66756c;
  font-size: 12px;
  line-height: 1.5;
}

.token-queue-wait {
  min-width: 118px;
  padding: 10px 13px;
  border: 1px solid #e0e9e3;
  border-radius: 12px;
  background: #ffffff;
  text-align: right;
}

.token-queue-wait span {
  display: block;
  margin-bottom: 3px;
  color: #7d8982;
  font-size: 10px;
  font-weight: 700;
}

.token-queue-wait strong {
  display: block;
  color: #263c30;
  font-size: 14px;
  font-weight: 800;
}


/* =========================================================
   RECEIPT ACTIONS
========================================================= */

.token-completion-receipt-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 18px;
}

.token-receipt-download-button,
.token-receipt-inline-button,
.token-receipt-side-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid #d8e5dc;
  border-radius: 11px;
  background: #ffffff;
  color: #1b5338;
  font-weight: 750;
  cursor: pointer;
  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease,
    background 0.18s ease,
    border-color 0.18s ease;
}

.token-receipt-download-button {
  width: 100%;
  min-height: 44px;
  padding: 11px 16px;
}

.token-receipt-download-button:hover,
.token-receipt-inline-button:hover,
.token-receipt-side-button:hover {
  background: #f2f8f4;
  border-color: #bfd6c6;
  box-shadow: 0 7px 18px rgba(27, 83, 56, 0.08);
  transform: translateY(-1px);
}

.token-receipt-inline-button {
  flex: 0 0 auto;
  min-height: 38px;
  padding: 8px 13px;
}

.token-receipt-side-button {
  width: 100%;
  min-height: 42px;
  margin-top: 10px;
  padding: 10px 14px;
}


/* =========================================================
   INLINE RECEIPT CARD
========================================================= */

.token-payment-receipt-inline {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-top: 16px;
  padding: 14px;
  border: 1px solid #dce8df;
  border-radius: 15px;
  background: #f7fbf8;
}

.token-payment-receipt-inline-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  background: #e3f1e7;
  color: #1b5338;
}

.token-payment-receipt-inline > div:nth-child(2) {
  min-width: 0;
  flex: 1;
}

.token-payment-receipt-inline > div:nth-child(2) strong {
  display: block;
  margin-bottom: 3px;
  color: #294136;
  font-size: 13px;
}

.token-payment-receipt-inline > div:nth-child(2) span {
  display: block;
  color: #748178;
  font-size: 11px;
  line-height: 1.5;
}


/* =========================================================
   PAYMENT COMPLETED CARD
========================================================= */

.token-completed-card {
  position: relative;
  overflow: hidden;
}

.token-completed-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: #1b5338;
}

.token-completed-header {
  display: flex;
  align-items: flex-start;
  gap: 15px;
}

.token-completed-icon {
  width: 52px;
  height: 52px;
  flex: 0 0 52px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 15px;
  background: #e5f3e9;
  color: #1b5338;
}


/* =========================================================
   PAYMENT SUMMARY
========================================================= */

.token-payment-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 20px;
}

.token-payment-item {
  min-width: 0;
  padding: 14px;
  border: 1px solid #e2e9e4;
  border-radius: 13px;
  background: #fafcfb;
}

.token-payment-item span {
  display: block;
  margin-bottom: 6px;
  color: #7a877f;
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.token-payment-item strong {
  display: block;
  color: #263d31;
  font-size: 14px;
  font-weight: 800;
  line-height: 1.35;
  overflow-wrap: anywhere;
}


/* =========================================================
   SMS CONFIRMATION
========================================================= */

.token-sms-confirmation {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-top: 16px;
  padding: 14px;
  border-radius: 14px;
  border: 1px solid #dde8df;
}

.token-sms-confirmation.sent {
  background: #f0f8f3;
  border-color: #cae2d1;
}

.token-sms-confirmation.failed {
  background: #fff5f3;
  border-color: #efd5d0;
}

.token-sms-confirmation.not-sent {
  background: #f8faf9;
  border-color: #e1e7e3;
}

.token-sms-confirmation-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
}

.token-sms-confirmation.sent .token-sms-confirmation-icon {
  background: #dcefe2;
  color: #1b5338;
}

.token-sms-confirmation.failed .token-sms-confirmation-icon {
  background: #f9dfda;
  color: #b84a3d;
}

.token-sms-confirmation.not-sent .token-sms-confirmation-icon {
  background: #edf1ef;
  color: #64726a;
}

.token-sms-confirmation-content {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.token-sms-status-label {
  margin-bottom: 3px;
  color: #78857d;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.11em;
}

.token-sms-confirmation-content strong {
  color: #263d31;
  font-size: 13px;
  line-height: 1.35;
}

.token-sms-confirmation-content > span:last-child {
  margin-top: 3px;
  color: #718078;
  font-size: 11px;
  line-height: 1.45;
}

.token-sms-time {
  flex: 0 0 auto;
  color: #7c8981;
  font-size: 10px;
  white-space: nowrap;
}


/* =========================================================
   QUEUE + COUNTDOWN SPACING
========================================================= */

.token-queue-position-card + .token-arrival-countdown {
  margin-top: 12px;
}


/* =========================================================
   BUTTON INTERACTIONS
========================================================= */

.token-receipt-download-button:active,
.token-receipt-inline-button:active,
.token-receipt-side-button:active {
  transform: translateY(0);
}

.token-receipt-download-button:disabled,
.token-receipt-inline-button:disabled,
.token-receipt-side-button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}


/* =========================================================
   TOKEN VISUAL RECEIPT BUTTON
========================================================= */

.token-visual-card .token-receipt-side-button {
  margin-top: 10px;
}


/* =========================================================
   PAYMENT MODAL
========================================================= */

.token-payment-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(20, 35, 28, 0.52);
  backdrop-filter: blur(7px);
}

.token-payment-modal {
  width: min(560px, 100%);
  max-height: min(760px, calc(100vh - 48px));
  overflow-y: auto;
  padding: 22px;
  border: 1px solid #dce6df;
  border-radius: 20px;
  background: #ffffff;
  box-shadow: 0 24px 70px rgba(17, 36, 26, 0.2);
}

.token-payment-modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 20px;
}

.token-payment-modal-header h2 {
  margin: 6px 0 0;
  color: #21392b;
  font-size: 24px;
  line-height: 1.15;
}

.token-payment-modal-header > button {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #dfe7e2;
  border-radius: 10px;
  background: #ffffff;
  color: #617066;
  cursor: pointer;
}

.token-payment-modal-header > button:hover {
  background: #f4f7f5;
}


/* =========================================================
   PAYMENT ISSUE FORM
========================================================= */

.token-payment-issue-label {
  display: block;
  margin-top: 16px;
}

.token-payment-issue-label > span {
  display: block;
  margin-bottom: 7px;
  color: #3a4e43;
  font-size: 12px;
  font-weight: 750;
}

.token-payment-issue-label select,
.token-payment-issue-label textarea {
  width: 100%;
  border: 1px solid #d9e3dd;
  border-radius: 11px;
  outline: none;
  background: #ffffff;
  color: #2c4034;
  font: inherit;
  transition:
    border-color 0.18s ease,
    box-shadow 0.18s ease;
}

.token-payment-issue-label select {
  min-height: 43px;
  padding: 9px 12px;
}

.token-payment-issue-label textarea {
  min-height: 100px;
  padding: 11px 12px;
  resize: vertical;
}

.token-payment-issue-label select:focus,
.token-payment-issue-label textarea:focus {
  border-color: #91b49c;
  box-shadow: 0 0 0 3px rgba(69, 118, 82, 0.1);
}

.token-payment-support-details {
  display: grid;
  gap: 6px;
  margin-top: 15px;
  padding: 12px 14px;
  border-radius: 11px;
  background: #f6f9f7;
  color: #68776e;
  font-size: 11px;
}

.token-payment-modal-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 18px;
}

.token-payment-help-link,
.token-payment-modal-close {
  min-height: 40px;
  padding: 9px 14px;
  border-radius: 10px;
  font-size: 12px;
  font-weight: 750;
  cursor: pointer;
}

.token-payment-help-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid #1b5338;
  background: #1b5338;
  color: #ffffff;
}

.token-payment-modal-close {
  border: 1px solid #dce5df;
  background: #ffffff;
  color: #53645a;
}

.token-payment-issue-success {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 9px;
  padding: 28px 12px 12px;
  text-align: center;
  color: #1b5338;
}

.token-payment-issue-success strong {
  color: #263d31;
  font-size: 16px;
}

.token-payment-issue-success span {
  max-width: 410px;
  color: #708077;
  font-size: 12px;
  line-height: 1.55;
}


/* =========================================================
   SPINNER
========================================================= */

.token-spin {
  animation: token-spin-animation 0.9s linear infinite;
}

@keyframes token-spin-animation {
  to {
    transform: rotate(360deg);
  }
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 900px) {

  .token-payment-summary {
    grid-template-columns: 1fr;
  }

  .token-queue-position-card {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .token-queue-position-content {
    min-width: calc(100% - 58px);
  }

  .token-queue-wait {
    width: 100%;
    min-width: 0;
    text-align: left;
  }

}


@media (max-width: 640px) {

  .token-queue-position-card {
    gap: 11px;
    padding: 14px;
  }

  .token-queue-position-icon {
    width: 38px;
    height: 38px;
    flex-basis: 38px;
    border-radius: 11px;
  }

  .token-queue-position-content > strong {
    font-size: 20px;
  }

  .token-completion-receipt-actions {
    margin-top: 14px;
  }

  .token-receipt-download-button {
    min-height: 42px;
    padding: 10px 13px;
    font-size: 12px;
  }

  .token-payment-receipt-inline {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .token-payment-receipt-inline > div:nth-child(2) {
    flex-basis: calc(100% - 51px);
  }

  .token-receipt-inline-button {
    width: 100%;
  }

  .token-sms-confirmation {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .token-sms-time {
    width: 100%;
    margin-left: 51px;
  }

  .token-payment-modal-backdrop {
    padding: 12px;
  }

  .token-payment-modal {
    max-height: calc(100vh - 24px);
    padding: 17px;
    border-radius: 16px;
  }

  .token-payment-modal-header h2 {
    font-size: 21px;
  }

  .token-payment-modal-actions {
    flex-direction: column-reverse;
    align-items: stretch;
  }

  .token-payment-help-link,
  .token-payment-modal-close {
    width: 100%;
    justify-content: center;
  }

}


