  }


  .app-header .theme-toggle span,
  .app-header .theme-toggle-button span,
  .app-header .theme-toggle-btn span {
    display: none !important;
  }


  /* =======================================================
     HELP BUTTON
  ======================================================= */

  .header-help-button {
    width: 34px;
    min-width: 34px;

    height: 34px;
    min-height: 34px;

    padding: 0;

    border-radius: 9px;

    display: flex;
    align-items: center;
    justify-content: center;
  }


  .header-help-button span {
    display: none !important;
  }


  .header-help-button svg {
    width: 17px;
    height: 17px;
  }

}


/* =========================================================
   VERY SMALL PHONES
========================================================= */

@media (max-width: 380px) {

  .app-header {
    padding: 7px 9px;
  }


  .app-header-brand,
  .app-header-brand img,
  .app-header-brand svg {
    width: 35px;
    max-width: 35px;
    height: 35px;
  }


  .app-header-actions {
