/* =========================================================
   VOICE ASSISTANT
========================================================= */

.voice-assistant-floating {
  position: fixed;
  right: 24px;
  bottom: 24px;
  width: 52px;
  height: 52px;
  border: 0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 9998;
  color: white;
  background: linear-gradient(
    135deg,
    #0f766e,
    #15803d
  );
  box-shadow:
    0 10px 28px rgba(
      0,
      0,
      0,
      0.18
    ),
    0 3px 8px rgba(
      15,
      118,
      110,
      0.22
    );
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.voice-assistant-floating:hover {
  transform:
    translateY(-2px)
    scale(1.03);
}

.voice-assistant-floating:active {
  transform:
    scale(0.96);
}

.voice-assistant-floating.listening {
  background:
    linear-gradient(
      135deg,
      #dc2626,
      #ea580c
    );
}

.voice-assistant-pulse {
  position: absolute;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  border: 2px solid rgba(
    255,
    255,
    255,
    0.65
  );
  animation:
    voice-assistant-pulse 1.4s
    ease-out infinite;
}

@keyframes voice-assistant-pulse {

  0% {
    transform: scale(1);
    opacity: 0.9;
  }

  70% {
    transform: scale(1.45);
    opacity: 0;
  }

  100% {
    transform: scale(1.45);
    opacity: 0;
  }

}


/* ---------------------------------------------------------
   PANEL
--------------------------------------------------------- */

.voice-assistant-panel {
  position: fixed;
  right: 24px;
  bottom: 88px;
  width: min(
    390px,
    calc(100vw - 32px)
  );
  max-height: min(
    650px,
    calc(100vh - 112px)
  );
  overflow: auto;
  z-index: 9999;

  border: 1px solid rgba(
    15,
    118,
    110,
    0.16
  );

  border-radius: 24px;

  background:
    rgba(
      255,
      255,
      255,
      0.97
    );

  box-shadow:
    0 25px 70px rgba(
      0,
      0,
      0,
      0.17
    ),
    0 8px 24px rgba(
      0,
      0,
      0,
      0.08
    );

  backdrop-filter:
    blur(18px);

  -webkit-backdrop-filter:
    blur(18px);

  animation:
    voice-assistant-panel-in
    0.24s
    ease-out;
}

@keyframes voice-assistant-panel-in {

  from {
    opacity: 0;
    transform:
      translateY(12px)
      scale(0.97);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }

}


