.voice-orb-wave {
  position: absolute;
  inset: -7px;
  border: 1px solid rgba(
    22,
    101,
    52,
    0.20
  );
  border-radius: 50%;
  animation:
    voice-orb-wave 1.8s
    ease-out infinite;
}

.wave-two {
  inset: -14px;
  animation-delay: 0.35s;
}

.wave-three {
  inset: -21px;
  animation-delay: 0.7s;
}

@keyframes voice-orb-wave {

  0% {
    transform: scale(0.88);
    opacity: 0.75;
  }

  80% {
    transform: scale(1.08);
    opacity: 0;
  }

  100% {
