    background 0.25s ease,
    opacity 0.25s ease;
}

.voice-assistant-floating::before {
  content: "";

  position: absolute;
  inset: -5px;

  border-radius: inherit;

  border: 1px solid rgba(255, 255, 255, 0.08);

  opacity: 0;

  transform: scale(0.92);

  transition:
    opacity 0.25s ease,
    transform 0.25s ease;
}

.voice-assistant-floating:hover {
  transform: translateY(-3px) scale(1.035);

  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.23),
      rgba(255, 255, 255, 0.08)
    );

  box-shadow:
    0 20px 44px rgba(0, 0, 0, 0.32),
    0 0 0 5px rgba(255, 255, 255, 0.025),
    inset 0 1px 1px rgba(255, 255, 255, 0.18);
}

.voice-assistant-floating:hover::before {
  opacity: 1;
  transform: scale(1);
}

.voice-assistant-floating:active {
  transform: scale(0.96);
}

.voice-assistant-floating.listening {
  animation: voice-assistant-pulse 1.8s ease-in-out infinite;
}

@keyframes voice-assistant-pulse {
  0%,
  100% {
    box-shadow:
      0 16px 38px rgba(0, 0, 0, 0.28),
      0 0 0 0 rgba(255, 255, 255, 0.18);
  }

  50% {
    box-shadow:
      0 18px 42px rgba(0, 0, 0, 0.30),
      0 0 0 9px rgba(255, 255, 255, 0.035);
  }
}


/* =========================================================
   FLOATING PANEL
========================================================= */

.voice-assistant-panel {
  position: fixed;

  right: 28px;
  bottom: 98px;

  z-index: 1199;

  width: min(560px, calc(100vw - 40px));
  height: min(720px, calc(100vh - 130px));

  display: flex;
  flex-direction: column;

  overflow: hidden;

  border:
    1px solid
    rgba(255, 255, 255, 0.14);

  border-radius: 26px;

  background:
    linear-gradient(
      145deg,
      rgba(20, 25, 31, 0.84),
      rgba(12, 16, 21, 0.78)
    );

  backdrop-filter:
    blur(28px)
    saturate(135%);

  -webkit-backdrop-filter:
    blur(28px)
    saturate(135%);

  box-shadow:
    0 35px 100px rgba(0, 0, 0, 0.48),
    0 10px 30px rgba(0, 0, 0, 0.20),
    inset 0 1px 1px rgba(255, 255, 255, 0.10);

  color: #ffffff;

  transform-origin:
    bottom right;

  animation:
    voice-assistant-open
    0.28s
    cubic-bezier(0.2, 0.85, 0.25, 1);
}

@keyframes voice-assistant-open {
  from {
    opacity: 0;
    transform:
      translateY(18px)
      scale(0.96);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}


/* =========================================================
   HEADER
========================================================= */

.voice-assistant-panel-header {
  min-height: 82px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding:
    18px
    20px;

  border-bottom:
    1px solid
    rgba(255, 255, 255, 0.08);

  background:
    linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.045),
      rgba(255, 255, 255, 0)
    );
}

.voice-assistant-heading {
  display: flex;
  align-items: center;
  gap: 13px;

  min-width: 0;
}

.voice-assistant-heading-icon {
  width: 42px;
  height: 42px;

  flex: 0 0 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 14px;

  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.15),
      rgba(255, 255, 255, 0.045)
    );

  border:
    1px solid
    rgba(255, 255, 255, 0.10);

  box-shadow:
    inset 0 1px 1px rgba(255, 255, 255, 0.08);
}

.voice-assistant-heading > div:last-child {
  min-width: 0;
}

.voice-assistant-heading strong {
  display: block;

  font-size: 16px;
  line-height: 1.25;

  font-weight: 700;

  letter-spacing: -0.015em;
}

.voice-assistant-heading span {
  display: block;

  margin-top: 4px;

  color:
    rgba(255, 255, 255, 0.58);

  font-size: 12px;
  line-height: 1.35;

  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.voice-assistant-header-actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

.voice-assistant-reset,
.voice-assistant-close {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid transparent;
  border-radius: 12px;

  background: transparent;

  color:
    rgba(255, 255, 255, 0.62);

  cursor: pointer;

  transition:
    background 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease;
}

.voice-assistant-reset:hover,
.voice-assistant-close:hover {
  background:
    rgba(255, 255, 255, 0.08);

  color: #ffffff;

  transform: translateY(-1px);
}

.voice-assistant-close:hover {
  background:
    rgba(255, 120, 120, 0.10);
}


/* =========================================================
   BODY
========================================================= */

.voice-assistant-body {
  min-height: 0;

  flex: 1;

  display: flex;
  flex-direction: column;

  padding: 18px;

  overflow: hidden;
}


/* =========================================================
   WELCOME
========================================================= */

.voice-assistant-welcome {
  flex: 1;

  display: flex;
  flex-direction: column;

  align-items: center;
  justify-content: center;

  text-align: center;

  padding:
    30px
    20px;
}

.voice-assistant-orb {
  width: 76px;
  height: 76px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-bottom: 18px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle at 35% 30%,
      rgba(255, 255, 255, 0.24),
      rgba(255, 255, 255, 0.06) 52%,
      rgba(255, 255, 255, 0.025) 100%
    );

  border:
    1px solid
    rgba(255, 255, 255, 0.13);

  box-shadow:
    0 16px 45px rgba(0, 0, 0, 0.25),
    inset 0 1px 1px rgba(255, 255, 255, 0.12);

  color:
    rgba(255, 255, 255, 0.88);
}

.voice-assistant-welcome .voice-assistant-state {
  margin-bottom: 0;
}

.voice-assistant-state {
  text-align: center;
}

.voice-assistant-state strong {
  display: block;

  font-size: 15px;
  line-height: 1.4;

  color:
    rgba(255, 255, 255, 0.84);
}


/* =========================================================
   CONVERSATION
========================================================= */

.voice-assistant-conversation {
  flex: 1;

  min-height: 0;

  overflow-y: auto;

  padding:
    4px
    3px
    18px;

  scroll-behavior: smooth;
}

.voice-assistant-conversation::-webkit-scrollbar {
  width: 6px;
}

.voice-assistant-conversation::-webkit-scrollbar-track {
  background: transparent;
}

.voice-assistant-conversation::-webkit-scrollbar-thumb {
  border-radius: 99px;

  background:
    rgba(255, 255, 255, 0.13);
}

.voice-assistant-message {
  display: flex;
  flex-direction: column;

  max-width: 86%;

  margin-bottom: 18px;
}

.voice-assistant-message.user {
  align-items: flex-end;

  margin-left: auto;
}

.voice-assistant-message.assistant {
  align-items: flex-start;

  margin-right: auto;
}

.voice-assistant-message-label {
  margin-bottom: 6px;

  padding:
    0
    4px;

  color:
    rgba(255, 255, 255, 0.44);

  font-size: 10px;

  font-weight: 700;

  letter-spacing: 0.08em;

  text-transform: uppercase;
}

.voice-assistant-message-bubble {
  padding:
    12px
    15px;

  border-radius: 17px;

  font-size: 14px;
  line-height: 1.55;

  word-break: break-word;

  white-space: pre-wrap;
}

.voice-assistant-message.user
.voice-assistant-message-bubble {
  border:
    1px solid
    rgba(255, 255, 255, 0.09);

  border-bottom-right-radius: 6px;

  background:
    rgba(255, 255, 255, 0.09);

  color:
    rgba(255, 255, 255, 0.93);

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.035);
}

.voice-assistant-message.assistant
.voice-assistant-message-bubble {
  border:
    1px solid
    rgba(255, 255, 255, 0.075);

  border-bottom-left-radius: 6px;

  background:
    rgba(255, 255, 255, 0.045);

  color:
    rgba(255, 255, 255, 0.82);

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.025);
}


/* =========================================================
   LIVE STATUS
========================================================= */

.voice-assistant-live-state {
  flex: 0 0 auto;

  min-height: 28px;

  display: flex;
  align-items: center;
  justify-content: center;

  gap: 7px;

  margin:
    0 0
    8px;

  color:
    rgba(255, 255, 255, 0.52);

  font-size: 12px;
}

.voice-assistant-live-state.listening {
  color:
    rgba(255, 255, 255, 0.84);
}

.voice-assistant-live-state.processing {
  color:
    rgba(255, 255, 255, 0.72);
}


/* =========================================================
   TRANSCRIPT
========================================================= */

.voice-assistant-transcript {
  flex: 0 0 auto;

  margin:
    4px
    0
    10px;

  padding:
    10px
    12px;

  border:
    1px solid
    rgba(255, 255, 255, 0.065);

  border-radius: 13px;

  background:
    rgba(255, 255, 255, 0.03);
}

.voice-assistant-transcript span {
  display: block;

  margin-bottom: 4px;

  color:
    rgba(255, 255, 255, 0.38);

  font-size: 10px;

  font-weight: 700;

  letter-spacing: 0.07em;

  text-transform: uppercase;
}

.voice-assistant-transcript p {
  margin: 0;

  color:
    rgba(255, 255, 255, 0.65);

  font-size: 12px;
  line-height: 1.45;
}


/* =========================================================
   ERROR
========================================================= */

.voice-assistant-error-card {
  flex: 0 0 auto;

  margin:
    2px
    0
    10px;

  padding:
    10px
    12px;

  border:
    1px solid
    rgba(255, 180, 180, 0.11);

  border-radius: 12px;

  background:
    rgba(255, 100, 100, 0.065);

  color:
    rgba(255, 220, 220, 0.76);

  font-size: 12px;
  line-height: 1.45;
}


/* =========================================================
   INPUT
========================================================= */

.voice-assistant-text-form {
  flex: 0 0 auto;

  display: flex;
  align-items: center;

  gap: 8px;

  margin-top: 3px;

  padding: 7px;

  border:
    1px solid
    rgba(255, 255, 255, 0.10);

  border-radius: 16px;

  background:
    rgba(255, 255, 255, 0.055);

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.035);

  transition:
    border-color 0.2s ease,
    background 0.2s ease,
    box-shadow 0.2s ease;
}

.voice-assistant-text-form:focus-within {
  border-color:
    rgba(255, 255, 255, 0.18);

  background:
    rgba(255, 255, 255, 0.065);

  box-shadow:
    0 0 0 3px
    rgba(255, 255, 255, 0.025);
}

.voice-assistant-text-form input {
  min-width: 0;
  flex: 1;

  height: 42px;

  border: 0;
  outline: none;

  background: transparent;

  color: #ffffff;

  font-size: 14px;
}

.voice-assistant-text-form input::placeholder {
  color:
    rgba(255, 255, 255, 0.34);
}

.voice-assistant-text-form input:disabled {
  opacity: 0.55;
}

.voice-assistant-text-form button {
  width: 42px;
  height: 42px;

  flex: 0 0 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 0;
  border-radius: 12px;

  background:
    rgba(255, 255, 255, 0.12);

  color: #ffffff;

  cursor: pointer;

  transition:
    background 0.2s ease,
    transform 0.2s ease,
    opacity 0.2s ease;
}

.voice-assistant-text-form button:hover:not(:disabled) {
  background:
    rgba(255, 255, 255, 0.18);

  transform: translateY(-1px);
}

.voice-assistant-text-form button:active:not(:disabled) {
  transform: scale(0.95);
}

.voice-assistant-text-form button:disabled {
  opacity: 0.28;

  cursor: not-allowed;
}


/* =========================================================
   VOICE BUTTON
========================================================= */

.voice-assistant-main-button {
  flex: 0 0 auto;

  min-height: 48px;

  display: flex;
  align-items: center;
  justify-content: center;

  gap: 8px;

  margin-top: 9px;

  border:
    1px solid
    rgba(255, 255, 255, 0.09);

  border-radius: 14px;

  background:
    rgba(255, 255, 255, 0.065);

  color:
    rgba(255, 255, 255, 0.82);

  font-size: 13px;

  font-weight: 600;

  cursor: pointer;

  transition:
    background 0.2s ease,
    transform 0.2s ease,
    border-color 0.2s ease;
}

.voice-assistant-main-button:hover:not(:disabled) {
  background:
    rgba(255, 255, 255, 0.11);

  border-color:
    rgba(255, 255, 255, 0.15);

  transform: translateY(-1px);
}

.voice-assistant-main-button:active:not(:disabled) {
  transform: scale(0.985);
}

.voice-assistant-main-button.stop {
  background:
    rgba(255, 255, 255, 0.10);
}

.voice-assistant-main-button:disabled {
  opacity: 0.35;

  cursor: not-allowed;
}


/* =========================================================
   EXAMPLES
========================================================= */

.voice-assistant-examples {
  flex: 0 0 auto;

  margin-top: 15px;
}

.voice-assistant-examples-heading {
  margin-bottom: 8px;

  color:
    rgba(255, 255, 255, 0.38);

  font-size: 10px;

  font-weight: 700;

  letter-spacing: 0.09em;

  text-transform: uppercase;
}

.voice-assistant-example-list {
  display: flex;

  gap: 7px;

  overflow-x: auto;

  padding-bottom: 2px;

  scrollbar-width: none;
}

.voice-assistant-example-list::-webkit-scrollbar {
  display: none;
}

.voice-assistant-example-list button {
  flex: 0 0 auto;

  min-height: 34px;

  padding:
    7px
    11px;

  border:
    1px solid
    rgba(255, 255, 255, 0.08);

  border-radius: 999px;

  background:
    rgba(255, 255, 255, 0.035);

  color:
    rgba(255, 255, 255, 0.62);

  font-size: 11px;

  cursor: pointer;

  transition:
    background 0.2s ease,
    color 0.2s ease,
    border-color 0.2s ease;
}

.voice-assistant-example-list button:hover:not(:disabled) {
  background:
    rgba(255, 255, 255, 0.08);

  color:
    rgba(255, 255, 255, 0.88);

  border-color:
    rgba(255, 255, 255, 0.13);
}

.voice-assistant-example-list button:disabled {
  opacity: 0.35;
}


/* =========================================================
   FOOTER
========================================================= */

.voice-assistant-footer {
  min-height: 48px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 12px;

  padding:
    10px
    16px;

  border-top:
    1px solid
    rgba(255, 255, 255, 0.065);

  background:
    rgba(0, 0, 0, 0.08);
}

.voice-assistant-footer button {
  display: inline-flex;
  align-items: center;

  gap: 7px;

  padding: 6px 8px;

  border: 0;
  border-radius: 9px;

  background: transparent;

  color:
    rgba(255, 255, 255, 0.46);

  font-size: 11px;

  cursor: pointer;

  transition:
    color 0.2s ease,
    background 0.2s ease;
}

.voice-assistant-footer button:hover {
  color:
    rgba(255, 255, 255, 0.78);

  background:
    rgba(255, 255, 255, 0.05);
}

.voice-assistant-language {
  color:
    rgba(255, 255, 255, 0.27);

  font-size: 10px;

  letter-spacing: 0.06em;
}


/* =========================================================
   SPINNER
========================================================= */

.voice-assistant-spin {
  animation:
    voice-assistant-spin
    0.9s
    linear
    infinite;
}

@keyframes voice-assistant-spin {
  to {
    transform: rotate(360deg);
  }
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 700px) {

  .voice-assistant-floating {
    right: 18px;
    bottom: 18px;

    width: 54px;
    height: 54px;
  }

  .voice-assistant-panel {
    right: 12px;
    bottom: 82px;

    width: calc(100vw - 24px);
    height: min(
      720px,
      calc(100vh - 98px)
    );

    border-radius: 22px;
  }

  .voice-assistant-panel-header {
    min-height: 74px;

    padding:
      15px
      16px;
  }

  .voice-assistant-body {
    padding:
      15px;
  }

  .voice-assistant-message {
    max-width: 91%;
  }

}


@media (max-width: 430px) {

  .voice-assistant-panel {
    right: 8px;
    bottom: 76px;

    width: calc(100vw - 16px);

    height: calc(100vh - 88px);

    border-radius: 20px;
  }

  .voice-assistant-floating {
    right: 15px;
    bottom: 15px;
  }

  .voice-assistant-heading-icon {
    width: 38px;
    height: 38px;
    flex-basis: 38px;
  }

  .voice-assistant-heading strong {
    font-size: 14px;
  }

  .voice-assistant-heading span {
    font-size: 11px;
  }

  .voice-assistant-message-bubble {
    font-size: 13px;

    padding:
      11px
      13px;
  }

}

/* =========================================================
   KRISHISETU AI ASSISTANT
   Theme-aware standalone styling
========================================================= */

/* ---------------------------------------------------------
   THEME VARIABLES
--------------------------------------------------------- */

:root,
html,
body {
  --ai-green: #2f7d4a;
  --ai-green-dark: #245f39;
  --ai-green-soft: #eaf6ed;

  --ai-yellow: #f4df91;
  --ai-yellow-soft: #fff8dc;

  --ai-blue: #8ebbd4;
  --ai-blue-soft: #edf7fb;

  --ai-white: #ffffff;
  --ai-cream: #faf9f3;

  --ai-text: #183226;
  --ai-text-soft: #63746a;
  --ai-border: rgba(47, 125, 74, 0.14);

  --ai-panel: rgba(255, 255, 255, 0.94);
  --ai-panel-solid: #ffffff;
  --ai-user-bubble: #edf7ef;
  --ai-assistant-bubble: #f7faf7;

  --ai-shadow:
    0 24px 70px rgba(27, 66, 42, 0.17),
    0 8px 30px rgba(27, 66, 42, 0.09);

  --ai-overlay: rgba(17, 34, 23, 0.12);

  --ai-radius-large: 24px;
  --ai-radius-medium: 16px;
  --ai-radius-small: 12px;
}


/* =========================================================
   LIGHT
========================================================= */

body.light,
html.light,
[data-theme="light"],
body[data-theme="light"] {
  --ai-green: #2f7d4a;
  --ai-green-dark: #245f39;
  --ai-green-soft: #eaf6ed;

  --ai-yellow: #f4df91;
  --ai-yellow-soft: #fff8dc;

  --ai-blue: #8ebbd4;
  --ai-blue-soft: #edf7fb;

  --ai-white: #ffffff;
  --ai-cream: #faf9f3;

  --ai-text: #183226;
  --ai-text-soft: #63746a;

  --ai-border: rgba(47, 125, 74, 0.14);

  --ai-panel: rgba(255, 255, 255, 0.95);
  --ai-panel-solid: #ffffff;

  --ai-user-bubble: #edf7ef;
  --ai-assistant-bubble: #f8faf8;

  --ai-shadow:
    0 24px 70px rgba(27, 66, 42, 0.17),
    0 8px 30px rgba(27, 66, 42, 0.09);

  --ai-overlay: rgba(17, 34, 23, 0.12);
}


/* =========================================================
   DARK
========================================================= */

body.dark,
html.dark,
[data-theme="dark"],
body[data-theme="dark"] {
  --ai-green: #71b989;
  --ai-green-dark: #4f9468;
  --ai-green-soft: rgba(113, 185, 137, 0.12);

  --ai-yellow: #dfcf82;
  --ai-yellow-soft: rgba(223, 207, 130, 0.10);

  --ai-blue: #85b6d0;
  --ai-blue-soft: rgba(133, 182, 208, 0.10);

  --ai-white: #f5f8f5;
  --ai-cream: #101713;

  --ai-text: #eef5ef;
  --ai-text-soft: #a5b4aa;

  --ai-border: rgba(133, 185, 148, 0.16);

  --ai-panel: rgba(19, 27, 22, 0.94);
  --ai-panel-solid: #141d17;

  --ai-user-bubble: rgba(72, 132, 90, 0.22);
  --ai-assistant-bubble: rgba(255, 255, 255, 0.045);

  --ai-shadow:
    0 30px 90px rgba(0, 0, 0, 0.46),
    0 8px 30px rgba(0, 0, 0, 0.28);

  --ai-overlay: rgba(0, 0, 0, 0.28);
}


/* =========================================================
   FOREST
========================================================= */

body.forest,
html.forest,
[data-theme="forest"],
body[data-theme="forest"] {
  --ai-green: #78a96b;
  --ai-green-dark: #547d4c;
  --ai-green-soft: rgba(120, 169, 107, 0.13);

  --ai-yellow: #e7d58a;
  --ai-yellow-soft: rgba(231, 213, 138, 0.12);

  --ai-blue: #89b9b2;
  --ai-blue-soft: rgba(137, 185, 178, 0.11);

  --ai-white: #f4f7ef;
  --ai-cream: #172018;

  --ai-text: #edf4e9;
  --ai-text-soft: #aebca8;

  --ai-border: rgba(130, 169, 112, 0.17);

  --ai-panel: rgba(25, 39, 27, 0.95);
  --ai-panel-solid: #19271c;

  --ai-user-bubble: rgba(101, 145, 85, 0.23);
  --ai-assistant-bubble: rgba(255, 255, 255, 0.045);

  --ai-shadow:
    0 30px 90px rgba(4, 18, 7, 0.48),
    0 10px 35px rgba(4, 18, 7, 0.28);

  --ai-overlay: rgba(4, 18, 7, 0.30);
}


/* =========================================================
   MIDNIGHT
========================================================= */

body.midnight,
html.midnight,
[data-theme="midnight"],
body[data-theme="midnight"] {
  --ai-green: #72b58d;
  --ai-green-dark: #4f9270;
  --ai-green-soft: rgba(114, 181, 141, 0.11);

  --ai-yellow: #dfcf86;
  --ai-yellow-soft: rgba(223, 207, 134, 0.09);

  --ai-blue: #81b8db;
  --ai-blue-soft: rgba(129, 184, 219, 0.10);

  --ai-white: #f2f6fa;
  --ai-cream: #0c121a;

  --ai-text: #eaf0f6;
  --ai-text-soft: #99a8b6;

  --ai-border: rgba(129, 184, 219, 0.14);

  --ai-panel: rgba(13, 20, 29, 0.95);
  --ai-panel-solid: #101822;

  --ai-user-bubble: rgba(79, 125, 165, 0.22);
  --ai-assistant-bubble: rgba(255, 255, 255, 0.045);

  --ai-shadow:
    0 30px 90px rgba(0, 0, 0, 0.56),
    0 10px 35px rgba(0, 0, 0, 0.32);

  --ai-overlay: rgba(0, 0, 0, 0.34);
}


/* =========================================================
   FLOATING BUTTON
========================================================= */

.voice-assistant-floating {
  position: fixed;

  right: 26px;
  bottom: 26px;

  width: 58px;
  height: 58px;

  border: 1px solid var(--ai-border);
  border-radius: 50%;

  display: flex;
  align-items: center;
  justify-content: center;

  cursor: pointer;

  color: var(--ai-white);

  background:
    linear-gradient(
      145deg,
      var(--ai-green),
      var(--ai-green-dark)
    );

  box-shadow:
    0 14px 34px rgba(47, 125, 74, 0.26);

  z-index: 10001;

  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    filter 180ms ease;
}

.voice-assistant-floating:hover {
  transform: translateY(-2px) scale(1.035);

  box-shadow:
    0 18px 40px rgba(47, 125, 74, 0.32);
}

.voice-assistant-floating:active {
  transform: scale(0.96);
}

.voice-assistant-floating.listening {
  animation: aiListeningPulse 1.7s ease-in-out infinite;
}

@keyframes aiListeningPulse {
  0%,
  100% {
    box-shadow:
      0 14px 34px rgba(47, 125, 74, 0.26),
      0 0 0 0 rgba(47, 125, 74, 0.24);
  }

  50% {
    box-shadow:
      0 16px 38px rgba(47, 125, 74, 0.32),
      0 0 0 9px rgba(47, 125, 74, 0.09);
  }
}


/* =========================================================
   PANEL
========================================================= */

.voice-assistant-panel {
  position: fixed;

  right: 26px;
  bottom: 96px;

  width: min(470px, calc(100vw - 32px));
  height: min(720px, calc(100vh - 125px));

  display: flex;
  flex-direction: column;

  overflow: hidden;

  border: 1px solid var(--ai-border);
  border-radius: var(--ai-radius-large);

  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.055),
      rgba(255, 255, 255, 0)
    ),
    var(--ai-panel);

  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);

  box-shadow: var(--ai-shadow);

  color: var(--ai-text);

  z-index: 10000;

  animation:
    aiPanelOpen 220ms cubic-bezier(.2,.75,.25,1) both;
}

@keyframes aiPanelOpen {
  from {
    opacity: 0;
    transform:
      translateY(12px)
      scale(0.975);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}


/* =========================================================
   HEADER
========================================================= */

.voice-assistant-panel-header {
  min-height: 76px;

  padding: 17px 18px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  border-bottom: 1px solid var(--ai-border);

  background:
    linear-gradient(
      90deg,
      var(--ai-green-soft),
      transparent 72%
    );
}

.voice-assistant-heading {
  display: flex;
  align-items: center;

  min-width: 0;
}

.voice-assistant-heading-icon {
  width: 39px;
  height: 39px;

  flex-shrink: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-right: 11px;

  border-radius: 13px;

  color: var(--ai-green-dark);

  background:
    linear-gradient(
      145deg,
      var(--ai-yellow-soft),
      var(--ai-green-soft)
    );
}

.voice-assistant-heading strong {
  display: block;

  color: var(--ai-text);

  font-size: 15px;
  line-height: 1.2;
  font-weight: 700;
}

.voice-assistant-heading span {
  display: block;

  margin-top: 4px;

  color: var(--ai-text-soft);

  font-size: 11.5px;
  line-height: 1.35;
}


/* =========================================================
   HEADER BUTTONS
========================================================= */

.voice-assistant-header-actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

.voice-assistant-reset,
.voice-assistant-close {
  width: 34px;
  height: 34px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid var(--ai-border);
  border-radius: 10px;

  background: transparent;

  color: var(--ai-text-soft);

  cursor: pointer;

  transition:
    background 160ms ease,
    color 160ms ease,
    transform 160ms ease;
}

.voice-assistant-reset:hover,
.voice-assistant-close:hover {
  background: var(--ai-green-soft);
  color: var(--ai-green);

  transform: translateY(-1px);
}


/* =========================================================
   BODY
========================================================= */

.voice-assistant-body {
  flex: 1;

  min-height: 0;

  overflow-y: auto;
  overflow-x: hidden;

  padding: 20px 18px 18px;

  scrollbar-width: thin;
  scrollbar-color:
    var(--ai-green)
    transparent;
}

.voice-assistant-body::-webkit-scrollbar {
  width: 6px;
}

.voice-assistant-body::-webkit-scrollbar-track {
  background: transparent;
}

.voice-assistant-body::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: var(--ai-green);
}


/* =========================================================
   WELCOME
========================================================= */

.voice-assistant-welcome {
  min-height: 360px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  text-align: center;
}

.voice-assistant-orb {
  width: 72px;
  height: 72px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 22px;

  color: var(--ai-green-dark);

  background:
    radial-gradient(
      circle at 35% 30%,
      var(--ai-yellow-soft),
      var(--ai-green-soft)
    );

  box-shadow:
    inset 0 0 0 1px var(--ai-border);
}

.voice-assistant-state {
  margin-top: 13px;

  text-align: center;
}

.voice-assistant-state strong {
  color: var(--ai-text);

  font-size: 13px;
  font-weight: 650;
}


/* =========================================================
   CONVERSATION
========================================================= */

.voice-assistant-conversation {
  display: flex;
  flex-direction: column;

  gap: 18px;

  width: 100%;
}


/* =========================================================
   MESSAGE
========================================================= */

.voice-assistant-message {
  width: 100%;

  display: flex;
  flex-direction: column;

  gap: 6px;
}

.voice-assistant-message.user {
  align-items: flex-end;
}

.voice-assistant-message.assistant {
  align-items: flex-start;
}

.voice-assistant-message-label {
  padding: 0 5px;

  color: var(--ai-text-soft);

  font-size: 10.5px;
  font-weight: 650;

  letter-spacing: 0.02em;
}

.voice-assistant-message-bubble {
  max-width: 86%;

  padding: 12px 14px;

  border: 1px solid var(--ai-border);
  border-radius: 16px;

  color: var(--ai-text);

  font-size: 13.5px;
  line-height: 1.55;

  white-space: pre-wrap;
  overflow-wrap: anywhere;

  box-shadow:
    0 4px 15px rgba(20, 50, 31, 0.035);
}

.voice-assistant-message.user
.voice-assistant-message-bubble {
  border-bottom-right-radius: 5px;

  background:
    linear-gradient(
      145deg,
      var(--ai-user-bubble),
      transparent
    );
}

.voice-assistant-message.assistant
.voice-assistant-message-bubble {
  border-bottom-left-radius: 5px;

  background:
    linear-gradient(
      145deg,
      var(--ai-assistant-bubble),
      transparent
    );
}


/* =========================================================
   LIVE STATE
========================================================= */

.voice-assistant-live-state {
  min-height: 24px;

  display: flex;
  align-items: center;
  justify-content: center;

  gap: 7px;

  margin-top: 4px;
  margin-bottom: 10px;

  color: var(--ai-green);

  font-size: 11.5px;
  font-weight: 650;
}


/* =========================================================
   TRANSCRIPT
========================================================= */

.voice-assistant-transcript {
  margin: 8px 0 12px;

  padding: 11px 13px;

  border-left: 3px solid var(--ai-yellow);

  border-radius: 10px;

  background: var(--ai-yellow-soft);
}

.voice-assistant-transcript span {
  display: block;

  margin-bottom: 4px;

  color: var(--ai-text-soft);

  font-size: 10px;
  font-weight: 700;

  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.voice-assistant-transcript p {
  margin: 0;

  color: var(--ai-text);

  font-size: 12.5px;
  line-height: 1.45;
}


/* =========================================================
   INPUT AREA
========================================================= */

.voice-assistant-text-form {
  display: flex;
  align-items: center;

  gap: 9px;

  margin-top: 13px;

  padding: 7px;

  border: 1px solid var(--ai-border);
  border-radius: 15px;

  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.025),
      transparent
    ),
    var(--ai-panel-solid);
}

.voice-assistant-text-form input {
  flex: 1;

  min-width: 0;

  height: 42px;

  padding: 0 11px;

  border: 0;
  outline: none;

  border-radius: 10px;

  background: transparent;

  color: var(--ai-text);

  font: inherit;
  font-size: 13px;
}

.voice-assistant-text-form input::placeholder {
  color: var(--ai-text-soft);
}

.voice-assistant-text-form button {
  width: 42px;
  height: 42px;

  flex-shrink: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 0;
  border-radius: 11px;

  background: var(--ai-green);

  color: white;

  cursor: pointer;

  transition:
    transform 160ms ease,
    background 160ms ease;
}

.voice-assistant-text-form button:hover:not(:disabled) {
  background: var(--ai-green-dark);

  transform: translateY(-1px);
}

.voice-assistant-text-form button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}


/* =========================================================
   MAIN VOICE BUTTON
========================================================= */

.voice-assistant-main-button {
  width: 100%;
  min-height: 48px;

  margin-top: 11px;

  display: flex;
  align-items: center;
  justify-content: center;

  gap: 8px;

  border: 1px solid var(--ai-border);
  border-radius: 13px;

  background:
    linear-gradient(
      145deg,
      var(--ai-green-soft),
      transparent
    );

  color: var(--ai-green);

  font: inherit;
  font-size: 12.5px;
  font-weight: 700;

  cursor: pointer;

  transition:
    background 160ms ease,
    transform 160ms ease;
}

.voice-assistant-main-button:hover:not(:disabled) {
  transform: translateY(-1px);

  background:
    linear-gradient(
      145deg,
      var(--ai-green-soft),
      var(--ai-blue-soft)
    );
}

.voice-assistant-main-button.stop {
  color: #b26454;

  background:
    rgba(178, 100, 84, 0.08);
}


/* =========================================================
   EXAMPLES
========================================================= */

.voice-assistant-examples {
  margin-top: 18px;
}

.voice-assistant-examples-heading {
  margin-bottom: 9px;

  color: var(--ai-text-soft);

  font-size: 10.5px;
  font-weight: 700;

  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.voice-assistant-example-list {
  display: flex;
  flex-wrap: wrap;

  gap: 7px;
}

.voice-assistant-example-list button {
  padding: 8px 10px;

  border: 1px solid var(--ai-border);
  border-radius: 10px;

  background:
    linear-gradient(
      145deg,
      var(--ai-blue-soft),
      transparent
    );

  color: var(--ai-text);

  font: inherit;
  font-size: 11px;

  cursor: pointer;

  transition:
    border-color 160ms ease,
    background 160ms ease,
    transform 160ms ease;
}

.voice-assistant-example-list button:hover:not(:disabled) {
  border-color: var(--ai-green);

  background: var(--ai-green-soft);

  transform: translateY(-1px);
}


/* =========================================================
   FOOTER
========================================================= */

.voice-assistant-footer {
  min-height: 49px;

  padding: 9px 15px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  border-top: 1px solid var(--ai-border);

  background:
    linear-gradient(
      90deg,
      var(--ai-blue-soft),
      transparent
    );
}

.voice-assistant-footer button {
  display: flex;
  align-items: center;

  gap: 6px;

  padding: 5px 7px;

  border: 0;
  border-radius: 8px;

  background: transparent;

  color: var(--ai-text-soft);

  font: inherit;
  font-size: 10.5px;

  cursor: pointer;
}

.voice-assistant-footer button:hover {
  color: var(--ai-green);
  background: var(--ai-green-soft);
}

.voice-assistant-language {
  color: var(--ai-text-soft);

  font-size: 10px;
  font-weight: 600;

  opacity: 0.8;
}


/* =========================================================
   ERROR
========================================================= */

.voice-assistant-error-card {
  margin-top: 9px;

  padding: 10px 12px;

  border: 1px solid rgba(180, 95, 74, 0.15);
  border-radius: 11px;

  background: rgba(180, 95, 74, 0.07);

  color: #a35e4e;

  font-size: 11.5px;
  line-height: 1.45;
}


/* =========================================================
   LOADING ANIMATION
========================================================= */

.voice-assistant-spin {
  animation: aiSpin 0.8s linear infinite;
}

@keyframes aiSpin {
  to {
    transform: rotate(360deg);
  }
}


/* =========================================================
   SMALL SCREEN
========================================================= */

@media (max-width: 640px) {

  .voice-assistant-floating {
    right: 16px;
    bottom: 16px;

    width: 54px;
    height: 54px;
  }

  .voice-assistant-panel {
    right: 10px;
    bottom: 82px;

    width: calc(100vw - 20px);
    height: min(700px, calc(100vh - 96px));

    border-radius: 21px;
  }

  .voice-assistant-panel-header {
    min-height: 69px;

    padding: 14px;
  }

  .voice-assistant-body {
    padding: 16px 14px 14px;
  }

  .voice-assistant-message-bubble {
    max-width: 91%;
  }

}


/* =========================================================
   REDUCE MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

  .voice-assistant-floating,
  .voice-assistant-panel,
  .voice-assistant-main-button,
  .voice-assistant-example-list button,
  .voice-assistant-text-form button {
    animation: none !important;
    transition: none !important;
  }

}

/* =========================================================
   KRISHISETU AI ASSISTANT
   PREMIUM FARMER-FRIENDLY DESIGN
   Keeps existing panel dimensions
========================================================= */


/* =========================================================
   THEME SYSTEM
========================================================= */

:root {

  --ai-primary: #3f8656;
  --ai-primary-deep: #2d6842;
  --ai-primary-soft: rgba(63, 134, 86, 0.10);

  --ai-leaf: #70a96e;
  --ai-leaf-soft: rgba(112, 169, 110, 0.12);

  --ai-yellow: #e7d58d;
  --ai-yellow-soft: rgba(231, 213, 141, 0.16);

  --ai-blue: #8cb8d0;
  --ai-blue-soft: rgba(140, 184, 208, 0.13);

  --ai-white: #ffffff;
  --ai-surface: rgba(255, 255, 255, 0.84);
  --ai-surface-strong: rgba(255, 255, 255, 0.94);

  --ai-text: #183226;
  --ai-text-secondary: #63776a;
  --ai-text-muted: #829187;

  --ai-border: rgba(47, 99, 64, 0.13);

  --ai-user: rgba(63, 134, 86, 0.095);
  --ai-assistant: rgba(255, 255, 255, 0.48);

  --ai-danger: #b3614f;

  --ai-shadow:
    0 24px 65px rgba(38, 78, 49, 0.16),
    0 8px 24px rgba(38, 78, 49, 0.08);

  --ai-inner-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.60);

  --ai-radius-xl: 24px;
  --ai-radius-lg: 17px;
  --ai-radius-md: 13px;
  --ai-radius-sm: 10px;
}


/* =========================================================
   LIGHT THEME
========================================================= */

html.light,
body.light,
html[data-theme="light"],
body[data-theme="light"],
[data-mode="light"] {

  --ai-primary: #3f8656;
  --ai-primary-deep: #2d6842;

  --ai-leaf: #70a96e;

  --ai-yellow: #e7d58d;
  --ai-yellow-soft: rgba(231, 213, 141, 0.16);

  --ai-blue: #8cb8d0;
  --ai-blue-soft: rgba(140, 184, 208, 0.13);

  --ai-white: #ffffff;

  --ai-surface: rgba(255, 255, 255, 0.84);
  --ai-surface-strong: rgba(255, 255, 255, 0.96);

  --ai-text: #183226;
  --ai-text-secondary: #63776a;
  --ai-text-muted: #829187;

  --ai-border: rgba(47, 99, 64, 0.13);

  --ai-user: rgba(63, 134, 86, 0.09);
  --ai-assistant: rgba(255, 255, 255, 0.50);

  --ai-shadow:
    0 24px 65px rgba(38, 78, 49, 0.16),
    0 8px 24px rgba(38, 78, 49, 0.08);
}


/* =========================================================
   DARK THEME
========================================================= */

html.dark,
body.dark,
html[data-theme="dark"],
body[data-theme="dark"],
[data-mode="dark"] {

