  --ai-text: #edf5e9;
  --ai-text-secondary: #acbca6;
  --ai-text-muted: #80937b;

  --ai-border: rgba(131, 171, 111, 0.16);

  --ai-user: rgba(109, 153, 91, 0.20);
  --ai-assistant: rgba(255, 255, 255, 0.04);

  --ai-shadow:
    0 30px 85px rgba(5, 22, 7, 0.46),
    0 8px 28px rgba(5, 22, 7, 0.25);
}


/* =========================================================
   MIDNIGHT THEME
========================================================= */

html.midnight,
body.midnight,
html[data-theme="midnight"],
body[data-theme="midnight"],
[data-mode="midnight"] {

  --ai-primary: #78b890;
  --ai-primary-deep: #579874;

  --ai-leaf: #70a978;

  --ai-yellow: #dfcf88;
  --ai-yellow-soft: rgba(223, 207, 136, 0.09);

  --ai-blue: #83b6d8;
  --ai-blue-soft: rgba(131, 182, 216, 0.09);

  --ai-white: #edf3f7;

  --ai-surface: rgba(13, 21, 29, 0.84);
  --ai-surface-strong: rgba(15, 24, 33, 0.95);

  --ai-text: #e9f0f5;
  --ai-text-secondary: #a0afbb;
  --ai-text-muted: #738492;

  --ai-border: rgba(127, 180, 214, 0.15);

  --ai-user: rgba(75, 122, 159, 0.20);
  --ai-assistant: rgba(255, 255, 255, 0.045);

  --ai-shadow:
    0 30px 90px rgba(0, 0, 0, 0.53),
    0 10px 32px rgba(0, 0, 0, 0.30);
}


/* =========================================================
   FLOATING ASSISTANT BUTTON
========================================================= */

.voice-assistant-floating {

  position: fixed;

  right: 24px;
  bottom: 24px;

  width: 58px;
  height: 58px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid rgba(255, 255, 255, 0.30);

  border-radius: 50%;

  color: #ffffff;

  cursor: pointer;

  background:
    radial-gradient(
      circle at 35% 25%,
      rgba(255,255,255,0.22),
      transparent 28%
    ),
    linear-gradient(
      145deg,
      var(--ai-primary),
      var(--ai-primary-deep)
    );

  box-shadow:
    0 12px 28px rgba(49, 100, 63, 0.23),
    inset 0 1px 0 rgba(255,255,255,0.22);

  z-index: 10001;

  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    filter 180ms ease;
}

.voice-assistant-floating::after {

  content: "";

  position: absolute;

  inset: 5px;

  border-radius: inherit;

  border: 1px solid rgba(255,255,255,0.12);

  pointer-events: none;
}

.voice-assistant-floating:hover {

  transform: translateY(-2px);

  box-shadow:
    0 17px 34px rgba(49, 100, 63, 0.27),
    inset 0 1px 0 rgba(255,255,255,0.24);
}

.voice-assistant-floating:active {

  transform: scale(0.95);
}


/* =========================================================
   NORMAL / OFF MIC STATE
========================================================= */

.voice-assistant-floating:not(.listening) {

  box-shadow:
    0 12px 28px rgba(49, 100, 63, 0.22),
    inset 0 1px 0 rgba(255,255,255,0.22);
}


/* =========================================================
   LISTENING STATE
========================================================= */

.voice-assistant-floating.listening {

  background:
    radial-gradient(
      circle at 50% 50%,
      rgba(255,255,255,0.20),
      transparent 35%
    ),
    linear-gradient(
      145deg,
      #4d9963,
      #2f7548
    );

  animation:
    ai-listening-breathe 1.6s ease-in-out infinite;
}

.voice-assistant-floating.listening::before {

  content: "";

  position: absolute;

  inset: -8px;

  border-radius: 50%;

  border: 2px solid
    rgba(87, 170, 104, 0.24);

  animation:
    ai-listening-ring 1.6s ease-out infinite;
}

@keyframes ai-listening-breathe {

  0%,
  100% {

    transform: scale(1);

    box-shadow:
      0 12px 28px rgba(49, 100, 63, 0.22),
      0 0 0 0 rgba(70, 155, 91, 0.22);

  }

  50% {

    transform: scale(1.035);

    box-shadow:
      0 16px 34px rgba(49, 100, 63, 0.27),
      0 0 0 8px rgba(70, 155, 91, 0.08);

  }

}

@keyframes ai-listening-ring {

  0% {

    opacity: 0.8;

    transform: scale(0.92);

  }

  100% {

    opacity: 0;

    transform: scale(1.28);

  }

}


/* =========================================================
   ASSISTANT PANEL
   IMPORTANT:
   NO WIDTH / HEIGHT HERE.
   YOUR EXISTING DIMENSIONS ARE PRESERVED.
========================================================= */

.voice-assistant-panel {

  border:
    1px solid var(--ai-border);

  border-radius:
    var(--ai-radius-xl);

  overflow: hidden;

  color:
    var(--ai-text);

  background:
    linear-gradient(
      145deg,
      rgba(255,255,255,0.10),
      rgba(255,255,255,0.025)
    ),
    var(--ai-surface);

  backdrop-filter:
    blur(24px)
    saturate(125%);

  -webkit-backdrop-filter:
    blur(24px)
    saturate(125%);

  box-shadow:
    var(--ai-shadow);

  animation:
    ai-panel-enter
    210ms
    cubic-bezier(.2,.75,.25,1)
    both;
}

@keyframes ai-panel-enter {

  from {

    opacity: 0;

    transform:
      translateY(8px)
      scale(0.985);

  }

  to {

    opacity: 1;

    transform:
      translateY(0)
      scale(1);

  }

}


/* =========================================================
   HEADER
========================================================= */

.voice-assistant-panel-header {

  min-height: 72px;

  padding:
    15px 17px;

  border-bottom:
    1px solid var(--ai-border);

  background:
    linear-gradient(
      105deg,
      var(--ai-green-soft),
      var(--ai-yellow-soft) 55%,
      transparent
    );

  box-shadow:
    var(--ai-inner-shadow);
}

.voice-assistant-heading-icon {

  width: 40px;
  height: 40px;

  border-radius: 13px;

  display: flex;
  align-items: center;
  justify-content: center;

  color:
    var(--ai-primary-deep);

  background:
    linear-gradient(
      145deg,
      var(--ai-yellow-soft),
      var(--ai-green-soft)
    );

  box-shadow:
    inset 0 0 0 1px var(--ai-border);
}


/* =========================================================
   HEADER TEXT
========================================================= */

.voice-assistant-heading strong {

  color:
    var(--ai-text);

  font-size:
    15px;

  line-height:
    1.2;

  font-weight:
    750;

}

.voice-assistant-heading span {

  margin-top:
    4px;

  color:
    var(--ai-text-secondary);

  font-size:
    11px;

  line-height:
    1.35;
}


/* =========================================================
   HEADER CONTROLS
========================================================= */

.voice-assistant-reset,
.voice-assistant-close {

  width: 34px;
  height: 34px;

  display: flex;
  align-items: center;
  justify-content: center;

  border:
    1px solid var(--ai-border);

  border-radius:
    10px;

  color:
    var(--ai-text-secondary);

  background:
    rgba(255,255,255,0.045);

  cursor: pointer;

  transition:
    background 150ms ease,
    color 150ms ease,
    transform 150ms ease;
}

.voice-assistant-reset:hover,
.voice-assistant-close:hover {

  color:
    var(--ai-primary);

  background:
    var(--ai-primary-soft);

  transform:
    translateY(-1px);
}


/* =========================================================
   CHAT BODY
========================================================= */

.voice-assistant-body {

  scrollbar-width:
    thin;

  scrollbar-color:
    var(--ai-primary)
    transparent;
}

.voice-assistant-body::-webkit-scrollbar {

  width: 6px;
}

.voice-assistant-body::-webkit-scrollbar-track {

  background:
    transparent;
}

.voice-assistant-body::-webkit-scrollbar-thumb {

  border-radius:
    999px;

  background:
    var(--ai-primary);
}


/* =========================================================
   WELCOME ORB
========================================================= */

.voice-assistant-orb {

  position: relative;

  width: 72px;
  height: 72px;

  display: flex;
  align-items: center;
  justify-content: center;

  border:
    1px solid var(--ai-border);

  border-radius:
    22px;

  color:
    var(--ai-primary-deep);

  background:
    radial-gradient(
      circle at 30% 25%,
      var(--ai-yellow-soft),
      transparent 38%
    ),
    linear-gradient(
      145deg,
      var(--ai-green-soft),
      var(--ai-blue-soft)
    );

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.26),
    0 10px 25px rgba(54, 102, 66, 0.06);
}


/* =========================================================
   CONVERSATION
========================================================= */

.voice-assistant-conversation {

  display: flex;

  flex-direction: column;

  gap: 20px;
}


/* =========================================================
   MESSAGE CONTAINERS
========================================================= */

.voice-assistant-message {

  display: flex;

  flex-direction: column;

  gap: 6px;
}

.voice-assistant-message.user {

  align-items: flex-end;
}

.voice-assistant-message.assistant {

  align-items: flex-start;
}


/* =========================================================
   MESSAGE LABEL
========================================================= */

.voice-assistant-message-label {

  padding:
    0 5px;

  color:
    var(--ai-text-muted);

  font-size:
    10px;

  font-weight:
    700;

  letter-spacing:
    0.035em;
}


/* =========================================================
   CHAT BUBBLES
========================================================= */

.voice-assistant-message-bubble {

  max-width:
    84%;

  padding:
    12px 14px;

  border:
    1px solid var(--ai-border);

  border-radius:
    var(--ai-radius-lg);

  color:
    var(--ai-text);

  font-size:
    13.2px;

  line-height:
    1.58;

  white-space:
    pre-wrap;

  overflow-wrap:
    anywhere;

  box-shadow:
    0 4px 14px rgba(30, 70, 42, 0.035);

  transition:
    transform 150ms ease;
}

.voice-assistant-message.user
.voice-assistant-message-bubble {

  border-bottom-right-radius:
    5px;

  background:
    linear-gradient(
      145deg,
      var(--ai-user),
      rgba(255,255,255,0.015)
    );
}

.voice-assistant-message.assistant
.voice-assistant-message-bubble {

  border-bottom-left-radius:
    5px;

  background:
    linear-gradient(
      145deg,
      var(--ai-assistant),
      rgba(255,255,255,0.015)
    );
}


/* =========================================================
   LIVE LISTENING / THINKING INDICATOR
========================================================= */

.voice-assistant-live-state {

  min-height:
    25px;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    7px;

  color:
    var(--ai-primary);

  font-size:
    11px;

  font-weight:
    700;
}

.voice-assistant-live-state.listening {

  color:
    var(--ai-primary);

}

.voice-assistant-live-state.processing {

  color:
    var(--ai-blue);
}


/* =========================================================
   TRANSCRIPT
========================================================= */

.voice-assistant-transcript {

  margin-top:
    9px;

  padding:
    10px 12px;

  border-left:
    3px solid var(--ai-yellow);

  border-radius:
    10px;

  background:
    linear-gradient(
      90deg,
      var(--ai-yellow-soft),
      transparent
    );
}

.voice-assistant-transcript span {

  display:
    block;

  margin-bottom:
    4px;

  color:
    var(--ai-text-muted);

  font-size:
    9.5px;

  font-weight:
    750;

  text-transform:
    uppercase;

  letter-spacing:
    0.055em;
}

.voice-assistant-transcript p {

  margin:
    0;

  color:
    var(--ai-text);

  font-size:
    12.5px;

  line-height:
    1.45;
}


/* =========================================================
   TEXT INPUT
========================================================= */

.voice-assistant-text-form {

  display:
    flex;

  align-items:
    center;

  gap:
    8px;

  margin-top:
    13px;

  padding:
    6px;

  border:
    1px solid var(--ai-border);

  border-radius:
    15px;

  background:
    rgba(255,255,255,0.11);

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.14);
}

.voice-assistant-text-form input {

  flex:
    1;

  min-width:
    0;

  height:
    42px;

  padding:
    0 11px;

  border:
    0;

  outline:
    none;

  background:
    transparent;

  color:
    var(--ai-text);

  font:
    inherit;

  font-size:
    13px;
}

.voice-assistant-text-form input::placeholder {

  color:
    var(--ai-text-muted);
}

.voice-assistant-text-form input:focus {

  outline:
    none;
}

.voice-assistant-text-form button {

  width:
    42px;

  height:
    42px;

  flex-shrink:
    0;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  border:
    0;

  border-radius:
    11px;

  color:
    #ffffff;

  background:
    linear-gradient(
      145deg,
      var(--ai-primary),
      var(--ai-primary-deep)
    );

  cursor:
    pointer;

  box-shadow:
    0 5px 12px rgba(48, 109, 67, 0.17);

  transition:
    transform 150ms ease,
    filter 150ms ease;
}

.voice-assistant-text-form button:hover:not(:disabled) {

  transform:
    translateY(-1px);

  filter:
    brightness(1.04);
}

.voice-assistant-text-form button:disabled {

  opacity:
    0.42;

  cursor:
    not-allowed;

  box-shadow:
    none;
}


/* =========================================================
   MICROPHONE BUTTON
========================================================= */

.voice-assistant-main-button {

  min-height:
    47px;

  width:
    100%;

  margin-top:
    10px;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    8px;

  border:
    1px solid var(--ai-border);

  border-radius:
    13px;

  color:
    var(--ai-primary);

  background:
    linear-gradient(
      105deg,
      var(--ai-green-soft),
      var(--ai-blue-soft)
    );

  font:
    inherit;

  font-size:
    12.5px;

  font-weight:
    750;

  cursor:
    pointer;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.13);

  transition:
    transform 150ms ease,
    background 150ms ease,
    box-shadow 150ms ease;
}

.voice-assistant-main-button:hover:not(:disabled) {

  transform:
    translateY(-1px);

  background:
    linear-gradient(
      105deg,
      var(--ai-green-soft),
      var(--ai-yellow-soft)
    );

  box-shadow:
    0 6px 16px rgba(49, 101, 61, 0.06);
}


/* =========================================================
   MIC OFF
========================================================= */

.voice-assistant-main-button:not(.stop) {

  color:
    var(--ai-primary-deep);
}


/* =========================================================
   MIC ON
========================================================= */

.voice-assistant-main-button.stop {

  color:
    var(--ai-primary-deep);

  border-color:
    rgba(76, 150, 91, 0.24);

  background:
    linear-gradient(
      105deg,
      rgba(79, 159, 97, 0.16),
      var(--ai-blue-soft)
    );

  box-shadow:
    0 0 0 3px rgba(72, 147, 89, 0.055);
}

.voice-assistant-main-button.stop svg {

  animation:
    ai-mic-pulse 1.25s ease-in-out infinite;
}

@keyframes ai-mic-pulse {

  0%,
  100% {

    transform:
      scale(1);

  }

  50% {

    transform:
      scale(1.10);

  }

}


/* =========================================================
   EXAMPLES
========================================================= */

.voice-assistant-examples {

  margin-top:
    17px;
}

.voice-assistant-examples-heading {

  margin-bottom:
    9px;

  color:
    var(--ai-text-muted);

  font-size:
    10px;

  font-weight:
    750;

  text-transform:
    uppercase;

  letter-spacing:
    0.055em;
}

.voice-assistant-example-list {

  display:
    flex;

  flex-wrap:
    wrap;

  gap:
    7px;
}

.voice-assistant-example-list button {

  padding:
    8px 10px;

  border:
    1px solid var(--ai-border);

  border-radius:
    10px;

  color:
    var(--ai-text);

  background:
    linear-gradient(
      145deg,
      var(--ai-blue-soft),
      rgba(255,255,255,0.02)
    );

  font:
    inherit;

  font-size:
    10.8px;

  cursor:
    pointer;

  transition:
    transform 150ms ease,
    border-color 150ms ease,
    background 150ms ease;
}

.voice-assistant-example-list button:hover:not(:disabled) {

  transform:
    translateY(-1px);

  border-color:
    rgba(63, 134, 86, 0.25);

  background:
    linear-gradient(
      145deg,
      var(--ai-green-soft),
      var(--ai-yellow-soft)
    );
}


/* =========================================================
   FOOTER
========================================================= */

.voice-assistant-footer {

  min-height:
    48px;

  padding:
    8px 14px;

  border-top:
    1px solid var(--ai-border);

  background:
    linear-gradient(
      90deg,
      var(--ai-blue-soft),
      transparent 75%
    );
}

.voice-assistant-footer button {

  display:
    flex;

  align-items:
    center;

  gap:
    6px;

  padding:
    5px 7px;

  border:
    0;

  border-radius:
    8px;

  color:
    var(--ai-text-secondary);

  background:
    transparent;

  font:
    inherit;

  font-size:
    10.5px;

  cursor:
    pointer;

  transition:
    background 150ms ease,
    color 150ms ease;
}

.voice-assistant-footer button:hover {

  color:
    var(--ai-primary);

  background:
    var(--ai-primary-soft);
}


/* =========================================================
   ERROR
========================================================= */

.voice-assistant-error-card {

  margin-top:
    9px;

  padding:
    10px 12px;

  border:
    1px solid rgba(179, 97, 79, 0.16);

  border-radius:
    11px;

  color:
    var(--ai-danger);

  background:
    rgba(179, 97, 79, 0.065);

  font-size:
    11.5px;

  line-height:
    1.45;
}


/* =========================================================
   LOADING
========================================================= */

.voice-assistant-spin {

  animation:
    ai-spin
    0.8s
    linear
    infinite;
}

@keyframes ai-spin {

  to {

    transform:
      rotate(360deg);

  }

}


/* =========================================================
   REDUCE MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

  .voice-assistant-floating,
  .voice-assistant-floating.listening,
  .voice-assistant-floating.listening::before,
  .voice-assistant-main-button.stop svg,
  .voice-assistant-panel,
  .voice-assistant-text-form button,
  .voice-assistant-example-list button {

    animation:
      none !important;

    transition:
      none !important;
  }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 640px) {

  .voice-assistant-floating {

    right:
      16px;

    bottom:
      16px;

    width:
      54px;

    height:
      54px;
  }

}

.voice-assistant-panel {
  width: 430px;
  max-width: calc(100vw - 32px);
}

.voice-assistant-panel-header {

  min-height: 72px;

  padding: 15px 17px;

  border-bottom:
    1px solid var(--ai-border);

  background:
    linear-gradient(
      120deg,
      var(--ai-primary-soft),
      var(--ai-yellow-soft) 55%,
      var(--ai-blue-soft)
    );

  box-shadow:
    var(--ai-inner-shadow);
}


.voice-assistant-heading-icon {

  width: 40px;
  height: 40px;

  border-radius: 13px;

  display: flex;
  align-items: center;
  justify-content: center;

  color:
    var(--ai-primary-deep);

  background:
    linear-gradient(
      145deg,
      var(--ai-yellow),
      var(--ai-leaf)
    );

  box-shadow:
    0 5px 14px rgba(63, 134, 86, 0.12),
    inset 0 1px 0 rgba(255,255,255,0.35);
}


.voice-assistant-heading strong {

  color:
    var(--ai-primary-deep);

  font-size:
    15px;

  line-height:
    1.2;

  font-weight:
    800;
}


.voice-assistant-heading span {

  margin-top:
    4px;

  color:
    var(--ai-text-secondary);

  font-size:
    11px;

  line-height:
    1.4;
}

.voice-assistant-floating:hover {

  transform:
    translateY(-2px);

  filter:
    none;

  background:
    linear-gradient(
      145deg,
      var(--ai-primary),
      var(--ai-primary-deep)
    );

  box-shadow:
    0 16px 32px rgba(49, 100, 63, 0.24),
    inset 0 1px 0 rgba(255,255,255,0.18);
}


.voice-assistant-reset:hover,
.voice-assistant-close:hover {

  color:
    var(--ai-primary);

  background:
    var(--ai-primary-soft);

  border-color:
    rgba(63, 134, 86, 0.22);

  transform:
    none;
}


.voice-assistant-example-list button:hover:not(:disabled) {

  transform:
    translateY(-1px);

  color:
    var(--ai-primary-deep);

  border-color:
    rgba(63, 134, 86, 0.24);

  background:
    var(--ai-primary-soft);

  box-shadow:
    none;
}


.voice-assistant-main-button:hover:not(:disabled) {

  transform:
    translateY(-1px);

  color:
    var(--ai-primary-deep);

  border-color:
    rgba(63, 134, 86, 0.22);

  background:
    var(--ai-primary-soft);

  box-shadow:
    none;
}


.voice-assistant-text-form button:hover:not(:disabled) {

  transform:
    translateY(-1px);

  filter:
    none;

  background:
    linear-gradient(
      145deg,
      var(--ai-primary),
      var(--ai-primary-deep)
    );

  box-shadow:
    0 5px 13px rgba(48, 109, 67, 0.16);
}


.voice-assistant-footer button:hover {

  color:
    var(--ai-primary);

  background:
    var(--ai-primary-soft);
}

.voice-assistant-message.user
.voice-assistant-message-bubble {

  border:
    1px solid rgba(63, 134, 86, 0.15);

  border-bottom-right-radius:
    5px;

  color:
    var(--ai-text);

  background:
    linear-gradient(
      145deg,
      rgba(63, 134, 86, 0.13),
      rgba(112, 169, 110, 0.06)
    );

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.08);
}


.voice-assistant-message.assistant
.voice-assistant-message-bubble {

  border:
    1px solid rgba(140, 184, 208, 0.13);

  border-bottom-left-radius:
    5px;

  color:
    var(--ai-text);

  background:
    linear-gradient(
      145deg,
      rgba(140, 184, 208, 0.10),
      rgba(255,255,255,0.025)
    );

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.06);
}


.voice-assistant-message.user
.voice-assistant-message-label {

  color:
    var(--ai-primary);
}


.voice-assistant-message.assistant
.voice-assistant-message-label {

  color:
    var(--ai-blue);
}

.voice-assistant-live-state.listening {

  color:
    var(--ai-primary);

  text-shadow:
    0 0 12px rgba(63, 134, 86, 0.16);
}


.voice-assistant-live-state.processing {

  color:
    var(--ai-blue);

  text-shadow:
    0 0 12px rgba(140, 184, 208, 0.14);
}

.voice-assistant-text-form {

  background:
    linear-gradient(
      145deg,
      rgba(255,255,255,0.065),
      var(--ai-primary-soft)
    );

  border:
    1px solid var(--ai-border);

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.08);
}


.voice-assistant-text-form:focus-within {

  border-color:
    rgba(63, 134, 86, 0.30);

  box-shadow:
    0 0 0 3px rgba(63, 134, 86, 0.055),
    inset 0 1px 0 rgba(255,255,255,0.08);
}

.voice-assistant-panel::before {

  content: "";

  position: absolute;

  top: 0;
  left: 12%;
  right: 12%;

  height: 1px;

  background:
    linear-gradient(
      90deg,
      transparent,
      var(--ai-yellow),
      var(--ai-primary),
      var(--ai-blue),
      transparent
    );

  opacity: 0.65;

  pointer-events: none;
}

.voice-assistant-welcome .voice-assistant-orb {

  color:
    var(--ai-primary-deep);

  background:
    radial-gradient(
      circle at 30% 20%,
      rgba(231,213,141,0.28),
      transparent 35%
    ),
    linear-gradient(
      145deg,
      var(--ai-primary-soft),
