.voice-assistant-welcome::before {

  content: "";

  position: absolute;

  width:
    calc(
      180px +
      (var(--voice-intensity, 0) * 180px)
    );

  height:
    calc(
      180px +
      (var(--voice-intensity, 0) * 180px)
    );

  left: 50%;
  top: 50%;

  transform:
    translate(-50%, -50%);

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(79,143,88,0.24),
      rgba(225,210,139,0.13) 42%,
      rgba(140,188,208,0.06) 64%,
      transparent 72%
    );

  opacity:
    calc(
      0.45 +
      (var(--voice-intensity, 0) * 0.55)
    );

  filter:
    blur(
      calc(
        16px -
        (var(--voice-intensity, 0) * 7px)
      )
    );

  transition:
    width 80ms linear,
    height 80ms linear,
    opacity 80ms linear;

  pointer-events:
    none;
}


.voice-assistant-welcome::after {

  content: "";

  position: absolute;

  inset: 12%;

  border-radius: 30px;

  background:
    radial-gradient(
      circle at 50% 50%,
      rgba(255,255,255,0.20),
      transparent 60%
    );

  opacity:
    calc(
      0.15 +
      (var(--voice-intensity, 0) * 0.35)
    );

  pointer-events:
    none;
}


