   ========================================================= */

@keyframes voice-assistant-panel-in {

  from {

    opacity:
      0;

    transform:
      translateY(18px)
      scale(0.97);

  }

  to {

    opacity:
      1;

    transform:
      translateY(0)
      scale(1);

  }

}


