  from {

    opacity:
      0;

  }

  to {

    opacity:
      1;

  }

}


@keyframes voice-assistant-message-in {

  from {

    opacity:
      0;

    transform:
      translateY(7px);

  }

  to {

    opacity:
      1;

    transform:
      translateY(0);

  }

}


