  0%,
  100% {

    box-shadow:
      0 16px 32px
        rgba(47, 101, 66, 0.14),

      0 0 0 0
        rgba(69, 149, 91, 0.24);

  }

  50% {

    box-shadow:
      0 18px 38px
        rgba(47, 101, 66, 0.18),

      0 0 0 10px
        rgba(69, 149, 91, 0.06);

  }

}


@keyframes assistant-thinking-dot {

  0%,
  60%,
  100% {

    opacity:
      0.30;

    transform:
      translateY(0);

  }

  30% {

    opacity:
      1;

    transform:
      translateY(-3px);

  }

}


@keyframes voice-assistant-live-dot {

  0%,
  100% {

    transform:
      scale(0.82);

    opacity:
      0.65;

  }

  50% {

    transform:
      scale(1.18);

    opacity:
