/* =========================================================
   ANIMATIONS
   ========================================================= */

.voice-assistant-spin {

  animation:
    ai-spin
    0.85s
    linear
    infinite;

}


@keyframes ai-spin {

  to {

    transform:
      rotate(360deg);

  }

}


@keyframes ai-panel-in {

  from {

    opacity:
      0;

    transform:
      translateY(16px)
      scale(0.975);

  }

  to {

    opacity:
      1;

    transform:
      translateY(0)
      scale(1);

  }

}


@keyframes ai-backdrop-in {

  from {

    opacity:
      0;

  }

  to {

    opacity:
      1;

  }

}


@keyframes ai-message-in {

  from {

    opacity:
      0;

    transform:
      translateY(6px);

  }

  to {

    opacity:
      1;

    transform:
      translateY(0);

  }

}


@keyframes ai-listening-breathe {

  0%,
  100% {

    box-shadow:
      0 18px 35px
        rgba(47,102,65,0.13),

      0 0 0 0
        rgba(69,149,91,0.24);

  }

  50% {

    box-shadow:
      0 20px 38px
        rgba(47,102,65,0.18),

      0 0 0 10px
        rgba(69,149,91,0.06);

  }

}


@keyframes ai-live-dot {

  0%,
  100% {

    transform:
      scale(0.82);

    opacity:
      0.65;

  }

  50% {

    transform:
      scale(1.18);

    opacity:
      1;

  }

}


@keyframes ai-button-pulse {

  0% {

    box-shadow:
      0 0 0 0
      rgba(255,225,139,0.40);

  }

  70% {

    box-shadow:
      0 0 0 8px
      rgba(255,225,139,0);

  }

  100% {

    box-shadow:
      0 0 0 0
      rgba(255,225,139,0);

  }

}


@keyframes ai-thinking-dot {

  0%,
  60%,
  100% {

    opacity:
      0.25;

    transform:
      translateY(0);

  }

  30% {

    opacity:
      1;

    transform:
      translateY(-3px);

  }

}


