/* =========================================================
   KRISHISETU AI — SCROLL FIX
========================================================= */

.voice-assistant-backdrop {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100dvh;
  overflow: hidden;
  overscroll-behavior: none;
  touch-action: none;
  box-sizing: border-box;
}

.voice-assistant-panel {
  min-height: 0;
  max-height: calc(100dvh - 20px);

  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;

  overflow: hidden;
}

.voice-assistant-body-shell {
  position: relative;

  min-height: 0;
  height: 100%;

  overflow: hidden;
  isolation: isolate;
}

.voice-assistant-body {
  position: absolute;
  inset: 0;

  width: 100%;
  height: 100%;

  min-height: 0;
  min-width: 0;

  overflow-y: auto;
  overflow-x: hidden;

  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;

  touch-action: pan-y;

  scrollbar-gutter: stable;
}

.voice-assistant-body::-webkit-scrollbar {
  width: 7px;
}

.voice-assistant-body::-webkit-scrollbar-track {
  background: transparent;
}

.voice-assistant-body::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(74, 112, 78, 0.30);
}

.voice-assistant-body::-webkit-scrollbar-thumb:hover {
  background: rgba(74, 112, 78, 0.50);
}

.voice-assistant-conversation {
  display: flex;
  flex-direction: column;

  gap: 18px;

  min-width: 0;

  padding:
    20px
    18px
    30px;

  box-sizing: border-box;
}

.voice-assistant-message {
  flex: 0 0 auto;
  min-width: 0;
  max-width: 88%;
}

.voice-assistant-message.user {
  align-self: flex-end;
}

.voice-assistant-message.assistant {
  align-self: flex-start;
}

.voice-assistant-scroll-bottom {
  position: absolute;

  right: 18px;
  bottom: 18px;

  z-index: 30;

  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid rgba(72, 110, 76, 0.30);
  border-radius: 50%;

  color: white;

  background:
    linear-gradient(
      145deg,
      #477b50,
      #6b9b6f
    );

  box-shadow:
    0 10px 28px rgba(41, 78, 47, 0.24),
