/* =========================================================
   PHASE 1 — FARMER BOOK EDIT MODE
   Scoped additions only. Existing rules are untouched.
========================================================= */

.farmer-book-page > .booking-error.prominent {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 12px 16px;
  border: 1px solid #dbe8df;
  border-radius: 12px;
  background: #f7fbf8;
  color: #496456;
  box-sizing: border-box;
}

.farmer-book-page > .booking-error.prominent .loading-spin {
  flex: 0 0 auto;
}

.farmer-book-page .booking-confirmed-card h2 {
  max-width: 620px;
}

/* =========================================================
   PHASE 1 — FARMER TOKEN ACTIONS
   Scoped additions only. Existing rules are untouched.
========================================================= */

.farmer-token-page > .booking-error.prominent {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 12px 16px;
  border: 1px solid #dbe8df;
  border-radius: 12px;
  background: #f7fbf8;
  box-sizing: border-box;
}

/* Cancel confirmation modal introduced in Phase 1. */
.farmer-token-page [aria-labelledby="cancel-booking-title"] {
  box-sizing: border-box;
}

.farmer-token-page [aria-labelledby="cancel-booking-title"] textarea {
  display: block;
  min-height: 92px;
  line-height: 1.5;
  color: #30493d;
  background: #fcfefd;
  outline: none;
  transition: border-color .18s ease, box-shadow .18s ease;
}

.farmer-token-page [aria-labelledby="cancel-booking-title"] textarea:focus {
  border-color: #93b9a0 !important;
  box-shadow: 0 0 0 3px rgba(72, 125, 88, .10);
}

.farmer-token-page [aria-labelledby="cancel-booking-title"] .token-inline-action {
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid #d6e2da;
  border-radius: 10px;
  background: #ffffff;
  color: #3f5b4d;
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: transform .16s ease, box-shadow .16s ease, border-color .16s ease, background .16s ease;
}

.farmer-token-page [aria-labelledby="cancel-booking-title"] .token-inline-action:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 7px 18px rgba(31, 58, 42, .08);
  border-color: #b9cec0;
  background: #fbfdfb;
}

.farmer-token-page [aria-labelledby="cancel-booking-title"] .token-inline-action:disabled {
  opacity: .58;
  cursor: not-allowed;
}

@media (max-width: 560px) {
  .farmer-token-page [aria-labelledby="cancel-booking-title"] {
    padding: 20px !important;
    border-radius: 16px !important;
  }

  .farmer-token-page [aria-labelledby="cancel-booking-title"] .token-inline-action {
    width: 100%;
  }
}



/* =========================================================
   LANDING — TRANSPORTER PORTAL + EXPERIENCE REFINEMENT
   Additive overrides for the expanded three-portal journey.
========================================================= */

.landing-header-actions {
  gap: 8px;
}

.landing-nav-farmer,
.landing-nav-admin {
  min-height: 40px;
  padding: 0 15px;
  border-radius: 10px;
  white-space: nowrap;
}

.landing-nav-transporter {
  color: #8c4f24 !important;
  border: 1px solid #efd4bd !important;
  background: #fff7ef !important;
  box-shadow: inset 0 0 0 1px rgba(181, 101, 45, 0.04);
}

.landing-nav-transporter:hover {
  color: #75401d !important;
  border-color: #dfb694 !important;
  background: #ffefe3 !important;
}


/* Hero: make the new logistics capability visible without crowding the hero. */
.landing-hero-transport-note {
  width: min(610px, 100%);
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 20px;
  padding: 12px 14px;
  border: 1px solid #eadfd2;
  border-radius: 15px;
  background: rgba(255, 251, 246, 0.84);
  box-shadow: 0 10px 30px rgba(67, 52, 38, 0.06);
  backdrop-filter: blur(8px);
}

.landing-hero-transport-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 11px;
  color: #9b5729;
  background: #f8e8d9;
}

.landing-hero-transport-note strong {
  display: block;
  margin-bottom: 2px;
  color: #3b4e57;
  font-size: 12px;
  font-weight: 900;
}

.landing-hero-transport-note span {
  display: block;
  color: #718087;
  font-size: 11px;
  line-height: 1.5;
}


/* Portals: three equal lanes instead of a two-column layout. */
.landing-portals-section {
  background:
    radial-gradient(circle at 0% 0%, rgba(33, 139, 82, 0.08), transparent 25%),
    radial-gradient(circle at 100% 35%, rgba(181, 101, 45, 0.06), transparent 28%),
    #fffdf9;
}

.landing-portals-intro {
  max-width: 900px;
}

.landing-portals-intro h2 {
  max-width: 760px;
}

.landing-portals-intro p {
  max-width: 760px;
}


/* Simple role guide keeps users oriented before the larger cards. */
.landing-portal-guide {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  max-width: 1180px;
  margin-top: 28px;
}

.landing-portal-guide > div {
  position: relative;
  display: grid;
  grid-template-columns: 34px 1fr;
  column-gap: 10px;
  padding: 13px 14px;
  border: 1px solid #e6e9e4;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.72);
}

.landing-portal-guide > div > span {
  grid-row: 1 / span 2;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  color: #708078;
  background: #f1f3ef;
  font-size: 10px;
  font-weight: 900;
}

.landing-portal-guide strong {
  color: #2f4752;
  font-size: 12px;
  font-weight: 900;
}

.landing-portal-guide p {
  margin: 3px 0 0;
  color: #7a878b;
  font-size: 11px;
  line-height: 1.45;
}


/* Three cards, clearer hierarchy and less visual heaviness. */
.landing-portal-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
  max-width: 1420px;
  margin-top: 28px;
}

.landing-portal-card {
  min-height: 555px;
  padding: 27px;
  border: 1px solid rgba(63, 87, 76, 0.08);
  box-shadow: 0 12px 34px rgba(47, 68, 59, 0.05);
}

.landing-portal-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 22px 48px rgba(47, 68, 59, 0.11);
}

.landing-portal-card.farmer {
  background:
    radial-gradient(circle at 90% 7%, rgba(255, 211, 97, 0.26), transparent 26%),
    linear-gradient(150deg, #f2faef 0%, #e1f2e2 100%);
  border-color: #d8eadb;
}

.landing-portal-card.transporter {
  background:
    radial-gradient(circle at 88% 8%, rgba(228, 156, 99, 0.24), transparent 27%),
    radial-gradient(circle at 10% 92%, rgba(181, 101, 45, 0.08), transparent 30%),
    linear-gradient(150deg, #fff7ef 0%, #f8eadc 100%);
  border-color: #ecd5bf;
}

.landing-portal-card.operations {
  background:
    radial-gradient(circle at 86% 8%, rgba(74, 164, 206, 0.18), transparent 27%),
    linear-gradient(150deg, #f1f8fc 0%, #e0edf5 100%);
  border-color: #d8e7ef;
}

.landing-portal-card.farmer .portal-card-icon {
  background: #166534;
}

.landing-portal-card.transporter .portal-card-icon {
  background: #b5652d;
  box-shadow: 0 8px 20px rgba(181, 101, 45, 0.18);
}

.landing-portal-card.operations .portal-card-icon {
  background: #277bae;
}

.landing-portal-card.farmer .portal-card-content > span {
  color: #166534;
}

.landing-portal-card.transporter .portal-card-content > span {
  color: #a35725;
}

.landing-portal-card.operations .portal-card-content > span {
  color: #277bae;
}

.landing-portal-card.farmer .portal-card-features svg {
  color: #166534;
}

.landing-portal-card.transporter .portal-card-features svg {
  color: #b5652d;
}

.landing-portal-card.operations .portal-card-features svg {
  color: #277bae;
}

.landing-portal-card.transporter .portal-card-action {
  color: #74431f;
}

.landing-portal-card.transporter .portal-card-action > div {
  background: #b5652d;
  box-shadow: 0 8px 20px rgba(181, 101, 45, 0.17);
}

.landing-portal-card.transporter .portal-number {
  color: rgba(127, 72, 35, 0.38);
}

.landing-portal-card.farmer .portal-number {
  color: rgba(27, 65, 79, 0.32);
}

.landing-portal-card.operations .portal-number {
  color: rgba(27, 65, 79, 0.32);
}

.portal-card-content p {
  max-width: 480px;
}

.portal-card-features {
  gap: 11px;
  margin-top: 25px;
}

.portal-card-action {
  padding-top: 26px;
}


/* A focused explanation of the transport bridge, separated from the cards. */
.landing-transport-bridge {
  max-width: 1420px;
  margin-top: 28px;
  padding: 24px;
  border: 1px solid #eadfce;
  border-radius: 22px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.94), rgba(255, 248, 239, 0.94));
  box-shadow: 0 16px 38px rgba(69, 57, 43, 0.06);
}

.landing-transport-bridge-heading span {
  display: inline-block;
  color: #a35c29;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.15em;
}

.landing-transport-bridge-heading h3 {
  margin: 7px 0 5px;
  color: #304953;
  font-family: var(--font-heading);
  font-size: clamp(24px, 2.5vw, 34px);
  line-height: 1.08;
}

.landing-transport-bridge-heading p {
  max-width: 850px;
  margin: 0;
  color: #728087;
  font-size: 12px;
  line-height: 1.6;
}

.landing-transport-bridge-flow {
  display: grid;
  grid-template-columns: 1fr auto 1fr auto 1fr auto 1fr;
  align-items: center;
  gap: 9px;
  margin-top: 19px;
}

.landing-transport-bridge-flow > div {
  min-width: 0;
  display: grid;
  grid-template-columns: 25px 25px 1fr;
  column-gap: 7px;
  align-items: center;
  padding: 12px 13px;
  border: 1px solid #ece2d5;
  border-radius: 14px;
  background: #fffdf9;
}

.landing-transport-bridge-flow > div > span {
  grid-row: 1 / span 2;
  color: #a46a3e;
  font-size: 9px;
  font-weight: 900;
}

.landing-transport-bridge-flow > div > svg {
  grid-row: 1 / span 2;
  color: #b5652d;
}

.landing-transport-bridge-flow strong {
  color: #344f58;
  font-size: 12px;
  font-weight: 900;
}

.landing-transport-bridge-flow small {
  color: #829096;
  font-size: 10px;
  line-height: 1.35;
}

.landing-transport-bridge-flow .bridge-arrow {
  color: #bd9b7e;
  flex: 0 0 auto;
}


/* Final CTA: transport gets its own warm accent rather than inheriting admin blue. */
.landing-final-transporter-button {
  color: #7c451f !important;
  border-color: #ddb995 !important;
  background: rgba(255, 246, 236, 0.88) !important;
}

.landing-final-transporter-button:hover {
  background: #ffecdc !important;
  border-color: #ca9a70 !important;
}


/* Footer now gives transporters a dedicated discovery path. */
.landing-footer-column strong {
  display: block;
}


/* Header becomes calmer on narrower desktop screens. */
@media (max-width: 1180px) {
  .landing-header-actions {
    gap: 6px;
  }

  .landing-nav-farmer,
  .landing-nav-admin {
    padding: 0 12px;
    font-size: 11px;
  }

  .landing-portal-grid {
    grid-template-columns: 1fr;
    max-width: 780px;
  }

  .landing-portal-card {
    min-height: 500px;
  }
}

@media (max-width: 860px) {
  .landing-portal-guide {
    grid-template-columns: 1fr;
    max-width: 780px;
  }

  .landing-transport-bridge-flow {
    grid-template-columns: 1fr;
  }

  .landing-transport-bridge-flow .bridge-arrow {
    display: none;
  }
}

@media (max-width: 700px) {
  .landing-header-actions {
    display: none;
  }

  .landing-hero-transport-note {
    align-items: flex-start;
    margin-top: 16px;
  }

  .landing-portal-grid {
    margin-top: 20px;
  }

  .landing-portal-card {
    min-height: 0;
    padding: 22px;
    border-radius: 22px;
  }

  .landing-portal-card .portal-card-content {
    margin-top: 32px;
  }

  .landing-portal-card .portal-card-content h3 {
    font-size: 30px;
  }

  .landing-transport-bridge {
    padding: 18px;
    border-radius: 18px;
  }

  .landing-final-cta-actions {
    align-items: stretch;
  }

  .landing-final-farmer-button,
  .landing-final-admin-button {
    width: 100%;
  }
}

@media (max-width: 520px) {
  .landing-portal-guide > div {
    padding: 12px;
  }

  .landing-transport-bridge-heading h3 {
    font-size: 25px;
  }

  .landing-transport-bridge-flow > div {
    grid-template-columns: 22px 25px 1fr;
  }
}



