========================================================= */

/* ---- Portal section: restore a normal single-column flow ---- */
.landing-portals-section {
  display: block !important;
  width: 100% !important;
  max-width: none !important;
  padding: clamp(88px, 9vw, 128px) clamp(24px, 7vw, 110px) !important;
  box-sizing: border-box !important;
}

.landing-portals-intro {
  width: min(820px, 100%) !important;
  max-width: 820px !important;
  margin: 0 auto !important;
  text-align: center !important;
}

.landing-portals-intro h2 {
  margin-top: 14px !important;
}

.landing-portals-intro p {
  max-width: 680px !important;
  margin: 18px auto 0 !important;
}

/* ---- Three portal guide items ---- */
.landing-portal-guide {
  width: min(1120px, 100%) !important;
  margin: 42px auto 0 !important;
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  gap: 14px !important;
  box-sizing: border-box !important;
}

.landing-portal-guide > div {
  min-width: 0 !important;
  padding: 18px 20px !important;
  border: 1px solid rgba(43, 75, 88, 0.10) !important;
  border-radius: 18px !important;
  background: rgba(255, 255, 255, 0.72) !important;
  box-sizing: border-box !important;
}

/* ---- MAIN PORTAL CARDS: the important fix ---- */
.landing-portal-grid {
  width: min(1280px, 100%) !important;
  max-width: 1280px !important;
  margin: 28px auto 0 !important;
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  gap: 22px !important;
  align-items: stretch !important;
  box-sizing: border-box !important;
}

.landing-portal-card {
  width: 100% !important;
  min-width: 0 !important;
  min-height: 540px !important;
  box-sizing: border-box !important;
  padding: 30px !important;
  border-radius: 28px !important;
  overflow: hidden !important;
}

.landing-portal-card .portal-card-content {
  min-width: 0 !important;
}

.landing-portal-card .portal-card-content h3 {
  max-width: none !important;
  font-size: clamp(28px, 2.45vw, 40px) !important;
  overflow-wrap: normal !important;
  word-break: normal !important;
}

.landing-portal-card .portal-card-content p {
  max-width: none !important;
  font-size: 14px !important;
  line-height: 1.65 !important;
}

.landing-portal-card .portal-card-features {
  width: 100% !important;
}

.landing-portal-card .portal-card-features span {
  min-width: 0 !important;
}

/* ---- Farmer ---- */
.landing-portal-card.farmer {
  background:
    radial-gradient(circle at 88% 8%, rgba(237, 195, 73, 0.20), transparent 28%),
    linear-gradient(145deg, #eef8f0 0%, #dcefe1 100%) !important;
}

.landing-portal-card.farmer .portal-card-icon,
.landing-portal-card.farmer .portal-card-action > div {
  background: #166534 !important;
}

/* ---- Transporter: unique warm terracotta identity ---- */
.landing-portal-card.transporter {
  background:
    radial-gradient(circle at 88% 8%, rgba(235, 145, 72, 0.18), transparent 29%),
    linear-gradient(145deg, #fff4e9 0%, #f8e5d3 100%) !important;
  border-color: rgba(194, 104, 36, 0.18) !important;
}

.landing-portal-card.transporter .portal-card-icon,
.landing-portal-card.transporter .portal-card-action > div {
  background: #c46824 !important;
}

.landing-portal-card.transporter .portal-card-content > span,
.landing-portal-card.transporter .portal-card-action > span,
.landing-portal-card.transporter .portal-card-features svg {
  color: #b55d1f !important;
}

.landing-portal-card.transporter .portal-number {
  color: rgba(181, 93, 31, 0.38) !important;
}

/* ---- Operations ---- */
.landing-portal-card.operations {
  background:
    radial-gradient(circle at 88% 8%, rgba(71, 154, 204, 0.16), transparent 29%),
    linear-gradient(145deg, #eef7fc 0%, #dcecf6 100%) !important;
}

.landing-portal-card.operations .portal-card-icon,
.landing-portal-card.operations .portal-card-action > div {
  background: #277bae !important;
}

/* ---- Give the portal block breathing room before the transport explanation ---- */
.landing-transport-bridge {
  width: min(1280px, 100%) !important;
  max-width: 1280px !important;
  margin: 44px auto 0 !important;
  box-sizing: border-box !important;
}

.landing-transport-bridge-heading {
  max-width: 820px !important;
}

.landing-transport-bridge-flow {
  width: 100% !important;
  display: grid !important;
  grid-template-columns: 1fr auto 1fr auto 1fr auto 1fr !important;
  align-items: stretch !important;
  gap: 12px !important;
  box-sizing: border-box !important;
}

.landing-transport-bridge-flow > div {
  min-width: 0 !important;
  box-sizing: border-box !important;
}

/* ---- Prevent global styles from forcing horizontal overflow ---- */
.landing-page,
.landing-page main,
.landing-portals-section,
.landing-portal-grid,
.landing-transport-bridge {
  overflow-x: clip !important;
}

/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1050px) {
  .landing-portal-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }

  .landing-portal-guide {
    grid-template-columns: 1fr !important;
  }

  .landing-transport-bridge-flow {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }

  .landing-transport-bridge-flow .bridge-arrow {
    display: none !important;
  }
}

@media (max-width: 700px) {
  .landing-portals-section {
    padding: 76px 18px 92px !important;
  }

  .landing-portal-grid {
    grid-template-columns: 1fr !important;
    gap: 16px !important;
    margin-top: 22px !important;
  }

  .landing-portal-card {
    min-height: 0 !important;
    padding: 24px !important;
  }

  .landing-portal-card .portal-card-content h3 {
    font-size: 31px !important;
  }

  .landing-portal-guide {
    margin-top: 28px !important;
  }

  .landing-transport-bridge {
    margin-top: 26px !important;
  }

  .landing-transport-bridge-flow {
    grid-template-columns: 1fr !important;
  }
}


/* =========================================================
   KRISHISETU TRANSPORT UI
   One shared stylesheet for:
   1. Transporter Registration
   2. Transporter Login
   3. Farmer Transport Tracking

   Import this same file in all three JSX files:
   import "./TransportPortal_All.css";
   ========================================================= */

:root {
  --ks-green: #177245;
  --ks-green-dark: #0f5a35;
  --ks-green-soft: #edf8f1;
  --ks-green-pale: #f5fbf7;
  --ks-text: #173126;
  --ks-muted: #6b7b73;
  --ks-border: #dfe9e3;
  --ks-card: #ffffff;
  --ks-bg: #f5f8f6;
  --ks-gold: #d99a20;
  --ks-red: #c83d3d;
  --ks-blue: #2878bd;
  --ks-shadow: 0 18px 45px rgba(22, 61, 43, 0.08);
  --ks-radius: 18px;
}

/* =========================================================
   SHARED RESET / PAGE
   ========================================================= */

.transporter-register-page,
.transporter-login-page,
.farmer-transport-tracking-page {
  min-height: 100vh;
  background:
    radial-gradient(circle at top right, rgba(23,114,69,.06), transparent 32%),
    var(--ks-bg);
  color: var(--ks-text);
}

.transporter-register-page *,
.transporter-login-page *,
.farmer-transport-tracking-page * {
  box-sizing: border-box;
}

.transporter-register-page button,
.transporter-login-page button,
.farmer-transport-tracking-page button {
  font: inherit;
}

.transporter-register-page input,
.transporter-register-page select,
.transporter-register-page textarea,
.transporter-login-page input,
.farmer-transport-tracking-page input,
.farmer-transport-tracking-page textarea {
  font: inherit;
}

/* =========================================================
   TRANSPORTER REGISTRATION
   ========================================================= */

.transporter-register-shell {
  width: min(1180px, calc(100% - 32px));
  margin: 0 auto;
  padding: 34px 0 60px;
}

.transporter-register-hero {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 20px;
  align-items: center;
  margin-bottom: 24px;
  padding: 28px;
  border: 1px solid var(--ks-border);
  border-radius: 24px;
  background: linear-gradient(135deg, #ffffff 0%, #f4fbf6 100%);
  box-shadow: var(--ks-shadow);
}

.transporter-register-hero-icon {
  width: 64px;
  height: 64px;
  border-radius: 18px;
  display: grid;
  place-items: center;
  background: var(--ks-green);
  color: #fff;
  box-shadow: 0 10px 24px rgba(23,114,69,.22);
}

.transporter-register-eyebrow {
  display: block;
  margin-bottom: 7px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .13em;
  color: var(--ks-green);
}

.transporter-register-hero h1 {
  margin: 0;
  font-size: clamp(28px, 4vw, 40px);
  line-height: 1.08;
  letter-spacing: -.03em;
}

.transporter-register-hero p {
  margin: 10px 0 0;
  max-width: 690px;
  color: var(--ks-muted);
  line-height: 1.65;
  font-size: 14px;
}

.transporter-register-hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 11px 14px;
  border: 1px solid #cfe7d8;
  border-radius: 999px;
  background: #f5fcf7;
  color: var(--ks-green-dark);
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
}

/* Step indicator */
.transporter-register-steps,
.transporter-register-stepper,
.step-indicator {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  margin: 0 0 20px;
  padding: 10px;
  overflow-x: auto;
}

.transporter-register-step,
.register-step,
.step-item {
  min-width: 130px;
  display: flex;
  align-items: center;
  gap: 9px;
  color: #92a097;
}

.transporter-register-step-number,
.step-number {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid #cedbd3;
  background: #fff;
  font-size: 12px;
  font-weight: 800;
}

.transporter-register-step.active,
.transporter-register-step.current,
.step-item.active,
.step-item.current {
  color: var(--ks-green);
}

.transporter-register-step.active .transporter-register-step-number,
.transporter-register-step.current .transporter-register-step-number,
.step-item.active .step-number,
.step-item.current .step-number {
  border-color: var(--ks-green);
  background: var(--ks-green);
  color: #fff;
  box-shadow: 0 7px 17px rgba(23,114,69,.18);
}

.transporter-register-step-title,
.step-title {
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

.transporter-register-step-line,
.step-line {
  width: 52px;
  min-width: 30px;
  height: 1px;
  margin: 0 10px;
  background: #d7e1db;
}

/* Main form card */
.transporter-register-card {
  padding: 28px;
  border: 1px solid var(--ks-border);
  border-radius: 24px;
  background: #fff;
  box-shadow: var(--ks-shadow);
}

.transporter-register-section {
  padding: 4px 0 28px;
}

.transporter-register-section + .transporter-register-section {
  border-top: 1px solid #edf2ef;
  padding-top: 28px;
}

.transporter-register-section-heading {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  margin-bottom: 22px;
}

.transporter-register-section-number {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: var(--ks-green-soft);
  color: var(--ks-green);
  font-weight: 900;
  font-size: 12px;
}

.transporter-register-section-heading span {
  display: block;
  margin-bottom: 4px;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .12em;
  color: var(--ks-green);
}

.transporter-register-section-heading h2 {
  margin: 0;
  font-size: 20px;
  letter-spacing: -.02em;
}

.transporter-register-section-heading p {
  margin: 5px 0 0;
  color: var(--ks-muted);
  font-size: 13px;
}

.transporter-register-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.transporter-register-grid > .full-width,
.transporter-register-grid > .span-2 {
  grid-column: 1 / -1;
}

.transporter-register-field,
.transporter-field,
.register-field {
  min-width: 0;
}

.transporter-register-field label,
.transporter-field > label,
.register-field > label,
.transporter-register-field > label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 7px;
  color: #274238;
  font-size: 12px;
  font-weight: 800;
}

.transporter-register-field input,
.transporter-register-field select,
.transporter-register-field textarea,
.transporter-field input,
.transporter-field select,
.transporter-field textarea,
.register-field input,
.register-field select,
.register-field textarea {
  width: 100%;
  border: 1px solid #d7e2dc;
  border-radius: 12px;
  outline: none;
  background: #fff;
  color: var(--ks-text);
  transition: border-color .18s ease, box-shadow .18s ease, background .18s ease;
}

.transporter-register-field input,
.transporter-register-field select,
.transporter-field input,
.transporter-field select,
.register-field input,
.register-field select {
  min-height: 46px;
  padding: 0 13px;
}

.transporter-register-field textarea,
.transporter-field textarea,
.register-field textarea {
  min-height: 100px;
  padding: 12px 13px;
  resize: vertical;
}

.transporter-register-field input:focus,
.transporter-register-field select:focus,
.transporter-register-field textarea:focus,
.transporter-field input:focus,
.transporter-field select:focus,
.transporter-field textarea:focus,
.register-field input:focus,
.register-field select:focus,
.register-field textarea:focus {
  border-color: #63ae80;
  box-shadow: 0 0 0 4px rgba(23,114,69,.08);
}

.transporter-register-input-wrap {
  position: relative;
}

.transporter-register-input-wrap > svg {
  position: absolute;
  left: 13px;
  top: 50%;
  transform: translateY(-50%);
  color: #729082;
  pointer-events: none;
}

.transporter-register-input-wrap input,
.transporter-register-input-wrap select {
  padding-left: 42px;
}

.transporter-register-input-wrap input[type="password"] {
  padding-right: 44px;
}

.field-help,
.transporter-register-field small,
.transporter-field small {
  display: block;
  margin-top: 6px;
  color: #8a9790;
  font-size: 11px;
  line-height: 1.5;
}

/* Vehicle / option cards */
.transporter-register-vehicle-grid,
.vehicle-options,
.vehicle-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.transporter-register-vehicle-card,
.vehicle-option,
.vehicle-card {
  position: relative;
  padding: 15px;
  border: 1px solid #dbe6df;
  border-radius: 15px;
  background: #fff;
  cursor: pointer;
  transition: .2s ease;
}

.transporter-register-vehicle-card:hover,
.vehicle-option:hover,
.vehicle-card:hover {
  transform: translateY(-2px);
  border-color: #98c9aa;
  box-shadow: 0 10px 24px rgba(22,61,43,.07);
}

.transporter-register-vehicle-card.active,
.transporter-register-vehicle-card.selected,
.vehicle-option.active,
.vehicle-option.selected,
.vehicle-card.active,
.vehicle-card.selected {
  border-color: var(--ks-green);
  background: #f3faf5;
  box-shadow: 0 8px 22px rgba(23,114,69,.09);
}

.transporter-register-vehicle-card strong,
.vehicle-option strong,
.vehicle-card strong {
  display: block;
  margin-top: 8px;
  font-size: 13px;
}

.transporter-register-vehicle-card span,
.vehicle-option span,
.vehicle-card span {
  display: block;
  margin-top: 3px;
  color: var(--ks-muted);
  font-size: 11px;
}

/* Tags / chips */
.transporter-register-chip-list,
.chip-list,
.selected-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.transporter-register-chip,
.chip,
.selected-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  border-radius: 999px;
  background: #cde7d3;
  color: var(--ks-green-dark);
  font-size: 11px;
  font-weight: 700;
}

.transporter-register-chip button,
.chip button,
.selected-chip button {
  width: 19px;
  height: 19px;
  display: grid;
  place-items: center;
  border: 0;
  border-radius: 50%;
  background: rgba(23,114,69,.1);
  color: var(--ks-green-dark);
  cursor: pointer;
}

/* Alerts */
.transporter-register-alert {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 13px 15px;
  margin-bottom: 18px;
  border-radius: 13px;
  font-size: 13px;
  line-height: 1.5;
}

.transporter-register-alert.error {
  border: 1px solid #f1cccc;
  background: #fff4f4;
  color: #8c2f2f;
}

.transporter-register-alert.success {
  border: 1px solid #c9e7d2;
  background: #f2fbf4;
  color: #21663b;
}

/* Actions */
.transporter-register-actions,
.register-actions,
.transporter-form-actions {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 26px;
  padding-top: 22px;
  border-top: 1px solid #edf2ef;
}

.transporter-register-actions button,
.register-actions button,
.transporter-form-actions button {
  min-height: 46px;
  padding: 0 18px;
  border-radius: 11px;
  border: 1px solid #d5e0da;
  background: #fff;
  color: #355046;
  font-weight: 800;
  cursor: pointer;
  transition: .18s ease;
}

.transporter-register-actions button:hover,
.register-actions button:hover,
.transporter-form-actions button:hover {
  transform: translateY(-1px);
}

.transporter-register-actions .primary,
.register-actions .primary,
.transporter-form-actions .primary,
button.transporter-primary {
  border-color: var(--ks-green);
  background: var(--ks-green);
  color: #fff;
  box-shadow: 0 9px 20px rgba(23,114,69,.18);
}

.transporter-register-actions .primary:hover,
.register-actions .primary:hover,
.transporter-form-actions .primary:hover {
  background: var(--ks-green-dark);
}

/* =========================================================
   TRANSPORTER LOGIN
   ========================================================= */

.transporter-login-page {
  display: flex;
  flex-direction: column;
}

.transporter-login-shell {
  width: min(1100px, calc(100% - 32px));
  margin: auto;
  padding: 38px 0 56px;
}

.transporter-login-card {
  display: grid;
  grid-template-columns: 1.03fr .97fr;
  min-height: 610px;
  overflow: hidden;
  border: 1px solid var(--ks-border);
  border-radius: 26px;
  background: #fff;
  box-shadow: 0 24px 65px rgba(22,61,43,.10);
}

.transporter-login-brand-panel {
  position: relative;
  overflow: hidden;
  padding: 46px;
  background:
    radial-gradient(circle at 10% 10%, rgba(255,255,255,.18), transparent 25%),
    linear-gradient(145deg, #0e5c36, #19834f);
  color: #fff;
}

.transporter-login-brand-panel::after {
  content: "";
  position: absolute;
  width: 260px;
  height: 260px;
  right: -110px;
  bottom: -110px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.16);
  box-shadow:
    0 0 0 32px rgba(255,255,255,.03),
    0 0 0 64px rgba(255,255,255,.025);
}

.transporter-login-logo-wrap {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 54px;
}

.transporter-login-logo,
.transporter-login-logo-wrap img {
  width: auto;
  height: 52px;
  max-width: 210px;
  object-fit: contain;
}

.transporter-login-brand-panel .transporter-login-logo,
.transporter-login-brand-panel .transporter-login-logo-wrap img {
  filter: none;
}

.transporter-login-brand-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  margin-bottom: 14px;
  border: 1px solid rgba(255,255,255,.20);
  border-radius: 999px;
  background: rgba(255,255,255,.08);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .1em;
}

.transporter-login-brand-panel h1 {
  max-width: 500px;
  margin: 0;
  font-size: clamp(30px, 4vw, 46px);
  line-height: 1.06;
  letter-spacing: -.04em;
}

.transporter-login-brand-panel > p {
  max-width: 500px;
  margin: 17px 0 0;
  color: rgba(255,255,255,.79);
  font-size: 14px;
  line-height: 1.75;
}

.transporter-login-benefits {
  display: grid;
  gap: 12px;
  margin-top: 32px;
}

.transporter-login-benefit {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 12px 0;
  border-top: 1px solid rgba(255,255,255,.11);
}

.transporter-login-benefit:first-child {
  border-top: 0;
}

.transporter-login-benefit-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: rgba(255,255,255,.12);
}

.transporter-login-benefit strong {
  display: block;
  margin-bottom: 3px;
  font-size: 12px;
}

.transporter-login-benefit span {
  display: block;
  color: rgba(255,255,255,.70);
  font-size: 11px;
  line-height: 1.5;
}

/* Login form */
.transporter-login-form-panel {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 42px;
  background: #fff;
}

.transporter-login-form-inner {
  width: 100%;
  max-width: 410px;
}

.transporter-login-form-inner > .eyebrow,
.transporter-login-eyebrow {
  display: block;
  margin-bottom: 8px;
  color: var(--ks-green);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .13em;
}

.transporter-login-form-inner h2 {
  margin: 0;
  font-size: 30px;
  letter-spacing: -.03em;
}

.transporter-login-form-inner > p {
  margin: 8px 0 25px;
  color: var(--ks-muted);
  font-size: 13px;
  line-height: 1.6;
}

.transporter-login-field {
  margin-bottom: 17px;
}

.transporter-login-field label {
  display: block;
  margin-bottom: 7px;
  font-size: 12px;
  font-weight: 800;
  color: #28443a;
}

.transporter-login-input-wrap {
  position: relative;
}

.transporter-login-input-wrap svg {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: #789087;
  pointer-events: none;
}

.transporter-login-input-wrap input {
  width: 100%;
  height: 50px;
  padding: 0 45px;
  border: 1px solid #d5e0da;
  border-radius: 13px;
  outline: none;
  background: #fff;
  color: var(--ks-text);
  transition: .18s ease;
}

.transporter-login-input-wrap input:focus {
  border-color: #61aa7d;
  box-shadow: 0 0 0 4px rgba(23,114,69,.08);
}

.transporter-login-password-toggle {
  position: absolute;
  top: 50%;
  right: 10px;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  transform: translateY(-50%);
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: #6f8178;
  cursor: pointer;
}

.transporter-login-password-toggle:hover {
  background: #f0f6f2;
  color: var(--ks-green);
}

.transporter-login-remember {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 8px 0 19px;
  color: var(--ks-muted);
  font-size: 12px;
}

.transporter-login-remember input {
  accent-color: var(--ks-green);
}

.transporter-login-submit {
  width: 100%;
  height: 50px;
  border: 0;
  border-radius: 13px;
  background: var(--ks-green);
  color: #fff;
  font-weight: 900;
  cursor: pointer;
  box-shadow: 0 10px 24px rgba(23,114,69,.18);
  transition: .18s ease;
}

.transporter-login-submit:hover {
  background: var(--ks-green-dark);
  transform: translateY(-1px);
}

.transporter-login-register {
  margin-top: 18px;
  text-align: center;
  color: var(--ks-muted);
  font-size: 12px;
}

.transporter-login-register a {
  color: var(--ks-green);
  font-weight: 800;
  text-decoration: none;
}

.transporter-login-register a:hover {
  text-decoration: underline;
}

.transporter-login-alert {
  display: flex;
  gap: 9px;
  align-items: flex-start;
  margin-bottom: 16px;
  padding: 12px 13px;
  border-radius: 11px;
  font-size: 12px;
  line-height: 1.5;
}

.transporter-login-alert.error {
  border: 1px solid #efcaca;
  background: #fff3f3;
  color: #8a3030;
}

.transporter-login-alert.success {
  border: 1px solid #cbe6d3;
  background: #f1faf4;
  color: #22643b;
}

/* =========================================================
   FARMER TRANSPORT TRACKING
   ========================================================= */

.farmer-transport-tracking-page {
  padding-bottom: 55px;
}

.farmer-transport-tracking-shell {
  width: min(1180px, calc(100% - 32px));
  margin: 0 auto;
  padding: 30px 0 50px;
}

.ftt-header,
.transport-tracking-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 18px;
  margin-bottom: 18px;
}

.ftt-header h1,
.transport-tracking-header h1 {
  margin: 0;
  font-size: clamp(25px, 4vw, 36px);
  line-height: 1.1;
  letter-spacing: -.035em;
}

.ftt-header p,
.transport-tracking-header p {
  margin: 8px 0 0;
  max-width: 720px;
  color: var(--ks-muted);
  font-size: 13px;
  line-height: 1.6;
}

.ftt-status-pill,
.transport-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 34px;
  padding: 0 12px;
  border-radius: 999px;
  background: #eff8f2;
  color: var(--ks-green-dark);
  font-size: 11px;
  font-weight: 900;
  white-space: nowrap;
}

.ftt-status-dot,
.transport-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #35a660;
  box-shadow: 0 0 0 5px rgba(53,166,96,.10);
}

/* Main tracking grid */
.ftt-grid,
.transport-tracking-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.43fr) minmax(310px, .77fr);
  gap: 18px;
  align-items: start;
}

.ftt-card,
.transport-tracking-card {
  border: 1px solid var(--ks-border);
  border-radius: 20px;
  background: #fff;
  box-shadow: 0 12px 34px rgba(22,61,43,.06);
}

.ftt-card + .ftt-card,
.transport-tracking-card + .transport-tracking-card {
  margin-top: 18px;
}

.ftt-card-header,
.transport-tracking-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 18px 20px;
  border-bottom: 1px solid #edf2ef;
}

.ftt-card-header h2,
.transport-tracking-card-header h2 {
  margin: 0;
  font-size: 15px;
  letter-spacing: -.01em;
}

.ftt-card-header span,
.transport-tracking-card-header span {
  color: var(--ks-muted);
  font-size: 11px;
}

.ftt-card-body,
.transport-tracking-card-body {
  padding: 20px;
}

/* Active vehicle hero */
.ftt-live-hero,
.transport-live-hero {
  position: relative;
  overflow: hidden;
  padding: 22px;
  border-radius: 20px;
  background:
    radial-gradient(circle at 86% 10%, rgba(255,255,255,.16), transparent 25%),
    linear-gradient(135deg, #115f38 0%, #1b8351 100%);
  color: #fff;
  box-shadow: 0 15px 34px rgba(23,114,69,.18);
}

.ftt-live-hero::after,
.transport-live-hero::after {
  content: "";
  position: absolute;
  width: 185px;
  height: 185px;
  right: -70px;
  bottom: -95px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.14);
}

.ftt-live-top,
.transport-live-top {
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: space-between;
  gap: 16px;
}

.ftt-live-eyebrow,
.transport-live-eyebrow {
  display: block;
  margin-bottom: 5px;
  color: rgba(255,255,255,.72);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .12em;
}

.ftt-live-hero h2,
.transport-live-hero h2 {
  margin: 0;
  font-size: 24px;
  letter-spacing: -.025em;
}

.ftt-live-hero p,
.transport-live-hero p {
  margin: 7px 0 0;
  color: rgba(255,255,255,.75);
  font-size: 12px;
  line-height: 1.5;
}

.ftt-eta,
.transport-eta {
  position: relative;
  z-index: 1;
  min-width: 112px;
  padding: 12px;
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 14px;
  background: rgba(255,255,255,.10);
  text-align: right;
}

.ftt-eta small,
.transport-eta small {
  display: block;
  margin-bottom: 3px;
  color: rgba(255,255,255,.68);
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
}

.ftt-eta strong,
.transport-eta strong {
  display: block;
  font-size: 22px;
}

/* Route visual */
.ftt-route,
.transport-route {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 13px;
  align-items: center;
  margin-top: 21px;
}

.ftt-route-point,
.transport-route-point {
  display: grid;
  justify-items: center;
  gap: 6px;
}

.ftt-route-marker,
.transport-route-marker {
  width: 35px;
  height: 35px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #fff;
  color: var(--ks-green);
  box-shadow: 0 8px 16px rgba(8,45,24,.17);
}

.ftt-route-label,
.transport-route-label {
  max-width: 92px;
  color: rgba(255,255,255,.88);
  font-size: 10px;
  text-align: center;
  line-height: 1.35;
}

.ftt-route-line,
.transport-route-line {
  position: relative;
  height: 3px;
  border-radius: 99px;
  background: rgba(255,255,255,.25);
}

.ftt-route-progress,
.transport-route-progress {
  width: 55%;
  height: 100%;
  border-radius: inherit;
  background: #fff;
}

.ftt-route-truck,
.transport-route-truck {
  position: absolute;
  top: 50%;
  left: 55%;
  transform: translate(-50%, -50%);
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #fff;
  color: var(--ks-green);
  box-shadow: 0 5px 12px rgba(5,31,16,.18);
}

/* Timeline */
.ftt-timeline,
.transport-timeline {
  display: grid;
  gap: 0;
}

.ftt-timeline-item,
.transport-timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 34px 1fr;
  gap: 12px;
  min-height: 64px;
}

.ftt-timeline-item:not(:last-child)::before,
.transport-timeline-item:not(:last-child)::before {
  content: "";
  position: absolute;
  left: 16px;
  top: 31px;
  bottom: -3px;
  width: 2px;
  background: #dce7e1;
}

.ftt-timeline-item.done:not(:last-child)::before,
.transport-timeline-item.done:not(:last-child)::before {
  background: #84c19b;
}

.ftt-timeline-icon,
.transport-timeline-icon {
  position: relative;
  z-index: 1;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid #d9e4de;
  background: #fff;
  color: #8a9b92;
}

.ftt-timeline-item.done .ftt-timeline-icon,
.transport-timeline-item.done .transport-timeline-icon {
  border-color: #7bc092;
  background: #ecf8ef;
  color: var(--ks-green);
}

.ftt-timeline-item.active .ftt-timeline-icon,
.transport-timeline-item.active .transport-timeline-icon {
  border-color: var(--ks-green);
  background: var(--ks-green);
  color: #fff;
  box-shadow: 0 0 0 5px rgba(23,114,69,.08);
}

.ftt-timeline-content strong,
.transport-timeline-content strong {
  display: block;
  padding-top: 1px;
  font-size: 12px;
}

.ftt-timeline-content span,
.transport-timeline-content span {
  display: block;
  margin-top: 3px;
  color: var(--ks-muted);
  font-size: 11px;
  line-height: 1.5;
}

/* Transporter info */
.ftt-driver,
.transport-driver {
  display: flex;
  align-items: center;
  gap: 13px;
}

.ftt-driver-avatar,
.transport-driver-avatar {
  width: 50px;
  height: 50px;
  flex: 0 0 50px;
  display: grid;
  place-items: center;
  border-radius: 15px;
  background: var(--ks-green-soft);
  color: var(--ks-green);
}

.ftt-driver strong,
.transport-driver strong {
  display: block;
  font-size: 14px;
}

.ftt-driver span,
.transport-driver span {
  display: block;
  margin-top: 3px;
  color: var(--ks-muted);
  font-size: 11px;
}

.ftt-driver-actions,
.transport-driver-actions {
  display: flex;
  gap: 8px;
  margin-top: 15px;
}

.ftt-driver-actions a,
.ftt-driver-actions button,
.transport-driver-actions a,
.transport-driver-actions button {
  flex: 1;
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid #d8e3dd;
  border-radius: 10px;
  background: #fff;
  color: #315046;
  text-decoration: none;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}

.ftt-driver-actions .primary,
.transport-driver-actions .primary {
  border-color: var(--ks-green);
  background: var(--ks-green);
  color: #fff;
}

/* Detail grid */
.ftt-details-grid,
.transport-details-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 11px;
}

.ftt-detail,
.transport-detail {
  padding: 12px;
  border: 1px solid #e4ece7;
  border-radius: 13px;
  background: #fbfdfc;
}

.ftt-detail-label,
.transport-detail-label {
  display: block;
  margin-bottom: 4px;
  color: #84938c;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.ftt-detail strong,
.transport-detail strong {
  font-size: 12px;
}

/* Fare */
.ftt-fare-total,
.transport-fare-total {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 15px;
  margin-bottom: 14px;
}

.ftt-fare-total span,
.transport-fare-total span {
  color: var(--ks-muted);
  font-size: 11px;
}

.ftt-fare-total strong,
.transport-fare-total strong {
  color: var(--ks-green-dark);
  font-size: 27px;
}

.ftt-fare-breakdown,
.transport-fare-breakdown {
  display: grid;
  gap: 8px;
  padding-top: 12px;
  border-top: 1px dashed #dce6e0;
}

.ftt-fare-row,
.transport-fare-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  color: #65766e;
  font-size: 11px;
}

.ftt-fare-row strong,
.transport-fare-row strong {
  color: #2f473d;
}

/* Tracking controls */
.ftt-controls,
.transport-tracking-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 15px;
}

.ftt-controls button,
.transport-tracking-controls button {
  min-height: 40px;
  padding: 0 13px;
  border: 1px solid #d8e4dd;
  border-radius: 10px;
  background: #fff;
  color: #315046;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}

.ftt-controls button.primary,
.transport-tracking-controls button.primary {
  border-color: var(--ks-green);
  background: var(--ks-green);
  color: #fff;
}

/* Loading / empty / error */
.ftt-loading,
.ftt-empty,
.ftt-error,
.transport-tracking-loading,
.transport-tracking-empty,
.transport-tracking-error {
  padding: 30px 20px;
  text-align: center;
  border: 1px dashed #d9e4de;
  border-radius: 15px;
  background: #fff;
  color: var(--ks-muted);
  font-size: 13px;
}

.ftt-error,
.transport-tracking-error {
  border-color: #efcccc;
  background: #fff6f6;
  color: #8f3434;
}

/* Rating */
.ftt-rating,
.transport-rating {
  display: flex;
  gap: 6px;
  margin-top: 12px;
}

.ftt-rating button,
.transport-rating button {
  border: 0;
  background: transparent;
  color: #b3bdb8;
  padding: 2px;
  cursor: pointer;
}

.ftt-rating button.active,
.transport-rating button.active {
  color: var(--ks-gold);
}

/* Responsive */
@media (max-width: 900px) {
  .transporter-login-card {
    grid-template-columns: 1fr;
  }

  .transporter-login-brand-panel {
    min-height: 330px;
  }

  .transporter-login-form-panel {
    padding: 32px 24px 38px;
  }

  .ftt-grid,
  .transport-tracking-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .transporter-register-shell,
  .transporter-login-shell,
  .farmer-transport-tracking-shell {
    width: min(100% - 20px, 1180px);
  }

  .transporter-register-hero {
    grid-template-columns: auto 1fr;
  }

  .transporter-register-hero-badge {
    grid-column: 1 / -1;
    justify-self: start;
  }

  .transporter-register-card {
    padding: 20px;
  }

  .transporter-register-grid {
    grid-template-columns: 1fr;
  }

  .transporter-register-grid > .full-width,
  .transporter-register-grid > .span-2 {
    grid-column: auto;
  }

  .transporter-register-vehicle-grid,
  .vehicle-options,
  .vehicle-grid {
    grid-template-columns: 1fr;
  }

  .transporter-register-actions,
  .register-actions,
  .transporter-form-actions,
  .ftt-header,
  .transport-tracking-header {
    flex-direction: column;
    align-items: stretch;
  }

  .transporter-register-actions button,
  .register-actions button,
  .transporter-form-actions button {
    width: 100%;
  }

  .ftt-live-top,
  .transport-live-top {
    flex-direction: column;
  }

  .ftt-eta,
  .transport-eta {
    width: fit-content;
    text-align: left;
  }
}

@media (max-width: 560px) {
  .transporter-register-shell,
  .transporter-login-shell,
  .farmer-transport-tracking-shell {
    width: calc(100% - 14px);
  }

  .transporter-register-hero {
    padding: 20px;
    border-radius: 18px;
  }

  .transporter-register-hero-icon {
    width: 52px;
    height: 52px;
    border-radius: 15px;
  }

  .transporter-register-hero h1 {
    font-size: 25px;
  }

  .transporter-register-card {
    border-radius: 18px;
    padding: 16px;
  }

  .transporter-register-section-heading h2 {
    font-size: 18px;
  }

  .transporter-login-brand-panel {
    padding: 30px 24px;
  }

  .transporter-login-form-panel {
    padding: 27px 18px 32px;
  }

  .transporter-login-brand-panel h1 {
    font-size: 31px;
  }

  .ftt-details-grid,
  .transport-details-grid {
    grid-template-columns: 1fr;
  }

  .ftt-card-header,
  .transport-tracking-card-header,
  .ftt-card-body,
  .transport-tracking-card-body {
    padding-left: 15px;
    padding-right: 15px;
  }
}


/* =========================================================
   KRISHISETU ADMIN SIDEBAR — FINAL PRODUCTION LAYOUT FIX
   Append this block at the VERY END of src/index.css.
   Fixes:
   - full-height sidebar without clipping
   - independently scrollable navigation
   - fixed header and system/logout area
   - no forced 101vh overflow
   - proper desktop content offset
   - mobile drawer remains fully scrollable
========================================================= */

.admin-sidebar {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  bottom: 0 !important;

  width: 270px !important;
  min-width: 270px !important;
  max-width: 270px !important;

  height: 100vh !important;
  height: 100dvh !important;
  min-height: 0 !important;

  display: flex !important;
  flex-direction: column !important;

  box-sizing: border-box !important;
  overflow: hidden !important;

  z-index: 1000 !important;
}

/* Main application reserves exactly the sidebar width */
.admin-layout-main {
  margin-left: 270px !important;
  width: calc(100% - 270px) !important;
  min-width: 0 !important;
  box-sizing: border-box !important;
}

/* Header / brand never participates in scrolling */
.admin-sidebar-top {
  flex: 0 0 auto !important;
  min-height: 0 !important;
}

/* Navigation is the ONLY desktop scroll container */
.admin-sidebar-nav {
  flex: 1 1 auto !important;
  min-height: 0 !important;

  overflow-y: auto !important;
  overflow-x: hidden !important;

  display: block !important;

  padding: 4px 7px 12px 0 !important;
  box-sizing: border-box !important;

  scrollbar-width: thin;
  scrollbar-color: rgba(74, 103, 116, 0.28) transparent;
}

/* Never compress sections/items to fit the screen */
.admin-sidebar-group {
  flex: 0 0 auto !important;
  min-height: max-content !important;
  margin-bottom: 14px !important;
}

/* Keep every navigation item reachable */
.admin-sidebar-items {
  display: flex !important;
  flex-direction: column !important;
  gap: 3px !important;
}

.admin-sidebar-link {
  flex: 0 0 auto !important;
  min-height: 48px !important;
  box-sizing: border-box !important;
}

/* Bottom status + logout stay visible */
.admin-sidebar-bottom {
  flex: 0 0 auto !important;
  min-height: 0 !important;

  transform: none !important;

  margin-top: 0 !important;
  padding-top: 10px !important;
  padding-bottom: 10px !important;

  box-sizing: border-box !important;
}

/* Scrollbar */
.admin-sidebar-nav::-webkit-scrollbar {
  width: 5px;
}

.admin-sidebar-nav::-webkit-scrollbar-track {
  background: transparent;
}

.admin-sidebar-nav::-webkit-scrollbar-thumb {
  background: rgba(74, 103, 116, 0.28);
  border-radius: 999px;
}

.admin-sidebar-nav::-webkit-scrollbar-thumb:hover {
  background: rgba(74, 103, 116, 0.42);
}

/* =========================================================
   LAPTOP / SHORT HEIGHT
========================================================= */

@media (max-height: 820px) and (min-width: 901px) {
  .admin-sidebar-link {
    min-height: 44px !important;
  }

  .admin-sidebar-section {
    margin-top: 13px !important;
    margin-bottom: 5px !important;
  }

  .admin-sidebar-group {
    margin-bottom: 8px !important;
  }

  .admin-sidebar-brand {
    padding-top: 7px !important;
    padding-bottom: 7px !important;
  }

  .admin-sidebar-bottom {
    padding-top: 7px !important;
    padding-bottom: 7px !important;
  }
}

/* Very short laptop: keep navigation scrollable instead of hiding items */
@media (max-height: 700px) and (min-width: 901px) {
  .admin-sidebar-link {
    min-height: 40px !important;
    font-size: 13px !important;
  }

  .admin-sidebar-section {
    margin-top: 8px !important;
    margin-bottom: 3px !important;
    font-size: 9px !important;
  }

  .admin-sidebar-group {
    margin-bottom: 4px !important;
  }

  .admin-sidebar-status {
    margin-bottom: 5px !important;
  }

  .admin-sidebar-logout {
    min-height: 38px !important;
  }
}

/* =========================================================
   MOBILE DRAWER
========================================================= */

@media (max-width: 900px) {
  .admin-sidebar {
    width: 285px !important;
