/* =========================================================
   KRISHISETU — FINAL VIEWPORT MODAL SYSTEM
   ========================================================= */

/*
   CORE RULE:
   A modal is a viewport UI, NOT part of the page's scroll.
   It always starts from the top of the viewport and its
   CONTENT is what scrolls.
*/


/* =========================================================
   1. CENTER FORM OVERLAY
   ========================================================= */

.admin-center-form-overlay {
  position: fixed !important;

  top: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  left: 0 !important;

  width: 100vw !important;
  height: 100dvh !important;

  min-height: 100dvh !important;

  margin: 0 !important;

  z-index: 50000 !important;

  display: flex !important;

  /*
     IMPORTANT:
     Do NOT center tall forms vertically.
     Always start near the top of the viewport.
  */
  align-items: flex-start !important;
  justify-content: center !important;

  padding:
    24px
    24px
    24px !important;

  box-sizing: border-box !important;

  overflow: hidden !important;

  /*
     Full-screen backdrop.
  */
  background:
    rgba(18, 38, 46, 0.46) !important;

  backdrop-filter:
    blur(9px) !important;

  -webkit-backdrop-filter:
    blur(9px) !important;

  overscroll-behavior: none !important;
}


/* =========================================================
   2. CENTER FORM ITSELF
   ========================================================= */

.admin-center-form-modal {
  position: relative !important;

  /*
     Never let the modal become taller than the viewport.
  */
  width: min(920px, 96vw) !important;

  max-width: 920px !important;

  height: auto !important;

  max-height:
    calc(100dvh - 48px) !important;

  min-height: 0 !important;

  margin:
    0 auto !important;

  box-sizing: border-box !important;

  overflow-x: hidden !important;

  overflow-y: auto !important;

  overscroll-behavior:
    contain !important;

  -webkit-overflow-scrolling:
    touch !important;

  flex: 0 1 auto !important;

  /*
     Do NOT use transform to position the modal.
     This prevents another containing-block bug.
  */
  transform: none !important;

  translate: none !important;
}


/* Remove the old opening transform animation */
.admin-center-form-modal {
  animation:
    adminCenterModalSafeIn
    0.18s
    ease-out
    both !important;
}

@keyframes adminCenterModalSafeIn {

  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }

}


