      farmerRegisterCardIn
      .32s
      ease-out
      both;
  }

  .farmer-register-page .register-intro {
    animation:
      farmerRegisterIntroIn
      .35s
      ease-out
      both;
  }

  .farmer-register-page .register-benefits > div {
    animation:
      farmerRegisterBenefitIn
      .28s
      ease-out
      both;
  }

  .farmer-register-page .register-benefits > div:nth-child(2) {
    animation-delay:
      .04s;
  }

  .farmer-register-page .register-benefits > div:nth-child(3) {
    animation-delay:
      .08s;
  }

  @keyframes farmerRegisterCardIn {
    from {
      opacity: 0;
      transform:
        translateY(8px);
    }

    to {
      opacity: 1;
      transform:
        translateY(0);
