/* =========================================================
   ADMIN TRANSPORT DETAILS MODAL
   This is the important scroll/locking fix.
   ========================================================= */

.at-modal-backdrop{
  position:fixed !important;
  inset:0 !important;
  width:100vw !important;
  height:100dvh !important;
  min-height:100dvh !important;
  padding:18px !important;
  margin:0 !important;

  display:grid !important;
  place-items:center !important;

  background:rgba(13,31,21,.42) !important;
  backdrop-filter:blur(5px);
  -webkit-backdrop-filter:blur(5px);

  overflow:hidden !important;
  overscroll-behavior:none !important;
  touch-action:none !important;

  z-index:50000 !important;
}

.at-modal{
  position:relative !important;

  width:min(680px,100%) !important;
  max-width:680px !important;

  /*
    Keep the modal inside the viewport.
    The modal itself becomes the scroll container.
  */
  height:auto !important;
  max-height:calc(100dvh - 36px) !important;
  min-height:0 !important;

  overflow-y:auto !important;
  overflow-x:hidden !important;

  overscroll-behavior:contain !important;
  -webkit-overflow-scrolling:touch !important;
  touch-action:pan-y !important;

  background:#fff !important;
  border:1px solid #dbe6df;
  border-radius:20px;
  padding:22px;
  box-shadow:0 28px 90px rgba(9,25,16,.22);

  box-sizing:border-box !important;

  /*
    Prevent long words/addresses from forcing the
    modal wider than the viewport.
  */
  overflow-wrap:anywhere;
}

.at-modal > *{
  max-width:100%;
}

.at-modal-close{
  position:sticky !important;
  right:auto;
  top:0;

  float:right;

  border:0;
  background:#f2f6f3;
  width:32px;
  height:32px;
  border-radius:9px;
  font-size:20px;
  color:#60766a;
  cursor:pointer;

  z-index:3;
}

.at-modal h2{
  clear:both;
  margin:4px 0 16px;
  font-size:22px;
}

.at-detail-grid{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:9px;
  min-width:0;
}

.at-detail-grid>div{
  min-width:0;
  border:1px solid #e4ebe6;
  border-radius:11px;
  padding:10px;
  background:#fbfdfb;
}

.at-detail-grid small,
.at-detail-grid strong{
  display:block;
}

.at-detail-grid small{
  font-size:8px;
  letter-spacing:.08em;
  text-transform:uppercase;
  color:#899790;
  font-weight:950;
}

.at-detail-grid strong{
  font-size:10px;
  margin-top:4px;
  color:#385344;
  line-height:1.45;
  overflow-wrap:anywhere;
  word-break:break-word;
}

.at-modal-footer{
  display:flex;
  gap:8px;
  margin-top:16px;
  flex-wrap:wrap;
}

.at-modal-btn{
  display:inline-flex;
  align-items:center;
  gap:6px;
  padding:9px 12px;
  border-radius:10px;
  background:#edf6f0;
  color:#2e714c;
  text-decoration:none;
  font-size:10px;
  font-weight:950;
}

.at-modal-btn.muted{
  background:#f6f8f6;
  color:#60786b;
}

/* ---------- Tablet ---------- */

@media (max-width:1100px){
  .at-stats{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }

  .at-request{
    grid-template-columns:55px minmax(120px,1.2fr) minmax(100px,1fr) minmax(130px,1.3fr) minmax(110px,1fr) 110px;
  }

  .at-active-grid{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
}

/* ---------- Smaller tablet ---------- */

@media (max-width:860px){
  .at-header{
    align-items:flex-start;
    flex-direction:column;
  }

  .at-search-wrap{
    width:100%;
  }

  .at-toolbar{
    flex-direction:column;
    align-items:stretch;
  }

  .at-request{
    grid-template-columns:50px minmax(0,1fr) minmax(0,1fr);
  }

  .at-request-main.wide{
    grid-column:2 / -1;
  }

  .at-request-side{
    grid-column:1 / -1;
    flex-direction:row;
    justify-content:flex-start;
    align-items:center;
  }

  .at-active-grid{
    grid-template-columns:1fr;
  }
}

/* ---------- Mobile ---------- */

@media (max-width:600px){
  .at-page{
    padding:18px 13px 35px;
  }

  .at-header h1{
    font-size:28px;
  }

  .at-header p{
    font-size:12px;
  }

  .at-stats{
    grid-template-columns:1fr 1fr;
  }

  .at-systembar{
    align-items:flex-start;
    flex-wrap:wrap;
  }

  .at-systembar small{
    margin-left:0;
    width:100%;
  }

  .at-detail-grid{
    grid-template-columns:1fr;
  }

  .at-modal-backdrop{
    padding:10px !important;
    place-items:center !important;
  }

  .at-modal{
    width:100% !important;
    max-width:100% !important;
    max-height:calc(100dvh - 20px) !important;
    border-radius:16px;
    padding:17px;
  }

  .at-modal-footer{
    flex-direction:column;
  }

  .at-modal-btn{
    width:100%;
    justify-content:center;
  }
}

/* ---------- Small mobile ---------- */

@media (max-width:430px){
  .at-page{
    padding-left:10px;
    padding-right:10px;
  }

  .at-stats{
    grid-template-columns:1fr;
  }

  .at-filters{
    overflow-x:auto;
    overflow-y:hidden;
    flex-wrap:nowrap;
    -webkit-overflow-scrolling:touch;
    scrollbar-width:none;
  }

  .at-filters::-webkit-scrollbar{
    display:none;
  }

  .at-request{
    grid-template-columns:1fr 1fr;
    gap:9px;
  }

  .at-request-id{
    grid-column:1 / -1;
  }

  .at-request-main.wide{
    grid-column:1 / -1;
  }

  .at-request-side{
    grid-column:1 / -1;
  }

  .at-modal{
    padding:15px;
    border-radius:14px;
  }

  .at-modal h2{
    font-size:19px;
  }
}

/* ---------- Dark theme compatibility ---------- */

html.dark .at-page{
  color:var(--ks-text,#e8f1eb);
}

html.dark .at-header h1{
  color:var(--ks-text,#e8f1eb);
}

html.dark .at-header p,
html.dark .at-stat span,
html.dark .at-request-main span,
html.dark .at-request-side small,
html.dark .at-trip>span,
html.dark .at-trip-meta,
html.dark .at-trip-route,
html.dark .at-mini-empty{
  color:var(--ks-muted,#a9b8af);
}

html.dark .at-stat,
html.dark .at-main-card,
html.dark .at-request,
html.dark .at-refresh,
html.dark .at-search-wrap,
html.dark .at-filters button,
html.dark .at-modal{
  background:var(--ks-surface,#13231a);
  color:var(--ks-text,#e8f1eb);
}

html.dark .at-stat,
html.dark .at-main-card,
html.dark .at-request,
html.dark .at-modal,
html.dark .at-detail-grid>div{
  border-color:rgba(220,240,226,.12);
}

html.dark .at-request:hover{
  background:rgba(255,255,255,.035);
}

html.dark .at-toolbar,
html.dark .at-filters{
  border-color:rgba(220,240,226,.10);
}

html.dark .at-search-wrap input{
  color:var(--ks-text,#e8f1eb);
}

html.dark .at-search-wrap{
  background:rgba(255,255,255,.025);
}

html.dark .at-detail-grid>div{
  background:rgba(255,255,255,.025);
}

html.dark .at-detail-grid strong{
  color:var(--ks-text,#e8f1eb);
}

html.dark .at-modal-close{
  background:rgba(255,255,255,.08);
  color:var(--ks-text,#e8f1eb);
}

html.dark .at-modal-btn{
  background:rgba(78,170,111,.14);
}

html.dark .at-modal-btn.muted{
  background:rgba(255,255,255,.06);
  color:var(--ks-text,#e8f1eb);
}



/* ============================================================
   ADMIN TRANSPORT DASHBOARD — VISUAL REDESIGN
   CSS ONLY — keeps existing .at-* markup and functionality
   ============================================================ */

.at-page{
  width:100%;
  max-width:1540px;
  min-width:0;
  margin:0 auto;
  padding:28px 30px 52px;
  box-sizing:border-box;
  color:#183126;
  font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
}

.at-page *,
.at-page *::before,
.at-page *::after{
  box-sizing:border-box;
}

/* ---------- HEADER ---------- */

.at-header{
  display:flex;
  justify-content:space-between;
  align-items:flex-end;
  gap:28px;
  margin:0 0 24px;
}

.at-eyebrow{
  margin:0 0 8px;
  color:#4d7b62;
  font-size:10px;
  line-height:1;
  letter-spacing:.19em;
  font-weight:900;
  text-transform:uppercase;
}

.at-header h1{
  margin:0;
  color:#173426;
  font-size:32px;
  line-height:1.12;
  letter-spacing:-.025em;
  font-weight:850;
}

.at-header p{
  max-width:680px;
  margin:9px 0 0;
  color:#718279;
  font-size:13px;
  line-height:1.55;
}

.at-head-actions{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:10px;
  flex-wrap:wrap;
}

.at-plain-link{
  color:#3d6d53;
  text-decoration:none;
  font-size:11px;
  font-weight:800;
}

.at-plain-link:hover{
  text-decoration:underline;
}

.at-refresh{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  min-height:38px;
  padding:0 13px;
  border:1px solid #d6e5dc;
  border-radius:10px;
  background:#fff;
  color:#2c6949;
  font:inherit;
  font-size:11px;
  font-weight:850;
  cursor:pointer;
  box-shadow:0 3px 10px rgba(25,65,44,.04);
  transition:transform .16s ease,box-shadow .16s ease,border-color .16s ease;
}

.at-refresh:hover{
  transform:translateY(-1px);
  border-color:#bfd5c7;
  box-shadow:0 7px 18px rgba(25,65,44,.08);
}

.at-refresh:disabled{
  opacity:.6;
  cursor:wait;
  transform:none;
}

.spin{
  animation:atspin .85s linear infinite;
}

@keyframes atspin{
  to{transform:rotate(360deg)}
}

/* ---------- KPI CARDS ---------- */

.at-stats{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:14px;
  margin-bottom:14px;
}

.at-stat{
  position:relative;
  min-width:0;
  min-height:104px;
  display:flex;
  align-items:center;
  gap:14px;
  padding:18px;
  overflow:hidden;
  border:1px solid #dce8e1;
  border-radius:17px;
  background:
    linear-gradient(145deg,#ffffff 0%,#fbfdfb 100%);
  box-shadow:0 7px 22px rgba(24,62,42,.055);
}

.at-stat::after{
  content:"";
  position:absolute;
  right:-26px;
  top:-32px;
  width:82px;
  height:82px;
  border-radius:50%;
  background:#edf7f0;
  opacity:.7;
}

.at-stat-icon{
  position:relative;
  z-index:1;
  flex:0 0 42px;
  width:42px;
  height:42px;
  display:grid;
  place-items:center;
  border:1px solid #d8ebdf;
  border-radius:12px;
  background:#edf7f1;
  color:#2c7750;
}

.at-stat strong,
.at-stat span{
  position:relative;
  z-index:1;
  display:block;
}

.at-stat strong{
  color:#173629;
  font-size:25px;
  line-height:1;
  letter-spacing:-.025em;
  font-weight:850;
}

.at-stat span{
  margin-top:6px;
  color:#71837a;
  font-size:10px;
  line-height:1.2;
  font-weight:800;
}

/* ---------- SYSTEM STATUS ---------- */

.at-systembar{
  display:flex;
  align-items:center;
  gap:10px;
  min-height:43px;
  margin-bottom:16px;
  padding:10px 13px;
  border:1px solid #d8e7de;
  border-radius:12px;
  background:#f7fbf8;
  color:#264638;
  font-size:10px;
}

.at-systembar span{
  color:#75877d;
}

.at-systembar small{
  margin-left:auto;
  color:#92a199;
  font-size:9px;
}

.at-system-dot{
  width:8px;
  height:8px;
  flex:0 0 8px;
  border-radius:50%;
  background:#3ea463;
  box-shadow:0 0 0 4px rgba(62,164,99,.11);
}

/* ---------- ERROR ---------- */

.at-alert{
  display:flex;
  align-items:center;
  gap:11px;
  margin-bottom:16px;
  padding:12px 14px;
  border-radius:13px;
}

.at-alert.error{
  border:1px solid #efd8d1;
  background:#fff6f3;
  color:#855044;
}

.at-alert div{
  display:grid;
  gap:3px;
  min-width:0;
  flex:1;
}

.at-alert strong{
  font-size:11px;
  font-weight:850;
}

.at-alert span{
  font-size:10px;
  line-height:1.45;
}

.at-alert button{
  border:1px solid #e4d0c9;
  border-radius:9px;
  padding:8px 10px;
  background:#fff;
  color:#7e4c40;
  font-size:10px;
  font-weight:850;
  cursor:pointer;
}

/* ---------- MAIN SECTIONS ---------- */

.at-main-card{
  margin-bottom:16px;
  overflow:hidden;
  border:1px solid #dce7e1;
  border-radius:20px;
  background:#fff;
  box-shadow:0 10px 30px rgba(18,55,35,.055);
}

.at-toolbar{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:20px;
  min-height:92px;
  padding:20px 22px 18px;
  border-bottom:1px solid #e7eee9;
}

.at-toolbar.compact{
  align-items:center;
  min-height:76px;
  padding-top:16px;
  padding-bottom:16px;
}

.at-card-label{
  margin-bottom:5px;
  color:#789087;
  font-size:9px;
  line-height:1;
  letter-spacing:.17em;
  font-weight:900;
  text-transform:uppercase;
}

.at-toolbar h2{
  margin:0;
  color:#18372a;
  font-size:25px;
  line-height:1;
  letter-spacing:-.025em;
  font-weight:850;
}

/* ---------- SEARCH ---------- */

.at-search-wrap{
  width:min(480px,100%);
  min-height:43px;
  display:flex;
  align-items:center;
  gap:9px;
  padding:0 13px;
  border:1px solid #d7e4dc;
  border-radius:12px;
  background:#fbfdfc;
  transition:border-color .16s ease,box-shadow .16s ease,background .16s ease;
}

.at-search-wrap:focus-within{
  border-color:#91bda4;
  background:#fff;
  box-shadow:0 0 0 3px rgba(75,139,98,.09);
}

.at-search-wrap svg{
  flex:0 0 auto;
  color:#789287;
}

.at-search-wrap input{
  width:100%;
  min-width:0;
  border:0;
  outline:0;
  padding:11px 0;
  background:transparent;
  color:#294437;
  font:inherit;
  font-size:11px;
}

.at-search-wrap input::placeholder{
  color:#9aa9a1;
}

/* ---------- FILTERS ---------- */

.at-filters{
  display:flex;
  gap:7px;
  align-items:center;
  padding:12px 18px;
  overflow-x:auto;
  border-bottom:1px solid #e9efeb;
  background:#fcfefd;
  scrollbar-width:thin;
}

.at-filters button{
  flex:0 0 auto;
  min-height:34px;
  padding:0 13px;
  border:1px solid #dce7e0;
  border-radius:999px;
  background:#fff;
  color:#687d72;
  font-size:10px;
  font-weight:850;
  cursor:pointer;
  transition:background .15s ease,color .15s ease,border-color .15s ease,transform .15s ease;
}

.at-filters button:hover{
  transform:translateY(-1px);
  border-color:#bdd4c5;
  color:#356b4d;
}

.at-filters button.selected{
  border-color:#8fbea1;
  background:#eaf6ee;
  color:#246944;
  box-shadow:inset 0 0 0 1px rgba(70,132,92,.04);
}

/* ---------- REQUEST LIST ---------- */

.at-request-list{
  display:grid;
  background:#fff;
}

.at-request{
  position:relative;
  display:grid;
  grid-template-columns:72px minmax(140px,1.05fr) minmax(100px,.7fr) minmax(190px,1.35fr) minmax(155px,1fr) 135px;
  gap:18px;
  align-items:center;
  min-width:0;
  padding:18px 22px;
  border:0;
  border-bottom:1px solid #edf2ee;
  background:#fff;
  text-align:left;
  font:inherit;
  cursor:pointer;
  transition:background .15s ease,box-shadow .15s ease;
}

.at-request:last-child{
  border-bottom:0;
}

.at-request:hover{
  background:#fbfdfc;
  box-shadow:inset 3px 0 0 #5a9b72;
}

.at-request:focus-visible{
  outline:2px solid #6da181;
  outline-offset:-2px;
}

.at-request-id{
  min-width:0;
  color:#8a9a92;
  font-size:9px;
  line-height:1.35;
  font-weight:850;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.at-request-main{
  min-width:0;
}

.at-request-main strong,
.at-request-main span{
  display:block;
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.at-request-main strong{
  color:#213d30;
  font-size:11px;
  line-height:1.35;
  font-weight:850;
}

.at-request-main span{
  margin-top:5px;
  color:#7e9087;
  font-size:9px;
  line-height:1.3;
}

.at-request-main.wide{
  min-width:0;
}

.at-request-side{
  min-width:0;
  display:flex;
  flex-direction:column;
  align-items:flex-end;
  justify-content:center;
  gap:6px;
}

.at-request-side small{
  color:#9aa69f;
  font-size:8px;
  line-height:1.2;
  white-space:nowrap;
}

.at-request-side a{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  color:#347b54;
  text-decoration:none;
}

.at-request-side a:hover{
  color:#1f603d;
}

/* ---------- STATUS BADGES ---------- */

.at-badge{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:max-content;
  max-width:100%;
  min-height:25px;
  padding:0 9px;
  border:1px solid #dbe7df;
  border-radius:999px;
  background:#f7faf8;
  color:#61776b;
  font-size:8px;
  line-height:1;
  font-weight:900;
  white-space:nowrap;
}

.status-requested{
  border-color:#eadcae;
  background:#fff9e7;
  color:#8a6927;
}

.status-assigned{
  border-color:#d3e2f1;
  background:#f0f7ff;
  color:#456e98;
}

.status-en_route_to_farmer,
.status-crop_picked_up,
.status-en_route_to_center{
  border-color:#cce4d5;
  background:#edf8f1;
  color:#2d744e;
}

.status-delivered,
.status-completed{
  border-color:#c5e1ce;
  background:#eaf7ee;
  color:#28714a;
}

.status-cancelled{
  border-color:#ebd1ca;
  background:#fff3f0;
  color:#965246;
}

/* ---------- ACTIVE TRIPS ---------- */

.at-live-pill{
  display:inline-flex;
  align-items:center;
  gap:6px;
  min-height:31px;
  padding:0 11px;
  border:1px solid #d4e6db;
  border-radius:999px;
  background:#f5fbf7;
  color:#397052;
  font-size:9px;
  font-weight:900;
}

.at-mini-empty{
  padding:27px 20px;
  color:#7c8e84;
  font-size:10px;
  text-align:center;
}

.at-active-grid{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:13px;
  padding:16px 18px 19px;
}

.at-trip{
  min-width:0;
  padding:16px;
  border:1px solid #dce8e1;
  border-radius:15px;
  background:linear-gradient(145deg,#fff 0%,#fbfdfb 100%);
  transition:transform .16s ease,box-shadow .16s ease,border-color .16s ease;
}

.at-trip:hover{
  transform:translateY(-2px);
  border-color:#c9ddd0;
  box-shadow:0 10px 24px rgba(26,68,45,.08);
}

.at-trip-top{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
}

.at-trip-icon{
  width:36px;
  height:36px;
  display:grid;
  place-items:center;
  border:1px solid #d8ebdf;
  border-radius:11px;
  background:#edf7f1;
  color:#2e754e;
}

.at-trip>strong,
.at-trip>span{
  display:block;
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.at-trip>strong{
  margin-top:11px;
  color:#294536;
  font-size:12px;
  font-weight:850;
}

.at-trip>span{
  margin-top:4px;
  color:#7a8d83;
  font-size:10px;
}

.at-trip-meta{
  display:flex;
  justify-content:space-between;
  gap:10px;
  margin-top:10px;
  color:#657a6e;
  font-size:9px;
}

.at-trip-route{
  display:grid;
  grid-template-columns:16px minmax(0,1fr) 16px minmax(0,1fr);
  gap:6px;
  align-items:center;
  margin-top:12px;
  padding-top:11px;
  border-top:1px dashed #dce7e0;
  color:#70827a;
  font-size:9px;
}

.at-trip-route span{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.at-trip-route svg:first-child{
  color:#317651;
}

.at-trip-actions{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  margin-top:12px;
}

.at-trip-actions a{
  display:inline-flex;
  align-items:center;
  gap:5px;
  min-height:29px;
  padding:0 9px;
  border:1px solid #d6e6dc;
  border-radius:8px;
  background:#f6fbf8;
  color:#2e704c;
  font-size:9px;
  font-weight:900;
  text-decoration:none;
}

.at-trip-actions a:hover{
  background:#edf7f1;
}

/* ---------- EMPTY STATE ---------- */

.at-empty{
  min-height:230px;
  display:grid;
  place-items:center;
  align-content:center;
  gap:8px;
  padding:28px 20px;
  color:#70827a;
  text-align:center;
}

.at-empty svg{
  color:#478261;
}

.at-empty strong{
  color:#40594b;
  font-size:12px;
}

.at-empty span{
  color:#819189;
  font-size:10px;
}

/* ---------- MODAL / DETAIL DRAWER ---------- */

.at-modal-backdrop{
  position:fixed;
  inset:0;
  width:100vw;
  height:100dvh;
  display:grid;
  place-items:center;
  padding:20px;
  overflow:hidden;
  overscroll-behavior:none;
  background:rgba(10,29,19,.58);
  backdrop-filter:blur(7px);
  -webkit-backdrop-filter:blur(7px);
  z-index:50000;
  touch-action:none;
}

.at-modal{
  position:relative;
  width:min(720px,100%);
  max-width:720px;
  max-height:calc(100dvh - 40px);
  min-height:0;
  overflow-x:hidden;
  overflow-y:auto;
  overscroll-behavior:contain;
  -webkit-overflow-scrolling:touch;
  touch-action:pan-y;
  padding:26px;
  border:1px solid #d6e5dc;
  border-radius:20px;
  background:#fff;
  box-shadow:0 30px 90px rgba(4,23,13,.28);
  scrollbar-width:thin;
  scrollbar-color:#b9cec0 transparent;
}

.at-modal::-webkit-scrollbar{
  width:8px;
}

.at-modal::-webkit-scrollbar-track{
  background:transparent;
}

.at-modal::-webkit-scrollbar-thumb{
  border-radius:99px;
  background:#b9cec0;
}

.at-modal-close{
  position:absolute;
  top:14px;
  right:14px;
  width:34px;
  height:34px;
  display:grid;
  place-items:center;
  border:1px solid #dce7e1;
  border-radius:10px;
  background:#f5f8f6;
  color:#60766a;
  font-size:20px;
  line-height:1;
  cursor:pointer;
}

.at-modal-close:hover{
  background:#edf5f0;
  color:#315d45;
}

.at-modal h2{
  margin:2px 45px 18px 0;
  color:#19372a;
  font-size:23px;
  line-height:1.2;
  letter-spacing:-.02em;
  font-weight:850;
}

.at-detail-grid{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:10px;
}

.at-detail-grid>div{
  min-width:0;
  padding:12px;
  border:1px solid #e0eae4;
  border-radius:11px;
  background:#fafcfb;
}

.at-detail-grid small,
.at-detail-grid strong{
  display:block;
}

.at-detail-grid small{
  color:#899890;
  font-size:8px;
  line-height:1.2;
  letter-spacing:.1em;
  font-weight:900;
  text-transform:uppercase;
}

.at-detail-grid strong{
  margin-top:5px;
  color:#385344;
  font-size:10px;
  line-height:1.5;
  overflow-wrap:anywhere;
}

.at-modal-footer{
  display:flex;
  flex-wrap:wrap;
  gap:9px;
  margin-top:18px;
  padding-top:16px;
  border-top:1px solid #e7eee9;
}

.at-modal-btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:6px;
  min-height:35px;
  padding:0 12px;
  border:1px solid #d4e6db;
  border-radius:9px;
  background:#eaf6ee;
  color:#2d704c;
  font-size:10px;
  font-weight:900;
  text-decoration:none;
}

.at-modal-btn:hover{
  background:#e0f1e7;
}

.at-modal-btn.muted{
  border-color:#e0e7e2;
  background:#f6f8f7;
  color:#61766a;
}

/* ---------- RESPONSIVE: 1200 ---------- */

@media (max-width:1200px){
  .at-request{
    grid-template-columns:65px minmax(125px,1fr) minmax(90px,.75fr) minmax(165px,1.2fr) minmax(140px,1fr) 120px;
    gap:13px;
    padding-left:18px;
    padding-right:18px;
  }

  .at-active-grid{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
}

/* ---------- RESPONSIVE: 980 ---------- */

@media (max-width:980px){
  .at-page{
    padding:22px 20px 42px;
  }

  .at-header{
    align-items:flex-start;
    flex-direction:column;
    gap:15px;
  }

  .at-head-actions{
    justify-content:flex-start;
  }

  .at-search-wrap{
    width:100%;
  }

  .at-toolbar{
    align-items:stretch;
    flex-direction:column;
    gap:15px;
  }

  .at-request{
    grid-template-columns:64px minmax(130px,1.2fr) minmax(95px,.8fr) minmax(145px,1fr) 118px;
  }

  .at-request-main.wide{
    grid-column:2 / 4;
  }

  .at-request-side{
    grid-column:5;
    grid-row:1 / span 2;
  }
}

/* ---------- RESPONSIVE: 760 ---------- */

@media (max-width:760px){
  .at-page{
    padding:18px 14px 34px;
  }

  .at-header h1{
    font-size:28px;
  }

  .at-header p{
    font-size:12px;
  }

  .at-stats{
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:10px;
  }

  .at-stat{
    min-height:92px;
    padding:14px;
  }

  .at-stat-icon{
    width:38px;
    height:38px;
    flex-basis:38px;
  }

  .at-toolbar{
    padding:17px;
  }

  .at-toolbar h2{
    font-size:23px;
  }

  .at-request{
    grid-template-columns:1fr 1fr;
    gap:0 16px;
    padding:16px 17px;
  }

  .at-request-id{
    grid-column:1 / -1;
    margin-bottom:9px;
  }

  .at-request-main{
    margin-bottom:11px;
  }

  .at-request-main.wide{
    grid-column:1 / -1;
  }

  .at-request-side{
    grid-column:1 / -1;
    grid-row:auto;
    flex-direction:row;
    align-items:center;
    justify-content:flex-start;
    gap:9px;
    padding-top:9px;
    border-top:1px dashed #e1eae4;
  }

  .at-request-side small{
    margin-left:auto;
  }

  .at-active-grid{
    grid-template-columns:1fr;
    padding:13px;
  }

  .at-modal-backdrop{
    padding:10px;
  }

  .at-modal{
    width:100%;
    max-width:none;
    max-height:calc(100dvh - 20px);
    padding:21px;
    border-radius:17px;
  }
}

/* ---------- RESPONSIVE: 520 ---------- */

@media (max-width:520px){
  .at-stats{
    grid-template-columns:1fr 1fr;
  }

  .at-stat{
    gap:10px;
    padding:13px 12px;
  }

  .at-stat strong{
    font-size:21px;
  }

  .at-stat span{
    font-size:9px;
  }

  .at-systembar{
    align-items:flex-start;
    flex-wrap:wrap;
  }

  .at-systembar small{
    width:100%;
    margin-left:18px;
  }

  .at-filters{
    padding:10px 13px;
  }

  .at-request{
    grid-template-columns:1fr 1fr;
    padding:15px 14px;
  }

  .at-request-main strong{
    font-size:10px;
  }

  .at-request-main span{
    font-size:8.5px;
  }

  .at-detail-grid{
    grid-template-columns:1fr;
  }

  .at-modal-footer{
    flex-direction:column;
  }

  .at-modal-btn{
    width:100%;
  }
}

/* ---------- VERY SMALL ---------- */

@media (max-width:390px){
  .at-page{
    padding-left:10px;
    padding-right:10px;
  }

  .at-stats{
    grid-template-columns:1fr;
  }

  .at-header h1{
    font-size:25px;
  }

  .at-request{
    display:block;
  }

  .at-request-id{
    margin-bottom:10px;
  }

  .at-request-main{
    margin-bottom:12px;
  }

  .at-request-side{
    display:flex;
    margin-top:3px;
  }

  .at-request-side small{
    margin-left:auto;
  }
}

/* ---------- DARK THEME COMPATIBILITY ---------- */

.dark .at-page,
[data-theme="dark"] .at-page{
  color:#e7f0ea;
}

.dark .at-stat,
[data-theme="dark"] .at-stat,
.dark .at-main-card,
[data-theme="dark"] .at-main-card,
.dark .at-request,
[data-theme="dark"] .at-request,
.dark .at-modal,
[data-theme="dark"] .at-modal,
.dark .at-trip,
[data-theme="dark"] .at-trip{
  background:#15231c;
  border-color:#2c4136;
}

.dark .at-header h1,
[data-theme="dark"] .at-header h1,
.dark .at-toolbar h2,
[data-theme="dark"] .at-toolbar h2,
.dark .at-stat strong,
[data-theme="dark"] .at-stat strong,
.dark .at-request-main strong,
[data-theme="dark"] .at-request-main strong,
.dark .at-modal h2,
[data-theme="dark"] .at-modal h2{
  color:#e6f1e9;
}

.dark .at-header p,
[data-theme="dark"] .at-header p,
.dark .at-stat span,
[data-theme="dark"] .at-stat span,
.dark .at-request-main span,
[data-theme="dark"] .at-request-main span,
.dark .at-request-side small,
[data-theme="dark"] .at-request-side small{
  color:#9aaca2;
}

.dark .at-toolbar,
[data-theme="dark"] .at-toolbar,
.dark .at-filters,
[data-theme="dark"] .at-filters,
.dark .at-request,
[data-theme="dark"] .at-request{
  border-color:#293c33;
}

.dark .at-filters,
[data-theme="dark"] .at-filters,
.dark .at-search-wrap,
[data-theme="dark"] .at-search-wrap{
  background:#111d17;
}

.dark .at-filters button,
[data-theme="dark"] .at-filters button,
.dark .at-refresh,
[data-theme="dark"] .at-refresh{
  background:#17271f;
  border-color:#344a3e;
  color:#b3c5ba;
}

.dark .at-modal-close,
[data-theme="dark"] .at-modal-close{
  background:#203129;
  border-color:#385046;
  color:#b7c8be;
}

@media (prefers-reduced-motion:reduce){
  .at-page *,
  .at-page *::before,
  .at-page *::after{
    scroll-behavior:auto !important;
    transition:none !important;
    animation:none !important;
  }
}



/* ============================================================
   ADMIN TRANSPORT DASHBOARD
   LARGE / CLEAR / REAL-WORLD ADMIN UI
   ============================================================ */

.at-page{
  width:100%;
  max-width:1600px;
  min-width:0;
  margin:0 auto;
  padding:32px 34px 56px;
  color:#183426;
  font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
  box-sizing:border-box;
}

.at-page *,
.at-page *::before,
.at-page *::after{
  box-sizing:border-box;
}

/* =========================
   HEADER
   ========================= */

.at-header{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:30px;
  margin-bottom:28px;
}

.at-eyebrow{
  margin:0 0 10px;
  color:#3d7454;
  font-size:12px;
  line-height:1;
  letter-spacing:.18em;
  font-weight:900;
  text-transform:uppercase;
}

.at-header h1{
  margin:0;
  color:#173628;
  font-size:38px;
  line-height:1.08;
  letter-spacing:-.03em;
  font-weight:850;
}

.at-header p{
  max-width:760px;
  margin:11px 0 0;
  color:#6d8176;
  font-size:15px;
  line-height:1.6;
}

.at-head-actions{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:12px;
  flex-wrap:wrap;
}

.at-plain-link{
  color:#356c4d;
  text-decoration:none;
  font-size:13px;
  font-weight:850;
}

.at-plain-link:hover{
  text-decoration:underline;
}

.at-refresh{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  min-height:44px;
  padding:0 16px;
  border:1px solid #cddfd3;
  border-radius:11px;
  background:#fff;
  color:#286443;
  font:inherit;
  font-size:13px;
  font-weight:850;
  cursor:pointer;
  box-shadow:0 4px 14px rgba(22,59,39,.05);
}

.at-refresh:hover{
  border-color:#a8c8b5;
  background:#f8fcf9;
}

.at-refresh:disabled{
  opacity:.6;
  cursor:wait;
}

.spin{
  animation:atspin .8s linear infinite;
}

@keyframes atspin{
  to{transform:rotate(360deg)}
}

/* =========================
   STAT CARDS
   ========================= */

.at-stats{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:18px;
  margin-bottom:18px;
}

.at-stat{
  position:relative;
  min-width:0;
  min-height:126px;
  display:flex;
  align-items:center;
  gap:16px;
  padding:22px;
  overflow:hidden;
  border:1px solid #d9e6de;
  border-radius:19px;
  background:#fff;
  box-shadow:0 9px 28px rgba(21,59,39,.065);
}

.at-stat-icon{
  flex:0 0 50px;
  width:50px;
  height:50px;
  display:grid;
  place-items:center;
  border:1px solid #d6eadc;
  border-radius:14px;
  background:#edf7f1;
  color:#2b7650;
}

.at-stat strong,
.at-stat span{
  display:block;
}

.at-stat strong{
  color:#163629;
  font-size:31px;
  line-height:1;
  letter-spacing:-.03em;
  font-weight:900;
}

.at-stat span{
  margin-top:8px;
  color:#71837a;
  font-size:13px;
  line-height:1.3;
  font-weight:750;
}

/* =========================
   CONNECTION BAR
   ========================= */

.at-systembar{
  display:flex;
  align-items:center;
  gap:11px;
  min-height:50px;
  margin-bottom:20px;
  padding:12px 16px;
  border:1px solid #d4e5db;
  border-radius:14px;
  background:#f7fbf8;
  color:#244536;
  font-size:12px;
}

.at-systembar span{
  color:#71847a;
}

.at-systembar small{
  margin-left:auto;
  color:#899a91;
  font-size:11px;
}

.at-system-dot{
  width:10px;
  height:10px;
  flex:0 0 10px;
  border-radius:50%;
  background:#3ea263;
  box-shadow:0 0 0 5px rgba(62,162,99,.1);
}

/* =========================
   ERROR
   ========================= */

.at-alert{
  display:flex;
  align-items:center;
  gap:13px;
  margin-bottom:18px;
  padding:15px 17px;
  border-radius:14px;
}

.at-alert.error{
  border:1px solid #ead2ca;
  background:#fff5f2;
  color:#875044;
}

.at-alert div{
  display:grid;
  gap:4px;
  min-width:0;
  flex:1;
}

.at-alert strong{
  font-size:13px;
}

.at-alert span{
  font-size:12px;
  line-height:1.45;
}

.at-alert button{
  border:1px solid #dfc9c1;
  border-radius:9px;
  padding:9px 12px;
  background:#fff;
  color:#79483c;
  font-size:11px;
  font-weight:850;
  cursor:pointer;
}

/* =========================
   CARDS
   ========================= */

.at-main-card{
  width:100%;
  min-width:0;
  margin-bottom:20px;
  overflow:hidden;
  border:1px solid #d7e4dc;
  border-radius:22px;
  background:#fff;
  box-shadow:0 10px 34px rgba(20,57,38,.065);
}

.at-toolbar{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:24px;
  min-height:112px;
  padding:25px 28px 23px;
  border-bottom:1px solid #e3ebe6;
}

.at-toolbar.compact{
  align-items:center;
  min-height:92px;
  padding-top:21px;
  padding-bottom:21px;
}

.at-card-label{
  margin-bottom:8px;
  color:#71887b;
  font-size:11px;
  line-height:1;
  letter-spacing:.17em;
  font-weight:900;
  text-transform:uppercase;
}

.at-toolbar h2{
  margin:0;
  color:#19382a;
  font-size:30px;
  line-height:1;
  letter-spacing:-.025em;
  font-weight:900;
}

/* =========================
   SEARCH
   ========================= */

.at-search-wrap{
  width:min(520px,100%);
  min-height:52px;
  display:flex;
  align-items:center;
  gap:11px;
  padding:0 15px;
  border:1px solid #d2e1d8;
  border-radius:13px;
  background:#fbfdfc;
}

.at-search-wrap:focus-within{
  border-color:#86b79a;
  background:#fff;
  box-shadow:0 0 0 4px rgba(66,137,91,.08);
}

.at-search-wrap svg{
  flex:0 0 auto;
  color:#718c7d;
}

.at-search-wrap input{
  width:100%;
  min-width:0;
  border:0;
  outline:0;
  padding:13px 0;
  background:transparent;
  color:#294638;
  font:inherit;
  font-size:14px;
}

.at-search-wrap input::placeholder{
  color:#9aa9a1;
}

/* =========================
   FILTER BAR
   ========================= */

.at-filters{
  display:flex;
  align-items:center;
  gap:9px;
  padding:14px 24px;
  overflow-x:auto;
  border-bottom:1px solid #e4ebe7;
  background:#fcfefd;
  scrollbar-width:thin;
}

.at-filters button{
  flex:0 0 auto;
  min-height:40px;
  padding:0 16px;
  border:1px solid #d7e3dc;
  border-radius:999px;
  background:#fff;
  color:#657a6f;
  font-size:12px;
  font-weight:850;
  cursor:pointer;
}

.at-filters button:hover{
  border-color:#abcbb7;
  color:#2f6d4c;
}

.at-filters button.selected{
  border-color:#88b79a;
  background:#eaf6ee;
  color:#246844;
  box-shadow:0 2px 7px rgba(40,105,67,.06);
}

/* ============================================================
   REQUEST TABLE
   IMPORTANT:
   - minmax(0,...) prevents overflow
   - action column has a guaranteed width
   - every child can shrink
   ============================================================ */

.at-request-list{
  display:block;
  width:100%;
  min-width:0;
  overflow:hidden;
  background:#fff;
}

.at-request{
  width:100%;
  min-width:0;
  display:grid;
  grid-template-columns:
    minmax(92px,.65fr)
    minmax(165px,1.25fr)
    minmax(120px,.9fr)
    minmax(190px,1.35fr)
    minmax(155px,1.05fr)
    minmax(142px,.85fr);
  gap:20px;
  align-items:center;
  padding:22px 26px;
  border:0;
  border-bottom:1px solid #e8efeb;
  background:#fff;
  text-align:left;
  font:inherit;
  cursor:pointer;
}

.at-request:last-child{
  border-bottom:0;
}

.at-request:hover{
  background:#fbfdfc;
  box-shadow:inset 4px 0 0 #55966e;
}

.at-request:focus-visible{
  outline:3px solid rgba(74,143,99,.2);
  outline-offset:-3px;
}

/* Every grid child is allowed to shrink. */
.at-request > *{
  min-width:0;
  max-width:100%;
}

.at-request-id{
  min-width:0;
  color:#71877a;
  font-size:11px;
  line-height:1.35;
  font-weight:850;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.at-request-main{
  min-width:0;
  max-width:100%;
}

.at-request-main strong,
.at-request-main span{
  display:block;
  min-width:0;
  max-width:100%;
  overflow:hidden;
  text-overflow:ellipsis;
}

.at-request-main strong{
  color:#203f30;
  font-size:15px;
  line-height:1.35;
  font-weight:900;
  white-space:nowrap;
}

.at-request-main span{
  margin-top:7px;
  color:#7a8d83;
  font-size:11px;
  line-height:1.35;
  white-space:nowrap;
}

.at-request-main.wide{
  min-width:0;
}

/* =========================
   ACTION / STATUS COLUMN
   ========================= */

.at-request-side{
  width:100%;
  min-width:0;
  max-width:100%;
  display:flex;
  flex-direction:column;
  align-items:flex-end;
  justify-content:center;
  gap:8px;
  overflow:hidden;
}

.at-request-side small{
  max-width:100%;
  color:#8d9c94;
  font-size:10px;
  line-height:1.25;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.at-request-side a{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:28px;
  height:28px;
  color:#317850;
  text-decoration:none;
}

.at-request-side a:hover{
  color:#1f603d;
  background:#edf7f1;
  border-radius:8px;
}

/* =========================
   BADGES
   ========================= */

.at-badge{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:max-content;
  max-width:100%;
  min-height:31px;
  padding:0 12px;
  border:1px solid #d9e6df;
  border-radius:999px;
  background:#f7faf8;
  color:#60766a;
  font-size:10px;
  line-height:1;
  font-weight:900;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.status-requested{
  border-color:#ead9a8;
  background:#fff9e8;
  color:#876725;
}

.status-assigned{
  border-color:#cbdfee;
  background:#eff7ff;
  color:#426d98;
}

.status-en_route_to_farmer,
.status-crop_picked_up,
.status-en_route_to_center{
  border-color:#c7e2d2;
  background:#edf8f1;
  color:#2b724c;
}

.status-delivered,
.status-completed{
  border-color:#c0dec9;
  background:#e9f7ed;
  color:#28704a;
}

.status-cancelled{
  border-color:#e9cec6;
  background:#fff3f0;
  color:#945045;
}

/* =========================
   ACTIVE TRIPS
   ========================= */

.at-live-pill{
  display:inline-flex;
  align-items:center;
  gap:7px;
  min-height:36px;
  padding:0 14px;
  border:1px solid #d1e4d8;
  border-radius:999px;
  background:#f4faf6;
  color:#34704e;
  font-size:11px;
  font-weight:900;
}

.at-mini-empty{
  padding:34px 22px;
  color:#75877e;
  font-size:12px;
  text-align:center;
}

.at-active-grid{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:16px;
  padding:20px 22px 23px;
}

.at-trip{
  min-width:0;
  padding:19px;
  border:1px solid #d9e6df;
  border-radius:16px;
  background:#fcfefd;
  box-shadow:0 4px 15px rgba(23,61,40,.035);
}

.at-trip-top{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
}

.at-trip-icon{
  width:43px;
  height:43px;
  display:grid;
  place-items:center;
  border:1px solid #d5e9dc;
  border-radius:12px;
  background:#edf7f1;
  color:#2d754e;
}

.at-trip>strong,
.at-trip>span{
  display:block;
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.at-trip>strong{
  margin-top:13px;
  color:#294638;
  font-size:14px;
  font-weight:900;
}

.at-trip>span{
  margin-top:5px;
  color:#758980;
  font-size:11px;
}

.at-trip-meta{
  display:flex;
  justify-content:space-between;
  gap:10px;
  margin-top:12px;
  color:#65796e;
  font-size:10px;
}

.at-trip-route{
  display:grid;
  grid-template-columns:18px minmax(0,1fr) 18px minmax(0,1fr);
  gap:7px;
  align-items:center;
  margin-top:13px;
  padding-top:13px;
  border-top:1px dashed #d9e5de;
  color:#6f8178;
  font-size:10px;
}

.at-trip-route span{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.at-trip-route svg:first-child{
  color:#307651;
}

.at-trip-actions{
  display:flex;
  flex-wrap:wrap;
  gap:9px;
  margin-top:14px;
}

.at-trip-actions a{
  display:inline-flex;
  align-items:center;
  gap:6px;
  min-height:34px;
  padding:0 11px;
  border:1px solid #d2e4da;
  border-radius:9px;
  background:#f4faf6;
  color:#2d704c;
  font-size:10px;
  font-weight:900;
  text-decoration:none;
}

/* =========================
   EMPTY
   ========================= */

.at-empty{
  min-height:270px;
  display:grid;
  place-items:center;
  align-content:center;
  gap:10px;
  padding:35px 22px;
  color:#71847a;
  text-align:center;
}

.at-empty svg{
  color:#407d59;
}

.at-empty strong{
  color:#3d5749;
  font-size:14px;
}

.at-empty span{
  color:#81928a;
  font-size:11px;
}

/* ============================================================
   MODAL
   ============================================================ */

.at-modal-backdrop{
  position:fixed;
  inset:0;
  width:100vw;
  height:100dvh;
  display:grid;
  place-items:center;
  padding:24px;
  overflow:hidden;
  overscroll-behavior:none;
  background:rgba(8,27,17,.58);
  backdrop-filter:blur(7px);
  -webkit-backdrop-filter:blur(7px);
  z-index:50000;
  touch-action:none;
}

.at-modal{
  position:relative;
  width:min(760px,100%);
  max-width:760px;
  max-height:calc(100dvh - 48px);
  min-height:0;
  overflow-x:hidden;
  overflow-y:auto;
  overscroll-behavior:contain;
  -webkit-overflow-scrolling:touch;
  touch-action:pan-y;
  padding:30px;
  border:1px solid #d4e4db;
  border-radius:21px;
  background:#fff;
  box-shadow:0 32px 100px rgba(3,22,13,.3);
  scrollbar-width:thin;
  scrollbar-color:#b8cec0 transparent;
}

.at-modal-close{
  position:absolute;
  top:15px;
  right:15px;
  width:38px;
  height:38px;
  display:grid;
  place-items:center;
  border:1px solid #d8e4dd;
  border-radius:10px;
  background:#f3f7f4;
  color:#60776b;
  font-size:22px;
  line-height:1;
  cursor:pointer;
}

.at-modal h2{
  margin:2px 50px 22px 0;
  color:#18372a;
  font-size:27px;
  line-height:1.2;
  font-weight:900;
}

.at-detail-grid{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:12px;
}

.at-detail-grid>div{
  min-width:0;
  padding:14px;
  border:1px solid #dce8e1;
  border-radius:12px;
  background:#fafcfb;
}

.at-detail-grid small,
.at-detail-grid strong{
  display:block;
}

.at-detail-grid small{
  color:#83948c;
  font-size:9px;
  letter-spacing:.1em;
  font-weight:900;
  text-transform:uppercase;
}

.at-detail-grid strong{
  margin-top:6px;
  color:#355243;
  font-size:12px;
  line-height:1.5;
  overflow-wrap:anywhere;
}

.at-modal-footer{
  display:flex;
  flex-wrap:wrap;
  gap:10px;
  margin-top:21px;
  padding-top:18px;
  border-top:1px solid #e3ebe6;
}

.at-modal-btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  min-height:40px;
  padding:0 14px;
  border:1px solid #cfe3d6;
  border-radius:10px;
  background:#eaf6ee;
  color:#2b704b;
  font-size:11px;
  font-weight:900;
  text-decoration:none;
}

.at-modal-btn.muted{
  border-color:#dfe7e2;
  background:#f5f8f6;
  color:#61766a;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width:1250px){
  .at-page{
    padding-left:25px;
    padding-right:25px;
  }

  .at-request{
    grid-template-columns:
      minmax(80px,.6fr)
      minmax(145px,1.2fr)
      minmax(105px,.85fr)
      minmax(170px,1.25fr)
      minmax(135px,1fr)
      minmax(125px,.8fr);
    gap:14px;
    padding-left:21px;
    padding-right:21px;
  }

  .at-request-main strong{
    font-size:14px;
  }
}

@media (max-width:1050px){
  .at-stats{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }

  .at-header{
    align-items:flex-start;
    flex-direction:column;
  }

  .at-head-actions{
    justify-content:flex-start;
  }

  .at-toolbar{
    align-items:stretch;
    flex-direction:column;
  }

  .at-search-wrap{
    width:100%;
  }

  .at-request{
    grid-template-columns:
      minmax(80px,.65fr)
      minmax(150px,1.25fr)
      minmax(105px,.9fr)
      minmax(150px,1.15fr)
      minmax(125px,1fr)
      minmax(120px,.85fr);
  }

  .at-active-grid{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
}

/* Tablet: switch from table-like row to a clear card row. */
@media (max-width:850px){
  .at-page{
    padding:22px 18px 42px;
  }

  .at-header h1{
    font-size:33px;
  }

  .at-toolbar{
    padding:21px;
  }

  .at-request{
    grid-template-columns:minmax(145px,1fr) minmax(125px,1fr) minmax(130px,1fr);
    gap:17px 20px;
    padding:20px;
  }

  .at-request-id{
    grid-column:1 / -1;
    padding-bottom:9px;
    border-bottom:1px dashed #dfe9e3;
    font-size:11px;
  }

  .at-request-main.wide{
    grid-column:1 / 3;
  }

  .at-request-side{
    grid-column:3;
    grid-row:2 / span 2;
    align-items:flex-end;
  }

  .at-active-grid{
    grid-template-columns:1fr;
  }
}

/* Mobile */
@media (max-width:620px){
  .at-page{
    padding:18px 12px 35px;
  }

  .at-header{
    margin-bottom:20px;
  }

  .at-header h1{
    font-size:29px;
  }

  .at-header p{
    font-size:13px;
  }

  .at-stats{
    grid-template-columns:1fr 1fr;
    gap:10px;
  }

  .at-stat{
    min-height:100px;
    gap:10px;
    padding:14px;
    border-radius:15px;
  }

  .at-stat-icon{
    width:40px;
    height:40px;
    flex-basis:40px;
  }

  .at-stat strong{
    font-size:25px;
  }

  .at-stat span{
    font-size:10px;
  }

  .at-systembar{
    flex-wrap:wrap;
    align-items:flex-start;
  }

  .at-systembar small{
    width:100%;
    margin-left:21px;
  }

  .at-toolbar{
    padding:18px;
  }

  .at-toolbar h2{
    font-size:26px;
  }

  .at-filters{
    padding:12px 14px;
  }

  .at-request{
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:0 17px;
    padding:19px 17px;
  }

  .at-request-id{
    grid-column:1 / -1;
    margin-bottom:13px;
  }

  .at-request-main{
    margin-bottom:15px;
  }

  .at-request-main.wide{
    grid-column:1 / -1;
  }

  .at-request-main strong{
    font-size:13px;
  }

  .at-request-main span{
    font-size:10px;
  }

  .at-request-side{
    grid-column:1 / -1;
    grid-row:auto;
    flex-direction:row;
    align-items:center;
    justify-content:flex-start;
    padding-top:12px;
    border-top:1px dashed #dfe9e3;
  }

  .at-request-side small{
    margin-left:auto;
  }

  .at-modal-backdrop{
    padding:10px;
  }

  .at-modal{
    width:100%;
    max-width:none;
    max-height:calc(100dvh - 20px);
    padding:22px;
    border-radius:17px;
  }

  .at-detail-grid{
    grid-template-columns:1fr;
  }

  .at-modal-footer{
    flex-direction:column;
  }

  .at-modal-btn{
    width:100%;
  }
}

@media (max-width:400px){
  .at-stats{
    grid-template-columns:1fr;
  }

  .at-request{
    display:block;
  }

  .at-request-id{
    margin-bottom:14px;
  }

  .at-request-main{
    margin-bottom:15px;
  }

  .at-request-side{
    display:flex;
    margin-top:4px;
  }
}

/* =========================
   ACCESSIBILITY
   ========================= */

@media (prefers-reduced-motion:reduce){
  .at-page *,
  .at-page *::before,
  .at-page *::after{
    animation:none !important;
    transition:none !important;
    scroll-behavior:auto !important;
  }
}




/* ================================================================
   KRISHISETU — ADMIN TRANSPORT DASHBOARD
   FINAL OVERRIDE CSS
   Paste this ENTIRE block at the VERY BOTTOM of index.css.

   IMPORTANT:
   Delete the old const STYLE = `...`; block from
   AdminTransportDashboard.jsx first.
   Also delete: <style>{STYLE}</style>

   This stylesheet is intentionally written from scratch.
   ================================================================ */


/* ----------------------------------------------------------------
   1. PAGE FOUNDATION
   ---------------------------------------------------------------- */

.at-page{
  width:100%;
  max-width:1600px;
  min-width:0;
  margin:0 auto;
  padding:34px 36px 60px;
  color:#18372a;
  font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
  box-sizing:border-box;
}

.at-page,
.at-page *,
.at-page *::before,
.at-page *::after{
  box-sizing:border-box;
}


/* ----------------------------------------------------------------
   2. HEADER
   ---------------------------------------------------------------- */

.at-header{
  width:100%;
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:30px;
  margin:0 0 28px;
}

.at-eyebrow{
  margin:0 0 10px;
  color:#34724f;
  font-size:12px;
  line-height:1;
  letter-spacing:.18em;
  font-weight:900;
  text-transform:uppercase;
}

.at-header h1{
  margin:0;
  color:#163a2a;
  font-size:40px;
  line-height:1.08;
  letter-spacing:-.035em;
  font-weight:900;
}

.at-header p{
  max-width:780px;
  margin:12px 0 0;
  color:#6d8177;
  font-size:15px;
  line-height:1.6;
}

.at-head-actions{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:12px;
  flex-wrap:wrap;
}

.at-plain-link{
  display:inline-flex;
  align-items:center;
  min-height:44px;
  color:#376b4e;
  font-size:13px;
  font-weight:850;
  text-decoration:none;
}

.at-plain-link:hover{
  text-decoration:underline;
}

.at-refresh{
  min-height:44px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  padding:0 17px;
  border:1px solid #cbded2;
  border-radius:11px;
  background:#ffffff;
  color:#286545;
  font:inherit;
  font-size:13px;
  font-weight:850;
  cursor:pointer;
  box-shadow:0 5px 15px rgba(21,61,39,.06);
  transition:.18s ease;
}

.at-refresh:hover{
  border-color:#9fc1ad;
  background:#f8fcf9;
  transform:translateY(-1px);
}

.at-refresh:disabled{
  opacity:.6;
  cursor:wait;
  transform:none;
}

.spin{
  animation:at-spin .8s linear infinite;
}

@keyframes at-spin{
  to{transform:rotate(360deg);}
}


/* ----------------------------------------------------------------
   3. STAT CARDS
   ---------------------------------------------------------------- */

.at-stats{
  width:100%;
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:18px;
  margin:0 0 18px;
}

.at-stat{
  position:relative;
  min-width:0;
  min-height:132px;
  display:flex;
  align-items:center;
  gap:17px;
  padding:22px;
  overflow:hidden;
  border:1px solid #d8e6de;
  border-radius:20px;
  background:#ffffff;
  box-shadow:0 10px 30px rgba(22,61,40,.065);
}

.at-stat::after{
  content:"";
  position:absolute;
  width:90px;
  height:90px;
  right:-32px;
  top:-34px;
  border-radius:50%;
  background:#eef8f2;
}

.at-stat-icon{
  position:relative;
  z-index:1;
  flex:0 0 52px;
  width:52px;
  height:52px;
  display:grid;
  place-items:center;
  border:1px solid #d3e8da;
  border-radius:14px;
  background:#edf8f1;
  color:#28764d;
}

.at-stat > div:last-child{
  position:relative;
  z-index:1;
  min-width:0;
}

.at-stat strong{
  display:block;
  color:#17392a;
  font-size:32px;
  line-height:1;
  letter-spacing:-.03em;
  font-weight:900;
}

.at-stat span{
  display:block;
  margin-top:8px;
  color:#708279;
  font-size:13px;
  line-height:1.3;
  font-weight:800;
}


/* ----------------------------------------------------------------
   4. SYSTEM STATUS
   ---------------------------------------------------------------- */

.at-systembar{
  width:100%;
  min-height:52px;
  display:flex;
  align-items:center;
  gap:11px;
  margin:0 0 20px;
  padding:13px 17px;
  border:1px solid #d5e5dc;
  border-radius:14px;
  background:#f7fbf8;
  color:#254738;
  font-size:12px;
}

.at-systembar strong{
  color:#244738;
  font-weight:900;
}

.at-systembar span{
  color:#72847b;
}

.at-systembar small{
  margin-left:auto;
  color:#899a91;
  font-size:11px;
}

.at-system-dot{
  width:10px;
  height:10px;
  flex:0 0 10px;
  border-radius:50%;
  background:#3ca263;
  box-shadow:0 0 0 5px rgba(60,162,99,.1);
}


/* ----------------------------------------------------------------
   5. ERROR
   ---------------------------------------------------------------- */

.at-alert{
  width:100%;
  display:flex;
  align-items:center;
  gap:13px;
  margin:0 0 20px;
  padding:16px 18px;
  border-radius:14px;
}

.at-alert.error{
  border:1px solid #ead2ca;
  background:#fff5f2;
  color:#875044;
}

.at-alert div{
  min-width:0;
  flex:1;
  display:grid;
  gap:4px;
}

.at-alert strong{
  font-size:13px;
  font-weight:900;
}

.at-alert span{
  font-size:12px;
  line-height:1.5;
}

.at-alert button{
  flex:0 0 auto;
  min-height:38px;
  padding:0 13px;
  border:1px solid #dfc9c1;
  border-radius:9px;
  background:#ffffff;
  color:#79483c;
  font-size:11px;
  font-weight:900;
  cursor:pointer;
}


/* ----------------------------------------------------------------
   6. MAIN CARDS
   ---------------------------------------------------------------- */

.at-main-card{
  width:100%;
  min-width:0;
  margin:0 0 20px;
  overflow:hidden;
  border:1px solid #d7e4dc;
  border-radius:22px;
  background:#ffffff;
  box-shadow:0 11px 35px rgba(20,57,38,.065);
}

.at-toolbar{
  width:100%;
  min-width:0;
  min-height:116px;
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:25px;
  padding:25px 28px 23px;
  border-bottom:1px solid #e2ebe6;
}

.at-toolbar.compact{
  min-height:94px;
  align-items:center;
  padding-top:21px;
  padding-bottom:21px;
}

.at-card-label{
  margin:0 0 8px;
  color:#71877b;
  font-size:11px;
  line-height:1;
  letter-spacing:.17em;
  font-weight:900;
  text-transform:uppercase;
}

.at-toolbar h2{
  margin:0;
  color:#173a2b;
  font-size:31px;
  line-height:1;
  letter-spacing:-.03em;
  font-weight:900;
}


/* ----------------------------------------------------------------
   7. SEARCH
   ---------------------------------------------------------------- */

.at-search-wrap{
  width:min(540px,100%);
  min-width:0;
  min-height:54px;
  display:flex;
  align-items:center;
  gap:11px;
  padding:0 16px;
  border:1px solid #cfdfd6;
  border-radius:13px;
  background:#fbfdfc;
}

.at-search-wrap svg{
  flex:0 0 auto;
  color:#708a7c;
}

.at-search-wrap input{
  width:100%;
  min-width:0;
  height:52px;
  border:0;
  outline:0;
  padding:0;
  background:transparent;
  color:#294738;
  font:inherit;
  font-size:14px;
}

.at-search-wrap input::placeholder{
  color:#9aa9a1;
}

.at-search-wrap:focus-within{
  border-color:#87b79a;
  background:#ffffff;
  box-shadow:0 0 0 4px rgba(63,137,91,.08);
}


/* ----------------------------------------------------------------
   8. FILTERS
   ---------------------------------------------------------------- */

.at-filters{
  width:100%;
  display:flex;
  align-items:center;
  gap:9px;
  padding:14px 24px;
  overflow-x:auto;
  overflow-y:hidden;
  border-bottom:1px solid #e4ebe7;
  background:#fcfefd;
  scrollbar-width:thin;
}

.at-filters button{
  flex:0 0 auto;
  min-height:40px;
  padding:0 17px;
  border:1px solid #d5e2db;
  border-radius:999px;
  background:#ffffff;
  color:#657a6f;
  font-size:12px;
  font-weight:900;
  white-space:nowrap;
  cursor:pointer;
  transition:.16s ease;
}

.at-filters button:hover{
  border-color:#a9c9b6;
  color:#2f6d4c;
  background:#f8fcf9;
}

.at-filters button.selected{
  border-color:#8bb99b;
  background:#eaf6ee;
  color:#236844;
  box-shadow:0 2px 8px rgba(39,104,67,.06);
}


/* =================================================================
   9. REQUEST TABLE — DESKTOP
   =================================================================

   Six columns:
   1 Booking
   2 Farmer
   3 Produce
   4 Schedule / route
   5 Transporter
   6 Status / action

   minmax(0,...) + min-width:0 prevents horizontal overflow.
   ================================================================= */

.at-request-list{
  width:100%;
  min-width:0;
  display:block;
  overflow:hidden;
  background:#ffffff;
}

.at-request{
  width:100%;
  min-width:0;
  display:grid;

  grid-template-columns:
    minmax(105px,.75fr)
    minmax(175px,1.2fr)
    minmax(125px,.85fr)
    minmax(190px,1.25fr)
    minmax(160px,1.05fr)
    minmax(145px,.9fr);

  gap:22px;
  align-items:center;

  padding:24px 28px;

  border:0;
  border-bottom:1px solid #e7eeea;
  background:#ffffff;

  text-align:left;
  font:inherit;
  cursor:pointer;

  transition:background .15s ease,box-shadow .15s ease;
}

.at-request:last-child{
  border-bottom:0;
}

.at-request:hover{
  background:#fbfdfc;
  box-shadow:inset 4px 0 0 #55976f;
}

.at-request:focus-visible{
  outline:3px solid rgba(69,142,97,.2);
  outline-offset:-3px;
}

/* Every direct child is allowed to shrink. */
.at-request > *{
  width:100%;
  min-width:0;
  max-width:100%;
  overflow:hidden;
}


/* ----------------------------------------------------------------
   10. REQUEST DATA
   ---------------------------------------------------------------- */

.at-request-id{
  min-width:0;
  max-width:100%;
  color:#6f8579;
  font-size:12px;
  line-height:1.4;
  font-weight:900;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.at-request-main{
  min-width:0;
  max-width:100%;
  overflow:hidden;
}

.at-request-main strong,
.at-request-main span{
  display:block;
  min-width:0;
  max-width:100%;
  overflow:hidden;
  text-overflow:ellipsis;
}

.at-request-main strong{
  color:#1f3f30;
  font-size:16px;
  line-height:1.35;
  font-weight:900;
  white-space:nowrap;
}

.at-request-main span{
  margin-top:7px;
  color:#788c82;
  font-size:11px;
  line-height:1.4;
  white-space:nowrap;
}

.at-request-main.wide{
  min-width:0;
}


/* ----------------------------------------------------------------
   11. STATUS COLUMN
   ---------------------------------------------------------------- */

.at-request-side{
  width:100%;
  min-width:0;
  max-width:100%;
  display:flex;
  flex-direction:column;
  align-items:flex-end;
  justify-content:center;
  gap:8px;
  overflow:hidden;
}

.at-request-side small{
  display:block;
  width:100%;
  max-width:100%;
  color:#899991;
  font-size:10px;
  line-height:1.3;
  text-align:right;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.at-request-side a{
  width:30px;
  height:30px;
  flex:0 0 30px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  border-radius:8px;
  color:#2e7650;
  text-decoration:none;
}

.at-request-side a:hover{
  background:#edf7f1;
}


/* ----------------------------------------------------------------
   12. STATUS BADGES
   ---------------------------------------------------------------- */

.at-badge{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:max-content;
  max-width:100%;
  min-height:32px;
  padding:0 12px;
  border:1px solid #d9e6df;
  border-radius:999px;
  background:#f7faf8;
  color:#60766a;
  font-size:10px;
  line-height:1;
  font-weight:900;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.status-requested{
  border-color:#ead9a8;
  background:#fff9e8;
  color:#876625;
}

.status-assigned{
  border-color:#cbdfee;
  background:#eff7ff;
  color:#426e99;
}

.status-en_route_to_farmer,
.status-crop_picked_up,
.status-en_route_to_center{
  border-color:#c6e2d1;
  background:#edf8f1;
  color:#2b734d;
}

.status-delivered,
.status-completed{
  border-color:#bfdec9;
  background:#e9f7ed;
  color:#28704a;
}

.status-cancelled{
  border-color:#e9cec6;
  background:#fff3f0;
  color:#955045;
}


/* ----------------------------------------------------------------
   13. ACTIVE TRIPS
   ---------------------------------------------------------------- */

.at-live-pill{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  min-height:38px;
  padding:0 14px;
  border:1px solid #d1e4d8;
  border-radius:999px;
  background:#f4faf6;
  color:#33704e;
  font-size:11px;
  font-weight:900;
}

.at-mini-empty{
  padding:36px 24px;
  color:#74877d;
  font-size:12px;
  text-align:center;
}

.at-active-grid{
  width:100%;
  min-width:0;
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:16px;
  padding:21px 22px 24px;
}

.at-trip{
  min-width:0;
  overflow:hidden;
  padding:20px;
  border:1px solid #d8e5de;
  border-radius:17px;
  background:#fcfefd;
  box-shadow:0 4px 16px rgba(22,61,40,.04);
}

.at-trip-top{
  min-width:0;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
}

.at-trip-icon{
  width:44px;
  height:44px;
  flex:0 0 44px;
  display:grid;
  place-items:center;
  border:1px solid #d3e8da;
  border-radius:12px;
  background:#edf7f1;
  color:#2d754e;
}

.at-trip > strong,
.at-trip > span{
  display:block;
  min-width:0;
  max-width:100%;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.at-trip > strong{
  margin-top:14px;
  color:#294638;
  font-size:14px;
  line-height:1.35;
  font-weight:900;
}

.at-trip > span{
  margin-top:5px;
  color:#74877e;
  font-size:11px;
  line-height:1.35;
}

.at-trip-meta{
  display:flex;
  justify-content:space-between;
  gap:10px;
  margin-top:13px;
  color:#63796d;
  font-size:10px;
}

.at-trip-route{
  min-width:0;
  display:grid;
  grid-template-columns:18px minmax(0,1fr) 18px minmax(0,1fr);
  gap:7px;
  align-items:center;
  margin-top:14px;
  padding-top:14px;
  border-top:1px dashed #d8e5de;
  color:#70837a;
  font-size:10px;
}

.at-trip-route span{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.at-trip-route svg:first-child{
  color:#307752;
}

.at-trip-actions{
  display:flex;
  align-items:center;
  flex-wrap:wrap;
  gap:9px;
  margin-top:15px;
}

.at-trip-actions a{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:6px;
  min-height:35px;
  padding:0 11px;
  border:1px solid #d1e3d8;
  border-radius:9px;
  background:#f4faf6;
  color:#2d704c;
  font-size:10px;
  font-weight:900;
  text-decoration:none;
}

.at-trip-actions a:hover{
  background:#eaf6ee;
}


/* ----------------------------------------------------------------
   14. EMPTY STATE
   ---------------------------------------------------------------- */

.at-empty{
  width:100%;
  min-height:280px;
  display:grid;
  place-items:center;
  align-content:center;
  gap:10px;
  padding:38px 24px;
  color:#70837a;
  text-align:center;
}

.at-empty svg{
  color:#407d59;
}

.at-empty strong{
  color:#3d5849;
  font-size:14px;
  font-weight:900;
}

.at-empty span{
  color:#81928a;
  font-size:11px;
}


/* =================================================================
   15. TRIP DETAILS MODAL
   ================================================================= */

.at-modal-backdrop{
  position:fixed;
  inset:0;
  width:100vw;
  height:100dvh;

  display:grid;
  place-items:center;

  padding:24px;

  overflow:hidden;
  overscroll-behavior:none;

  background:rgba(7,27,17,.60);

  backdrop-filter:blur(7px);
  -webkit-backdrop-filter:blur(7px);

  z-index:50000;

  touch-action:none;
}

.at-modal{
  position:relative;

  width:min(780px,100%);
  max-width:780px;

  max-height:calc(100dvh - 48px);
  min-height:0;

  overflow-x:hidden;
  overflow-y:auto;

  overscroll-behavior:contain;
  -webkit-overflow-scrolling:touch;
  touch-action:pan-y;

  padding:31px;

  border:1px solid #d3e3da;
  border-radius:21px;

  background:#ffffff;

  box-shadow:0 34px 105px rgba(2,21,12,.32);

  scrollbar-width:thin;
  scrollbar-color:#b5cbbd transparent;
}

.at-modal::-webkit-scrollbar{
  width:8px;
}

.at-modal::-webkit-scrollbar-track{
  background:transparent;
}

.at-modal::-webkit-scrollbar-thumb{
  border-radius:99px;
  background:#b5cbbd;
}

.at-modal-close{
  position:absolute;
  top:15px;
  right:15px;

  width:40px;
  height:40px;

  display:grid;
  place-items:center;

  border:1px solid #d6e3dc;
  border-radius:10px;

  background:#f3f7f4;
  color:#60766b;

  font-size:23px;
  line-height:1;

  cursor:pointer;
}

.at-modal-close:hover{
  background:#eaf5ee;
  color:#315d45;
}

.at-modal h2{
  margin:2px 52px 23px 0;
  color:#18382a;
  font-size:28px;
  line-height:1.2;
  letter-spacing:-.025em;
  font-weight:900;
}

.at-detail-grid{
  width:100%;
  min-width:0;
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:12px;
}

.at-detail-grid > div{
  min-width:0;
  overflow:hidden;
  padding:15px;
  border:1px solid #dce8e1;
  border-radius:12px;
  background:#fafcfb;
}

.at-detail-grid small,
.at-detail-grid strong{
  display:block;
  min-width:0;
  max-width:100%;
}

.at-detail-grid small{
  color:#82938b;
  font-size:9px;
  line-height:1.2;
  letter-spacing:.1em;
  font-weight:900;
  text-transform:uppercase;
}

.at-detail-grid strong{
  margin-top:6px;
  color:#355244;
  font-size:12px;
  line-height:1.55;
  overflow-wrap:anywhere;
  word-break:break-word;
}

.at-modal-footer{
  display:flex;
  flex-wrap:wrap;
  gap:10px;
  margin-top:21px;
  padding-top:18px;
  border-top:1px solid #e2ebe6;
}

.at-modal-btn{
  min-height:41px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  padding:0 15px;
  border:1px solid #cfe2d6;
  border-radius:10px;
  background:#eaf6ee;
  color:#2b704b;
  font-size:11px;
  font-weight:900;
  text-decoration:none;
}

.at-modal-btn:hover{
  background:#dff1e6;
}

.at-modal-btn.muted{
  border-color:#dfe7e2;
  background:#f5f8f6;
  color:#60766a;
}


/* =================================================================
   16. DESKTOP COMPRESSION — prevents cramped columns
   ================================================================= */

@media (max-width:1280px){

  .at-page{
    padding-left:28px;
    padding-right:28px;
  }

  .at-request{
    grid-template-columns:
      minmax(90px,.7fr)
      minmax(155px,1.15fr)
      minmax(115px,.8fr)
      minmax(175px,1.2fr)
      minmax(145px,1fr)
      minmax(135px,.85fr);

    gap:15px;
    padding-left:23px;
    padding-right:23px;
  }

  .at-request-main strong{
    font-size:15px;
  }
}


/* =================================================================
   17. TABLET
   ================================================================= */

@media (max-width:1050px){

  .at-stats{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }

  .at-header{
    align-items:flex-start;
    flex-direction:column;
  }

  .at-head-actions{
    justify-content:flex-start;
  }

  .at-toolbar{
    align-items:stretch;
    flex-direction:column;
  }

  .at-search-wrap{
    width:100%;
  }

  .at-request{
    grid-template-columns:
      minmax(85px,.65fr)
      minmax(145px,1.1fr)
      minmax(105px,.8fr)
      minmax(155px,1.1fr)
      minmax(130px,.95fr)
      minmax(125px,.85fr);

    gap:12px;
    padding-left:20px;
    padding-right:20px;
  }

  .at-active-grid{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
}


/* =================================================================
   18. TABLET CARD ROW
   ================================================================= */

@media (max-width:850px){

  .at-page{
    padding:24px 20px 45px;
  }

  .at-header h1{
    font-size:35px;
  }

  .at-request{
    grid-template-columns:
      minmax(145px,1fr)
      minmax(130px,1fr)
      minmax(130px,1fr);

    gap:17px 20px;
    padding:21px 20px;
  }

  .at-request-id{
    grid-column:1 / -1;
    padding-bottom:10px;
    border-bottom:1px dashed #dce8e1;
  }

  .at-request-main.wide{
    grid-column:1 / 3;
  }

  .at-request-side{
    grid-column:3;
    grid-row:2 / span 2;
  }

  .at-active-grid{
    grid-template-columns:1fr;
  }
}


/* =================================================================
   19. MOBILE
   ================================================================= */

@media (max-width:620px){

  .at-page{
    padding:19px 13px 36px;
  }

  .at-header{
    margin-bottom:22px;
  }

  .at-header h1{
    font-size:30px;
  }

  .at-header p{
    font-size:13px;
  }

  .at-head-actions{
    width:100%;
    justify-content:flex-start;
  }

  .at-refresh{
    min-height:42px;
  }

  .at-stats{
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:10px;
  }

  .at-stat{
    min-height:105px;
    gap:10px;
    padding:15px;
    border-radius:16px;
  }

  .at-stat-icon{
    width:42px;
    height:42px;
    flex-basis:42px;
  }

  .at-stat strong{
    font-size:26px;
  }

  .at-stat span{
    font-size:10px;
  }

  .at-systembar{
    min-height:auto;
    flex-wrap:wrap;
    align-items:flex-start;
    padding:12px 14px;
  }

  .at-systembar small{
    width:100%;
    margin-left:21px;
  }

  .at-toolbar{
    padding:19px 17px;
  }

  .at-toolbar h2{
    font-size:27px;
  }

  .at-filters{
    padding:12px 14px;
  }

  .at-request{
    grid-template-columns:1fr 1fr;
    gap:0 18px;
    padding:20px 17px;
  }

  .at-request-id{
    grid-column:1 / -1;
    margin-bottom:14px;
  }

  .at-request-main{
    margin-bottom:16px;
  }

  .at-request-main.wide{
    grid-column:1 / -1;
  }

  .at-request-main strong{
    font-size:14px;
  }

  .at-request-main span{
    font-size:10px;
  }

  .at-request-side{
    grid-column:1 / -1;
    grid-row:auto;
    flex-direction:row;
    align-items:center;
    justify-content:flex-start;
    padding-top:13px;
    border-top:1px dashed #dce8e1;
  }

  .at-request-side small{
    width:auto;
    margin-left:auto;
    text-align:right;
  }

  .at-modal-backdrop{
    padding:10px;
  }

  .at-modal{
    width:100%;
    max-width:none;
    max-height:calc(100dvh - 20px);
    padding:23px 19px;
    border-radius:17px;
  }

  .at-modal h2{
    font-size:25px;
  }

  .at-detail-grid{
    grid-template-columns:1fr;
  }

  .at-modal-footer{
    flex-direction:column;
  }

  .at-modal-btn{
    width:100%;
  }
}


/* =================================================================
   20. VERY SMALL PHONES
   ================================================================= */

@media (max-width:400px){

  .at-page{
    padding-left:10px;
    padding-right:10px;
  }

  .at-stats{
    grid-template-columns:1fr;
  }

  .at-header h1{
    font-size:27px;
  }

  .at-request{
    display:block;
  }

  .at-request-id{
    margin-bottom:15px;
  }

  .at-request-main{
    margin-bottom:15px;
  }

  .at-request-side{
    display:flex;
    margin-top:4px;
  }

  .at-request-side small{
    margin-left:auto;
  }
}


/* =================================================================
   21. SAFETY AGAINST GLOBAL CSS INTERFERENCE
   ================================================================= */

.at-page button,
.at-page input,
.at-page a{
  font-family:inherit;
}

.at-page img,
.at-page svg{
  max-width:100%;
}

.at-request,
.at-request:hover,
.at-request:focus,
.at-request:active{
  text-decoration:none;
}

@media (prefers-reduced-motion:reduce){

  .at-page *,
  .at-page *::before,
  .at-page *::after{
    animation:none !important;
    transition:none !important;
    scroll-behavior:auto !important;
  }
}




/* ================================================================
   KRISHISETU — TRANSPORTER LOGIN
   PREMIUM LOGIN PAGE
   ================================================================
   Paste at the VERY BOTTOM of src/index.css.

   Your current TransporterLogin JSX does not give the outer
   elements page-specific class names, so this stylesheet uses
   the stable structure of that page. It also supports the
   recommended class names below if you add them later:
     transporter-login-page
     transporter-login-wrapper
     transporter-login-brand-section
     transporter-login-card
   ================================================================ */


/* ----------------------------------------------------------------
   1. PAGE BACKGROUND
   ---------------------------------------------------------------- */

.transporter-login-page{
  min-height:100vh !important;
  position:relative !important;
  isolation:isolate !important;
  overflow:hidden !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  padding:32px 34px !important;

  color:#234056 !important;

  background:
    linear-gradient(
      135deg,
      rgba(248,252,253,.97) 0%,
      rgba(235,247,244,.94) 48%,
      rgba(238,248,252,.96) 100%
    ) !important;
}

/* Large soft background image / illustration. */
.transporter-login-page::before{
  content:"" !important;
  position:absolute !important;
  z-index:-2 !important;

  width:min(780px,58vw) !important;
  height:min(780px,58vw) !important;

  right:-170px !important;
  bottom:-230px !important;

  background:
    linear-gradient(
      rgba(245,251,249,.70),
      rgba(245,251,249,.70)
    ),
    url("./assets/hero.png") center/contain no-repeat !important;

  opacity:.22 !important;
  pointer-events:none !important;
  transform:rotate(-8deg) !important;
}

/* Soft glow behind the login card. */
.transporter-login-page::after{
  content:"" !important;
  position:absolute !important;
  z-index:-1 !important;

  width:520px !important;
  height:520px !important;

  right:7% !important;
  top:4% !important;

  border-radius:50% !important;

  background:
    radial-gradient(
      circle,
      rgba(34,151,193,.12) 0%,
      rgba(57,161,104,.08) 38%,
      transparent 72%
    ) !important;

  filter:blur(3px) !important;
  pointer-events:none !important;
}


/* ----------------------------------------------------------------
   2. MAIN TWO-COLUMN LAYOUT
   ---------------------------------------------------------------- */

.transporter-login-wrapper{
  width:min(1260px,100%) !important;
  min-width:0 !important;

  display:grid !important;
  grid-template-columns:minmax(0,1fr) minmax(470px,560px) !important;
  gap:76px !important;
  align-items:center !important;

  position:relative !important;
  z-index:1 !important;
}


/* ----------------------------------------------------------------
   3. LEFT BRAND / HERO
   ---------------------------------------------------------------- */

.transporter-login-brand-section{
  min-width:0 !important;
  padding:20px 0 !important;
}

.transporter-login-brand-section > button{
  display:inline-flex !important;
  align-items:center !important;
  gap:13px !important;

  padding:0 !important;
  border:0 !important;
  background:transparent !important;
  text-align:left !important;
}

.transporter-login-brand-section > button > div:first-child{
  width:54px !important;
  height:54px !important;
  flex:0 0 54px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border-radius:16px !important;

  /*
     Uses the REAL KrishiSetu logo from /src/assets.
     The current JSX has a "K" text here; hiding it and placing
     the asset here gives the requested real logo.
  */
  color:transparent !important;
  font-size:0 !important;

  background:
    rgba(255,255,255,.88)
    url("./assets/krishisetu-logo.png")
    center/72% 72%
    no-repeat !important;

  border:1px solid rgba(190,211,221,.85) !important;

  box-shadow:
    0 12px 30px rgba(21,77,99,.12),
    0 2px 7px rgba(21,77,99,.05) !important;
}

.transporter-login-brand-section > button > div:last-child{
  min-width:0 !important;
}

.transporter-login-brand-section > button > div:last-child > div:first-child{
  color:#173b52 !important;
  font-family:var(--font-heading,"Manrope",sans-serif) !important;
  font-size:22px !important;
  line-height:1.08 !important;
  font-weight:900 !important;
  letter-spacing:-.04em !important;
}

.transporter-login-brand-section > button > div:last-child > div:last-child{
  margin-top:4px !important;
  color:#718595 !important;
  font-size:11px !important;
  line-height:1.2 !important;
  font-weight:700 !important;
}


/* ----------------------------------------------------------------
   4. HERO COPY
   ---------------------------------------------------------------- */

.transporter-login-brand-section > div:last-child{
  max-width:650px !important;
  margin-top:90px !important;
}

.transporter-login-brand-section > div:last-child > div:first-child{
  display:inline-flex !important;
  align-items:center !important;
  gap:8px !important;

  min-height:32px !important;
  padding:0 11px !important;

  border:1px solid rgba(212,145,38,.25) !important;
  border-radius:999px !important;

  background:rgba(239,176,52,.09) !important;
  color:#b67109 !important;

  font-size:11px !important;
  line-height:1 !important;
  font-weight:900 !important;
  letter-spacing:.13em !important;
  text-transform:uppercase !important;
}

.transporter-login-brand-section > div:last-child > div:first-child > span{
  width:7px !important;
  height:7px !important;
  flex:0 0 7px !important;
  border-radius:50% !important;
  background:#d68b13 !important;
  box-shadow:0 0 0 4px rgba(214,139,19,.10) !important;
}

.transporter-login-brand-section h1{
  max-width:660px !important;

  margin:21px 0 18px !important;

  color:#163f59 !important;

  font-family:var(--font-heading,"Manrope",sans-serif) !important;
  font-size:clamp(52px,5.3vw,78px) !important;
  line-height:.98 !important;
  letter-spacing:-.065em !important;
  font-weight:900 !important;
}

.transporter-login-brand-section h1 span{
  color:#f97316 !important;
}

.transporter-login-brand-section > div:last-child > p{
  max-width:610px !important;

  margin:0 !important;

  color:#647f90 !important;
  font-size:16px !important;
  line-height:1.72 !important;
}


/* ----------------------------------------------------------------
