  min-height:100vh !important;
  width:100% !important;
  overflow-x:hidden !important;

  color:var(--tr-ink) !important;

  background:
    radial-gradient(
      circle at 8% 12%,
      rgba(51,166,102,.12),
      transparent 24%
    ),
    radial-gradient(
      circle at 92% 7%,
      rgba(26,141,198,.14),
      transparent 25%
    ),
    radial-gradient(
      circle at 70% 90%,
      rgba(234,161,40,.07),
      transparent 22%
    ),
    linear-gradient(
      145deg,
      #f7fbf9 0%,
      #f1f8fa 47%,
      #f7fbf8 100%
    ) !important;
}

/* Decorative hero image. Uses the project's existing asset. */
.transporter-register-page::before{
  content:"" !important;
  position:absolute !important;
  z-index:0 !important;

  width:min(780px,57vw) !important;
  height:min(780px,57vw) !important;

  right:-205px !important;
  top:60px !important;

  background:
    linear-gradient(
      135deg,
      rgba(247,251,249,.20),
      rgba(247,251,249,.76)
    ),
    url("./assets/hero.png")
      center/contain
      no-repeat !important;

  opacity:.20 !important;
  filter:saturate(.75) contrast(.96) !important;
  pointer-events:none !important;

  animation:tr-hero-float 12s ease-in-out infinite !important;
}

.transporter-register-page::after{
  content:"" !important;
  position:absolute !important;
  z-index:0 !important;

  width:520px !important;
  height:520px !important;

  left:-280px !important;
  bottom:-190px !important;

  border-radius:50% !important;

  background:
    radial-gradient(
      circle,
      rgba(28,145,98,.09),
      rgba(28,145,98,0) 68%
    ) !important;

  filter:blur(4px) !important;
  pointer-events:none !important;

  animation:tr-glow-float 14s ease-in-out infinite alternate !important;
}

@keyframes tr-hero-float{
  0%,100%{transform:translate3d(0,0,0) rotate(-2deg);}
  50%{transform:translate3d(-10px,12px,0) rotate(1deg);}
}

@keyframes tr-glow-float{
  from{transform:translate3d(0,0,0) scale(.96);}
  to{transform:translate3d(24px,-18px,0) scale(1.04);}
}


/* ========================================================================
   02. SHELL
   ======================================================================== */

.transporter-register-shell{
  position:relative !important;
  z-index:1 !important;

  width:min(1240px,calc(100% - 48px)) !important;
  max-width:1240px !important;
  margin:0 auto !important;

  padding:46px 0 60px !important;
}


/* ========================================================================
   03. HERO
   ======================================================================== */

.transporter-register-hero{
  position:relative !important;

  display:grid !important;
  grid-template-columns:auto minmax(0,1fr) auto !important;
  align-items:center !important;
  gap:20px !important;

  padding:27px 30px !important;

  border:1px solid rgba(200,222,230,.90) !important;
  border-radius:24px !important;

  background:
    linear-gradient(
      135deg,
      rgba(255,255,255,.94),
      rgba(249,253,254,.84)
