  overflow:hidden !important;
}

.transporter-register-hero::before{
  content:"" !important;
  position:absolute !important;
  inset:0 auto auto 0 !important;

  width:100% !important;
  height:4px !important;

  background:
    linear-gradient(
      90deg,
      #1487bb 0%,
      #32a05d 54%,
      #e4951c 100%
