  margin-bottom:8px !important;

  color:#bd750e !important;
  font-size:11px !important;
  line-height:1 !important;
  letter-spacing:.16em !important;
  font-weight:900 !important;
}

.transporter-register-hero h1{
  margin:0 !important;

  color:#173f56 !important;
  font-family:var(--font-heading,"Manrope",sans-serif) !important;

  font-size:clamp(28px,3vw,43px) !important;
  line-height:1.08 !important;
  letter-spacing:-.035em !important;
  font-weight:900 !important;
}

.transporter-register-hero p{
  max-width:710px !important;
  margin:9px 0 0 !important;

  color:#708693 !important;
  font-size:13px !important;
  line-height:1.6 !important;
}

.transporter-register-language-control{
  position:relative !important;
  z-index:2 !important;

  min-width:185px !important;

  display:grid !important;
  grid-template-columns:auto 1fr !important;
  align-items:center !important;
