}


/* ========================================================================
   04. STEP INDICATOR
   ======================================================================== */

.transporter-register-steps{
  position:relative !important;

  width:100% !important;

  display:grid !important;
  grid-template-columns:repeat(5,minmax(0,1fr)) !important;

  margin:22px 0 !important;
  padding:14px !important;

  border:1px solid #dbe8ed !important;
  border-radius:18px !important;

  background:rgba(255,255,255,.88) !important;

  box-shadow:0 10px 28px rgba(28,74,94,.055) !important;

  backdrop-filter:blur(14px) !important;
  -webkit-backdrop-filter:blur(14px) !important;
}

.transporter-register-step{
  position:relative !important;
  min-width:0 !important;

  display:grid !important;
  grid-template-columns:auto minmax(0,1fr) !important;
  align-items:center !important;
  gap:10px !important;

  padding:7px 13px !important;
}

.transporter-register-step-circle{
  width:35px !important;
  height:35px !important;
  flex:0 0 35px !important;

  display:grid !important;
  place-items:center !important;

  border:1px solid #cbdde5 !important;
  border-radius:50% !important;

  color:#6f8793 !important;
  background:#f6fafc !important;

  font-size:11px !important;
  font-weight:900 !important;

  transition:
    transform .25s ease,
    box-shadow .25s ease,
    background-color .25s ease,
    border-color .25s ease,
    color .25s ease !important;
}

.transporter-register-step-copy{
  min-width:0 !important;
}

.transporter-register-step-copy strong,
.transporter-register-step-copy span{
  display:block !important;
  min-width:0 !important;
  overflow:hidden !important;
  text-overflow:ellipsis !important;
  white-space:nowrap !important;
}

.transporter-register-step-copy strong{
  color:#496372 !important;
  font-size:10px !important;
  line-height:1.25 !important;
  font-weight:900 !important;
}

.transporter-register-step-copy span{
  margin-top:3px !important;
  color:#92a3ac !important;
  font-size:8px !important;
  line-height:1.2 !important;
}

.transporter-register-step-line{
  position:absolute !important;
  top:24px !important;
  right:-3px !important;

  width:calc(100% - 42px) !important;
  height:1px !important;

  background:#dce8ed !important;
  transform:translateX(50%) !important;
  pointer-events:none !important;
}

.transporter-register-step.active .transporter-register-step-circle{
  color:#ffffff !important;
  border-color:#147db7 !important;
  background:
    linear-gradient(145deg,#1b91c9,#126fa8) !important;

  box-shadow:
    0 7px 18px rgba(20,125,183,.20),
    0 0 0 5px rgba(20,125,183,.08) !important;

  transform:scale(1.07) !important;
}

.transporter-register-step.active .transporter-register-step-copy strong{
  color:#1675aa !important;
}

.transporter-register-step.completed .transporter-register-step-circle{
  color:#ffffff !important;
  border-color:#27945b !important;
  background:#27945b !important;
  box-shadow:0 6px 15px rgba(39,148,91,.16) !important;
}

.transporter-register-step.completed .transporter-register-step-copy strong{
  color:#27744b !important;
}

.transporter-register-step.completed .transporter-register-step-line{
  background:#b9dcc7 !important;
}


/* ========================================================================
   05. MAIN FORM CARD
   ======================================================================== */

.transporter-register-card{
  position:relative !important;

  width:100% !important;
  min-width:0 !important;

  padding:34px !important;

  border:1px solid #d5e4ea !important;
  border-radius:24px !important;

  background:
    linear-gradient(
      180deg,
      rgba(255,255,255,.98),
      rgba(251,253,254,.98)
    ) !important;

  box-shadow:var(--tr-shadow-lg) !important;

  overflow:hidden !important;
}

.transporter-register-card::before{
  content:"" !important;
  position:absolute !important;
  top:0 !important;
  left:0 !important;
  width:6px !important;
  height:100% !important;

  background:
    linear-gradient(
      180deg,
      #1689bd 0%,
      #31a05c 53%,
      #df9419 100%
    ) !important;
}


/* ========================================================================
   06. ALERTS
   ======================================================================== */

.transporter-register-alert{
  width:100% !important;

  display:flex !important;
  align-items:flex-start !important;
  gap:10px !important;

  margin:0 0 18px !important;
  padding:14px 16px !important;

  border-radius:13px !important;

  font-size:12px !important;
  line-height:1.55 !important;
  font-weight:750 !important;

  animation:tr-alert-in .35s ease both !important;
}

.transporter-register-alert.error{
  border:1px solid #efcfca !important;
  background:#fff5f3 !important;
  color:#93483f !important;
}

.transporter-register-alert.success{
  border:1px solid #c9e5d3 !important;
  background:#f0faf3 !important;
  color:#276f47 !important;
}

.transporter-register-alert svg{
  flex:0 0 auto !important;
  margin-top:1px !important;
}

@keyframes tr-alert-in{
  from{
    opacity:0;
    transform:translateY(-5px);
  }
  to{
    opacity:1;
    transform:translateY(0);
  }
}


/* ========================================================================
