/*
  KrishiSetu — Farmer Transport workspace
  CSS-only fix for FarmerTransport_Phase2 / ft-* markup.

  IMPORTANT:
  The original stylesheet had a class-name collision:
  .ft-status was used both for the full status card <section>
  and for the small status badge <div>. The later badge rule changed
  the entire status card into an inline-flex element.

  This stylesheet keeps the existing JSX class names and resolves the
  collision with .ft-card.ft-status and .ft-status:not(.ft-card).
*/

.farmer-transport-page,
.farmer-transport-page * {
  box-sizing: border-box;
}

.farmer-transport-page {
  min-height: 100vh;
  background:
    radial-gradient(circle at 8% 8%, rgba(64, 137, 89, .06), transparent 30%),
    radial-gradient(circle at 92% 12%, rgba(112, 161, 129, .05), transparent 27%),
    linear-gradient(180deg, #f7faf8 0%, #eef5f0 100%);
  color: #17372a;
  overflow-x: clip;
}

.farmer-transport-page button,
.farmer-transport-page input,
.farmer-transport-page select,
.farmer-transport-page textarea {
  font: inherit;
}

.ft-shell {
  width: min(1380px, calc(100% - 40px));
  margin: 0 auto;
  padding: 28px 0 64px;
}

.ft-center {
  min-height: calc(100vh - 100px);
  display: grid;
  place-items: center;
}

.ft-loading {
  width: min(620px, 100%);
  padding: 46px 34px;
  text-align: center;
  border: 1px solid #dbe7df;
  border-radius: 28px;
  background: rgba(255, 255, 255, .96);
  box-shadow: 0 24px 80px rgba(31, 76, 49, .09);
}

.ft-loading > svg {
  color: #2d7950;
  margin-bottom: 6px;
}

.ft-loading span,
.ft-eyebrow,
.ft-card-head > div > span,
.ft-sec-title > span,
.ft-side-head > div > span,
.ft-system > span,
.ft-match-head > div > small,
.ft-modal > span,
.ft-tracking-head small,
.ft-fare small,
.ft-rating small,
.ft-transporter small,
.ft-linked small {
  display: block;
  font-size: 10px;
  line-height: 1.2;
  font-weight: 900;
  letter-spacing: .15em;
  text-transform: uppercase;
  color: #638071;
}

.ft-loading h1,
.ft-head h1 {
  letter-spacing: -.045em;
}

.ft-loading p,
.ft-head p,
.ft-card-head p,
.ft-match-head p,
.ft-system p,
.ft-tracking-head p {
  color: #70837a;
  line-height: 1.6;
}

.ft-loading h1 {
  margin: 8px 0 0;
  font-size: 29px;
}

.ft-loading p {
  margin: 10px auto 0;
  max-width: 520px;
  font-size: 13px;
}

.ft-spin {
  animation: ft-spin .9s linear infinite;
}

@keyframes ft-spin {
  to { transform: rotate(360deg); }
}

/* ---------- Header ---------- */
.ft-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 26px;
  margin-bottom: 18px;
}

.ft-back {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 13px;
  color: #577368;
  text-decoration: none;
  font-size: 12px;
  font-weight: 850;
}

.ft-back:hover {
  color: #2c6847;
}

.ft-eyebrow {
  margin-bottom: 8px;
}

.ft-head h1 {
  margin: 0;
  max-width: 860px;
  color: #183b2d;
  font-size: clamp(34px, 4.3vw, 54px);
  line-height: .99;
}

.ft-head p {
  max-width: 820px;
  margin: 11px 0 0;
  font-size: 14px;
}

.ft-head-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}

.ft-online {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  padding: 0 12px;
  border: 1px solid #d5e4da;
  border-radius: 999px;
  background: #fff;
  color: #33704c;
  font-size: 11px;
  font-weight: 900;
  white-space: nowrap;
}

.ft-online i,
.ft-live i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #4da66a;
  box-shadow: 0 0 0 4px rgba(77, 166, 106, .10);
}

.ft-online.off {
  color: #93682f;
  border-color: #eadfc9;
  background: #fff9ef;
}

.ft-online.off i {
  background: #cc8b38;
  box-shadow: 0 0 0 4px rgba(204, 139, 56, .10);
}

/* ---------- Alerts ---------- */
.ft-alerts {
  display: grid;
  gap: 8px;
  margin: 0 0 16px;
}

.ft-alert {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 46px;
  padding: 10px 12px;
  border-radius: 13px;
  font-size: 12px;
  font-weight: 750;
}

.ft-alert span {
  min-width: 0;
  flex: 1;
}

.ft-alert button {
  width: 28px;
  height: 28px;
  margin-left: auto;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: inherit;
  cursor: pointer;
}

.ft-alert.err {
  color: #963f34;
  border: 1px solid #efc8c1;
  background: #fff2ef;
}

.ft-alert.inf {
  color: #28677a;
  border: 1px solid #cde2eb;
  background: #eff8fb;
}

.ft-alert.ok {
  color: #2c7449;
  border: 1px solid #cfe8d6;
  background: #eef9f1;
}

.ft-alert.draft {
  color: #8a632c;
  border: 1px solid #eadfc3;
  background: #fff9ec;
}

/* ---------- Feature row ---------- */
.ft-features {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 11px;
  margin-bottom: 16px;
}

.ft-features > div {
  min-width: 0;
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr);
  column-gap: 10px;
  row-gap: 2px;
  align-items: center;
  padding: 12px 14px;
  border: 1px solid #dfeae2;
  border-radius: 16px;
  background: rgba(255, 255, 255, .94);
  box-shadow: 0 9px 25px rgba(37, 78, 54, .045);
}

.ft-features svg {
  grid-row: 1 / span 2;
  width: 40px;
  height: 40px;
  padding: 9px;
  border-radius: 12px;
  background: #edf7f0;
  color: #2f7650;
}

.ft-features b {
  font-size: 12px;
  color: #2d493b;
}

.ft-features span {
  color: #788a82;
  font-size: 10px;
}

/* ---------- Main two-column workspace ---------- */
.ft-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 350px;
  gap: 18px;
  align-items: start;
}

.ft-grid > section,
.ft-grid > aside {
  min-width: 0;
}

.ft-grid > aside {
  display: grid;
  gap: 14px;
  align-self: start;
  position: sticky;
  top: 14px;
}

/* ---------- Tabs ---------- */
.ft-tabs {
  width: fit-content;
  max-width: 100%;
  display: inline-flex;
  gap: 3px;
  padding: 4px;
  margin-bottom: 11px;
  border: 1px solid #dce7e0;
  border-radius: 14px;
  background: rgba(230, 239, 233, .9);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.45);
}

.ft-tabs button,
.ft-toggle button {
  appearance: none;
  border: 0;
  background: transparent;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  cursor: pointer;
  color: #62766d;
  font-weight: 900;
}

.ft-tabs button {
  min-height: 40px;
  padding: 0 14px;
  border-radius: 10px;
  font-size: 11px;
  white-space: nowrap;
}

.ft-tabs button:hover {
  color: #2d6144;
}

.ft-tabs button.sel,
.ft-toggle button.sel {
  color: #1f5c3e;
  background: #fff;
  box-shadow: 0 5px 16px rgba(41, 76, 55, .09);
}

.ft-tabs em {
  min-width: 19px;
  height: 19px;
  padding: 0 5px;
  display: grid;
  place-items: center;
  border-radius: 99px;
  background: #dceee1;
  color: #34734d;
  font-size: 9px;
  font-style: normal;
}

/* ---------- Common cards ---------- */
.ft-card {
  background: #fff;
  border: 1px solid #dce8e1;
  border-radius: 22px;
  box-shadow: 0 18px 52px rgba(28, 67, 43, .055);
  overflow: hidden;
}

.ft-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 21px 24px 18px;
  border-bottom: 1px solid #e9efeb;
}

.ft-card-head h2 {
  margin: 6px 0 4px;
  color: #1e4332;
  font-size: 24px;
  line-height: 1.08;
  letter-spacing: -.025em;
}

.ft-card-head p {
  max-width: 720px;
  margin: 0;
  font-size: 11px;
}

.ft-card-head > svg {
  width: 39px;
  height: 39px;
  padding: 10px;
  flex: 0 0 auto;
  border-radius: 12px;
  color: #2f714d;
  background: #edf7f0;
}

/* ---------- Buttons ---------- */
.ft-btn,
.ft-primary,
.ft-light,
.ft-danger,
.ft-gps {
  appearance: none;
  text-decoration: none;
}

.ft-btn {
  min-height: 41px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 13px;
  border-radius: 10px;
  border: 1px solid transparent;
  font-size: 11px;
  font-weight: 900;
  cursor: pointer;
  transition: transform .15s ease, background .15s ease, border-color .15s ease, box-shadow .15s ease;
}

.ft-btn:not(:disabled):hover {
  transform: translateY(-1px);
}

.ft-btn:disabled {
  opacity: .53;
  cursor: default;
}

.ft-light {
  border-color: #d6e2da;
  background: #fff;
  color: #355547;
}

.ft-light:not(:disabled):hover {
  background: #f6faf7;
  border-color: #b9d0c0;
}

.ft-primary {
  border-color: #1e6945;
  background: #226e48;
  color: #fff;
  box-shadow: 0 9px 22px rgba(34, 110, 72, .14);
}

.ft-primary:not(:disabled):hover {
  background: #195d3c;
}

.ft-danger {
  border-color: #ebc5be;
  background: #fff2ef;
  color: #a04539;
}

.ft-danger:not(:disabled):hover {
  background: #ffebe7;
}

.ft-danger.strong {
  border-color: #a44337;
  background: #a44337;
  color: #fff;
}

/* ---------- Request form ---------- */
.ft-section {
  padding: 22px 24px;
  border-bottom: 1px solid #edf2ef;
}

.ft-section:last-of-type {
  border-bottom: 0;
}

.ft-sec-title {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 13px;
}

.ft-sec-title > b {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 10px;
  color: #2f704b;
  background: #edf6ef;
  font-size: 10px;
  font-weight: 950;
}

.ft-sec-title strong {
  display: block;
  color: #2c493a;
  font-size: 14px;
}

.ft-sec-title span {
  margin-top: 3px;
  color: #798b82;
  font-size: 10px;
  letter-spacing: normal;
  text-transform: none;
  font-weight: 600;
}

.ft-two {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 12px;
}

.ft-field {
  min-width: 0;
  display: grid;
  gap: 7px;
}

.ft-field > span {
  color: #60776b;
  font-size: 10px;
  font-weight: 900;
}

.ft-field input,
.ft-field select,
.ft-field textarea,
.ft-select select,
.ft-time input {
  width: 100%;
  min-width: 0;
  border: 1px solid #d3e0d8;
  border-radius: 11px;
  outline: 0;
  background: #fff;
  color: #274839;
  font-size: 12px;
}

.ft-field input,
.ft-field select {
  min-height: 45px;
  padding: 0 12px;
}

.ft-field textarea {
  min-height: 88px;
  padding: 11px 12px;
  resize: vertical;
  line-height: 1.45;
}

.ft-field input:focus,
.ft-field select:focus,
.ft-field textarea:focus,
.ft-time input:focus {
  border-color: #78a489;
  box-shadow: 0 0 0 4px rgba(69, 132, 91, .09);
}

.ft-picker {
  display: flex;
  align-items: center;
  gap: 8px;
}

.ft-select {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
}

.ft-select select {
  appearance: none;
  height: 45px;
  padding: 0 40px 0 12px;
}

.ft-select > svg {
  position: absolute;
  right: 12px;
  top: 14px;
  color: #7c8d84;
  pointer-events: none;
}

.ft-link,
.ft-link-btn {
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 0;
  border-radius: 10px;
  padding: 0 11px;
  background: #eef6f0;
  color: #2b6847;
  font-size: 11px;
  font-weight: 900;
  cursor: pointer;
  text-decoration: none;
}

.ft-link:hover,
.ft-link-btn:hover {
  background: #e5f1e8;
}

.ft-icon-input {
  position: relative;
}

.ft-icon-input > svg {
  position: absolute;
  left: 12px;
  top: 14px;
  color: #758980;
  pointer-events: none;
}

.ft-icon-input input,
.ft-icon-input select {
  padding-left: 38px;
}

.ft-suffix {
  position: relative;
}

.ft-suffix input {
  padding-right: 44px;
}

.ft-suffix b {
  position: absolute;
  right: 13px;
  top: 13px;
  color: #788980;
  font-size: 11px;
}

.ft-note {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 10px;
  padding: 10px 11px;
  border: 1px solid #e1ebe4;
  border-radius: 11px;
  background: #f8fbf9;
  color: #657970;
  font-size: 10px;
  line-height: 1.5;
}

.ft-destination {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 10px;
  padding: 11px;
  border: 1px solid #dfeae2;
  border-radius: 13px;
  background: #f8fbf9;
}

.ft-destination > svg {
  color: #2f724c;
  flex: 0 0 auto;
}

.ft-destination div {
  min-width: 0;
  flex: 1;
}

.ft-destination b,
.ft-destination span {
  display: block;
}

.ft-destination b {
  font-size: 11px;
}

.ft-destination span {
  margin-top: 2px;
  color: #778980;
  font-size: 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ft-destination button {
  border: 0;
  background: transparent;
  color: #2d6c48;
  font-size: 10px;
  font-weight: 900;
  cursor: pointer;
}

.ft-loc-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.ft-gps {
  min-height: 41px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 11px;
  border: 1px dashed #c8d9cf;
  border-radius: 10px;
  background: #fbfdfb;
  color: #70847a;
  font-size: 10px;
  font-weight: 850;
  cursor: pointer;
}

.ft-gps.ready {
  border-style: solid;
  border-color: #cce2d3;
  background: #eef8f1;
  color: #2d704a;
}

.ft-gps svg:last-child {
  margin-left: 3px;
}

.ft-gps-box {
  margin-top: 9px;
  padding: 12px;
  border: 1px solid #e1eae4;
  border-radius: 13px;
  background: #fbfdfb;
}

.ft-link-btn {
  min-height: auto;
  padding: 0;
  margin-top: 9px;
  background: transparent;
}

.ft-toggle {
  display: flex;
  gap: 4px;
  padding: 4px;
  margin-bottom: 12px;
  border-radius: 11px;
  background: #edf2ee;
}

.ft-toggle button {
  flex: 1;
  min-height: 39px;
  border-radius: 8px;
  font-size: 10px;
}

.ft-time {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  gap: 7px;
  align-items: center;
}

.ft-time label {
  position: relative;
  min-width: 0;
}

.ft-time label > svg {
  position: absolute;
  left: 10px;
  top: 14px;
  color: #7b8c83;
  pointer-events: none;
}

.ft-time input {
  min-height: 45px;
  padding: 0 9px 0 32px;
}

.ft-slots {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding: 1px 0 2px;
  margin-top: 9px;
  scrollbar-width: thin;
}

.ft-slots button {
  flex: 0 0 auto;
  min-height: 34px;
  padding: 0 10px;
  border: 1px solid #d5e2da;
  border-radius: 9px;
  background: #fff;
  color: #4b6559;
  font-size: 10px;
  font-weight: 800;
  cursor: pointer;
}

.ft-slots button.sel {
  border-color: #c2dacb;
  background: #eaf5ed;
  color: #27613f;
}

.ft-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 24px;
  background: #fbfdfb;
}

.ft-footer > span {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #778a81;
  font-size: 9px;
  font-weight: 800;
}

.ft-footer > div {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

/* ---------- STATUS VIEW: collision-safe rules ---------- */
/* The page-level status card must remain a normal block card. */
.ft-card.ft-status {
  display: block;
  padding-bottom: 22px;
}

/* The small status badge is the non-card .ft-status element. */
.ft-status:not(.ft-card) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: fit-content;
  min-height: 34px;
  padding: 8px 11px;
  border-radius: 999px;
  background: #edf6ef;
  color: #2e6d49;
  font-size: 10px;
  font-weight: 900;
  white-space: nowrap;
}

.ft-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding: 0 24px 16px;
}

.ft-id {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 32px;
  margin: 0 0 0 7px;
  padding: 0 9px;
  border: 1px solid #dce7e1;
  border-radius: 8px;
  background: #fafcfa;
  color: #63786d;
  font-size: 9px;
  font-weight: 900;
  cursor: pointer;
}

.ft-id:hover {
  border-color: #bdd4c5;
  background: #f4f9f5;
}

.ft-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px;
  margin-bottom: 0;
  background: #e8eee9;
}

.ft-summary > div {
  min-width: 0;
  padding: 13px;
  background: #fbfdfb;
}

.ft-summary small {
  display: block;
  margin-bottom: 5px;
  color: #87958d;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .1em;
  text-transform: uppercase;
}

.ft-summary b {
  display: block;
  color: #29483a;
  font-size: 11px;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.ft-schedule {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
  margin: 12px 24px 0;
  padding: 10px 11px;
  border: 1px solid #e1e9e4;
  border-radius: 11px;
  background: #f8fbf9;
  color: #4e6c5d;
  font-size: 10px;
}

/* ---------- Timeline ---------- */
.ft-timeline {
  position: relative;
  padding: 20px 24px 4px;
}

.ft-tline {
  position: relative;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 10px;
  min-height: 64px;
}

.ft-tline:not(:last-child)::before {
  content: "";
  position: absolute;
  left: 16px;
  top: 30px;
  bottom: 0;
  width: 2px;
  background: #dfe7e2;
}

.ft-ticon {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border: 3px solid #fff;
  border-radius: 50%;
  background: #edf2ee;
  color: #87988f;
  box-shadow: 0 0 0 1px #d8e2dc;
  z-index: 1;
}

.ft-tline.hit .ft-ticon {
  background: #dff0e4;
  color: #2f7650;
}

.ft-tline.current .ft-ticon {
  background: #1f6944;
  color: #fff;
  box-shadow: 0 0 0 4px rgba(31, 105, 68, .10);
}

.ft-tline.cancelled .ft-ticon {
  background: #fff0ed;
  color: #a3483a;
}

.ft-tline b {
  display: block;
  padding-top: 2px;
  color: #304b3e;
  font-size: 11px;
}

.ft-tline span {
  display: block;
  margin-top: 2px;
  color: #85958d;
  font-size: 9px;
}

.ft-tline small {
  display: block;
  margin-top: 4px;
  color: #63776c;
  font-size: 9px;
  line-height: 1.45;
}

/* ---------- Transporter + tracking ---------- */
.ft-transport-stack {
  display: grid;
  gap: 9px;
  margin: 4px 24px 16px;
}

.ft-transporter {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
  padding: 13px;
  margin: 0;
  border: 1px solid #d8e8dc;
  border-radius: 15px;
  background: #f6fbf7;
}

.ft-avatar,
.ft-person-icon {
  width: 43px;
  height: 43px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 13px;
  background: #e5f2e8;
  color: #2d6c48;
}

.ft-transporter > div:nth-child(2) {
  min-width: 0;
  flex: 1;
}

.ft-transporter h3 {
  margin: 4px 0 2px;
  color: #2a493a;
  font-size: 14px;
}

.ft-transporter p {
  margin: 0;
  color: #6f8278;
  font-size: 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ft-contacts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 7px;
}

.ft-contacts a,
.ft-contacts button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 0;
  padding: 0;
  background: transparent;
  color: #2e6b48;
  text-decoration: none;
  font-size: 9px;
  font-weight: 900;
  cursor: pointer;
}

.ft-live {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
  padding: 6px 8px;
  border: 1px solid #d8e8dc;
  border-radius: 999px;
  background: #fff;
  color: #2f6f4b;
  font-size: 9px;
  font-weight: 900;
}

.ft-live.offline {
  color: #855e54;
  border-color: #ecdcd6;
  background: #fff7f4;
}

.ft-live.offline i {
  background: #bd7563;
  box-shadow: 0 0 0 4px rgba(189, 117, 99, .09);
}

.ft-tracking-card,
.ft-fare,
.ft-rating,
.ft-matches,
.ft-report,
.ft-linked {
  border: 1px solid #e0eae4;
  background: #fbfdfb;
}

.ft-tracking-card {
  padding: 15px;
  border-radius: 17px;
}

.ft-tracking-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.ft-tracking-head h3 {
  margin: 5px 0 2px;
  color: #2d4a3c;
  font-size: 15px;
}

.ft-tracking-head p {
  max-width: 640px;
  margin: 0;
  font-size: 10px;
}

.ft-route {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 42px minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  margin: 18px 0 12px;
}

.ft-route-point {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.ft-route-point > span {
  width: 13px;
  height: 13px;
  margin-top: 2px;
  flex: 0 0 auto;
  border: 3px solid #fff;
  border-radius: 50%;
  box-shadow: 0 0 0 1px #b7ccc0;
}

.ft-route-point > span.farm {
  background: #2d7650;
}

.ft-route-point > span.center {
  background: #5d6f68;
}

.ft-route-point b,
.ft-route-point small {
  display: block;
}

.ft-route-point b {
  color: #2d493b;
  font-size: 10px;
}

.ft-route-point small {
  margin-top: 3px;
  color: #829189;
  font-size: 9px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.ft-route-line {
  position: relative;
  height: 2px;
  background: #cddbd2;
}

.ft-truck-pin {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  border: 1px solid #d0e2d6;
  border-radius: 10px;
  background: #e7f3eb;
  color: #2c6d49;
}

.ft-live-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  overflow: hidden;
  border: 1px solid #e4ece6;
  border-radius: 11px;
  background: #e4ece6;
}

.ft-live-stats > div {
  min-width: 0;
  padding: 9px;
  background: #fff;
}

.ft-live-stats small,
.ft-live-stats b {
  display: block;
}

.ft-live-stats small {
  color: #87958e;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .09em;
}

.ft-live-stats b {
  margin-top: 4px;
  color: #304c3e;
  font-size: 10px;
  overflow-wrap: anywhere;
}

.ft-fare {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr);
  gap: 12px;
  padding: 14px 15px;
  border-radius: 15px;
  background: #fff;
}

.ft-fare h3 {
  margin: 5px 0 2px;
  color: #1f4b38;
  font-size: 24px;
  letter-spacing: -.03em;
}

.ft-fare p {
  margin: 0;
  color: #7f8f88;
  font-size: 9px;
}

.ft-fare-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 7px;
  align-content: center;
  font-size: 10px;
}

.ft-fare-grid span {
  color: #83928b;
}

.ft-fare-grid b {
  color: #385447;
  text-align: right;
}

/* ---------- Smart matches ---------- */
.ft-linked {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 4px 24px 16px;
  padding: 12px;
  border-radius: 13px;
  background: #fff;
}

.ft-linked b {
  display: block;
  margin-top: 4px;
  color: #304d3f;
  font-size: 11px;
  overflow-wrap: anywhere;
}

.ft-matches {
  margin: 0 24px;
  padding: 15px;
  border-radius: 16px;
  background: #fbfdfb;
}

.ft-match-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.ft-match-head h3 {
  margin: 5px 0 2px;
  color: #2f4c3d;
  font-size: 15px;
}

.ft-match-head p {
  margin: 0;
  font-size: 10px;
}

.ft-match-list {
  display: grid;
  gap: 6px;
  margin-top: 11px;
}

.ft-match {
  min-width: 0;
  display: grid;
  grid-template-columns: 25px 30px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 8px;
  padding: 9px;
  border: 1px solid #e5ece7;
  border-radius: 11px;
  background: #fff;
}

.ft-match > svg {
  color: #2d6c48;
}

.ft-match > div:nth-child(3) {
  min-width: 0;
}

.ft-match strong,
.ft-match span {
  display: block;
}

.ft-match strong {
  color: #304c3e;
  font-size: 10px;
}

.ft-match span {
  margin-top: 2px;
  color: #778980;
  font-size: 9px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ft-match em {
  color: #425e50;
  font-size: 10px;
  font-style: normal;
  font-weight: 900;
  white-space: nowrap;
}

.ft-no-match {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  margin-top: 9px;
  padding: 11px;
  border-radius: 10px;
  background: #f7faf7;
  color: #677b71;
  font-size: 10px;
  line-height: 1.5;
}

/* ---------- Empty + history ---------- */
.ft-empty {
  min-height: 290px;
  display: grid;
  place-items: center;
  align-content: center;
  padding: 58px 24px;
  text-align: center;
}

.ft-empty.small {
  min-height: 200px;
  padding: 40px 24px;
}

.ft-empty svg {
  color: #3a7755;
}

.ft-empty h2 {
  margin: 8px 0 0;
  color: #315243;
  font-size: 20px;
}

.ft-empty p {
  max-width: 460px;
  margin: 8px 0 17px;
  color: #74857c;
  font-size: 11px;
  line-height: 1.55;
}

.ft-history {
  display: grid;
  gap: 7px;
  padding: 10px 18px 22px;
}

.ft-history button {
  width: 100%;
  display: grid;
  grid-template-columns: 9px minmax(0, 1fr) auto 16px;
  align-items: center;
  gap: 10px;
  padding: 12px;
  border: 1px solid #e2eae5;
  border-radius: 12px;
  background: #fff;
  text-align: left;
  cursor: pointer;
}

.ft-history button:hover {
  border-color: #c7dbcd;
  background: #fbfefc;
}

.ft-history .dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #788b82;
}

.ft-history .dot.status-completed {
  background: #50a06d;
}

.ft-history .dot.status-cancelled {
  background: #bc5c4e;
}

.ft-history b,
.ft-history span {
  display: block;
}

.ft-history b {
  color: #304c3e;
  font-size: 10px;
}

.ft-history span {
  margin-top: 3px;
  color: #7c8d85;
  font-size: 9px;
  overflow-wrap: anywhere;
}

/* ---------- Right rail ---------- */
.ft-side {
  padding: 17px;
}

.ft-side-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.ft-side-head h2 {
  margin: 5px 0 0;
  color: #234636;
  font-size: 20px;
  letter-spacing: -.02em;
}

.ft-side-head em {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 9px;
  background: #eaf4ed;
  color: #2d6e4a;
  font-size: 10px;
  font-style: normal;
  font-weight: 900;
}

.ft-active-list {
  display: grid;
  gap: 7px;
  margin-top: 12px;
}

.ft-active-list button {
  width: 100%;
  padding: 11px;
  border: 1px solid #e1e9e4;
  border-radius: 12px;
  background: #fff;
  text-align: left;
  cursor: pointer;
  transition: border-color .15s ease, box-shadow .15s ease, transform .15s ease;
}

.ft-active-list button:hover {
  transform: translateY(-1px);
  border-color: #c7dccd;
}

.ft-active-list button.sel {
  border-color: #9fc9ab;
  box-shadow: 0 0 0 3px rgba(66, 132, 85, .08);
}

.ft-active-list button > span {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 0 7px;
  border-radius: 999px;
  background: #edf5ef;
  color: #2e6e49;
  font-size: 8px;
  font-weight: 900;
}

.ft-active-list button > b {
  display: block;
  margin-top: 7px;
  color: #304c3e;
  font-size: 11px;
}

.ft-active-list button > small,
.ft-active-list button > i {
  display: block;
  margin-top: 3px;
  color: #798b83;
  font-size: 9px;
  font-style: normal;
  overflow-wrap: anywhere;
}

.ft-side-empty {
  display: grid;
  gap: 5px;
  margin-top: 12px;
  padding: 16px;
  border: 1px solid #e5ece7;
  border-radius: 12px;
  background: #e2f4e5;
  color: #71847a;
}

.ft-side-empty b {
  color: #365243;
  font-size: 10px;
}

.ft-side-empty span {
  font-size: 9px;
  line-height: 1.45;
}

.ft-system {
  padding: 19px;
}

.ft-system > svg {
  width: 43px;
  height: 43px;
  padding: 10px;
  margin-bottom: 8px;
  border-radius: 13px;
  background: #edf6f0;
  color: #2d6f4a;
}

.ft-system h2 {
  margin: 6px 0;
  color: #2d4c3d;
  font-size: 18px;
  line-height: 1.15;
}

.ft-system p {
  margin: 0;
  font-size: 10px;
}

.ft-system > div {
  display: grid;
  gap: 7px;
  margin-top: 13px;
}

.ft-system b {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #527063;
  font-size: 9px;
}

.ft-system b svg {
  color: #4c9966;
}

/* ---------- Rating / report ---------- */
.ft-rating {
  display: grid;
  gap: 10px;
  padding: 15px;
  border-radius: 15px;
  background: #fff;
}

.ft-rating h3 {
  margin: 4px 0 0;
  color: #304d3f;
  font-size: 15px;
}

.ft-stars {
  display: flex;
  gap: 3px;
}

.ft-stars button {
  border: 0;
  padding: 4px;
  background: transparent;
  color: #abbab2;
  cursor: pointer;
}

.ft-stars button.sel {
  color: #d2a43b;
}

.ft-rating textarea {
  width: 100%;
  min-height: 70px;
  border: 1px solid #d8e3dc;
  border-radius: 11px;
  padding: 10px;
  resize: vertical;
  outline: 0;
  font-size: 10px;
}

.ft-rating textarea:focus {
  border-color: #78a489;
  box-shadow: 0 0 0 4px rgba(69, 132, 91, .09);
}

.ft-rating-done {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  color: #2d704b;
}

.ft-rating-done b,
.ft-rating-done span {
  display: block;
}

.ft-rating-done b {
  font-size: 11px;
}

.ft-rating-done span {
  margin-top: 3px;
  color: #75867e;
  font-size: 9px;
  line-height: 1.45;
}

.ft-report {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 13px;
  border-color: #eadfd9;
  border-radius: 13px;
  background: #fffaf8;
  color: #805c51;
}

.ft-report > div {
  min-width: 0;
  flex: 1;
}

.ft-report b,
.ft-report span {
  display: block;
}

.ft-report b {
  color: #574039;
  font-size: 10px;
}

.ft-report span {
  margin-top: 3px;
  color: #7c6b64;
  font-size: 9px;
  line-height: 1.45;
}

.ft-report a {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  flex: 0 0 auto;
  color: #7d4a3d;
  text-decoration: none;
  font-size: 9px;
  font-weight: 900;
}

/* ---------- Modals ---------- */
.ft-modal-bg {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  padding: 18px;
  background: rgba(12, 31, 21, .46);
  backdrop-filter: blur(5px);
}

.ft-modal {
  width: min(500px, 100%);
  max-height: min(90vh, 760px);
  overflow: auto;
  padding: 23px;
  border: 1px solid #dbe6df;
  border-radius: 22px;
  background: #fff;
  box-shadow: 0 30px 100px rgba(9, 25, 16, .24);
}

.ft-modal-icon {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  margin-bottom: 10px;
  border-radius: 14px;
  background: #fff0ed;
  color: #a54739;
}

.ft-modal h2 {
  margin: 6px 0;
  color: #2d4a3c;
  font-size: 22px;
}

.ft-modal p {
  color: #6d8176;
  font-size: 11px;
  line-height: 1.55;
}

.ft-modal .ft-field {
  margin-top: 10px;
}

.ft-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 15px;
}

/* ---------- Responsive ---------- */
@media (max-width: 1120px) {
  .ft-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .ft-grid > aside {
    position: static;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 860px) {
  .ft-shell {
    width: min(100% - 28px, 760px);
    padding-top: 22px;
  }

  .ft-head {
    flex-direction: column;
    align-items: flex-start;
  }

  .ft-head-actions {
    width: 100%;
    justify-content: flex-start;
  }

  .ft-features {
    grid-template-columns: 1fr;
  }

  .ft-grid > aside {
    grid-template-columns: 1fr;
  }

  .ft-two,
  .ft-summary {
    grid-template-columns: 1fr;
  }

  .ft-picker {
    align-items: stretch;
    flex-direction: column;
  }

  .ft-picker .ft-link {
    width: 100%;
  }

  .ft-footer {
    align-items: stretch;
    flex-direction: column;
  }

  .ft-footer > div {
    width: 100%;
  }

  .ft-footer > div > * {
    flex: 1 1 0;
  }

  .ft-actions {
    padding-left: 20px;
    padding-right: 20px;
  }

  .ft-card-head,
  .ft-section {
    padding-left: 20px;
    padding-right: 20px;
  }

  .ft-schedule,
  .ft-linked,
  .ft-transport-stack,
  .ft-matches {
    margin-left: 20px;
    margin-right: 20px;
  }

  .ft-timeline {
    padding-left: 20px;
    padding-right: 20px;
  }
}

@media (max-width: 620px) {
  .ft-shell {
    width: min(100% - 18px, 600px);
    padding-top: 16px;
    padding-bottom: 42px;
  }

  .ft-head h1 {
    font-size: 34px;
  }

  .ft-head p {
    font-size: 12px;
  }

  .ft-tabs {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .ft-tabs button {
    min-width: 0;
    padding: 0 6px;
    font-size: 9px;
  }

  .ft-tabs button svg {
    width: 14px;
    height: 14px;
  }

  .ft-card,
  .ft-loading {
    border-radius: 18px;
  }

  .ft-card-head {
    flex-direction: column;
    gap: 11px;
  }

  .ft-card-head > svg {
    width: 35px;
    height: 35px;
    padding: 9px;
  }

  .ft-card-head h2 {
    font-size: 21px;
  }

  .ft-actions {
    align-items: stretch;
  }

  .ft-actions > * {
    flex: 1 1 calc(50% - 4px);
  }

  .ft-actions .ft-id {
    flex: 1 1 100%;
    width: fit-content;
    justify-self: flex-start;
  }

  .ft-route {
    grid-template-columns: minmax(0, 1fr) 28px minmax(0, 1fr);
  }

  .ft-fare {
    grid-template-columns: 1fr;
  }

  .ft-live-stats {
    grid-template-columns: 1fr;
  }

  .ft-tracking-head {
    flex-direction: column;
  }

  .ft-tracking-head .ft-btn {
    width: 100%;
  }

  .ft-match {
    grid-template-columns: 23px 28px minmax(0, 1fr);
  }

  .ft-match > div:nth-child(4),
  .ft-match > em {
    grid-column: 3;
    text-align: left;
  }

  .ft-transporter {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .ft-live {
    margin-left: auto;
  }

  .ft-loc-actions,
  .ft-loc-actions > * {
    width: 100%;
  }

  .ft-loc-actions > * {
    justify-content: center;
  }

  .ft-modal-actions {
    flex-direction: column;
  }

  .ft-modal-actions > * {
    width: 100%;
  }
}

@media (max-width: 420px) {
  .ft-shell {
    width: calc(100% - 12px);
  }

  .ft-head h1 {
    font-size: 30px;
  }

  .ft-online,
  .ft-head-actions .ft-btn {
    width: 100%;
  }

  .ft-head-actions {
    display: grid;
    grid-template-columns: 1fr;
    width: 100%;
  }

  .ft-tabs button {
    font-size: 8px;
  }

  .ft-section,
  .ft-card-head {
    padding-left: 16px;
    padding-right: 16px;
  }

  .ft-actions,
  .ft-timeline {
    padding-left: 16px;
    padding-right: 16px;
  }

  .ft-schedule,
  .ft-linked,
  .ft-transport-stack,
  .ft-matches {
    margin-left: 16px;
    margin-right: 16px;
  }
}
/*
  KrishiSetu — Farmer Transport workspace
  CSS-only fix for FarmerTransport_Phase2 / ft-* markup.

  IMPORTANT:
  The original stylesheet had a class-name collision:
  .ft-status was used both for the full status card <section>
  and for the small status badge <div>. The later badge rule changed
  the entire status card into an inline-flex element.

  This stylesheet keeps the existing JSX class names and resolves the
  collision with .ft-card.ft-status and .ft-status:not(.ft-card).
*/

.farmer-transport-page,
.farmer-transport-page * {
  box-sizing: border-box;
}

.farmer-transport-page {
  min-height: 100vh;
  background:
    radial-gradient(circle at 8% 8%, rgba(64, 137, 89, .06), transparent 30%),
    radial-gradient(circle at 92% 12%, rgba(112, 161, 129, .05), transparent 27%),
    linear-gradient(180deg, #f7faf8 0%, #eef5f0 100%);
  color: #17372a;
  overflow-x: clip;
}

.farmer-transport-page button,
.farmer-transport-page input,
.farmer-transport-page select,
.farmer-transport-page textarea {
  font: inherit;
}

.ft-shell {
  width: min(1380px, calc(100% - 40px));
  margin: 0 auto;
  padding: 28px 0 64px;
}

.ft-center {
  min-height: calc(100vh - 100px);
  display: grid;
  place-items: center;
}

.ft-loading {
  width: min(620px, 100%);
  padding: 46px 34px;
  text-align: center;
  border: 1px solid #dbe7df;
  border-radius: 28px;
  background: rgba(255, 255, 255, .96);
  box-shadow: 0 24px 80px rgba(31, 76, 49, .09);
}

.ft-loading > svg {
  color: #2d7950;
  margin-bottom: 6px;
}

.ft-loading span,
.ft-eyebrow,
.ft-card-head > div > span,
.ft-sec-title > span,
.ft-side-head > div > span,
.ft-system > span,
.ft-match-head > div > small,
.ft-modal > span,
.ft-tracking-head small,
.ft-fare small,
.ft-rating small,
.ft-transporter small,
.ft-linked small {
  display: block;
  font-size: 10px;
  line-height: 1.2;
  font-weight: 900;
  letter-spacing: .15em;
  text-transform: uppercase;
  color: #638071;
}

.ft-loading h1,
.ft-head h1 {
  letter-spacing: -.045em;
}

.ft-loading p,
.ft-head p,
.ft-card-head p,
.ft-match-head p,
.ft-system p,
.ft-tracking-head p {
  color: #70837a;
  line-height: 1.6;
}

.ft-loading h1 {
  margin: 8px 0 0;
  font-size: 29px;
}

.ft-loading p {
  margin: 10px auto 0;
  max-width: 520px;
  font-size: 13px;
}

.ft-spin {
  animation: ft-spin .9s linear infinite;
}

@keyframes ft-spin {
  to { transform: rotate(360deg); }
}

/* ---------- Header ---------- */
.ft-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 26px;
  margin-bottom: 18px;
}

.ft-back {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 13px;
  color: #577368;
  text-decoration: none;
  font-size: 12px;
  font-weight: 850;
}

.ft-back:hover {
  color: #2c6847;
}

.ft-eyebrow {
  margin-bottom: 8px;
}

.ft-head h1 {
  margin: 0;
  max-width: 860px;
  color: #183b2d;
  font-size: clamp(34px, 4.3vw, 54px);
  line-height: .99;
}

.ft-head p {
  max-width: 820px;
  margin: 11px 0 0;
  font-size: 14px;
}

.ft-head-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}

.ft-online {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  padding: 0 12px;
  border: 1px solid #d5e4da;
  border-radius: 999px;
  background: #fff;
  color: #33704c;
  font-size: 11px;
  font-weight: 900;
  white-space: nowrap;
}

.ft-online i,
.ft-live i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #4da66a;
  box-shadow: 0 0 0 4px rgba(77, 166, 106, .10);
}

.ft-online.off {
  color: #93682f;
  border-color: #eadfc9;
  background: #fff9ef;
}

.ft-online.off i {
  background: #cc8b38;
  box-shadow: 0 0 0 4px rgba(204, 139, 56, .10);
}

/* ---------- Alerts ---------- */
.ft-alerts {
  display: grid;
  gap: 8px;
  margin: 0 0 16px;
}

.ft-alert {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 46px;
  padding: 10px 12px;
  border-radius: 13px;
  font-size: 12px;
  font-weight: 750;
}

.ft-alert span {
  min-width: 0;
  flex: 1;
}

.ft-alert button {
  width: 28px;
  height: 28px;
  margin-left: auto;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: inherit;
  cursor: pointer;
}

.ft-alert.err {
  color: #963f34;
  border: 1px solid #efc8c1;
  background: #fff2ef;
}

.ft-alert.inf {
  color: #28677a;
  border: 1px solid #cde2eb;
  background: #eff8fb;
}

.ft-alert.ok {
  color: #2c7449;
  border: 1px solid #cfe8d6;
  background: #eef9f1;
}

.ft-alert.draft {
  color: #8a632c;
  border: 1px solid #eadfc3;
  background: #fff9ec;
}

/* ---------- Feature row ---------- */
.ft-features {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 11px;
  margin-bottom: 16px;
}

.ft-features > div {
  min-width: 0;
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr);
  column-gap: 10px;
  row-gap: 2px;
  align-items: center;
  padding: 12px 14px;
  border: 1px solid #dfeae2;
  border-radius: 16px;
  background: rgba(255, 255, 255, .94);
  box-shadow: 0 9px 25px rgba(37, 78, 54, .045);
}

.ft-features svg {
  grid-row: 1 / span 2;
  width: 40px;
  height: 40px;
  padding: 9px;
  border-radius: 12px;
  background: #edf7f0;
  color: #2f7650;
}

.ft-features b {
  font-size: 12px;
  color: #2d493b;
}

.ft-features span {
  color: #788a82;
  font-size: 10px;
}

/* ---------- Main two-column workspace ---------- */
.ft-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 350px;
  gap: 18px;
  align-items: start;
}

.ft-grid > section,
.ft-grid > aside {
  min-width: 0;
}

.ft-grid > aside {
  display: grid;
  gap: 14px;
  align-self: start;
  position: sticky;
  top: 14px;
}

/* ---------- Tabs ---------- */
.ft-tabs {
  width: fit-content;
  max-width: 100%;
  display: inline-flex;
  gap: 3px;
  padding: 4px;
  margin-bottom: 11px;
  border: 1px solid #dce7e0;
  border-radius: 14px;
  background: rgba(230, 239, 233, .9);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.45);
}

.ft-tabs button,
.ft-toggle button {
  appearance: none;
  border: 0;
  background: transparent;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  cursor: pointer;
  color: #62766d;
  font-weight: 900;
}

.ft-tabs button {
  min-height: 40px;
  padding: 0 14px;
  border-radius: 10px;
  font-size: 11px;
  white-space: nowrap;
}

.ft-tabs button:hover {
  color: #2d6144;
}

.ft-tabs button.sel,
.ft-toggle button.sel {
  color: #1f5c3e;
  background: #fff;
  box-shadow: 0 5px 16px rgba(41, 76, 55, .09);
}

.ft-tabs em {
  min-width: 19px;
  height: 19px;
  padding: 0 5px;
  display: grid;
  place-items: center;
  border-radius: 99px;
  background: #dceee1;
  color: #34734d;
  font-size: 9px;
  font-style: normal;
}

/* ---------- Common cards ---------- */
.ft-card {
  background: #fff;
  border: 1px solid #dce8e1;
  border-radius: 22px;
  box-shadow: 0 18px 52px rgba(28, 67, 43, .055);
  overflow: hidden;
}

.ft-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 21px 24px 18px;
  border-bottom: 1px solid #e9efeb;
}

.ft-card-head h2 {
  margin: 6px 0 4px;
  color: #1e4332;
  font-size: 24px;
  line-height: 1.08;
  letter-spacing: -.025em;
}

.ft-card-head p {
  max-width: 720px;
  margin: 0;
  font-size: 11px;
}

.ft-card-head > svg {
  width: 39px;
  height: 39px;
  padding: 10px;
  flex: 0 0 auto;
  border-radius: 12px;
  color: #2f714d;
  background: #edf7f0;
}

/* ---------- Buttons ---------- */
.ft-btn,
.ft-primary,
.ft-light,
.ft-danger,
.ft-gps {
  appearance: none;
  text-decoration: none;
}

.ft-btn {
  min-height: 41px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 13px;
  border-radius: 10px;
  border: 1px solid transparent;
  font-size: 11px;
  font-weight: 900;
  cursor: pointer;
  transition: transform .15s ease, background .15s ease, border-color .15s ease, box-shadow .15s ease;
}

.ft-btn:not(:disabled):hover {
  transform: translateY(-1px);
}

.ft-btn:disabled {
  opacity: .53;
  cursor: default;
}

.ft-light {
  border-color: #d6e2da;
  background: #fff;
  color: #355547;
}

.ft-light:not(:disabled):hover {
  background: #f6faf7;
  border-color: #b9d0c0;
}

.ft-primary {
  border-color: #1e6945;
  background: #226e48;
  color: #fff;
  box-shadow: 0 9px 22px rgba(34, 110, 72, .14);
}

.ft-primary:not(:disabled):hover {
  background: #195d3c;
}

.ft-danger {
  border-color: #ebc5be;
  background: #fff2ef;
  color: #a04539;
}

.ft-danger:not(:disabled):hover {
  background: #ffebe7;
}

.ft-danger.strong {
  border-color: #a44337;
  background: #a44337;
  color: #fff;
}

/* ---------- Request form ---------- */
.ft-section {
  padding: 22px 24px;
  border-bottom: 1px solid #edf2ef;
}

.ft-section:last-of-type {
  border-bottom: 0;
}

.ft-sec-title {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 13px;
}

.ft-sec-title > b {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 10px;
  color: #2f704b;
  background: #edf6ef;
  font-size: 10px;
  font-weight: 950;
}

.ft-sec-title strong {
  display: block;
  color: #2c493a;
  font-size: 14px;
}

.ft-sec-title span {
  margin-top: 3px;
  color: #798b82;
  font-size: 10px;
  letter-spacing: normal;
  text-transform: none;
  font-weight: 600;
}

.ft-two {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 12px;
}

.ft-field {
  min-width: 0;
  display: grid;
  gap: 7px;
}

.ft-field > span {
  color: #60776b;
  font-size: 10px;
  font-weight: 900;
}

.ft-field input,
.ft-field select,
.ft-field textarea,
.ft-select select,
.ft-time input {
  width: 100%;
  min-width: 0;
  border: 1px solid #d3e0d8;
  border-radius: 11px;
  outline: 0;
  background: #fff;
  color: #274839;
  font-size: 12px;
}

.ft-field input,
.ft-field select {
  min-height: 45px;
  padding: 0 12px;
}

.ft-field textarea {
  min-height: 88px;
  padding: 11px 12px;
  resize: vertical;
  line-height: 1.45;
}

.ft-field input:focus,
.ft-field select:focus,
.ft-field textarea:focus,
.ft-time input:focus {
  border-color: #78a489;
  box-shadow: 0 0 0 4px rgba(69, 132, 91, .09);
}

.ft-picker {
  display: flex;
  align-items: center;
  gap: 8px;
}

.ft-select {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
}

.ft-select select {
  appearance: none;
  height: 45px;
  padding: 0 40px 0 12px;
}

.ft-select > svg {
  position: absolute;
  right: 12px;
  top: 14px;
  color: #7c8d84;
  pointer-events: none;
}

.ft-link,
.ft-link-btn {
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 0;
  border-radius: 10px;
  padding: 0 11px;
  background: #eef6f0;
  color: #2b6847;
  font-size: 11px;
  font-weight: 900;
  cursor: pointer;
  text-decoration: none;
}

.ft-link:hover,
.ft-link-btn:hover {
  background: #e5f1e8;
}

.ft-icon-input {
  position: relative;
}

.ft-icon-input > svg {
  position: absolute;
  left: 12px;
  top: 14px;
  color: #758980;
  pointer-events: none;
}

.ft-icon-input input,
.ft-icon-input select {
  padding-left: 38px;
}

.ft-suffix {
  position: relative;
}

.ft-suffix input {
  padding-right: 44px;
}

.ft-suffix b {
  position: absolute;
  right: 13px;
  top: 13px;
  color: #788980;
  font-size: 11px;
}

.ft-note {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 10px;
  padding: 10px 11px;
  border: 1px solid #e1ebe4;
  border-radius: 11px;
  background: #f8fbf9;
  color: #657970;
  font-size: 10px;
  line-height: 1.5;
}

.ft-destination {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 10px;
  padding: 11px;
  border: 1px solid #dfeae2;
  border-radius: 13px;
  background: #f8fbf9;
}

.ft-destination > svg {
  color: #2f724c;
  flex: 0 0 auto;
}

.ft-destination div {
  min-width: 0;
  flex: 1;
}

.ft-destination b,
.ft-destination span {
  display: block;
}

.ft-destination b {
  font-size: 11px;
}

.ft-destination span {
  margin-top: 2px;
  color: #778980;
  font-size: 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ft-destination button {
  border: 0;
  background: transparent;
  color: #2d6c48;
  font-size: 10px;
  font-weight: 900;
  cursor: pointer;
}

.ft-loc-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.ft-gps {
  min-height: 41px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 11px;
  border: 1px dashed #c8d9cf;
  border-radius: 10px;
  background: #fbfdfb;
  color: #70847a;
  font-size: 10px;
  font-weight: 850;
  cursor: pointer;
}

.ft-gps.ready {
  border-style: solid;
  border-color: #cce2d3;
  background: #eef8f1;
  color: #2d704a;
}

.ft-gps svg:last-child {
  margin-left: 3px;
}

.ft-gps-box {
  margin-top: 9px;
  padding: 12px;
  border: 1px solid #e1eae4;
  border-radius: 13px;
  background: #fbfdfb;
}

.ft-link-btn {
  min-height: auto;
  padding: 0;
  margin-top: 9px;
  background: transparent;
}

.ft-toggle {
  display: flex;
  gap: 4px;
  padding: 4px;
  margin-bottom: 12px;
  border-radius: 11px;
  background: #edf2ee;
}

.ft-toggle button {
  flex: 1;
  min-height: 39px;
  border-radius: 8px;
  font-size: 10px;
}

.ft-time {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  gap: 7px;
  align-items: center;
}

.ft-time label {
  position: relative;
  min-width: 0;
}

.ft-time label > svg {
  position: absolute;
  left: 10px;
  top: 14px;
  color: #7b8c83;
  pointer-events: none;
}

.ft-time input {
  min-height: 45px;
  padding: 0 9px 0 32px;
}

.ft-slots {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding: 1px 0 2px;
  margin-top: 9px;
  scrollbar-width: thin;
}

.ft-slots button {
  flex: 0 0 auto;
  min-height: 34px;
  padding: 0 10px;
  border: 1px solid #d5e2da;
  border-radius: 9px;
  background: #fff;
  color: #4b6559;
  font-size: 10px;
  font-weight: 800;
  cursor: pointer;
}

.ft-slots button.sel {
  border-color: #c2dacb;
  background: #eaf5ed;
  color: #27613f;
}

.ft-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 24px;
  background: #fbfdfb;
}

.ft-footer > span {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #778a81;
  font-size: 9px;
  font-weight: 800;
}

.ft-footer > div {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

/* ---------- STATUS VIEW: collision-safe rules ---------- */
/* The page-level status card must remain a normal block card. */
.ft-card.ft-status {
  display: block;
  padding-bottom: 22px;
}

/* The small status badge is the non-card .ft-status element. */
.ft-status:not(.ft-card) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: fit-content;
  min-height: 34px;
  padding: 8px 11px;
  border-radius: 999px;
  background: #edf6ef;
  color: #2e6d49;
  font-size: 10px;
  font-weight: 900;
  white-space: nowrap;
}

.ft-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding: 0 24px 16px;
}

.ft-id {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 32px;
  margin: 0 0 0 7px;
  padding: 0 9px;
  border: 1px solid #dce7e1;
  border-radius: 8px;
  background: #fafcfa;
  color: #63786d;
  font-size: 9px;
  font-weight: 900;
  cursor: pointer;
}

.ft-id:hover {
  border-color: #bdd4c5;
  background: #f4f9f5;
}

.ft-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px;
  margin-bottom: 0;
  background: #e8eee9;
}

.ft-summary > div {
  min-width: 0;
  padding: 13px;
  background: #fbfdfb;
}

.ft-summary small {
  display: block;
  margin-bottom: 5px;
  color: #87958d;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .1em;
  text-transform: uppercase;
}

.ft-summary b {
  display: block;
  color: #29483a;
  font-size: 11px;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.ft-schedule {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
  margin: 12px 24px 0;
  padding: 10px 11px;
  border: 1px solid #e1e9e4;
  border-radius: 11px;
  background: #f8fbf9;
  color: #4e6c5d;
  font-size: 10px;
}

/* ---------- Timeline ---------- */
.ft-timeline {
  position: relative;
  padding: 20px 24px 4px;
}

.ft-tline {
  position: relative;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 10px;
  min-height: 64px;
}

.ft-tline:not(:last-child)::before {
  content: "";
  position: absolute;
  left: 16px;
  top: 30px;
  bottom: 0;
  width: 2px;
  background: #dfe7e2;
}

.ft-ticon {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border: 3px solid #fff;
  border-radius: 50%;
  background: #edf2ee;
  color: #87988f;
  box-shadow: 0 0 0 1px #d8e2dc;
  z-index: 1;
}

.ft-tline.hit .ft-ticon {
  background: #dff0e4;
  color: #2f7650;
}

.ft-tline.current .ft-ticon {
  background: #1f6944;
  color: #fff;
  box-shadow: 0 0 0 4px rgba(31, 105, 68, .10);
}

.ft-tline.cancelled .ft-ticon {
  background: #fff0ed;
  color: #a3483a;
}

.ft-tline b {
  display: block;
  padding-top: 2px;
  color: #304b3e;
  font-size: 11px;
}

.ft-tline span {
  display: block;
  margin-top: 2px;
  color: #85958d;
  font-size: 9px;
}

.ft-tline small {
  display: block;
  margin-top: 4px;
  color: #63776c;
  font-size: 9px;
  line-height: 1.45;
}

/* ---------- Transporter + tracking ---------- */
.ft-transport-stack {
  display: grid;
  gap: 9px;
  margin: 4px 24px 16px;
}

.ft-transporter {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
  padding: 13px;
  margin: 0;
  border: 1px solid #d8e8dc;
  border-radius: 15px;
  background: #f6fbf7;
}

.ft-avatar,
.ft-person-icon {
  width: 43px;
  height: 43px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 13px;
  background: #e5f2e8;
  color: #2d6c48;
}

.ft-transporter > div:nth-child(2) {
  min-width: 0;
  flex: 1;
}

.ft-transporter h3 {
  margin: 4px 0 2px;
  color: #2a493a;
  font-size: 14px;
}

.ft-transporter p {
  margin: 0;
  color: #6f8278;
  font-size: 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ft-contacts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 7px;
}

.ft-contacts a,
.ft-contacts button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 0;
  padding: 0;
  background: transparent;
  color: #2e6b48;
  text-decoration: none;
  font-size: 9px;
  font-weight: 900;
  cursor: pointer;
}

.ft-live {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
  padding: 6px 8px;
  border: 1px solid #d8e8dc;
  border-radius: 999px;
  background: #fff;
  color: #2f6f4b;
  font-size: 9px;
  font-weight: 900;
}

.ft-live.offline {
  color: #855e54;
  border-color: #ecdcd6;
  background: #fff7f4;
}

.ft-live.offline i {
  background: #bd7563;
  box-shadow: 0 0 0 4px rgba(189, 117, 99, .09);
}

.ft-tracking-card,
.ft-fare,
.ft-rating,
.ft-matches,
.ft-report,
.ft-linked {
  border: 1px solid #e0eae4;
  background: #fbfdfb;
}

.ft-tracking-card {
  padding: 15px;
  border-radius: 17px;
}

.ft-tracking-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.ft-tracking-head h3 {
  margin: 5px 0 2px;
  color: #2d4a3c;
  font-size: 15px;
}

.ft-tracking-head p {
  max-width: 640px;
  margin: 0;
  font-size: 10px;
}

.ft-route {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 42px minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  margin: 18px 0 12px;
}

.ft-route-point {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.ft-route-point > span {
  width: 13px;
  height: 13px;
  margin-top: 2px;
  flex: 0 0 auto;
  border: 3px solid #fff;
  border-radius: 50%;
  box-shadow: 0 0 0 1px #b7ccc0;
}

.ft-route-point > span.farm {
  background: #2d7650;
}

.ft-route-point > span.center {
  background: #5d6f68;
}

.ft-route-point b,
.ft-route-point small {
  display: block;
}

.ft-route-point b {
  color: #2d493b;
  font-size: 10px;
}

.ft-route-point small {
  margin-top: 3px;
  color: #829189;
  font-size: 9px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.ft-route-line {
  position: relative;
  height: 2px;
  background: #cddbd2;
}

.ft-truck-pin {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  border: 1px solid #d0e2d6;
  border-radius: 10px;
  background: #e7f3eb;
  color: #2c6d49;
}

.ft-live-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  overflow: hidden;
  border: 1px solid #e4ece6;
  border-radius: 11px;
  background: #e4ece6;
}

.ft-live-stats > div {
  min-width: 0;
  padding: 9px;
  background: #fff;
}

.ft-live-stats small,
.ft-live-stats b {
  display: block;
}

.ft-live-stats small {
  color: #87958e;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .09em;
}

.ft-live-stats b {
  margin-top: 4px;
  color: #304c3e;
  font-size: 10px;
  overflow-wrap: anywhere;
}

.ft-fare {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr);
  gap: 12px;
  padding: 14px 15px;
  border-radius: 15px;
  background: #fff;
}

.ft-fare h3 {
  margin: 5px 0 2px;
  color: #1f4b38;
  font-size: 24px;
  letter-spacing: -.03em;
}

.ft-fare p {
  margin: 0;
  color: #7f8f88;
  font-size: 9px;
}

.ft-fare-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 7px;
  align-content: center;
  font-size: 10px;
}

.ft-fare-grid span {
  color: #83928b;
}

.ft-fare-grid b {
  color: #385447;
  text-align: right;
}

/* ---------- Smart matches ---------- */
.ft-linked {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 4px 24px 16px;
  padding: 12px;
  border-radius: 13px;
  background: #fff;
}

.ft-linked b {
  display: block;
  margin-top: 4px;
  color: #304d3f;
  font-size: 11px;
  overflow-wrap: anywhere;
}

.ft-matches {
  margin: 0 24px;
  padding: 15px;
  border-radius: 16px;
  background: #fbfdfb;
}

.ft-match-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.ft-match-head h3 {
  margin: 5px 0 2px;
  color: #2f4c3d;
  font-size: 15px;
}

.ft-match-head p {
  margin: 0;
  font-size: 10px;
}

.ft-match-list {
  display: grid;
  gap: 6px;
  margin-top: 11px;
}

.ft-match {
  min-width: 0;
  display: grid;
  grid-template-columns: 25px 30px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 8px;
  padding: 9px;
  border: 1px solid #e5ece7;
  border-radius: 11px;
  background: #fff;
}

.ft-match > svg {
  color: #2d6c48;
}

.ft-match > div:nth-child(3) {
  min-width: 0;
}

.ft-match strong,
.ft-match span {
  display: block;
}

.ft-match strong {
  color: #304c3e;
  font-size: 10px;
}

.ft-match span {
  margin-top: 2px;
  color: #778980;
  font-size: 9px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ft-match em {
  color: #425e50;
  font-size: 10px;
  font-style: normal;
  font-weight: 900;
  white-space: nowrap;
}

.ft-no-match {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  margin-top: 9px;
  padding: 11px;
  border-radius: 10px;
  background: #f7faf7;
  color: #677b71;
  font-size: 10px;
  line-height: 1.5;
}

/* ---------- Empty + history ---------- */
.ft-empty {
  min-height: 290px;
  display: grid;
  place-items: center;
  align-content: center;
  padding: 58px 24px;
  text-align: center;
}

.ft-empty.small {
  min-height: 200px;
  padding: 40px 24px;
}

.ft-empty svg {
  color: #3a7755;
}

.ft-empty h2 {
  margin: 8px 0 0;
  color: #315243;
  font-size: 20px;
}

.ft-empty p {
  max-width: 460px;
  margin: 8px 0 17px;
  color: #74857c;
  font-size: 11px;
  line-height: 1.55;
}

.ft-history {
  display: grid;
  gap: 7px;
  padding: 10px 18px 22px;
}

.ft-history button {
  width: 100%;
  display: grid;
  grid-template-columns: 9px minmax(0, 1fr) auto 16px;
  align-items: center;
  gap: 10px;
  padding: 12px;
  border: 1px solid #e2eae5;
  border-radius: 12px;
  background: #fff;
  text-align: left;
  cursor: pointer;
}

.ft-history button:hover {
  border-color: #c7dbcd;
  background: #fbfefc;
}

.ft-history .dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #788b82;
}

.ft-history .dot.status-completed {
  background: #50a06d;
}

.ft-history .dot.status-cancelled {
  background: #bc5c4e;
}

.ft-history b,
.ft-history span {
  display: block;
}

.ft-history b {
  color: #304c3e;
  font-size: 10px;
}

.ft-history span {
  margin-top: 3px;
  color: #7c8d85;
  font-size: 9px;
  overflow-wrap: anywhere;
}

/* ---------- Right rail ---------- */
.ft-side {
  padding: 17px;
}

.ft-side-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.ft-side-head h2 {
  margin: 5px 0 0;
  color: #234636;
  font-size: 20px;
  letter-spacing: -.02em;
}

.ft-side-head em {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 9px;
  background: #eaf4ed;
  color: #2d6e4a;
  font-size: 10px;
  font-style: normal;
  font-weight: 900;
}

.ft-active-list {
  display: grid;
  gap: 7px;
  margin-top: 12px;
}

.ft-active-list button {
  width: 100%;
  padding: 11px;
  border: 1px solid #e1e9e4;
  border-radius: 12px;
  background: #fff;
  text-align: left;
  cursor: pointer;
  transition: border-color .15s ease, box-shadow .15s ease, transform .15s ease;
}

.ft-active-list button:hover {
  transform: translateY(-1px);
  border-color: #c7dccd;
}

.ft-active-list button.sel {
  border-color: #9fc9ab;
  box-shadow: 0 0 0 3px rgba(66, 132, 85, .08);
}

.ft-active-list button > span {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 0 7px;
  border-radius: 999px;
  background: #edf5ef;
  color: #2e6e49;
  font-size: 8px;
  font-weight: 900;
}

.ft-active-list button > b {
  display: block;
  margin-top: 7px;
  color: #304c3e;
  font-size: 11px;
}

.ft-active-list button > small,
.ft-active-list button > i {
  display: block;
  margin-top: 3px;
  color: #798b83;
  font-size: 9px;
  font-style: normal;
  overflow-wrap: anywhere;
}

.ft-side-empty {
  display: grid;
  gap: 5px;
  margin-top: 12px;
  padding: 16px;
  border: 1px solid #e5ece7;
  border-radius: 12px;
  background: #e2f4e5;
  color: #71847a;
}

.ft-side-empty b {
  color: #365243;
  font-size: 10px;
}

.ft-side-empty span {
  font-size: 9px;
  line-height: 1.45;
}

.ft-system {
  padding: 19px;
}

.ft-system > svg {
  width: 43px;
  height: 43px;
  padding: 10px;
  margin-bottom: 8px;
  border-radius: 13px;
  background: #edf6f0;
  color: #2d6f4a;
}

.ft-system h2 {
  margin: 6px 0;
  color: #2d4c3d;
  font-size: 18px;
  line-height: 1.15;
}

.ft-system p {
  margin: 0;
  font-size: 10px;
}

.ft-system > div {
  display: grid;
  gap: 7px;
  margin-top: 13px;
}

.ft-system b {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #527063;
  font-size: 9px;
}

.ft-system b svg {
  color: #4c9966;
}

/* ---------- Rating / report ---------- */
.ft-rating {
  display: grid;
  gap: 10px;
  padding: 15px;
  border-radius: 15px;
  background: #fff;
}

.ft-rating h3 {
  margin: 4px 0 0;
  color: #304d3f;
  font-size: 15px;
}

.ft-stars {
  display: flex;
  gap: 3px;
}

.ft-stars button {
  border: 0;
  padding: 4px;
  background: transparent;
  color: #abbab2;
  cursor: pointer;
}

.ft-stars button.sel {
  color: #d2a43b;
}

.ft-rating textarea {
  width: 100%;
  min-height: 70px;
  border: 1px solid #d8e3dc;
  border-radius: 11px;
  padding: 10px;
  resize: vertical;
  outline: 0;
  font-size: 10px;
}

.ft-rating textarea:focus {
  border-color: #78a489;
  box-shadow: 0 0 0 4px rgba(69, 132, 91, .09);
}

.ft-rating-done {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  color: #2d704b;
}

.ft-rating-done b,
.ft-rating-done span {
  display: block;
}

.ft-rating-done b {
  font-size: 11px;
}

.ft-rating-done span {
  margin-top: 3px;
  color: #75867e;
  font-size: 9px;
  line-height: 1.45;
}

.ft-report {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 13px;
  border-color: #eadfd9;
  border-radius: 13px;
  background: #fffaf8;
  color: #805c51;
}

.ft-report > div {
  min-width: 0;
  flex: 1;
}

.ft-report b,
.ft-report span {
  display: block;
}

.ft-report b {
  color: #574039;
  font-size: 10px;
}

.ft-report span {
  margin-top: 3px;
  color: #7c6b64;
  font-size: 9px;
  line-height: 1.45;
}

.ft-report a {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  flex: 0 0 auto;
  color: #7d4a3d;
  text-decoration: none;
  font-size: 9px;
  font-weight: 900;
}

/* ---------- Modals ---------- */
.ft-modal-bg {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  padding: 18px;
  background: rgba(12, 31, 21, .46);
  backdrop-filter: blur(5px);
}

.ft-modal {
  width: min(500px, 100%);
  max-height: min(90vh, 760px);
  overflow: auto;
  padding: 23px;
  border: 1px solid #dbe6df;
  border-radius: 22px;
  background: #fff;
  box-shadow: 0 30px 100px rgba(9, 25, 16, .24);
}

.ft-modal-icon {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  margin-bottom: 10px;
  border-radius: 14px;
  background: #fff0ed;
  color: #a54739;
}

.ft-modal h2 {
  margin: 6px 0;
  color: #2d4a3c;
  font-size: 22px;
}

.ft-modal p {
  color: #6d8176;
  font-size: 11px;
  line-height: 1.55;
}

.ft-modal .ft-field {
  margin-top: 10px;
}

.ft-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 15px;
}

/* ---------- Responsive ---------- */
@media (max-width: 1120px) {
  .ft-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .ft-grid > aside {
    position: static;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 860px) {
  .ft-shell {
    width: min(100% - 28px, 760px);
    padding-top: 22px;
  }

  .ft-head {
    flex-direction: column;
    align-items: flex-start;
  }

  .ft-head-actions {
    width: 100%;
    justify-content: flex-start;
  }

  .ft-features {
    grid-template-columns: 1fr;
  }

  .ft-grid > aside {
    grid-template-columns: 1fr;
  }

  .ft-two,
  .ft-summary {
    grid-template-columns: 1fr;
  }

  .ft-picker {
    align-items: stretch;
    flex-direction: column;
  }

  .ft-picker .ft-link {
    width: 100%;
  }

  .ft-footer {
    align-items: stretch;
    flex-direction: column;
  }

  .ft-footer > div {
    width: 100%;
  }

  .ft-footer > div > * {
    flex: 1 1 0;
  }

  .ft-actions {
    padding-left: 20px;
    padding-right: 20px;
  }

  .ft-card-head,
  .ft-section {
    padding-left: 20px;
    padding-right: 20px;
  }

  .ft-schedule,
  .ft-linked,
  .ft-transport-stack,
  .ft-matches {
    margin-left: 20px;
    margin-right: 20px;
  }

  .ft-timeline {
    padding-left: 20px;
    padding-right: 20px;
  }
}

@media (max-width: 620px) {
  .ft-shell {
    width: min(100% - 18px, 600px);
    padding-top: 16px;
    padding-bottom: 42px;
  }

  .ft-head h1 {
    font-size: 34px;
  }

  .ft-head p {
    font-size: 12px;
  }

  .ft-tabs {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .ft-tabs button {
    min-width: 0;
    padding: 0 6px;
    font-size: 9px;
  }

  .ft-tabs button svg {
    width: 14px;
    height: 14px;
  }

  .ft-card,
  .ft-loading {
    border-radius: 18px;
  }

  .ft-card-head {
    flex-direction: column;
    gap: 11px;
  }

  .ft-card-head > svg {
    width: 35px;
    height: 35px;
    padding: 9px;
  }

  .ft-card-head h2 {
    font-size: 21px;
  }

  .ft-actions {
    align-items: stretch;
  }

  .ft-actions > * {
    flex: 1 1 calc(50% - 4px);
  }

  .ft-actions .ft-id {
    flex: 1 1 100%;
    width: fit-content;
    justify-self: flex-start;
  }

  .ft-route {
    grid-template-columns: minmax(0, 1fr) 28px minmax(0, 1fr);
  }

  .ft-fare {
    grid-template-columns: 1fr;
  }

  .ft-live-stats {
    grid-template-columns: 1fr;
  }

  .ft-tracking-head {
    flex-direction: column;
  }

  .ft-tracking-head .ft-btn {
    width: 100%;
  }

  .ft-match {
    grid-template-columns: 23px 28px minmax(0, 1fr);
  }

  .ft-match > div:nth-child(4),
  .ft-match > em {
    grid-column: 3;
    text-align: left;
  }

  .ft-transporter {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .ft-live {
    margin-left: auto;
  }

  .ft-loc-actions,
  .ft-loc-actions > * {
    width: 100%;
  }

  .ft-loc-actions > * {
    justify-content: center;
  }

  .ft-modal-actions {
    flex-direction: column;
  }

  .ft-modal-actions > * {
    width: 100%;
  }
}

@media (max-width: 420px) {
  .ft-shell {
    width: calc(100% - 12px);
  }

  .ft-head h1 {
    font-size: 30px;
  }

  .ft-online,
  .ft-head-actions .ft-btn {
    width: 100%;
  }

  .ft-head-actions {
    display: grid;
    grid-template-columns: 1fr;
    width: 100%;
  }

  .ft-tabs button {
    font-size: 8px;
  }

  .ft-section,
  .ft-card-head {
    padding-left: 16px;
    padding-right: 16px;
  }

  .ft-actions,
  .ft-timeline {
    padding-left: 16px;
    padding-right: 16px;
  }

  .ft-schedule,
  .ft-linked,
  .ft-transport-stack,
  .ft-matches {
    margin-left: 16px;
    margin-right: 16px;
  }
}

/* ==========================================================
   KRISHISETU — COLOR + LARGE CARD + ANIMATION ENHANCEMENT
   Keeps the existing layout; only enhances visual hierarchy.
   ========================================================== */

:root {
  --ks-green-950: #103b28;
  --ks-green-900: #145c3b;
  --ks-green-800: #1d7449;
  --ks-green-700: #278557;
  --ks-green-600: #37a368;
  --ks-green-100: #e6f6ec;
  --ks-green-50: #f3fbf6;
  --ks-ink: #16352a;
  --ks-muted: #6a8175;
  --ks-line: #d5e7db;
  --ks-gold: #d8a63c;
  --ks-blue: #377fb0;
  --ks-danger: #b34a3e;
}

/* Page atmosphere */
.farmer-transport-page {
  background:
    radial-gradient(circle at 8% 4%, rgba(55,163,104,.16), transparent 24%),
    radial-gradient(circle at 94% 9%, rgba(55,127,176,.11), transparent 22%),
    radial-gradient(circle at 56% 80%, rgba(216,166,60,.07), transparent 20%),
    linear-gradient(180deg, #f7fbf8 0%, #edf6f0 48%, #e8f1eb 100%);
}

/* Big, readable page heading */
.ft-head h1 {
  color: var(--ks-green-950);
  font-size: clamp(40px, 5vw, 62px);
  line-height: .98;
  text-shadow: 0 2px 0 rgba(255,255,255,.7);
  animation: ft-title-in .55s cubic-bezier(.2,.75,.2,1) both;
}

.ft-head p {
  color: #61796d;
  font-size: 15px;
}

.ft-eyebrow,
.ft-card-head > div > span,
.ft-sec-title > span,
.ft-side-head > div > span,
.ft-system > span,
.ft-match-head > div > small,
.ft-modal > span,
.ft-tracking-head small,
.ft-fare small,
.ft-rating small,
.ft-transporter small,
.ft-linked small {
  color: var(--ks-green-700);
}

@keyframes ft-title-in {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Feature strip — make the boxes feel substantial */
.ft-features {
  gap: 15px;
  margin-bottom: 19px;
}

.ft-features > div {
  min-height: 88px;
  padding: 17px 18px;
  border: 1px solid #d3e5da;
  border-radius: 18px;
  background:
    linear-gradient(145deg, rgba(255,255,255,.98), rgba(246,251,247,.96));
  box-shadow: 0 14px 34px rgba(22,73,46,.07);
  position: relative;
  overflow: hidden;
  animation: ft-rise .55s cubic-bezier(.2,.75,.2,1) both;
}

.ft-features > div:nth-child(2) { animation-delay: .08s; }
.ft-features > div:nth-child(3) { animation-delay: .16s; }

.ft-features > div::after {
  content: "";
  position: absolute;
  inset: auto -30px -45px auto;
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: rgba(55,163,104,.06);
  pointer-events: none;
}

.ft-features svg {
  width: 44px;
  height: 44px;
  padding: 10px;
  border-radius: 14px;
  background: linear-gradient(145deg, #e4f6e9, #d6efdf);
  color: var(--ks-green-800);
  box-shadow: inset 0 0 0 1px rgba(55,163,104,.06);
}

.ft-features b {
  font-size: 14px;
  color: var(--ks-ink);
}

.ft-features span {
  font-size: 12px;
  color: var(--ks-muted);
}

@keyframes ft-rise {
  from { opacity: 0; transform: translateY(15px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Main cards become larger and more visible */
.ft-card,
.ft-loading,
.ft-side-card,
.ft-active-card,
.ft-empty,
.ft-booking-summary,
.ft-bottom-bar {
  box-shadow: 0 20px 55px rgba(20,72,45,.08);
}

.ft-card {
  border-color: #d2e3d8;
}

.ft-card-head {
  padding: 25px 27px 20px;
  background: linear-gradient(180deg, #ffffff 0%, #fbfefc 100%);
}

.ft-card-head h2 {
  font-size: clamp(24px, 2.5vw, 31px);
  color: var(--ks-green-950);
}

.ft-card-head p {
  font-size: 12px;
}

/* Section blocks in request form */
.ft-section {
  padding: 27px 29px;
  background: #fff;
  transition: background .22s ease, box-shadow .22s ease;
}

.ft-section:hover {
  background: linear-gradient(180deg, #ffffff 0%, #fbfefc 100%);
  box-shadow: inset 4px 0 0 var(--ks-green-600);
}

.ft-sec-title > b {
  width: 40px;
  height: 40px;
  border-radius: 13px;
  background: linear-gradient(145deg, #e4f7ea, #d5efde);
  color: var(--ks-green-900);
  font-size: 12px;
  box-shadow: 0 6px 16px rgba(39,133,87,.10);
}

.ft-sec-title strong {
  font-size: 16px;
  color: var(--ks-ink);
}

.ft-sec-title span {
  font-size: 11px;
}

/* Larger fields for easy farmer interaction */
.ft-field > span {
  font-size: 12px;
  color: #4d685c;
}

.ft-field input,
.ft-field select,
.ft-field textarea,
.ft-select select,
.ft-time input {
  min-height: 52px;
  border-color: #ccdcd2;
  border-radius: 14px;
  background: #fcfefd;
  font-size: 14px;
  color: #1f4032;
  transition: border-color .18s ease, box-shadow .18s ease, transform .18s ease, background .18s ease;
}

.ft-field textarea {
  min-height: 102px;
}

.ft-field input:hover,
.ft-field select:hover,
.ft-field textarea:hover {
  border-color: #9ec5ad;
  background: #ffffff;
}

.ft-field input:focus,
.ft-field select:focus,
.ft-field textarea:focus,
.ft-time input:focus {
  border-color: var(--ks-green-600);
  box-shadow: 0 0 0 4px rgba(55,163,104,.12), 0 8px 18px rgba(25,89,54,.05);
  transform: translateY(-1px);
  background: #fff;
}

/* Buttons */
.ft-btn,
.ft-link,
.ft-link-btn,
.ft-location-btn,
.ft-primary-btn,
.ft-secondary-btn,
.ft-ghost-btn,
.ft-small-btn {
  transition: transform .18s ease, box-shadow .18s ease, background .18s ease, border-color .18s ease;
}

.ft-btn:hover:not(:disabled),
.ft-primary-btn:hover,
.ft-secondary-btn:hover,
.ft-ghost-btn:hover,
.ft-link:hover,
.ft-location-btn:hover,
.ft-small-btn:hover {
  transform: translateY(-2px);
}

.ft-primary,
.ft-primary-btn,
.ft-location-btn {
  background: linear-gradient(135deg, #1c7448 0%, #2c9861 100%);
  border-color: #1b6842;
  box-shadow: 0 12px 25px rgba(28,116,72,.20);
}

.ft-primary:hover,
.ft-primary-btn:hover,
.ft-location-btn:hover {
  background: linear-gradient(135deg, #165f3a 0%, #238451 100%);
  box-shadow: 0 15px 30px rgba(28,116,72,.25);
}

.ft-light,
.ft-secondary-btn {
  background: #fff;
  border-color: #cfdfd6;
}

.ft-light:hover,
.ft-secondary-btn:hover {
  background: #f1f8f3;
  border-color: #9fc5ad;
}

.ft-danger {
  background: #fff5f2;
  color: var(--ks-danger);
  border-color: #eac3bc;
}

/* GPS and schedule callouts */
.ft-gps-box,
.ft-note,
.ft-destination,
.ft-schedule,
.ft-linked,
.ft-tracking-card,
.ft-fare,
.ft-rating,
.ft-report,
.ft-matches {
  border-color: #d2e5d9;
  box-shadow: 0 8px 22px rgba(27,81,51,.04);
}

.ft-note,
.ft-gps-box,
.ft-destination {
  background: linear-gradient(180deg, #f7fcf8 0%, #eff8f2 100%);
}

.ft-gps.ready {
  color: #1c7047;
  border-color: #9fcfaf;
  background: linear-gradient(135deg, #eefaf2, #e0f3e7);
}

/* Active trip / status area — big, calm, readable */
.ft-card.ft-status {
  border-radius: 26px;
  overflow: hidden;
  animation: ft-card-in .48s cubic-bezier(.2,.75,.2,1) both;
}

.ft-card.ft-status > .ft-card-head {
  padding: 28px 30px 22px;
  background:
    radial-gradient(circle at 90% 0%, rgba(55,163,104,.11), transparent 28%),
    linear-gradient(180deg, #ffffff 0%, #f8fcf9 100%);
}

.ft-card.ft-status > .ft-card-head h2 {
  font-size: clamp(27px, 3vw, 37px);
}

.ft-status:not(.ft-card) {
  min-height: 40px;
  border: 1px solid #b9dac5;
  background: linear-gradient(135deg, #eaf8ee, #dff2e5);
  color: #21633f;
  box-shadow: 0 8px 18px rgba(39,133,87,.10);
  animation: ft-pulse-soft 2.8s ease-in-out infinite;
}

@keyframes ft-pulse-soft {
  0%,100% { box-shadow: 0 8px 18px rgba(39,133,87,.08); }
  50% { box-shadow: 0 10px 24px rgba(39,133,87,.18); }
}

@keyframes ft-card-in {
  from { opacity: 0; transform: translateY(18px) scale(.992); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

/* Progress timeline */
.ft-progress {
  gap: 10px;
  padding: 25px 10px 10px;
}

.ft-progress-step {
  animation: ft-step-in .45s ease both;
}

.ft-progress-step:nth-child(2) { animation-delay: .04s; }
.ft-progress-step:nth-child(3) { animation-delay: .08s; }
.ft-progress-step:nth-child(4) { animation-delay: .12s; }
.ft-progress-step:nth-child(5) { animation-delay: .16s; }
.ft-progress-step:nth-child(6) { animation-delay: .20s; }
.ft-progress-step:nth-child(7) { animation-delay: .24s; }

.ft-progress-dot {
  width: 34px;
  height: 34px;
  border: 1px solid #cdded5;
  background: #f7fbf8;
}

.ft-progress-step.done .ft-progress-dot {
  background: linear-gradient(145deg, #2b955d, #1e7047);
  border-color: #1f7047;
  box-shadow: 0 7px 16px rgba(39,133,87,.18);
}

.ft-progress-step.current .ft-progress-dot {
  box-shadow: 0 0 0 5px rgba(55,163,104,.10), 0 8px 20px rgba(39,133,87,.18);
}

@keyframes ft-step-in {
  from { opacity: 0; transform: translateY(7px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Info cards — bigger blocks */
.ft-summary {
  background: #dfece4;
}

.ft-summary > div,
.ft-info-card {
  padding: 17px;
  background: linear-gradient(180deg, #ffffff 0%, #f8fcf9 100%);
}

.ft-summary b,
.ft-info-card strong {
  font-size: 14px;
  color: var(--ks-ink);
}

.ft-summary small,
.ft-info-card span {
  color: #738a7e;
}

.ft-info-card {
  border-radius: 16px;
  min-height: 86px;
  transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
}

.ft-info-card:hover {
  transform: translateY(-3px);
  border-color: #b8d4c1;
  box-shadow: 0 12px 25px rgba(25,89,54,.07);
}

/* Transporter card */
.ft-transporter {
  padding: 17px;
  border-radius: 17px;
  background: linear-gradient(135deg, #f0f9f3, #e8f5ed);
  border-color: #cfe4d6;
}

.ft-avatar,
.ft-person-icon {
  width: 50px;
  height: 50px;
  border-radius: 15px;
  background: linear-gradient(145deg, #dff3e6, #cae9d5);
  color: var(--ks-green-800);
}

.ft-transporter h3 {
  font-size: 17px;
  color: var(--ks-green-950);
}

/* Active request list on the right */
.ft-side-card {
  border-radius: 22px;
  padding: 21px;
  background: linear-gradient(180deg, #ffffff 0%, #f8fcf9 100%);
}

.ft-side-head h2 {
  font-size: 24px;
  color: var(--ks-green-950);
}

.ft-side-head em {
  width: 38px;
  height: 38px;
  background: linear-gradient(145deg, #e7f7ed, #d9f0e2);
  color: var(--ks-green-800);
  box-shadow: 0 8px 16px rgba(39,133,87,.10);
}

.ft-active-list button {
  padding: 15px;
  border-radius: 15px;
  border-color: #d6e5dc;
  background: #fff;
  transition: transform .18s ease, border-color .18s ease, box-shadow .18s ease;
}

.ft-active-list button:hover,
.ft-active-list button.sel {
  transform: translateY(-2px);
  border-color: #a8cfb6;
  box-shadow: 0 12px 25px rgba(29,104,64,.08);
}

.ft-active-list button > span {
  padding: 6px 9px;
  background: #e8f7ed;
  color: #257149;
  font-size: 9px;
}

.ft-active-list button > b {
  font-size: 14px;
  color: #203f31;
}

/* Fare area */
.ft-fare {
  background: linear-gradient(135deg, #f7fbf8 0%, #eaf7ee 100%);
  border-color: #cae1d2;
}

.ft-fare h3 {
  font-size: clamp(25px, 3vw, 34px);
  color: var(--ks-green-900);
}

/* Sticky request footer — larger action target */
.ft-footer {
  padding: 20px 28px;
  background: linear-gradient(180deg, #f9fcfa 0%, #f0f8f3 100%);
}

.ft-footer > div {
  gap: 10px;
}

.ft-footer .ft-btn {
  min-height: 48px;
  padding: 0 16px;
}

/* Modal */
.ft-modal-bg {
  background: rgba(9,32,20,.56);
  backdrop-filter: blur(7px);
}

.ft-modal {
  border-radius: 26px;
  border-color: #cfe1d5;
  box-shadow: 0 35px 110px rgba(6,27,16,.28);
  animation: ft-modal-in .25s cubic-bezier(.2,.75,.2,1) both;
}

@keyframes ft-modal-in {
  from { opacity: 0; transform: translateY(14px) scale(.97); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

/* Smooth reveal for commonly visible blocks */
.ft-grid,
.ft-history,
.ft-alerts,
.ft-head-actions {
  animation: ft-fade-up .48s ease both;
}

@keyframes ft-fade-up {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Respect reduced-motion settings */
@media (prefers-reduced-motion: reduce) {
  .farmer-transport-page *,
  .farmer-transport-page *::before,
  .farmer-transport-page *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Mobile: keep boxes large, stack cleanly, avoid cramped text */
@media (max-width: 800px) {
  .ft-shell {
    width: min(calc(100% - 20px), 720px);
    padding: 20px 0 48px;
  }

  .ft-head h1 {
    font-size: clamp(34px, 10vw, 46px);
  }

  .ft-features > div {
    min-height: 82px;
  }

  .ft-card-head,
  .ft-card.ft-status > .ft-card-head {
    padding: 21px;
  }

  .ft-section {
    padding: 22px 20px;
  }

  .ft-info-card,
  .ft-summary > div {
    min-height: 76px;
  }

  .ft-footer {
    padding: 17px 20px;
  }
}

@media (max-width: 560px) {
  .ft-shell {
    width: calc(100% - 14px);
  }

  .ft-head h1 {
    font-size: 34px;
  }

  .ft-head p {
    font-size: 13px;
  }

  .ft-features > div {
    min-height: 78px;
    padding: 15px;
  }

  .ft-features svg {
    width: 40px;
    height: 40px;
  }

  .ft-card-head h2,
  .ft-card.ft-status > .ft-card-head h2 {
    font-size: 25px;
  }

  .ft-section {
    padding: 20px 16px;
  }

  .ft-sec-title > b {
    width: 37px;
    height: 37px;
  }

  .ft-field input,
  .ft-field select,
  .ft-field textarea,
  .ft-select select,
  .ft-time input {
    min-height: 50px;
    font-size: 14px;
  }

  .ft-btn,
  .ft-primary-btn,
  .ft-secondary-btn,
  .ft-ghost-btn,
  .ft-location-btn {
    min-height: 46px;
  }

  .ft-footer > div > * {
    min-height: 50px;
  }
}


/* =========================================================
   FARMER HOME - LARGE NOTIFICATION PANEL
   ========================================================= */

/* Full-screen notification backdrop */
.notification-backdrop,
.notifications-backdrop,
.notification-overlay,
.notifications-overlay {
  position: fixed !important;
  inset: 0 !important;
  z-index: 99990 !important;
  background: rgba(18, 42, 31, 0.28) !important;
  backdrop-filter: blur(10px) saturate(115%) !important;
  -webkit-backdrop-filter: blur(10px) saturate(115%) !important;
}

/* Almost full-screen notification drawer */
.notification-panel,
.notifications-panel,
.notification-drawer,
.notifications-drawer,
.notifications-modal,
.notification-modal {
  position: fixed !important;
  z-index: 99991 !important;

  top: 2.5vh !important;
  right: 2.5vw !important;
  bottom: 2.5vh !important;
  left: 2.5vw !important;

  width: auto !important;
  max-width: none !important;
  height: auto !important;
  max-height: none !important;

  display: flex !important;
  flex-direction: column !important;

  overflow: hidden !important;

  background:
    linear-gradient(
      145deg,
      rgba(255,255,255,0.99) 0%,
      rgba(250,253,251,0.99) 100%
    ) !important;

  border: 1px solid rgba(38, 101, 64, 0.14) !important;
