  .landing-image-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

.landing-image-card {
  position: relative;
  border-radius: 20px;
  overflow: hidden;
  box-shadow: 0 15px 35px rgba(22, 101, 52, 0.1);
  aspect-ratio: 4/5;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.landing-image-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 20px 45px rgba(234, 88, 12, 0.15);
}

.landing-image-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}

.landing-image-card:hover img {
  transform: scale(1.05);
}

.landing-image-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 30px 20px 20px;
  background: linear-gradient(to top, rgba(22, 101, 52, 0.9) 0%, rgba(22, 101, 52, 0) 100%);
  color: #fff;
}

