/* =========================================================
   GLOBAL THEME VISIBILITY FIX (All Dashboards)
========================================================= */

/* 
  Force all major text elements inside ANY card to adapt correctly to the theme, 
  overriding any pesky inline styles that cause invisible text. 
*/

/* 1. LIGHT MODE: Ensure all text in cards/panels is dark and readable */
:is([data-theme="light"], body:not(.dark):not([data-theme="dark"]):not([data-theme="forest"]):not([data-theme="midnight"])) 
:is(.card, .panel, .box, .home-dashboard-card, .dashboard-card, .booking-status-message, .home-center-details) 
:is(h1, h2, h3, p, span, strong, div, small) {
    color: #1e293b; 
}

/* Specific overrides for light mode backgrounds that need to be transparent to show glassmorphism */
:is([data-theme="light"], body:not(.dark):not([data-theme="dark"]):not([data-theme="forest"]):not([data-theme="midnight"])) 
:is(.home-dashboard-card, .booking-status-message, .home-center-details, .dashboard-card) > div {
    background-color: transparent !important;
}

/* 2. ALL DARK MODES (Dark, Midnight, Forest): Force text to be light and readable */
:is([data-theme="dark"], [data-theme="midnight"], [data-theme="forest"], body.dark) 
:is(.card, .panel, .box, .home-dashboard-card, .dashboard-card, .transporter-card, .admin-card, .booking-status-message, .home-center-details, .farmer-notification-panel) 
:is(h1, h2, h3, h4, p, span, strong, small) {
    color: #f8fafc !important;
    text-shadow: 0 1px 2px rgba(0,0,0,0.5); /* subtle shadow ensures readability over images */
}

/* Prevent any div inside a card from keeping a hardcoded white/light background in dark mode */
:is([data-theme="dark"], [data-theme="midnight"], [data-theme="forest"], body.dark) 
:is(.card, .panel, .box, .home-dashboard-card, .dashboard-card, .booking-status-message, .home-center-details) > div {
    background: transparent !important;
    border-color: rgba(255,255,255,0.1) !important;
}

/* Ensure all SVG icons turn light in dark modes so they don't disappear */
:is([data-theme="dark"], [data-theme="midnight"], [data-theme="forest"], body.dark) 
:is(.card, .panel, .box, .home-dashboard-card, .dashboard-card, .booking-status-message, .home-center-details) svg {
    color: #f8fafc !important;
    stroke: #f8fafc !important;
}

/* Except buttons! Buttons should keep their distinct colors */
:is([data-theme="dark"], [data-theme="midnight"], [data-theme="forest"], body.dark) button span,
:is([data-theme="dark"], [data-theme="midnight"], [data-theme="forest"], body.dark) button svg {
    color: inherit !important;
    text-shadow: none !important;
}


/* =========================================================
   DRYING YARD MODAL
========================================================= */

.drying-yard-backdrop {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.6);
  backdrop-filter: blur(8px);
  z-index: 99999999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.drying-yard-modal {
  background: white;
  width: 100%;
  max-width: 800px;
  border-radius: 20px;
  box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  animation: slideUp 0.3s ease-out forwards;
}

[data-theme="dark"] .drying-yard-modal,
[data-theme="midnight"] .drying-yard-modal,
[data-theme="forest"] .drying-yard-modal,
body.dark .drying-yard-modal {
  background: #1e293b;
  color: #f8fafc;
  border: 1px solid rgba(255,255,255,0.1);
}

.drying-yard-header {
  padding: 24px 30px;
  border-bottom: 1px solid #e2e8f0;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  background: #f8fafc;
}

[data-theme="dark"] .drying-yard-header,
[data-theme="midnight"] .drying-yard-header,
[data-theme="forest"] .drying-yard-header,
body.dark .drying-yard-header {
  background: rgba(0,0,0,0.2);
  border-bottom-color: rgba(255,255,255,0.1);
}

.drying-yard-header h2 {
  margin: 0 0 8px 0;
  color: #0f172a;
  font-size: 24px;
}

[data-theme="dark"] .drying-yard-header h2,
[data-theme="midnight"] .drying-yard-header h2,
[data-theme="forest"] .drying-yard-header h2,
body.dark .drying-yard-header h2 {
  color: #f8fafc;
}

.drying-yard-header p {
  margin: 0;
  color: #64748b;
  font-size: 14px;
}

[data-theme="dark"] .drying-yard-header p,
body.dark .drying-yard-header p {
  color: #94a3b8;
}

.drying-yard-header strong {
  color: #ef4444;
}

.close-btn {
  background: transparent;
  border: none;
  cursor: pointer;
  color: #64748b;
  padding: 4px;
  border-radius: 8px;
  transition: 0.2s;
}

.close-btn:hover {
  background: #e2e8f0;
  color: #0f172a;
}

[data-theme="dark"] .close-btn:hover,
body.dark .close-btn:hover {
  background: rgba(255,255,255,0.1);
  color: #f8fafc;
}

.drying-yard-body {
  display: grid;
  grid-template-columns: 300px 1fr;
  gap: 30px;
  padding: 30px;
}

@media (max-width: 768px) {
  .drying-yard-body {
    grid-template-columns: 1fr;
  }
}

.drying-yard-info {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.info-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  background: #f1f5f9;
  border-radius: 12px;
  border: 1px solid #e2e8f0;
}

[data-theme="dark"] .info-card,
[data-theme="midnight"] .info-card,
[data-theme="forest"] .info-card,
body.dark .info-card {
  background: rgba(0,0,0,0.2);
  border-color: rgba(255,255,255,0.05);
}

.info-card span {
  display: block;
  font-size: 12px;
  color: #64748b;
  text-transform: uppercase;
  font-weight: 700;
  letter-spacing: 0.5px;
}

[data-theme="dark"] .info-card span,
body.dark .info-card span {
  color: #94a3b8;
}

.info-card strong {
  display: block;
  font-size: 18px;
  color: #0f172a;
  margin-top: 4px;
}

[data-theme="dark"] .info-card strong,
body.dark .info-card strong {
  color: #f1f5f9;
}

.advisory-box {
  margin-top: auto;
  padding: 16px;
  background: #ecfdf5;
  border: 1px dashed #34d399;
  border-radius: 12px;
  color: #065f46;
  font-size: 13px;
  line-height: 1.5;
}

[data-theme="dark"] .advisory-box,
body.dark .advisory-box {
  background: rgba(16, 185, 129, 0.1);
  color: #34d399;
  border-color: rgba(52, 211, 153, 0.3);
}

.drying-yard-selection h3 {
  margin: 0 0 16px 0;
  font-size: 18px;
  color: #0f172a;
}

[data-theme="dark"] .drying-yard-selection h3,
body.dark .drying-yard-selection h3 {
  color: #f8fafc;
}

.yard-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 24px;
}

.yard-slot {
  background: #ffffff;
  border: 2px solid #e2e8f0;
  border-radius: 12px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  cursor: pointer;
  transition: all 0.2s ease;
}

[data-theme="dark"] .yard-slot,
body.dark .yard-slot {
  background: rgba(255,255,255,0.05);
  border-color: rgba(255,255,255,0.1);
}

.yard-slot:hover:not(.occupied) {
  border-color: #3b82f6;
  background: #f0f9ff;
  transform: translateY(-2px);
}

[data-theme="dark"] .yard-slot:hover:not(.occupied),
body.dark .yard-slot:hover:not(.occupied) {
  background: rgba(59, 130, 246, 0.1);
}

.yard-slot.selected {
  border-color: #3b82f6;
  background: #eff6ff;
  box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.1);
}

[data-theme="dark"] .yard-slot.selected,
body.dark .yard-slot.selected {
  background: rgba(59, 130, 246, 0.2);
}

.yard-slot.occupied {
  opacity: 0.6;
  cursor: not-allowed;
  background: #f8fafc;
}

[data-theme="dark"] .yard-slot.occupied,
body.dark .yard-slot.occupied {
  background: rgba(0,0,0,0.3);
}

.yard-slot svg {
  color: #64748b;
  margin-bottom: 12px;
}

.yard-slot.selected svg {
  color: #3b82f6;
}

.yard-slot strong {
  font-size: 16px;
  color: #0f172a;
  margin-bottom: 6px;
}

[data-theme="dark"] .yard-slot strong,
body.dark .yard-slot strong {
  color: #f1f5f9;
}

.yard-slot .status {
  font-size: 12px;
  padding: 4px 10px;
  border-radius: 100px;
  background: #f1f5f9;
  color: #64748b;
  font-weight: 600;
  margin-bottom: 8px;
}

[data-theme="dark"] .yard-slot .status,
body.dark .yard-slot .status {
  background: rgba(255,255,255,0.1);
  color: #cbd5e1;
}

.yard-slot .status.available {
  background: #dcfce7;
  color: #166534;
}

[data-theme="dark"] .yard-slot .status.available,
body.dark .yard-slot .status.available {
  background: rgba(34, 197, 94, 0.2);
  color: #4ade80;
}

.yard-slot small {
  color: #94a3b8;
  font-size: 12px;
}

.confirm-booking-btn {
  width: 100%;
  padding: 16px;
  background: #3b82f6;
  color: white;
  border: none;
  border-radius: 12px;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  transition: 0.2s;
  box-shadow: 0 4px 12px rgba(59, 130, 246, 0.3);
}

.confirm-booking-btn:hover:not(:disabled) {
  background: #2563eb;
  transform: translateY(-1px);
}

.confirm-booking-btn:disabled {
  background: #94a3b8;
  cursor: not-allowed;
  box-shadow: none;
  opacity: 0.7;
}

.drying-yard-success {
  padding: 60px 20px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.drying-yard-success h3 {
  font-size: 24px;
  color: #0f172a;
  margin: 24px 0 8px 0;
}

[data-theme="dark"] .drying-yard-success h3,
body.dark .drying-yard-success h3 {
  color: #f1f5f9;
}

.drying-yard-success p {
  color: #64748b;
  font-size: 16px;
  margin: 0 0 24px 0;
}

[data-theme="dark"] .drying-yard-success p,
body.dark .drying-yard-success p {
  color: #94a3b8;
}

.digital-token {
  background: #f1f5f9;
  padding: 12px 24px;
  border-radius: 12px;
  font-size: 20px;
  font-weight: 800;
  color: #3b82f6;
  letter-spacing: 1px;
  border: 2px dashed #cbd5e1;
}

[data-theme="dark"] .digital-token,
body.dark .digital-token {
  background: rgba(0,0,0,0.3);
  border-color: rgba(255,255,255,0.1);
  color: #60a5fa;
}

@keyframes slideUp {
  from { opacity: 0; transform: translateY(20px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}


/* =========================================================================
   SIH MOBILE RESPONSIVENESS FIXES
========================================================================= */

/* Farmer Quality Metrics */
.sih-quality-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 12px;
}
@media (max-width: 650px) {
  .sih-quality-grid {
    grid-template-columns: 1fr;
    gap: 8px;
  }
}

/* Admin Quality Inputs */
.sih-admin-quality-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
@media (max-width: 650px) {
  .sih-admin-quality-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }
}

/* Transporter Job Main Grid */
.sih-transporter-job-main {
  display: grid;
  grid-template-columns: 1.2fr 0.75fr 0.8fr 0.75fr 1.2fr; /* Added 5th column for Jute Bags */
}
@media (max-width: 1024px) {
  .sih-transporter-job-main {
    grid-template-columns: 1fr 1fr;
    gap: 16px !important;
  }
}
@media (max-width: 650px) {
  .sih-transporter-job-main {
    grid-template-columns: 1fr;
    gap: 16px !important;
  }
}

@keyframes noticePulse {
  0% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(1.2); }
  100% { opacity: 1; transform: scale(1); }
}
.notice-pulse-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  background: #fff;
  border-radius: 50%;
  animation: noticePulse 1.5s infinite ease-in-out;
}


/* ========================================================
