}

.clock-hour-hand {
    width: 6px !important;
    background: #022c22 !important;
    box-shadow: 0 2px 5px rgba(0,0,0,0.4) !important;
}
.clock-minute-hand {
    width: 4px !important;
    background: #064e3b !important;
    box-shadow: 0 2px 5px rgba(0,0,0,0.4) !important;
}
.clock-second-hand {
    width: 3px !important;
    background: #dc2626 !important; /* Red for pop */
    box-shadow: 0 2px 5px rgba(0,0,0,0.4) !important;
}

.orbital-clock-dot {
    background: #dc2626 !important;
